    ('0047ae41-af8e-44e1-b196-4035f5860554'::uuid, 'antiquity', '8', '6', 'card-stats-2026-11-05-rollback:0047ae41-af8e-44e1-b196-4035f5860554:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on Gonnus', 'e8b03de0c81ad1924c8761c581631922', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -4000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80590", "url": "remediation_change_log", "quote": "phase4:p4-2001:chunk-0001: description \"Gonnus (Γόννοι) was an ancient Greek polis of the Perrhaebi in Thessaly, situated on the northern bank of the Peneius River at the narrow entrance to the Vale of Tempe[1]. Its strategic position at one of only two northern passes into Thessaly made it a key defensive stronghold, controlling access to the region from Macedonia[1]. According to later Greek critics, the settlement was named after Gonneus, a figure mentioned in Homer''s Iliad[1]. The pass west of Tempe leading through Mount Olympus into Thessaly was used by Xerxes I''s army during the Persian invasion of 480 BC[1].\" -> ''Gonnus or Gonnos or Gonni was a town and polis of the Perrhaebi in ancient Thessaly, which derived its name, according to the later Greek critics, from Gonneus [1]. Its position made it one of the most important places in the north of Thessaly [1]. It stood on the northern side of the Peneius, near the entrance of the only two passes by which an enemy can penetrate into Thessaly from the north [1]. The celebrated vale of Tempe begins to narrow at Gonnus; and the pass across Mount Olympus a little to the west of Tempe leads into Thessaly at Gonnus [1]. It was by the latter route that the army of Xerxes I entered Thessaly [1]. After the Battle of Cynoscephalae (197 BCE), Philip V of Macedon fled in haste to Tempe, but halted a day at Gonnus, to receive such of his troops as might have survived the battle [1]. Gonnus does not occur in history after the wars of the Romans in Greece, but it is mentioned by Strabo and Ptolemy [1]. The editors of the Barrington Atlas of the Greek and Roman World locate Gonnus at the modern town of Gonnoi [1].''"}, {"source": "remediation_change_log:113391", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:113392", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:141897", "url": "remediation_change_log", "quote": "served-image-2026-09-30-001: thumbnail_url ''/data/images/wiki/0047ae41/hero.webp'' -> None"}, {"source": "remediation_change_log:245543", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:245544", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_start None -> ''-1500''"}, {"source": "remediation_change_log:346216", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''1500 - 500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:346217", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''-1500'' -> ''-4000''"}]'::jsonb),
