    ('008ecaa5-ce9b-484d-9eb8-0f27659bc91d'::uuid, 'mystery', '2', '7', 'card-stats-2026-11-05-rollback:008ecaa5-ce9b-484d-9eb8-0f27659bc91d:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Fort Abbas', '1675f90bf402878f4cbd71c29beba6d9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 2 from (''City/town/settlement'', ''Undated'') is shared by 159 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28410", "url": "remediation_change_log", "quote": "phase3:batch-0128:chunk-0001: period_start ''-5000'' -> ''-4000''"}, {"source": "remediation_change_log:28411", "url": "remediation_change_log", "quote": "phase3:batch-0128:chunk-0001: site_type ''Fortress/citadel'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:30330", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''< 4500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:35628", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_name ''4500 - 3000 BC'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:35629", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-4000'' -> ''-5000''"}, {"source": "remediation_change_log:81514", "url": "remediation_change_log", "quote": "phase4:p4-2035:chunk-0001: description ''Fort Abbas is a town and archaeological site in Bahawalnagar District, Punjab, Pakistan, located in the Cholistan Desert south of Haroonabad near the India-Pakistan border[1]. The area was a major center of the ancient Hakra civilization, with ceramic surveys dating to 5000 BC[2]. The town was named by Nawab Sir Sadiq after his eldest son Muhammad Abbas[1].'' -> ''The region of Fort Abbas is associated with the ancient Ghaggar Hakra river system, which is believed by many scholars to represent a former river course linked to early urban settlements in South Asia [1]. Archaeological investigations in the Cholistan Desert have recorded hundreds of ancient settlement sites along the dry riverbed [1]. Surveys conducted by early researchers and later archaeologists documented continuous human occupation dating back to the fourth millennium BCE [1]. The earliest cultural material discovered in the region is known as Hakra Ware [1]. Before the modern name Fort Abbas was adopted, the settlement was known as Pholra [1]. It functioned as a fortified outpost along caravan trade routes connecting Multan with regions of present day Rajasthan and northern India [1]. The settlement played an important role in protecting trade routes across the Cholistan Desert [1].''"}, {"source": "remediation_change_log:92373", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:92374", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_start ''-5000'' -> None"}, {"source": "remediation_change_log:304058", "url": "remediation_change_log", "quote": "2026-10-04e_period-label-undated: period_name None -> ''Undated''"}]'::jsonb),
