    ('01704ebd-c0b1-4c2b-bdd0-7ffb3b6b4370'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:01704ebd-c0b1-4c2b-bdd0-7ffb3b6b4370:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Dobberworth', 'abf428ccea416ade5add2276138da4d7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81554", "url": "remediation_change_log", "quote": "phase4:p4-2036:chunk-0001: description ''The Dobberworth (also Dubberworth) is one of the largest prehistoric tumuli in northern Germany, located near Sagard on the island of Rugen. Standing approximately 12-15 m tall with a circumference of 150 m, it was constructed from an estimated 22,000 cubic metres of earth, making it the largest barrow on Rugen. Archaeologists have not yet precisely dated the mound but believe it was used during the Bronze Age. The tumulus is surrounded by local legends, including tales of a giantess who accidentally built the mound and dwarves said to inhabit it. Its monumental scale and prominent hilltop position reflect the significant resources and social organization required for such funerary constructions in prehistoric northern Europe.'' -> ''The Dobberworth or Dubberworth is one of the largest prehistoric tumuli in northern Germany, located on the isle of Rügen near Sagard [1]. The Dubberworth is about 15 metres tall, and was made from an estimated 22,000 cubic metres of earth, making it the largest tumulus in Rügen [1]. Archaeologists have not been able to date the tumulus precisely, but assume it was used during the Bronze Age [1]. According to local legends, the Dubberworth was made by a giant who intended to fill a narrow ford linking two nearby Bodden and lost the clay on their way [1].''"}, {"source": "remediation_change_log:92389", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:92390", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:141945", "url": "remediation_change_log", "quote": "served-image-2026-09-30-001: thumbnail_url ''/data/images/wiki/01704ebd/hero.webp'' -> ''/data/images/wiki/01704ebd/Dobberworth 2016 03.jpg1.webp''"}, {"source": "remediation_change_log:245557", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:245558", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_start None -> ''-4000''"}, {"source": "remediation_change_log:304604", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001: thumbnail_url ''/data/images/wiki/01704ebd/Dobberworth 2016 03.jpg1.webp'' -> ''/data/images/wiki/01704ebd/Dobberworth_2016_02.webp''"}, {"source": "remediation_change_log:305814", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001-rollback-rest-001: thumbnail_url ''/data/images/wiki/01704ebd/Dobberworth_2016_02.webp'' -> ''/data/images/wiki/01704ebd/Dobberworth 2016 03.jpg1.webp''"}, {"source": "remediation_change_log:306690", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-001: thumbnail_url ''/data/images/wiki/01704ebd/Dobberworth 2016 03.jpg1.webp'' -> ''/data/images/wiki/01704ebd/Dobberworth_2016_02.webp''"}, {"source": "remediation_change_log:346222", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC