    ('020bd9f9-8d19-4e19-b869-189f4273707f'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:020bd9f9-8d19-4e19-b869-189f4273707f:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Devil''s Humps, Stoughton', '125616a66899a6e616732e985ed3c96a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81562", "url": "remediation_change_log", "quote": "phase4:p4-2036:chunk-0001: description \"The Devil''s Humps are four Bronze Age barrows on Bow Hill in the South Downs near Stoughton, West Sussex, England[1]. Situated on a downland ridgeway crossed by an ancient trackway above Kingley Vale, they rank among the most impressive round barrows surviving on the South Downs and lie within the Kingley Vale National Nature Reserve[1]. The site comprises two bell barrows, two bowl barrows, and two pond barrows with an associated cross dyke, all protected as Scheduled Ancient Monuments[1].\" -> \"The Devil''s Humps are counted among the most impressive round barrows surviving on the South Downs [1]. The four barrows forming the Devil''s Humps are all aligned and stand 3 to 4 metres high in spite of damage caused by early explorations [1]. No records survive from these early excavations, so the precise date for the construction of the barrows is unknown [1]. However, they are believed to date from the Late Neolithic or the Early Bronze Age [1].\""}, {"source": "remediation_change_log:92415", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:92416", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:141976", "url": "remediation_change_log", "quote": "served-image-2026-09-30-001: thumbnail_url ''/data/images/wiki/020bd9f9/hero.webp'' -> \"/data/images/wiki/020bd9f9/Devil''s Humps Barrow C.webp\""}, {"source": "remediation_change_log:245569", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:245570", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_start None -> ''-4000''"}, {"source": "remediation_change_log:346232", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:346233", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
