    ('0349db41-4fca-4804-b614-e075164512b3'::uuid, 'rarity_tier', '2', '3', 'card-stats-2026-11-05-rollback:0349db41-4fca-4804-b614-e075164512b3:rarity_tier', 'rollback of card-stats-2026-11-05: rarity_tier ''3'' restored on Adulis', 'fc3fb0fbf25df3bd6730dca45814f884', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_tier = 2 from rarity_score 25"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27938", "url": "remediation_change_log", "quote": "phase3:batch-0033:chunk-0001: period_start ''-2000'' -> ''-1450''"}, {"source": "remediation_change_log:30332", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''3000 - 1500 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:80598", "url": "remediation_change_log", "quote": "phase4:p4-2001:chunk-0001: description \"An ancient port city on the southwestern Red Sea coast in Eritrea''s Gulf of Zula, serving as the principal seaport of the Aksumite Kingdom. Trade connections reached from the Pharaonic era through the 7th century AD, facilitating exchange of ivory, incense, gold, and obsidian with the Mediterranean, Arabia, Persia, and India. Excavations since 2011 have uncovered early Christian basilicas with marble decorations, a cathedral, and imported Roman amphorae, Indian ceramics, and Sassanian glassware. The city was abandoned around the 7th-8th century during the early Islamic period.\" -> ''Adulis was an ancient city along the Red Sea in the Gulf of Zula, about 40 kilometers south of Massawa [1]. Archeological excavations conducted at Adulis unearthed the existence of a late prehistoric settlement beneath the town, dating from the mid-2nd to early 1st millennium BCE [1]. Pliny the Elder is the earliest European writer to mention Adulis [1]. Adulis is also mentioned in the Periplus of the Erythraean Sea, a guide of the Red Sea and the Indian Ocean [1]. Adulis was one of the first Axumite sites to undergo excavation, when a French mission to Eritrea under Vignaud and Petit performed an initial survey in 1840, and prepared a map which marked the location of three structures they believed were temples [1]. The first scientific excavations at Adulis were undertaken in 1906, under the supervision of Richard Sundström [1]. Sundström worked in the northern sector of the site, exposing a large structure, which he dubbed the \"palace of Adulis\", as well as recovering some examples of Axumite coinage [1].''"}, {"source": "remediation_change_log:84145", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: lat ''15.273933181644413'' -> ''15.2636''"}, {"source": "remediation_change_log:84146", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: lon ''39.69111438105472'' -> ''39.6606''"}, {"source": "remediation_change_log:84147", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: site_type ''Temple complex'' -> ''City''"}, {"source": "remediation_change_log:141994", "url": "remediation_change_log", "quote": "served-image-2026-09-30-001: thumbnail_url ''/data/images/wiki/0349db41/hero.webp'' -> ''/data/images/wiki/0349db41/ADOULIS Canal Sud détail.webp''"}, {"source": "remediation_change_log:304649", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001: thumbnail_url ''/data/images/wiki/0349db41/ADOULIS Canal Sud détail.webp'' -> ''/data/images/wiki/0349db41/Byzantine_Basilica_(8527948107).webp''"}, {"source": "remediation_change_log:305859", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001-rollback-rest-001: thumbnail_url ''/data/images/wiki/0349