    ('0608f0dc-4dd4-420e-ad27-ea59fe561212'::uuid, 'mystery', '3', '6', 'card-stats-2026-11-05-rollback:0608f0dc-4dd4-420e-ad27-ea59fe561212:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Tell Maghzaliyah', '7670400ad8521ded4eb171ea27340bba', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''< 4500 BC'') is shared by 105 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81654", "url": "remediation_change_log", "quote": "phase4:p4-2039:chunk-0001: description ''Tell Maghzaliyah is a fortified aceramic Mesolithic and Neolithic settlement in Nineveh Governorate, Iraq, dating to before 4500 BC (c. 7000 BC start). Located 7.5 km northwest of Yarim Tepe near the Abra River (tributary of the Habur-Euphrates system), it demonstrates pre-Hassuna cultural development and shares strong connections with the Jarmo culture.[1][2][3]'' -> ''Tell Maghzaliyah, in Nineveh Governorate, Iraq, is a prehistoric fortified aceramic Mesolithic and Neolithic site located approximately 7.5 km northwest of Yarim Tepe, with which it shows some similarities [1]. It is situated near the Abra River, a tributary of the Habur River, which eventually drains into the Euphrates River [1]. Tell Maghzaliyah shows the development of pre-Hassuna culture [1]. There are also numerous connections to the Jarmo culture going back to 7000 BCE [1]. The site is approximately 4500 square meters in area, and the depth of deposit is approximately 8 meters [1]. It was excavated during 12 seasons between 1969 and 1980 on the Sinjar Plain, by a Soviet team from the Institute of Archaeology [1].''"}, {"source": "remediation_change_log:92504", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:92505", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_start ''-7000'' -> None"}, {"source": "remediation_change_log:234528", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:234529", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_start None -> ''-6500''"}, {"source": "remediation_change_log:355562", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
    ('0608f0dc-4dd4-420e-ad27-ea59fe561212'::uuid, 'rarity_score', '25', '34', 'card-stats-2026-11-05-rollback:0608f0dc-4dd4-420e-ad27-ea59fe561212:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''34'' restored on Tell Maghzaliyah', '7670400ad8521ded4eb171ea27340bba', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 25 from mystery 3, cultural_influence 7"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81654", "url": "remediation_change_log", "quote": "phase4:p4-2039:chunk-0001: description ''Tell Maghzaliyah is a fortified aceramic Mesolithic and Neolithic settlement in Nineveh Governorate, Iraq, dating to before 4500 BC (c. 7000 BC start). Located 7.5 km northwest of Yarim Tepe near the Abra River (tributary of the Habur-Euphrates system), it demonstrates pre-Hassuna cultural development and shares strong connections with the Jarmo culture.[1][2][3]'' -> ''Tell Maghzaliyah, in Nineveh Governorate, Iraq, is a prehistoric fortified aceramic Mesolithic and Neolithic site located approximately 7.5 km northwest of Yarim Tepe, with which it shows some similarities [1]. It is situated near the Abra River, a tributary of the Habur River, which eventually drains into the Euphrates River [1]. Tell Maghzaliyah shows the development of pre-Hassuna culture [1]. There are also numerous connections to the Jarmo culture going back to 7000 BCE [1]. The site is approximately 4500 square meters in area, and the depth of deposit is approximately 8 meters [1]. It was excavated during 12 seasons between 1969 and 1980 on the Sinjar Plain, by a Soviet team from the Instit