    ('06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0'::uuid, 'mystery', '10', '7', 'card-stats-2026-11-05-rollback:06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Ngarrabullgan', '0c01c45bbe070758182501ea39ca627c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 10 from (''Sacred site'', ''< 4500 BC'') is shared by 1 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80626", "url": "remediation_change_log", "quote": "phase4:p4-2002:chunk-0001: description \"Ngarrabullgan is a large tabletop mountain in north Queensland, sacred to the Djungan Aboriginal people as a Dreaming place. Ngarrabullgan Cave is one of Queensland''s two oldest known Aboriginal sites, with cultural deposits radiocarbon dated to over 37,000 years ago. Twenty rock shelters with paintings have been recorded, with 90% featuring abstract geometric forms. Aboriginal people stopped camping on the mountain around 600 years ago. It was listed as a National Heritage site in 2011.\" -> \"Ngarrabullgan, officially named Mount Mulligan by the State, is a large tabletop mountain located 100 kilometres west of Cairns in the north of Queensland [1]. The tabletop mountain is a monolith bounded by high cliffs that fall 200 to 400 m to the surrounding Hodgkinson Basin, making it an impressive natural monument which is regarded by the local Djungan Aboriginal peoples to be a sacred ''Dreaming'' place, and features in the mythological legends and beliefs of other Aboriginal groups for hundreds of kilometres around [1]. On the tabletop itself are found the two oldest-known Aboriginal sites in Queensland: Nonda Rock and Ngarrabullgan Cave [1]. Here Aboriginal cultural deposits have been radiocarbon dated, and dated by optically stimulated luminescence, back to 40,000+ years ago [1].\""}, {"source": "remediation_change_log:113483", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:113484", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: period_start ''-500'' -> None"}, {"source": "remediation_change_log:113485", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: site_type ''Cave Structures'' -> ''Sacred site''"}, {"source": "remediation_change_log:142078", "url": "remediation_change_log", "quote": "served-image-2026-09-30-001: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/aa/Ngarrabullgin001.JPG'' -> ''/data/images/wiki/06a1c527/hero.webp''"}, {"source": "remediation_change_log:245611", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:245612", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_start None -> ''-10000''"}]'::jsonb),
