    ('06a73089-340c-40ac-9979-4a5c08f93da5'::uuid, 'mystery', '9', '10', 'card-stats-2026-11-05-rollback:06a73089-340c-40ac-9979-4a5c08f93da5:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Cissbury Ring', 'd3c3e97f7023a40c870d1a0e5829e546', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 9 from (''Fort'', ''4500 - 3000 BC'') is shared by 2 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27884", "url": "remediation_change_log", "quote": "phase3:batch-0025:chunk-0001: period_start ''-1500'' -> ''-250''"}, {"source": "remediation_change_log:30336", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:35640", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_name ''500 BC - 1 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:35641", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-250'' -> ''-1500''"}, {"source": "remediation_change_log:37661", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-wrong-both: period_name ''1500 - 500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:37662", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-wrong-both: period_start ''-1500'' -> ''-3700''"}, {"source": "remediation_change_log:43727", "url": "remediation_change_log", "quote": "phase4:p4-0081:chunk-0001: description ''Cissbury Ring is an 84.2-hectare (208-acre) biological Site of Special Scientific Interest north of Worthing in West Sussex, England [1]. It is owned by the National Trust and is designated a Scheduled monument for its Neolithic flint mine and Iron Age hillfort [1].'' -> ''Cissbury Ring is an 84.2-hectare biological Site of Special Scientific Interest north of Worthing in West Sussex [1]. It is owned by the National Trust and is designated a Scheduled monument for its Neolithic flint mine and Iron Age hillfort [1]. The earthworks that form the fortifications were built around the beginning of the Middle Iron-Age possibly around 250 BC but abandoned in the period 50 BC - 50 AD [1]. The site of the fort contains a Neolithic mine, one of the first flint mines in Britain [1]. Around 270 shafts were dug into Cissbury hill over around 300 years of use [1]. Shafts were up to 12 metres deep with 7 metres diameters at the surface [1]. Up to eight galleries extended outwards from the bottoms of the shafts, often interconnecting with one another [1]. The shafts at Cissbury were excavated with antler picks, much like those at Grimes Graves and elsewhere [1].''"}, {"source": "remediation_change_log:113486", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: site_type ''Mine/quarry'' -> ''Fort''"}, {"source": "remediation_change_log:142080", "url": "remediation_change_log", "quote": "served-image-2026-09-30-001: thumbnail_url ''/data/images/wiki/06a73089/hero.webp'' -> ''/data/images/wiki/06a73089/Cissbury_Ring_rampart_5.webp''"}]'::jsonb),
