    ('0a5920b9-0a15-48f6-bd19-cc8bdd75f26c'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:0a5920b9-0a15-48f6-bd19-cc8bdd75f26c:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Stannon Stone Circle', '8f642dd369964a6e5dadc43c1d45e166', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2900"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43907", "url": "remediation_change_log", "quote": "phase4:p4-0082:chunk-0001: description \"Stannon Stone Circle is a large late Neolithic or early Bronze Age monument on the western slopes of Bodmin Moor near St. Breward, Cornwall. It comprises around 47 closely spaced local granite stones within a slightly flattened circle approximately 42 meters in diameter -- an example of Alexander Thom''s Type A flattened ring. Reputed to be one of the earliest stone circles in the district, it forms part of a Bronze Age ritual landscape oriented toward the peaks of Rough Tor and Brown Willy. Four outlying stones to the northwest may indicate a ceremonial alignment. Excavations by R. J. Mercer in the late 1960s explored the surrounding Stannon Down settlement.\" -> \"Stannon stone circle (also known as Stannon circle or simply Stannon) is a stone circle located near St. Breward on Bodmin Moor in Cornwall, England [1]. The stones average size is around 0.5 metres with the largest stone in the group having a base width of over 1.2 metres [1]. Stannon is an example of Alexander Thom''s Type A flattened circle, being noticeably flattened on the north side [1]. When standing in the supposed centre of Stannon Circle, a point between twenty-two and twenty-eight degrees north from east is marked by Rough Tor [1].\""}, {"source": "remediation_change_log:92563", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:92564", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:142691", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/5/51/Stone_Circle_with_modern_china_clay_works._-_geograph.org.uk_-_418770.jpg'' -> ''/data/images/wiki/0a5920b9/hero.webp''"}, {"source": "remediation_change_log:245657", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:245658", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_start None -> ''-4000''"}, {"source": "remediation_change_log:346290", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:346291", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''-4000'' -> ''-2900''"}]'::jsonb),
    ('0a5920b9-0a15-48f6-bd19-cc8bdd75f26c'::uuid, 'total_power', '28', '29', 'card-stats-2026-11-05-rollback:0a5920b9-0a15-48f6-bd19-cc8bdd75f26c:total_power', 'rollback of card-stats-2026-11-05: total_power ''29'' restored on Stannon Stone Circle', '8f642dd369964a6e5dadc43c1d45e166', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 28 from antiquity + fortification + cultural_influence + mystery + legacy = 7 + 8 + 8 + 4 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43907", "url": "remediation_change_log", "quote": "phase4:p4-0082:chunk-0001: description \"Stannon Stone Circle is a large late Neolithic or early Bronze Age monument on the western slopes of Bodmin Moor near St. Breward, Cornwall. It comprises around 47 closely spaced local granite stones within a slightly flattened circle approximately 42 meters in diameter -- an example of Alexander Thom''s Type A flattened ring. Reputed to be one of the earliest stone circles in the district, it forms part of a Bronze Age ritual landscape oriented toward the peaks of Rough Tor and Brown Willy. Four outlying stones to the northwest may indicate a ceremonial alignment. Excavations by R. J. Mercer in the late 1960s explored the surrounding Stannon Down settlement.\" -> \"Stannon stone circle (also known as Stannon circle or simply Stannon) is a stone circle located near St. Breward on Bodmin Moor in Cornwall, England [1]. The stones average size is around 0.5 metres with the largest stone in the group having a base width of over 1.2 metres [1]. Stannon is an example of Alexander Thom''s Type A flattened circle, being noticeably flattened on the north side [1]. When standing in the supposed centre of Stannon Circle, a point between twenty-two and twenty-eight degrees north from east is marked by Rough Tor [1].\""}, {"source": "remediation_change_log:92563", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:92564", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s001: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:142691", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/5/51/Stone_Circle_with_modern_china_clay_works._-_geograph.org.uk_-_418770.jpg'' -> ''/data/images/wiki/0a5920b9/hero.webp''"}, {"source": "remediation_change_log:245657", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:245658", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s001: period_start None -> ''-4000''"}, {"source": "remediation_change_log:346290", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:346291", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''-4000'' -> ''-2900''"}]'::jsonb),
