    ('0abf05cb-0fda-4567-9d9d-0829911a8c66'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:0abf05cb-0fda-4567-9d9d-0829911a8c66:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Paradise Cave', '01d37b1157945c5fc034e98102123e1c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33043", "url": "remediation_change_log", "quote": "phase4:p4-0012:chunk-0001: description ''Paradise Cave (Jaskinia Raj) is a karstic limestone cave near Kielce, Poland, and one of the most important Palaeolithic sites in the Swietokrzyskie region. The cave served as a Neanderthal encampment approximately 60,000-70,000 years ago, with excavations in the 1960s yielding over 600 flint artifacts and animal remains including horse, mammoth, and rhinoceros bones. Recent research has uncovered hundreds of well-preserved prehistoric bones from cave lions, bears, and mammoths in just five square feet of excavation. The cave also contains spectacular calcite formations with approximately 47,000 stalactites, and has been open to visitors since 1972.'' -> ''Paradise Cave is a horizontal karstic limestone cave located inside the Malik hill, to the south of Kielce, Świętokrzyskie Voivodship, Poland [1]. The cave was discovered in 1963 by Józef Kopeć and Feliks Wawrzeńczak, students of a local technical school [1]. In the sub-recent cave deposits, there are traces of occupancy by Neanderthal dating back to the late Pleistocene, 50 to 60 thousand years ago [1].''"}, {"source": "remediation_change_log:93233", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:93234", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''-60000'' -> None"}, {"source": "remediation_change_log:142718", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/3/37/Jaskiniaraj.jpg'' -> ''/data/images/wiki/0abf05cb/Raj Cave stalactites 2020.webp''"}, {"source": "remediation_change_log:302096", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:302097", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-126000''"}, {"source": "remediation_change_log:304765", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001: thumbnail_url ''/data/images/wiki/0abf05cb/Raj Cave stalactites 2020.webp'' -> ''/data/images/wiki/0abf05cb/Jaskiniaraj.webp''"}, {"source": "remediation_change_log:305969", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001-rollback-rest-001: thumbnail_url ''/data/images/wiki/0abf05cb/Jaskiniaraj.webp'' -> ''/data/images/wiki/0abf05cb/Raj Cave stalactites 2020.webp''"}, {"source": "remediation_change_log:306851", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-001: thumbnail_url ''/data/images/wiki/0abf05cb/Raj Cave stalactites 2020.webp'' -> ''/data/images/wiki/0abf05cb/Jaskiniaraj.webp''"}]'::jsonb),
