    ('0ac27bb1-9767-4302-bcfc-0480349aaf1b'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:0ac27bb1-9767-4302-bcfc-0480349aaf1b:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Knockmaree Dolmen', '28f5212989f8500e0b1314b50a1810a0', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Dolmen'', ''3000 - 1500 BC'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29362", "url": "remediation_change_log", "quote": "phase3:batch-0277:chunk-0001: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:30340", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:35647", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_name ''3000 - 1500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:35648", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-3000'' -> ''-4500''"}, {"source": "remediation_change_log:81752", "url": "remediation_change_log", "quote": "phase4:p4-2042:chunk-0001: description ''Knockmaree Dolmen (also called Knockmaree Cist or Knockmary) is a Neolithic burial monument in Phoenix Park, Dublin, Ireland, dating to approximately 3000-2500 BC. The tomb is a cist situated on a small ridge, with a water-worn capstone measuring 1.96m by 1.05m supported by smaller stones. It was discovered in 1838 when workmen removed a tumulus 15 feet high and 120 feet in circumference, revealing this and four other cists. Finds examined by the Royal Irish Academy included human remains and grave goods.'' -> \"Knockmaree Dolmen, or Knockmaree Cist, is a prehistoric site of the Neolithic period, in Phoenix Park just north of Chapelizod, near Dublin, Ireland [1]. The tomb, situated on a small ridge, is a cist, a type of burial chamber found in Ireland on the south and east coast [1]. It dates from about 3000 B.C. to 2500 B.C. A capstone, measuring 1.96 metres (6 ft 5 in) by 1.05 metres (3 ft 5 in), is supported by smaller stones [1]. The capstone is water-worn, and is thought to have come from the River Liffey nearby [1]. It was discovered in 1838, when workmen were employed to remove a tumulus of height 15 feet (4.6 m) and circumference 120 feet (37 m) [1]. In the centre of the mound were found the stones now visible; four other cists were found in the outer area [1]. The remains were examined by the Royal Irish Academy, the Academy''s report later being delivered by George Petrie [1].\""}, {"source": "remediation_change_log:93235", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:93236", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:142721", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''/data/images/wiki/0ac27bb1/hero.webp'' -> ''/data/images/wiki/0ac27bb1/County Dublin - Knockmaree Dolmen - 20190914151453.webp''"}, {"source": "remediation_change_log:320990", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-001: thumbnail_url ''/data/images/wiki/0ac27bb1/County Dublin - Knockmaree Dolmen - 20190914151453.webp'' -> ''/data/images/wiki/0ac27bb1/hero.webp''"}, {"source": "remediation_change_log:324942", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-