    ('0be2f25c-0545-4329-b65e-fcd3c29ff85d'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:0be2f25c-0545-4329-b65e-fcd3c29ff85d:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Endebjerg', '9781b32fd0709ed8224a214e8949ff02', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81778", "url": "remediation_change_log", "quote": "phase4:p4-2043:chunk-0001: description \"Endebjerg is an excavation site on the Danish island of Samsø, revealing continuous occupation since the Early Neolithic period around 4500 BC [1]. The site was first officially excavated in 1988 under Christian Adamsen, when three-and-a-half pithouses were uncovered alongside a longhouse dated to the Late Iron Age or Viking Age [1]. The most recent excavation occurred in summer 2018, conducted jointly by Harvard University''s Viking Studies Program and Moesgaard Museum under Peter Jensen''s leadership [1]. This multi-period site provides significant insights into prehistoric settlement patterns in Denmark.\" -> ''Endebjerg is the location of an excavation site set in the middle of farmland on the island of Samsø [1]. A series of excavations have shown that this site has been occupied by a variety of cultures since the Early Neolithic period [1]. The site was first officially excavated in 1988 under Christian Adamsen [1]. Endebjerg is located on a hill on the southern side of Stavns Fjord [1]. Three and a half pithouses were excavated, as well as two of the roof-bearing post holes and some of the wall posts belonging to a longhouse dated to the Late Iron Age or Viking Age [1]. A series of flint finds were found that showed evidence of flintknapping that can be dated to the Funnelbeaker culture of the Neolithic period [1]. Ceramic shards found in one of the pithouses can be dated to the Germanic Iron age [1]. Endebjerg is important to the study of Viking activity on Samsø because of the evidence of trade found in the excavations [1].''"}, {"source": "remediation_change_log:93265", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:93266", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:142759", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''/data/images/wiki/0be2f25c/hero.webp'' -> ''/data/images/wiki/0be2f25c/Post_hole_A12.webp''"}, {"source": "remediation_change_log:246031", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:246032", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_start None -> ''-4500''"}, {"source": "remediation_change_log:346302", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:346303", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''-4500'' -> None"}]'::jsonb),
