    ('0c259791-b095-4347-8e59-2172d8791617'::uuid, 'mystery', '4', '5', 'card-stats-2026-11-05-rollback:0c259791-b095-4347-8e59-2172d8791617:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Stanton Drew Stone Circles', '0fb38150e1c7c5a50c0e5e969418f6cc', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Stone circle'', ''3000 - 1500 BC'') is shared by 57 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81780", "url": "remediation_change_log", "quote": "phase4:p4-2043:chunk-0001: description ''The Stanton Drew Stone Circles are located just outside the village of Stanton Drew in Somerset, England. The Great Circle measures 113 metres (371 ft) in diameter, making it the second largest stone circle in Britain after Avebury[1]. Dating to between 3000 and 2000 BCE, this Late Neolithic to Early Bronze Age monument is considered one of the largest Neolithic monuments to have been built[1]. The site was designated a scheduled monument in 1982, providing it legal protection as a nationally important archaeological site[1].'' -> \"The Stanton Drew stone circles are just outside the village of Stanton Drew in the English county of Somerset [1]. The largest stone circle is the Great Circle, 113 metres in diameter and the second largest stone circle in Britain; it is considered to be one of the largest Neolithic monuments to have been built [1]. Some of the stones are still vertical, but the majority are now recumbent, and some are no longer present [1]. The stone circles have been studied since John Aubrey''s visit in 1664, and some excavations of the site were performed in the 18th century [1]. In the late 20th and early 21st centuries, geophysical surveys have confirmed the size of the stone circles and identified additional pits and postholes [1]. The North East Circle is 30 metres in diameter and probably consisted of 10 or more stones, of which 8 survive today [1]. The South West Circle is 43 metres in diameter, and has 12 stones surviving today [1].\""}, {"source": "remediation_change_log:93272", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:93273", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:142806", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/2/22/Stanton_Drew_stone_circle%2C_Somerset.jpg'' -> ''/data/images/wiki/0c259791/Landscape context of Stanton Drew stone circles.webp''"}, {"source": "remediation_change_log:304792", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001: thumbnail_url ''/data/images/wiki/0c259791/Landscape context of Stanton Drew stone circles.webp'' -> ''/data/images/wiki/0c259791/Stanton_Drew_stone_circle,_Somerset.webp''"}, {"source": "remediation_change_log:305993", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001-rollback-rest-001: thumbnail_url ''/data/images/wiki/0c259791/Stanton_Drew_stone_circle,_Somerset.webp'' -> ''/data/images/wiki/0c259791/Landscape context of Stanton Drew stone circles.webp''"}, {"source": "remediation_change_log:306878", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-001: thumbnail_url ''/data/images/wiki/0c259791/Landscape context of Stanton Drew stone circles.webp'' -> ''/data/images/wiki/0c259791/Stanton_Drew_stone_circle,_Somerset.webp''"}]'::jsonb),
