    ('0cd2e708-f7f6-412d-91ba-6d00420b5056'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:0cd2e708-f7f6-412d-91ba-6d00420b5056:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Uley Long Barrow', 'aa7c4956defe105a5cd864a595e49222', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81786", "url": "remediation_change_log", "quote": "phase4:p4-2043:chunk-0001: description \"Also known as Hetty Pegler''s Tump, this Neolithic transepted gallery grave near Uley, Gloucestershire, was built before 3000 BC. The mound measures 37 metres long and 3 metres high, containing a central stone passage with two side chambers and an end chamber. Excavations revealed 15-20 skeletal remains and a later Roman-era intrusive burial. Named after Hester Pegler, wife of a 17th-century landowner. Reconstructed by Dr John Thurnham in 1854, it remains one of the best-surviving Cotswold-Severn group barrows.\" -> \"The Uley Long Barrow, also known locally as Hetty Pegler''s Tump, is a Neolithic burial mound near the village of Uley, Gloucestershire [1]. Although typically described as a long barrow, the mound is actually a transepted gallery grave [1]. It was probably built before 3000 BC [1]. It measures around 37 metres long, 34 metres wide, and has a maximum height of 3 metres [1]. It contains a stone-built central passage with two chambers on each side and another at the end [1]. The earthen mound is surrounded by a dry-stone revetting wall [1]. The barrow was archaeologically excavated in 1821, revealing the remains of fifteen skeletons and a later, intrusive Roman age burial above the northeast chamber [1].\""}, {"source": "remediation_change_log:142813", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/96/Uley_Long_Barrow.jpg'' -> ''/data/images/wiki/0cd2e708/Uley Long Barrow (42082931545).webp''"}, {"source": "remediation_change_log:304795", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001: thumbnail_url ''/data/images/wiki/0cd2e708/Uley Long Barrow (42082931545).webp'' -> ''/data/images/wiki/0cd2e708/Uley_Long_Barrow.webp''"}, {"source": "remediation_change_log:305996", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001-rollback-rest-001: thumbnail_url ''/data/images/wiki/0cd2e708/Uley_Long_Barrow.webp'' -> ''/data/images/wiki/0cd2e708/Uley Long Barrow (42082931545).webp''"}, {"source": "remediation_change_log:306881", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-001: thumbnail_url ''/data/images/wiki/0cd2e708/Uley Long Barrow (42082931545).webp'' -> ''/data/images/wiki/0cd2e708/Uley_Long_Barrow.webp''"}]'::jsonb),
