    ('0dfe2efe-0699-4300-8f2e-04852c23ab55'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:0dfe2efe-0699-4300-8f2e-04852c23ab55:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Balls Head Reserve', 'eed7a77163552765feb05a125edef07f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43917", "url": "remediation_change_log", "quote": "phase4:p4-0082:chunk-0001: description ''Forested headland reserve in Waverton, Sydney, on Port Jackson, 1.5 km west of the Harbour Bridge. Traditional land of the Cammeraygal people, the reserve preserves Aboriginal rock engravings, art sites, and shell middens. The most notable feature is a large whale engraving approximately 6 m long with unusually deep-cut grooves and a mysterious human-like figure near the tail. The engraving was partly covered by a roadway for over 80 years before being uncovered during renovations at the Coal Loader site. The reserve is believed to have been a place for sacred corroborees.'' -> ''The Balls Head Reserve is a forested headland nature reserve situated on Balls Head in Sydney [1]. The headland is in Port Jackson, 1.5 kilometres west of the Sydney Harbour Bridge, between Berrys Bay to the east and Balls Head Bay to the west [1]. The original inhabitants were the Cammeraygal people [1]. Evidence of their occupation includes art sites, middens and a spectacular petroglyph of a marine creature [1]. An Aboriginal burial site within a rock shelter was documented by Sandra Bowdler, an archaeologist from the Australian Museum in 1964 [1]. Until 1916, the Balls Head area was frequented by the local Aboriginal community and sites including middens, art sites and rock engravings remain today [1]. The Aboriginal name for Balls Head is Yerroulbine [1].''"}, {"source": "remediation_change_log:113545", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:113546", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:142833", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''/data/images/wiki/0dfe2efe/hero.webp'' -> ''/data/images/wiki/0dfe2efe/(1)Balls_Head_Reserve-3.webp''"}, {"source": "remediation_change_log:246045", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:246046", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_start None -> ''-10000''"}, {"source": "remediation_change_log:304816", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001: thumbnail_url ''/data/images/wiki/0dfe2efe/(1)Balls_Head_Reserve-3.webp'' -> ''/data/images/wiki/0dfe2efe/Angophora_costata_Balls_Head.webp''"}, {"source": "remediation_change_log:306017", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001-rollback-rest-001: thumbnail_url ''/data/images/wiki/0dfe2efe/Angophora_costata_Balls_Head.webp'' -> ''/data/images/wiki/0dfe2efe/(1)Balls_Head_Reserve-3.webp''"}, {"source": "remediation_change_log:306902", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-001: thumbnail_url ''/data/images/wiki/0dfe2efe/(1)Balls_Head_Reserve-3.webp'' -> ''/data/images/wiki/0dfe2efe/Angophora_costata_Balls_Head.webp''"}, {"source": "remediation_change_log:346310", "url": "remediation_change_log", "quote"