    ('0e0531f8-6b94-43ab-b6db-81611a30e297'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:0e0531f8-6b94-43ab-b6db-81611a30e297:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Carisbrook Stone Arrangement', 'bf436db59961864cafd0359e4b63602e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81796", "url": "remediation_change_log", "quote": "phase4:p4-2043:chunk-0001: description ''The Carisbrook Stone Arrangement is a well-preserved Aboriginal ceremonial site on the banks of Tullaroop Creek, about 5 km southeast of Carisbrook in Victoria, Australia. Measuring 60 by 5 metres, it consists of a double arc of boulders forming a boomerang shape, a stone cairn, and smaller circles -- making it the only boomerang-design stone arrangement in the state and one of only four stone arrangements in Victoria. First reported in the 1960s and surveyed in the 1980s by the Victorian Archaeological Survey, the site was purchased by the state government in 1975 and declared an Archaeological Area under the Archaeological and Aboriginal Relics Protection Act 1972. The Indigenous Land Council acquired the surrounding farm in 1997 and divested it to the Ballarat Aboriginal Co-op as custodians.'' -> ''The Carisbrook stone arrangement is a well-preserved Aboriginal stone arrangement in Victoria [1]. The site consists of a double arc shape of boulders, a cairn of stones and other small stone circles [1]. The ends of the crescent point to the cardinal points [1]. It has been considered by some to be a male initiation ground, mainly on the basis of comparison with other similar sites in NSW [1]. This arrangement is believed to fall within the traditional land of the Wurn balug clan of the Djadjawurrung [1]. Following its rediscovery in 1963, interest was focussed on its interpretation and protection, with initial protection provided under the Archaeological Relics Office [1].''"}, {"source": "remediation_change_log:93298", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:93299", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''1'' -> None"}, {"source": "remediation_change_log:93300", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: site_type ''Stone circle'' -> None"}, {"source": "remediation_change_log:234571", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: site_type None -> ''Archaeological site''"}, {"source": "remediation_change_log:246049", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:246050", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_start None -> ''1''"}, {"source": "remediation_change_log:346312", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:346313", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''1'' -> None"}]'::jsonb),
