    ('0e4e4bfd-6702-4adc-b6be-c2e47764cfef'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:0e4e4bfd-6702-4adc-b6be-c2e47764cfef:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Gough''s Cave', 'f0f1820dc5cd45af05236de9cc4b9288', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43307", "url": "remediation_change_log", "quote": "phase4:p4-0071:chunk-0001: description \"Gough''s Cave is located in Cheddar Gorge on the Mendip Hills in Somerset, England. The cave extends 115 meters deep and 3.405 kilometers in length, featuring large chambers and rock formations [1]. It contains the Cheddar Yeo, the largest underground river system in Britain [1]. Archaeologically, the cave is famous for a late Upper Paleolithic Magdalenian occupation around 14,700 years ago, with human remains showing evidence of cannibalism and skull cup production [1]. The cave also yielded the Mesolithic skeleton of Cheddar Man, dating to approximately 10,300 years ago [1].\" -> ''Gough\\''s Cave is located in Cheddar Gorge on the Mendip Hills, in Cheddar, Somerset, England [1]. The cave contained skeletal remains of animals and of humans, indicating that the cave was occupied for a relatively brief period by Magdalenian peoples towards the end of the last ice age, when conditions had become warm enough for humans to return to Britain after northern Europe became uninhabitable around the Last Glacial Maximum [1]. Skull fragments represent from 5 to 7 humans, including a young child of about 3 years and two adolescents [1]. The Magdalenian human skulls found at Gough\\''s cave were carefully processed using stone tools to produce \"skull cups\", likely used as ritual drinking cups or bowls [1]. In 1903 the remains of a human male, since named Cheddar Man, were found a short distance inside Gough\\''s Cave [1]. He is Britain\\''s oldest complete human skeleton, having been dated to the Mesolithic, approximately 10,564–9,915\\u2009calibrated years Before Present [1].''"}, {"source": "remediation_change_log:83064", "url": "remediation_change_log", "quote": "2026-09-26c_fields-wd1-s001: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:83065", "url": "remediation_change_log", "quote": "2026-09-26c_fields-wd1-s001: period_start ''-500'' -> None"}, {"source": "remediation_change_log:142860", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''/data/images/wiki/0e4e4bfd/hero.webp'' -> ''/data/images/wiki/0e4e4bfd/Cheddar_cave_cheese.webp''"}, {"source": "remediation_change_log:234575", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:234576", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_start None -> ''-12750''"}, {"source": "remediation_change_log:304825", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001: thumbnail_url ''/data/images/wiki/0e4e4bfd/Cheddar_cave_cheese.webp'' -> \"/data/images/wiki/0e4e4bfd/Gough''s_cave_entrance,_Cheddar.webp\""}, {"source": "remediation_change_log:306026", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001-rollback-rest-001: thumbnail_url \"/data/images/wiki/0e4e4bfd/Gough''s_cave_entrance,_Cheddar.webp\" -> ''/data/images/wiki/0e4e4bfd/Cheddar_cave_cheese.webp''"}, {"source": "remediation_change_log:306911", "url": "remediation_change_log", "quote