    ('0e942695-743b-4144-bf9f-f5687fc61447'::uuid, 'mystery', '6', '4', 'card-stats-2026-11-05-rollback:0e942695-743b-4144-bf9f-f5687fc61447:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Court Hill, Sussex', 'fe16362fb9de9a20498f8616f3413832', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Earthwork'', ''4500 - 3000 BC'') is shared by 13 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28550", "url": "remediation_change_log", "quote": "phase3:batch-0158:chunk-0003: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:81824", "url": "remediation_change_log", "quote": "phase4:p4-2044:chunk-0001: description ''Court Hill is a Neolithic causewayed enclosure near East Dean in West Sussex, dating to the 4th millennium BC. Identified as potentially significant in 1951, it was excavated by Owen Bedwin in 1982 and confirmed as a causewayed enclosure. The site is approximately 175 m across, shaped as an irregular rectangle with rounded corners defined by a ditch with an internal bank. Causewayed enclosures are characterized by interrupted ditches and may have served as seasonal meeting places for trading goods or conducting funerary rites. The bank has been levelled by ploughing, though the ditch remains visible in the wooded northeastern area.'' -> ''Court Hill is a causewayed enclosure in West Sussex [1]. The site was identified as of possible archaeological interest in 1951, and was excavated in 1982 by Owen Bedwin [1]. It was confirmed to be a causewayed enclosure by Bedwin, and has since been dated to the fourth millennium BC by radiocarbon dating [1]. The site lies at the southwest end of a wooded ridge, near the village of East Dean [1]. The enclosure is about 175 metres across [1]. The enclosure is shaped like an irregular rectangle with rounded corners, and is defined by a ditch with a bank inside it [1]. The bank has been levelled by ploughing and is no longer visible; the ditch is still visible within the wooded area in the northeastern part of the enclosure [1]. The curator of the Sussex Archaeological Society, N. E. S. Norris, was the first to notice the possibility of a prehistoric site on Court Hill [1].''"}, {"source": "remediation_change_log:113551", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: site_type ''Archaeological site'' -> ''Earthwork''"}]'::jsonb),
