    ('0ecacadb-c9da-490b-95ef-4b220c386d3d'::uuid, 'mystery', '4', '7', 'card-stats-2026-11-05-rollback:0ecacadb-c9da-490b-95ef-4b220c386d3d:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Carranque', '1d4dec0ed749d6e3a78384602590497c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Residence/villa/farmhouse'', ''1 - 500 AD'') is shared by 75 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:113557", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: lat ''40.17097264016538'' -> ''40.188889''"}, {"source": "remediation_change_log:113558", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: lon ''-3.896847843879161'' -> ''-3.955556''"}, {"source": "remediation_change_log:113559", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: site_type ''Residence/villa/farmhouse'' -> ''Villa''"}, {"source": "remediation_change_log:113560", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: source_url ''https://en.wikipedia.org/wiki/Carranque'' -> ''https://es.wikipedia.org/wiki/Villa_romana_de_Carranque''"}, {"source": "remediation_change_log:142873", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''/data/images/wiki/0ecacadb/hero.webp'' -> ''/data/images/wiki/0ecacadb/Carranque.webp''"}, {"source": "remediation_change_log:169281", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4206:chunk-0001: description \"Carranque Archaeological Park in Toledo province, Spain, preserves a lavish 4th-century Roman villa complex rediscovered in 1983 when a farmer''s plough struck a mosaic. The site comprises the Villa of Maternus with elaborate floor mosaics depicting scenes including the death of Adonis and the god Oceanus, a basilica originally featuring 32 monolithic marble columns, and a mausoleum. The villa included luxury amenities such as hypocaust under-floor heating and running water, with mosaics assembled by at least three workshops, two of which signed their work. The complex is attributed to Maternus Cynegius, an Iberian-born adviser to Emperor Theodosius, and later saw Visigothic, Islamic, and Knights Templar occupation.\" -> \"Carranque Archaeological Park in Toledo province, Spain, preserves a lavish 4th-century Roman villa complex rediscovered in 1983 when a farmer''s plough struck a mosaic [1]. The site comprises the Villa of Maternus with elaborate floor mosaics depicting scenes including the death of Adonis and the god Oceanus, a basilica originally featuring 32 monolithic marble columns, and a mausoleum [1] [2] [3]. The villa included luxury amenities such as hypocaust under-floor heating and running water, with mosaics assembled by at least three workshops, two of which signed their work [1].\""}, {"source": "remediation_change_log:304836", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001: thumbnail_url ''/data/images/wiki/0ecacadb/Carranque.webp'' -> ''/data/images/wiki/0ecacadb/Carranque-basilica.webp''"}, {"source": "remediation_change_log:306037", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-001-001-rollback-rest-001: thumbnail_url ''/data/images/wiki/0ecacadb/Carranque-basilica.webp'' -> ''/data/images/wiki/0ecacadb/Carranque.webp''"}, {"source": "remediation_change_log:306922", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-001: thumbnail_url ''/data/images/wiki/0ecacadb/Carranque.webp'' -> ''/data/images/wiki/0ecacadb/Carranque-basilica.webp''"}, {"source": "remediation_change_log:3555