    ('0ed79845-f651-4c52-85cd-7f96bab43d4e'::uuid, 'mystery', '9', '8', 'card-stats-2026-11-05-rollback:0ed79845-f651-4c52-85cd-7f96bab43d4e:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Eightercua Stone Row', '3d078c8cdbb2633d082abc621f89d34e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 9 from (''Standing stone'', ''3000 - 1500 BC'') is shared by 2 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81828", "url": "remediation_change_log", "quote": "phase4:p4-2044:chunk-0001: description ''Eightercua is a four-stone alignment megalithic tomb in County Kerry, Ireland, located 1.5 km south-south-east of Waterville. The tallest stone reaches 10 feet in height, with the alignment stretching 25 feet in an east-west direction [1][2]. Dating to circa 1700 BC, surrounding artifacts include remains of a possible tomb and ancient enclosure, suggesting ritual purpose [1][2]. By tradition, it is the burial place of Scéine, wife of Milesian leader Amergin mac Míled [1][2].'' -> ''Eightercua is thought to originate from around 1700 BC, and by tradition is the burial place of Scéine, wife of the leader of the Milesian invaders, Amergin mac Míled [1]. The site features four tall slabs from 1.8 to 3 meters high running east and west [1]. From one stone a slab runs south and could be part of a tomb chamber or cist set in an oval cairn 1 meter high [1].''"}, {"source": "remediation_change_log:113564", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: site_type ''Megalithic stones'' -> ''Standing stone''"}, {"source": "remedi