    ('0eec5ffa-1383-4b6b-92d1-cdc1f1dc0cfb'::uuid, 'mystery', '8', '10', 'card-stats-2026-11-05-rollback:0eec5ffa-1383-4b6b-92d1-cdc1f1dc0cfb:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Densuș Church', '06afba6eb599d8ee326648547a18dda7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Church/cathedral'', ''1000 - 1500 AD'') is shared by 3 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33077", "url": "remediation_change_log", "quote": "phase4:p4-0013:chunk-0001: description ''The Densus Church (St Nicholas) in Hunedoara County is considered the oldest stone church in Romania, with regular services held for over 700 years. Built in its present form around the 13th century, it incorporates Roman-era stone columns, marble blocks, tiles, and terra cotta pipes salvaged from the ruins of Ulpia Traiana Sarmizegetusa, the former capital of Roman Dacia. Some scholars believe it was erected on the site of a 2nd-century Roman temple dedicated to Mars. The interior features remarkable 15th-century mural paintings depicting Jesus Christ in traditional Romanian garments.'' -> ''The Densuș Church in the village of Densuș, Hunedoara County is the oldest Orthodox stone church in Romania [1]. Up to the 15th century it was part of a court of the local knezial family [1]. The church has a stone tower above the naos [1]. The altar, nave, and diaconicon were built in the same period, while the side chapel is a later addition [1]. Inside the church there are 15th-century mural paintings that show Jesus wearing traditional Romanian clothes [1]. These paintings were made by artist Ștefan [1]. In the 18th century more paintings were added by Simion de Pitești and his apprentices [1]. From 1566 to the end of the 19th century, the building functioned as a Calvinist church, too [1].''"}, {"source": "remediation_change_log:93312", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:93313", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''1'' -> None"}, {"source": "remediation_change_log:142879", "url": "remediation_change_log", "quote": "served-image-2026-09-30-002: thumbnail_url ''/data/images/wiki/0eec5ffa/hero.webp'' -> ''/data/images/wiki/0eec5ffa/Biserica Densuș pe fundal de Sub Carpați Retezat.webp''"}, {"source": "remediation_change_log:234581", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_name None -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:234582", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_start None -> ''1250''"}]'::jsonb),
