    ('0fa0df95-200a-40bf-805d-51a1f530f973'::uuid, 'antiquity', '5', '2', 'card-stats-2026-11-05-rollback:0fa0df95-200a-40bf-805d-51a1f530f973:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''2'' restored on Burra Ness Broch', 'b74f7173475e964d4f79a6602bc623c1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -800"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81870", "url": "remediation_change_log", "quote": "phase4:p4-2045:chunk-0001: description \"Burra Ness Broch is an Iron Age broch on the east coast of Yell, Shetland, situated on the tip of the Burra Ness headland south of Gutcher. The tower has an external diameter of 18.3 metres with drystone walls 4.6 metres thick, standing up to 4.27 metres high on the east side. A scarcement ledge for an upper floor is visible in the interior. The broch sits on a low artificial platform with later structures built around it, and earthen ramparts survive to the south and southwest. Never formally excavated, it is one of Shetland''s best-preserved brochs after Mousa and Clickimin.\" -> ''Burra Ness Broch is an iron-age broch located on the east coast of the island of Yell, Shetland [1]. Burra Ness Broch is situated 2.6 kilometres south of the small village of Gutcher on the tip of the headland of Burra Ness [1]. The broch has an external diameter of about 18 metres [1]. The outer wall is around 4.5 metres thick, and stands over 4 metres high on the east side [1]. Two hundred years ago the broch is reported to have been 20 feet (6.1 metres) high, and the beginning of a bell-shaped profile was clearly visible [1]. Internally a \"scarcement\" ledge to support an upper floor is visible some 4 metres above the ground [1].''"}, {"source": "remediation_change_log:93331", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:93332", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:246063", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:246064", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_start None -> ''800''"}, {"source": "remediation_change_log:346322", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''500 - 1000 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:346323", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''800'' -> ''-800''"}]'::jsonb),
