    ('1010b3bf-a7d5-4e2c-9f70-8212a2cd1699'::uuid, 'rarity_tier', '2', '3', 'card-stats-2026-11-05-rollback:1010b3bf-a7d5-4e2c-9f70-8212a2cd1699:rarity_tier', 'rollback of card-stats-2026-11-05: rarity_tier ''3'' restored on La Corona', '0dbc8a9ffbf51f9902df2c192c72c3a4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_tier = 2 from rarity_score 28"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81874", "url": "remediation_change_log", "quote": "phase4:p4-2045:chunk-0001: description \"La Corona is an ancient Maya court residence in Guatemala''s Petén department, discovered in 1996 and identified as the long-sought ''Site Q'', the source of a series of unprovenanced limestone reliefs of exceptional artistic quality [1]. The site''s Classical Maya name was Sak-Nikte'' (''White-Flower'') [1].\" -> ''La Corona is the name given by archaeologists to an ancient Maya court residence in Guatemala\\''s Petén department that was discovered in 1996, and later identified as the long-sought \"Site Q\", the source of a long series of unprovenanced limestone reliefs of exceptional artistic quality [1]. The site\\''s Classical name appears to have been Sak-Nikte\\'' (\\''White-Flower\\'') [1]. During the 1960s, looted Maya reliefs from a then-unknown city surfaced on the international art market [1]. In 2005 Marcello A. Canuto, then a Yale professor, found a panel in situ at La Corona that mentioned two Site Q rulers [1]. In April 2012, La Corona Archaeological Project discovered a row of 12 staircase risers with many different relief scenes; another 10 sculpted risers were found looted from their original context but then discarded for being too eroded to be worth selling on the illicit antiquities market [1]. In 679 AD, a daughter of Calakmul\\''s powerful Yuknoom Ch\\''een was given in marriage to a La Corona king [1]. In 721 AD, a daughter of the Calakmul king (Yuknoom Took\\'' K\\''awiil) was married off to a king of La Corona [1].''"}, {"source": "remediation_change_log:93347", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:93348", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''500'' -> None"}, {"source": "remediation_change_log:93349", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: site_type ''Settlement'' -> ''City''"}, {"source": "remediation_change_log:143358", "url": "remediation_change_log", "quote": "served-image-2026-09-30-003: thumbnail_url ''/data/images/wiki/1010b3bf/hero.webp'' -> ''/data/images/wiki/1010b3bf/La_Corona_relieve.webp''"}, {"source": "remediation_change_log:234596", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:234597", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_start None -> ''250''"}, {"source": "remediation_change_log:321046", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-001: thumbnail_url ''/data/images/wiki/1010b3bf/La_Corona_relieve.webp'' -> ''/data/images/wiki/1010b3bf/hero.webp''"}, {"source": "remediation_change_log:324951", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/1010b3bf/hero.webp'' -> ''/data/images/wiki/1010b3bf/La Corona Relieve Juego de Pelota.webp''"}, {"source": "remediation_change_log:355569", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''City'' -> ''City/town