    ('1032047c-3a0c-413b-bd70-23b81f64487e'::uuid, 'total_power', '29', '30', 'card-stats-2026-11-05-rollback:1032047c-3a0c-413b-bd70-23b81f64487e:total_power', 'rollback of card-stats-2026-11-05: total_power ''30'' restored on Shovel Down', 'a7d3d27e0d29f9696c20c243a97509f6', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 29 from antiquity + fortification + cultural_influence + mystery + legacy = 7 + 8 + 8 + 5 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81876", "url": "remediation_change_log", "quote": "phase4:p4-2045:chunk-0001: description ''Shovel Down is a megalithic complex on Dartmoor, Devon, featuring multiple stone rows, the Fourfold Stone Circle, and standing stones [1].'' -> ''Shovel Down is an area of Dartmoor in Devon that is covered in megaliths including the remains of several stone rows, the Fourfold Stone Circle, and several standing stones [1]. The Shovel Down stone row complex occupies the northern and southern slopes of a broad east-west ridge of unenclosed moorland [1]. It is of probable Bronze Age date [1]. Approximately five double stone rows and one single stone row are to be seen [1]. The Fourfold Circle is a configuration of four concentric stone circles [1]. The Fourfold Circle is the location of a turf-covered cairn with a central cist which has been robbed [1]. The Long Stone stands in the middle of two stone rows [1]. It is referred to as the \"Langstone\" in a documentary source of 1240 [1].''"}, {"source": "remediation_change_log:93353", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''4500