    ('113ce1a7-3e6a-49cb-9120-e6e230191646'::uuid, 'antiquity', '5', '2', 'card-stats-2026-11-05-rollback:113ce1a7-3e6a-49cb-9120-e6e230191646:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''2'' restored on Bilbao', 'c7bf1e506c2759f95f48671151ea3406', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81898", "url": "remediation_change_log", "quote": "phase4:p4-2046:chunk-0001: description \"Bilbao is a major Mesoamerican archaeological site near Santa Lucia Cotzumalguapa in the Escuintla department of Guatemala, situated on the Pacific coastal plain among sugar plantations. One of three principal compounds of the ancient Cotzumalhuapa urban center, alongside El Baul and El Castillo, the city flourished during the Late Classic period (c. 650-950 AD) and dominated the southern Maya area. The site is known for its corpus of over 200 monumental stone sculptures carved in a distinctive style. Bilbao was connected to El Baul by the 3-kilometre-long Gavarrete Causeway, a stone-paved avenue 11-14 metres wide that served as the city''s main thoroughfare.\" -> \"Bilbao is a Mesoamerican archaeological site about 1 mile from the modern town of Santa Lucía Cotzumalguapa in the Escuintla department of Guatemala [1]. Bilbao was a major centre belonging to the Cotzumalhuapa culture with its main occupation dating to the Late Classic (c. AD 600–800) [1]. The archaeological sites of Bilbao, El Baúl and El Castillo were all parts of the same urban centre that extended over about 10 square kilometres [1]. This extended urban area is known as the Cotzumalhuapa Nuclear Zone by archaeologists and Bilbao lies in the southernmost part of this area [1]. Bilbao was occupied since the Preclassic and was the most important site dating to the Preclassic within what became in later periods the Cotzumalhuapa Nuclear Zone [1]. 58 monuments were listed by Parsons at Bilbao, but only 3 remain in situ in Bilbao''s Monument Plaza [1]. Ballgame reliefs at Bilbao feature blossoming and fruiting plants symbolic of agricultural fertility [1]. Stelae at Bilbao depict ballplayers with disembodied heads and various sculptures depict dismembered body parts [1].\""}, {"source": "remediation_change_log:93366", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:93367", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''500'' -> None"}, {"source": "remediation_change_log:93368", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:234603", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: site_type None -> ''Urban''"}, {"source": "remediation_change_log:246079", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:246080", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_start None -> ''500''"}, {"source": "remediation_change_log:346334", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''500 - 1000 AD'' -> ''Undated''"}, {"source": "remediation_change_log:346335", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''500'' -> None"}, {"source": "remediation_change_log:355572", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-