    ('14c408ee-cfa0-43cc-8294-a2f8cc0d76bb'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:14c408ee-cfa0-43cc-8294-a2f8cc0d76bb:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Cave of Pedra Furada', 'f65733768e9bb3828198a87f12174397', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Cave Structures'', ''4500 - 3000 BC'') is shared by 11 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33115", "url": "remediation_change_log", "quote": "phase4:p4-0014:chunk-0001: description ''The Cave of Pedra Furada is a small cave located in the municipality of Vila Franca de Xira, approximately 20 km north of Lisbon, Portugal [1]. The cave was formed through karstification of the limestone Upper Jurassic Massif [1]. Archaeological excavations have revealed evidence of intermittent human occupation during at least three distinct periods between the end of the fourth millennium BC and the second millennium BC [1]. This evidence indicates prolonged or repeated use of the site throughout prehistoric times, making it a significant archaeological location for understanding Neolithic and Chalcolithic human activity in the region [1].'' -> \"The Cave of Pedra Furada is a small cave located in the municipality of Vila Franca de Xira, about 20 km north of Lisbon in Portugal [1]. Archaeological studies conducted within the cave suggest it was occupied intermittently by humans during at least three periods between the end of the fourth millennium BC and the second millennium BC [1]. The cave results from karstification of the limestone Upper Jurassic Massif [1]. The first formal archaeological excavation was carried out in 1955 by a team led by Hipólito Cabaço [1]. This identified a communal funeral space, and radiocarbon dating of one individual''s bones indicates that the use of the cave as a necropolis dates back to between 3095 BC and 2915 BC [1]. Archaeologists also collected a number of objects, such as bone drills, beads of various materials, flint arrowheads, microliths, a polished stone axe, fragments of pottery and a bone figurine of a rabbit [1].\""}, {"source": "remediation_change_log:93416", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:93417", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s002: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:143414", "url": "remediation_change_log", "quote": "served-image-2026-09-30-003: thumbnail_url ''/data/images/wiki/14c408ee/hero.webp'' -> ''/data/images/wiki/14c408ee/PedraFurada2.webp''"}, {"source": "remediation_change_log:234632", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:234633", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_start None -> ''-3095''"}, {"source": "remediation_change_log:321064", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-001: thumbnail_url ''/data/images/wiki/14c408ee/PedraFurada2.webp'' -> ''/data/images/wiki/14c408ee/hero.webp''"}, {"source": "remediation_change_log:324954", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/14c408ee/hero.webp'' -> ''/data/images/wiki/14c408ee/PedraFurada1.webp''"}]'::jsonb),
