ni [1].''"}, {"source": "remediation_change_log:113617", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:113618", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: period_start ''1'' -> None"}, {"source": "remediation_change_log:113619", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:113620", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: source_url ''https://en.wikipedia.org/wiki/Intikancha_(Puno)'' -> None"}, {"source": "remediation_change_log:234647", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: site_type None -> ''Archaeological site''"}, {"source": "remediation_change_log:234648", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: source_url None -> ''https://en.wikipedia.org/wiki/Intikancha_(Puno)''"}, {"source": "remediation_change_log:246121", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_name None -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:246122", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_start None -> ''1000''"}, {"source": "remediation_change_log:346364", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''1000 - 1500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:346365", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''1000'' -> None"}]'::jsonb),
    ('16bdc3b7-0e3b-4c6f-9313-6988d76fa673'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:16bdc3b7-0e3b-4c6f-9313-6988d76fa673:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Sara Sara', '108c1d287c5f54d4679613d041e938c0', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80656", "url": "remediation_change_log", "quote": "phase4:p4-2003:chunk-0001: description ''Sara Sara is a 5,505-metre-high (18,061 ft) volcano in southern Peru, situated between Lake Parinacochas and the Ocoña River in the Parinacochas and Paucar del Sara Sara provinces. It formed during the Pleistocene through four stages of volcanic activity, building a volcanic edifice with an oval outline consisting of lava flows and lava domes [1]. The volcano was glaciated during the Last Glacial Maximum and may still retain glaciers [1]. Its last eruption occurred about 14,000 years ago, and future eruptions remain possible [1]. Notably, archaeologists discovered an Inca mummy of a 15-year-old girl on the summit, indicating the volcano was worshipped by the local population [1].'' -> ''Sara Sara is a 5,505-metre-high volcano lying between Lake Parinacochas and the Ocoña River in Peru [1]. The volcano formed during the Pleistocene during four different stages of volcanic activity, which constructed a volcanic edifice with an oval outline consisting of lava flows and lava domes [1]. The mountain was worshipped by local populations in and before Inca time, and the Inca performed human sacrifices on it [1]. During Inca times it was part of the Kuntisuyu province [1]. According to the writings of a cleric Cristóbal de Albornoz, who beginning in 1570 wrote about local religious practices, the local population considered Sara Sara a sacred mountain and offered gold, silver, animals and servants to it [1]. In 1996, archaeologists discovered a burial in a collapsed structure just northeast of the summit and recovered a body [1]. This mummy was nicknamed \"Sarita\" and appears to be a 15-year old girl [1]. It was accompanied by the remnants of offerings and the ice surrounding the body had melted [1].''"}, {"source": "remediation_change_log:94323", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:94324", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''1'' -> None"}, {"source": "remediation_change_log:143454", "url": "remediation_change_log", "quote": "served-image-2026-09-30-003: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/8/88/Sara_Sara_Volcano.jpg'' -> ''/data/images/wiki/16bdc3b7/Sara_Sara_Volcano.webp''"}, {"source": "remediation_change_log:246123", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:246124", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_start None -> ''1''"}, {"source": "remediation_change_log:346366", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:346367", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''1'' -> None"}]'::jsonb),
