    ('16d9eae9-81b1-436e-bd93-e6aea4b4c818'::uuid, 'antiquity', '6', '4', 'card-stats-2026-11-05-rollback:16d9eae9-81b1-436e-bd93-e6aea4b4c818:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Samicum', '8c970dab7162f5a29384ca8822652184', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 6 from period_start -2000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82016", "url": "remediation_change_log", "quote": "phase4:p4-2049:chunk-0001: description ''Samicum (or Samikon) was an ancient town of Triphylia in Elis, Greece, situated near the coast roughly halfway between the mouths of the Alpheius and Neda rivers, and slightly north of the Anigrus[1]. It occupied a projecting spur of a lofty mountain that approached so near the coast as to leave only a narrow pass[1]. From its strategic position commanding this pass, it is probable a city existed here from the earliest times[2]. Samicum was occupied by the Aetolian Polysperchon during conflicts with the Arcadians[2].'' -> ''Samicum or Samikon was a town of Triphylia in ancient Elis, situated near the coast about half-way between the mouths of the Alpheius and the Neda, and a little north of the Anigrus [1]. It stood upon a projecting spur of a lofty mountain, which here approaches so near the coast as to leave only a narrow pass [1]. Samicum was occupied by the Aetolian Polysperchon against the Arcadians, and was taken by Philip V of Macedon in 219 BCE [1]. Near Samicum upon the coast was a celebrated temple of the Samian Poseidon, surrounded by a grove of wild olives [1]. It was the centre of the religious worship of the six Triphylian cities, all of whom contributed to its support [1]. The ruins of Samicum are found at Kleidi Hill near Kato Samiko [1]. The ruined walls are 6 feet (2 m) thick, and about 1.5 miles (2.4 km) in circumference [1]. The remains found on Kleidi Hill include cyclopean walls and remnants of a settlement that was occupied in the middle and late Helladic periods [1].''"}, {"source": "remediation_change_log:94325", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:94326", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''-500'' -> None"}, {"source": "remediation_change_log:143463", "url": "remediation_change_log", "quote": "served-image-2026-09-30-003: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/b/b3/Samiko.jpg'' -> ''/data/images/wiki/16d9eae9/Samia acropolis.webp''"}, {"source": "remediation_change_log:246127", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:246128", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s002: period_start None -> ''-500''"}, {"source": "remediation_change_log:321080", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-001: thumbnail_url ''/data/images/wiki/16d9eae9/Samia acropolis.webp'' -> ''/data/images/wiki/16d9eae9/hero.webp''"}, {"source": "remediation_change_log:324956", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/16d9eae9/hero.webp'' -> ''/data/images/wiki/16d9eae9/Samiko.webp''"}, {"source": "remediation_change_log:346370", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''500 BC - 1 AD'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:346371", "url": "remediation_change_log", "quote": "2026-10-17a_fields-