    ('17c94d52-2df2-44ba-83f1-41c26ee6eea3'::uuid, 'mystery', '1', '5', 'card-stats-2026-11-05-rollback:17c94d52-2df2-44ba-83f1-41c26ee6eea3:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Butrint', 'e1af4fdaa2b51e213cc3dcc99adeb67f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''1500 - 500 BC'') is shared by 286 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29284", "url": "remediation_change_log", "quote": "phase3:batch-0266:chunk-0001: period_start ''-3000'' -> ''-1000''"}, {"source": "remediation_change_log:29285", "url": "remediation_change_log", "quote": "phase3:batch-0266:chunk-0001: site_type ''Temple complex'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:30356", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''3000 - 1500 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:32390", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-journal-reversal-2: site_type ''City/town/settlement'' -> ''Temple complex''"}, {"source": "remediation_change_log:80660", "url": "remediation_change_log", "quote": "phase4:p4-2003:chunk-0001: description ''Butrint is an ancient Greek and Roman city in Vlore County, Albania, designated a UNESCO World Heritage Site in 1992. Settled from as early as the 10th-8th centuries BC by the Chaonian tribe, it grew into a major centre with a theatre, an Asclepius sanctuary, and an agora by the 4th century BC. Under Rome it became a colonia with baths, an aqueduct, a nymphaeum, and temples of Minerva and Asclepius. It later served as an early Christian bishopric before declining after a medieval earthquake flooded the site. The 200-hectare archaeological reserve includes a baptistery, the Lion Gate, and extensive fortifications.'' -> \"Butrint was an ancient Greek polis and later Roman city and the seat of an early Christian bishopric in Epirus [1]. Bouthroton (modern day Butrint) was originally one of the major centres of the Epirote tribe of the Chaonians, part of the northwestern Greek group of tribes [1]. The inventories of bishoprics from the 10th to 12th centuries identify the bishop of Butrint as subject to the metropolitan bishopric of Nafpaktos [1]. Butrint became Catholic after it was conquered by the Angevins, and remained so throughout the fourteenth century [1]. The first modern archaeological excavations began in 1928 when the Fascist government of Benito Mussolini''s Italy sent an expedition to Butrint [1]. Since 1993 further major excavations have taken place led by the Butrint Foundation in collaboration with the Albanian Institute of Archaeology [1].\""}, {"source": "remediation_change_log:113633", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s001: site_type ''Temple complex'' -> ''City''"}, {"source": "remediation_change_log:143497", "url": "remediation_change_log", "quote": "served-image-2026-09-30-003: thumbnail_url ''/data/images/wiki/17c94d52/hero.webp'' -> ''/data/images/wiki/17c94d52/2011_Butrint_02_Agora.webp''"}, {"source": "remediation_change_log:355576", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
