    ('18462ce6-cfb7-43ba-83cd-d44c26395227'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:18462ce6-cfb7-43ba-83cd-d44c26395227:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Zennor Quoit', '33c2a1061f973e57838035c39a96cc94', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Dolmen'', ''3000 - 1500 BC'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82062", "url": "remediation_change_log", "quote": "phase4:p4-2050:chunk-0001: description ''Zennor Quoit is a ruined megalithic burial chamber (dolmen) on Zennor Moor, Cornwall, dating to 2500–1500 BC[1]. Located about 1.6 km (1 mi) east of Zennor village, it features several upright stones supporting a massive 12.5-tonne capstone that collapsed between 1770 and 1865[1]. Archaeological evidence indicates the chamber was used for collective burial, where bodies were initially interred, later cremated, and their remains relocated[1]. Despite the fallen roof, the chamber remains substantially intact[1].'' -> ''Zennor Quoit is a ruined megalithic burial chamber or dolmen, located on a moor about a mile east of the village of Zennor, Cornwall, England [1]. Aside from the 12.5-tonne roof, which collapsed some time between 1770 and 1865, the chamber is in good condition [1]. The quoit measures 12.8 metres in total in diameter [1]. The chamber itself consists of seven upright stones and was originally covered by a cairn [1]. The chamber dates to between 2500 and 1500 BC and is one of eight remaining quoits on the West Penwith moors [1]. Archaeological evidence unearthed on the site has indicated that the chamber was used for the burial of bodies which at some point would be cremated and removed and replaced with others [1]. Excavations at the site have revealed flint and Neolithic style pottery and cremated bones [1]. In 1754 and in 1769, before the roof had fallen, the quoit was analysed by the antiquary Dr. William Borlase, who described and provided detailed drawings of it and published some of his findings in his Antiquities of Cornwall [1].''"}, {"source": "remediation_change_log:94353", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:94354", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:143516", "url": "remediation_change_log", "quote": "served-image-2026-09-30-003: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/b/b9/Zennor_Quoit_%28small%29_%289612120%29.jpg'' -> ''/data/images/wiki/18462ce6/hero.webp''"}, {"source": "remediation_change_log:234661", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:234662", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s001: period_start None -> ''-2500''"}, {"source": "remediation_change_log:307683", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-002: thumbnail_url ''/data/images/wiki/18462ce6/hero.webp'' -> ''/data/images/wiki/18462ce6/Zennor_Quoit_(small)_(9612120).webp''"}]'::jsonb),
