    ('192076c0-4d8f-4217-a193-ecfffb6a5a50'::uuid, 'antiquity', '4', '6', 'card-stats-2026-11-05-rollback:192076c0-4d8f-4217-a193-ecfffb6a5a50:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on Castallack Round', 'cedcda829ecb25287c006b0553c48fac', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 4 from period_start -100"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82094", "url": "remediation_change_log", "quote": "phase4:p4-2051:chunk-0001: description \"Castallack Round (also Roundago) is a prehistoric earthwork near Castallack in Cornwall, England, and a scheduled monument dating to the late Iron Age through early post-Roman period [1]. The site occupies a ridge summit overlooking the Lamorna valley [1]. A ''round'' is a small circular embanked enclosure with a single entrance, a settlement type common across Cornwall [1]. Surviving rampart sections comprise large stones and slabs standing approximately 1.6 metres high and 1.8 metres wide [1].\" -> ''Castallack Round or Roundago is a prehistoric site near Castallack in Cornwall, England [1]. It is a scheduled monument [1]. The site is near the summit of a ridge overlooking the Lamorna valley [1]. Part of the rampart survives; it is composed of large stones and slabs, height about 1.6 metres and width 1.8 metres, forming an oval enclosure [1]. There was originally a surrounding ditch [1]. On the tithe map of 1840, the round is depicted as having a colonnade of stones leading from the entrance in the south to an inner circular enclosure; John Thomas Blight, describing it in 1865, found that these features had mostly disappeared [1]. To the north-west of the round there are thick stone walls, height up to 0.9 metres: the remains of a structure with an internal diameter of about 7.5 metres [1]. This is interpreted as a courtyard house, a type of building that developed in west Cornwall from the 2nd to 4th centuries AD [1].''"}, {"source": "remediation_change_log:94373", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:94374", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:94375", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: site_type ''Earthwork'' -> ''Settlement''"}, {"source": "remediation_change_log:246469", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:246470", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_start None -> ''-1500''"}, {"source": "remediation_change_log:346392", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:346393", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:354759", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_name ''Undated'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:354760", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_start None -> ''-100''"}, {"source": "remediation_change_log:355577", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
