    ('1a2c2dc7-7003-4025-a8ce-f3401a10134f'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:1a2c2dc7-7003-4025-a8ce-f3401a10134f:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Tomb of Eve', 'dec98f1b6334bc2d9ed8a64cfd1b83ca', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Necropolis/tombs complex'', ''Undated'') is shared by 18 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82128", "url": "remediation_change_log", "quote": "phase4:p4-2052:chunk-0001: description ''The Tomb of Eve in Jeddah, Saudi Arabia, is an archaeological site believed by some Muslims to be the burial place of the biblical Eve (Hawwa). The earliest documented mention comes from the Arab cartographer Muhammad al-Idrisi in the mid-12th century. The tomb was reportedly 120 m long before Prince Faisal, Viceroy of Hejaz, destroyed it in 1928. In 1975, the site was sealed with concrete by religious authorities opposed to tomb veneration. Today it is a row of unmarked graves with no visible trace of the original structure.'' -> \"The Tomb of Eve, also known as Eve''s Grave and Eve''s Tomb, is an archaeological site located in Jeddah, Saudi Arabia [1]. It is considered by some Muslims to be the burial place of Eve [1]. Prince Faisal, Viceroy of Hejaz, destroyed it in 1928 [1]. In 1975, the site was also sealed with concrete by religious authorities, who disapprove of pilgrims praying at tombs [1]. Richard Francis Burton mentions seeing it in his translation of the Book of a Thousand Nights and a Night [1]. Ibn al-Mujawir (13th century) makes a clear reference to the Tomb of Eve in Jeddah, and so does Ibn Khallikan (13th century) [1]. Aun Ar-Rafiq (Amir in Hijaz 1882–1905) tried to demolish the tomb, but that caused a public outcry [1].\""}, {"source": "remediation_change_log:94389", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:94390", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''1'' -> None"}, {"source": "remediation_change_log:143931", "url": "remediation_change_log", "quote": "served-image-2026-09-30-004: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/8/80/Eves-tomb-the-story-of-a-pilgrimage-to-hijaz.png'' -> ''/data/images/wiki/1a2c2dc7/Tomb of Eve - topview.webp''"}, {"source": "remediation_change_log:246475", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:246476", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_start None -> ''-800''"}, {"source": "remediation_change_log:307725", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-002: thumbnail_url ''/data/images/wiki/1a2c2dc7/Tomb of Eve - topview.webp'' -> ''/data/images/wiki/1a2c2dc7/Eves-tomb-the-story-of-a-pilgrimage-to-hijaz.webp''"}, {"source": "remediation_change_log:346394", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:346395", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s001: period_start ''-800'' -> None"}]'::jsonb),
