    ('1a9242d4-250f-4ffb-8dad-dae849c10798'::uuid, 'mystery', '6', '4', 'card-stats-2026-11-05-rollback:1a9242d4-250f-4ffb-8dad-dae849c10798:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Balankanche Cave', '10fbffd3f702fa3738a3e5cc4cf90a85', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Cave Structures'', ''500 BC - 1 AD'') is shared by 19 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:32152", "url": "remediation_change_log", "quote": "2026-09-23_source-url-split-wave4: source_url ''https://www.megalithic.co.uk/article.php?sid=22783\\nhttps://en.wikipedia.org/wiki/Balankanche'' -> ''https://www.megalithic.co.uk/article.php?sid=22783''"}, {"source": "remediation_change_log:82132", "url": "remediation_change_log", "quote": "phase4:p4-2052:chunk-0001: description \"Sacred Maya cave located approximately 4 km southeast of Chichen Itza in Yucatan, Mexico. Used for over two thousand years for rituals dedicated to the rain god Chaac and, in the Post-Classic period, his Toltec counterpart Tlaloc. First visited by Edward Thompson and Alfred Tozzer in 1905, the cave''s full extent and hidden passages were not discovered until 1959. The 2 km cave complex contained stairs, altars, and ritual displays of ceramics and stone implements. INAH converted it into an underground museum with artifacts returned to their original positions.\" -> \"Balankanche is an ancient Maya cave site lying at short distance from the archaeological Maya-Toltec city of Chichen Itza [1]. For more than two thousand years, it has been the focus of rituals dedicated to the Maya rain god, Chaac, and, in the Post-Classic period, also to his Toltec counterpart, Tlaloc [1]. The cave complex was visited by Edward Thompson and Alfred Tozzer in 1905 and has since 1932 been explored and studied by various Mexican and US scholars [1]. Small buildings and platforms surrounded the cave''s entrance; inside, stairs, walls, altars and ritual displays of ceramics and small stone implements were discovered [1].\""}, {"source": "remediation_change_log:94404", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:94405", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:235504", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:235505", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_start None -> ''-300''"}]'::jsonb),
