    ('1d4dd1f5-e841-4c8c-9761-2d4ad3eec155'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:1d4dd1f5-e841-4c8c-9761-2d4ad3eec155:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Kinniside Stone Circle', '828c4aba019ee0a3f0b99268ff6738ca', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33219", "url": "remediation_change_log", "quote": "phase4:p4-0017:chunk-0001: description ''Kinniside Stone Circle (also called Blakeley Raise) is a reconstructed Bronze Age stone circle in the civil parish of Ennerdale and Kinniside, Cumbria, situated alongside the fell road from Ennerdale Bridge to Calder Bridge. It consists of 11 local granite stones forming a circle 18 m in diameter, with the tallest stone reaching 1.15-1.5 m. A possible cairn 5 m across occupies the centre. The original circle was dismantled in the 18th century by a farmer who reused the stones as gateposts; Dr. Quine of Frizington re-erected it in 1925 with the stones set in concrete. The accuracy of the reconstruction to the original layout remains uncertain.'' -> ''Kinniside Stone Circle is a reconstructed stone circle in the civil parish of Ennerdale and Kinniside in Cumbria [1]. Kinniside Stone Circle is situated next to the fell road from Ennerdale Bridge to Calder Bridge in Cumbria [1]. It consists of 11 small stones of local granite with a possible cairn at its centre [1]. The circle was apparently dismantled in the 18th century by a farmer who used the stones for gate-posts [1]. In 1925 a Doctor Quine of Frizington \"restored\" the stone circle, setting the stones in concrete [1]. Whether or not he erected the stones in their original stone holes is unclear, and it is unlikely that all of the re-erected stones come from the original circle [1].''"}, {"source": "remediation_change_log:94460", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:94461", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:246511", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:246512", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_start None -> ''-4000''"}, {"source": "remediation_change_log:347163", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:347164", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-4000'' -> None"}]'::jsonb),
