    ('1da76491-5256-486f-b67e-ff6f762c46b5'::uuid, 'mystery', '6', '4', 'card-stats-2026-11-05-rollback:1da76491-5256-486f-b67e-ff6f762c46b5:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on High Peak, Devon', '329c58addd6711fe2c03ee778059250e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Fort'', ''Undated'') is shared by 11 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82196", "url": "remediation_change_log", "quote": "phase4:p4-2055:chunk-0001: description ''High Peak is a partially eroded hill with a cliff face on the English Channel coast, southwest of Sidmouth, Devon, England [1]. Its highest point reaches approximately 157 metres (515 ft) above sea-level [1]. The site contains the remains of a partially eroded Iron Age hill fort [1]. Archaeological excavations have uncovered both pre-Roman and post-Roman pottery at the location [1].'' -> ''High Peak is a hill which is partially eroded, resulting in a cliff face, on the English Channel coast to the southwest of Sidmouth, Devon, southern England [1]. Its highest point is about 157 metres above sea-level [1]. It features a partially eroded Iron Age hill fort, with pre-Roman and post Roman pottery found there [1]. On the edge of the cliff there are the remains of significant earthworks, which have been variously shown as having Iron Age, Roman and Dark Age occupation [1]. Geological study, and the lines of the earthworks, suggest that the site once extended several tens of metres into what is now eroded away [1]. General interpretation suggests that it was an Iron Age defensive site which saw re-use in the Dark Age period, perhaps as a coastal trading station [1].''"}, {"source": "remediation_change_log:114813", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:114814", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:114815", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: site_type ''Fortress/citadel'' -> ''Fort''"}, {"source": "remediation_change_log:114816", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: source_url ''https://en.wikipedia.org/wiki/High_Peak,_Devon'' -> ''https://www.megalithic.co.uk/article.php?sid=43929''"}, {"source": "remediation_change_log:144044", "url": "remediation_change_log", "quote": "served-image-2026-09-30-004: thumbnail_url ''/data/images/wiki/1da76491/hero.webp'' -> ''/data/images/wiki/1da76491/View from Peak Hill, near Sidmouth - geograph.org.uk - 1372146.webp''"}, {"source": "remediation_change_log:246517", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:246518", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_start None -> ''-800''"}, {"source": "remediation_change_log:307809", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-002: thumbnail_url ''/data/images/wiki/1da76491/View from Peak Hill, near Sidmouth - geograph.org.uk - 1372146.webp'' -> ''/data/images/wiki/1da76491/2010-10-07_peak_hill_sidmouth.webp''"}, {"source": "remediation_change_log:347167", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:347168", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-800'' 