    ('1dd3a790-bf81-49e2-b516-dcc04a14328f'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:1dd3a790-bf81-49e2-b516-dcc04a14328f:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Roman Theatre, St Albans', 'a8dde25d2a9f97562aca5047e7ba79b1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Theatre'', ''1 - 500 AD'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28010", "url": "remediation_change_log", "quote": "phase3:batch-0050:chunk-0001: site_type ''Megalithic stones'' -> ''Theatre''"}, {"source": "remediation_change_log:43981", "url": "remediation_change_log", "quote": "phase4:p4-0084:chunk-0001: description ''Built around 140 AD within the Roman walled city of Verulamium, this is the only known Roman theatre with a stage (as opposed to an amphitheatre) in Britain. Originally used for religious processions, wrestling, and beast shows, the stage grew in prominence from 180 AD. By 300 AD, renovations expanded seating capacity to 2,000 spectators with excellent acoustics for dramatic performances. First excavated in 1847 and again in the 1930s by Kathleen Kenyon, the site also revealed surrounding shops occupied by blacksmiths and bronze workers.'' -> ''The Roman Theatre at St Albans, Hertfordshire, England is an excavated site within the Roman walled city of Verulamium [1]. Although there are other Roman theatres in Britain, the one at Verulamium is claimed to be the only example of its kind, being a theatre with a stage rather than an amphitheatre [1]. The theatre differs from the typical Roman theatre in being built on a site that is only slightly sloping (where possible Roman theatres took advantage of the natural terrain), and in its plan (although there are theatres with similar plans in Northern Gaul) [1]. The theatre was built in about 140AD [1]. Urban life continued in Verulamium into the 5th century [1]. However, by that time the theatre had fallen into disuse [1]. It was used as a rubbish dump in the 4th century [1].''"}, {"source": "remediation_change_log:114818", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: lat ''51.7551328001168'' -> ''51.754079''"}, {"source": "remediation_change_log:114819", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: lon ''-0.3360214604358662'' -> ''-0.358312''"}, {"source": "remediation_change_log:144049", "url": "remediation_change_log", "quote": "served-image-2026-09-30-004: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/a0/RomanTheatreVerulamium-PS1.jpg'' -> ''/data/images/wiki/1dd3a790/The Roman Theatre at Verulamium, St Albans (14213826514).webp''"}, {"source": "remediation_change_log:307818", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-002: thumbnail_url ''/data/images/wiki/1dd3a790/The Roman Theatre at Verulamium, St Albans (14213826514).webp'' -> ''/data/images/wiki/1dd3a790/RomanTheatreVerulamium-PS1.webp''"}]'::jsonb),
