    ('1dfccf93-13b6-46cf-a719-8cfd1683e097'::uuid, 'cultural_influence', '5', '3', 'card-stats-2026-11-05-rollback:1dfccf93-13b6-46cf-a719-8cfd1683e097:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''3'' restored on Sagalassos Antoninler Çeşmesi', '00a0e6177932271d8e9c20150c0e4c48', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 5 from description yes, thumbnail yes, 0 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:94478", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:94479", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''1'' -> None"}, {"source": "remediation_change_log:94480", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: site_type ''Monument'' -> None"}, {"source": "remediation_change_log:169831", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4213:chunk-0001: description ''The Antonine Nymphaeum, a monumental fountain built during the reign of Marcus Aurelius (AD 161-180) at the ancient city of Sagalassos in Burdur Province, Turkey. Measuring 28 metres long and 9 metres tall, it was constructed from seven types of colored stone and adorned with sculptures of Dionysus, Nemesis, Asklepios, and other classical deities. Destroyed by a 7th-century earthquake, the fountain was excavated between 1993-1995 and restored using original elements by 2010. It honors the Antonine dynasty and was likely financed by patron Titus Flavius Severianus Neon.'' -> ''The Antonine Nymphaeum, a monumental fountain built during the reign of Marcus Aurelius (AD 161-180) at the ancient city of Sagalassos in Burdur Province, Turkey [1] [2] [3]. Measuring 28 metres long and 9 metres tall, it was constructed from seven types of colored stone and adorned with sculptures of Dionysus, Nemesis, Asklepios, and other classical deities [4]. Destroyed by a 7th-century earthquake, the fountain was excavated between 1993-1995 and restored using original elements by 2010 [4].''"}, {"source": "remediation_change_log:235564", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:235565", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_start None -> ''160''"}, {"source": "remediation_change_log:235566", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: site_type None -> ''Monument''"}, {"source": "remediation_change_log:339044", "url": "remediation_change_log", "quote": "insert-2026-10-07-001-001: thumbnail_url None -> ''/data/images/wiki/1dfccf93/Sagalassos Antonine Fountain in 2012 2684.webp''"}]'::jsonb),
