    ('1e6efd70-020c-43b7-a63c-495eefa5a972'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:1e6efd70-020c-43b7-a63c-495eefa5a972:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on La Draga', 'c4c13c425ec48fec948a7e5a31185d18', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''< 4500 BC'') is shared by 105 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28570", "url": "remediation_change_log", "quote": "phase3:batch-0162:chunk-0001: period_start ''-6000'' -> ''-5300''"}, {"source": "remediation_change_log:35686", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-5300'' -> ''-6000''"}, {"source": "remediation_change_log:43985", "url": "remediation_change_log", "quote": "phase4:p4-0084:chunk-0001: description ''Early Neolithic lakeshore settlement on Lake Banyoles in Catalunya, Spain, dating to the last quarter of the 6th millennium BC. La Draga is the only prehistoric lacustrine site known in the Iberian Peninsula. Archaeological excavations revealed two distinct occupation phases, though no significant change in material culture or technical tradition has been observed between them[1].'' -> ''La Draga is an Early Neolithic lakeshore site (last quarter of the 6th millennium BCE) located in Banyoles and it is the only prehistoric lacustrine site of the Iberian Peninsula [1]. Excavations allowed the identification of two different Early Neolithic phases of occupation, though no change in the technical tradition has been recorded between the two phases [1]. La Draga was discovered during preventive archaeological excavations led in 1990 by the Museu Arqueològic Comarcal de Banyoles [1]. This first excavation revealed that the site was an Early Neolithic Cardial settlement likely occupied from the end of the 6th millennium BC [1]. During the older phase (5.290-5.200 cal BC) the settlement can be described as a pile dwelling site and it represents the largest known settlement in the NE of the Iberian Peninsula, while in the later phase (5.100-4.800 cal BC) large surfaces were covered by stone pavement [1]. The farmers of La Draga were among the first to practise agriculture in the north-east of the Iberian Peninsula [1].''"}, {"source": "remediation_change_log:94490", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: lat ''42.11961149100136'' -> ''42.126667''"}, {"source": "remediation_change_log:94491", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: lon ''2.766367439024681'' -> ''2.758611''"}, {"source": "remediation_change_log:144065", "url": "remediation_change_log", "quote": "served-image-2026-09-30-004: thumbnail_url ''/data/images/wiki/1e6efd70/hero.webp'' -> ''/data/images/wiki/1e6efd70/La Draga 01.webp''"}]'::jsonb),
