    ('1ed00cd4-fec4-406f-af91-8c6bf79eeb3d'::uuid, 'mystery', '10', '8', 'card-stats-2026-11-05-rollback:1ed00cd4-fec4-406f-af91-8c6bf79eeb3d:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Filitosa', '9a00db01489aca922e0fe461b9d4cc9a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 10 from (''Megalithic statues'', ''4500 - 3000 BC'') is shared by 1 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80704", "url": "remediation_change_log", "quote": "phase4:p4-2005:chunk-0001: description ''A major megalithic site in the Taravo Valley of southern Corsica, France, with evidence of occupation from approximately 6000 BC through Roman times. Discovered by Charles-Antoine Cesari in 1946, systematic excavations by archaeologist Roger Grosjean from 1954 onward revealed about twenty anthropomorphic menhir statues -- some depicting armed warriors with swords and daggers -- representing roughly half of all such monuments in Corsica. The site also features three Torrean tower monuments from the second half of the 2nd millennium BC. Classified as a Historic Monument in 1980, Filitosa is among the 100 historic sites of common interest to Mediterranean countries.'' -> ''Filitosa is a megalithic site in southern Corsica, France [1]. The period of occupation spans from the end of the Neolithic era and the beginning of the Bronze Age, until around the Roman times in Corsica [1]. The site was discovered in 1946 by the owner of the land, Charles-Antoine Cesari, and brought to the attention of archeologists by the British writer, Dorothy Carrington [1]. Systematic excavations started in 1954 by Roger Grosjean [1]. Finds of arrow heads and pottery date earliest inhabitation to 3300 BC [1]. Around 1500 BC, 2-3 metre menhirs were erected [1]. They have been carved with representations of human faces, armour and weapons [1].''"}, {"source": "remediation_change_log:94505", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:94506", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:94507", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: site_type ''Megalithic stones'' -> ''Megalithic statues''"}, {"source": "remediation_change_log:144518", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''/data/images/wiki/1ed00cd4/hero.webp'' -> ''/data/images/wiki/1ed00cd4/Corse-Du-Sud Filitosa Oppidum - panoramio (2).webp''"}, {"source": "remediation_change_log:235573", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:235574", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_start None -> ''-3300''"}]'::jsonb),
