    ('1ee1e668-a44a-47f0-840a-c1d5e804ff2c'::uuid, 'mystery', '7', '8', 'card-stats-2026-11-05-rollback:1ee1e668-a44a-47f0-840a-c1d5e804ff2c:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Puka Pukara Archaeological Complex', 'a5c5fa8dd2cac613ed7fde6d9c622a0b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Fortress/citadel'', ''1000 - 1500 AD'') is shared by 6 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82222", "url": "remediation_change_log", "quote": "phase4:p4-2056:chunk-0001: description ''Puka Pukara is an ancient Inca fortress and military complex situated in the Cusco Region of Peru, near the city of Cusco. The site features large stone walls, terraces, and staircases. It served as a strategic defensive fortification protecting the capital city of Cusco and the broader Inca Empire.[1]'' -> ''Puka Pukara (Quechua puka red, pukara fortress, \"red fortress\", hispanicized spellings Pucapucara, Puca Pucara, Puca Pucará) is a site of military ruins in Peru situated in the Cusco Region, Cusco Province, Cusco District [1]. Puka Pukara is located in mid-southern Peru, about 7 kilometres from Cusco, on the road to Pisac, near to the Antisuyo, the jungle portion of the former Incan empire [1]. The fort is located on high ground overlooking the Cusco valley and Tambo Machay [1]. Although less is known about Puka Pukara than many other Incan ruins, there is a theory that this site was probably constructed during the reign of Pachacutec [1].''"}, {"source": "remediation_change_log:144542", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/7/78/Tambo_Machay_D%C3%A9cembre_2006.jpg'' -> ''/data/images/wiki/1ee1e668/Puka_Pukara_Inca_site,_Peru.webp''"}, {"source": "remediation_change_log:333695", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-001: thumbnail_url ''/data/images/wiki/1ee1e668/Puka_Pukara_Inca_site,_Peru.webp'' -> ''/data/images/wiki/1ee1e668/Tambo_Machay_Décembre_2006.webp''"}]'::jsonb),
