    ('1f5cb852-dcc8-440d-9931-c5968dff6cc0'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:1f5cb852-dcc8-440d-9931-c5968dff6cc0:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Marlborough Mound', '78600a6c085efbe733f9f232848cae54', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Mound/tumulus'', ''3000 - 1500 BC'') is shared by 14 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82224", "url": "remediation_change_log", "quote": "phase4:p4-2056:chunk-0001: description \"2400 BC Marlborough Mound is a Neolithic mound in Marlborough, Wiltshire, standing 19 metres (60 ft) tall[1]. It is the second-largest such monument in Britain, surpassed only by nearby Silbury Hill[1]. The mound was constructed around 2400 BC during the Neolithic period and was designated a Scheduled Monument in 1951[1]. It forms part of a complex of Neolithic monuments that includes Avebury Ring, Silbury Hill, and West Kennet Long Barrow[1]. Local legend associates the mound with Merlin, earning it the alternative name Merlin''s Mound or Merlin''s Mount[1].\" -> \"The Marlborough Mound, also known as Merlin''s Mound or Merlin''s Mount, is a Neolithic monument in the town of Marlborough in the English county of Wiltshire [1]. Standing 19 metres tall, it is second only to the nearby Silbury Hill in terms of height for such a monument [1]. Since construction, the mound has functioned as the motte for a Norman castle, a garden feature for a stately home, and the site for a water tower within Marlborough College [1]. The mound is located on the western side of Marlborough within the grounds of Marlborough College, close to the River Kennet [1]. The original purpose of Marlborough Mound is unknown as it dates from around 2400 BC, the Neolithic period [1].\""}, {"source": "remediation_change_log:144569", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''/data/images/wiki/1f5cb852/hero.webp'' -> ''/data/images/wiki/1f5cb852/Marlborough_mound_20240518_looking_southwards.webp''"}]'::jsonb),
