    ('1ff140bb-47dc-44c9-93bb-c47dda258591'::uuid, 'antiquity', '8', '7', 'card-stats-2026-11-05-rollback:1ff140bb-47dc-44c9-93bb-c47dda258591:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Dolmen of Carapito I', '3ad3a9851de518f9f5d87555d68aaabd', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -3998"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82232", "url": "remediation_change_log", "quote": "phase4:p4-2056:chunk-0001: description ''The Dolmen of Carapito I (Anta de Carapito I) is a megalithic monument in the parish of Carapito, municipality of Aguiar da Beira, Guarda District, Portugal, dating to approximately 2900 BC. It is a simple structure with a ten-sided polygonal chamber without a corridor, facing northwest, with pillars reaching 3.5 metres in height. Two of its orthostats bear engravings of circles, stripes, vertical wavy lines, and concentric circles. The structure was explored by V. Leisner and L. Ribeiro in 1966, who revealed an entranceway and a large fallen stone.'' -> ''Dolmen of Carapito I is a megalithic monument located in the civil parish of Carapito, in the municipality of Aguiar da Beira in the Guarda District of Portugal [1]. The dolmen was constructed during the Megalithic period, around 2900 BC [1]. The first explorations of the site were completed by J. Coelho, who collected ceramic fragments [1]. Excavations by Vera Leisner and Leonel Ribeiro were undertaken in 1966 [1]. Located near Guarda, the dolmen is located in a rural landscape, isolated on the western margin of the Ribeira do Carapito [1]. Carapito I is the type of megalithic dolmen characterised by I. Moita as a simple structure with a ten-sided polygonal chamber without a corridor [1].''"}, {"source": "remediation_change_log:94518", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:94519", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s003: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:235575", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:235576", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_start None -> ''-2900''"}, {"source": "remediation_change_log:324967", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/1ff140bb/hero.webp'' -> ''/data/images/wiki/1ff140bb/Dólmen I de Carapito.webp''"}, {"source": "remediation_change_log:347177", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''3000 - 1500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:347178", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-2900'' -> None"}, {"source": "remediation_change_log:354763", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_name ''Undated'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:354764", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_start None -> ''-3998''"}]'::jsonb),
