    ('218a4df9-1bc1-43ce-a054-1d964d7232a4'::uuid, 'cultural_influence', '5', '3', 'card-stats-2026-11-05-rollback:218a4df9-1bc1-43ce-a054-1d964d7232a4:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''3'' restored on Tarragal Caves', '83eb21f621f1bccb3ae5ace18c00cc13', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 5 from description yes, thumbnail yes, 0 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44015", "url": "remediation_change_log", "quote": "phase4:p4-0085:chunk-0001: description ''The Tarragal Caves are a network of limestone caves and rock shelters overlooking the Bridgewater Lakes near Cape Bridgewater, Victoria, Australia. Excavations in the late 1970s by Harry Lourandos revealed stratified deposits dating to 11,300 years ago, along with shell midden deposits and earth ovens over 11,000 years old. The caves were important Aboriginal camping places, and pollen analysis of cave sediments has helped reconstruct the Pleistocene climate and environment of the region.'' -> ''The Tarragal Caves are a network of large limestone caves and rockshelters which overlook the Bridgewater Lakes near the towns of Tarragal and Cape Bridgewater [1]. The caves were identified as important Aboriginal camping places early in the historic period, and were excavated in the late 1970s by Harry Lourandos, revealing stratified deposits in the floor of 11,300 years old, along with shell midden deposits and earth ovens over 11,000 years old [1]. One of the caves extends under ground for over 400 m and has a sinkhole opening to the surface so that there is a constant stream of air through the cave and rising up the hole [1]. Pollen analysis of sediments in the cave has assisted in reconstructing the Pleistocene climate and environment of the region and understanding what resources were available to Aborigines [1].''"}, {"source": "remediation_change_log:95193", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:95194", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''-9000'' -> None"}, {"source": "remediation_change_log:246547", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:246548", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s003: period_start None -> ''-4501''"}, {"source": "remediation_change_log:339239", "url": "remediation_change_log", "quote": "insert-2026-10-07-002-001: thumbnail_url None -> ''/data/images/wiki/218a4df9/Tarragal Cave.webp''"}]'::jsonb),
