    ('21f3da5f-262c-46e8-bead-32be438da097'::uuid, 'mystery', '1', '5', 'card-stats-2026-11-05-rollback:21f3da5f-262c-46e8-bead-32be438da097:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Los Naranjos Archaeological Park', 'a85885129e56f9cb74a5535c97913636', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''1500 - 500 BC'') is shared by 286 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80712", "url": "remediation_change_log", "quote": "phase4:p4-2005:chunk-0001: description ''A pre-Columbian archaeological site on the northwest shore of Lake Yojoa in Honduras, first occupied around 1300 BC and featuring some of the tallest monumental platforms in pre-Columbian Honduras outside the Classic Maya zone. Structure IV measures 100 m on a side and stands about 20 m tall, constructed primarily of earth with stone facing. Four phases span from Jaral (800-400 BC) through Rio Blanco (950-1250 AD), with artifacts including jade figurines and objects showing Olmec-related imagery such as cylinder seals. French archaeologists Baudez and Becquelin excavated the site from 1967 to 1969, and it is now preserved as the Parque Eco-Arqueologico Los Naranjos.'' -> ''Los Naranjos archaeological site is located on the border of Mesoamerica [1]. The site appears to have reached one of its peak periods during the Eden phase, corresponding to the Late Formative and Early Classic period [1]. In 1935, Frans Blom and Jens Yde conducted an excavation of a large mound at Los Naranjos [1]. They found a large collection of polychrome pottery [1]. The site contained two large ditches, one that stretched from Lake Yojoa to a pool just north of an encampment, made during the Jaral phase [1].''"}, {"source": "remediation_change_log:95216", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''500 BC - 1 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:95217", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''-500'' -> ''-1000''"}, {"source": "remediation_change_log:95218", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:144644", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Los_Naranjos_Honduras.jpg/400px-Los_Naranjos_Honduras.jpg'' -> None"}, {"source": "remediation_change_log:235602", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: site_type None -> ''City''"}, {"source": "remediation_change_log:355589", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
