    ('22aa305a-3ecf-454e-a643-3e08dbbd2e14'::uuid, 'mystery', '10', '9', 'card-stats-2026-11-05-rollback:22aa305a-3ecf-454e-a643-3e08dbbd2e14:mystery', 'rollback of card-stats-2026-11-05: mystery ''9'' restored on al-Siq', '9245c6e5a67d44bbb20cf3860056f5ec', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 10 from (''Natural feature'', ''500 BC - 1 AD'') is shared by 1 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82284", "url": "remediation_change_log", "quote": "phase4:p4-2057:chunk-0001: description ''The Siq (Arabic: السِّق, \"gorge\") is the principal entrance to the ancient Nabatean city of Petra in southern Jordan [1]. This dim, narrow sandstone gorge winds approximately 1.2 km (0.7 mi) through rose-red cliffs, creating one of archaeology\\''s most dramatic pedestrian approaches [1][2]. The passage ends at Al-Khazneh, Petra\\''s most elaborate ruin, which greets visitors with its intricate carved facade [1]. A wide valley outside leading to the Siq is known as the Bab as-Sīq [1].'' -> \"The Siq is the main entrance to the ancient Nabatean city of Petra in southern Jordan [1]. Also known as Siqit, it is a dim, narrow gorge (in some points no more than 3 metres (10 ft) wide) and winds its way approximately 1.2 kilometres and ends at Petra''s most elaborate ruin, Al-Khazneh [1]. Unlike slot canyons such as Antelope Canyon in the American Southwest, which are directly shaped by water, the Siq is a natural geological fault split apart by tectonic forces; only later was it worn smooth by water [1]. The walls that enclose the Siq stand between 91–182 metres in height [1]. The entrance to the Siq contains a huge dam designed to bar the mouth of the Siq and reroute the waters of Wadi Musa [1]. The dam is a fairly true reconstruction of what the Nabataeans did to control Wadi Musa between the 1st century BC and the beginning of the 1st century AD [1]. The entrance also contains the remnants of a monumental arch, of which only the two abutments and some hewn stones of the arch itself have survived [1].\""}, {"source": "remediation_change_log:114843", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_name ''1 - 500 AD'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:114844", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_start ''1'' -> ''-100''"}, {"source": "remediation_change_log:114845", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: site_type ''Archaeological site'' -> ''Natural feature''"}, {"source": "remediation_change_log:144673", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''/data/images/wiki/22aa305a/hero.webp'' -> ''/data/images/wiki/22aa305a/24 Petra (19) (13251279145).webp''"}, {"source": "remediation_change_log:308504", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/22aa305a/24 Petra (19) (13251279145).webp'' -> ''/data/images/wiki/22aa305a/Petra_First_Glimpse.webp''"}]'::jsonb),
    ('22aa305a-3ecf-454e-a643-3e08dbbd2e14'::uuid, 'rarity_score', '52', '49', 'card-stats-2026-11-05-rollback:22aa305a-3ecf-454e-a643-3e08dbbd2e14:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''49'' restored on al-Siq', '9245c6e5a67d44bbb20cf3860056f5ec', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 52 from mystery 10, cultural_influence 10"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82284", "url": "remediation_change_log", "quote": "phase4:p4-2057:chunk-0001: description ''The Siq (Arabic: السِّق, \"gorge\") is the principal entrance to the ancient Nabatean city of Petra in southern Jordan [1]. This dim, narrow sandstone gorge winds approximately 1.2 km (0.7 mi) through rose-red cliffs, creating one of archaeology\\''s most dramatic pedestrian approaches [1][2]. The passage ends at Al-Khazneh, Petra\\''s most elaborate ruin, which greets visitors with its intricate carved facade [1]. A wide valley outside leading to the Siq is known as the Bab as-Sīq [1].'' -> \"The Siq is the main entrance to the ancient Nabatean city of Petra in southern Jordan [1]. Also known as Siqit, it is a dim, narrow gorge (in some points no more than 3 metres (10 ft) wide) and winds its way approximately 1.2 kilometres and ends at Petra''s most elaborate ruin, Al-Khazneh [1]. Unlike slot canyons such as Antelope Canyon in the American Southwest, which are directly shaped by water, the Siq is a natural geological fault split apart by tectonic forces; only later was it worn smooth by water [1]. The walls that enclose the Siq stand between 91–182 metres in height [1]. The entrance to the Siq contains a huge dam designed to bar the mouth of the Siq and reroute the waters of Wadi Musa [1]. The dam is a fairly true reconstruction of what the Nabataeans did to control Wadi Musa between the 1st century BC and the beginning of the 1st century AD [1]. The entrance also contains the remnants of a monumental arch, of which only the two abutments and some hewn stones of the arch itself have survived [1].\""}, {"source": "remediation_change_log:114843", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_name ''1 - 500 AD'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:114844", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_start ''1'' -> ''-100''"}, {"source": "remediation_change_log:114845", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: site_type ''Archaeological site'' -> ''Natural feature''"}, {"source": "remediation_change_log:144673", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''/data/images/wiki/22aa305a/hero.webp'' -> ''/data/images/wiki/22aa305a/24 Petra (19) (13251279145).webp''"}, {"source": "remediation_change_log:308504", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/22aa305a/24 Petra (19) (13251279145).webp'' -> ''/data/images/wiki/22aa305a/Petra_First_Glimpse.webp''"}]'::jsonb),
