    ('24aa135d-4714-47f5-96c0-d58f0bc04b6f'::uuid, 'mystery', '7', '6', 'card-stats-2026-11-05-rollback:24aa135d-4714-47f5-96c0-d58f0bc04b6f:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Chiapa de Corzo', '7d8248464020a9b5a03cec4c8f4e53c7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (None, ''1500 - 500 BC'') is shared by 7 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:32153", "url": "remediation_change_log", "quote": "2026-09-23_source-url-split-wave4: source_url ''https://www.megalithic.co.uk/article.php?sid=26242\\nhttps://en.wikipedia.org/wiki/Chiapa_de_Corzo_(Mesoamerican_site)'' -> ''https://www.megalithic.co.uk/article.php?sid=26242''"}, {"source": "remediation_change_log:95280", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: site_type ''Pyramid complex'' -> None"}, {"source": "remediation_change_log:170054", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4216:chunk-0001: description ''Chiapa de Corzo is a major Mesoamerican archaeological site in Chiapas, Mexico, settled by the Zoque people, descendants of Mixe-Zoquean speakers from the Olmec tradition. Rising to prominence c. 700-500 BCE, it became one of the earliest linearly planned towns in Mesoamerica, reaching 70 hectares. In 2010, archaeologists discovered a 2,700-year-old pyramidal tomb in Mound 11 containing a couple adorned with nearly 4,000 jade, pearl shell, and amber pieces -- the oldest such tomb in Mesoamerica, predating those at Tikal by 600 years. The site also features an E-Group astronomical complex dating to 900-800 BCE.'' -> ''Chiapa de Corzo is a major Mesoamerican archaeological site in Chiapas, Mexico, settled by the Zoque people, descendants of Mixe-Zoquean speakers from the Olmec tradition [1] [2] [3]. Rising to prominence c. 700-500 BCE, it became one of the earliest linearly planned towns in Mesoamerica, reaching 70 hectares [1] [2]. In 2010, archaeologists discovered a 2,700-year-old pyramidal tomb in Mound 11 -- the oldest such tomb in Mesoamerica, predating those at Tikal by 600 years [1] [2]. The site also features an E-Group astronomical complex dating to 900-800 BCE [2].''"}]'::jsonb),
