    ('257fe33f-735b-46d0-9cb6-83ca0e03937f'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:257fe33f-735b-46d0-9cb6-83ca0e03937f:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Threestoneburn Stone Circle', 'd912d26f9fe201bf3ddea9fd16768c5f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2900"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44051", "url": "remediation_change_log", "quote": "phase4:p4-0086:chunk-0001: description ''A late Neolithic or early Bronze Age stone circle near Ilderton in Northumberland, set on a promontory overlooking the confluence of Threestone Burn and a tributary. The oval ring measures 36 by 30 metres and comprises 16 stones of local pink granite spaced about 5.5 metres apart, though only four remain upright. George Tate excavated the site in the 19th century, finding charcoal spreads and a worked flint. A probable double stone row extends at least 60 metres northward from the circle. The site is a scheduled monument within Threestoneburn Wood.'' -> ''Threestoneburn Stone Circle is an archaeological site, a stone circle near the village of Ilderton and about 5 miles south of Wooler, in Northumberland, England [1]. The circle, of the late Neolithic or early Bronze Age, is situated in a large clearing in the modern afforestation of Threestoneburn Wood, formerly overlooking a spacious valley to the east [1]. It is on a slight promontory near the confluence of Threestone Burn and one of its tributaries [1]. Its dimensions are 36 metres north-west to south-east by 30 metres north-east to south-west [1]. There are 16 stones of local pink granite, set about 5.5 metres apart; a larger gap on the east side is thought to be an original entrance [1]. Four of these are upright, with heights 0.7 to 1.3 metres; the rest are recumbent [1]. A thick layer of peat was found above the ground surface [1]. A flint tool was found, and spreads of charcoal which may be the traces of fire-rituals [1].''"}, {"source": "remediation_change_log:95294", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:95295", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:144713", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/5/52/Threestoneburn_Stone_Circle_-_geograph.org.uk_-_1836990.jpg'' -> ''/data/images/wiki/257fe33f/hero.webp''"}, {"source": "remediation_change_log:246911", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:246912", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_start None -> ''-4000''"}, {"source": "remediation_change_log:347206", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:347207", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-4000'' -> ''-2900''"}]'::jsonb),
