    ('25ba654d-b16a-44bc-9022-459aeb272ca2'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:25ba654d-b16a-44bc-9022-459aeb272ca2:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Al-Rabadha', 'd85505dde278b1eae772c74528f09843', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82350", "url": "remediation_change_log", "quote": "phase4:p4-2059:chunk-0001: description ''Al-Rabadha (also Al-Rabatha) is an early Islamic archaeological site in Saudi Arabia, situated approximately 200 km northeast of Medina along the historic Darb Zubaydah pilgrimage route from Kufa to Mecca [1][2]. Archaeological excavations conducted by King Saud University have revealed important information about early Islamic urban culture and housing [1]. The site is traditionally associated with Abu Dharr al-Ghifari, a companion of Prophet Muhammad who spent his final years and died at this location [3].'' -> ''Al-Rabadha is a settlement in Saudi Arabia located some 200 km to the north-east of Medina on the pilgrim route from Kufa to Mecca, known as Darb Zubaydah [1]. The archaeological excavations directed by King Saud University have shown that Al-Rabadha yields important information for the early phases of Islamic culture [1]. The town is also known as the place where Abu Dharr al-Ghifari spent his last years and died [1]. The excavations at Al-Rabadha give a good insight into urban housing in the Early Islamic Period [1]. The site is dominated by a palace structure, consisting of 13 rooms all with doors opening on a central courtyard [1]. Each room is likely to have served a different purpose, with evidence for ovens, grain storage and a furnace for glass-making found in separate areas [1]. A more typical house from the site is similar in its design, but smaller in area, with divided rooms averaging 3x2m [1]. In contrast with Western Europe, timber is not used in construction, with all houses being made from sun-dried mud brick and having stone foundations [1].''"}, {"source": "remediation_change_log:95296", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:95297", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''1'' -> None"}, {"source": "remediation_change_log:144720", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''/data/images/wiki/25ba654d/hero.webp'' -> ''/data/images/wiki/25ba654d/Al-Rabadha_Jar.webp''"}, {"source": "remediation_change_log:246913", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:246914", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_start None -> ''1''"}, {"source": "remediation_change_log:347208", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:347209", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''1'' -> None"}]'::jsonb),
