    ('262b6a28-de86-4e63-bdba-398a67236618'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:262b6a28-de86-4e63-bdba-398a67236618:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Brisworthy Stone Circle', 'd9ddcb5ef6f38cf8ec068a6825b1536e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80732", "url": "remediation_change_log", "quote": "phase4:p4-2006:chunk-0001: description ''Brisworthy Stone Circle is a Bronze Age stone circle on Dartmoor, Devon, situated in the Upper Plym Valley about 300 m from Ringmoor Stone Row. The slightly oval ring has a diameter of approximately 24 m and retains 24 upright stones, probably half the original number, all broad rather than tall at less than 1 m high. Dartmoor stone circles are dated mainly to the late 3rd or 2nd millennium BC. By 1909 most stones had fallen; they were re-erected that year and a trial excavation yielded charcoal and a rough flint flake. The circle is a Scheduled Monument.'' -> ''Brisworthy stone circle is a stone circle on Dartmoor, Devon [1]. It is located three miles east of the A386, northeast of the village of Shaugh Prior [1]. It is three hundred metres from Ringmoor stone row and cairn circle, and is one of the archaeological sites found in the Upper Plym Valley [1]. The stone circle is a slight oval shape with a diameter of around 24 metres [1]. It consists of 24 upright stones which are probably only half the original number [1]. The stones are broad rather than tall, and are less than 1 metre tall [1]. Prior to 1909 most of the stones had fallen [1]. It was restored in that year, and a trial excavation is said to have yielded a small amount of charcoal and one rough flint flake [1].''"}, {"source": "remediation_change_log:95305", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:95306", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:246917", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:246918", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_start None -> ''-4000''"}, {"source": "remediation_change_log:308567", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/262b6a28/hero.webp'' -> ''/data/images/wiki/262b6a28/Stone Circle at Brisworthy - geograph.org.uk - 9820.webp''"}, {"source": "remediation_change_log:347212", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:347213", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
