    ('2753c6bb-1b90-4d49-8e59-b037bf1df930'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:2753c6bb-1b90-4d49-8e59-b037bf1df930:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Abrigo de la Quebrada', '146af083671ce102c40c3ae65ed877a4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29107", "url": "remediation_change_log", "quote": "phase3:batch-0239:chunk-0001: period_start ''1'' -> ''-48800''"}, {"source": "remediation_change_log:30367", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1 - 500 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:33455", "url": "remediation_change_log", "quote": "phase4:p4-0019:chunk-0001: description ''Abrigo de la Quebrada is a Middle Palaeolithic rock shelter in Chelva, Valencia, Spain, situated at 728 metres elevation on the left bank of the Barranco de Ahillas ravine [1][2]. The shelter is 38 metres long and 2 to 9 metres deep, containing nine archaeological levels spanning MIS 5 to MIS 3, with the oldest levels dated to approximately 80,000-83,000 years ago [1][2]. Excavations from 2007 to 2015 revealed repeated short-duration Neanderthal occupations, primarily from spring to autumn, focused on hunting medium and large ungulates including ibex, equids and cervids [1][2]. Phytolith analysis shows Neanderthals collected grasses and other plants for fire production and possibly bedding [3]. Flint sourcing studies demonstrate that identical raw materials appear at sites up to 120 km apart, indicating north-south mobility along the Mediterranean coast of central Iberia [4].'' -> ''The Abrigo de la Quebrada is an archaeological site in the municipality of Chelva, in the Spanish Province of Valencia, ca. 65 km northwest of the city of Valencia [1]. It shows evidence of frequent occupation by Neanderthals [1]. The site is on the left bank of a small ravine, the Barranco de Ahillas; it is a rock shelter between 2 and 9 meters deep, and 38 meters long, facing the northwest [1]. Because of the lack of direct sunshine and its exposure, the site was occupied only from June to October, according to Phytoliths and other evidence, including the reuse and resharpening of stone tools [1]. The deposit is around 3 meters thick, and is divided into eight units by archaeologists [1]. Flint tools found at the site give evidence of extensive traffic of Neanderthal populations in the area [1]. While much of the flint was procured locally, some of it came from over 100 kilometers away; knapping was done also by way of the Levallois technique [1].''"}, {"source": "remediation_change_log:95326", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:95327", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''-48800'' -> None"}, {"source": "remediation_change_log:246935", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:246936", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_start None -> ''-126000''"}, {"source": "remediation_change_log:324979", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/2753c6bb/hero.webp'' -> ''/data/images/wiki/2753c6bb/Vista general Quebrada.webp''"}]'::jsonb),
    ('2753c6bb-1b90-4d49-8e59-b037bf1df930'::uuid, 'rarity_score', '29', '32', 'card-stats-2026-11-05-rollback:2753c6bb-1b90-4d49-8e59-b037bf1df930:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''32'' restored on Abrigo de la Quebrada', '146af083671ce102c40c3ae65ed877a4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 29 from mystery 3, cultural_influence 9"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29107", "url": "remediation_change_log", "quote": "phase3:batch-0239:chunk-0001: period_start ''1'' -> ''-48800''"}, {"source": "remediation_change_log:30367", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1 - 500 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:33455", "url": "remediation_change_log", "quote": "phase4:p4-0019:chunk-0001: description ''Abrigo de la Quebrada is a Middle Palaeolithic rock shelter in Chelva, Valencia, Spain, situated at 728 metres elevation on the left bank of the Barranco de Ahillas ravine [1][2]. The shelter is 38 metres long and 2 to 9 metres deep, containing nine archaeological levels spanning MIS 5 to MIS 3, with the oldest levels dated to approximately 80,000-83,000 years ago [1][2]. Excavations from 2007 to 2015 revealed repeated short-duration Neanderthal occupations, primarily from spring to autumn, focused on hunting medium and large ungulates including ibex, equids and cervids [1][2]. Phytolith analysis shows Neanderthals collected grasses and other plants for fire production and possibly bedding [3]. Flint sourcing studies demonstrate that identical raw materials appear at sites up to 120 km apart, indicating north-south mobility along the Mediterranean coast of central Iberia [4].'' -> ''The Abrigo de la Quebrada is an archaeological site in the municipality of Chelva, in the Spanish Province of Valencia, ca. 65 km northwest of the city of Valencia [1]. It shows evidence of frequent occupation by Neanderthals [1]. The site is on the left bank of a small ravine, the Barranco de Ahillas; it is a rock shelter between 2 and 9 meters deep, and 38 meters long, facing the northwest [1]. Because of the lack of direct sunshine and its exposure, the site was occupied only from June to October, according to Phytoliths and other evidence, including the reuse and resharpening of stone tools [1]. The deposit is around 3 meters thick, and is divided into eight units by archaeologists [1]. Flint tools found at the site give evidence of extensive traffic of Neanderthal populations in the area [1]. While much of the flint was procured locally, some of it came from over 100 kilometers away; knapping was done also by way of the Levallois technique [1].''"}, {"source": "remediation_change_log:95326", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:95327", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''-48800'' -> None"}, {"source": "remediation_change_log:246935", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:246936", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_start None -> ''-126000''"}, {"source": "remediation_change_log:324979", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/2753c6bb/hero.webp'' -> ''/data/images/wiki/2753c6bb/Vista general Quebrada.webp''"}]'::jsonb),
