    ('277be4f6-02bc-4dd4-b1a2-1898e529faf9'::uuid, 'mystery', '3', '10', 'card-stats-2026-11-05-rollback:277be4f6-02bc-4dd4-b1a2-1898e529faf9:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Gournia', '42fcd010a963896e643eb25d1664c082', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''3000 - 1500 BC'') is shared by 130 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33459", "url": "remediation_change_log", "quote": "phase4:p4-0019:chunk-0001: description ''Gournia is a Minoan town and palace complex in Lasithi, eastern Crete, often called the \"Pompeii of Crete\" for its exceptional preservation. It flourished from roughly 1550-1450 BC, was destroyed by an earthquake around 1450 BC, and finally abandoned about 1200 BC. First excavated by American archaeologist Harriet Boyd-Hawes (1901-1904), the site revealed about 50 houses, a cobbled street system, a central court, a small hilltop palace, and a snake goddess temple. Gournia served as a regional trade hub with overseas connections to the Aegean and Near East, and as the palatial administrative center of the Mirabello region.'' -> ''Gournia is the site of a Minoan palace complex in the Lasithi regional unit on the island of Crete, Greece [1]. Its modern name originated from the many stone troughs that are at the site and its original name for the site is unknown [1]. Harriet Boyd Hawes first excavated the Minoan village for three field seasons in 1901, 1903 and 1904 [1]. Boyd and her team were able to expose nearly the entire town, uncovering sixty houses, the cemetery, a road system connecting everything and a central building which she called \"the palace\" [1]. The town itself is centered around the palatial complex which is located on the central-West side of the town [1]. During the Middle Minoan IB period (1925–1875 B.C.E.) substantial construction began which was later destroyed in the Middle Minoan II period (1875–1700 B.C.E.) [1]. Rebuilding occurred in the Middle Minoan III period, which included the palace complex [1].''"}, {"source": "remediation_change_log:95328", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: site_type ''Castle/palace'' -> ''Town''"}, {"source": "remediation_change_log:145351", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''/data/images/wiki/277be4f6/hero.webp'' -> ''/data/images/wiki/277be4f6/Gournia_024.webp''"}, {"source": "remediation_change_log:308600", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/277be4f6/Gournia_024.webp'' -> ''/data/images/wiki/277be4f6/Gournia_Minoan_Palace_1.webp''"}, {"source": "remediation_change_log:355595", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Town'' -> ''City/town/settlement''"}]'::jsonb),
