    ('280f2b7d-4978-4352-896d-bcbb03837d3e'::uuid, 'antiquity', '1', '3', 'card-stats-2026-11-05-rollback:280f2b7d-4978-4352-896d-bcbb03837d3e:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Inti Watana, Ayacucho', '4498b2b4264c87add4f68f0c008ea279', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 1 from period_start 1438"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27901", "url": "remediation_change_log", "quote": "phase3:batch-0028:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:33461", "url": "remediation_change_log", "quote": "phase4:p4-0019:chunk-0001: description ''Inca elite retreat and ceremonial complex at 3,126 m elevation beside Lake Pumaqucha (\"Puma Lake\" in Quechua) near Vischongo, Vilcas Huaman Province. The 3,000 m2 complex features an Intihuatana sundial stone used for astronomical observation, a palace built for Inca nobility, a semicircular defensive tower (Torreon), a Sun Gate, and Inca baths with a 13-angled stone still standing after 500+ years. Mortarless stone construction and a hydraulic canal system feeding the lake remain functional to this day. Declared National Cultural Heritage of Peru in 2001.'' -> ''Inti Watana, Intiwatana or Pumaqucha is an archaeological site in Peru [1]. It is located in the Ayacucho Region, Vilcas Huamán Province, Vischongo District, at the lake Pumaqucha [1]. The site was declared a National Cultural Heritage of Peru by Resolución Directoral No. Nº 751/INC on July 27, 2001  [1].''"}, {"source": "remediation_change_log:95342", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:95343", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''1'' -> None"}, {"source": "remediation_change_log:145363", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''/data/images/wiki/280f2b7d/hero.webp'' -> ''/data/images/wiki/280f2b7d/Pumacocha Archaeological site - bath.webp''"}, {"source": "remediation_change_log:246943", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:246944", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_start None -> ''1''"}, {"source": "remediation_change_log:308615", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/280f2b7d/Pumacocha Archaeological site - bath.webp'' -> ''/data/images/wiki/280f2b7d/Pumacocha_Archaeological_site_-_doorway.webp''"}, {"source": "remediation_change_log:347235", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''1 - 500 AD'' -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:347236", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''1'' -> ''1438''"}]'::jsonb),
