    ('291542d5-8a09-4599-bd7a-715f45e432a1'::uuid, 'antiquity', '7', '10', 'card-stats-2026-11-05-rollback:291542d5-8a09-4599-bd7a-715f45e432a1:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Massleberg 1 Rock Art', 'bd0ccf2425d8eb692cd0a94c64995c0c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80738", "url": "remediation_change_log", "quote": "phase4:p4-2006:chunk-0001: description ''The Massleberg 1 rock carvings (RAA Skee 614:1) are located near Stromstad in Bohuslan, southwestern Sweden, about 80 metres from the Massleberg grave field. Dating to the Nordic Bronze Age (c. 1500-500 BC), the rock face displays partially overlapping carvings of ships, ithyphallic men bearing axes and spears, footprints, animals, cup marks, and a sun cross. A central hunting scene relates to the ships and footprints, possibly reflecting fertility rites with figures interpreted as gods transforming into animals. The site is part of a broader archaeological landscape including passage graves and barrow cemeteries.'' -> ''The Massleberg 1 rock art are located near Strömstad in Bohuslän, in south-western Sweden, some 80 metres from the Massleberg grave field [1]. On a rock face, several partially overlapping carvings from the Bronze Age can be seen [1]. Surrounded by numerous cup marks, the carvings depict Ithyphallic men, some bearing or raising axes, spears, and shields; Footprints; a lattice pattern; a sun cross; small and large ships; animals (deer and dogs), as well as various other images [1]. Small strokes in the rowing ship symbolise the crew members [1]. The \"hook\" on the ship image indicates a Lur [1]. The unusual image of a man carrying a ship is almost exactly the same as the depiction of shipbearer on another rock face in Bohuslän [1].''"}, {"source": "remediation_change_log:95367", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:95368", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:246951", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:246952", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_start None -> ''-10000''"}, {"source": "remediation_change_log:324983", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/291542d5/hero.webp'' -> ''/data/images/wiki/291542d5/Strömstad Massleberg Skee 614-1 IMG 8921 ID 10159506140001.webp''"}, {"source": "remediation_change_log:347239", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''< 4500 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:347240", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-10000'' -> ''-2500''"}]'::jsonb),
