    ('29bbdfce-7b18-4530-b668-8a2fb289694b'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:29bbdfce-7b18-4530-b668-8a2fb289694b:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Qillqatani', '916739578f67d9b301f7ae37b97da850', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Rock art'', ''< 4500 BC'') is shared by 29 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27836", "url": "remediation_change_log", "quote": "phase3:batch-0016:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:33499", "url": "remediation_change_log", "quote": "phase4:p4-0020:chunk-0001: description ''A rock shelter at 4,400 m elevation along the Rio Chila in the southwestern Lake Titicaca Basin, first systematically excavated by Aldenderfer in 1990. Archaeologists identified 36 cultural strata spanning from the Middle Archaic (c. 5500 BC) through the Late Horizon, making it one of the most deeply stratified sites in the region. The sequence reveals a pivotal transition from hunting and gathering to a pastoral economy between levels 25 and 24, with level 24 representing the first residential occupation. The shelter also features elaborate rock art panels and yielded significant Chivay obsidian assemblages.'' -> ''Qillqatani is an archaeological site in Peru [1]. It is located above the Rio Chila, in the Puno Region, El Collao Province, Santa Rosa District, at a height of about 5 m above the riverbed [1]. Qillqatani is known for its elaborate rock art panels [1]. Qillqatani is the first archaeological site in the Lake Titicaca basin to be systematically excavated [1]. Archaeologists have identified 36 cultural strata at the site [1]. From 7500 to 4000 BP, Qillqatani was inhabited by hunter-gatherers as a seasonal campsite [1]. These early occupants hunted mostly camelids, and some deer [1]. From 3660 BP onwards, Qillqatani was inhabited by pastoralist camelid-herders who built houses and began to occupy the site long-term [1].''"}, {"source": "remediation_change_log:35703", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:95385", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:95386", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''-5500'' -> None"}, {"source": "remediation_change_log:95387", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: site_type ''City/town/settlement'' -> ''Rock art''"}, {"source": "remediation_change_log:235669", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:235670", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_start None -> ''-7000''"}]'::jsonb),
