    ('2a4b62ce-c1d8-4def-ba57-ec8c77edb502'::uuid, 'mystery', '4', '5', 'card-stats-2026-11-05-rollback:2a4b62ce-c1d8-4def-ba57-ec8c77edb502:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Nine Ladies Stone Circle', '09b2b522940abc5f20bbec62f580b853', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Stone circle'', ''3000 - 1500 BC'') is shared by 57 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28210", "url": "remediation_change_log", "quote": "phase3:batch-0094:chunk-0001: period_start ''-4500'' -> ''-3300''"}, {"source": "remediation_change_log:35706", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-3300'' -> ''-4500''"}, {"source": "remediation_change_log:82508", "url": "remediation_change_log", "quote": "phase4:p4-2063:chunk-0001: description ''The Nine Ladies is a stone circle on Stanton Moor in Derbyshire, East Midlands, England. Built during the Late Neolithic to Early Bronze Age (3300–900 BCE), it consists of ten Millstone Grit stones forming a circle 10.8 metres in diameter. A single monolith, the King Stone, stands to the southwest. The Nine Ladies is part of a tradition of stone circle construction that spread throughout Britain, Ireland, and Brittany. The purpose of such monuments remains unknown, though archaeologists speculate the stones represented supernatural entities for their builders.'' -> ''The Nine Ladies is a stone circle on Stanton Moor in Derbyshire in the English East Midlands [1]. The Nine Ladies is part of a tradition of stone circle construction that spread throughout much of Britain, Ireland, and Brittany during the Late Neolithic and Early Bronze Ages [1]. The Nine Ladies stands on the northern end of Stanton Moor, an area of heathland in the Peak District [1]. It is at a height of between 297 and 298 metres OD [1]. The Nine Ladies stone circle measures 10.8 m in diameter, and is located on ground which slopes downward towards the east to northeast [1]. A report from 1907 noted that there were nine stones in the circle, all but one of which stood upright [1]. The stones are made from a millstone grit sourced locally, a type of medium-grained sandstone [1]. The antiquarian Hayman Rooke noted the existence of the Nine Ladies, which he considered \"a Druid temple,\" in a 1782 article about the heritage of Stanton Moor published in the journal Archaeologia [1].''"}, {"source": "remediation_change_log:114895", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:114896", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_start ''-4500'' -> ''-2000''"}, {"source": "remediation_change_log:145451", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/b/b7/Nine_Ladies_Stone_Circle_on_Stanton_Moor.jpg'' -> ''/data/images/wiki/2a4b62ce/Nine Ladies Stone Circle Derbyshire.webp''"}, {"source": "remediation_change_log:308665", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/2a4b62ce/Nine Ladies Stone Circle Derbyshire.webp'' -> ''/data/images/wiki/2a4b62ce/Nine_Ladies_Stone_Circle_on_Stanton_Moor.webp''"}]'::jsonb),
