iod.'' -> None"}, {"source": "remediation_change_log:246977", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:246978", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_start None -> ''1''"}, {"source": "remediation_change_log:338487", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4325:chunk-0001: description None -> ''Svileuva is a Serbian village in the Koceljeva municipality of the Mačva District [1]. The village counted 1,464 inhabitants in 2011 [1]. The Svileuva area is first mentioned by Roman sources from the 1st to the 4th century AD in the Sirmium district [1]. Svileuva counts as a significant archaeological site of the Roman imperial period [1]. An excavation after the Second World War brought 21,000 Roman coins to light [1].''"}, {"source": "remediation_change_log:347265", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:347266", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''1'' -> None"}]'::jsonb),
