    ('2c36db5a-566a-4bda-ad03-f14936f83eb8'::uuid, 'antiquity', '8', '10', 'card-stats-2026-11-05-rollback:2c36db5a-566a-4bda-ad03-f14936f83eb8:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Deer Valley Petroglyph Preserve', '97bb51d95cf9d40e8130ab7cc41d0906', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -3050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82548", "url": "remediation_change_log", "quote": "phase4:p4-2064:chunk-0001: description \"The Deer Valley Petroglyph Preserve is a 47-acre nature preserve in Phoenix, Arizona, featuring over 1,500 Hohokam, Patayan, and Archaic petroglyphs carved onto 500 basalt boulders [1]. The rock art dates between 500 and 5,000 years old [1]. In 1980, the US Army Corps of Engineers commissioned archaeologist J. Simon Bruder to conduct excavations before construction of the Adobe Dam at Hedgpeth Hills [1]. The site was listed on the National Register of Historic Places in 1984 and is now operated by Arizona State University''s School of Human Evolution and Social Change [1].\" -> ''The Deer Valley Petroglyph Preserve, formerly known as the Deer Valley Rock Art Center, is a 47-acre nature preserve featuring over 1500 Hohokam, Patayan, and Archaic petroglyphs visible on 500 basalt boulders in the Deer Valley area of Phoenix, Arizona [1]. The petroglyphs are between 500 and 5,000 years old [1]. The site was listed on the National Register of Historic Places in 1984, and it was also listed with the Phoenix Points of Pride [1]. The Museum of Northern Arizona, in a project directed by J. Simon Bruder, conducted extensive fieldwork and discovered a wide variety of features and artifacts [1]. Their fieldwork lasted three months and an archaeological report was published [1].''"}, {"source": "remediation_change_log:114919", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:114920", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:145574", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''/data/images/wiki/2c36db5a/hero.webp'' -> ''/data/images/wiki/2c36db5a/Phoenix-Deer_Valley_Rock_Art_Center-_Petroglyph_-_2.webp''"}, {"source": "remediation_change_log:246983", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:246984", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s004: period_start None -> ''-10000''"}, {"source": "remediation_change_log:308701", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/2c36db5a/Phoenix-Deer_Valley_Rock_Art_Center-_Petroglyph_-_2.webp'' -> ''/data/images/wiki/2c36db5a/Phoenix-Deer_Valley_Rock_Art_Center-_Petroglyph_-_3.webp''"}, {"source": "remediation_change_log:347271", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''< 4500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:347272", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-10000'' -> ''-3050''"}]'::jsonb),
