    ('2c4d2e4b-57b5-4788-8ba6-22955dac6448'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:2c4d2e4b-57b5-4788-8ba6-22955dac6448:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Roman Theatre of Arles', 'faed5b074f4dc501366bf664fc100421', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Theatre'', ''500 BC - 1 AD'') is shared by 28 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27852", "url": "remediation_change_log", "quote": "phase3:batch-0017:chunk-0004: site_type ''Megalithic structures'' -> ''Theatre''"}, {"source": "remediation_change_log:33515", "url": "remediation_change_log", "quote": "phase4:p4-0020:chunk-0001: description ''A 1st-century BC/AD Roman theatre in Arles, Provence, built during the reign of Augustus. It originally featured 33 rows of seating for 8,000 spectators. Part of the UNESCO World Heritage Site \"Arles, Roman and Romanesque Monuments\" since 1981. Quarried extensively during the Middle Ages, today only the stage area, orchestra, partial seating rows, and two standing columns survive. The famous Venus d\\''Arles statue, found here, is now displayed in the Louvre. The site hosts the annual Rencontres d\\''Arles photography festival.'' -> ''The Roman Theatre of Arles is a 1st-century Roman theatre, built during the reign of Caesar Augustus [1]. It is located next to the Arles Amphitheatre in the city of Arles, Provence, France [1]. In Roman times, the theatre had 33 rows of steps and could seat 8,000 people [1]. It was as large as the Roman Theatre of Orange, although much less well-preserved [1]. During the Middle Ages, the theatre was used as a quarry, with the stone pillaged to build the city wall and other buildings [1]. Today, only the stage area, orchestra section, seating rows, and two columns survive [1]. The Venus of Arles, a famous Roman statue made of marble, was found in pieces at the Roman theatre in 1651 [1].''"}, {"source": "remediation_change_log:96315", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_name ''1 - 500 AD'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:96316", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_start ''1'' -> ''-40''"}, {"source": "remediation_change_log:145577", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/e/e9/Arles%2C_teatro_romano%2C_02.jpg'' -> ''/data/images/wiki/2c4d2e4b/Arles (13) Rue de la Calade Théâtre gallo-romain 584.webp''"}, {"source": "remediation_change_log:308707", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/2c4d2e4b/Arles (13) Rue de la Calade Théâtre gallo-romain 584.webp'' -> ''/data/images/wiki/2c4d2e4b/Arles,_teatro_romano,_02.webp''"}]'::jsonb),
