    ('2cc719f3-4797-4137-a5b2-7b41d15b8d3a'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:2cc719f3-4797-4137-a5b2-7b41d15b8d3a:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Roman Ovens of the Fornaca', '86b3d2293d30ebf49fc59bb32ec61473', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Archaeological site'', ''1 - 500 AD'') is shared by 15 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29668", "url": "remediation_change_log", "quote": "phase3:batch-0323:chunk-0001: site_type ''Megalithic structures'' -> ''Archaeological site''"}, {"source": "remediation_change_log:82576", "url": "remediation_change_log", "quote": "phase4:p4-2065:chunk-0001: description ''Ancient Roman kilns at the Fornaca archaeological site in Vilassar de Dalt, Catalonia, Spain, dedicated to industrial production of ceramic materials from the 1st to 3rd centuries AD. The site comprises three circular kilns: two with double chambers (combustion and cooking) and one with a single chamber. Construction materials and dolia (large storage jars) were produced here. Dated through typological analysis and magnetic property studies, the Fornaca kilns are considered among the best-preserved Roman industrial sites in Catalonia. The name Fornaca, first documented in 1290, derives from the Latin word for oven.'' -> ''The Roman ovens of the Fornaca are ancient Roman structures in the archaeological site of Fornaca at Vilassar de Dalt, Catalonia [1]. They were used for the industrial production of large ceramic materials [1]. Based on their typology, the materials found in the excavation, and study of their magnetic properties, archaeologists have dated the ovens 1 and 2 to the 1st and 2nd centuries AD [1]. The name Fornaca, documented for the first time in 1290 at the castle of Speculum Vilassar, gives clues about the antiquity of the area of industrial production [1].''"}, {"source": "remediation_change_log:145605", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Catalonia_VilassarDeDalt_FornsRomansFornaca_Forns1I2_B.JPG/400px-Catalonia_VilassarDeDalt_FornsRomansFornaca_Forns1I2_B.JPG'' -> ''/data/images/wiki/2cc719f3/hero.webp''"}]'::jsonb),
    ('2cc719f3-4797-4137-a5b2-7b41d15b8d3a'::uuid, 'rarity_score', '40', '37', 'card-stats-2026-11-05-rollback:2cc719f3-4797-4137-a5b2-7b41d15b8d3a:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''37'' restored on Roman Ovens of the Fornaca', '86b3d2293d30ebf49fc59bb32ec61473', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 40 from mystery 6, cultural_influence 10"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29668", "url": "remediation_change_log", "quote": "phase3:batch-0323:chunk-0001: site_type ''Megalithic structures'' -> ''Archaeological site''"}, {"source": "remediation_change_log:82576", "url": "remediation_change_log", "quote": "phase4:p4-2065:chunk-0001: description ''Ancient Roman kilns at the Fornaca archaeological site in Vilassar de Dalt, Catalonia, Spain, dedicated to industrial production of ceramic materials from the 1st to 3rd centuries AD. The site comprises three circular kilns: two with double chambers (combustion and cooking) and one with a single chamber. Construction materials and dolia (large storage jars) were produced here. Dated through typological analysis and magnetic property studies, the Fornaca kilns are considered among the best-preserved Roman industrial sites in Catalonia. The name Fornaca, first documented in 1290, derives from the Latin word for oven.'' -> ''The Roman ovens of the Fornaca are ancient Roman structures in the archaeological site of Fornaca at Vilassar de Dalt, Catalonia [1]. They were used for the industrial production of large ceramic materials [1]. Based on their typology, the materials found in the excavation, and study of their magnetic properties, archaeologists have dated the ovens 1 and 2 to the 1st and 2nd centuries AD [1]. The name Fornaca, documented for the first time in 1290 at the castle of Speculum Vilassar, gives clues about the antiquity of the area of industrial production [1].''"}, {"source": "remediation_change_log:145605", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Catalonia_VilassarDeDalt_FornsRomansFornaca_Forns1I2_B.JPG/400px-Catalonia_VilassarDeDalt_FornsRomansFornaca_Forns1I2_B.JPG'' -> ''/data/images/wiki/2cc719f3/hero.webp''"}]'::jsonb),
