    ('2d61ebea-06e2-4163-b610-a1a5187ed6d6'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:2d61ebea-06e2-4163-b610-a1a5187ed6d6:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Yelland Stone Rows', 'e128fa25743049621b634a4ee931b1ba', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2550"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82586", "url": "remediation_change_log", "quote": "phase4:p4-2065:chunk-0001: description ''A prehistoric double stone row of approximately 22 small standing stones extending 34.5 metres across the tidal mudflats of the River Taw estuary in Devon, England. Excavations in the 1930s uncovered nine pairs of stones or sockets alongside flint tools and evidence of Mesolithic, Neolithic, and Early Bronze Age occupation. A nationally important Scheduled Ancient Monument, the stones progressively vanished beneath estuarine silt after the 1980s closure of a nearby power station altered sediment flow. By the 1990s no stones remained visible. In 2018, Historic England funded a geophysical survey to locate the buried alignment.'' -> ''The Yelland Stone Rows is a prehistoric monument of two parallel rows of small standing stones located on the tidal mudflats of the River Taw estuary, in Devon [1]. The stone alignment consists of at least 18 sandstone pieces, at least 30 cm high and 22 cm wide, positioned in a pair of parallel rows, up to 2.5 m apart [1]. The Yelland Stone Rows were excavated by archaeologist, E. H. Rogers in the 1930s [1]. A partial excavation uncovered eighteen stones arranged into nine standing pairs [1]. Near the stones, Rogers discovered flint tools and evidence indicating human occupation of the site during the Mesolithic, Neolithic and Early Bronze Age eras [1]. In 1932, the tallest standing stone measured 40cm in height above the silt, and the rows were determined to be 56m in length [1]. By 1983, only seven stones were visible above the mud and the remaining stones disappeared from view over the next several years [1].''"}, {"source": "remediation_change_log:96330", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:96331", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:145622", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/4/45/Location_of_Yelland_Stone_Rows.jpg'' -> None"}, {"source": "remediation_change_log:247331", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:247332", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_start None -> ''-4000''"}, {"source": "remediation_change_log:321283", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-001: thumbnail_url None -> ''/data/images/wiki/2d61ebea/hero.webp''"}, {"source": "remediation_change_log:324987", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/2d61ebea/hero.webp'' -> ''/data/images/wiki/2d61ebea/Location of Yelland Stone Rows.webp''"}, {"source": "remediation_change_log:347279", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:347280", "url": "remediation_change_log", "quote":