    ('2d98b59c-598f-4e05-b7ec-7233cd4e88ca'::uuid, 'antiquity', '7', '1', 'card-stats-2026-11-05-rollback:2d98b59c-598f-4e05-b7ec-7233cd4e88ca:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''1'' restored on Castle of Cola', '51e2ffcf8f60b3be2f0c0175945c19af', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82588", "url": "remediation_change_log", "quote": "phase4:p4-2065:chunk-0001: description ''The Castle of Cola (Castelo de Cola) is an Iron Age fortified settlement and later Islamic redoubt in the Alentejo region of southern Portugal, classified as a National Monument. The castro sits at 201 metres elevation on a mountain crest above the Ribeira do Marchicao and Rio Mira, with an irregular polygonal plan measuring 125 metres long and 60 metres wide. Occupation began in the Bronze Age and continued through the Iron Age, Roman, and Medieval Islamic periods. During the 10th-13th centuries, it became an enclosed town with stone walls 2.4 metres thick and 5-6 metres tall, reinforced by squared towers. The site is part of a larger archaeological circuit covering 23 stations across 15 km, including megalithic monuments and necropolises.'' -> ''Castle of Cola is an Iron Age residence and Islamic redoubt in the Portuguese Alentejo, classified as a National Monument [1]. The castro is part of a larger archaeological park of Castro da Cola, that includes various Megalithic and Chalcolithic monuments, including necropolises of the Bronze and Iron Ages [1]. During the period of Islamic influence within the Iberian peninsula, the castro was reinforced to serve as an outpost [1]. The fortification controlled one of the principal routes of passage into the Algarve [1]. The plan of the castle consists of an irregular 125 metres-long polygon, with 60 metres width, consisting of 2.4 metres thick walls, although in some areas this width was between 5–6 metres [1]. These walls were reinforced by unequal-sized rectangular blocks [1].''"}, {"source": "remediation_change_log:96336", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:96337", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:145642", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''/data/images/wiki/2d98b59c/hero.webp'' -> ''/data/images/wiki/2d98b59c/Castro da Cola 02.webp''"}, {"source": "remediation_change_log:247337", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_name None -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:247338", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_start None -> ''1000''"}, {"source": "remediation_change_log:308726", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/2d98b59c/Castro da Cola 02.webp'' -> ''/data/images/wiki/2d98b59c/Castelo_da_Cola.webp''"}, {"source": "remediation_change_log:357099", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s002: period_name ''1000 - 1500 AD'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:357100", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s002: period_start ''1000'' -> ''-2500''"}]'::jsonb),
