    ('2e0236e5-ca62-49f1-8532-303463aba86b'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:2e0236e5-ca62-49f1-8532-303463aba86b:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Notgrove Long Barrow', '4b05220fe38c13d05e0b9229a60c60a2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33541", "url": "remediation_change_log", "quote": "phase4:p4-0021:chunk-0001: description ''Notgrove Long Barrow is a Neolithic chambered tomb of the Cotswold-Severn type in Gloucestershire, England. The east-west oriented mound measures 50m long by 26m wide, supported by a low stone retaining wall, with a 12m gallery leading to an antechamber and four side chambers. Excavated in 1881 and 1934-35, the barrow yielded a male skeleton in a stone cist, Neolithic pottery, bone tools, and human and animal remains in the side chambers. The barrow was sealed and turfed over after 1976 to prevent further deterioration, though it remains openly accessible as a scheduled monument.'' -> ''Notgrove Long Barrow is a prehistoric long barrow burial mound in Gloucestershire, England [1]. It consists of a large mound with a passage running through the centre and several small chambers opening off it [1]. Human remains were interred in these chambers [1]. It is unlikely that any of these remains are still within the mound, as the barrow was open for thousands of years before being sealed in 1976 to prevent further damage to the site [1]. The barrow was surveyed in 1974 and the dimensions were estimated at 46 metres long, 30 metres wide and 1.7 metres high [1].''"}, {"source": "remediation_change_log:96351", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_name ''3000 - 1500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:96352", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_start ''-3000'' -> ''-3600''"}, {"source": "remediation_change_log:145679", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/a0/Notgrove_Long_Barrow_-_geograph.org.uk_-_93007.jpg'' -> ''/data/images/wiki/2e0236e5/hero.webp''"}]'::jsonb),
    ('2e0236e5-ca62-49f1-8532-303463aba86b'::uuid, 'rarity_score', '33', '30', 'card-stats-2026-11-05-rollback:2e0236e5-ca62-49f1-8532-303463aba86b:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''30'' restored on Notgrove Long Barrow', '4b05220fe38c13d05e0b9229a60c60a2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 33 from mystery 5, cultural_influence 8"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33541", "url": "remediation_change_log", "quote": "phase4:p4-0021:chunk-0001: description ''Notgrove Long Barrow is a Neolithic chambered tomb of the Cotswold-Severn type in Gloucestershire, England. The east-west oriented mound measures 50m long by 26m wide, supported by a low stone retaining wall, with a 12m gallery leading to an antechamber and four side chambers. Excavated in 1881 and 1934-35, the barrow yielded a male skeleton in a stone cist, Neolithic pottery, bone tools, and human and animal remains in the side chambers. The barrow was sealed and turfed over after 1976 to prevent further deterioration, though it remains openly accessible as a scheduled monument.'' -> ''Notgrove Long Barrow is a prehistoric long barrow burial mound in Gloucestershire, England [1]. It consists of a large mound with a passage running through the centre and several small chambers opening off it [1]. Human remains were interred in these chambers [1]. It is unlikely that any of these remains are still within the mound, as the barrow was open for thousands of years before being sealed in 1976 to prevent further damage to the site [1]. The barrow was surveyed in 1974 and the dimensions were estimated at 46 metres long, 30 metres wide and 1.7 metres high [1].''"}, {"source": "remediation_change_log:96351", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_name ''3000 - 1500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:96352", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_start ''-3000'' -> ''-3600''"}, {"source": "remediation_change_log:145679", "url": "remediation_change_log", "quote": "served-image-2026-09-30-006: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/a0/Notgrove_Long_Barrow_-_geograph.org.uk_-_93007.jpg'' -> ''/data/images/wiki/2e0236e5/hero.webp''"}]'::jsonb),
