    ('2e46252e-2205-4aed-92ee-38eeb5758399'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:2e46252e-2205-4aed-92ee-38eeb5758399:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Domica Cave', '0b6b6d2b01d66240b37e22f45c20d044', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44095", "url": "remediation_change_log", "quote": "phase4:p4-0087:chunk-0001: description ''Domica Cave is a karst cave on the Silicka Planina Plateau in southern Slovakia, extending 9,796 m when connected with Certova Diera Cave. Inhabited from around 5000 BC by the Neolithic Bukk culture, excavations revealed over 200 reconstructed ceramic vessels, evidence of on-site pottery manufacture, and the oldest comb in Europe. Other finds include bone fishhooks, decorated bracelets, stone axes, and the oldest fabric imprint in Slovakia. The cave features exceptional speleothems including flowstone shields, cascade pools, and pagoda-like stalagmites. Listed as a UNESCO World Heritage Site in 1995 as part of the Aggtelek Karst and Slovak Karst cave system.'' -> ''The Domica cave is a karst cave situated on the south-western border of the Silicka planina Plateau 10 km south-east of Plesivec in the Rožňava District of the Košice Region in southern Slovakia [1]. The cave is well known for its complex structure and high density of speleothems [1]. Jaroslav Böhm directed excavations during the 1930s [1]. Human presence has been documented dating back to the Paleolithic [1]. Post holes from dwelling objects and fireplaces were discovered in several places of the cave [1].''"}, {"source": "remediation_change_log:96355", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:96356", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_start ''-6000'' -> None"}, {"source": "remediation_change_log:146216", "url": "remediation_change_log", "quote": "served-image-2026-09-30-007: thumbnail_url ''/data/images/wiki/2e46252e/hero.webp'' -> ''/data/images/wiki/2e46252e/Domica Cave 02.webp''"}, {"source": "remediation_change_log:236528", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:236529", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_start None -> ''-35000''"}, {"source": "remediation_change_log:308738", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-003: thumbnail_url ''/data/images/wiki/2e46252e/Domica Cave 02.webp'' -> ''/data/images/wiki/2e46252e/Domica_Cave_22.webp''"}]'::jsonb),
