    ('2f93c277-9023-4fbd-9b56-dc2c4f18c1f6'::uuid, 'empire_count', '1', '0', 'card-stats-2026-11-05-rollback:2f93c277-9023-4fbd-9b56-dc2c4f18c1f6:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Dragon Hill, Uffington', '7c3271974a49de08e1fb518417980375', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 1 from tag_site(51.57944331958981, -1.5685029181181667, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82646", "url": "remediation_change_log", "quote": "phase4:p4-2067:chunk-0001: description ''A natural chalk hill about 10 metres high with an artificially flattened top, situated immediately below the Uffington White Horse on the Oxfordshire-Wiltshire border. Likely formed by glacial erosion, its summit was levelled by the Dobunni, a pre-Roman Celtic tribe. Legend holds that Saint George slew the dragon here, with a bare chalk patch where no grass grows said to mark where the dragon\\''s blood spilled. In a 10th-century charter the hill is called Eccles Beorh (\"Church Barrow\"), suggesting a former Christian building on its summit. The site sits within a rich Bronze Age and Iron Age landscape including Uffington Castle hillfort and the White Horse figure dated to 1740-210 BC.'' -> \"Dragon Hill is a small hillock immediately below the Uffington White Horse on the border of the civil parishes of Uffington and Woolstone in the English county of Oxfordshire [1]. Dragon Hill is a natural chalk hill with an artificially flattened top [1]. According to legend, Saint George slew the dragon here [1]. A bare patch of chalk upon which no grass will grow is purported to be where the dragon''s blood spilled [1]. It has been suggested as some sort of Iron Age ritual site associated with the nearby hill figure [1]. It is part of the White Horse group of monuments in the care of the National Trust, and a Scheduled Monument in its own right [1].\""}, {"source": "remediation_change_log:96379", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:96380", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_start ''-800'' -> None"}, {"source": "remediation_change_log:302107", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:302108", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-800''"}, {"source": "remediation_change_log:324990", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/2f93c277/hero.webp'' -> ''/data/images/wiki/2f93c277/Dragon Hill.webp''"}, {"source": "remediation_change_log:347293", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:347294", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-800'' -> None"}]'::jsonb),
