    ('31490608-0d55-49b1-843b-b983ed37ae64'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:31490608-0d55-49b1-843b-b983ed37ae64:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Sancreed Beacon', '756f8e2bcd0d1f06db4d190529674b56', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28862", "url": "remediation_change_log", "quote": "phase3:batch-0207:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:82678", "url": "remediation_change_log", "quote": "phase4:p4-2068:chunk-0001: description ''Sancreed Beacon is a Bronze Age archaeological site near the village of Sancreed on the Penwith peninsula in Cornwall, England, dating to roughly 3000-500 BC. The hilltop features several stone cists and burial mounds, with the remains of a Bronze Age hut discovered on the western slope. The site is maintained by the Cornwall Heritage Trust and forms part of a rich prehistoric landscape in the Penwith area [1][2].'' -> ''Sancreed Beacon is a Bronze Age archaeological site near the village of Sancreed in the Penwith peninsula of Cornwall maintained by the Cornwall Heritage Trust [1]. On top of the hill are several stone cists and Bronze Age archaeological remains comprising burial mounds and the remains of a Bronze Age hut on the Western slope [1]. This site can be taken in the context of a rich variety of archaeological evidence in the vicinity from the Iron Age, Bronze Age and dating as far back as Neolithic time