    ('31860bc4-476a-49bc-9f97-e25220063d19'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:31860bc4-476a-49bc-9f97-e25220063d19:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Satsurblia Cave', 'dce18402d76b77e1d59e1de276ffa425', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -23550"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27255", "url": "remediation_change_log", "quote": "2026-09-21_mechanical-country: country ''Georgia (country)'' -> ''Georgia''"}, {"source": "remediation_change_log:80766", "url": "remediation_change_log", "quote": "phase4:p4-2007:chunk-0001: description \"Satsurblia Cave Natural Monument is a paleoanthropological site located 1.2 km from Kumistavi village in Georgia''s Imereti region, situated 287 meters above sea level [1]. This karst cave was first excavated in 1976 by archaeologist A. N. Kalandadze [1]. During the Medieval period, the cave served as a refuge [1].\" -> ''Satsurblia Cave Natural Monument is a paleoanthropological site located 1.2 km from Kumistavi village, Tsqaltubo Municipality, in the Imereti region of Georgia [1]. The karst cave was first excavated in 1976 by A. N. Kalandadze [1]. Prehistoric people first occupied the cave from around 25,500 to 24,400 BP [1]. The next period of human occupation at Satsurblia took place from around 17,000 to 16,200 BP [1]. The hiatus in human occupation at Satsurblia coincides with the Last Glacial Maximum [1]. Lithic artefacts, bone artefacts, charcoal, flax fibers, and pottery were discovered at the cave [1]. Perforated pendants made out of stalagmite and polished bovid bone were also discovered [1]. In 2013, archaeologists found a temporal bone fragment of an ancient human in the cave [1].''"}, {"source": "remediation_change_log:114971", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: lat ''42.37726777374251'' -> ''42.388111''"}, {"source": "remediation_change_log:114972", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: lon ''42.60097658321723'' -> ''42.606167''"}, {"source": "remediation_change_log:114973", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:114974", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: period_start ''-500'' -> None"}, {"source": "remediation_change_log:146291", "url": "remediation_change_log", "quote": "served-image-2026-09-30-007: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/ad/Satsurblia_11.jpg'' -> ''/data/images/wiki/31860bc4/Pollen and spores from Satsurblia Cave.webp''"}, {"source": "remediation_change_log:247379", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:247380", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_start None -> ''-500''"}, {"source": "remediation_change_log:309385", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-004: thumbnail_url ''/data/images/wiki/31860bc4/Pollen and spores from Satsurblia Cave.webp'' -> ''/data/images/wiki/31860bc4/Satsurblia_11.webp''"}, {"source": "remediation_change_log:347308", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:347309", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-500'' -> ''-23550''"}]'::jsonb),
