    ('3191f287-4b47-4d83-903f-9815001086ed'::uuid, 'category_group', 'Other', 'Settlements', 'card-stats-2026-11-05-rollback:3191f287-4b47-4d83-903f-9815001086ed:category_group', 'rollback of card-stats-2026-11-05: category_group ''Settlements'' restored on Nausharo', '8c030a57e3877ef3b2b47bba25550371', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "category_group = Other from site_type None is in group ''Other''"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27821", "url": "remediation_change_log", "quote": "phase3:batch-0014:chunk-0001: period_start ''-4500'' -> ''-2900''"}, {"source": "remediation_change_log:27822", "url": "remediation_change_log", "quote": "phase3:batch-0014:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:30376", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:33555", "url": "remediation_change_log", "quote": "phase4:p4-0021:chunk-0001: description ''Nausharo is an archaeological site in Balochistan, Pakistan, 6 km from the major site of Mehrgarh. Excavated between 1985 and 1996 by a French team under Jean-Francois Jarrige, it revealed occupation from 3000 to 2550 BC and again from 2550 to 1900 BC, spanning the Early to Mature Harappan periods. Discoveries include a pottery workshop with fired and unfired vessels, flint blades showing use-wear from shaping pottery on a wheel, and organized settlement patterns with drains and walls. The site demonstrates cultural continuity and links between Indus Valley communities during the late Early Indus tradition.'' -> ''Nausharo is an archaeological site dating back to the Harappan period, located in Balochistan, Pakistan [1]. The excavations were carried out between 1985 and 1996 by a French team of archaeologists, under the direction of Jean-François Jarrige [1]. Excavations at Nausharo, 6 km from Mehrgarh, revealed a dwelling-site contemporaneous and identical to the later periods of Mehrgarh [1]. The discovery of a pottery workshop at Nausharo revealed fired and unfired pottery pieces and unworked clay, as well as 12 flint blades or blade fragments [1]. Also significant was the discovery of copper traces found on the platforms of two blades examined with a scanning electron microscope and X ray analysis [1]. Somewhere between 2600 BC and 2000 BC, Mehrgarh seems to have been largely abandoned in favor of Nausharo, which became fortified and quite large [1].''"}, {"source": "remediation_change_log:35723", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:96435", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:146292", "url": "remediation_change_log", "quote": "served-image-2026-09-30-007: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/6/65/Nausharo_Matka.jpg'' -> ''/data/images/wiki/3191f287/hero.webp''"}, {"source": "remediation_change_log:236553", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: site_type None -> ''City''"}, {"source": "remediation_change_log:324994", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/3191f287/hero.webp'' -> ''/data/images/wiki/3191f287/Nausharo Matka.webp''"}, {"source": "remediation_change_log:347310", "url": "remediation_chang