    ('31ba0428-1f43-411a-8473-0f1ade121091'::uuid, 'mystery', '3', '6', 'card-stats-2026-11-05-rollback:31ba0428-1f43-411a-8473-0f1ade121091:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Independence Fjord', 'a07179a65b7d4e599abdac93e6e4f253', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''3000 - 1500 BC'') is shared by 130 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29430", "url": "remediation_change_log", "quote": "phase3:batch-0288:chunk-0001: site_type ''City/town/settlement'' -> ''Natural feature''"}, {"source": "remediation_change_log:35724", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Natural feature'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:82684", "url": "remediation_change_log", "quote": "phase4:p4-2068:chunk-0001: description ''A large fjord in eastern Peary Land, northern Greenland, about 200 km long, that gave its name to two Paleo-Eskimo cultures. In 1948, Danish explorer Eigil Knuth discovered the Deltaterrasserne site nearby and identified the Independence I culture (c. 2400-1900 BC), the oldest known culture in Greenland. These hunter-gatherers lived in tent-ring dwellings with central hearths, subsisting primarily on muskox, and crafted microblades and bone needles. A later Independence II culture also occupied the region.'' -> ''Independence Fjord or Independence Sound is a large fjord or sound in the eastern part of northern Greenland [1]. It is about 200 km long and up to 30 km wide [1]. In the area around Independence Fjord there are traces of two paleo-Eskimo cultures that were named Independence I culture and Independence II culture after the fjord [1]. The traces of ancient human settlements in the area have been the subject of research since the beginning of the 20th century [1]. North of the fjord, in southern Peary Land, there are remains of dwellings with elliptical floor plan, built by Early Paleoeskimo Independence I culture [1]. These people used tools made from rocks and bones, and subsisted from hunting wildlife like musk oxen and Arctic hares [1]. Bones of musk oxen hunted down in Peary Land show that the area was inhabited at 2000 BC [1]. The oldest discoveries are dated at 2400 BC [1].''"}, {"source": "remediation_change_log:114975", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s002: site_type ''City/town/settlement'' -> ''Settlement''"}, {"source": "remediation_change_log:146319", "url": "remediation_change_log", "quote": "served-image-2026-09-30-007: thumbnail_url ''/data/images/wiki/31ba0428/hero.webp'' -> ''/data/images/wiki/31ba0428/Fjord Independance vue du nord.webp''"}, {"source": "remediation_change_log:355608", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
