    ('32f8606a-075b-4e6c-afae-427a49ef9df4'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:32f8606a-075b-4e6c-afae-427a49ef9df4:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Smythe''s Megalith', '1200af5895e7a7d44303ee38ec8796b2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Tomb'', ''4500 - 3000 BC'') is shared by 12 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82706", "url": "remediation_change_log", "quote": "phase4:p4-2069:chunk-0001: description \"Smythe''s Megalith, also called Warren Farm Chamber, was a chambered long barrow near Aylesford in Kent, England. Probably built in the 4th millennium BCE during Britain''s Early Neolithic period, it was discovered and dismantled in 1822. The monument consisted of a roughly rectangular earthen tumulus enhanced with at least five local sarsen megaliths, featuring a stone chamber at its eastern end where human remains were deposited.[1]\" -> \"Smythe''s Megalith, also known as the Warren Farm Chamber, was a chambered long barrow near the village of Aylesford in the south-eastern English county of Kent [1]. Probably constructed in the 4th millennium BCE, during Britain''s Early Neolithic period, it was discovered in 1822, at which point it was dismantled [1]. Built out of earth and at least five local sarsen megaliths, the long barrow consisted of a roughly rectangular earthen tumulus with a stone chamber in its eastern end [1]. Human remains were deposited into this chamber [1]. Archaeologists have established that the monument was built by pastoralist communities shortly after the introduction of agriculture to Britain from continental Europe [1]. Although representing part of an architectural tradition of long barrow building widespread across Neolithic Europe, Smythe''s Megalith belonged to a localised regional variant produced in the vicinity of the River Medway, now known as the Medway Megaliths [1].\""}, {"source": "remediation_change_log:96453", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:96454", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:96455", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: site_type ''Megalithic stones'' -> ''Tomb''"}, {"source": "remediation_change_log:146341", "url": "remediation_change_log", "quote": "served-image-2026-09-30-007: thumbnail_url \"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Smythe''s_Megalith_field.jpg/400px-Smythe''s_Megalith_field.jpg\" -> \"/data/images/wiki/32f8606a/Smythe''s_Megalith_Illustration.webp\""}, {"source": "remediation_change_log:236558", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:236559", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_start None -> ''-4000''"}]'::jsonb),
