    ('34139009-7bb5-42d7-b9d1-f5163fdb856d'::uuid, 'antiquity', '4', '8', 'card-stats-2026-11-05-rollback:34139009-7bb5-42d7-b9d1-f5163fdb856d:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Aves Ditch', '6d6304ce57aff17c736a2c6b2039b279', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 4 from period_start -100"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82722", "url": "remediation_change_log", "quote": "phase4:p4-2069:chunk-0001: description ''An Iron Age linear earthwork running approximately 4.8 km through the Cherwell District of Oxfordshire. Once mistaken for a Roman road, excavation revealed it to be a boundary dyke dating to 500-325 BC. Scholars Sauer and Lambrick proposed it formed part of the tribal boundary between the Dobunni and Catuvellauni. A skull found in the ditch dates to Anglo-Saxon reuse of the monument. It now forms civil parish boundaries, reflecting its enduring role as a territorial marker.'' -> ''Aves Ditch is an Iron Age ditch and bank structure running about 3 miles on a northeast to southwest alignment in the Cherwell District of Oxfordshire [1]. It was once believed to have been a Roman road but excavation has shown it to be a boundary dyke of Iron Age date that was reused in the Anglo-Saxon period [1]. A skull found in the ditch was dated to the Anglo-Saxon period [1]. Both Sauer and Lambrick have suggested that the Aves Ditch along with the North Oxfordshire Grim’s Ditch and the South Oxfordshire Grim’s Ditch may have formed the boundary between the Iron Age tribes of the Dobunni and the Catuvellauni [1].''"}, {"source": "remediation_change_log:96481", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:96482", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s005: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:247397", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:247398", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_start None -> ''-4000''"}, {"source": "remediation_change_log:347315", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''4500 - 3000 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:347316", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-4000'' -> ''-100''"}]'::jsonb),
