    ('34c9266e-b55c-4f29-9e6e-eeb547ecfd50'::uuid, 'mystery', '7', '6', 'card-stats-2026-11-05-rollback:34c9266e-b55c-4f29-9e6e-eeb547ecfd50:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Dun Hallin', 'f90e3f4c59b6791ec761ef57b0eeb639', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Fortification'', ''1500 - 500 BC'') is shared by 10 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28132", "url": "remediation_change_log", "quote": "phase3:batch-0079:chunk-0001: site_type ''Minaret/tower'' -> ''Fortification''"}, {"source": "remediation_change_log:44123", "url": "remediation_change_log", "quote": "phase4:p4-0088:chunk-0001: description ''Dun Hallin is an Iron Age Broch located near the northwest coast of the island of Skye, Scotland [1].'' -> ''Dun Hallin is an Iron Age broch located near the northwest coast of the island of Skye, in Scotland [1]. Dun Hallin is located on the Waternish peninsula of Skye, just east of the settlement of Hallin [1]. It occupies the southeast end of a steep-sided rocky plateau overlooking a fertile valley and the sea [1]. Dun Hallin has an external diameter of around 17.4 metres and an internal diameter of around 10.5 metres [1]. The broch walls currently stand to a maximum height of 3.8 metres on the north and west sides [1]. The entrance is on the southeast side but is in a ruined state [1]. On each side of the entrance passage are oval guard cells, although only the northern, right-hand cell can easily be seen [1]. The interior of the broch has much rubble grassed over [1].''"}, {"source":