    ('34f757be-a065-458c-9200-05b3beeeca2c'::uuid, 'antiquity', '6', '8', 'card-stats-2026-11-05-rollback:34f757be-a065-458c-9200-05b3beeeca2c:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Ponton Heath Barrow Cemetery', 'b0510b7df51eeebd108d3df2089b9c29', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 6 from period_start -2000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44125", "url": "remediation_change_log", "quote": "phase4:p4-0088:chunk-0001: description ''The Ponton Heath Barrow Cemetery comprises at least eleven Middle Bronze Age round barrows on high ground south of Grantham in South Kesteven, Lincolnshire, England[1]. Five barrows were destroyed by ironstone quarrying in 1959; the surviving six are scheduled monuments and listed on the Heritage at Risk Register[1].'' -> ''The Ponton Heath Barrow Cemetery is a group of at least eleven Middle Bronze Age round barrows south of Grantham, in the South Kesteven district of Lincolnshire, England [1]. Five of the barrows were destroyed by ironstone quarrying in 1959; the remaining six are scheduled monuments [1]. The cemetery is located on Ponton Heath, an area of high ground several miles south of the market town of Grantham [1]. It is centred approximately 1.2 kilometres northeast of the hamlet of Hungerton and 1.5 kilometres southwest of the village of Stroxton [1]. In 1959, following the opening of Harlaxton Quarry No. 4, a rescue excavation was carried out by Ernest Greenfield of the Ministry of Works [1]. In Barrow J he found an intact main burial chamber containing a crushed red collared urn, decorated with cord impressions, inverted over burned bone [1]. He also found numerous secondary cremations and stone tools, leading him to classify the builders as the \"Yorkshire Food Vessel Culture\" in the terminology of the time [1]. The site also contained evidence of later Romano-British occupation [1].''"}, {"source": "remediation_change_log:97149", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:97150", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:247405", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:247406", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_start None -> ''-4000''"}, {"source": "remediation_change_log:347320", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:347321", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''-4000'' -> ''-2000''"}]'::jsonb),
