    ('360da20f-8f95-4ba9-83fc-49d4b193b679'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:360da20f-8f95-4ba9-83fc-49d4b193b679:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Padah-Lin Caves', 'b3ea08cd06627135010ab0d53c9c1e43', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -23050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80786", "url": "remediation_change_log", "quote": "phase4:p4-2008:chunk-0001: description ''The Padah-Lin Caves are limestone caves in Taunggyi District, Shan State, Myanmar, consisting of two caves within the Panlaung Reserved Forest. Cave 1 contains Neolithic paintings in red ochre depicting wild boars, sun symbols, and hands that were painted rather than stencilled. Excavations from 1969-1972 yielded 1,600 stone artefacts with C14 dates ranging from 1,750 to 13,000 years BP. Cave 2 contains a 358m-long passage system with deposits dating to 65,000 years BP and flaked stone artifacts from 25,000 years BP. The caves were added to the UNESCO World Heritage Tentative List in 1996.'' -> ''The Padah-Lin Caves are limestone caves located in Taunggyi District, Shan State, Burma [1]. It is located near a path from Nyaunggyat to Yebock, on a spur of the Nwalabo mountains within the Panlaung Reserved Forest [1]. There are two caves; the smaller of the two is a rock shelter while the larger cave comprises nine chambers connected by narrow passages in a north-south axis, three large sinkholes that let natural light in, and several active speleothem formations [1]. Red ochre paintings of human hands, fish, bulls, bison, deer and other objects are visible at the rock shelter [1]. More than 300 cupules have been documented in the rockshelter [1]. Excavations at the rock shelter from 1969 to 1972 recovered seven pieces of charcoal and bone that were radiocarbon dated to between 1,750 and 13,000 years BP [1]. The excavation also recovered over 1,600 stone artifacts as well as many pieces of bone and red ochre [1].''"}, {"source": "remediation_change_log:97172", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:97173", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''-500'' -> None"}, {"source": "remediation_change_log:146403", "url": "remediation_change_log", "quote": "served-image-2026-09-30-007: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/d/d1/Padah-Lin_Cave_1_sign.jpg'' -> ''/data/images/wiki/360da20f/Buddhist_stupa_at_Padah-Lin_Cave_1.webp''"}, {"source": "remediation_change_log:247411", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:247412", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_start None -> ''-500''"}, {"source": "remediation_change_log:333733", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-001: thumbnail_url ''/data/images/wiki/360da20f/Buddhist_stupa_at_Padah-Lin_Cave_1.webp'' -> ''/data/images/wiki/360da20f/hero.webp''"}, {"source": "remediation_change_log:357137", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s003: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:357138", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s003: period_start ''-500'' -> ''-23050''"}]'::jsonb),
