    ('36408f22-774c-4626-a92f-e0c231f69206'::uuid, 'antiquity', '2', '3', 'card-stats-2026-11-05-rollback:36408f22-774c-4626-a92f-e0c231f69206:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Rumicolca', '8b66edd4b7b6bf4a4997b1c6fa010e20', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 2 from period_start 600"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33619", "url": "remediation_change_log", "quote": "phase4:p4-0023:chunk-0001: description ''Monumental stone gateway located 31 km southeast of Cusco, originally built by the Wari culture (c. 550-900 AD) and later enlarged by the Inca. The structure functioned as a checkpoint on the royal road to Collasuyo, one of the four regions of Tahuantinsuyo. Walls reach up to 12 metres (39 feet) high. The Inca reinforced sections with precisely cut and fitted andesite stonework over the older Wari foundations. Situated adjacent to Pikillaqta, the largest known Wari provincial center, near Lake Huacarpay. One theory holds the original structure served as a Wari aqueduct.'' -> ''Rumicolca (possibly from Quechua rumi stone, qullqa, qulqa deposit, storehouse) is an archaeological site in Peru [1]. It is located in the Cusco Region, Quispicanchi Province, Lucre District [1]. Rumicolca is situated near the archaeological sites Chuqi Pukyu and Pikillaqta, east of Lake Huacarpay [1].''"}, {"source": "remediation_change_log:97176", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:97177", "url": "remediation_cha