161", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:116162", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_start ''1'' -> None"}, {"source": "remediation_change_log:116163", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: source_url ''https://en.wikipedia.org/wiki/Isla_de_Sacrificios'' -> ''https://www.megalithic.co.uk/article.php?sid=31058''"}, {"source": "remediation_change_log:146941", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/36778e23/hero.webp'' -> ''/data/images/wiki/36778e23/Monkey Jar.webp''"}, {"source": "remediation_change_log:247423", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:247424", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_start None -> ''43''"}, {"source": "remediation_change_log:331599", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-006-001: thumbnail_url ''/data/images/wiki/36778e23/Monkey Jar.webp'' -> ''/data/images/wiki/36778e23/Massico, totonac, remojadas veracruz, figura di comandante seduto, 300-600 dc ca.webp''"}, {"source": "remediation_change_log:347328", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:347329", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s002: period_start ''43'' -> None"}]'::jsonb),
