    ('3696e872-ce24-42c2-b632-fe7b034171df'::uuid, 'mystery', '3', '6', 'card-stats-2026-11-05-rollback:3696e872-ce24-42c2-b632-fe7b034171df:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Karahan Tepe', '0cd8cc9bbc1e51ff14a4fdad0e048404', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''< 4500 BC'') is shared by 105 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28074", "url": "remediation_change_log", "quote": "phase3:batch-0065:chunk-0001: site_type ''Megalithic stones'' -> ''Archaeological site''"}, {"source": "remediation_change_log:33623", "url": "remediation_change_log", "quote": "phase4:p4-0023:chunk-0001: description ''Karahan Tepe is a Pre-Pottery Neolithic site in Şanlıurfa, Turkey, dating to 10,000–9500 BCE[1]. Excavations have uncovered T-shaped pillars, similar to those found at Göbekli Tepe[1]. Evidence suggests Karahan Tepe may predate Göbekli Tepe by several centuries, potentially representing the earliest known human village[1].'' -> ''Karahan Tepe is a Pre-Pottery Neolithic archaeological site in Şanlıurfa, Turkey [1]. The site is in the same geographical region as Göbekli Tepe, and archaeologists have also uncovered T-shaped stelae there and believe that the sites are related [1]. Additionally, the site may be the earliest known human village, predating the construction of Göbekli Tepe by several centuries, dating to between 10,000 and 9500 BC [1]. The site was filled with dirt and rubble at some point, preserving T-topped columns carved into bedrock [1]. The Karahan tepe archaeological site covers almost 10 hectares, which increases by another five hectares if the quarries for the T-shaped columns are included [1]. The site contains numerous T-shaped pillars similar to those of Gobekli Tepe [1].''"}, {"source": "remediation_change_log:35730", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''Megalithic stones''"}, {"source": "remediation_change_log:116169", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: site_type ''Megalithic stones'' -> ''Settlement''"}, {"source": "remediation_change_log:146947", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/3696e872/hero.webp'' -> ''/data/images/wiki/3696e872/Karahan_Tepe_head_(de-shadowed).webp''"}, {"source": "remediation_change_log:355613", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
