    ('373ccffa-991d-4455-b116-19957b288a28'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:373ccffa-991d-4455-b116-19957b288a28:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Featherwood Roman Camps', 'df1253e9ce5e761355981fa4810f94a7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Earthwork'', ''1 - 500 AD'') is shared by 11 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82780", "url": "remediation_change_log", "quote": "phase4:p4-2071:chunk-0001: description ''Two 1st-century AD Roman temporary marching camps in Northumberland, England, situated on either side of Dere Street, the Roman road running from York into Scotland. The eastern camp is roughly square at 400 x 410 metres enclosing about 16 hectares, while the western camp is trapezoidal at 365 x 445 metres enclosing 15.6 hectares. Both feature gateways protected by external titulum defences. The camps were likely used by soldiers advancing northward and by groups maintaining the road.'' -> ''Featherwood Roman Camps are neighbouring archaeological sites in Northumberland, England, 1 mile north of Featherwood and about 3 miles east of Byrness [1]. The remains of two Roman camps, near Dere Street, are scheduled monuments [1]. The two camps, about 500 metres apart, are situated on either side of Dere Street, a Roman road in use between AD 78 and AD 211 running from Eboracum into Scotland [1]. The camps date from the 1st century AD [1]. They are thought to have been used by soldiers advancing northwards, and by smaller groups employed in routine maintenance [1]. Chew Green and Bremenium, nearby Roman encampments on Dere Street, lie to the north and south [1].''"}, {"source": "remediation_change_log:97187", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:97188", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''1'' -> None"}, {"source": "remediation_change_log:236595", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:236596", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_start None -> ''1''"}]'::jsonb),
