    ('37999fa3-d22d-4c51-a2f5-fa0dd9d82942'::uuid, 'antiquity', '5', '6', 'card-stats-2026-11-05-rollback:37999fa3-d22d-4c51-a2f5-fa0dd9d82942:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on El Baúl', '8ea717b5e779c42039dea355b97c5cd9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29602", "url": "remediation_change_log", "quote": "phase3:batch-0312:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:33627", "url": "remediation_change_log", "quote": "phase4:p4-0023:chunk-0001: description ''El Baul is a Pre-Columbian archaeological site in Escuintla, Guatemala, part of the Cotzumalhuapa Archaeological Zone alongside Bilbao and El Castillo. Flourishing during the Late Classic period (600-900 AD), it contains over 200 structures and 187 sculptured monuments, including Stela 1 dated to 36 CE. The site features an acropolis 83 feet high with four courts, a ball court, and 22 platforms. Its inhabitants developed an original undeciphered writing system and an artistic style linked to cacao production and ritual practices.'' -> \"El Baúl is a Pre-Columbian archaeological site in present-day Escuintla Department, Guatemala [1]. El Baúl, along with the sites of Bilbao and El Castillo, is part of the Cotzumalhuapa Archaeological Zone [1]. It was occupied during the prehistoric Formative stage of the Americas [1]. The El Baúl acropolis is located 4 km north of Santa Lucía Cotzumalguapa, 550 metres above sea level, 50 kilometres from the Pacific Ocean [1]. Its southern acropolis complex was destroyed in 1997 by urban development and the main groups are now covered by sugar cane fields [1]. The site''s geologic context is volcanic; it is located just south of an active stratovolcano, Fuego volcano [1]. The site contains monumental architecture in its acropolis as well as a probable sweatbath and obsidian workshops [1].\""}, {"source": "remediation_change_log:35732", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:84200", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:84201", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:146990", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/37999fa3/hero.webp'' -> ''/data/images/wiki/37999fa3/El Baúl 20.webp''"}, {"source": "remediation_change_log:247429", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:247430", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_start None -> ''-1500''"}, {"source": "remediation_change_log:309492", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-004: thumbnail_url ''/data/images/wiki/37999fa3/El Baúl 20.webp'' -> ''/data/images/wiki/37999fa3/ElBaulSt.webp''"}, {"source": "remediation_change_log:348078", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:348079", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-1500'' -> None"}]'::jsonb),
