    ('38325c7e-7878-4dc9-b9eb-318ac744d3c2'::uuid, 'mystery', '7', '6', 'card-stats-2026-11-05-rollback:38325c7e-7878-4dc9-b9eb-318ac744d3c2:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Megaliths in Mecklenburg-Vorpommern', 'a3ac3b7c592682b06a071b96a46a7b54', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Megalithic structures'', ''4500 - 3000 BC'') is shared by 10 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82808", "url": "remediation_change_log", "quote": "phase4:p4-2072:chunk-0001: description \"In Mecklenburg-Vorpommern, Germany, up to 5,000 megalithic tombs were erected between 3500 and 3200 BC by the Neolithic Funnelbeaker (TRB) culture, with over 1,000 surviving today under legal protection. Most are dolmens built from glacial erratics, often set within circular or trapezoid frames of standing stones. Regional variations include passage graves in northern Mecklenburg, extended dolmens in the south, and stone cists in Vorpommern. Locally known as Hunengraber (Giants'' Graves), they represent one of Europe''s densest concentrations of megalithic monuments.\" -> ''The megaliths in Mecklenburg-Vorpommern were erected as burial sites in the Neolithic, by the bearers of the Funnelbeaker (TRB) culture, between 3,500 and 3,200 BC [1]. 144 megaliths have been excavated since 1945 [1]. 106 of these were excavated and afterwards restored by archaeologist Ewald Schuldt and his team between 1964 and 1972 [1]. Disarticulated bones from up to twenty individuals have been discovered in excavated dolmens [1]. Few dolmens contain only TRB finds, as most were also used by the contemporary and subsequent Globular Amphora and Single Grave cultures, and some remained in use until the Bronze Age [1]. The bearers of the Globular Amphora culture removed and demolished skeletons and items from previous burials before reusing the tombs for their own dead [1]. Many megaliths were used as quarries in the past, e.g. for the construction of 13th- and 14th-century churches, medieval and early modern stone walls, 18th-century manor houses, as well as for 19th-century dikes, roads, bridges and milestones [1].''"}, {"source": "remediation_change_log:97206", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:97207", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:97208", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: site_type ''Dolmen'' -> ''Megalithic structures''"}, {"source": "remediation_change_log:147019", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/38325c7e/hero.webp'' -> ''/data/images/wiki/38325c7e/Riesenberg_Nobbin.webp''"}, {"source": "remediation_change_log:236612", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:236613", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_start None -> ''-3500''"}, {"source": "remediation_change_log:309507", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-004: thumbnail_url ''/data/images/wiki/38325c7e/Riesenberg_Nobbin.webp'' -> ''/data/images/wiki/38325c7e/LG_Dolmen1.webp''"}]'::jsonb),
    ('38325c7e-7878-4dc9-b9eb-318ac744d3c2'::uuid, 'rarity_score', '43', '40', 'card-stats-2026-11-05-rollback:38325c7e-7878-4dc9-b9eb-318ac744d3c2:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''40'' restored on Megaliths in Mecklenburg-Vorpommern', 'a3ac3b7c592682b06a071b96a46a7b54', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 43 from mystery 7, cultural_influence 10"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:82808", "url": "remediation_change_log", "quote": "phase4:p4-2072:chunk-0001: description \"In Mecklenburg-Vorpommern, Germany, up to 5,000 megalithic tombs were erected between 3500 and 3200 BC by the Neolithic Funnelbeaker (TRB) culture, with over 1,000 surviving today under legal protection. Most are dolmens built from glacial erratics, often set within circular or trapezoid frames of standing stones. Regional variations include passage graves in northern Mecklenburg, extended dolmens in the south, and stone cists in Vorpommern. Locally known as Hunengraber (Giants'' Graves), they represent one of Europe''s densest concentrations of megalithic monuments.\" -> ''The megaliths in Mecklenburg-Vorpommern were erected as burial sites in the Neolithic, by the bearers of the Funnelbeaker (TRB) culture, between 3,500 and 3,200 BC [1]. 144 megaliths have been excavated since 1945 [1]. 106 of these were excavated and afterwards restored by archaeologist Ewald Schuldt and his team between 1964 and 1972 [1]. Disarticulated bones from up to twenty individuals have been discovered in excavated dolmens [1]. Few dolmens contain only TRB finds, as most were also used by the contemporary and subsequent Globular Amphora and Single Grave cultures, and some remained in use until the Bronze Age [1]. The bearers of the Globular Amphora culture removed and demolished skeletons and items from previous burials before reusing the tombs for their own dead [1]. Many megaliths were used as quarries in the past, e.g. for the construction of 13th- and 14th-century churches, medieval and early modern stone walls, 18th-century manor houses, as well as for 19th-century dikes, roads, bridges and milestones [1].''"}, {"source": "remediation_change_log:97206", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:97207", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:97208", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: site_type ''Dolmen'' -> ''Megalithic structures''"}, {"source": "remediation_change_log:147019", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/38325c7e/hero.webp'' -> ''/data/images/wiki/38325c7e/Riesenberg_Nobbin.webp''"}, {"source": "remediation_change_log:236612", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:236613", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_start None -> ''-3500''"}, {"source": "remediation_change_log:309507", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-004: thumbnail_url ''/data/images/wiki/38325c7e/Riesenberg_Nobbin.webp'' -> ''/data/images/wiki/38325c7e/LG_Dolmen1.webp''"}]'::jsonb),
