    ('384133aa-dc2d-4f86-9f20-e53c98e5c5be'::uuid, 'antiquity', '3', '4', 'card-stats-2026-11-05-rollback:384133aa-dc2d-4f86-9f20-e53c98e5c5be:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Roman Dam of Pego da Moura', '0af7c311ecf1a5cf9de6618bae100cbf', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 3 from period_start 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33633", "url": "remediation_change_log", "quote": "phase4:p4-0023:chunk-0001: description ''A small Roman buttress dam in the municipality of Grandola, Setubal District, Portugal, constructed during the Roman occupation. Built in two phases, it consists of a rectilinear wall originally about 40 metres long with a maximum height of 3.3 metres. Six downstream buttresses spaced 2.5 metres apart reinforce the structure, built largely using opus incertum with a vaulted chamber in opus signinum. Traces of a water mill survive. First noted by Father Carvalho Costa in 1712, the dam was not archaeologically studied until the 1990s.'' -> ''The Roman Dam of Pego da Moura is a small buttress dam situated in the municipality of Grândola in the Setúbal District of Portugal [1]. The dam was constructed during the middle of the Roman occupation of Portugal [1]. Built in two phases, it consists of a rectilinear wall that was originally about 40 metres long [1]. The ruins have a maximum height of 3 m. and a thickness of 2.90 m [1]. There are six downstream buttresses that are 2.50 m. apart, which are around 2.70 m. thick and 2.90 m long [1]. The dam was almost entirely constructed using opus incertum [1]. The dam was first noted by Father Carvalho Costa in 1712 in his work, Corographia Portugueza [1]. However, it was not until the 1990s that a brief archaeological study was conducted [1].''"}, {"source": "remediation_change_log:97211", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:97212", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''1'' -> None"}, {"source": "remediation_change_log:147044", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/6/6f/Pego_da_Moura3.JPG'' -> ''/data/images/wiki/384133aa/Pego da Moura1.webp''"}, {"source": "remediation_change_log:247431", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:247432", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s005: period_start None -> ''-27''"}, {"source": "remediation_change_log:309513", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-004: thumbnail_url ''/data/images/wiki/384133aa/Pego da Moura1.webp'' -> ''/data/images/wiki/384133aa/Pego_da_Moura3.webp''"}, {"source": "remediation_change_log:348080", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''500 BC - 1 AD'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:348081", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-27'' -> ''1''"}]'::jsonb),
