    ('3b7c9b7b-5792-4162-84ed-5663b1760d60'::uuid, 'mystery', '3', '8', 'card-stats-2026-11-05-rollback:3b7c9b7b-5792-4162-84ed-5663b1760d60:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Heaning Wood Bone Cave', '4a9f29498a68a3f196823cc1940400c9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33673", "url": "remediation_change_log", "quote": "phase4:p4-0024:chunk-0001: description ''Heaning Wood Bone Cave is a cave of major archaeological importance in Great Urswick, Cumbria, England, first excavated by Holland in 1958. Excavations since 2016 by local archaeologist Martin Stables uncovered human remains radiocarbon-dated to approximately 11,000 years ago, making them the earliest found in northern Britain. The cave saw at least three distinct periods of burial: Early Mesolithic (~11,000 BP), Early Neolithic (~5,500 BP), and Early Bronze Age (~4,000 BP). Evidence suggests at least eight individuals were deliberately interred alongside stone tools, pottery, and perforated periwinkle shell beads. DNA analysis by the Francis Crick Institute identified one Mesolithic individual, nicknamed the \"Ossick Lass,\" as a young girl aged two to three years.'' -> ''Heaning Wood Bone Cave is a cave of archaeological importance in Great Urswick, Cumbria [1]. The cave was first excavated by Holland in 1958, when he found Bronze Age pottery, human and animal bones, and a stone-flake knife of Langdale stone [1]. In January 2023 it was reported that human bone and a periwinkle shell bead, found in the cave by local archaeologist Martin Stables, had been dated to 11,000 years ago [1]. At least eight individuals had been buried in the cave, from the early Bronze Age (4,000 years ago), the early Neolithic period (6,000 years ago) and the early Mesolithic period (11,000 years ago) [1]. In February 2026 it was announced that some of the bones had been identified as being from a female aged between two and a half and three and a half years [1]. She had been given the name Ossick Lass, reflecting the local name for Urswick [1]. She has been dated to between 9290 and 8925 BCE [1].''"}, {"source": "remediation_change_log:97265", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:97266", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''-9000'' -> None"}, {"source": "remediation_change_log:97267", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: site_type ''Cave Structures'' -> ''Cave''"}, {"source": "remediation_change_log:236644", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:236645", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_start None -> ''-9290''"}, {"source": "remediation_change_log:355622", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Cave'' -> ''Cave Structures''"}]'::jsonb),
