    ('3c1e886f-d77b-4d46-899b-2aaf26861a4d'::uuid, 'mystery', '9', '6', 'card-stats-2026-11-05-rollback:3c1e886f-d77b-4d46-899b-2aaf26861a4d:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Burial Ground of Cherneliv-Ruskyi', '7ad2d16151fa28b414d1031b787c16e1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 9 from (''Cemetery'', ''Undated'') is shared by 2 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43345", "url": "remediation_change_log", "quote": "phase4:p4-0073:chunk-0001: description \"The Burial Ground of Cherneliv-Ruskyi is a major Chernyakhov culture cemetery (3rd-4th century AD) in the Ternopil Oblast of western Ukraine, and the most extensively studied site of this culture in Right-bank Ukraine. Excavated between 1973 and 2000 by archaeologist Ihor Gereta, the site yielded 315 burials: 288 Chernyakhov, 24 Kievan Rus'', two Pomeranian, and one unidentified burial possibly from the Bronze Age. The Chernyakhov graves display both cremation and inhumation practices, with inhumed dead typically oriented north-south and accompanied by fibulae, belt buckles, bone combs, and glass vessels. The site provides key evidence for understanding the multi-ethnic Chernyakhov culture.\" -> \"The burial ground of Cherneliv-Ruskyi is a burial site of the Chernyakhov culture, an archaeological monument of local importance [1]. It is located in the Mohylky tract of the village of Cherneliv-Ruskyi in the Baikivtsi Hromada of the Ternopil Raion of the Ternopil Oblast [1]. The site was investigated between 1973 and 2000 by Ukrainian archaeologist Ihor Gereta [1]. During the excavations, 315 burials were discovered, including 288 Chernyakhov, 24 Kievan Rus'', two Pomeranian, and one unidentified burial, probably dating from the Bronze Age [1].\""}, {"source": "remediation_change_log:97276", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:97277", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:147141", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/3c1e886f/hero.webp'' -> ''/data/images/wiki/3c1e886f/Моя_Тернопільщина_Місто407.webp''"}, {"source": "remediation_change_log:247805", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:247806", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-800''"}, {"source": "remediation_change_log:348105", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:348106", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-800'' -> None"}]'::jsonb),
