    ('3c612fb4-3639-4124-8e26-58457c82376a'::uuid, 'antiquity', '8', '4', 'card-stats-2026-11-05-rollback:3c612fb4-3639-4124-8e26-58457c82376a:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Beinan Cultural Park', '67dc678a07a3114ff6d57914d3767cbf', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -3050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83252", "url": "remediation_change_log", "quote": "phase4:p4-2074:chunk-0001: description \"Beinan Cultural Park (Peinan Site Park) in Taitung City, Taiwan, contains the largest and most complete prehistoric settlement discovered in Taiwan, dating to 4500-3000 BC. The site spans over 10,000 square metres and contains more than 1,600 burial sites, making it one of the most significant archaeological sites in East Asia. Excavations have revealed sophisticated stone structures, jade artifacts, and evidence of complex social organization. The site was first documented by Japanese anthropologist Torii Ryūzō in the early 20th century and is recognized as a Potential World Heritage Site by Taiwan''s government.[1][2]\" -> ''Peinan Site Park (traditional Chinese: 卑南遺址公園; simplified Chinese: 卑南遺址公园; pinyin: Pēinán Yízhǐ Gōngyuán) is an archeological site in Taitung City, Taitung County, Taiwan [1]. The park is the site for the largest and most complete prehistoric settlement ever discovered in Taiwan [1]. The park covers an area of 10,000 square metres and contains more than 1,600 burial sites [1]. Around 20,000 pieces of jade, pottery and stone tools were also found [1].''"}, {"source