y and stone tools were also found [1].''"}, {"source": "remediation_change_log:116222", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:116223", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:116224", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: source_url ''https://en.wikipedia.org/wiki/Beinan_Cultural_Park'' -> ''https://en.wikipedia.org/wiki/Peinan_Site_Park''"}, {"source": "remediation_change_log:147153", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/3c612fb4/hero.webp'' -> ''/data/images/wiki/3c612fb4/Excavation_of_the_Peinan_Site.webp''"}, {"source": "remediation_change_log:247809", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:247810", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-500''"}, {"source": "remediation_change_log:321416", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-001: thumbnail_url ''/data/images/wiki/3c612fb4/Excavation_of_the_Peinan_Site.webp'' -> ''/data/images/wiki/3c612fb4/hero.webp''"}, {"source": "remediation_change_log:325008", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/3c612fb4/hero.webp'' -> ''/data/images/wiki/3c612fb4/Dulan Stone Wall - 4.webp''"}, {"source": "remediation_change_log:348109", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''500 BC - 1 AD'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:348110", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-500'' -> ''-3050''"}]'::jsonb),
