    ('3d20c37f-30ac-405f-8dc4-16c40e7cbeae'::uuid, 'antiquity', '4', '5', 'card-stats-2026-11-05-rollback:3d20c37f-30ac-405f-8dc4-16c40e7cbeae:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Ariconium', '7363317981ae8aa27229a1d9e6f6bc83', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 4 from period_start -100"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33685", "url": "remediation_change_log", "quote": "phase4:p4-0024:chunk-0001: description ''A Romano-British settlement at Weston under Penyard, Herefordshire, listed as a road station in the Antonine Itinerary, 15 miles from Gloucester and 11 from Monmouth. The site was a major iron-working center from the late Iron Age through the Roman period, with extensive evidence of bloom furnaces, forges, and slag deposits. Coins span from Claudius (AD 41) to Magnentius (AD 353), and finds include a bronze Diana statue, fibulae, and tessellated pavements. The settlement was abandoned c. AD 360 under unknown circumstances.'' -> ''Ariconium was a road station of Roman Britain mentioned in Iter XIII of the Iter Britanniarum of the Antonine Itineraries [1]. It was located at Bury Hill in the parish of Weston under Penyard, about 3 miles east of Ross on Wye, Herefordshire, and about 15 miles southeast of Hereford [1]. The site existed prior to the Roman era, and then came under Roman control [1]. It was abandoned, perhaps shortly after 360, but precisely when and under what circumstances is unknown [1]. Finds have included pre-Roman British coins, including one minted by Cunobelin, and coins from the Roman arrival until 360, after which there are no coins found [1].''"}, {"source": "remediation_change_log:97287", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:97288", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:97289", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:147202", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/3d20c37f/hero.webp'' -> None"}, {"source": "remediation_change_log:236655", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: site_type None -> ''Town''"}, {"source": "remediation_change_log:247815", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:247816", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-800''"}, {"source": "remediation_change_log:348114", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:348115", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-800'' -> ''-100''"}, {"source": "remediation_change_log:355624", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Town'' -> ''City/town/settlement''"}]'::jsonb),
