 the Roman arrival until 360, after which there are no coins found [1].''"}, {"source": "remediation_change_log:97287", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:97288", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:97289", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:147202", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/3d20c37f/hero.webp'' -> None"}, {"source": "remediation_change_log:236655", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: site_type None -> ''Town''"}, {"source": "remediation_change_log:247815", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:247816", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-800''"}, {"source": "remediation_change_log:348114", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:348115", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-800'' -> ''-100''"}, {"source": "remediation_change_log:355624", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Town'' -> ''City/town/settlement''"}]'::jsonb),
