    ('3d5420dd-9557-4c54-89a8-a4a8d84ea0b6'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:3d5420dd-9557-4c54-89a8-a4a8d84ea0b6:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Asseria', '0e4b71eb42acd3885303c185bd631e3d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27916", "url": "remediation_change_log", "quote": "phase3:batch-0030:chunk-0001: site_type ''Fortress/citadel'' -> ''Settlement''"}, {"source": "remediation_change_log:83280", "url": "remediation_change_log", "quote": "phase4:p4-2075:chunk-0001: description \"Ancient Liburnian hillfort and later Roman town at Podgrade near Benkovac, 30 km east of Zadar, Croatia. Occupied from the Bronze Age through the 6th century AD, it was a major centre of the Asseriates tribe before becoming a Roman municipium. Massive stone walls stretch 2.5 km, standing up to 7 metres high. The site preserves a triumphal arch erected for Emperor Trajan''s visit, a forum, an aqueduct, and distinctive Liburnian cipus tombstones.\" -> \"Asseria was an ancient settlement located at Podgrađe, Benkovac around 30 kilometres east of Zadar in Croatia [1]. In pre-Roman times Asseria was an important centre in south Liburnia for the Asseriates tribe [1]. In the 1st century AD it became a Roman military post and later developed into a market centre [1]. It lay along the important Roman road connecting the colony of Iader to the capital Salona via other towns such as Burnum [1]. Parts of Asseria''s city walls have survived, as well as a triumphal arch erected in 113 AD during the time of Trajan [1]. The city walls are of ashlar, predating Roman occupation [1]. Excavations have uncovered the 1st-century Roman forum, as well as a likely basilica [1]. Water was supplied by a 3 km-long aqueduct from the spring of Čatrnja in the village of Lisičić [1].\""}, {"source": "remediation_change_log:97294", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:97295", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s006: period_start ''1'' -> None"}, {"source": "remediation_change_log:147206", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/3d5420dd/hero.webp'' -> ''/data/images/wiki/3d5420dd/Ancient Asseria (ancient settlement in Croatia) 01.webp''"}, {"source": "remediation_change_log:247819", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:247820", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''1''"}, {"source": "remediation_change_log:309598", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-004: thumbnail_url ''/data/images/wiki/3d5420dd/Ancient Asseria (ancient settlement in Croatia) 01.webp'' -> ''/data/images/wiki/3d5420dd/Asseria,_Dalmatia_(12265922074).webp''"}, {"source": "remediation_change_log:348118", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:348119", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''1'' -> None"}, {"source": "remediation_change_log:355625", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
