    ('3d8cb484-8b57-41fa-ab0d-203449c1c821'::uuid, 'antiquity', '10', '8', 'card-stats-2026-11-05-rollback:3d8cb484-8b57-41fa-ab0d-203449c1c821:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Burrington Combe', '0566b9e53dfadfa953eb0a2b7c9b7fc7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -50000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29569", "url": "remediation_change_log", "quote": "phase3:batch-0308:chunk-0001: site_type ''Cave Structures'' -> ''Natural feature''"}, {"source": "remediation_change_log:35744", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Natural feature'' -> ''Cave Structures''"}, {"source": "remediation_change_log:43349", "url": "remediation_change_log", "quote": "phase4:p4-0073:chunk-0001: description \"Burrington Combe is a Carboniferous Limestone gorge on the north side of the Mendip Hills in North Somerset, containing entrances to numerous caves including Aveline''s Hole, Sidcot Swallet, and Goatchurch Cavern. Aveline''s Hole holds the earliest scientifically dated cemetery in Great Britain, with human bone fragments from approximately 21 individuals dated to 10,200-10,400 years ago. Beaker Age pottery and Neolithic implements were found in neighbouring depressions, while Read''s Cavern contained early Iron Age occupants buried under a rockfall. Above the gorge sits Burrington Camp, an Iron Age univallate hillfort with Romano-British elements.\" -> \"Burrington Combe is a Carboniferous Limestone gorge near the village of Burrington, on the north side of the Mendip Hills Area of Outstanding Natural Beauty, in North Somerset, England [1]. Burrington Combe is a gorge through the limestone hills although there is now no river running through it [1]. Various cave entrances are exposed which have been occupied by humans for over 10,000 years, with a hillfort being built beside the combe in the Iron Age [1]. Archaeological discoveries of early cemeteries demonstrate human occupation of the combe and its caves from the Bronze Age with some evidence of occupation during the Upper Palaeolithic period [1]. The combe contains the entrances to many of the caves of the Mendip Hills, including Aveline''s Hole, Sidcot Swallet and Goatchurch Cavern [1]. Above the combe on its eastern side is the site of an Iron Age univallate hill fort known as Burrington Camp [1]. It is around 100 metres by 80 metres and includes Romano-British elements [1].\""}, {"source": "remediation_change_log:116248", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:116249", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:147215", "url": "remediation_change_log", "quote": "served-image-2026-09-30-008: thumbnail_url ''/data/images/wiki/3d8cb484/hero.webp'' -> \"/data/images/wiki/3d8cb484/Acting all ''goat-like'' - panoramio.webp\""}, {"source": "remediation_change_log:247825", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:247826", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-4500''"}, {"source": "remediation_change_log:333754", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-001: thumbnail_url \"/data/images/wiki/3d8cb484/Acting all ''goat-like'' - panoramio.webp\" -> ''/data/imag