    ('3e25aa3a-9fb4-4e40-9989-07039d798515'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:3e25aa3a-9fb4-4e40-9989-07039d798515:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Agrour Amogjar', 'a047c7d1086462e46fcae8e3b3fe4442', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:33713", "url": "remediation_change_log", "quote": "phase4:p4-0025:chunk-0001: description ''A 690-meter peak near the Amogjar Pass in the Adrar plateau of central Mauritania, housing a series of six caves containing 24 Neolithic rock paintings over 5,000 years old. The panels depict naturalistic wildlife including giraffes, lions, and crocodiles, alongside cattle herds, geometric sunburst designs, handprints, and a notable frieze of dancers. Eight stylistic groups have been recorded, from the pastoral period to recent graffiti, reflecting an era when the Sahara was green and populated.'' -> ''The Agrour Amogjar is a 690 m high peak near the Amogjar Pass, in the Adrar plateau of central Mauritania [1]. Its small natural shelters house a rich collection of rock paintings in a damaged state [1]. The set of rock paintings is heterogeneous [1]. Eight stylistic groups have been recorded, ranging from the \"pastoral\" period to the most recent graffiti [1]. The panels are featuring geometric circles with sunburst design, handprints, naturalistic wildlife such as giraffe, lion and crocodile, as well as herds of cattle and human collective scenes [1]. The most important set is a frieze of dancers [1].''"}, {"source": "remediation_change_log:116266", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:116267", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_start ''-500'' -> None"}, {"source": "remediation_change_log:247833", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:247834", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-10000''"}, {"source": "remediation_change_log:309619", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-004: thumbnail_url ''/data/images/wiki/3e25aa3a/hero.webp'' -> ''/data/images/wiki/3e25aa3a/AgrourAmogjar6.webp''"}, {"source": "remediation_change_log:348130", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''< 4500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:348131", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-10000'' -> None"}]'::jsonb),
