    ('3e7d6ad9-37c8-4899-9956-99088ff63c78'::uuid, 'cultural_influence', '8', '6', 'card-stats-2026-11-05-rollback:3e7d6ad9-37c8-4899-9956-99088ff63c78:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''6'' restored on Annaghmare Court Tomb', 'bd7f4f8487555b222fd3774ba3a895cd', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 8 from description yes, thumbnail yes, 5 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28092", "url": "remediation_change_log", "quote": "phase3:batch-0070:chunk-0001: site_type ''Cairn'' -> ''Megalithic structures''"}, {"source": "remediation_change_log:30797", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-uk-parts: country ''Ireland'' -> ''Northern Ireland''"}, {"source": "remediation_change_log:32397", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-journal-reversal-2: site_type ''Megalithic structures'' -> ''Cairn''"}, {"source": "remediation_change_log:33715", "url": "remediation_change_log", "quote": "phase4:p4-0025:chunk-0001: description \"A Neolithic court tomb near Crossmaglen in County Armagh, Northern Ireland, also known as The Black Castle. Excavated in 1963-64 by Queen''s University Belfast, it is considered one of the best-preserved court tombs in Ireland. The cairn extends nearly 20 metres long, with a south-facing horseshoe-shaped court and a 7-metre gallery divided by jambs into three chambers. Court stones stand up to 1.9 metres high, with drystone walling between uprights. Cremated human remains were recovered from the burial chambers.\" -> ''Annaghmare Court Tomb, also known as The Black Castle, is a chamber tomb located near to the town of Crossmaglen in County Armagh [1]. The site was excavated in 1963–64, with many of its features preserved in situ [1]. Items recovered from the excavation include cremated bones of at least two individuals, animal teeth, flint tools and pottery from the Neolithic period [1]. High-quality masonry can be seen in the horizontal drystone walling between the uprights of the more than semi-circular forecourt, which leads into a long triple-chambered burial gallery [1]. The stone mound surrounding this gallery was later extended to enclose two further burial chambers entered from the side of the cairn [1].''"}, {"source": "remediation_change_log:343694", "url": "remediation_change_log", "quote": "insert-2026-10-07-010-001: thumbnail_url None -> ''/data/images/wiki/3e7d6ad9/Visitors car park at Achadh an Marbh-Annaghmare Court Tomb - geograph.org.uk - 4172658.webp''"}]'::jsonb),
