    ('3f06d44f-7bcc-4a9e-882f-c19f436b0612'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:3f06d44f-7bcc-4a9e-882f-c19f436b0612:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Stoney Littleton Long Barrow', 'e6cbe2cc6349497bb9e3ff43fc8c5da3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44163", "url": "remediation_change_log", "quote": "phase4:p4-0089:chunk-0001: description ''Stoney Littleton Long Barrow is a Neolithic chambered tomb near Wellow in Somerset, England, built between approximately 3750 and 3400 BC. The barrow measures 30 metres long and 12.5 metres wide, containing a 13-metre passage leading to three pairs of side chambers and an end chamber. Excavated by John Skinner and Richard Colt Hoare in 1816-17, it yielded bones and ashes of several men, women, and children, possibly three generations of local farmers. A notable ammonite fossil embedded at the entrance may have held ceremonial significance. Managed by English Heritage, it is one of approximately 140 Cotswold-Severn group tombs.'' -> ''The Stoney Littleton Long Barrow is a Neolithic chambered tomb with multiple burial chambers, located near the village of Wellow in the English county of Somerset [1]. It is an example of the Cotswold-Severn Group and was scheduled as an ancient monument in 1882 [1]. The stone structure is about 30 metres in length and contains a 12.8-metre long gallery with three pairs of side chambers and an end chamber [1]. Stoney Littleton Long Barrow was probably constructed around 3500 BC [1]. The tomb was first opened around 1760 by a local farmer to obtain stone for road building [1]. The site was excavated by John Skinner and Richard Hoare in 1816–17, along with a labourer Zebedee Weston [1]. The excavation revealed the bones (some burned) of several individuals [1]. The passage and entrance are roughly aligned towards the midwinter sunrise [1].''"}, {"source": "remediation_change_log:147762", "url": "remediation_change_log", "quote": "served-image-2026-09-30-009: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/2/2a/Stoney_Littleton_Long_Barrow_2015_11.jpg'' -> ''/data/images/wiki/3f06d44f/Stoney Littleton Long Barrow (35987410634).webp''"}, {"source": "remediation_change_log:309637", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-004: thumbnail_url ''/data/images/wiki/3f06d44f/Stoney Littleton Long Barrow (35987410634).webp'' -> ''/data/images/wiki/3f06d44f/Stoney_Littleton_Long_Barrow_2015_11.webp''"}]'::jsonb),
