    ('402f38a8-f484-49eb-99bb-d508093abbd3'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:402f38a8-f484-49eb-99bb-d508093abbd3:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Nine Maidens Stone Row', '25544a1288a1f31ecbb20ada26608daa', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2900"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44165", "url": "remediation_change_log", "quote": "phase4:p4-0089:chunk-0001: description ''A late Neolithic stone row in the parish of St Columb Major, Cornwall, comprising nine granite megaliths stretching approximately 108 metres in a northeast alignment. Stone heights range from 0.8 to over 2.1 metres, making them the largest stones of any known row in Cornwall. The row aligns toward a solitary menhir called the Fiddler, located roughly 800 metres to the north. Known in Cornish as Naw-voz or Naw-whoors (\"the nine sisters\"), legend holds the maidens were petrified for dancing on the Sabbath. First documented by Richard Carew in 1605.'' -> ''Nine Maidens stone row is an ancient monument in the parish of St Columb Major, Cornwall, England [1]. The Nine Maidens are also known in Cornish as Naw-voz, or Naw-whoors meaning \"the nine sisters\" [1]. This late neolithic stone row is 2 miles north of St Columb Major [1]. The row comprises nine stone megaliths and is situated in a field alongside the A39 between St Columb Major and Wadebridge [1]. The row is approximately 108 metres long, with stones varying in height from 0.8 metres to 2.1 metres [1]. The stones are irregularly spaced and aligned in a north easterly direction [1]. They are aligned towards a stone known as the Fiddler, which lies on the moorland approximately 800 metres away [1]. The stone row was first noted by historian Richard Carew in 1605 [1].''"}, {"source": "remediation_change_log:97978", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:97979", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:147812", "url": "remediation_change_log", "quote": "served-image-2026-09-30-009: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/4/4b/Nine_maiden_jpg.jpg'' -> ''/data/images/wiki/402f38a8/The Nine Maidens Standing Stones (or five of them anyway^) - panoramio.webp''"}, {"source": "remediation_change_log:247861", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:247862", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-4000''"}, {"source": "remediation_change_log:333763", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-001: thumbnail_url ''/data/images/wiki/402f38a8/The Nine Maidens Standing Stones (or five of them anyway^) - panoramio.webp'' -> ''/data/images/wiki/402f38a8/hero.webp''"}, {"source": "remediation_change_log:348153", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:348154", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-4000'' -> ''-2900''"}]'::jsonb),
