    ('415f4848-7b6c-4da9-9713-684fcb67c6a7'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:415f4848-7b6c-4da9-9713-684fcb67c6a7:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Sieben Steinhäuser', 'ae8fbd3548a09b302e3a2159f4e9f0f3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Dolmen'', ''3000 - 1500 BC'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83376", "url": "remediation_change_log", "quote": "phase4:p4-2078:chunk-0001: description ''(3500–2800 BC) The Sieben Steinhäuser is a group of five dolmens on the Lüneburg Heath in the NATO training area of Bergen-Hohne, in Lower Saxony, northern Germany. The stones are considered part of the Funnelbeaker culture. The gravesite was granted protected cultural monument status in 1923[1].'' -> ''The Sieben Steinhäuser also Siebensteinhäuser is a group of five dolmens on the Lüneburg Heath in the NATO training area of Bergen-Hohne, in the state of Lower Saxony in northern Germany [1]. The Sieben Steinhäuser gravesite was established during the third millennium BC during the Neolithic funnelbeaker period by the first settled farmers [1]. Although they are traditionally called the Sieben Steinhäuser (\"seven stone houses\") there are actually only five graves [1]. The first written record of the graves was made in 1720 by an academic [1]. The burial chambers are all rectangular and aligned in a northeast-southwest direction [1]. Their capstones are not of bay construction, but almost always supported by three or four points of contact [1]. All the graves were originally covered with earth, so that they would have looked like earth mounds or tumuli [1]. Four graves were excavated and restored between 1924 and 1937 [1].''"}, {"source": "remediation_change_log:97989", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:97990", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:147847", "url": "remediation_change_log", "quote": "served-image-2026-09-30-009: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/0/0d/Steinhaus_D_2008.jpg'' -> ''/data/images/wiki/415f4848/Sieben Steinhäuser Bernsteinanhänger, Flintartefakte Grab B@Nieders. Landesmuseum.webp''"}, {"source": "remediation_change_log:310277", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-005: thumbnail_url ''/data/images/wiki/415f4848/Sieben Steinhäuser Bernsteinanhänger, Flintartefakte Grab B@Nieders. Landesmuseum.webp'' -> ''/data/images/wiki/415f4848/Steinhaus_D_2008.webp''"}]'::jsonb),
