itute of Culture [1].''"}, {"source": "remediation_change_log:98024", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:98025", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''1'' -> None"}, {"source": "remediation_change_log:236708", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_name None -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:236709", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s003: period_start None -> ''1300''"}, {"source": "remediation_change_log:343709", "url": "remediation_change_log", "quote": "insert-2026-10-07-010-001: thumbnail_url None -> ''/data/images/wiki/43c12659/Chullpas de Molloko en Puno, Perú.webp''"}]'::jsonb),
