    ('43ee9ef2-ada7-4796-98eb-4d2ba9728d74'::uuid, 'antiquity', '5', '6', 'card-stats-2026-11-05-rollback:43ee9ef2-ada7-4796-98eb-4d2ba9728d74:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on Kintradwell Broch', 'db2a68c7cd1a8d4aeac0e6b23ec365b5', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:74325", "url": "remediation_change_log", "quote": "2026-09-26_l5-links-001: source_url ''https://en.wikipedia.org/wiki/Brora'' -> ''https://her.highland.gov.uk/Monument/MHG9777''"}, {"source": "remediation_change_log:98030", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:98031", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:98032", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: site_type ''Minaret/tower'' -> None"}, {"source": "remediation_change_log:147904", "url": "remediation_change_log", "quote": "served-image-2026-09-30-009: thumbnail_url ''/data/images/wiki/43ee9ef2/hero.webp'' -> None"}, {"source": "remediation_change_log:247881", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:247882", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-1500''"}, {"source": "remediation_change_log:336763", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4303:chunk-0001: description ''Kintradwell Broch (also known as Cinn Trolla) is an Iron Age broch on the coast a few miles north of Brora in Sutherland, Highland Scotland. Walls survive in places to 3 m in height, preserving features of broch architecture including a scarcement ledge, intramural staircase, and a well-proportioned intramural cell. When excavated by Joass before 1871, the entrance passage was found to be 2.1 m high -- unusually tall for a broch -- and a rock-cut well over 2 m deep with steps was discovered within the tower. Surrounding the broch is an extensive settlement linked by passages to the tower. Finds included iron spears, dagger blades, and a lead ring from burials in wall chambers.'' -> ''Kintradwell Broch (also known as Cinn Trolla) is an Iron Age broch on the coast north of Brora in Sutherland, Highland Scotland [1] [2] [3]. When excavated, the entrance passage was found to be 2.1 m high -- unusually tall for a broch -- and a rock-cut well over 2 m deep with steps was discovered within the tower [1]. Surrounding the broch is an extensive settlement linked by passages to the tower [1].''"}, {"source": "remediation_change_log:339659", "url": "remediation_change_log", "quote": "insert-2026-10-07-004-001: thumbnail_url None -> ''/data/images/wiki/43ee9ef2/Cinn Trolla Broch, Sutherland - geograph.org.uk - 5339442.webp''"}, {"source": "remediation_change_log:348166", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: lat ''58.010147753244'' -> ''58.048774''"}, {"source": "remediation_change_log:348167", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: lon ''-3.8500107312077168'' -> ''-3.815623''"}, {"source": "remediation_change_log:348168", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:348169", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003