    ('44428a81-cfc8-4e6b-9671-f40a385b2c4f'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:44428a81-cfc8-4e6b-9671-f40a385b2c4f:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Roman Theatre of Philippopolis', '718bced8191eccd02f11ebee220c9ee4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Theatre'', ''1 - 500 AD'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83424", "url": "remediation_change_log", "quote": "phase4:p4-2080:chunk-0001: description \"The Roman Theatre of Philippopolis is one of the world''s best-preserved ancient Roman theatres, situated in the historic centre of modern Plovdiv, Bulgaria, on the site of the ancient city of Philippopolis [1]. Constructed in the 1st century AD, likely during Domitian''s reign, the theatre originally seated between 5,000 and 7,000 spectators in its cavea [1]. The theatre remains operational today, hosting contemporary cultural performances [1].\" -> \"The Roman theatre of Philippopolis is one of the world''s best-preserved ancient Roman theatres, located in the city center of modern Plovdiv, Bulgaria, once the ancient city of Philippopolis [1]. It was constructed in the 1st century AD, probably during the reign of Domitian [1]. In outline, the theatre is a semi-circle with an outer diameter of 82 meters [1]. The theatre itself is divided into the seating section (cavea) and the stage [1]. The cavea, the area in which people gathered, is hollowed out of a hill or slope, while the outer radian seats required structural support and solid retaining walls [1]. At the end of the 4th century a large part of the theatre was destroyed [1].\""}, {"source": "remediation_change_log:147930", "url": "remediation_change_log", "quote": "served-image-2026-09-30-009: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/c/c3/Roman_Theatre_Plovdiv_3.jpg'' -> ''/data/images/wiki/44428a81/Bulgaria_Bulgaria-0780_-_Roman_Theatre_of_Philippopolis_(7432755200).webp''"}, {"source": "remediation_change_log:310313", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-005: thumbnail_url ''/data/images/wiki/44428a81/Bulgaria_Bulgaria-0780_-_Roman_Theatre_of_Philippopolis_(7432755200).webp'' -> ''/data/images/wiki/44428a81/Roman_Theatre_Plovdiv_3.webp''"}]'::jsonb),
