    ('44996991-ef99-4593-a645-74bf63d9056a'::uuid, 'cultural_influence', '7', '5', 'card-stats-2026-11-05-rollback:44996991-ef99-4593-a645-74bf63d9056a:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''5'' restored on Funzie Girt', '481f720b5be14d9b89171e78fe56ea29', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 7 from description yes, thumbnail yes, 0 content link(s), 3 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83426", "url": "remediation_change_log", "quote": "phase4:p4-2080:chunk-0001: description \"Funzie Girt (also known as Finnigirt Dyke) is an ancient wall stretching over 4 km (2.5 mi) north-south across Fetlar in Shetland, Scotland [1]. It once divided the island into two nearly equal sections [1]. Portions have vanished at the southern end, but substantial ruins remain visible across the uninhabited northern landscape, where it forms a conspicuous feature [1]. The wall''s original purpose remains unknown, as does its relationship to other contemporary archaeological sites nearby [1]. The structure is woven into local folklore and has inspired several Shetland folk music pieces [1].\" -> ''Funzie Girt is an ancient wall that was erected from north to south across the island of Fetlar in Shetland, Scotland [1]. The line of the wall, which ran for over 4 kilometres, once divided the island in two almost equal sections [1]. Also known as the Finnigirt Dyke, it has vanished in places at the southern end, although the ruins are clearly visible along much of the uninhabited north of the island [1]. The dyke\\''s original purpose is not known, nor is its relationship to other archaeological sites of a similar age nearby [1]. The name \"Funzie Girt\" means \"Finns\\'' dyke\", the Finns being the legendary pre-Norse inhabitants of the islands who were said to possess magical powers [1]. Originally 1 metre wide it begins at the north shore by the cliffs of Muckle Funziegord Geo, crosses an RSPB reserve to the west of Vord Hill, then vanishes near the enclosure of Whilsa Pund [1]. It can be seen again passing the Haltadans stone circle as it heads for the northern shore of Skutes Water [1]. The northern, and most complete section of Funzie Girt has been protected as a scheduled monument since December 1957 [1].''"}, {"source": "remediation_change_log:98035", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:98036", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:147933", "url": "remediation_change_log", "quote": "served-image-2026-09-30-009: thumbnail_url ''/data/images/wiki/44996991/hero.webp'' -> None"}, {"source": "remediation_change_log:247883", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:247884", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-800''"}, {"source": "remediation_change_log:343724", "url": "remediation_change_log", "quote": "insert-2026-10-07-010-001: thumbnail_url None -> ''/data/images/wiki/44996991/Funziegirt, south-west of Vord Hill, Fetlar - geograph.org.uk - 4308134.webp''"}, {"source": "remediation_change_log:348170", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:348171", "url": "remediation_chang