    ('44cc38c9-b726-4bff-8f59-c547b69d6dab'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:44cc38c9-b726-4bff-8f59-c547b69d6dab:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Axlor', '585ea9bfb00c1848ad9e5ddff3c843a6', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:34383", "url": "remediation_change_log", "quote": "phase4:p4-0026:chunk-0001: description ''Axlor is a Middle Paleolithic (Mousterian) cave site in Dima, Biscay, Basque Country, Spain, with deposits dating back to around 85,000 BC. Discovered and excavated by archaeologist Jose Miguel Barandiaran from 1967 to 1974, the site contains nine stratigraphic layers, five yielding Mousterian lithic artifacts. Recent zooarchaeological studies have revealed the earliest evidence of Neanderthal bird and carnivore exploitation in the Cantabrian region, demonstrating complex hunting and exploitation behaviors. [1][2]'' -> ''Axlor is a prehistoric archeological site in the village of Dima in Biscay in the Autonomous Basque Community of Spain, dating from the Middle Paleolithic or Mousterian period [1]. The archaeologist Jose Miguel Barandiaran discovered the site and directed the first excavations from 1967 until 1974 [1]. Barandiaran noted the presence of 9 different layers at the site, 5 of which contained Mousterian lithic artifacts [1]. Jose Maria Basabe studied 5 teeth from a young Neanderthal found on the site [1]. Axlor has a sequence of Middle Paleolithic levels, representing the later stages of the Mousterian in the Pyrenees region [1]. The most recent levels at Axlor are dated to approximately 42,000 years before present (using C14 radiocarbon analysis) [1]. Axlor is one of few securely-dated late Middle Palaeolithic sites in the Basque region [1]. The Neanderthals of Axlor made stone tools using flint from distant places (between 30 and 60 kilometers from the site) [1].''"}, {"source": "remediation_change_log:98039", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:98040", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-85000'' -> None"}, {"source": "remediation_change_log:147939", "url": "remediation_change_log", "quote": "served-image-2026-09-30-009: thumbnail_url ''/data/images/wiki/44cc38c9/hero.webp'' -> ''/data/images/wiki/44cc38c9/Axlor.webp''"}, {"source": "remediation_change_log:247887", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:247888", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-300000''"}]'::jsonb),
