    ('450b08c8-702f-496a-8ce0-3946c646e80a'::uuid, 'mystery', '1', '6', 'card-stats-2026-11-05-rollback:450b08c8-702f-496a-8ce0-3946c646e80a:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Cividade de Âncora', '143d4df10d7d90fac3e095e37ab66196', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''500 BC - 1 AD'') is shared by 316 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29729", "url": "remediation_change_log", "quote": "phase3:batch-0334:chunk-0001: period_start ''-1000'' -> ''-200''"}, {"source": "remediation_change_log:30388", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:34409", "url": "remediation_change_log", "quote": "phase4:p4-0027:chunk-0001: description ''Cividade de Ancora (also known as Cividade de Afife) is a Castro culture hillfort on Monte da Suavidade, at the border of the municipalities of Viana do Castelo and Caminha in northern Portugal. Built during the Iron Age in the 2nd century BC, the settlement was occupied until the Romanization of Hispania in the 1st century AD. The hill reaches 187 metres in altitude and sits just 1,250 metres from the Atlantic coast, giving the castro a commanding position over the Ancora River valley. First excavated by Francisco Martins Sarmento in 1880, the site saw its most recent archaeological intervention in 2013. Despite no evidence of post-Roman habitation, two medieval stelae were found in the area. Recovered artifacts are housed in the municipal museums of Caminha and Viana do Castelo.'' -> ''The Cividade de Âncora (also known as Cividade de Afife) is an archaeological site of the Castro culture located in Afife and Âncora, at the border of the municipalities of Viana do Castelo and Caminha [1]. The Cividade was built during the Iron Age (2nd Century BCE) and was occupied up to the Romanization of Hispania (1st Century CE) [1]. The Cividade was first dug in 1880 by Francisco Martins Sarmento and the last intervention was in 2013 [1]. The Cividade was built on the Monte da Suavidade (\"Hill of Softness\"), overseeing the Âncora River [1]. The hill has a maximum height of 187 metres (614 ft) and is 1,250 metres (4,100 ft) from the sea [1]. The Cividade\\''s cemetery was located within the residential section of the Cividade [1]. The houses were of circular and oval shape, made of stone walls and ceilings of perishable materials [1].''"}, {"source": "remediation_change_log:116321", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: site_type ''City/town/settlement'' -> ''Settlement''"}, {"source": "remediation_change_log:310331", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-005: thumbnail_url ''/data/images/wiki/450b08c8/Cividade de Afife (52698744620).webp'' -> ''/data/images/wiki/450b08c8/Cividade_de_Afife_(52697809777).webp''"}, {"source": "remediation_change_log:355634", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
