    ('45b4e76d-0430-4abe-acfd-af61e2938421'::uuid, 'mystery', '8', '10', 'card-stats-2026-11-05-rollback:45b4e76d-0430-4abe-acfd-af61e2938421:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Sklavokampos', '1c8513708ee8c68a2633bed31aba578d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Residence/villa/farmhouse'', ''1500 - 500 BC'') is shared by 5 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83460", "url": "remediation_change_log", "quote": "phase4:p4-2081:chunk-0001: description ''Sklavokampos (also Sklavokambos) is an archaeological site of a Minoan settlement in central Crete, located in the Malevizi municipality, approximately 13 kilometers southwest of Heraklion [1]. The settlement was occupied during the Late Minoan period (roughly 3000-1500 BC). The site was discovered during road construction to Anogeia and first excavated in the 1930s [1]. Excavations revealed a multiple-story building with a main room yielding a clay ox head in LMIB style [1].'' -> ''Sklavokampos is the archaeological site of an ancient Minoan settlement in Crete, used during the Late Minoan period [1]. Sklavokampos is southwest of Tylissos, at the road that connects in with Anogeia, 22 kilometres from Heraklion [1]. The site was discovered while constructing a road to Anogeia and was first excavated in the 1930s [1]. A multiple-story building was found at the site [1]. Its main room yielded a clay ox head, a LMIB style jug and a stone rhyton [1]. The building had at least 17 rooms [1]. Finds from an upper story included 39 sealings, a cylindrical vessel, a stone hammer and a clay foot [1].''"}, {"source": "remediation_change_log:116327", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: lat ''35.29412372562346'' -> ''35.2953''"}, {"source": "remediation_change_log:116328", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: lon ''25.008609885852838'' -> ''24.958''"}, {"source": "remediation_change_log:116329", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_name ''3000 - 1500 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:116330", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: period_start ''-2000'' -> ''-1500''"}, {"source": "remediation_change_log:116331", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s003: site_type ''City/town/settlement'' -> ''Villa''"}, {"source": "remediation_change_log:148513", "url": "remediation_change_log", "quote": "served-image-2026-09-30-010: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/0/05/%CE%9C%CE%B9%CE%BD%CF%89%CE%B9%CE%BA%CE%AE_%CE%B1%CE%B3%CF%81%CE%BF%CE%B9%CE%BA%CE%AF%CE%B1_%CE%A3%CE%BA%CE%BB%CE%B1%CE%B2%CF%8C%CE%BA%CE%B1%CE%BC%CF%80%CE%BF%CF%85_2969.jpg'' -> ''/data/images/wiki/45b4e76d/Sklavokambos Minoische Villa 05.webp''"}, {"source": "remediation_change_log:321463", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-001: thumbnail_url ''/data/images/wiki/45b4e76d/Sklavokambos Minoische Villa 05.webp'' -> ''/data/images/wiki/45b4e76d/hero.webp''"}, {"source": "remediation_change_log:325015", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/45b4e76d/hero.webp'' -> ''/data/images/wiki/45b4e76d/Μινωική αγροικία Σκλαβόκαμπου 2969.webp''"}, {"source": "remediation_change_log:355635", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s001: site_type ''Villa'' -> ''Residence/villa/farmhouse''"}]'::jsonb),
