    ('474fa9e0-74cc-4a87-9cac-dd7dbe83ddd5'::uuid, 'antiquity', '9', '4', 'card-stats-2026-11-05-rollback:474fa9e0-74cc-4a87-9cac-dd7dbe83ddd5:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Cave of Salemas', '6238637edd5cb2ebbc6f9dc41c12badf', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 9 from period_start -4501"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:91704", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4003:chunk-0001: description \"A solutional cave near the village of Lousa in Loures municipality, Lisbon District, Portugal, situated in a Cretaceous limestone outcrop. First explored in 1959 by L. Albuquerque e Castro and fully excavated by the Geological Survey of Portugal in 1959-1960, radiocarbon dating places human remains at approximately 25,000 to 20,000 years ago. Lower levels yielded Solutrean lithic and bone tools alongside fauna including brown bears, cave bears, leopards, and hyenas, while upper Neolithic layers contained ceramics and human bones from a necropolis. Artifacts are held in Lisbon''s Geological Museum.\" -> None"}, {"source": "remediation_change_log:98094", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:98095", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-500'' -> None"}, {"source": "remediation_change_log:148578", "url": "remediation_change_log", "quote": "served-image-2026-09-30-010: thumbnail_url ''/data/images/wiki/474fa9e0/hero.webp'' -> ''/data/images/wiki/474fa9e0/CaveSalemas3.webp''"}, {"source": "remediation_change_log:248237", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s007: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:248238", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s007: period_start None -> ''-500''"}, {"source": "remediation_change_log:321471", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-001: thumbnail_url ''/data/images/wiki/474fa9e0/CaveSalemas3.webp'' -> ''/data/images/wiki/474fa9e0/hero.webp''"}, {"source": "remediation_change_log:325016", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/474fa9e0/hero.webp'' -> ''/data/images/wiki/474fa9e0/CaveSalemas4.webp''"}, {"source": "remediation_change_log:338499", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4325:chunk-0001: description None -> \"The Cave of Salemas is a cave in a Cretaceous limestone outcrop near the village of Lousa, in the municipality of Loures in Portugal''s Lisbon District [1]. People appear to have used the cave as a temporary refuge during the Upper Paleolithic and as a tomb in the Neolithic [1]. The cave stands roughly 100 metres north of the Neolithic dolmen called the Anta do Alto da Toupeira [1]. A team from the Geological Survey of Portugal excavated the cave in two digs, in November 1959 and from October to December 1960 [1]. Carbon dating placed the human bones and one Paleolithic tooth at around 25,000 to 20,000 years ago [1]. Neolithic materials such as ceramic items came from the top excavated levels together with human bones consistent with a necropolis [1].\""}, {"source": "remediation_change_log:348187", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:348188", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-500'' -> ''-4501''"}]'::jsonb),
