    ('498589cb-b378-4a09-adc3-3a911dc1cd77'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:498589cb-b378-4a09-adc3-3a911dc1cd77:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Lake Bolac Stone Arrangement', '0dcd3dae43e096d98ac31321315c001d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83534", "url": "remediation_change_log", "quote": "phase4:p4-2083:chunk-0001: description ''The Lake Bolac Stone Arrangement, also known as the Kuyang Stone Arrangement, is an Aboriginal ceremonial site in Victoria, Australia. Basalt stones are arranged in a 176-metre crescent pattern widely understood to depict a giant eel. It served as a gathering place for the Wada wurrung, Girai wurrung, and Djab wurrung peoples, with colonial records from 1841 noting gatherings of 800 to 1,000 Aboriginal people during eeling season. Registered on the Victorian Aboriginal Heritage Register since 1975, the site may have functioned as an astronomical indicator or aquacultural trap.'' -> ''The Lake Bolac stone arrangement, also known as the Kuyang stone arrangement, is an Aboriginal ceremonial site near the town of Lake Bolac in the Western District, north-east of Hamilton, Victoria [1]. It is one of several Aboriginal stone arrangements scattered across Australia [1]. It was registered on the Victorian Aboriginal Heritage Register in 1975 [1]. The basalt stones are arranged in two lines and are said to resemble a giant eel [1]. The stones vary in size from about 30 centimetres to 150 centimetres, with some possibly having been embedded in holes in the ground so as to make them stand upright [1]. The Lake Bolac ceremonial site, and the similar Wurdi Youang site, were identified as being Aboriginal structures on the basis that there was \"no counterpart among colonial structures and there was no evidence that they ever formed part of any type of fence or building\" [1]. At some stage, some of the stones were removed to make way for a road [1].''"}, {"source": "remediation_change_log:98119", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:98120", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:248253", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s007: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:248254", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s007: period_start None -> ''-4000''"}, {"source": "remediation_change_log:348197", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:348198", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-4000'' -> None"}]'::jsonb),
