    ('4a42b149-b113-4896-a907-24b21f8b36ec'::uuid, 'mystery', '4', '5', 'card-stats-2026-11-05-rollback:4a42b149-b113-4896-a907-24b21f8b36ec:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Duloe Stone Circle', 'bd7e1d8ae0b4d043602e2b970ad70a22', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Stone circle'', ''3000 - 1500 BC'') is shared by 57 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83542", "url": "remediation_change_log", "quote": "phase4:p4-2083:chunk-0001: description ''Duloe Stone Circle is the smallest stone circle in Cornwall but features the largest stones of any Cornish circle, uniquely constructed from white quartz rather than the typical granite. The oval ring measures 11.7m by 10.2m and comprises eight stones, with four larger stones (up to 9 tons each) positioned at cardinal points and four smaller stones between them. Dating from the later third to early second millennia BC, the circle likely served as a community gathering place for ceremonies and rituals. First recorded in 1801, a hedge bisecting the circle was removed in 1858, and during re-erection of three stones in 1863 a Bronze Age urn containing cremated human bones was discovered, suggesting the ring may encircle a burial barrow.'' -> ''Duloe stone circle or Duloe circle is a stone circle near the village of Duloe, located 5 miles from Looe in southeast Cornwall, England [1]. Stones vary in height, the largest on the south being over 12 tons and 2.65 metres high [1]. The dimensions in a north–south direction are 11.9 metres by 10.7 metres [1]. Its original width is unknown as it was moved in 1861 due to an intersecting hedge [1]. Two of the stones were broken in the manoeuvre [1].''"}, {"source": "remediation_change_log:98125", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:98126", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:148691", "url": "remediation_change_log", "quote": "served-image-2026-09-30-010: thumbnail_url ''/data/images/wiki/4a42b149/hero.webp'' -> ''/data/images/wiki/4a42b149/1006714-DuloeStoneCircle (1).webp''"}, {"source": "remediation_change_log:237549", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:237550", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_start None -> ''-2000''"}, {"source": "remediation_change_log:310405", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-005: thumbnail_url ''/data/images/wiki/4a42b149/1006714-DuloeStoneCircle (1).webp'' -> ''/data/images/wiki/4a42b149/Duloe Stone Circle - geograph.org.uk - 1242170.webp''"}]'::jsonb),
