    ('4c648b74-8558-41c8-a195-12ed6fea4984'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:4c648b74-8558-41c8-a195-12ed6fea4984:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Cuckoo Stone', 'f77963c103ea3f0a7c921f96459e756d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Megalithic stones'', ''3000 - 1500 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83582", "url": "remediation_change_log", "quote": "phase4:p4-2084:chunk-0001: description \"The Cuckoo Stone is a Neolithic or Bronze Age sarsen standing stone, now fallen on its side, located in a field near Woodhenge and Durrington Walls in Wiltshire, England, part of the wider Stonehenge World Heritage landscape. The stone is the same type of sarsen as the largest monoliths at Stonehenge, approximately 2.5 km to the southwest. Excavated in 2007 as part of the Stonehenge Riverside Project, the dig revealed the pit in which the stone once stood immediately to the west. Geochemical analysis indicates it was likely transported from West Woods on the Marlborough Downs, the same source that supplied Stonehenge''s large sarsens.\" -> ''The Cuckoo Stone is a Neolithic or Bronze Age standing stone [1]. The stone, which is now fallen, is in a field near to Woodhenge and Durrington Walls in Wiltshire, England [1]. It is part of the wider Stonehenge Landscape [1]. The Cuckoo Stone is a squat sarsen stone which lies on its side [1]. It is the same type of stone as the largest stones used in the Stonehenge circle [1]. The site was excavated in 2007 as part of the Stonehenge Riverside Project [1]. The stone was originally a natural feature, which sometime before 2000 BC, was placed in an upright position [1]. Around 2000 BC the Cuckoo Stone became the focus for several nearby cremation burials [1].''"}, {"source": "remediation_change_log:148800", "url": "remediation_change_log", "quote": "served-image-2026-09-30-010: thumbnail_url ''/data/images/wiki/4c648b74/hero.webp'' -> ''/data/images/wiki/4c648b74/Cuckoo Stone Near Woodhenge, Durrington June 2015. - panoramio.webp''"}, {"source": "remediation_change_log:310433", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-005: thumbnail_url ''/data/images/wiki/4c648b74/Cuckoo Stone Near Woodhenge, Durrington June 2015. - panoramio.webp'' -> ''/data/images/wiki/4c648b74/Cuckoo_Stone_1.webp''"}]'::jsonb),
