    ('4d0928dd-8050-4e45-a9d2-f9a8331fa425'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:4d0928dd-8050-4e45-a9d2-f9a8331fa425:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Saraakallio Rock Paintings', '63f392db4566414feba5fb93830e4809', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Rock art'', ''< 4500 BC'') is shared by 29 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83770", "url": "remediation_change_log", "quote": "phase4:p4-2085:chunk-0001: description \"The Saraakallio Rock Paintings are prehistoric petroglyphs in Central Finland, dating to 4500–3000 BC [1]. Located on the eastern shore of Lake Saraavesi in Laukaa, the site features two distinct art areas—Saraakallio I and Saraakallio II—on a prominent cliff face overlooking the Keitele Canal [1]. The paintings depict elk, humans, and abstract symbols, representing some of Finland''s oldest surviving rock art [1].\" -> ''Saraakallio rock paintings are situated on the Saraakallio cliff in Laukaa, Central Finland [1]. The rock site lies on the eastern shore of Lake Saraavesi [1]. An important water route, the Keitele Canal, runs in front of the paintings [1]. There are two art areas, Saraakallio I and Saraakallio II [1]. It is difficult to count and list all the paintings of Saraakallio, partly because they are so many and varied, and also because many of them are blurred, fragmentary or have been painted over [1]. The pictures number between 50–200, making it the biggest rock art area in Finland [1]. The oldest paintings are circa 6,600 years old [1]. The most common themes in Saraakallio paintings are deer, human, and boat figures [1].''"}, {"source": "remediation_change_log:98167", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:98168", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:149408", "url": "remediation_change_log", "quote": "served-image-2026-09-30-011: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/3/3d/Laukaa_-_rock_painting2.jpg'' -> ''/data/images/wiki/4d0928dd/Kalliomaalaukset Saraakalliolla.webp''"}, {"source": "remediation_change_log:237568", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:237569", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_start None -> ''-5000''"}, {"source": "remediation_change_log:310451", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-005: thumbnail_url ''/data/images/wiki/4d0928dd/Kalliomaalaukset Saraakalliolla.webp'' -> ''/data/images/wiki/4d0928dd/Laukaa_-_rock_painting2.webp''"}]'::jsonb),
