    ('4df3dcbd-62d3-4e37-92fe-e79989233f1f'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:4df3dcbd-62d3-4e37-92fe-e79989233f1f:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on La Pintada', '460520283ebea4ecf000b1bc33d21dad', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:83800", "url": "remediation_change_log", "quote": "phase4:p4-2086:chunk-0001: description ''La Pintada is an archaeological site in the Sierra Libre, about 60 km south of Hermosillo, Sonora, Mexico, considered one of the most important cave painting areas in northwestern Mexico. The canyon contains over 2,500 catalogued rock art images including cave paintings and engravings depicting animals such as birds, deer, and reptiles, believed to be cosmo-vision representations created about 1,200 years ago. The site served diverse groups including hunter-gatherers during the 12th-13th centuries and later Seri, Yaqui, and Pima peoples who used it as a ritual center between the 17th-18th centuries. Outside the canyon, seasonal camping grounds attest to prolonged occupation.'' -> ''La Pintada is an archaeological site located some 60 kilometers south of the city of Hermosillo, Sonora, Mexico, within the \"La Pintada\" canyon, part of the \"Sierra Libre\" [1]. La Pintada comprises two different archaeological components; within the Canyon are cave paintings and rock engravings, while outside, on the alluvial plain of the Canyon are vestiges of various seasonal camping grounds in an extensive area, characterized by a concentration of archaeological material: ceramic, stone tools [1]. Most of the archaeological materials found in these grounds, are within the archaeological tradition known as Central Coast, and are particularly similar to those found by Edward Mosler and Thomas Bowen at sites in the region of Tastiota and Punta San Antonio in the southern part of the Central Coast area [1]. So far, La Pintada is the site associated with that archaeological tradition farther away from the coastline [1].''"}, {"source": "remediation_change_log:98173", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:98174", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''500'' -> None"}, {"source": "remediation_change_log:149419", "url": "remediation_change_log", "quote": "served-image-2026-09-30-011: thumbnail_url ''/data/images/wiki/4df3dcbd/hero.webp'' -> None"}, {"source": "remediation_change_log:248281", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s007: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:248282", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s007: period_start None -> ''-10000''"}, {"source": "remediation_change_log:348217", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''< 4500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:348218", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-10000'' -> None"}]'::jsonb),
