    ('4ff99d9d-a0a1-4056-87a7-a9e9f517440e'::uuid, 'antiquity', '5', '6', 'card-stats-2026-11-05-rollback:4ff99d9d-a0a1-4056-87a7-a9e9f517440e:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on Ancient Pydna', 'c3bb40c81bf87daa193bf79b4afa4f52', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43505", "url": "remediation_change_log", "quote": "phase4:p4-0074:chunk-0001: description \"Pydna was an ancient Greek city in Pieria, Central Macedonia, situated directly on the Aegean Sea coast, approximately 16 km northeast of Katerini and 2.5 km from Makrygialos village [1]. The site contains two Macedonian tombs discovered by French archaeologist Leon Heuzey during his Greek travels in the mid-19th century [1]. Nearby, the fortress-like bishop''s seat of Louloudies lies a few kilometers to the south [1]. The archaeological site is open Monday through Friday from 8:00 to 14:00, with free admission [2].\" -> ''At the site of the ancient Pydna, the visible buildings are from the Byzantine era [1]. The remains of the ancient Polis from the Classical, Hellenistic and, possibly, pre-Greek period are lying, at least partly, under the Byzantine buildings [1]. The entire complex measures 320 m by 130 m [1]. The northern necropolis contains more than 3300 graves [1].''"}, {"source": "remediation_change_log:98844", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:98845", "url": "remediation_ch