    ('5077f16f-1d87-4be3-a870-35f3e1cf55fe'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:5077f16f-1d87-4be3-a870-35f3e1cf55fe:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Nobbin', '0668d39104ce34551c50adf460b560e1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:34489", "url": "remediation_change_log", "quote": "phase4:p4-0029:chunk-0001: description ''A village on the Wittow peninsula of Rugen island in the German Baltic Sea, best known for the Riesenberg megalithic tomb dating to the Funnel Beaker Culture (c. 4100-2800 BC). One of the largest stone graves in northern Germany, the trapezoidal enclosure measures 34 metres long and 8 to 11 metres wide, originally containing 53 boundary stones of which 39 survive. Two rare guardian stones (Wachtersteine) exceeding 3 metres in height mark the southwestern entrance, reflecting Scandinavian dolmen traditions. Excavations in 1970 by Ewald Schuldt uncovered arrowheads, ceramic fragments, two skulls, and notably a 9th-century Arabic silver coin, attesting to millennia of site significance.'' -> ''Nobbin is best known for the megalithic tomb known as the Riesenberg (also Großsteingrab Riesenberg) [1]. The tomb was constructed of glacial erratic boulders and dates back to the New Stone Age in Rügen [1]. It is one of the largest stone graves in North Germany and lies just a few metres from the steep coast on the bay of Tromper Wiek [1]. The trapezoidal enclosure, which originally had 53 large boundary stones, is 34 metres long and 8 to 11 metres wide (39 stones have survived) [1]. In the north-east were two transverse dolmens, of which only one is well preserved [1]. It is 1.4 metres high, 1.8 metres long and 1.1 metres wide [1].''"}, {"source": "remediation_change_log:117538", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: period_name ''< 4500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:117539", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: period_start ''-5000'' -> ''-3500''"}, {"source": "remediation_change_log:117540", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: source_url ''https://en.wikipedia.org/wiki/Nobbin'' -> ''https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Nobbin''"}, {"source": "remediation_change_log:149505", "url": "remediation_change_log", "quote": "served-image-2026-09-30-011: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/9a/Riesenberg_Nobbin.jpg'' -> ''/data/images/wiki/5077f16f/Riesenberg_Nobbin.webp''"}]'::jsonb),
