    ('50abd026-06c4-4790-a102-26da88b3eae4'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:50abd026-06c4-4790-a102-26da88b3eae4:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Wéris Megaliths', 'cc516933e1524f11fadfba835ab7cae3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Megalithic stones'', ''4500 - 3000 BC'') is shared by 17 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84308", "url": "remediation_change_log", "quote": "phase4:p4-2087:chunk-0001: description ''The Wéris megaliths are a group of megalithic monuments near the village of Wéris in the Belgian province of Luxembourg [1].'' -> ''The Wéris megaliths are a group of megalithic monuments found near the village of Wéris, in the province of Luxembourg, in Belgium [1]. The megalithic remains at Wéris are scattered over a region more than 5 miles long and form a group which is unique in Belgium [1]. There are many standing stones, including one beside the road just southwest of Wéris [1]. Of the many chamber tombs (dolmens) which once existed in the area, two now survive in good condition [1]. These remains generally date to around 3000 BC, a time period which corresponds to that of the Seine-Oise-Marne culture [1]. The dolmens are made from slabs of conglomerate stone [1]. A notable feature of the two dolmens is that the funerary chamber and the ante-chamber are separated by a stone slab pierced with a circular opening [1].''"}, {"source": "remediation_change_log:117542", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: lat ''50.326178057935174'' -> ''50.33348''"}, {"source": "remediation_change_log:117543", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: lon ''5.531032183658238'' -> ''5.52263''"}, {"source": "remediation_change_log:149510", "url": "remediation_change_log", "quote": "served-image-2026-09-30-011: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/3/32/W%C3%A9ris_Dol1a_JPG.jpg'' -> ''/data/images/wiki/50abd026/Wéris_Dol1a_JPG.webp''"}]'::jsonb),
