    ('50f9ccc8-06b1-4283-af88-a6769d0b9083'::uuid, 'mystery', '4', '5', 'card-stats-2026-11-05-rollback:50f9ccc8-06b1-4283-af88-a6769d0b9083:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Nine Stones, Winterbourne Abbas', '366caf32be85fa08acb047d259ea4ad2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Stone circle'', ''3000 - 1500 BC'') is shared by 57 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28224", "url": "remediation_change_log", "quote": "phase3:batch-0097:chunk-0001: period_start ''-4500'' -> ''-3300''"}, {"source": "remediation_change_log:34493", "url": "remediation_change_log", "quote": "phase4:p4-0029:chunk-0001: description ''A late Neolithic to early Bronze Age stone circle near Winterbourne Abbas in Dorset, dating to approximately 2000 BC. The circle has a maximum diameter of about 8 metres and consists of nine irregularly shaped stones ranging from 0.5 to 1.5 metres in height. Two notably larger stones on the northwest side, separated by a 3-metre gap suggesting a ceremonial entrance, distinguish the monument. Its valley-bottom location is described as very unusual for such monuments, and it is one of only four surviving stone circles in south Dorset. Managed by English Heritage.'' -> \"The Nine Stones, also known as the Devil''s Nine Stones, the Nine Ladies, or Lady Williams and her Dog, is a stone circle located near to the village of Winterbourne Abbas in the southwestern English county of Dorset [1]. The Nine Stones is part of a tradition of stone circle construction that spread through much of Great Britain, Ireland, and Brittany between 3,300 and 900 BCE, during the Late Neolithic and Early Bronze Age [1]. The Nine Stones circle is positioned at the national grid reference 36100904, on the western edge of the village of Winterbourne Abbas in Dorset [1]. The roots of a beech tree have engulfed two of the megaliths in the circle [1]. Seven of the nine surviving stones are under 90 centimetres tall, but two of the northwestern stones are considerably larger [1]. The circle is located at the bottom of a narrow valley [1]. In the nineteenth century the site was visited by the antiquarian Charles Warne, who wrote about it in his 1872 book Ancient Dorset [1].\""}, {"source": "remediation_change_log:35766", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-3300'' -> ''-4500''"}, {"source": "remediation_change_log:84222", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:84223", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:149521", "url": "remediation_change_log", "quote": "served-image-2026-09-30-011: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/3/3b/The_Winterbourne_Abbas_Nine_Stones_-_geograph.org.uk_-_25044.jpg'' -> ''/data/images/wiki/50f9ccc8/Nine_Stones,_Dorset.webp''"}, {"source": "remediation_change_log:302122", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:302123", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-2500''"}]'::jsonb),
