culture [1].''"}, {"source": "remediation_change_log:98877", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:98878", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_start ''-40000'' -> None"}, {"source": "remediation_change_log:149535", "url": "remediation_change_log", "quote": "served-image-2026-09-30-011: thumbnail_url None -> \"/data/images/wiki/51c8708e/Bulletins de l''Académie royale des sciences, des lettres et des beaux-arts de Belgique (1867) (20501488455).webp\""}, {"source": "remediation_change_log:248317", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s007: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:248318", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s007: period_start None -> ''-500''"}, {"source": "remediation_change_log:348243", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:348244", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-500'' -> None"}]'::jsonb),
