    ('525dac17-d918-4dd5-9f58-6bc00715525e'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:525dac17-d918-4dd5-9f58-6bc00715525e:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Carwynnen Quoit', '8660ad0a9399d1b7fc80fe8d3e8ea9d8', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Dolmen'', ''3000 - 1500 BC'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29127", "url": "remediation_change_log", "quote": "phase3:batch-0243:chunk-0001: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:30398", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:84344", "url": "remediation_change_log", "quote": "phase4:p4-2088:chunk-0001: description \"Carwynnen Quoit is a Neolithic portal dolmen located at Carwynnen near Camborne in west Cornwall, England[1]. The monument, also known as ''The Giant''s Quoit'', ''The Giant''s Frying Pan'', ''Pendarvis Quoit'' and ''Pendarves Quoit'', is one of only a handful of such ancient structures in Cornwall[1]. The structure collapsed in 1966, remaining in ruins until a community-led restoration project re-erected it in 2014[2]. This ancient monument represents a rare surviving example of Neolithic funerary architecture in South-West England[1].\" -> \"Carwynnen Quoit is a dolmen belonging to the Neolithic period, at Carwynnen near Camborne in west Cornwall [1]. It is also known as ''The Giant''s Quoit'', ''The Giant''s Frying Pan'', ''Pendarvis Quoit'' and ''Pendarves Quoit'' [1]. It collapsed in 1966 and was re-erected in 2014 [1]. Carwynnen Quoit is one of an ancient and rare group of monuments and can be found at Carwynnen in Cornwall [1]. It is a portal dolmen belonging to the Neolithic period, built around 3000 BC, one of the few Cornish portal dolmens to be found outside the Penwith peninsula [1]. It is situated on a gentle west-facing slope between two small tributaries to the Red River [1]. The dolmen stands to a height of 1.5 metres with a capstone measuring around 3.3 metres long by 2.5 metres wide and 30 cm thick and weighs around 10 tons [1]. The site was first recorded by the Welsh antiquarian Edward Lhuyd around 1700 and a symbol of the cromlech appeared on Martyn''s 1748 map of Cornwall [1].\""}]'::jsonb),
