    ('539b56ad-5705-40c1-848b-767710247e7c'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:539b56ad-5705-40c1-848b-767710247e7c:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Lligwy Burial Chamber', 'b306b7cd5516124a01117ccb7113f406', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Dolmen'', ''3000 - 1500 BC'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84378", "url": "remediation_change_log", "quote": "phase4:p4-2089:chunk-0001: description \"Neolithic dolmen on Anglesey''s east coast, built before 4500 BC. A circle of upright stones supports a massive 25‑tonne capstone, creating a low burial chamber. The 1909 excavation uncovered human remains from approximately 15–30 individuals, along with Late Neolithic pottery. Situated near Moelfre village, it lies just metres from the road.[1][2][3]\" -> ''Lligwy Burial Chamber is a Neolithic burial chamber in Lligwy, near the east coast of Anglesey, Wales [1]. It consists of a circle of upright stones, made into a low chamber by a very large roof slab estimated at 25 tonnes [1]. Excavation in 1909 found the remains of some 15 to 30 people, and pottery suggesting a Late Neolithic date [1]. The eight uprights which support the massive capstone are larger than they at first appear, because half of their 2 m height is buried in the ground [1]. The capstone is about 5.5 m long and 4.5 m wide, with a thickness of around 1 m [1]. It is estimated to weigh about 25 tonnes and is in contact with only three of the uprights [1].''"}, {"source": "remediation_change_log:98911", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''< 4500 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:98912", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_start ''-5000'' -> ''-2500''"}, {"source": "remediation_change_log:149574", "url": "remediation_change_log", "quote": "served-image-2026-09-30-011: thumbnail_url ''/data/images/wiki/539b56ad/hero.webp'' -> ''/data/images/wiki/539b56ad/Lligwy Burial Chamber with background fence.webp''"}, {"source": "remediation_change_log:311134", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/539b56ad/Lligwy Burial Chamber with background fence.webp'' -> ''/data/images/wiki/539b56ad/Lligwy_Burial_Chamber_in_Anglesey.webp''"}]'::jsonb),
