    ('54e625b7-a84e-4502-b43a-e65734d928c7'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:54e625b7-a84e-4502-b43a-e65734d928c7:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Lefkaritis Tomb', 'e6d9ec4d41e7958d8761f3abd2c5279a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Necropolis/tombs complex'', ''1500 - 500 BC'') is shared by 24 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84578", "url": "remediation_change_log", "quote": "phase4:p4-2090:chunk-0001: description \"The Lefkaritis Tomb is an 8th-century BC hypogeum discovered in 1998 within the city walls of ancient Kition (modern Larnaca), Cyprus. Unlike most burials in Kition''s external necropolis, this intact built chamber tomb was found sealed for nearly 2,800 years, providing reliable chronological data for Iron Age burial practices. Among the artifacts recovered were extraordinary gold ornaments, transferred to the Cyprus Museum for conservation. The tomb is attributed to Kition''s social elite and represents one of the earliest built burial structures in the necropolis, dating to the late Cypro-Geometric or very early Cypro-Archaic period.\" -> ''The Lefkaritis Tomb is a hypogeum (a type of tomb) in Larnaca, Cyprus [1]. It was discovered in 1998 in an \"un-looted chamber that had been sealed nearly 2800 years ago\" in the city-kingdom of Kition [1]. Among the \"few objects found\", were \"extraordinary gold ornaments\", which were moved to Cyprus Museum for conservation [1]. The tomb was discovered in the vicinity of the residence of Dino Lefkaritis, hence the name Lefkaritis Tomb [1].''"}, {"source": "remediation_change_log:98927", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:98928", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:237632", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:237633", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_start None -> ''-800''"}]'::jsonb),
