    ('55ac13ab-3693-4e65-af02-a6b424d0e345'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:55ac13ab-3693-4e65-af02-a6b424d0e345:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Roman Τheatre of Bosra', 'afbc75c94d1d44bbee4f094549d8c4e2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Theatre'', ''1 - 500 AD'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84582", "url": "remediation_change_log", "quote": "phase4:p4-2090:chunk-0001: description ''A remarkably preserved 2nd-century Roman theatre in Bosra, southwestern Syria, likely built during the reign of Trajan. Constructed of black basalt, the theatre seats approximately 15,000 spectators with a stage 45 m long and 8 m deep, measuring 102 m across. It is the only Roman theatre with its upper gallery in the form of a covered portico fully preserved. Later enclosed within an Ayyubid fortress, the sand accumulation during medieval reuse fortuitously protected the interior. Part of the Ancient City of Bosra UNESCO World Heritage Site since 1980, it was placed on the World Heritage in Danger list in 2013 due to the Syrian Civil War.'' -> ''The Roman Theatre at Bosra is a large Roman theatre in Bosra, in the district of Daraa in south-western Syria [1]. The theatre was originally built outside the walls of the town, but was later completely enclosed by an Ayyubid fortress [1]. The theatre is 102 metres across and has seating for about 17,000 people; it is thus among the largest of the Ancient Roman civilisation [1].''"}, {"source": "remediation_change_log:149641", "url": "remediation_change_log", "quote": "served-image-2026-09-30-011: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/0/02/Syria_bosra_theater.jpg'' -> ''/data/images/wiki/55ac13ab/Jebel el-Druze & Hauran. Basra Eski Sham. The castle surrounding the Roman theatre, XIII cent. LOC matpc.03729.webp''"}, {"source": "remediation_change_log:311161", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/55ac13ab/Jebel el-Druze & Hauran. Basra Eski Sham. The castle surrounding the Roman theatre, XIII cent. LOC matpc.03729.webp'' -> ''/data/images/wiki/55ac13ab/Syria_bosra_theater.webp''"}]'::jsonb),
