    ('55da0a74-b7fc-4b66-a104-e6b32df0e8e3'::uuid, 'antiquity', '8', '10', 'card-stats-2026-11-05-rollback:55da0a74-b7fc-4b66-a104-e6b32df0e8e3:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Ballochmyle Cup and Ring marks', '230569ebe65ce5ab30f1faa72ac6ae82', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -4000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84584", "url": "remediation_change_log", "quote": "phase4:p4-2090:chunk-0001: description \"4500–3000 BC: The Ballochmyle Cup and Ring marks are carved on a vertical red Permian sandstone cliff at Ballochmyle, Mauchline, East Ayrshire, Scotland [1]. First recorded in 1986, they form one of Britain''s most extensive rock carving sites, spread across two panels [1]. The pink desert sandstone displays clear dune bedding and has been designated a scheduled monument [1][2].\" -> \"The Ballochmyle cup and ring marks were first recorded at Ballochmyle, Mauchline, East Ayrshire, Scotland in 1986, very unusually carved on a vertical red sandstone cliff face, forming one of the most extensive areas of such carvings as yet found in Britain [1]. They have been designated a scheduled monument [1]. The cup and ring marks are composed of two ''panels'' with several hundred ''cup and ring'' and other glyphs or carvings in a range of styles [1]. Less common, but unique in the Scottish context are ‘square with cup’ carvings; ‘ringed stars’ are also present [1]. The soft nature of the stone at Ballochmyle gives insights into how the glyphs were created with many small holes that could not have been formed by a hammering action [1].\""}, {"source": "remediation_change_log:98935", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:98936", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:150140", "url": "remediation_change_log", "quote": "served-image-2026-09-30-012: thumbnail_url ''/data/images/wiki/55da0a74/hero.webp'' -> ''/data/images/wiki/55da0a74/1751 carving, Ballochmyle, East Ayrshire, Scotland.webp''"}, {"source": "remediation_change_log:248697", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:248698", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_start None -> ''-10000''"}, {"source": "remediation_change_log:311164", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/55da0a74/1751 carving, Ballochmyle, East Ayrshire, Scotland.webp'' -> ''/data/images/wiki/55da0a74/Cup_marks_at_Mauchline,_Scotland.webp''"}, {"source": "remediation_change_log:357181", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s004: period_name ''< 4500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:357182", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s004: period_start ''-10000'' -> ''-4000''"}]'::jsonb),
