    ('55f1b595-fef2-4d16-9dfc-fb5e22634b07'::uuid, 'mystery', '4', '5', 'card-stats-2026-11-05-rollback:55f1b595-fef2-4d16-9dfc-fb5e22634b07:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Twelve Apostles, West Yorkshire', '7f346a5f904e1450eb5a60ad2ffad7fd', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Stone circle'', ''3000 - 1500 BC'') is shared by 57 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84586", "url": "remediation_change_log", "quote": "phase4:p4-2090:chunk-0001: description ''3300 - 500 BC: The Twelve Apostles is a stone circle near Ilkley and Burley in Wharfedale in West Yorkshire, England[1].'' -> ''The Twelve Apostles is a stone circle near Ilkley and Burley in Wharfedale in West Yorkshire, England [1]. The stone circle is slightly below and to the northeast of an east-west ridge at about 381 metres above sea level [1]. The Twelve Apostles consists of the remains of a stone circle with a diameter of about 15 metres [1]. The circle originally had between 16 and 20 stones, but it is now reduced to 12 stones [1]. The stones are made from the local millstone grit [1]. All of the stones were fallen by the mid-20th-century and were lying loose upon the ground [1]. The circle was inside a bank 1.2 metres wide and 0.6 metres high [1].''"}, {"source": "remediation_change_log:98937", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:98938", "url": "remediation_change_log", "quote": "2026-09-26d_field