    ('565483ad-e6c8-4053-9d06-dfd254daa246'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:565483ad-e6c8-4053-9d06-dfd254daa246:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Shell Mound in Dongsam-dong, Busan', 'bfa24a67b9e0e81afd4dddceab264b50', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Archaeological site'', ''< 4500 BC'') is shared by 19 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28220", "url": "remediation_change_log", "quote": "phase3:batch-0096:chunk-0003: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:84602", "url": "remediation_change_log", "quote": "phase4:p4-2091:chunk-0001: description ''A Neolithic shell midden on the west coast of Yeong-do Island in Busan, South Korea, dating from the 9th to 3rd millennium BC. Excavated three times by the National Museum of Korea from 1969, it is among the oldest Jeulmun pottery period middens in southern Korea. Artifacts include comb-patterned pottery, stoneware, bone tools, and the oldest millet found on the Korean Peninsula. The site provides key evidence for Siberian cultural influences on Korea and prehistoric exchange between southern Korea and Kyushu, Japan. A dedicated Shell Midden Exhibition Hall opened in 2002.'' -> ''Shell Mound in Dongsam-dong, Busan is located on the west coast of Yeong-do Island in Dongsam-dong, Yeongdo District, Busan [1]. This archaeological site consists of a midden of shells of various mollusc taxa that were discarded in a relatively small or restricted area by people who lived there in the Jeulmun pottery period [1]. It was excavated three times by archaeologists of the National Museum of Korea from 1969 and was found to be among the oldest Jeulmun middens so far discovered in the southern part of the Korean Peninsula [1]. The presence of Yunggimun (appliqué-pattern) pottery indicates the site was occupied for a time between 8000-7000 BP, but many absolute dates generated from carbon that was excavated from the site indicate the site was also occupied in the Middle (c. 3500 BC) and Late (c. 2000 BC) Jeulmun sub-periods [1]. A variety of artifacts, including three types of pottery, and tools made of bone and stone were uncovered [1].''"}, {"source": "remediation_change_log:98945", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:98946", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_start ''-9000'' -> None"}, {"source": "remediation_change_log:150148", "url": "remediation_change_log", "quote": "served-image-2026-09-30-012: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/5/51/Dongsam-dong_Shell_Midden.jpg'' -> None"}, {"source": "remediation_change_log:237636", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:237637", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_start None -> ''-3500''"}, {"source": "remediation_change_log:321552", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-001: thumbnail_url None -> ''/data/images/wiki/565483ad/hero.webp''"}, {"source": "remediation_change_log:325029", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-001: thumbnail_url ''/data/images/wiki/565483ad/hero.webp'' -> ''/data/images/wiki/565483ad/Dongsam-dong Shell Midden.webp''"}, {"source": "remediation_change_log:349006", "url