    ('569f53de-6821-4597-b4f3-f695504b9d60'::uuid, 'mystery', '6', '4', 'card-stats-2026-11-05-rollback:569f53de-6821-4597-b4f3-f695504b9d60:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Halliggye Fogou', '28767ff419741ceb2478ba6989e6789d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Cave Structures'', ''500 BC - 1 AD'') is shared by 19 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80870", "url": "remediation_change_log", "quote": "phase4:p4-2011:chunk-0001: description \"The largest and best-preserved fogou (underground stone passage) in Cornwall, England, constructed in the 5th or 4th centuries BC during the middle Iron Age. The complex features a 20-metre main sloping passage terminating in a reduced-height creep, plus a 28-metre curving side passage running westward. Built within a farming settlement called a ''round,'' the site housed several family groups in four or five houses surrounded by an earthwork enclosure. Pottery evidence indicates the settlement was occupied for 700 years through the end of the Roman period, though the fogou''s exact purpose -- whether storage, refuge, or ceremonial space -- remains debated.\" -> ''Halliggye Fogou is one of many fogous in Cornwall, England [1]. The Halliggye Fogou consists of a long narrow tunnel leading to three sectioned chambers [1]. The complex of passages has a roof and walls of stone, and is the largest and best-preserved of several mysterious tunnels associated with Cornish Iron Age settlements [1]. Pottery found during excavations has included local Iron Age cordoned wares and some sherds of Roman Samian ware from southern Gaul [1].''"}, {"source": "remediation_change_log:117592", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:117593", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: period_start ''-1500'' -> ''-500''"}, {"source": "remediation_change_log:117594", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: site_type ''Infrastructure'' -> ''Cave Structures''"}]'::jsonb),
