    ('571c2899-adaa-4520-b758-3bdcaaf8d503'::uuid, 'antiquity', '7', '5', 'card-stats-2026-11-05-rollback:571c2899-adaa-4520-b758-3bdcaaf8d503:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Sutkagan Dor', '27bed548dc27168600780b63403106dc', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2600"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84626", "url": "remediation_change_log", "quote": "phase4:p4-2092:chunk-0001: description \"Sutkagan Dor is the westernmost known archaeological site of the Indus Valley civilization, located about 480 km west of Karachi on the Makran coast near Gwadar, close to the Iranian border in Pakistan''s Baluchistan Province [1]. The site lies near the western bank of the Dasht River at its confluence with the Gajo Kaur stream [1]. It was a smaller settlement with substantial stone walls and gateways.\" -> ''Sutkagan Dor is the westernmost known archaeological site of the Indus Valley civilisation [1]. It is located about 480 km west of Karachi on the Makran coast near Gwadar, close to the Iranian border, in Pakistan\\''s Balochistan Province [1]. The site is within the Union Council of Suntsar and is near the western bank of the Dasht River and its confluence with a smaller stream, known as the Gajo Kaur [1]. It was a smaller settlement with substantial stone walls and gateways [1]. Sutkagan Dor was discovered in 1876 by Major Edward Mockler, who conducted small-scale excavation [1]. In October 1960, Sutkagan Dor was more extensively excavated by George F. Dales as part of his Makran Survey, 