on_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/57ced914/hero.webp'' -> ''/data/images/wiki/57ced914/Beacon Hill - geograph.org.uk - 409967.webp''"}, {"source": "remediation_change_log:337381", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4311:chunk-0001: description ''Beacon Hill is a Bronze Age hill fort site in Charnwood Forest, Leicestershire, rising to 248 m above sea level. Defensive earthworks discovered near the summit confirmed the presence of a fortified settlement believed to be up to 3,000 years old. In 1858, bronze jewellery, an axe, and a spearhead were unearthed at the site, now displayed at Charnwood Museum in Loughborough. The monument includes a slight univallate hillfort, a linear boundary, and an enclosure, and is legally protected as a Scheduled Ancient Monument by Historic England.'' -> ''Beacon Hill is a hill fort site in Charnwood Forest, Leicestershire, rising to 248 m above sea level [1] [2] [3]. The monument includes a slight univallate hillfort, a linear boundary, and an enclosure, and is legally protected as a Scheduled Ancient Monument by Historic England [4] [5] [6] [7].''"}, {"source": "remediation_change_log:349024", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349025", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-800'' -> None"}]'::jsonb),
    ('57f3306b-9927-46a4-84ef-9688bc9809f5'::uuid, 'cultural_influence', '8', '6', 'card-stats-2026-11-05-rollback:57f3306b-9927-46a4-84ef-9688bc9809f5:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''6'' restored on Lavatrae', '133e4379efbd1ac4aa0f3ebb0cfe2738', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 8 from description yes, thumbnail yes, 5 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84632", "url": "remediation_change_log", "quote": "phase4:p4-2092:chunk-0001: description \"Lavatrae (also Lavatris) was a Roman fort in the modern village of Bowes, County Durham, guarding the eastern entrance to the Stainmore Pass through the Pennines. Built with timber ramparts in the early 70s AD under Governor Petilius Cerealis, it served as a waypoint on the road connecting Carlisle to York. Stone walls replaced the timber defences in the 130s AD, and a civilian vicus developed to the north with a bathhouse to the southeast. The medieval Bowes Castle was later constructed within the fort''s perimeter. The site is a Scheduled Monument managed by Historic England.\" -> ''Lavatrae, also known as Lavatris, was a Roman fort in the modern-day village of Bowes, County Durham [1]. The Romans built a fort with wooden ramparts at Lavatrae in the early AD 70s, after an invasion of the region by Governor Petilius Cerealis [1]. It was intended as a waypoint on the northern leg of the Roman equivalent of Watling Street in the section connecting Luguvalium (Carlisle) to Eboracum (York) and points south [1]. It guarded the eastern entrance to the Stainmore Pass through the Pennines, overlooking the River Greta [1]. Stone walls were built around the site in the 130s, and an external settlement called a vicus was constructed to the north of the fort, with a bathhouse to the south-east [1]. The bathhouse was 30 by 20 feet, tiled and appears to have been destroyed in a fire, and then rebuilt [1]. The Cambridge Museum of Archaeology has a stone altar from the bathhouse, erected by the 1st Cohort of the Thracians [1]. Only earthworks and the parts of the stone walls of the bathhouse survive in the 21st century [1].''"}, {"source": "remediation_change_log:98995", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:98996", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_start ''1'' -> None"}, {"source": "remediation_change_log:237656", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:237657", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_start None -> ''70''"}, {"source": "remediation_change_log:343784", "url": "remediation_change_log", "quote": "insert-2026-10-07-010-001: thumbnail_url None -> ''/data/images/wiki/57f3306b/A lidar view of Bowes Castle within the ruins of the Roman fort of Lavatrae.webp''"}]'::jsonb),
