    ('5801a79b-8780-405a-9e1b-6a6016c5438b'::uuid, 'antiquity', '5', '7', 'card-stats-2026-11-05-rollback:5801a79b-8780-405a-9e1b-6a6016c5438b:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Bedd Arthur', '0a36fa95aafa321f668afb6f586cd23b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:34543", "url": "remediation_change_log", "quote": "phase4:p4-0030:chunk-0001: description ''Bedd Arthur (\"Arthur\\''s Grave\") is a possibly Neolithic hengiform monument in the Preseli Hills, Pembrokeshire, Wales. Thirteen upright stones and at least two fallen ones, each no higher than 60 cm, form an oval horseshoe measuring roughly 20 by 10 m with similarities to the earliest phase of Stonehenge. The site overlooks Carn Menyn, a suggested source for some of Stonehenge\\''s bluestones, and has been speculatively proposed as a prototype for that monument. It has never been excavated, so its dating and relationship to Stonehenge remain unconfirmed.'' -> ''Bedd Arthur consists of a barely visible oval bank and ditch, with thirteen standing stones, none higher than 60 centimetres arranged inside along with two further fallen stones [1]. The stone layout measures around 20 by 10 metres [1]. The shape is not well defined and is generally described as sub-rectangular but has been described as a rectangle, a horseshoe, an oval and a pointed ellipse [1]. The site has not been excavated and is absent from authoritative surveys [1]. The site is in Eglwyswrw community, and is a Scheduled monument with legal protection from disturbance and is within the Pembrokeshire Coast National Park [1].''"}, {"source": "remediation_change_log:98999", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:99000", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:150244", "url": "remediation_change_log", "quote": "served-image-2026-09-30-012: thumbnail_url ''/data/images/wiki/5801a79b/hero.webp'' -> ''/data/images/wiki/5801a79b/Beddarthur standing stone circle, Preseli Mountains - geograph.org.uk - 258436.webp''"}, {"source": "remediation_change_log:248731", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:248732", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_start None -> ''-3000''"}, {"source": "remediation_change_log:349026", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''3000 - 1500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349027", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-3000'' -> None"}]'::jsonb),
