    ('588e9b03-5d4a-44cd-a6f4-f1de7c8ff3aa'::uuid, 'mystery', '3', '8', 'card-stats-2026-11-05-rollback:588e9b03-5d4a-44cd-a6f4-f1de7c8ff3aa:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Laugerie-Basse', 'a36e8ecef7fa96269192c036d9fb348a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28815", "url": "remediation_change_log", "quote": "phase3:batch-0197:chunk-0001: period_start ''-500'' -> ''-15000''"}, {"source": "remediation_change_log:30408", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:91830", "url": "remediation_change_log", "quote": "phase4:p4-2210:chunk-0001: description ''Laugerie-Basse is an Upper Paleolithic rock shelter site in the Vezere Valley, approximately 2 km upstream from Les Eyzies-de-Tayac-Sireuil in the Dordogne, France. Occupied during the Middle and Upper Magdalenian (c. 15,000-8,000 BC), the site has yielded approximately 600 art objects, mainly mobiliary bone and antler carvings. In 1864, the Marquis de Vibraye discovered the 8 cm ivory Venus Impudique here, the first known Paleolithic Venus figurine. Inscribed as a UNESCO World Heritage Site in 1979 as part of the Prehistoric Sites and Decorated Caves of the Vezere Valley.'' -> ''Laugerie-Basse is an important Upper Paleolithic archaeological site within the territory of the French commune Les Eyzies-de-Tayac-Sireuil in Dordogne [1]. It is known for several works of art from the Magdalenian [1]. The prehistoric site consists of two abris: the main abri and 50 meters upstream the Abri of Marseilles [1]. In 1863 Édouard Lartet and Henry Christy began for the first time with excavations on the main abri [1]. The stratigraphy in the main abri comprises archaeological material mainly from Magdalenian III and Magdalenian IV [1]. Apart from stone artefacts and other tools, all in all approximately 600 art objects from the Magdalenian were recovered in Laugerie-Basse [1]. In Laugerie-Basse Paul Hurault, 8th Marquis de Vibraye discovered in 1864 the \"Immodest Venus\" which gave its name to the genre of Paleolithic Venus figurines [1]. The main abri was inhabited in the middle and upper Magdalenian as well as in the Azilian, which roughly corresponds to the time segment from 14,000 until 10,000 years BP [1].''"}, {"source": "remediation_change_log:117625", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: lat ''44.57043827631812'' -> ''44.9497''"}, {"source": "remediation_change_log:117626", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: lon ''0.595587783333077'' -> ''0.9983''"}, {"source": "remediation_change_log:117627", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: site_type ''Cave Structures'' -> ''Cave''"}, {"source": "remediation_change_log:150254", "url": "remediation_change_log", "quote": "served-image-2026-09-30-012: thumbnail_url ''/data/images/wiki/588e9b03/hero.webp'' -> ''/data/images/wiki/588e9b03/Laugerie-Basse 3 2017-09-20.webp''"}, {"source": "remediation_change_log:311206", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/588e9b03/Laugerie-Basse 3 2017-09-20.webp'' -> ''/data/images/wiki/588e9b03/Laugerie-Basse.webp''"}, {"source": "remediation_change_log:355858", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: si