    ('58e730c7-6ec4-44a4-97e8-d2f75d9a1c9e'::uuid, 'mystery', '9', '10', 'card-stats-2026-11-05-rollback:58e730c7-6ec4-44a4-97e8-d2f75d9a1c9e:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Carn Menyn', '97ef4c3c3aacaf518f56fa3017982a2f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 9 from (''Geological interest'', ''< 4500 BC'') is shared by 2 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44415", "url": "remediation_change_log", "quote": "phase4:p4-0093:chunk-0001: description \"Carn Menyn is a grouping of craggy spotted dolerite outcrops in the Preseli Hills of Pembrokeshire, Wales, long identified as a source of Stonehenge''s bluestones. In the 1920s, petrographer H.H. Thomas first linked the Preseli dolerite to Stonehenge, and subsequent research by Darvill and Wainwright supported Carn Menyn as a primary quarry. More recent UCL-led excavations confirmed nearby Carn Goedog as the main source of spotted dolerite bluestones (quarried c. 3200 BC) and Craig Rhos-y-felin for rhyolite bluestones (c. 3400 BC), located 140 miles from Stonehenge. The 500-year gap between quarrying and Stonehenge installation (c. 2900 BC) suggests the stones may have first been used locally before transport eastward.\" -> ''Carn Menyn is a grouping of craggy rock outcrops or tors in the Preseli Hills in the Welsh county of Pembrokeshire [1]. The name means \"butter rock\" [1]. Carn Menyn sits on top of the Preseli ridge, close to the stone setting of Bedd Arthur [1]. It consists of a series of outcrops of spotted dolerite similar to that of other tors in the area, and several other prehistoric sites have been identified nearby [1]. Survey work between 2002 and 2004 by the Strumble-Preseli Ancient Communities and Environment Study recorded an enclosure on the upper part of the outcrop consisting of a steep-sided promontory with a bank of stones across its neck [1]. Although only around 3,500 square metres in area the enclosure contains several dolerite outcrops, each naturally fractured into shapes that could be formed into columns [1].''"}, {"source": "remediation_change_log:99023", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:99024", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:150298", "url": "remediation_change_log", "quote": "served-image-2026-09-30-012: thumbnail_url ''/data/images/wiki/58e730c7/hero.webp'' -> ''/data/images/wiki/58e730c7/View from Carn Menyn eastwards towards Foel Drigarn and Y Frenni 2011.webp''"}, {"source": "remediation_change_log:237670", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:237671", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_start None -> ''-6000''"}, {"source": "remediation_change_log:349033", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''< 4500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349034", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-6000'' -> None"}, {"source": "remediation_change_log:354775", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_name ''Undated'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:354776", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_start None -