    ('5928dcb7-1a73-4bf6-8bd3-3fe6ba8c6b90'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:5928dcb7-1a73-4bf6-8bd3-3fe6ba8c6b90:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Carnfree', '44998b97fe3439d2f9b7ae28b6c6151d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84668", "url": "remediation_change_log", "quote": "phase4:p4-2093:chunk-0001: description \"Carnfree is a multi-period archaeological complex south of Tulsk in County Roscommon, located near the royal site of Rathcroghan [1]. The principal feature is a mound dating to 3000–2000 BC, traditionally identified as the cairn of the legendary Connacht warrior Fráech [1]. This Bronze Age funerary monument later served as an inauguration site for medieval kings of Connacht, continuing ancient ceremonial traditions into the late medieval period [1]. The complex also includes the area of Selc, featuring the passage tomb Duma Selga [1], and an early Christian ecclesiastical site associated with Saint Patrick''s ministry to the Ui Brian princes of Connacht [1].\" -> ''Carnfree is a site south of the village of Tulsk in Roscommon that also lies close to the more celebrated ancient landscape of Rathcroghan [1]. The chief feature here is the bronze-age mound of Carnfree itself, believed to be the cairn of the Connacht warrior Fráech, that was used as an inauguration place up to late medieval times [1]. Up until the mid-nineteenth century a proclamation stone stood nearby that featured two sunken footprints [1].''"}, {"source": "remediation_change_log:99029", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:99030", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:99031", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s008: site_type ''Mound/tumulus'' -> ''Cairn''"}, {"source": "remediation_change_log:248747", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:248748", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_start None -> ''-4000''"}, {"source": "remediation_change_log:349035", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:349036", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
