    ('5b4e478e-a052-46d9-b892-c3894bd8c3ae'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:5b4e478e-a052-46d9-b892-c3894bd8c3ae:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Suessula', '776f9971ad02a35e955a0718f2a0f8cb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -900"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84718", "url": "remediation_change_log", "quote": "phase4:p4-2094:chunk-0001: description \"Suessula was an ancient city of Campania, southern Italy, situated near the frontier with Samnium between Capua and Nola. It was the scene of a decisive Roman victory over the Samnites in 343 BC and served as a strategic base during the Second Punic War against Hannibal. It continued as a municipal town under the Roman Empire and became an episcopal see until the 10th century, when it was abandoned due to Saracen raids and malaria. The ruins lie within the Bosco d''Acerra, about 7 km south of Maddaloni.\" -> \"Suessula is repeatedly mentioned during the wars between Romans and Samnites [1]. In the Second Punic War the city played a considerable part, though apparently more from its position than its own importance [1]. Suessula was on the line of the Via Popillia, which was here intersected by a road which ran from Neapolis through Acerrae, and on to the Via Appia [1]. The ruins of the town lie within the Bosco d''Acerra, a picturesque forest, about 7 km south of Maddaloni [1]. They were more conspicuous in the 19th century than they now are, but traces of the theater may still be seen, and debris of other buildings [1]. Oscan tombs were excavated there between 1878 and 1886, and important finds of vases and bronzes have been made [1].\""}, {"source": "remediation_change_log:99957", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:99958", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-500'' -> None"}, {"source": "remediation_change_log:150369", "url": "remediation_change_log", "quote": "served-image-2026-09-30-012: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/d/d8/Suessola-Panoramica.jpg'' -> ''/data/images/wiki/5b4e478e/Anfora decorata.webp''"}, {"source": "remediation_change_log:248773", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:248774", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_start None -> ''-500''"}, {"source": "remediation_change_log:333850", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-001: thumbnail_url ''/data/images/wiki/5b4e478e/Anfora decorata.webp'' -> ''/data/images/wiki/5b4e478e/Suessola-Panoramica.webp''"}, {"source": "remediation_change_log:349049", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''500 BC - 1 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:349050", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-500'' -> ''-900''"}]'::jsonb),
