    ('5b59aada-2931-4de8-aad0-cd97a35e7e0b'::uuid, 'mystery', '8', '9', 'card-stats-2026-11-05-rollback:5b59aada-2931-4de8-aad0-cd97a35e7e0b:mystery', 'rollback of card-stats-2026-11-05: mystery ''9'' restored on Pont sur la Laye', 'f7b8067b6add5acfdfd82dcc76334f38', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Gate/archway/bridge'', ''1000 - 1500 AD'') is shared by 3 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84744", "url": "remediation_change_log", "quote": "phase4:p4-2095:chunk-0001: description ''A stone arch bridge spanning the Laye stream near the town of Mane in Provence, France. The central arch dates to the late 1st or early 2nd century AD, making it one of approximately twelve known Roman segmental arch bridges. The 40-metre-long bridge features three arches of notably different sizes, though the two lateral arches with their breakwaters were added in the 17th century. Built of local limestone with voussoirs in the arches and irregular stonework in the spandrel walls, the main pier is protected by large triangular cutwaters. It remains a classified historical monument.'' -> ''The Pont sur la Laye or Pont roman de Mane is an old stone arch bridge across the stream Laye in the French Provence close to the town Mane [1]. The 40-metre-long and 3.2-metre-wide bridge features three segmental arches with a span to rise ratio of up to c. 3:1 [1]. The bridge was built of local limestone whose shape varies according to its function: the arches consist of voussoirs, the spandrel walls of irregular stonework [1]. The main pier is protected both upstream and downstream by large triangular cutwaters out of rectangular blocks of stone [1]. The paved roadway rises sharply from the left bank to the main arch, and then drops in a gentler gradient to the higher bank on the other side [1].''"}, {"source": "remediation_change_log:99963", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:99964", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''1'' -> None"}, {"source": "remediation_change_log:150372", "url": "remediation_change_log", "quote": "served-image-2026-09-30-012: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/1/11/Pont_sur_Laye%2C_Mane%2C_Alpes-de-Haute-Provence%2C_France._Pic_01.jpg'' -> ''/data/images/wiki/5b59aada/Pont sur la laye.webp''"}, {"source": "remediation_change_log:237690", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_name None -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:237691", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_start None -> ''1101''"}, {"source": "remediation_change_log:322917", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-002: thumbnail_url ''/data/images/wiki/5b59aada/Pont sur la laye.webp'' -> ''/data/images/wiki/5b59aada/hero.webp''"}, {"source": "remediation_change_log:325235", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/5b59aada/hero.webp'' -> ''/data/images/wiki/5b59aada/Pont sur Laye, Mane, Alpes-de-Haute-Provence, France. Pic 01.webp''"}]'::jsonb),
