    ('5bb2f3b5-7bc6-4cf8-a3b4-cbb4b6e35595'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:5bb2f3b5-7bc6-4cf8-a3b4-cbb4b6e35595:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on The Ridgeway', 'bd965d8917602cb79194f12580ea5eb8', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84750", "url": "remediation_change_log", "quote": "phase4:p4-2095:chunk-0001: description \"The Ridgeway is a ridgeway and ancient trackway, often described as Britain''s oldest road [1]. The preserved section runs from Wiltshire along the chalk ridge of the Berkshire Downs to the River Thames at Goring Gap, forming part of the Icknield Way that connected Salisbury Plain to East Anglia [1]. In 1972, the route was adapted to create the Ridgeway National Trail, an 87-mile (140 km) path from Overton Hill near Avebury to Ivinghoe Beacon in Buckinghamshire [1].\" -> \"The Ridgeway is a ridgeway or ancient trackway described as Britain''s oldest road [1]. The section clearly identified as an ancient trackway extends from Wiltshire along the chalk ridge of the Berkshire Downs to the River Thames at the Goring Gap, part of the Icknield Way which ran, not always on the ridge, from Salisbury Plain to East Anglia [1]. For at least 5,000 years travellers have used the Ridgeway [1]. The Ridgeway provided a reliable trading route to the Dorset coast and to the Wash in Norfolk [1]. The high dry ground made travel easy and provided a measure of protection by giving traders a commanding view, warning against potential attacks [1]. During the Iron Age, inhabitants took advantage of the high ground by building hillforts along the Ridgeway to help defend the trading route [1].\""}, {"source": "remediation_change_log:99972", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:99973", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:150903", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/2/27/Ridgeway_mongwell.jpg'' -> ''/data/images/wiki/5bb2f3b5/The_Ridgeway_approaching_Whitehorse_Hill_from_the_west.webp''"}, {"source": "remediation_change_log:248783", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:248784", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_start None -> ''-4500''"}, {"source": "remediation_change_log:311289", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/5bb2f3b5/The_Ridgeway_approaching_Whitehorse_Hill_from_the_west.webp'' -> ''/data/images/wiki/5bb2f3b5/Ridgeway_mongwell.webp''"}, {"source": "remediation_change_log:349058", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349059", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-4500'' -> None"}]'::jsonb),
