    ('5beb80c3-7968-4097-b2b3-a699f276ca88'::uuid, 'mystery', '6', '8', 'card-stats-2026-11-05-rollback:5beb80c3-7968-4097-b2b3-a699f276ca88:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Daorson', '2f2b4fab3ce96e14198c8af9d1bee650', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Fortress/citadel'', ''3000 - 1500 BC'') is shared by 19 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28553", "url": "remediation_change_log", "quote": "phase3:batch-0159:chunk-0001: site_type ''Megalithic structures'' -> ''Fortress''"}, {"source": "remediation_change_log:84754", "url": "remediation_change_log", "quote": "phase4:p4-2095:chunk-0001: description ''Daorson was the capital of the Illyrian Daorsi tribe, situated in the Neretva River valley [1]. The Daorsi lived between 300 BC and 50 BC and came into early contact with Greek traders, acquiring many aspects of Greek civilization, and the town acquired a degree of Hellenization [1]. Following the peace treaty with Rome in 168/167 BC, the Daorsi minted their own coins [1].'' -> ''Daorson was the capital of the Illyrian tribe of the Daorsi [1]. The Daorsi lived in the valley of the Neretva River between 300 BC and 50 BC [1]. The ruins of Daorson are located at Ošanjići, near Stolac [1]. Daorson was built around a central fort or acropolis, surrounded by cyclopean walls made of huge stone blocks [1]. The defensive wall extending from southwest to northeast was 65 metres long, 4.2 metres wide [1]. The most valuable of the finds is a bronze helmet decorated with a series of mythological figures [1]. The date of the ransacking of the town of Daorson that finally put an end to human settlement there can be determined with fair accuracy as the mid or second half of the 1st century BCE from the details of the wars waged by the Roman Praetor Vatinius against the Delmati [1].''"}, {"source": "remediation_change_log:99976", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''500 BC - 1 AD'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:99977", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-500'' -> ''-1700''"}, {"source": "remediation_change_log:150908", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''/data/images/wiki/5beb80c3/hero.webp'' -> ''/data/images/wiki/5beb80c3/Daorson (01).webp''"}, {"source": "remediation_change_log:333856", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-001: thumbnail_url ''/data/images/wiki/5beb80c3/Daorson (01).webp'' -> ''/data/images/wiki/5beb80c3/hero.webp''"}, {"source": "remediation_change_log:355860", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Fortress'' -> ''Fortress/citadel''"}]'::jsonb),
