    ('5bf42cbd-5082-43a3-b064-91ca60423e51'::uuid, 'total_power', '26', '24', 'card-stats-2026-11-05-rollback:5bf42cbd-5082-43a3-b064-91ca60423e51:total_power', 'rollback of card-stats-2026-11-05: total_power ''24'' restored on Camel Carving Site', '539f68bec58198a1ff76b966257097b1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 26 from antiquity + fortification + cultural_influence + mystery + legacy = 9 + 2 + 6 + 8 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84756", "url": "remediation_change_log", "quote": "phase4:p4-2095:chunk-0001: description ''The Camel Carving Site near Sakaka in al-Jawf Province, Saudi Arabia, contains some of the oldest large-scale animal reliefs in the world, dating to the 6th millennium BCE. The site features 21 carvings including 17 life-sized camel reliefs and 2 equid figures, all produced using Neolithic stone tools. Discovered in 2016 and studied by an international Saudi-French-German team, radiocarbon dating places occupation between 5200 and 5600 BCE. The site has suffered from erosion, vandalism, and agricultural irrigation damage.'' -> ''The Camel Carving Site is considered one of the most prominent archaeological sites of Prehistoric Arabia [1]. It dates to the Neolithic period of the Al-Jawf region in modern-day Saudi Arabia, specifically located in the eastern center of Sakaka Governorate [1]. The site \"likely has the oldest known surviving large-scale animal reliefs in the world\", differing in execution from the rock art common throughout Saudi Arabia [1]. The site is also considered among Saudi Arabia\\''s oldest rock art sites, which typically feature two-dimensional carvings in both prominent and recessed styles [1].''"}, {"source": "remediation_change_log:99978", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: site_type ''Petroglyphs'' -> ''Rock relief/carving''"}]'::jsonb),
    ('5c40d704-05a0-4951-a5cf-20066d444d81'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:5c40d704-05a0-4951-a5cf-20066d444d81:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Walton Common', '94bc65d2427fe2e5e722d41f785a6c47', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84758", "url": "remediation_change_log", "quote": "phase4:p4-2095:chunk-0001: description ''Walton Common is a 25.5-hectare site near the village of Walton in Gordano, North Somerset, designated both a Scheduled Ancient Monument and a Site of Special Scientific Interest. The common preserves two saucer-shaped Bronze Age round barrows and a distinctive late Iron Age banjo enclosure, a circular earthwork with parallel-ditched entrance track resembling a banjo shape. Additional prehistoric earthworks include field systems, hut circles, and other enclosures, situated on a ridge overlooking the Gordano Valley and Severn Estuary. The site is managed as a nature reserve by the Avon Wildlife Trust.'' -> ''Walton Common is a 25.5 hectare biological Site of Special Scientific Interest near the village of Walton in Gordano, North Somerset [1]. The site has two saucer-shaped round barrows from the Bronze Age, and the Walton Common banjo enclosure, a banjo enclosure from the late Iron Age that may be a univallate hillfort [1].''"}, {"source": "remediation_change_log:117674", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: period_name ''4500 - 3000 BC'' -> None"}, {"source"