    ('5d1b5446-41d9-46db-98c9-ac4d1996a3c1'::uuid, 'mystery', '4', '5', 'card-stats-2026-11-05-rollback:5d1b5446-41d9-46db-98c9-ac4d1996a3c1:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Grange Stone Circle', 'd31bdc26b1a6bce75247d2eb10939bf5', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Stone circle'', ''3000 - 1500 BC'') is shared by 57 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28307", "url": "remediation_change_log", "quote": "phase3:batch-0108:chunk-0001: period_start ''-4000'' -> ''-2000''"}, {"source": "remediation_change_log:30411", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:80904", "url": "remediation_change_log", "quote": "phase4:p4-2012:chunk-0001: description \"Ireland''s largest stone circle, built c. 2200 BC near Lough Gur in County Limerick. Comprising 113 contiguous standing stones in a ring 45 metres in diameter, sunken 1.2 metres into the landscape. The entrance aligns with the summer solstice sunrise and the Samhain sunset in November. Excavations in 1939 uncovered deliberately smashed Beaker pottery, unburnt human remains, and cattle bones. The largest stone, Rannach Chruim Duibh, stands over 4 metres tall and weighs 40 tonnes. In 2022 previously unknown carved concentric circles and arcs were discovered on one of the stones.\" -> ''Grange stone circle is a stone circle in County Limerick, Ireland [1]. It is located 300m west of Lough Gur, 4 km north of Bruff [1]. The Limerick-Kilmallock road is nearby [1]. It is estimated to be 4,000-years-old, dating from the Bronze Age [1]. The largest stone is Rannach Chruim Duibh and is over 4m high and weighs 40 tonnes [1]. The entrance of the circle is aligned with the rising sun at the summer solstice [1]. A short distance to the north-north east of the main stone circle, is a second smaller circle, also constructed of large stones [1]. To the north of this is a large leaning standing stone [1].''"}, {"source": "remediation_change_log:99999", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:100000", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:150940", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''/data/images/wiki/5d1b5446/hero.webp'' -> ''/data/images/wiki/5d1b5446/LoughGurStoneCircle-Apr2012.webp''"}, {"source": "remediation_change_log:237699", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:237700", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_start None -> ''-3000''"}, {"source": "remediation_change_log:311303", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/5d1b5446/LoughGurStoneCircle-Apr2012.webp'' -> ''/data/images/wiki/5d1b5446/Grange_stone_circle.webp''"}]'::jsonb),
