    ('5d316e03-60c3-47c0-ae67-3f432cdc9050'::uuid, 'empire_count', '3', '0', 'card-stats-2026-11-05-rollback:5d316e03-60c3-47c0-ae67-3f432cdc9050:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Sa Cudia Cremada', '8fcee3f7e16acdc210af7320db41d3ba', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 3 from tag_site(39.88022346910098, 4.243121454255389, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80906", "url": "remediation_change_log", "quote": "phase4:p4-2012:chunk-0001: description \"A Talayotic settlement on the outskirts of Mahon, Menorca, Spain, featuring three talayots (monumental tower structures), cyclopean walls, hypogea burial caves, and a recently discovered taula enclosure. Excavations since 2015 revealed the T-shaped taula sanctuary with a double altar, animal remains, and ritual features, intentionally abandoned in the late 3rd century BC. The site spans the Bronze and Iron Ages and is among 32 talayotic sites in Menorca''s UNESCO World Heritage candidature.\" -> ''Sa Cudia Cremada is the name of an archaeological site located in a land property called in the same way, in the outskirts of the city of Mahón, the capital of Menorca [1]. The remains which form part of the site belonged to the Talaiotic culture from the Bronze and Iron Ages, although the site continued being occupied during the first centuries of the Roman conquest of the island, since Roman materials can be found on the surface that date back to the first phase of the Roman occupation of Menorca (end of the 2nd and 1st centuries BC) [1]. The site presents a great state of preservation as several of its structures show [1]. The most significant ones are three talayots or truncated-shape towers built with the cyclopean construction technique, the sanctuary, several hypogea, a large pit possibly for the storage of goods, and other remains, such as a stretch of a wall [1]. The easternmost talayot has an oval layout and its base is 19 meters in diameter [1]. Its façade is somewhat concave and is oriented to the South [1].''"}, {"source": "remediation_change_log:100005", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:100006", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:100007", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: site_type ''Megalithic structures'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:150945", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/8/82/Sacudiacremadahypogeum.JPG'' -> ''/data/images/wiki/5d316e03/Sa Cudia Cremada Hypogeum 2.webp''"}, {"source": "remediation_change_log:248797", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:248798", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_start None -> ''-3000''"}, {"source": "remediation_change_log:311309", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/5d316e03/Sa Cudia Cremada Hypogeum 2.webp'' -> ''/data/images/wiki/5d316e03/Sacudiacremadahypogeum.webp''"}, {"source": "remediation_change_log:349070", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''3000 - 1500 BC'' -> ''Undated''"