    ('5d3fc50c-0709-4d5a-bd6c-900bc7c542b1'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:5d3fc50c-0709-4d5a-bd6c-900bc7c542b1:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Al Naslaa', 'fc8fccff6e474453209095555b218c80', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27898", "url": "remediation_change_log", "quote": "phase3:batch-0027:chunk-0004: site_type ''Petroglyphs'' -> ''Natural feature''"}, {"source": "remediation_change_log:34595", "url": "remediation_change_log", "quote": "phase4:p4-0032:chunk-0001: description ''Al Naslaa is a striking sandstone rock formation located 50 km south of the Tayma oasis in Saudi Arabia. Standing about 6 m high and 9 m wide, it consists of twin boulders balanced on natural pedestals, split by a precise vertical gap likely caused by a geological fault or freeze-thaw weathering. The southeast face is covered in petroglyphs depicting Arabian horses, ibexes, and humans, dating to the Bronze Age.'' -> ''The Al Naslaa rock is a landform 50 kilometres (31 mi) south of the Tayma oasis in Saudi Arabia [1]. It is a large sandstone rock split neatly down the middle into two parts, both balanced on small pedestals [1]. The overall shape of the rock is due to wind erosion and the chemical weathering made possible by the moist conditions in the protected underside of the rock [1]. It is split in two by a joint [1]. The rock is about 6 metres (20 ft) high and 9 metres (30 ft) wide, and is covered on its south-east face with numerous petroglyphs, including depictions of horses and ibex [1].''"}, {"source": "remediation_change_log:35783", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Natural feature'' -> ''Petroglyphs''"}, {"source": "remediation_change_log:100010", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:100011", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''1'' -> None"}, {"source": "remediation_change_log:248799", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:248800", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_start None -> ''-10000''"}, {"source": "remediation_change_log:349072", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''< 4500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349073", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-10000'' -> None"}]'::jsonb),
