    ('5d64e4f8-8a98-4cf7-a97b-c353d6029e84'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:5d64e4f8-8a98-4cf7-a97b-c353d6029e84:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Julliberrie''s Grave', '9f8b0ec9a69de802f5fc037dcc5d4f9a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:34597", "url": "remediation_change_log", "quote": "phase4:p4-0032:chunk-0001: description \"Julliberrie''s Grave is an unchambered long barrow situated near the village of Chilham in Kent, England[1]. Constructed during the fourth millennium BCE, it dates to Britain''s Early Neolithic period[1]. Today the site survives only in ruins, though it was once a substantial earthwork mound[1]. Local folklore also knows the site as The Giant''s Grave or simply The Grave[1].\" -> \"Julliberrie''s Grave, also known as The Giant''s Grave or The Grave, is an unchambered long barrow located near to the village of Chilham in the south-eastern English county of Kent [1]. Probably constructed in the fourth millennium BCE, during Britain''s Early Neolithic period, today it survives only in a state of ruin [1]. Julliberrie''s Grave is 44 metres long, 2 metres high, and 15 metres at its widest [1]. It was originally larger, with the northern end having been destroyed [1]. A rectangular pit was dug into the western side of the barrow shortly after its completion, likely containing a ritual deposit of organic material [1]. In the Iron Age, a hearth was established in the ditch circling the barrow; in the Romano-British period, human remains and a coin hoard were buried around its perimeter [1].\""}, {"source": "remediation_change_log:100014", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:100015", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:237709", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:237710", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s004: period_start None -> ''-4000''"}, {"source": "remediation_change_log:325239", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/5d64e4f8/hero.webp'' -> \"/data/images/wiki/5d64e4f8/Julliberrie''s Grave in September 2012.webp\""}]'::jsonb),
