    ('5d97461b-02b7-4227-8918-bc6c80a531ac'::uuid, 'antiquity', '10', '8', 'card-stats-2026-11-05-rollback:5d97461b-02b7-4227-8918-bc6c80a531ac:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Dmanisi', 'b76e79c9f9728425908036d241e481e4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -1798050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27260", "url": "remediation_change_log", "quote": "2026-09-21_mechanical-country: country ''Georgia (country)'' -> ''Georgia''"}, {"source": "remediation_change_log:80908", "url": "remediation_change_log", "quote": "phase4:p4-2012:chunk-0001: description \"Dmanisi is an archaeological site in the Kvemo Kartli region of Georgia, about 85 km southwest of Tbilisi. It contains hominin fossils dated to 1.85-1.77 million years ago, making them the earliest well-documented human remains outside Africa. The site has yielded five remarkably well-preserved skulls and over 100 postcranial bones, representing the largest collection of early Homo erectus from a single location. The skulls display such wide morphological variation that, found separately, they would have been classified as different species, prompting scientists to propose that several named early human species may actually represent natural variation within Homo erectus. Dmanisi also preserves a medieval town with churches and fortifications, and is on Georgia''s UNESCO Tentative List.\" -> \"Dmanisi is a town and archaeological site in the Kvemo Kartli region of Georgia approximately 93 km southwest of the nation''s capital Tbilisi in the river valley of Mashavera [1]. A series of skulls which had diverse physical traits, discovered at Dmanisi in the early 2000s, led to the hypothesis that many separate species in the genus Homo were in fact a single lineage [1]. The area around the town of Dmanisi has been settled since the Early Bronze Age [1]. Beyond a rich collection of ancient and medieval artifacts and the ruins of various buildings and structures, unique remains of prehistoric animals and humans have been unearthed [1]. The discovery of primitive stone tools in 1984 led to increasing interest to the archaeological site [1]. Early human fossils, originally named Homo georgicus and now considered Homo erectus georgicus, were found at Dmanisi between 1991 and 2005 [1]. At 1.8 million years old, they are now believed to be a subspecies of Homo erectus and not a separate species of Homo [1]. These fossils represent the earliest known human presence in the Caucasus [1].\""}, {"source": "remediation_change_log:100018", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:100019", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:150979", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''/data/images/wiki/5d97461b/hero.webp'' -> ''/data/images/wiki/5d97461b/Dmanisi_Sioni_cathedral.webp''"}, {"source": "remediation_change_log:248805", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:248806", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_start None -> ''-4500''"}, {"source": "remediation_change_log:349074", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''4500 - 3000 BC'' -> ''< 4500 BC''"}, {"source": "remed