    ('5df03f8d-0b22-4188-b7ae-ccd2b00d8f47'::uuid, 'antiquity', '5', '2', 'card-stats-2026-11-05-rollback:5df03f8d-0b22-4188-b7ae-ccd2b00d8f47:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''2'' restored on Sacul', 'df542cc14a5838831d7554da883c6a8c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28589", "url": "remediation_change_log", "quote": "phase3:batch-0166:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:35784", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:84802", "url": "remediation_change_log", "quote": "phase4:p4-2096:chunk-0001: description \"Sacul was a Maya city in the upper Mopan River drainage of Guatemala''s Petén department, occupying a key trade route through the Maya Mountains. The main period of occupation dates to the Late Classic Period. In the late 8th to early 9th century, Sacul was one of only three southeastern Petén kingdoms—alongside Ixtutz and Ucanal—to use its own Emblem Glyph, indicating royal political status [1].\" -> \"Sacul is an archaeological site of the Maya civilization located in the upper drainage of the Mopan River, in the Petén department of Guatemala [1]. The city occupied an important trade route through the Maya Mountains [1]. The main period of occupation dates to the Late Classic Period [1]. In the late 8th century AD through to the early 9th century, Sacul was one of the few kingdoms in the southeastern Petén region to use its own Emblem Glyph, together with Ixtutz and Ucanal [1]. In AD 779 Sacul went to war against Ixkun and lost, but stelae at both cities record a visit to Ixkun by king Ch''iyel of Sacul just 11 years later and the two cities appear to have formed a military alliance at that time [1]. The site core is arranged around a number of plazas, one of which forms a monumental acropolis [1]. The site core includes pyramids, a ballcourt, a triadic complex and two E-Group astronomical complexes [1]. The last stela erected in Sacul bears a date corresponding to AD 800 [1].\""}, {"source": "remediation_change_log:100023", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:100024", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''500'' -> None"}, {"source": "remediation_change_log:150984", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Sacul_emblem_glyph.gif/400px-Sacul_emblem_glyph.gif'' -> ''/data/images/wiki/5df03f8d/hero.webp''"}, {"source": "remediation_change_log:248807", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:248808", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s008: period_start None -> ''500''"}, {"source": "remediation_change_log:349076", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''500 - 1000 AD'' -> ''Undated''"}, {"source": "remediation_change_log:349077", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''500'' -> None"}]'::jsonb),
