    ('5e7bedef-ef5e-44b4-b479-ec462b3ba954'::uuid, 'cultural_influence', '8', '6', 'card-stats-2026-11-05-rollback:5e7bedef-ef5e-44b4-b479-ec462b3ba954:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''6'' restored on Black Mountain (Pima County, Arizona)', 'd2e689b3003b3a3e7c49f4966cc28b6a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 8 from description yes, thumbnail yes, 3 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84828", "url": "remediation_change_log", "quote": "phase4:p4-2097:chunk-0001: description \"A lava-capped mesa in Pima County, Arizona, rising 305 m above its base to an altitude of 1,128 m. Atop the mesa lie the ruins of an ancient Hohokam fortification dating to approximately AD 300-1500, featuring long stone walls, circular stone rings, petroglyphs, man-made trails, and pottery sherds. The Hohokam were master desert dwellers who built sophisticated canal systems and are the ancestors of the modern Tohono O''odham people. The site is located on reservation land and is not open to the general public, preserving these archaeological remains from disturbance.\" -> ''Black Mountain is a lava capped mesa in Pima County, Arizona, that rises 1,000 feet above its base to an altitude of 3,700 feet [1]. It is a northeast trending ridge, 5,600 feet in length, located along Mission Road nine miles southwest of Tucson [1]. It is on the San Xavier Indian Reservation, 3.18 miles southwest of the Mission San Xavier del Bac [1]. The Sierrita Mountains rise to the southwest and the Santa Cruz River is about four miles to the east [1]. On top of Black Mountain are the ruins of an ancient Hohokam fortification [1]. Long stone walls, circular stone rings, petroglyphs, man-made trails, and pottery sherds can still be seen today [1].''"}, {"source": "remediation_change_log:117711", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:117712", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: period_start ''1'' -> None"}, {"source": "remediation_change_log:117713", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: site_type ''Fortress/citadel'' -> ''Fortification''"}, {"source": "remediation_change_log:151017", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''/data/images/wiki/5e7bedef/hero.webp'' -> None"}, {"source": "remediation_change_log:249173", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:249174", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_start None -> ''-800''"}, {"source": "remediation_change_log:333874", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-001: thumbnail_url None -> ''/data/images/wiki/5e7bedef/hero.webp''"}, {"source": "remediation_change_log:349084", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349085", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-800'' -> None"}]'::jsonb),
