    ('5f77f387-c246-4943-821e-259e4d4f50ab'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:5f77f387-c246-4943-821e-259e4d4f50ab:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Grønsalen', 'c7689fa85f815624e7098ad60f693c2e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84836", "url": "remediation_change_log", "quote": "phase4:p4-2097:chunk-0001: description \"Gronsalen (Gronjaegers Hoj) near Fanefjord Church on the Danish island of Mon is Denmark''s largest long barrow, measuring approximately 102m long and 11m wide. Dating to c. 3500 BC in the Neolithic period, the barrow is encircled by 134-147 large kerbstones and contains three burial chambers, two of which are open. Named after the legendary Green Hunter (Gron Jaeger), who according to local folklore ruled western Mon and was buried here with his wife Fane. The site was first documented c. 1186, examined by Bishop Munter in 1810, protected by law thereafter, and restored in 1963.\" -> \"Grønsalen or Grønjægers Høj is located near Fanefjord Church on the Danish island of Møn [1]. Some 100 metres long and 10 metres wide, it is Denmark''s largest long barrow and is widely recognised as one of Europe''s outstanding ancient monuments [1]. The barrow, rising over a metre above the surrounding area, is encircled by 134 large stones [1]. The grave, at the centre, is covered with earth and contains three burial chambers, two of which are open [1]. It is not known when they were first opened or what was found inside [1]. The long barrow was examined in 1810 by Bishop Münter and was protected by law after that [1]. On the basis of its shape, the barrow has been dated as Neolithic, approximately 3500 BC [1].\""}, {"source": "remediation_change_log:117735", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: site_type ''Necropolis/tombs complex'' -> ''Barrow''"}, {"source": "remediation_change_log:151035", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''/data/images/wiki/5f77f387/hero.webp'' -> ''/data/images/wiki/5f77f387/Grønsalen.Møn.1.webp''"}, {"source": "remediation_change_log:311361", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/5f77f387/Grønsalen.Møn.1.webp'' -> ''/data/images/wiki/5f77f387/Groensalen.webp''"}]'::jsonb),
