    ('5f9051e0-639a-4d93-939b-f96b41fd35b1'::uuid, 'cultural_influence', '6', '5', 'card-stats-2026-11-05-rollback:5f9051e0-639a-4d93-939b-f96b41fd35b1:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''5'' restored on Petuaria', '6cbba88fd79221f17eaabfdce79de245', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 6 from description yes, thumbnail yes, 0 content link(s), 2 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84838", "url": "remediation_change_log", "quote": "phase4:p4-2097:chunk-0001: description \"Petuaria was a Roman fort founded in 70 AD at modern Brough in the East Riding of Yorkshire, abandoned by 125 AD. The adjacent civilian settlement grew into the probable capital of the Celtic Parisi tribe and an important port on the Humber, surviving until around 370 AD. A unique dedication stone records Marcus Ulpius Januarius gifting a theatre stage around 140 AD -- the only known epigraphic mention of a magistrate in Roman Britain. Petuaria marked the southern terminus of Cade''s Road, running northward to Newcastle.\" -> \"Petuaria was originally a Roman fort situated where the town of Brough in the East Riding of Yorkshire now stands [1]. Petuaria means something like ''quarter'' or ''fourth part'', incorporating the archaic Brythonic *petuar, ''four'' [1]. It was founded in 70 AD and abandoned in about 125 [1]. The adjacent civitas, ferry-crossing and port which grew over and replaced the fort survived until about 370, and was probably the capital of the Celtic tribe called the Parisi [1]. Petuaria marked the southern end of the Roman road known now as Cade''s Road, which ran roughly northwards for a hundred miles to Pons Aelius [1]. Archaeological excavations of the site of Petuaria were carried out in the 1930s, and between 1958 and 1962 [1].\""}, {"source": "remediation_change_log:100044", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:100045", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''1'' -> None"}, {"source": "remediation_change_log:151036", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/1/1c/High_Street%2C_Kingston_upon_Hull_%28geograph_3824295%29.jpg'' -> ''/data/images/wiki/5f9051e0/hero.webp''"}, {"source": "remediation_change_log:238517", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:238518", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_start None -> ''70''"}, {"source": "remediation_change_log:331788", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-006-001: thumbnail_url ''/data/images/wiki/5f9051e0/hero.webp'' -> ''/data/images/wiki/5f9051e0/High Street, Kingston upon Hull (geograph 3824295).webp''"}]'::jsonb),
