    ('5f9bc540-443e-41d6-93af-9c65dd28673b'::uuid, 'antiquity', '5', '7', 'card-stats-2026-11-05-rollback:5f9bc540-443e-41d6-93af-9c65dd28673b:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Anta de Carcavelos', 'd34526f6a7c68c991e26d32c03c89cac', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:34623", "url": "remediation_change_log", "quote": "phase4:p4-0033:chunk-0001: description ''The Anta de Carcavelos is a Chalcolithic-period dolmen located near Carcavelos village in the municipality of Loures, Lisbon District, Portugal [1]. Dating to 4500–3000 BC, it served as a communal burial chamber with a polygonal-shaped sepulchral chamber [1]. The remaining structure consists of six cretaceous limestone slabs, representing one of many megalithic tombs documented across Portugal [1][2].'' -> ''The Anta de Carcavelos, located close to the village of Carcavelos near the town of Lousa in the municipality of Loures in the Lisbon District of Portugal, is a stone age dolmen or megalithic monument from the Chalcolithic period [1]. The Anta was a communal grave consisting of a sepulchral chamber with a polygonal shape [1]. The remains of the tomb consist of six cretaceous limestone slabs that originated in the area, which has several sizeable limestone outcrops [1]. Hastened as a result of looting at the site, the first excavations were carried out in 1986 and continued again from 1991-1994 [1]. From the studies carried out in 1994, many bones were collected, with over 80 adult males and females believed to have been buried there [1]. Various objects were also found such as flint arrowheads, smooth and decorated bell-shaped ceramics, dishes, cylindrical idols, and objects of adornment [1]. The evaluation of items found suggested a probable initial use of the dolmen as being in the last centuries of the 4th millennium BCE, with an intensification in its use between 3000 and 2600 BCE [1].''"}, {"source": "remediation_change_log:100051", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:100052", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:238522", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:238523", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_start None -> ''-3000''"}, {"source": "remediation_change_log:325241", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/5f9bc540/hero.webp'' -> ''/data/images/wiki/5f9bc540/AntadeCarcavelos1.webp''"}, {"source": "remediation_change_log:345690", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_name ''3000 - 1500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:345691", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_start ''-3000'' -> None"}]'::jsonb),
