    ('611a3218-4df9-4018-8d46-c1e731f04b2a'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:611a3218-4df9-4018-8d46-c1e731f04b2a:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Brean Down', '95896a6182b19c9ced4e72878357f4bc', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43533", "url": "remediation_change_log", "quote": "phase4:p4-0075:chunk-0001: description ''Brean Down is a limestone promontory extending 2.5 km into the Bristol Channel in Somerset, rising 97 m high as a geological continuation of the Mendip Hills. The site has deep archaeological layers spanning over 10,000 years, including evidence of extinct megafauna, Bronze Age and Iron Age occupation, and prehistoric field systems. A Romano-Celtic temple was built here around 340 AD, featuring a square cella sanctuary with an ambulatory, vestibule, and a porch flanked by Tuscan columns of Bath stone; it was demolished roughly 50 years later. The promontory is a scheduled monument and Site of Special Scientific Interest, managed by the National Trust.'' -> ''Brean Down is a promontory off the coast of Somerset, England [1]. The site has been occupied by humans since the late Bronze Age and includes the remains of a Romano-Celtic Temple [1]. Human occupation dates back to the Beaker culture of the late Bronze Age [1]. There is also evidence of an Iron Age hill fort and prehistoric barrows and field systems [1]. There is evidence of a shrine dating from pre-Roman times, which was re-established as a Romano-Celtic Temple in the mid-4th century [1]. Several Roman finds including gold coins of Augustus, Nero, and Drusus, two silver denarii of Vespasian and a Roman carnelian ring were found at the site during quarrying [1].''"}, {"source": "remediation_change_log:84227", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:84228", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:84229", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: site_type ''Fortress/citadel'' -> ''Fort''"}, {"source": "remediation_change_log:84230", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: source_url ''https://en.wikipedia.org/wiki/Brean_Down'' -> ''https://www.megalithic.co.uk/article.php?sid=25260''"}, {"source": "remediation_change_log:151102", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''/data/images/wiki/611a3218/hero.webp'' -> ''/data/images/wiki/611a3218/Brean, UK - panoramio (13).webp''"}, {"source": "remediation_change_log:249195", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:249196", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_start None -> ''-358900''"}, {"source": "remediation_change_log:311382", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-006: thumbnail_url ''/data/images/wiki/611a3218/Brean, UK - panoramio (13).webp'' -> ''/data/images/wiki/611a3218/BreanDown2.webp''"}, {"source": "remediation_change_log:349098", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''< 4500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349099", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: p