    ('61e8d3cd-1e93-4c78-a558-f2955a9fe221'::uuid, 'mystery', '7', '8', 'card-stats-2026-11-05-rollback:61e8d3cd-1e93-4c78-a558-f2955a9fe221:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Sacsayhuamán', '81c3a0cebfd677bcd286f7a3cfc12b45', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Fortress/citadel'', ''500 - 1000 AD'') is shared by 9 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28312", "url": "remediation_change_log", "quote": "phase3:batch-0109:chunk-0001: period_start ''1000'' -> ''900''"}, {"source": "remediation_change_log:30415", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1000 - 1500 AD'' -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:34631", "url": "remediation_change_log", "quote": "phase4:p4-0033:chunk-0001: description ''A massive Inca citadel on the northern outskirts of Cusco, Peru, built under Emperor Pachacuti in the 15th century using approximately 20,000 laborers. The fortress features three concentric zigzag walls stretching over 540 metres, built from precisely interlocking polygonal stone blocks -- some exceeding 100 tons -- fitted without mortar. Beyond military defense, Sacsayhuaman served as a religious center with temples to the sun god Inti and a major storage depot. Part of the UNESCO World Heritage City of Cusco, it hosts the annual Inti Raymi festival.'' -> \"Sacsayhuamán or Saksaywaman is a citadel on the northern outskirts of the city of Cusco, Peru, the historic capital of the Inca Empire [1]. The site is an important example of Inca architecture and sits at an altitude of 3,701 metres [1]. The Spanish chroniclers recorded that within the Inca''s oral history, the fortress was said to be built during the reign of Sapa Inca Pachacuti and his successors, Topa Inca Yupanqui and Huayna Capac [1]. Dry stone walls constructed of huge stones were built on the site, with the workers carefully cutting the boulders to fit them together tightly without mortar [1]. Archeological studies of surface collections of pottery at Sacsayhuamán indicate that the earliest occupation of the hilltop dates to about 900 CE [1]. During the 15th century, the Imperial Inca expanded on this settlement, building dry stone walls constructed of huge stones [1].\""}, {"source": "remediation_change_log:100094", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: site_type ''Megalithic structures'' -> ''Fortress/citadel''"}, {"source": "remediation_change_log:151120", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/6/60/Sacsayhuam%C3%A1n%2C_Cusco%2C_Per%C3%BA%2C_2015-07-31%2C_DD_27.JPG'' -> ''/data/images/wiki/61e8d3cd/Sacsayhuamán,_Cusco,_Perú,_2015-07-31,_DD_21.webp''"}, {"source": "remediation_change_log:333886", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-001: thumbnail_url ''/data/images/wiki/61e8d3cd/Sacsayhuamán,_Cusco,_Perú,_2015-07-31,_DD_21.webp'' -> ''/data/images/wiki/61e8d3cd/Sacsayhuamán,_Cusco,_Perú,_2015-07-31,_DD_27.webp''"}]'::jsonb),
