    ('6290bb50-27f9-412e-86d8-0c9faf98dfc1'::uuid, 'mystery', '8', '6', 'card-stats-2026-11-05-rollback:6290bb50-27f9-412e-86d8-0c9faf98dfc1:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Rock Carvings at Møllerstufossen', '8e41b9a14b7324ae652133e517643e72', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Rock relief/carving'', ''< 4500 BC'') is shared by 4 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84928", "url": "remediation_change_log", "quote": "phase4:p4-2100:chunk-0001: description ''Mesolithic rock carvings along the River Etna in Nordre Land municipality, Innlandet county, Norway, dating to 6000-8000 years ago. The site covers about 20 sq m and contains 14 figures including eleven ungulates (mostly elk), one beaver, and two small human figures. The largest carving depicts a bull elk with massive antlers, measuring about 90 cm. Notably, animals are depicted with internal organs visible. Discovered in 1961 during logging operations, the carvings were made using pebbles as tools.'' -> ''The Rock carvings at Møllerstufossen are petroglyphs found in Nordsinni in Nordre Land Municipality in Innlandet county [1]. The carvings comprise several representations of moose and one other animal [1]. The site covers about 20 square metres [1]. The largest figure measures about 90 centimetres across [1]. The figures are easy to spot: they were carved with deep and wide strokes and have been repainted [1]. The river Etna runs approximately 10 metres away, and in spring nearly floods the site [1].''"}, {"source": "remediation_change_log:100108", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:100109", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:151625", "url": "remediation_change_log", "quote": "served-image-2026-09-30-014: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/92/Hellerisninger_Etna%2C_Nordre_Land.JPG'' -> ''/data/images/wiki/6290bb50/Helleristning Dokkaelva ved Møllerstuefossen - Oppland - Norway B.webp''"}, {"source": "remediation_change_log:238546", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:238547", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_start None -> ''-5600''"}, {"source": "remediation_change_log:312012", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-007: thumbnail_url ''/data/images/wiki/6290bb50/Helleristning Dokkaelva ved Møllerstuefossen - Oppland - Norway B.webp'' -> ''/data/images/wiki/6290bb50/Hellerisninger_Etna,_Nordre_Land.webp''"}]'::jsonb),
