e [1].''"}, {"source": "remediation_change_log:100108", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:100109", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:151625", "url": "remediation_change_log", "quote": "served-image-2026-09-30-014: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/92/Hellerisninger_Etna%2C_Nordre_Land.JPG'' -> ''/data/images/wiki/6290bb50/Helleristning Dokkaelva ved Møllerstuefossen - Oppland - Norway B.webp''"}, {"source": "remediation_change_log:238546", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:238547", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_start None -> ''-5600''"}, {"source": "remediation_change_log:312012", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-007: thumbnail_url ''/data/images/wiki/6290bb50/Helleristning Dokkaelva ved Møllerstuefossen - Oppland - Norway B.webp'' -> ''/data/images/wiki/6290bb50/Hellerisninger_Etna,_Nordre_Land.webp''"}]'::jsonb),
