    ('62baaf4c-8ad4-4bf4-b0e0-e5587c5a64a1'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:62baaf4c-8ad4-4bf4-b0e0-e5587c5a64a1:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Goffers Knoll', 'ebb99b801e7218f5cbd29bea172360c4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:34635", "url": "remediation_change_log", "quote": "phase4:p4-0033:chunk-0001: description ''Goffers Knoll is a prominent chalk spur on the Hertfordshire-Cambridgeshire border near Royston, standing about 60 m above sea level. Crowning the knoll within a copse of trees is a substantially intact Bronze Age bowl barrow, scheduled as an ancient monument since 1926. Despite partial excavation in the 1920s, the barrow is well preserved and retains archaeological remains and environmental evidence relating to its construction and use. The site lies along the ancient Icknield Way, a prehistoric trackway linking Wessex to East Anglia.'' -> ''Goffers Knoll is a prominent knoll on the Hertfordshire-Cambridgeshire border in the east of England, to the east of the town of Royston and south of Melbourn [1]. Hidden within the copse of trees which surmounts the knoll is a bowl barrow which dates from the Bronze Age and is reported to be substantially intact [1]. It is a scheduled ancient monument [1]. The barrow is 21m in diameter and stands some 1.5m in height above ground level [1]. In the absence of trees, the barrow would be a prominent landmark overlooking the ancient Icknield way and the low-lying land towards Duxford and Cambridge [1]. Excavations of the barrow were carried out by RC Neville in the mid 19th Century and again around 1920 [1].''"}, {"source": "remediation_change_log:117769", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:117770", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s004: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:249213", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:249214", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_start None -> ''-4000''"}, {"source": "remediation_change_log:349109", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:349110", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
