    ('63220a54-b953-4e72-a914-8f564b8f3e11'::uuid, 'antiquity', '4', '5', 'card-stats-2026-11-05-rollback:63220a54-b953-4e72-a914-8f564b8f3e11:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Mellor Hill Fort', 'a254a951d20d06cc143da91232734103', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 4 from period_start -500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29720", "url": "remediation_change_log", "quote": "phase3:batch-0333:chunk-0001: period_start ''-1500'' -> ''-500''"}, {"source": "remediation_change_log:30418", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:35793", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_name ''500 BC - 1 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:35794", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-500'' -> ''-1500''"}, {"source": "remediation_change_log:80934", "url": "remediation_change_log", "quote": "phase4:p4-2013:chunk-0001: description ''Mellor Hill Fort is a prehistoric hill fort in North West England, dating from the British Iron Age (800 BC to 100 AD). Located on a hill in Mellor, Greater Manchester, on the western edge of the Peak District, it overlooks the Cheshire Plain.[1] Evidence of activity dates back to 8,000 BC, and during the Bronze Age the site may have been used for funerary practices.[1] A Bronze Age amber necklace found at the site indicates high status and long-distance trade connections.[1] The settlement was occupied into the Roman period before being abandoned in the 4th century, and remained forgotten until its rediscovery in the 1990s.[1]'' -> ''Mellor hill fort is a prehistoric site in North West England dating from the British Iron Age – about 800 BC to 100 AD [1]. Situated on a hill in Mellor, Greater Manchester, on the western edge of the Peak District, the hill fort overlooks the Cheshire Plain [1]. Although the settlement was founded during the Iron Age, evidence exists of activity on the site as far back as 8,000 BC; during the Bronze Age the hill may have been an area where funerary practices were performed [1]. The settlement was occupied into the Roman period [1]. After the site was abandoned, probably in the 4th century, it was forgotten until its rediscovery in the 1990s [1]. At grid reference SJ9820088929, the known site of the Iron Age settlement in Mellor is partially under St Thomas Church and extends into the gardens of several nearby houses [1]. Over 200 lithics have been recovered and range from the early to the late Mesolithic [1]. The investigation of the site has revealed two ditches [1].''"}, {"source": "remediation_change_log:100115", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:100116", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:249219", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:249220", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_start None -> ''-800''"}, {"source": "remediation_change_log:349113", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remedi