    ('632852aa-7180-41f8-be7c-1da9cdc115e8'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:632852aa-7180-41f8-be7c-1da9cdc115e8:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Addington Long Barrow', 'be0259e6af747453e0271cf41e502d01', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84960", "url": "remediation_change_log", "quote": "phase4:p4-2101:chunk-0001: description \"Addington Long Barrow is a chambered long barrow located near the village of Addington in Kent, England[1]. Probably constructed in the fourth millennium BCE during Britain''s Early Neolithic period, today it survives only in a ruined state[1]. Built of earth and approximately fifty local sarsen megaliths, the long barrow consisted of a sub-rectangular earthen tumulus enclosed by kerb-stones[1].\" -> \"Addington Long Barrow is a chambered long barrow located near the village of Addington in the southeastern English county of Kent [1]. Probably constructed in the fourth millennium BCE, during Britain''s Early Neolithic period, today it survives only in a ruined state [1]. Archaeologists have established that the monument was built by pastoralist communities shortly after the introduction of agriculture to Britain from continental Europe [1]. Although representing part of an architectural tradition of long barrow building that was widespread across Neolithic Europe, Addington Long Barrow belongs to a localised regional variant of barrows produced in the vicinity of the River Medway, now known as the Medway Megaliths [1]. It lies near to both Chestnuts Long Barrow and Coldrum Long Barrow on the western side of the river [1]. The ruin attracted the interest of antiquarians in the early 18th century, and was studied by local archaeologists in the 20th [1]. Upon construction, the barrow would have been about 60 metres long [1].\""}, {"source": "remediation_change_log:151685", "url": "remediation_change_log", "quote": "served-image-2026-09-30-014: thumbnail_url ''/data/images/wiki/632852aa/hero.webp'' -> ''/data/images/wiki/632852aa/Addington Long Barrow, north side of road 07.webp''"}, {"source": "remediation_change_log:312030", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-007: thumbnail_url ''/data/images/wiki/632852aa/Addington Long Barrow, north side of road 07.webp'' -> ''/data/images/wiki/632852aa/Addington_Long_Barrow,_north_side_of_road_01.webp''"}]'::jsonb),
