    ('657dbfe1-7b3f-4548-93c6-99be8674a6ff'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:657dbfe1-7b3f-4548-93c6-99be8674a6ff:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Quoyness Chambered Cairn', 'bf8576fb3ae2b3c0942da9ebe8dbc5eb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Cairn'', ''3000 - 1500 BC'') is shared by 35 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28446", "url": "remediation_change_log", "quote": "phase3:batch-0135:chunk-0001: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:30421", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:85010", "url": "remediation_change_log", "quote": "phase4:p4-2102:chunk-0001: description ''Quoyness Chambered Cairn is a Neolithic burial monument on the island of Sanday in Orkney, Scotland. Similar to Maeshowe in design, the tomb was probably built around 3000 BC[1]. The skeletal remains of several people were uncovered during an excavation in 1867[1]. The monument was partially restored and reconstructed after a second excavation in the early 1950s to display the different original stages of construction[1]. The site is now in the care of Historic Environment Scotland as a scheduled monument[1].'' -> ''Quoyness chambered cairn is a Neolithic burial monument located on the island of Sanday in Orkney [1]. Similar to Maeshowe in design, the tomb was probably built around 3000 BC [1]. The skeletal remains of several people were uncovered in the tomb during excavation in 1867 [1]. The monument was partially restored and reconstructed after a second excavation during the early 1950s [1]. Quoyness chambered cairn is located on the Elsness peninsula [1]. The cairn sits on a wide, oval-shaped stone platform and was built with a mix of stones, earth and waste material intermixed with horizontal slabs [1]. A stone kerb surrounds the platform on the south and the west ends [1]. The cairn was excavated by James Farrer and George Petrie in 1867 [1].''"}, {"source": "remediation_change_log:151710", "url": "remediation_change_log", "quote": "served-image-2026-09-30-014: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/b/b3/Quoyness_cairn_%28cropped%29.jpg'' -> ''/data/images/wiki/657dbfe1/Quoyness_chambered_cairn_entrance.webp''"}, {"source": "remediation_change_log:334502", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/657dbfe1/Quoyness_chambered_cairn_entrance.webp'' -> ''/data/images/wiki/657dbfe1/Quoyness_cairn_(cropped).webp''"}]'::jsonb),
