    ('662d37b5-2ade-44f2-8ba6-3c6df5524bf8'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:662d37b5-2ade-44f2-8ba6-3c6df5524bf8:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Gudenus Cave', 'f33409b9d84ec61af764f0ae8315b964', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -68050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85018", "url": "remediation_change_log", "quote": "phase4:p4-2102:chunk-0001: description ''The Gudenus Cave is an archaeological site near Krems in northeastern Austria, used from the Middle Paleolithic through the Late Upper Paleolithic (approximately 16,000–10,000 BC). The deposit contains abundant faunal remains including woolly mammoth, woolly rhinoceros, aurochs, chamois, reindeer, and red deer. Archaeological finds include numerous flint implements associated with Mousterian (Neanderthal) occupation, making it significant for understanding Paleolithic human activity in the Danube region[1].'' -> ''The Gudenus Cave is an archaeological site near the city of Krems in north-eastern Austria [1]. It is noted for its fossils and remains of Palaeolithic human settlers [1]. The Gudenus Cavern is situated 20 km northwest of the city of Krems, in the valley of the Little Krems, not far from Willendorf [1]. The cave is 22 m long with a width of 2 to 3 m and is situated 7.5 m above the level of the stream [1]. The archaeological deposit has yielded bones of numerous animals, including Woolly mammoth, Woolly rhinoceros, Aurochs, Chamois, Reindeer, and Red deer [1]. Human artifacts include numerous flint implements beginning with the Mousterian of the Middle Paleolithic, although there is no certainty as to the dating [1]. There is also an Upper Palaeolithic, Magdalenian, assemblage including an engraved reindeer bone, and a fragment of a bone flute dated to about 16,000–10,000 BCE [1].''"}, {"source": "remediation_change_log:100837", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:100838", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_start ''-90000'' -> None"}, {"source": "remediation_change_log:151736", "url": "remediation_change_log", "quote": "served-image-2026-09-30-014: thumbnail_url ''/data/images/wiki/662d37b5/hero.webp'' -> ''/data/images/wiki/662d37b5/Gudenushöhle_Noe_01.webp''"}, {"source": "remediation_change_log:249245", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:249246", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_start None -> ''-500''"}, {"source": "remediation_change_log:312078", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-007: thumbnail_url ''/data/images/wiki/662d37b5/Gudenushöhle_Noe_01.webp'' -> ''/data/images/wiki/662d37b5/Weinzierl_am_Walde_-_Gudenushöhle,_linker_Eingangsbereich.webp''"}, {"source": "remediation_change_log:357189", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s004: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:357190", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s004: period_start ''-500'' -> ''-68050''"}]'::jsonb),
