    ('6726100a-71c5-44b2-9286-b176dd495a51'::uuid, 'mystery', '1', '5', 'card-stats-2026-11-05-rollback:6726100a-71c5-44b2-9286-b176dd495a51:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Arsemia Ören Yeri', '6f1cf890652a609f0d94d6e3b1125f67', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''500 BC - 1 AD'') is shared by 316 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80942", "url": "remediation_change_log", "quote": "phase4:p4-2013:chunk-0001: description ''Summer capital of the Kingdom of Commagene, founded c. 260 BC by King Arsames on the Nymphaios River near modern Adiyaman, Turkey. The site features a hierothesion (sacred tomb) built by Antiochus I for his father Mithridates I Kallinikos, with three dexiosis reliefs showing kings shaking hands with deities. It contains the longest known Greek inscription in Anatolia, detailing founding rites in five columns, and a 160-meter tunnel of unknown purpose. Discovered in 1951 by Friedrich Karl Dorner.'' -> \"Arsameia on the Nymphaios is an ancient city located in Old Kâhta (Eski Kâhta) in Kâhta district, Adıyaman Province, Turkey [1]. The site is near Kâhtaçay, known in ancient times as Nymphaios [1]. Arsameia was a royal seat of the kingdom of Commagene [1]. The ancient town of Nymphaios was renamed Arsameia in the third century BCE by the Armenian king Arsames (255–225 BCE) [1]. Apart from the Hierothesion which Antiochos himself built on Nemrut Dağı, and the second one on Karakuş which his son Mithridates II built for the female members of the royal house, a third is to be found in Arsameia, the burial site and the associated cultic area for Antiochus'' father Mithridates [1].\""}, {"source": "remediation_change_log:118841", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: period_name ''1 - 500 AD'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:118842", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: period_start ''1'' -> ''-300''"}, {"source": "remediation_change_log:118843", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: site_type ''Temple complex'' -> ''City''"}, {"source": "remediation_change_log:355876", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
