tion_change_log:337869", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4317:chunk-0001: description ''Anku is an archaeological settlement in the Peruvian Andes, located in the Huánuco Region, Huamalíes Province, Tantamayo District at approximately 3,900 meters (12,795 ft) elevation [1]. Its name derives from Aymara, meaning \"indomitable, unstoppable\" [1]. Anku was declared a National Cultural Heritage by Peruvian authorities on June 18, 2002, under Resolución Directoral No. 533/INC [1].'' -> ''Anku was declared a National Cultural Heritage by Peruvian authorities on June 18, 2002, under Resolución Directoral No. 533/INC [1].''"}, {"source": "remediation_change_log:349131", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349132", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-800'' -> None"}, {"source": "remediation_change_log:355877", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Citadel'' -> ''Fortress/citadel''"}]'::jsonb),
    ('67661f87-a03e-4e21-b8d1-c62fbf91361d'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:67661f87-a03e-4e21-b8d1-c62fbf91361d:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Treasury of Atreus', '1c0714b265ab050d27721ac0ff373522', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Necropolis/tombs complex'', ''1500 - 500 BC'') is shared by 24 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27866", "url": "remediation_change_log", "quote": "phase3:batch-0020:chunk-0003: period_start ''-1500'' -> ''-1300''"}, {"source": "remediation_change_log:34831", "url": "remediation_change_log", "quote": "phase4:p4-0034:chunk-0001: description \"The Treasury of Atreus (Tomb of Agamemnon) is the largest and most elaborate tholos tomb of the Aegean Bronze Age, built between 1350 and 1250 BC at Mycenae. Its corbelled dome, nearly 15 m in diameter and over 13 m high, remained the world''s largest dome until the Roman Pantheon. The entrance features a monumental lintel weighing approximately 120 tons, flanked by half-columns of green marble carved with spirals and zigzags, now in the British Museum. A long dromos passage leads to the circular chamber with a secondary rock-hewn burial room.\" -> \"The Treasury of Atreus is the largest and most elaborate of the known Mycenaean tholos tombs [1]. It follows the typical tripartite division of these tombs into a narrow rectangular passageway (dromos), joined by a deep doorway (stomion) to a burial chamber (thalamos) surmounted by a corbelled dome [1]. The dome was covered with earth to heighten it; some of this mound remains, but erosion has reduced its height and moved its apex towards the west [1]. The dromos of the tomb is oriented east-west and is 36 m long by 6 m wide [1]. For the first 19 metres from the stomion, the sides are dressed with conglomerate stone walls: while the dromoi of earlier tombs had been lined with rubble or poros ashlar, the Treasury of Atreus is the first tomb at Mycenae to be fully lined with conglomerate [1]. The Treasury of Atreus is set alone at the southern edge of a bowl on the Panagia ridge''s eastern slope [1]. The first securely-documented entrance to the tomb was undertaken by the British aristocrat Thomas Bruce, 7th Earl of Elgin [1].\""}, {"source": "remediation_change_log:35808", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-1300'' -> ''-1500''"}, {"source": "remediation_change_log:151750", "url": "remediation_change_log", "quote": "served-image-2026-09-30-014: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/d/dc/Treasury_of_Atreus_Mycenae.jpg'' -> ''/data/images/wiki/67661f87/Treasury_of_Atreus_and_Maycenae,_20M0599.webp''"}, {"source": "remediation_change_log:312108", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-007: thumbnail_url ''/data/images/wiki/67661f87/Treasury_of_Atreus_and_Maycenae,_20M0599.webp'' -> ''/data/images/wiki/67661f87/Treasury_of_Atreus_Mycenae.webp''"}]'::jsonb),
