    ('68677772-b461-49a3-bf2b-376e2b0e970b'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:68677772-b461-49a3-bf2b-376e2b0e970b:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Lake Mungo', '64c47b8c841a42deb0d85b79ef67ebe2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -48050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:32719", "url": "remediation_change_log", "quote": "phase4:p4-0001:chunk-0001: description ''Lake Mungo is a dry lake in New South Wales, Australia, approximately 760 km west of Sydney and 90 km northeast of Mildura[1]. It is the central feature of Mungo National Park and one of seventeen lakes in the World Heritage-listed Willandra Lakes Region[1]. The site is famous for the discovery of Mungo Man, the oldest human remains found in Australia, and Mungo Woman[1]. It also marks the location of the Lake Mungo geomagnetic excursion, the first convincing evidence that geomagnetic excursions are a geomagnetic phenomenon rather than sedimentological[1].'' -> ''Lake Mungo is a dry lake located in New South Wales [1]. It is about 760 km due west of Sydney and 90 km north-east of Mildura [1]. Sediments at Lake Mungo have been deposited over more than 120,000 years [1]. On the eastern side of the Mungo lake bed are the \"Walls of China,\" a series of crescent-shaped sand dunes or lunettes, up to 40 m in height, that stretch for more than 33 km, where most archaeological material has been found [1]. The most publicized findings at Lake Mungo have been Mungo Man and Mungo Woman [1]. Mungo Woman was only partially cremated before the remainder of her bones were crushed [1]. The first evidence of human occupation in Lake Mungo was revealed after an excavation of two Lake Mungo trenches contained 11 silcrete flakes [1]. Fish otoliths have been recovered from hearths in Lake Mungo [1].''"}, {"source": "remediation_change_log:100861", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:100862", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_start ''-500'' -> None"}, {"source": "remediation_change_log:151767", "url": "remediation_change_log", "quote": "served-image-2026-09-30-014: thumbnail_url ''/data/images/wiki/68677772/hero.webp'' -> ''/data/images/wiki/68677772/Lake_Mungo_lunette.webp''"}, {"source": "remediation_change_log:249259", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:249260", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_start None -> ''-500''"}, {"source": "remediation_change_log:349133", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:349134", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-500'' -> ''-48050''"}]'::jsonb),
