    ('6b6a62fc-a743-47a2-9caf-9d41ee6a36e7'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:6b6a62fc-a743-47a2-9caf-9d41ee6a36e7:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on The Pipers, St Buryan', '6536bc1db6bf7362c07560bb2312c51f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:34871", "url": "remediation_change_log", "quote": "phase4:p4-0035:chunk-0001: description \"The Pipers at St Buryan are a pair of standing stones near the Merry Maidens stone circle in west Cornwall. The NE Piper stands 4.6 metres tall, making it Cornwall''s tallest standing stone, while the SW Piper measures 4.1 metres. Aligned northeast to southwest, they point almost directly at the Merry Maidens circle, a Late Neolithic to Early Bronze Age monument of nineteen granite megaliths. Legend holds the Pipers were musicians petrified for playing on the Sabbath, though another tradition says they commemorate leaders Howel and Aethelstan who died in a 10th-century battle.\" -> ''The Pipers are a pair of standing stones near The Merry Maidens stone circle located 2 miles to the south of the village of St Buryan, in Cornwall, United Kingdom [1]. The Pipers are on a northeast to southwest alignment which points almost directly at The Merry Maidens [1]. The two stones stand in separate fields about 90 metres apart [1]. The southwest stone is the taller of the two, measuring 4.7 metres high—there are two longitudinal cracks down the northwest side, and one down the southeast side [1]. The northeast stone is 4.2 metres high and is of rectangular section—the stone leans to the northwest [1]. The stones were first recorded by William Borlase in 1754 [1]. His descendant William Copeland Borlase excavated the stones in 1871 with no result [1].''"}, {"source": "remediation_change_log:100915", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:100916", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:152270", "url": "remediation_change_log", "quote": "served-image-2026-09-30-015: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/3/3a/%22The_Pipers%22_standing_stones_near_Boleigh_Farm_-_geograph.org.uk_-_41054.jpg'' -> ''/data/images/wiki/6b6a62fc/The Pipers 05.webp''"}, {"source": "remediation_change_log:249287", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:249288", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_start None -> ''-4000''"}, {"source": "remediation_change_log:349157", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:349158", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s004: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
