    ('6c689af9-749f-4272-aa69-d1634dd8e4d5'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:6c689af9-749f-4272-aa69-d1634dd8e4d5:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Lyneham Long Barrow', '3bc576dadc60cd1183a6730a5315a388', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85146", "url": "remediation_change_log", "quote": "phase4:p4-2106:chunk-0001: description ''Lyneham Long Barrow is a Neolithic chambered long barrow near Lyneham, Oxfordshire, likely one of the earliest surviving structures in the area at 5,000 to 6,000 years old. The mound extends up to 52 m long and 19 m wide with a 1.8 m tall standing stone nearby. A partial excavation in 1894 by Lord Moreton and Edward Conder uncovered two internal chambers containing human and animal bones, pottery, and charcoal, along with secondary Anglo-Saxon burials cut into the top of the mound.'' -> ''Lyneham Longbarrow is a long barrow near Lyneham, Oxfordshire [1]. Just nine metres from the barrow mound stands a 1.8-metre-tall standing stone [1]. Lyneham barrow stands on a ridge overlooking valleys to the northwest and southeast [1]. The long barrow mound is 52 metres long, 19 metres wide and stands up to 1.75 metres high [1]. The stone may have been part of a facade of standing stones [1]. The barrow was excavated in 1894 [1]. The excavations located two chambers on the southeast side of the mound and at least one of these contained bone fragments, pottery and charcoal [1]. Also found were two Anglo-Saxon burials which had been cut into the top of the existing mound [1].''"}, {"source": "remediation_change_log:100929", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:100930", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:249657", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:249658", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_start None -> ''-4000''"}, {"source": "remediation_change_log:312172", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-007: thumbnail_url ''/data/images/wiki/6c689af9/hero.webp'' -> ''/data/images/wiki/6c689af9/Lyneham Longbarrow - geograph.org.uk - 3144.webp''"}]'::jsonb),
