    ('6cf72484-5b8f-44b0-acfe-fd70ebfa5f26'::uuid, 'antiquity', '3', '5', 'card-stats-2026-11-05-rollback:6cf72484-5b8f-44b0-acfe-fd70ebfa5f26:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Abbatija Tad-Dejr Hypogeal Complex', '92c75753f8ef373c4249e93d26cd7ad1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 3 from period_start 330"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44487", "url": "remediation_change_log", "quote": "phase4:p4-0095:chunk-0001: description ''The Abbatija tad-Dejr is an early Christian hypogeal burial complex in Rabat, Malta, comprising four interconnected underground chambers carved into rock [1][2]. The main hypogeum features a rectangular hallway with five wall openings leading to burial areas, with baldacchino tombs in a grid pattern decorated with spirals, fish-scale motifs, and palm branches [1][2]. Roman funerary elements including triclinia and window tombs are found across all four hypogea [2]. The complex developed gradually from the 4th to 9th century, with excavations conducted between 1926 and 1933 [3]. Around the 13th century the site was converted into a Christian oratory, featuring a Crucifixion fresco with the Virgin Mary, John, and Archangel Gabriel, along with coats-of-arms now housed at MUZA in Valletta [1].'' -> ''The Abbatija Tad-Dejr hypogeal complex is a paleochristian burial site in Rabat, Malta [1]. The early catacombs comprised a singular shaft and chamber tombs dug from the vertical face of a quarry [1]. Baldacchino tombs are often considered to be the richest out of the array of tomb types found in Maltese catacombs; at least three such tombs in this complex are heavily decorated with reliefs [1]. In the post-Roman period, the largest catacomb was enlarged and turned into a small church [1]. The presence in the hypogeum of a stone altar and the number of crosses carved into the rock surface suggest early Christian use [1]. A fresco that, until recently, decorated the apse over the supposed location of the original altar is now housed in the National Museum of Fine Arts [1]. The catacombs underwent various other phases of use, including as cow pens and for the quarrying of stone used in the production of lime [1]. The latter has resulted in extensive damage [1].''"}, {"source": "remediation_change_log:100948", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:100949", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_start ''1'' -> None"}, {"source": "remediation_change_log:152318", "url": "remediation_change_log", "quote": "served-image-2026-09-30-015: thumbnail_url ''/data/images/wiki/6cf72484/hero.webp'' -> ''/data/images/wiki/6cf72484/Crucifixion with Annunciation (fresco from Abbatija tad-Dejr), MUŻA, Valletta 001.webp''"}, {"source": "remediation_change_log:249669", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:249670", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_start None -> ''-800''"}, {"source": "remediation_change_log:334517", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/6cf72484/Crucifixion with Annunciation (fresco from Abbatija tad-Dejr), MUŻA, Valletta 001.webp'' -> ''/data/images/wiki/6cf72484/hero.webp''"}, {"source": "remediation_change_log:349897", "url": "remediation_change_log", "quote": "2026-10-17a_fields-w