    ('6e49927e-99cd-480d-8474-4da41b51ae46'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:6e49927e-99cd-480d-8474-4da41b51ae46:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Swastika Stone', '532b49fb51d919c4fa889eb2dc2b0eb2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85186", "url": "remediation_change_log", "quote": "phase4:p4-2107:chunk-0001: description ''The Swastika Stone is a prehistoric rock carving on Woodhouse Crag at the northern edge of Ilkley Moor in West Yorkshire, England[1]. The stone features a double-outlined swastika design with four curved arms and an attached S-shape, each enclosing a distinctive \"cup\" mark[2]. Similar cup and ring marks are found on other stones across the moor[3].'' -> ''The Swastika Stone is a stone adorned with a swastika, located on the Woodhouse Crag on the northern edge of Ilkley Moor in West Yorkshire [1]. It is the only one of its kind known in Britain [1]. The design has a double outline with four curved arms and an attached S-shape, each enclosing a so-called \"cup\" mark [1]. Similar cup and ring marks can be found on other stones nearby [1]. The stone has not been verifiably dated [1]. The academic consensus suggests it to have been carved sometime around the Neolithic or early Bronze Age, although Frank Elgee suggests that the design indicates a late Iron Age origin [1].''"}, {"source": "remediation_change_log:100967", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: per