    ('6f6c5cc0-b0ac-4222-bb04-747352eb83d1'::uuid, 'antiquity', '5', '6', 'card-stats-2026-11-05-rollback:6f6c5cc0-b0ac-4222-bb04-747352eb83d1:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on Garden of the Fugitives, Pompeii', 'ccd5a66c6f104562e9c055a8d3bc0b9a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29730", "url": "remediation_change_log", "quote": "phase3:batch-0334:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:80976", "url": "remediation_change_log", "quote": "phase4:p4-2015:chunk-0001: description ''Archaeological site in Regio I, Insula 21 of ancient Pompeii containing plaster casts of 13 victims of the 79 AD eruption of Mount Vesuvius. Discovered in 1961 under the direction of Amedeo Maiuri, the casts were created by pouring liquid plaster into cavities left by decomposed bodies, a technique pioneered by Giuseppe Fiorelli in the 19th century. The victims, including men, women, and children, were caught by a pyroclastic surge while fleeing toward the Nocera Gate. The area had been a vegetable garden and vineyard with a triclinium for outdoor banquets before the eruption.'' -> ''The Garden of the Fugitives is an archaeological site located in the ancient destroyed city of Pompeii, in Regio 1 Insula 21 [1]. It contains the casts of 13 victims of the eruption of Mount Vesuvius in 79 AD [1]. The insula once contained more town houses than the two which stand at the northwestern end of the insula but the rest of the area had been largely converted into a vegetable garden and vineyard before the eruption, with a triclinium covered by a pergola for outdoor banquets [1]. The garden is situated near the Large Palaestra and just inside the Nocera gate [1]. The victims were adults and children, several found close together and others scattered over the area [1]. They died apparently while trying to find a way out of the Nocera Gate, as they were above the layer of pumice that had already reached a height of 3.5 metres, and were caught by the pyroclastic flow which was fatal [1]. The Fugitives were uncovered by Amedeo Maiuri [1]. They were uncovered in 1961 as hollow cavities where the flesh had rotted away [1].''"}, {"source": "remediation_change_log:100990", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:100991", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:249693", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:249694", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_start None -> ''-1500''"}, {"source": "remediation_change_log:349914", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349915", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-1500'' -> None"}]'::jsonb),
