    ('70762563-db82-43f3-ad30-bce5fde9c9bd'::uuid, 'mystery', '8', '10', 'card-stats-2026-11-05-rollback:70762563-db82-43f3-ad30-bce5fde9c9bd:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Syberg', '99b58d8973efb8263d02e1870268a3a4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Castle/palace'', ''500 - 1000 AD'') is shared by 3 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:34913", "url": "remediation_change_log", "quote": "phase4:p4-0036:chunk-0001: description ''The Syberg is a 240-metre hill in southern Dortmund, part of the Ardey Hills, with archaeological remains spanning from the Neolithic era through the Middle Ages. Around 700 AD, Westphalian Saxons built a hillfort called the Sigiburg, which Charlemagne captured in 775 during the Saxon Wars. The Saxons failed to reconquer it two years later. In the High Middle Ages, the Archbishop of Cologne established a castle on the site from 1150, which was destroyed in the 16th-17th centuries. Today, partial stone walls and the Vincke Tower remain, alongside a monument to Kaiser Wilhelm I.'' -> ''The Syberg is a hill in the Ruhr in the southern part of Dortmund, 240 m above sea level, which is part of the Ardey Hills [1]. The Syberg is part of the Ardey Hills, and was formed of sandstone and slate of the Namurian, a stratigraphic unit of the Carboniferous [1]. The oldest relicts of human presence on the Syberg are from the Neolithic and Bronze Age [1]. Syberg became a historical location during the Saxon Wars, when Charlemagne captured a hillfort on top of the hill named \"Sigiburg\" in 775 AD; two years later the Saxons failed with a reconquest of Sigiburg [1].''"}, {"source": "remediation_change_log:118946", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: period_name ''4500 - 3000 BC'' -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:118947", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: period_start ''-4500'' -> ''700''"}, {"source": "remediation_change_log:118948", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: site_type ''City/town/settlement'' -> ''Castle''"}, {"source": "remediation_change_log:118949", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: source_url ''https://en.wikipedia.org/wiki/Syberg'' -> ''https://en.wikipedia.org/wiki/Sigiburg''"}, {"source": "remediation_change_log:152419", "url": "remediation_change_log", "quote": "served-image-2026-09-30-015: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/2/2b/Syberg_2012-03-11-6107.jpg'' -> ''/data/images/wiki/70762563/Dortmund Syburg - Syberg (Ruhrbrücke Dortmunder Straße) 01 ies.webp''"}, {"source": "remediation_change_log:331836", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-006-001: thumbnail_url ''/data/images/wiki/70762563/Dortmund Syburg - Syberg (Ruhrbrücke Dortmunder Straße) 01 ies.webp'' -> ''/data/images/wiki/70762563/Ruine Hohensyburg, Blick vom Vincketurm.webp''"}, {"source": "remediation_change_log:355885", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Castle'' -> ''Castle/palace''"}]'::jsonb),
