    ('70c04f92-593e-467b-8568-b585e1cdb58f'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:70c04f92-593e-467b-8568-b585e1cdb58f:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Little Meg', '69680c91fd08584a6128b1938c0827b9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27806", "url": "remediation_change_log", "quote": "phase3:batch-0012:chunk-0001: period_start ''-4500'' -> ''-2500''"}, {"source": "remediation_change_log:30434", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:85264", "url": "remediation_change_log", "quote": "phase4:p4-2109:chunk-0001: description ''Little Meg is a small circle of large kerb stones probably surrounding a Bronze Age kerb cairn, located near Langwathby village northeast of Penrith in Cumbria, England. It lies 650 metres northeast of the famous Long Meg and Her Daughters stone circle, forming part of a complex that includes the circles at Glassonby, Old Parks, and other lost sites [1].'' -> \"Little Meg is a small circle of large kerb stones which probably surrounded a Bronze Age kerb cairn [1]. It is close to the village of Langwathby to the north-east of Penrith in the English county of Cumbria and is 650 metres north-east of the more famous stone circle of Long Meg and Her Daughters [1]. It forms part of a complex of stone circles and cairns around the Long Meg site that includes the circle at Glassonby, Old Parks, and other sites since lost [1]. Two of the stones (only one remaining) were decorated in antiquity with a series of concentric circles and a spiral [1]. When first discovered in the middle of the nineteenth century, there was a c.1.3m mound covering the stones [1]. Bones, charcoal and a ''coarse pot'' were found buried in a cist at the centre of the circle [1]. Two stones found in the cist (now in Penrith Museum), have cup and ring markings [1].\""}, {"source": "remediation_change_log:118955", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:118956", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: period_start ''-2500'' -> None"}, {"source": "remediation_change_log:118957", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: site_type ''Stone circle'' -> ''Cairn''"}, {"source": "remediation_change_log:249703", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:249704", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_start None -> ''-4000''"}, {"source": "remediation_change_log:349925", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:349926", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
