    ('71b5fca6-6ce4-43f0-bddd-6b3c15ca3f0e'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:71b5fca6-6ce4-43f0-bddd-6b3c15ca3f0e:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Naveta d''Es Tudons', '4c1731ce33dc94a05441e7cd1f40d918', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Necropolis/tombs complex'', ''1500 - 500 BC'') is shared by 24 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44515", "url": "remediation_change_log", "quote": "phase4:p4-0096:chunk-0001: description \"Naveta d''Es Tudons is the most remarkable megalithic chamber tomb in Menorca, dating to 1200–750 BC [1]. Located 4.8 km (3 mi) west of Ciutadella, near the Ciutadella-Mahón road, it stands on slight rising ground in a sloping valley [1]. The monument represents a pinnacle of Talaiotic culture funerary architecture, featuring a distinctive inverted-hull shape built with large stone blocks [1]. The site is open to the public for exterior visits [1].\" -> \"The Naveta d''Es Tudons is the largest and best preserved funerary naveta in Menorca [1]. The Naveta d''Es Tudons served as collective ossuary between 1200 and 750 BC [1]. The shape of the Naveta d''Es Tudons is that of a boat upside down, with the stern as its trapezoidal façade and the bow as its rounded apse [1]. Its groundplan is an elongated semicircle [1]. Externally, the edifice is 14.5 m long by 6.5 m wide and 4.55 m high but it would originally have been 6 m high [1]. The front, side walls and apse of the edifice consist of successive horizontal corbelled courses of huge rectangular or square limestone blocks dressed with a hammer and fitted together without mortar [1]. The narrow, low entrance doorway is rebated to receive a closing slab [1].\""}, {"source": "remediation_change_log:152923", "url": "remediation_change_log", "quote": "served-image-2026-09-30-016: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/8/8a/Naveta_des_Tudons.jpg'' -> \"/data/images/wiki/71b5fca6/Naveta d''Es Tudons (Menorca, 11 de agosto de 2014) 01.webp\""}, {"source": "remediation_change_log:331852", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-006-001: thumbnail_url \"/data/images/wiki/71b5fca6/Naveta d''Es Tudons (Menorca, 11 de agosto de 2014) 01.webp\" -> ''/data/images/wiki/71b5fca6/Naveta des Tudons.webp''"}]'::jsonb),
