    ('722bf4c1-6dca-454a-9d27-89503114e75c'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:722bf4c1-6dca-454a-9d27-89503114e75c:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Phyle Cave', 'cc73a868e76f68b539c1de8c91f89d85', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85292", "url": "remediation_change_log", "quote": "phase4:p4-2110:chunk-0001: description ''The Phyle Cave is a small cave on Mount Parnes near Fyli (Phyle), a suburb of Athens in Attica, Greece [1]. In ancient Greece it served as a sanctuary dedicated to Pan and the nymphs [1]. The cave is also known as Lychnospilia (Λυχνοσπηλιά), meaning \"lamp cave,\" named for the large number of oil lamps discovered within [1]. It has been identified as the cave mentioned in Menander\\''s comedy Dyskolos [1]. The cave was excavated in 1901 [1]. Three votive reliefs found in the cave are now displayed in the National Archaeological Museum of Athens [1].'' -> ''The Phyle Cave is a small cave on Mount Parnes near Fyli, a suburb of Athens in Attica, Greece [1]. In ancient Greece it was the site of a sanctuary to Pan and the nymphs [1]. It is also known as Lychnospilia, meaning lamp cave, for the large number of oil lamps found in the cave [1]. It has been identified as the cave which occurs in the Dyskolos of Menander [1]. The cave was excavated in 1901 [1]. Three votive reliefs found in the cave are now on display in the National Archaeological Museum of Athens [1]. Because of its use for the veneratio