    ('72396ba8-bfa7-46e1-8abe-e06c76dbe570'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:72396ba8-bfa7-46e1-8abe-e06c76dbe570:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on La Marche Cave', 'c86a8f185cd6eceb2ce23b657128a6a4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:80984", "url": "remediation_change_log", "quote": "phase4:p4-2015:chunk-0001: description ''La Marche is a cave and archaeological site in Lussac-les-Châteaux, Vienne, western France. Carved etchings discovered in 1937 depict detailed humans and animals that may be approximately 15,000 years old, dating to the Upper Paleolithic period. However, the authenticity of these cave paintings remains controversial and debated within the archaeological community [1].'' -> ''The La Marche cave is located in the Lussac-les-Châteaux area of western France [1]. It is at the bottom of a small valley bordered by the Petit Moulin river [1]. It most likely is the result of the underground tunneling of the river [1]. The La Marche cave paintings were discovered in the caves in the Lussac-les-Châteaux area of France by Léon Péricard in November 1937 [1]. Péricard, and his partner Stephane Lwoff, studied these caves for five years and found etchings on more than 1,500 slabs [1]. In 1938, they presented their discovery to the French Prehistoric Society [1].''"}, {"source": "remediation_change_log:101670", "url": "remediation_change_log", "quote": "2026-09-26d_f