    ('725d79b1-6918-484c-97eb-ff6ae947f840'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:725d79b1-6918-484c-97eb-ff6ae947f840:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Roman Milestones of Braga', 'd20c9f719dff6f98bfa34054b6ea7d84', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28280", "url": "remediation_change_log", "quote": "phase3:batch-0104:chunk-0005: site_type ''Megalithic stones'' -> ''Inscription''"}, {"source": "remediation_change_log:44517", "url": "remediation_change_log", "quote": "phase4:p4-0096:chunk-0001: description ''A series of ancient Roman road markers in Braga, northern Portugal, associated with the Via de Braga a Guimaraes that connected Bracara Augusta to surrounding settlements in the 1st century AD. Roman milestones were placed at intervals of about 1,480 metres, inscribed with distances to the Roman forum and construction details. Classified in 1910 by Martins Capela, who inventoried 21 milestones or fragments including 20 from Campo das Carvalheiras. They bear inscriptions from emperors including Claudius, Hadrian, Caracalla, Diocletian, and Constantine. Several are displayed at the D. Diogo de Sousa Museum in Braga.'' -> ''The Roman Milestones of Braga (Portuguese: Marcos Miliários no Concelho de Braga) are a series of ancient road markers located in civil parish of Braga, municipality of Braga in northern Portugal [1]. The Via de Braga a Guimarães was constructed during the period of Romanization of the later-Portuguese territory [1]. The milestones were essential to the consolidation of the new territorial administration imposed by Rome and the routes served inherent military purposes, while assuring the transport of raw materials essential to the good performance of the new imperial order [1]. Examples of the Roman milestones are housed in the installations of the Museum D. Diogo de Sousa [1].''"}, {"source": "remediation_change_log:101679", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:101680", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_start ''1'' -> None"}, {"source": "remediation_change_log:101681", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: site_type ''Inscription'' -> None"}, {"source": "remediation_change_log:152931", "url": "remediation_change_log", "quote": "served-image-2026-09-30-016: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/d/db/Geira_Milha_XXIX_detalhe.jpg'' -> None"}, {"source": "remediation_change_log:238666", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:238667", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_start None -> ''-41''"}, {"source": "remediation_change_log:238668", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: site_type None -> ''Monument''"}, {"source": "remediation_change_log:312298", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-007: thumbnail_url None -> ''/data/images/wiki/725d79b1/Geira_Milha_XXIX_detalhe.webp''"}, {"source": "remediation_change_log:349935", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:349936", "url": "remediation_change_log", "quote": "2026-10-17a_fields