    ('728762be-061a-4f8a-b03f-980153495b02'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:728762be-061a-4f8a-b03f-980153495b02:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Trier Amphitheatre', 'e32568c1e752f96c5dfe37b9001e76c9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Theatre'', ''1 - 500 AD'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85298", "url": "remediation_change_log", "quote": "phase4:p4-2110:chunk-0001: description ''The Trier Amphitheatre is a Roman amphitheatre in Trier, Germany, built in the mid-2nd century AD during the rule of Antoninus Pius. Measuring 120 by 145 meters and dug into the slope of the Petrisberg hill, it could accommodate approximately 20,000 spectators, making it the 10th largest surviving Roman amphitheatre. It hosted gladiatorial contests and also served a defensive role as part of the city walls. The amphitheatre is designated as part of the UNESCO World Heritage Site \"Roman Monuments, Cathedral of St. Peter and Church of Our Lady in Trier,\" inscribed in 1986.'' -> \"The Trier Amphitheater is a Roman amphitheater in Trier, Germany [1]. The structure which was dug into the side of a hill was erected around the 2nd century A.D during the rule of Antoninus Pius [1]. Measuring 120 by 145 meters, the amphitheatre could accommodate approximately 20,000 spectators and is the 10th largest Roman amphitheatre still intact [1]. It was built into what was at the time the city''s wall, to the east of the modern and Roman city centre [1]. When Constantius Chlorus moved to Trier, Germany around 293 during the Tetrarchy he renovated the amphitheater [1]. On the eastern bank of the amphitheatre, a small burial ground was discovered in 1996, containing the graves of 46 people [1].\""}, {"source": "remediation_change_log:152957", "url": "remediation_change_log", "quote": "served-image-2026-09-30-016: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/4/4a/Trier_Amphitheater_BW_2013-07-08_13-24-21.JPG'' -> ''/data/images/wiki/728762be/Trier_Amphitheater_BW_2013-07-08_12-48-48.webp''"}, {"source": "remediation_change_log:312304", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-007: thumbnail_url ''/data/images/wiki/728762be/Trier_Amphitheater_BW_2013-07-08_12-48-48.webp'' -> ''/data/images/wiki/728762be/Trier_Amphitheater_BW_2013-07-08_13-24-21.webp''"}]'::jsonb),
