    ('730f6c51-c41c-4f6a-9443-31acb7f007a3'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:730f6c51-c41c-4f6a-9443-31acb7f007a3:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Koonalda Cave', 'fc5bc97b14d24c31417d0671207c5cf9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28854", "url": "remediation_change_log", "quote": "phase3:batch-0204:chunk-0001: period_start ''-500'' -> ''-20000''"}, {"source": "remediation_change_log:30437", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:80988", "url": "remediation_change_log", "quote": "phase4:p4-2015:chunk-0001: description \"Koonalda Cave is an Aboriginal archaeological site on the Nullarbor Plain in South Australia, notable for containing the world''s most impressive display of Pleistocene-era finger flutings -- engravings made by drawing fingers across soft cave surfaces. Dating estimates range from 31,000 to 15,000 years ago. The cave also served as a flint mine, with nodules traded across 3,000 km of long-distance routes. Listed as Australian National Heritage in 2014, it holds deep significance for the Mirning people.\" -> ''Koonalda Cave is a cave in the Australian state of South Australia, on the Nullarbor Plain [1]. It is located within the Nullarbor Wilderness Protection Area, 99 kilometres west of the Nullarbor roadhouse and 97 kilometres north east from Eucla, Western Australia [1]. Thousands of square metres in the cave are covered in parallel finger-marked geometric lines and patterns, Aboriginal Australian artwork which has been dated as 20,000 years old [1]. The cave was abandoned 19,000 years ago [1]. Analysis of finger markings and archaeological deposits showed that Aboriginal people used the cave 22,000 years ago [1]. The cave was explored by an expedition led by Captain J. M. Thompson in 1935 [1]. In the 1960s, the cave was excavated by Alexandor Gallus, who found that Aboriginal people had mined flint there [1].''"}]'::jsonb),
