    ('73577152-2aef-4a45-9668-b0404238695b'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:73577152-2aef-4a45-9668-b0404238695b:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Halae', '4e34db591f4109e9195cda4441d693f8', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''< 4500 BC'') is shared by 105 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85306", "url": "remediation_change_log", "quote": "phase4:p4-2110:chunk-0001: description ''Ancient town in East Opuntian Lokris, Greece, situated by the sea on the Bay of Atalante near modern Theologos. Excavations by Hetty Goldman and Alice Walker from 1911 to 1935 uncovered a fortified acropolis with continuous occupation from the Neolithic through Late Roman or Byzantine periods, along with approximately 280 tombs of Archaic, Classical, and Hellenistic date. The acropolis contained a temple area, fortification walls with bastions, and a sanctuary, while a well yielded archaic figurines associated with worship of Athena. Pausanias described it as the last town of Boeotia, likely named after salt springs still found in the vicinity.'' -> ''Halae or Halai was a town of ancient Locris, situated upon the Opuntian Gulf, but belonging to Boeotia in the time of Strabo and Pausanias [1]. It is described by Pausanias as situated to the right of the Platanias River, and as the last town of Boeotia [1]. It probably derived its name from some salt springs which are still found in its neighbourhood [1]. Its site is located near modern Theologos, where some ruins exist near the church of St. John [1].''"}, {"source": "remediation_change_log:101694", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:101695", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:238678", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:238679", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s005: period_start None -> ''-6000''"}]'::jsonb),
