    ('73ebc428-aeb1-4512-9c52-af90a3768431'::uuid, 'antiquity', '8', '6', 'card-stats-2026-11-05-rollback:73ebc428-aeb1-4512-9c52-af90a3768431:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on Lindus', '5f16d8612a772ff774f98da888d12f6e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -4000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85332", "url": "remediation_change_log", "quote": "phase4:p4-2111:chunk-0001: description \"Lindos (ancient Lindus) is an archaeological site on the eastern coast of Rhodes, Greece, and was one of the island''s three original city-states before their unification in 408 BC. The acropolis, perched on a 116-metre cliff, features the Doric Temple of Athena Lindia, which reached its final form around 300 BC. In the 6th century BC, Lindos was ruled by Cleobulus, one of the Seven Sages of Greece. Danish excavations from 1902-1924 uncovered a temple chronicle compiled in 99 BC listing dedications from across the Mediterranean.\" -> ''Lindus or Lindos (Greek: Λίνδος) was one of the most important towns in ancient Rhodes [1]. In the Catalogue of Ships in the Iliad of Homer, Lindus, together with the two other Rhodian cities, Ialysus and Camirus, are said to have taken part in the war against Troy [1]. Previous to the year 408 BCE, when the city of Rhodes was built, Lindus, like the other cities, formed a little state by itself, but when Rhodes was founded, a great part of the population and the common government was transferred to the new city [1]. Lindus, however, though it lost its political importance, still retained religious importance, for it contained two ancient and much revered sanctuaries – one of Athena, hence called the Lindian, and the other of Heracles [1]. The former was believed to have been built by Danaus, or, according to others by his daughters on their flight from Egypt [1].''"}, {"source": "remediation_change_log:101700", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:101701", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:152979", "url": "remediation_change_log", "quote": "served-image-2026-09-30-016: thumbnail_url ''/data/images/wiki/73ebc428/hero.webp'' -> ''/data/images/wiki/73ebc428/1016 Temple of Athena Lindia at Rhodes Photo by Giles Laurent.webp''"}, {"source": "remediation_change_log:249733", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:249734", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_start None -> ''-1500''"}, {"source": "remediation_change_log:349947", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''1500 - 500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:349948", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-1500'' -> ''-4000''"}]'::jsonb),
