    ('75dccc9d-fb68-40a9-aa2e-e58a47067580'::uuid, 'mystery', '6', '4', 'card-stats-2026-11-05-rollback:75dccc9d-fb68-40a9-aa2e-e58a47067580:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Elephanta Caves', '105b9ae4963df9bd3eb7a5589d8715ca', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Cave Structures'', ''500 BC - 1 AD'') is shared by 19 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:30922", "url": "remediation_change_log", "quote": "phase3:gap-0013:chunk-0001: period_start ''-500'' -> ''500''"}, {"source": "remediation_change_log:35834", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''500'' -> ''-500''"}, {"source": "remediation_change_log:85368", "url": "remediation_change_log", "quote": "phase4:p4-2112:chunk-0001: description ''The Elephanta Caves are a rock-cut temple complex on Elephanta Island in Mumbai Harbour, Maharashtra, dating to approximately the 2nd century BCE [1]. Predominantly dedicated to the Hindu god Shiva, the complex features five Hindu caves with elaborate high-relief sculptures carved from solid basalt rock [1][2]. The artwork shows syncretism between Hindu and Buddhist iconographic traditions [2]. The island also contains Buddhist remains, including stupa mounds and two caves with water tanks, indicating multi-religious use [1]. UNESCO designated the Elephanta Caves as a World Heritage Site in 1987 [2].'' -> ''The Elephanta Caves form a collection of cave temples predominantly dedicated to the Hindu god Shiva; UNESCO has designated them as a World Heritage Site [1]. They are located on Elephanta Island, or Gharapuri, in Mumbai Harbour [1]. The island, about 2 kilometres west of the Jawaharlal Nehru Port, features five Hindu caves, a few Buddhist stupa mounds that date back to the 2nd century BCE, and two Buddhist caves with water tanks [1]. The Elephanta Caves contain rock-cut stone sculptures, mostly in high relief, that show a syncretism of Hindu—Buddhist ideas and iconography [1]. The caves are hewn from solid basalt rock [1]. The main cave (Cave 1, or the Great Cave) was a Hindu place of worship until the Portuguese arrived, whereupon the island ceased to be an active place of worship [1]. The main cave, also called Cave 1, Grand Cave, or the Great Cave, is 39.63 metres square in plan with a hall [1].''"}, {"source": "remediation_change_log:119010", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s005: site_type ''Temple complex'' -> ''Cave Structures''"}]'::jsonb),
