    ('763e4a8b-eed2-495d-81db-35f83a3d5d82'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:763e4a8b-eed2-495d-81db-35f83a3d5d82:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Blowing Stone', '2385098f1c8e955c37c38b090ba1cdd0', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85384", "url": "remediation_change_log", "quote": "phase4:p4-2112:chunk-0001: description \"The Blowing Stone is a perforated sarsen megalith in Kingston Lisle, Oxfordshire (historically Berkshire). Located at the foot of Blowingstone Hill south of the Icknield Way, this 3ft tall stone features multiple holes and a Y-shaped internal channel. When the largest hole is covered with the mouth and blown, the stone produces a distinctive musical note [1][2]. First recorded on Roque''s map of 1761, the stone sits near the Icknield Way, about 7km west of Wantage and 2.4km east of White Horse Hill on the Berkshire Downs escarpment [1][3].\" -> \"The Blowing Stone is a perforated sarsen in Kingston Lisle, Oxfordshire, England [1]. The stone is in a garden at the foot of Blowingstone Hill just south of the Icknield Way, about 4+1⁄2 miles (7 km) west of Wantage and about 1+1⁄2 miles (2.4 km) east of White Horse Hill [1]. Blowingstone Hill is part of the escarpment of the Berkshire Downs [1]. The stone is capable of producing a booming sound if someone with the required skill blows into one of the holes the right way [1]. Legend tells that it could be heard atop White Horse Hill, where 19th-century antiquarians thought King Alfred the Great''s Saxon troops had camped, and that this was how Alfred summoned them for the Battle of Ashdown against the Danes in 871 CE [1].\""}, {"source": "remediation_change_log:101744", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:101745", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:249757", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:249758", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s010: period_start None -> ''-4000''"}, {"source": "remediation_change_log:325272", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/763e4a8b/hero.webp'' -> ''/data/images/wiki/763e4a8b/Blowing Stone 2.webp''"}, {"source": "remediation_change_log:349962", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349963", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-4000'' -> None"}]'::jsonb),
