    ('786c39f1-9944-4733-93c5-4d465f5f7767'::uuid, 'mystery', '6', '4', 'card-stats-2026-11-05-rollback:786c39f1-9944-4733-93c5-4d465f5f7767:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Hembury', '1543eff4868196ae9b6f9e8ef588cd02', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Earthwork'', ''4500 - 3000 BC'') is shared by 13 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29049", "url": "remediation_change_log", "quote": "phase3:batch-0231:chunk-0001: period_start ''-5000'' -> ''-4500''"}, {"source": "remediation_change_log:30442", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''< 4500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:44549", "url": "remediation_change_log", "quote": "phase4:p4-0097:chunk-0001: description ''Hembury is a Neolithic causewayed enclosure and Iron Age hillfort near Honiton in Devon, England[1]. Its history spans from the late fifth and early fourth millennia BC to the Roman invasion[1]. The earthwork sits on a south-facing promontory at the end of a 240m high ridge in the Blackdown Hills, north of the River Otter valley[1]. This elevated position provided panoramic views of the surrounding countryside as well as natural defensive advantages[1]. The Devon Archaeological Society purchased the hillfort in 2022 to ensure its preservation[1].'' -> ''Hembury is a Neolithic causewayed enclosure and Iron Age hillfort near Honiton in Devon [1]. Its history stretches from the late fifth and early fourth millennia BC to the Roman invasion [1]. The fort is situated on a south facing promontory at the end of a 240m high ridge in the Blackdown Hills [1]. Originally a Neolithic site, an Iron Age hill fort was later built on the same site [1]. It was excavated between 1930 and 1935 by Dorothy Liddell [1]. She identified a timber framed entrance to the causewayed enclosure and an oval arrangement of postholes in the middle which she interpreted as being a building destroyed by fire before the enclosure earthworks were built [1]. During an excavation in the 1980s headed by Malcolm Todd, archaeological evidence was found on the site of Roman military occupation, suggesting a fort within the existing Iron Age site [1]. The site has given its name to some of the earliest Neolithic pottery in southern Britain after a large collection of pieces of this type of pottery were found during excavations by Dorothy Liddell [1].''"}, {"source": "remediation_change_log:101798", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:101799", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:153171", "url": "remediation_change_log", "quote": "served-image-2026-09-30-016: thumbnail_url ''/data/images/wiki/786c39f1/hero.webp'' -> ''/data/images/wiki/786c39f1/Hembury Hill III.webp''"}, {"source": "remediation_change_log:250123", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:250124", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''-4000''"}, {"source": "remediation_change_log:313006", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-008: thumbnail_url ''/data/images/wiki/786c39f1/Hembury Hill III.webp'' -> ''/data/images/wiki/786c39f1/Payhembury, Hembury hillfort - geograph.org.uk