    ('78c84929-bf4c-4cef-9335-6063ba3337f7'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:78c84929-bf4c-4cef-9335-6063ba3337f7:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Craddock Moor Stone Circle', 'fd778f67c3f1cd3026e838e514f45d84', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81022", "url": "remediation_change_log", "quote": "phase4:p4-2016:chunk-0001: description ''Craddock Moor Stone Circle is a Bronze Age monument on Bodmin Moor in Cornwall, dating to approximately 2500-1000 BC. Unusually, all of its stones are recumbent; originally up to 27 stones, only 17 survive today. The circle is situated roughly 0.8 km northwest of The Hurlers and may have been positioned so that the summit of Brown Willy marked the midsummer sunset. Despite being surveyed since its discovery in 1923, it has never been excavated. Its significance is enhanced by association with nearby contemporary ceremonial and funerary monuments on Craddock and Rillaton Moor.'' -> ''Craddock Moor Stone Circle or Craddock Moor Circle is a stone circle located near Minions on Bodmin Moor in Cornwall [1]. It is situated around half a mile Northwest of The Hurlers [1]. The circle consists of sixteen fallen stones with one remaining possible stump [1]. John Barnatt has suggested that the circle was situated so that the summit of Brown Willy marked the midsummer sunset [1]. It is nearby to Craddock Moor stone row and an embanked enclosure [1]. One of the first archaeological surveys of Bodmin Moor, including Craddock Moor Circle was carried out c. 1800 by Nicholas Johnson and Peter Rose [1].''"}, {"source": "remediation_change_log:101802", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:101803", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:250129", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:250130", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''-4000''"}, {"source": "remediation_change_log:349982", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:349983", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
