    ('79132373-7a68-45e3-a174-3b1e429a12b3'::uuid, 'antiquity', '5', '7', 'card-stats-2026-11-05-rollback:79132373-7a68-45e3-a174-3b1e429a12b3:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Punta de Estaca de Bares', 'ce05a6d2e450c117e08d8ec48289653a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28008", "url": "remediation_change_log", "quote": "phase3:batch-0049:chunk-0005: site_type ''City/town/settlement'' -> ''Natural feature''"}, {"source": "remediation_change_log:85468", "url": "remediation_change_log", "quote": "phase4:p4-2114:chunk-0001: description ''Punta de Estaca de Bares is the northernmost point of the Iberian Peninsula in Galicia, Spain, with archaeological remains spanning the Early Iron Age to the Late Classical Period. The site features ruins of a Phoenician salt fish factory and port, evidence of ancient maritime trade and fish processing activities along this strategic Atlantic coastline. The ruins are open to visitors alongside an 1850 lighthouse still in operation. During WWII, a German submarine was sunk offshore, adding layers of historical significance to this remote headland.'' -> ''Punta da Estaca de Bares is the northernmost point of Spain and the Iberian Peninsula, at a latitude of 43° 47′ 38″ North [1]. It is located in Galicia [1]. The peninsula of Estaca de Bares penetrates considerably into the Cantabrian Sea, and as a result it is one of the rainiest places in Europe, with more than 2500 mm a year [1]. These special weather conditions have created over the centuries a unique ecosystem and biodiversity which have made it possible for this area to be declared an Area of National Natural Interest [1]. The ruins of the Phoenician Salt Fish Factory and the Phoenician Port are open to visitors [1].''"}, {"source": "remediation_change_log:101806", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:101807", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:153718", "url": "remediation_change_log", "quote": "served-image-2026-09-30-017: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/b/bd/Estaca-de-bares.jpg'' -> ''/data/images/wiki/79132373/Acantilados de Estaca de Bares.webp''"}, {"source": "remediation_change_log:250135", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:250136", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''-3000''"}, {"source": "remediation_change_log:313018", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-008: thumbnail_url ''/data/images/wiki/79132373/Acantilados de Estaca de Bares.webp'' -> ''/data/images/wiki/79132373/Estaca-de-bares.webp''"}, {"source": "remediation_change_log:345701", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_name ''3000 - 1500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:345702", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_start ''-3000'' -> None"}]'::jsonb),
