    ('79484b17-4db6-454c-aacb-a3cb5eafaec9'::uuid, 'empire_count', '1', '0', 'card-stats-2026-11-05-rollback:79484b17-4db6-454c-aacb-a3cb5eafaec9:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Scutchamer Knob', 'b9e382408bac200d92f828c842a0f16c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 1 from tag_site(51.562533365808505, -1.3427892739398462, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81038", "url": "remediation_change_log", "quote": "phase4:p4-2017:chunk-0001: description \"Scutchamer Knob, originally called Cwichelm''s Barrow (Cwichelmeshlaew), is an Iron Age round barrow on the Ridgeway in Oxfordshire, England, rumoured to be the burial place of the Saxon king Cwichelm. It served as a shire moot meeting place during the Middle Ages, and in 1006 a Danish army reportedly marched there during their raid on Wessex. The mound originally measured 43 metres in diameter and 7 metres high but was heavily damaged by excavations in 1842-44, which found only an oaken moot-stake bound with willow twigs and no burial.\" -> \"Scutchamer Knob, also known as Cuckhamsley Hill and occasionally as Scotsman''s Knob or Beacon Hill, is an early Iron Age round barrow on the Ridgeway National Trail at East Hendred Down in the English county of Oxfordshire (formerly in Berkshire) [1]. Originally called Cwichelmeshlaew or Cwichelm''s Barrow, it is recorded as having been the place where King Edwin of Northumbria killed Cwichelm of Wessex in AD 636 and, in the Middle Ages, became the meeting point of the shire moot which was abolished in 1620 [1]. It was long thought to be the actual burial place of Cwichelm but the mound has been excavated several times without serious finds [1]. In 1006, the Anglo-Saxon Chronicle states that the Danes marched to Cuckhamsley Hill as they believed that if they reached the Hill, they would never return to the sea [1].\""}, {"source": "remediation_change_log:101808", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:101809", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s011: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:153720", "url": "remediation_change_log", "quote": "served-image-2026-09-30-017: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/9c/Scutchamer.png'' -> ''/data/images/wiki/79484b17/hero.webp''"}, {"source": "remediation_change_log:302142", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:302143", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-800''"}, {"source": "remediation_change_log:349993", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:349994", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-800'' -> None"}]'::jsonb),
