    ('7bfb0158-bf33-40c2-aff0-3af9efcd5193'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:7bfb0158-bf33-40c2-aff0-3af9efcd5193:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Caves and Ice Age Art in the Swabian Jura', 'aeba8bbe65c92b2ed0136796861a5c4e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -41050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:35009", "url": "remediation_change_log", "quote": "phase4:p4-0039:chunk-0001: description ''The Caves and Ice Age Art in the Swabian Jura are a collection of six caves in southern Germany used by Ice Age humans for shelter approximately 33,000 to 43,000 years ago [1]. These caves contain the oldest known non-stationary works of human art, including carved animal and humanoid figurines, the oldest musical instruments ever discovered, and a female statuette [1]. Inscribed on the UNESCO World Heritage List in 2017, these caves provide crucial testimony to the development of Paleolithic art and culture in Europe [1].'' -> ''The Caves and Ice Age Art in the Swabian Jura are a collection of six caves in southern Germany which were used by Ice Age humans for shelter about 33,000 to 43,000 years ago [1]. Within the caves were found the oldest non-stationary works of human art yet discovered, in the form of carved animal and humanoid figurines, in addition to the oldest musical instruments ever found [1]. Some of the figurines depict creatures that are half animal, half human [1]. Bone flutes from the Geissenklösterle cave, dated around c.\\u200943,150–39,370 BP, are the oldest musical instruments ever found [1]. The 41,000 to 39,000-year-old Lion-man and the 42,000 to 41,000-year-old Venus of Hohle Fels are the oldest confirmed sculptures in the world [1].''"}, {"source": "remediation_change_log:84245", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:84246", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_start ''-500'' -> None"}, {"source": "remediation_change_log:153818", "url": "remediation_change_log", "quote": "served-image-2026-09-30-017: thumbnail_url ''/data/images/wiki/7bfb0158/hero.webp'' -> ''/data/images/wiki/7bfb0158/Die Bocksteinhöhle im Lonetal. 02.webp''"}, {"source": "remediation_change_log:250155", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:250156", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''-500''"}, {"source": "remediation_change_log:313064", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-008: thumbnail_url ''/data/images/wiki/7bfb0158/Die Bocksteinhöhle im Lonetal. 02.webp'' -> ''/data/images/wiki/7bfb0158/Hohler_Fels_Eingang_Gang_Steg.webp''"}, {"source": "remediation_change_log:350003", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:350004", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-500'' -> ''-41050''"}]'::jsonb),
