    ('7c97de3a-0401-4cd9-892a-79450990b3ce'::uuid, 'mystery', '4', '5', 'card-stats-2026-11-05-rollback:7c97de3a-0401-4cd9-892a-79450990b3ce:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Little St Bernard Pass', 'dcbec0aadd230d0ba8a9d3ea40dd72dc', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Stone circle'', ''3000 - 1500 BC'') is shared by 57 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:35015", "url": "remediation_change_log", "quote": "phase4:p4-0039:chunk-0001: description \"The Little St Bernard Pass hosts a prehistoric stone circle (cromlech) at 2,188 metres elevation on the France-Italy border, south of Mont Blanc. The circle measures approximately 72 metres in diameter with 46 of the original stones still standing, though only eight are authentic. Classified as Neolithic to Bronze Age, the cromlech was built by pre-Celtic Alpine peoples including the Salasses and Ceutrones, and likely served as an astronomical observatory aligned with the summer solstice. The pass itself is historically significant as a major Alpine crossing, traditionally identified as the route taken by Hannibal''s army.\" -> ''The Little St Bernard Pass is a mountain pass in the Alps on the France–Italy border [1]. Its saddle is at 2188 metres above sea level [1]. The road across this pass is usually open from May to October [1]. At the summit, the road cuts through a stone circle measuring 72 m (236 ft) in diameter [1]. A standing stone once stood in the middle [1]. From coin finds this is believed to date from the Iron Age, possibly being a ceremonial site of the Tarentaisian culture (c. 725 BC–450 BC) [1]. The stone circle was partly restored in the 19th century [1]. In the Roman era, a temple dedicated to Jupiter was erected nearby along with a mansio serving travellers along the pass, and it is thought that Carthaginian general Hannibal used this route [1].''"}, {"source": "remediation_change_log:120169", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:120170", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:120171", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: source_url ''https://en.wikipedia.org/wiki/Little_St_Bernard_Pass'' -> ''https://fr.wikipedia.org/wiki/Cromlech_du_Petit-Saint-Bernard''"}, {"source": "remediation_change_log:141485", "url": "remediation_change_log", "quote": "2026-10-01a_fields-wd3-s001: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:141486", "url": "remediation_change_log", "quote": "2026-10-01a_fields-wd3-s001: period_start None -> ''-3000''"}, {"source": "remediation_change_log:153843", "url": "remediation_change_log", "quote": "served-image-2026-09-30-017: thumbnail_url ''/data/images/wiki/7c97de3a/hero.webp'' -> ''/data/images/wiki/7c97de3a/Col_du_Petit-Saint-Bernard_-_cromlech.webp''"}]'::jsonb),
