    ('7ccaad38-8cfb-401e-a938-e2c792914b75'::uuid, 'total_power', '24', '29', 'card-stats-2026-11-05-rollback:7ccaad38-8cfb-401e-a938-e2c792914b75:total_power', 'rollback of card-stats-2026-11-05: total_power ''29'' restored on Jabal al-ʿHayn', 'c472f34e472226827b2c20c10fa6972f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 24 from antiquity + fortification + cultural_influence + mystery + legacy = 5 + 2 + 10 + 6 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:35017", "url": "remediation_change_log", "quote": "phase4:p4-0039:chunk-0001: description \"A prominent outcrop of red sandstone in Medina Province, Saudi Arabia, about 17.5 km northeast of al-Hanakiya, known for its prehistoric petroglyphs, tribal markings (wusum), and inscriptions in early Semitic languages and Arabic. The ancient rock carvings depict horned bison, standing human figures, and a distinctive wild cat with a curling tail, while later petroglyphs show camels in various scenes. The site reflects the broader tradition of Arabian rock art spanning millennia, documenting the region''s shifting environment from a wetter prehistoric climate to arid conditions.\" -> ''Jabal al-ʿHayn is a prominent outcrop of red sandstone in Saudi Arabia, known for its pre-historic petroglyphs, tribal markings (wusūm) and inscriptions in early Semitic languages as well as Arabic [1]. Ancient petroglyphs carved on the rock faces of Jabal al-ʿHayn depict horned bison, standing figures and an exceptional wild cat with a curling tail [1]. Camels are shown in some petroglyphs that seem to be less ancient [1]. Among the many inscriptions at Jabal al-ʿHayn are a number in Arabic which date to the earliest years of the Islamic calendar [1]. One inscription quotes Quran, Surah 18 Al-Kahf verse 21 [1]. The inscription was studied by Fred Donner and published in 1984 [1]. In a second record of singular historical importance, an individual named Rāfiʿ bin \\''Alī declares \"I believe that there is no God except Him in whom the children of Israel believed, (believing as) a Muslim Hanif; nor am I among the polytheists.\" This gives a direct quote of Quran, Surah 10 Yunus verse 90 [1]. Also published by Donner is an inscription on a boulder invoking the name of God and giving an exceptional religious maxim [1].''"}, {"source": "remediation_change_log:120177", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:120178", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_start ''-7000'' -> None"}, {"source": "remediation_change_log:153872", "url": "remediation_change_log", "quote": "served-image-2026-09-30-017: thumbnail_url ''/data/images/wiki/7ccaad38/hero.webp'' -> ''/data/images/wiki/7ccaad38/Religious_maxim_in_Arabic.webp''"}, {"source": "remediation_change_log:250165", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:250166", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''-10000''"}, {"source": "remediation_change_log:313077", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-008: thumbnail_url ''/data/images/wiki/7ccaad38/Religious_maxim_in_Arabic.webp'' -> ''/data/images/wiki/7ccaad38/Hanakiya,_tribal_markings_and_camels.webp''"}, {"source": "remediation_change_log:350007", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''< 4500 BC'' -> ''Undated''"}, {"source": "remedia