    ('7d24037c-4afc-49e7-a13e-713769bf8208'::uuid, 'antiquity', '5', '2', 'card-stats-2026-11-05-rollback:7d24037c-4afc-49e7-a13e-713769bf8208:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''2'' restored on Zapote Bobal', '0cbd4a3bf865d66c1262b534609020b8', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:35027", "url": "remediation_change_log", "quote": "phase4:p4-0039:chunk-0001: description \"Zapote Bobal is a pre-Columbian Maya site in the Peten department of Guatemala, discovered by Ian Graham in the 1970s. Built atop a levelled hill 1 km long and 700 m wide, the site contains a royal palace, temple-pyramids, and over 400 structures within a 2.5 km radius. It served as the capital of the Hix Witz kingdom during the Late Classic period (AD 600-800), ruled by kings bearing variations of the name Chan Ahk (''Sky Turtle''). Epigrapher David Stuart connected the site in 2003 to a polity frequently mentioned in inscriptions at Piedras Negras and Yaxchilan, revealing its role as a contested crossroads kingdom.\" -> ''Zapote Bobal is the modern name for a pre-Columbian Maya archaeological site located south of the San Pedro Martir river in the Petén department of Guatemala [1]. The name Zapote Bobal was coined by archaeologist Ian Graham, who discovered the site in the 1970s [1]. Built atop a leveled natural hill 1 kilometer long and 700 meters wide, the center of the site is characterized by a royal palace, several temple-pyramids, and elite residences [1]. Immediately outside this center are several mound groups, including one characterized by a pyramid 35 meters in height [1]. Although the general scale of construction at Zapote Bobal is quite large and would normally be characteristic of a long-lived ancient Maya center, it is clear that the city center was occupied for a brief period of time [1]. The royal dynasty at Zapote Bobal seems to have flourished for only 200 years, disintegrating by A.D. 800 [1]. For the majority of the Late Classic (AD 600-900), Zapote Bobal was the center of a kingdom that included the sites of Pajaral and (probably) La Joyanca [1].''"}, {"source": "remediation_change_log:102514", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:102515", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''500'' -> None"}, {"source": "remediation_change_log:102516", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:153883", "url": "remediation_change_log", "quote": "served-image-2026-09-30-017: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/7/7c/Estela_12.jpg'' -> ''/data/images/wiki/7d24037c/hero.webp''"}, {"source": "remediation_change_log:239589", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: site_type None -> ''City''"}, {"source": "remediation_change_log:250173", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:250174", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''500''"}, {"source": "remediation_change_log:350014", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''500 - 1000 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350015", "url": "remediation_change_log", "qu