    ('7d8df981-b89f-4d88-809d-205d2d11c160'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:7d8df981-b89f-4d88-809d-205d2d11c160:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Taghlar Cave', 'c0f568aff8de3f9f882790834c6d02d3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:35055", "url": "remediation_change_log", "quote": "phase4:p4-0040:chunk-0001: description \"The Taghlar Cave is an archaeological site in Azerbaijan''s disputed Nagorno-Karabakh region, located in the southern part of Boyuk Taghlar village on the left bank of the Guruchay River [1]. The cave was inhabited by prehistoric humans of the Mousterian culture during the Paleolithic period [2]. The site provides important evidence of prehistoric human activity in the South Caucasus region.\" -> ''The Taghlar cave is an archaeological site that was inhabited by prehistoric humans of the Mousterian culture during the Paleolithic [1]. The cave is located in Azerbaijan, in the disputed region of Nagorno-Karabakh, in the southern part of Boyuk Taghlar village, on the left banks of the Guruchay River [1]. Ancient people lived here 64-24 thousand years ago [1]. The cave was discovered during the Paleolithic archaeological expedition of Academy of Science of Azerbaijan under the leadership of M.Huseynov in 1960 [1]. Beginning in 1963, archaeological excavations were carried out in the cave and more than 7,000 stone tools and over 2,000 faunal fossilized bones were discovered and six cultural sediment layers were identified at the site [1]. Indices of the Mousterian culture were found in between the 2nd and 6th layer [1]. The remains of large mammals such as horse, noble deer, bull were found in the 5th layer [1].''"}, {"source": "remediation_change_log:102525", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:102526", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-500'' -> None"}, {"source": "remediation_change_log:153891", "url": "remediation_change_log", "quote": "served-image-2026-09-30-017: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Çaxmaqdaşı_və_dəvəgözündən_əmək_alətləri.JPG/400px-Çaxmaqdaşı_və_dəvəgözündən_əmək_alətləri.JPG'' -> ''/data/images/wiki/7d8df981/hero.webp''"}, {"source": "remediation_change_log:250177", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:250178", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''-3000000''"}]'::jsonb),
