    ('7ee712a7-ac2d-448e-953e-1292d104facc'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:7ee712a7-ac2d-448e-953e-1292d104facc:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Cova d''en Daina', '6904f6c0691c4271c8fe47ce6b6a08fd', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Dolmen'', ''3000 - 1500 BC'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28795", "url": "remediation_change_log", "quote": "phase3:batch-0195:chunk-0001: site_type ''Necropolis/tombs complex'' -> ''Dolmen''"}, {"source": "remediation_change_log:35057", "url": "remediation_change_log", "quote": "phase4:p4-0040:chunk-0001: description ''Cova d\\''en Daina is a Late Neolithic dolmen near Romanya de la Selva in Santa Cristina d\\''Aro, Catalonia, dated to 2700-2200 BC. Classified as a \"Catalan gallery\" or wide corridor grave, it features a covered gallery 7 m long built from granite slabs, with a circular tumulus and cromlech originally 11 m in diameter. Discovered by Pere Cama i Casas in 1894, later excavations by Lluis Esteva i Cruanas yielded fragmented human bones and teeth from adults and children, flint tools, pottery fragments, and ornaments including necklace beads and small pieces of slate and gold. It is considered one of the most complete and best-preserved megaliths in Catalonia.'' -> \"Cova d''en Daina is a dolmen located near Romanyà de la Selva, in the municipality of Santa Cristina d''Aro, Catalonia, Spain [1]. The dolmen was built out of granite blocks and is dated around 2700–2200 BC [1]. It was discovered by Pere Cama i Casas and the first mention of its uncovering was by Agustí Casas in 1894 [1]. It was later excavated by Lluís Esteva i Cruañas, who unearthed human bones and teeth, flint arrowheads, knife and pottery fragments, and necklace beads [1]. It was partially reconstructed in the 1950s [1]. It is seven metres long and made up of an entrance passage into the funeral chamber, with a circular tumulus that is 11 metres in diameter [1]. The entrance to the tomb is oriented to the southeast, which allows sunlight to reach the interior on the winter solstice [1].\""}, {"source": "remediation_change_log:153945", "url": "remediation_change_log", "quote": "served-image-2026-09-30-017: thumbnail_url ''/data/images/wiki/7ee712a7/hero.webp'' -> \"/data/images/wiki/7ee712a7/Romanyà Cova d''en Daina DSC01827.webp\""}, {"source": "remediation_change_log:334559", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url \"/data/images/wiki/7ee712a7/Romanyà Cova d''en Daina DSC01827.webp\" -> \"/data/images/wiki/7ee712a7/Cova_d''en_Daina_-_002.webp\""}]'::jsonb),
