    ('7ee94c43-3a26-44db-8dee-bd7829b5a171'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:7ee94c43-3a26-44db-8dee-bd7829b5a171:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Castro of Castelo Velho', 'bff69775864853a609e2e477b592dfed', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28886", "url": "remediation_change_log", "quote": "phase3:batch-0210:chunk-0001: site_type ''Fortress/citadel'' -> ''Settlement''"}, {"source": "remediation_change_log:85596", "url": "remediation_change_log", "quote": "phase4:p4-2118:chunk-0001: description ''The Castro of Castelo Velho is a Chalcolithic fortified settlement in the civil parish of Terena, municipality of Alandroal, Alentejo Central, Portugal [1]. The site features an irregular, fortified village plan that was used and modified across different historical periods, particularly during the Chalcolithic period and the Bronze Age [2].'' -> ''The Castro of Castelo Velho (Portuguese: Castro de Castelo Velho) is a Chalcolithic settlement in the civil parish of Terena (São Pedro), municipality of Alandroal in the Alentejo Central area of the Portuguese Alentejo [1]. The first settlements date to the Chalcolithic [1]. By the late Bronze Age the location had become a centre of intense metallurgical activities [1]. During the 20th century (1990s), Manuel Calado held the first archeological excavations in the area to study the settlement [1]. The fortified settlement has an irregular plan, utilized and modified in different periods [1]. Around its perimeter is a slope with visible vestiges of low walls [1]. These defensive structures have distinct plans corresponding to different phases at the site [1].''"}, {"source": "remediation_change_log:102544", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:102545", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:250183", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:250184", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''-500''"}, {"source": "remediation_change_log:340799", "url": "remediation_change_log", "quote": "insert-2026-10-07-005-001: thumbnail_url None -> ''/data/images/wiki/7ee94c43/Castelo Velho de Freixo de Numão - Portugal (50801841192).webp''"}, {"source": "remediation_change_log:350018", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350019", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-500'' -> None"}, {"source": "remediation_change_log:355903", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
