    ('7f9f3957-7fc4-4775-8c45-93c279feb753'::uuid, 'rarity_score', '37', '34', 'card-stats-2026-11-05-rollback:7f9f3957-7fc4-4775-8c45-93c279feb753:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''34'' restored on Windmill Tump', '95e53170ef19c9914e3b8d8d1dddb262', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 37 from mystery 5, cultural_influence 10"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:35061", "url": "remediation_change_log", "quote": "phase4:p4-0040:chunk-0001: description ''Windmill Tump, also known as Rodmarton Chambered Tomb, is a Neolithic burial site, a stone tumulus or barrow. Located in Gloucestershire, it lies west of Rodmarton village, south of the road between Cherington and Tarlton. Trees now grow on the site [1].'' -> ''Windmill Tump, also known as Rodmarton Chambered Tomb, is a Neolithic burial site, a stone tumulus or barrow [1]. It is a mound covering the site of graves, in the form of a cairn, located in Gloucestershire [1]. It lies to the west of the village of Rodmarton, south of the road between Cherington and Tarlton [1]. The construction consists of approximately 5,000 tons of stone, under a mound [1]. The only portion of the stones that can still be seen is a fake entrance, which lies at the eastern side of the mound [1]. Digging took place in 1863, and again in 1939, after which the mound was restored [1]. The site contains two tombs, behind the false entrance, with passageways to the north and south [1]. The tombs contained the remains of ten adults and three children [1].''"}, {"source": "remediation_change_log:102560", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:102561", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:153961", "url": "remediation_change_log", "quote": "served-image-2026-09-30-017: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/8/82/Entrance_Portal_Rodmarton_Long_Barrow_-_geograph.org.uk_-_1002575.jpg'' -> ''/data/images/wiki/7f9f3957/Chamber in the Forecourt of Windmill Tump.webp''"}, {"source": "remediation_change_log:239614", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:239615", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_start None -> ''-4000''"}, {"source": "remediation_change_log:313137", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-008: thumbnail_url ''/data/images/wiki/7f9f3957/Chamber in the Forecourt of Windmill Tump.webp'' -> ''/data/images/wiki/7f9f3957/Entrance Portal Rodmarton Long Barrow - geograph.org.uk - 1002575.webp''"}]'::jsonb),
