rs old [1].''"}, {"source": "remediation_change_log:102598", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:102599", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-115000'' -> None"}, {"source": "remediation_change_log:302152", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:302153", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-300000''"}, {"source": "remediation_change_log:325283", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/81666db8/hero.webp'' -> ''/data/images/wiki/81666db8/Cueva de los Aviones.webp''"}]'::jsonb),
