    ('820ff35d-d611-4865-b4e3-27e09843aa9a'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:820ff35d-d611-4865-b4e3-27e09843aa9a:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Banoštor', 'b74e3e1e1d9ea81eb15542f4795a43a1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:35087", "url": "remediation_change_log", "quote": "phase4:p4-0041:chunk-0001: description ''A village in Vojvodina, Serbia, on the Danube at the edge of the Fruska Gora mountains, site of the ancient Roman military stronghold Bononia. Originally a Celtic settlement called Malata founded after the Gallic invasion of 279 BC, it was conquered by Rome in the 1st century BC and garrisoned by the Cohors Alpinorum and later Legio VI Herculia. The name Banostor (\"monastery of the ban\") derives from a 12th-century monastery founded by Ban Belos, palatine of Hungary, who ruled Srem from 1142 to 1163.'' -> ''Following the Gallic invasion of the Balkans in 279 BC, Celtic tribes settled throughout Serbia, their settlement at Banoštor was called Malata [1]. It was later conquered by the Romans in 1st century BC and was renamed to Bononia [1]. Romans transformed the settlement into a military stronghold with a Roman military unit based here known as Cohors Alpinorum [1]. The Roman legion named Herculia VI was also stationed in the town [1]. Two religious altars were also situated near Bononia, one of them was dedicated to Jupiter and another one to Neptune [1]. Banoštor is located on the edge of the Fruška Gora Mountain Range and on the Danube River [1].''"}, {"source": "remediation_change_log:102616", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:102617", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-500'' -> None"}, {"source": "remediation_change_log:154550", "url": "remediation_change_log", "quote": "served-image-2026-09-30-018: thumbnail_url ''/data/images/wiki/820ff35d/hero.webp'' -> ''/data/images/wiki/820ff35d/Banoštor,_crkva_Sv._Georgija_016.webp''"}, {"source": "remediation_change_log:239642", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:239643", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_start None -> ''-279''"}, {"source": "remediation_change_log:350033", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350034", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-279'' -> None"}]'::jsonb),
