    ('82ab3246-cd82-4453-bd84-4668d3640ad1'::uuid, 'antiquity', '4', '5', 'card-stats-2026-11-05-rollback:82ab3246-cd82-4453-bd84-4668d3640ad1:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Dağlı Kalesi', '929c80f3bdba6c34ab6ad8e13f76fbe9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 4 from period_start -27"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85686", "url": "remediation_change_log", "quote": "phase4:p4-2121:chunk-0001: description \"Dagli Castle is a ruined fortress in Mersin Province, Turkey, perched on a hill overlooking the Karakiz valley at over 900 metres elevation. Built during the Roman Empire in the 2nd century AD, it was subsequently used during the Byzantine Empire and the Armenian Kingdom of Cilicia, likely controlling ancient and medieval caravan routes. Surviving features include a large chamber known as the Queen''s Room, two small compartments believed to be toilets and dungeons, and rock reliefs of two soldiers and a pregnant woman near the main gate. An Armenian inscription dating to King Hetum I''s reign (1226-1269) was found but later stolen in 2013.\" -> ''Dağlı Castle is a castle ruin in Mersin Province, Turkey [1]. The castle was built during the Roman Empire and later used by the Byzantine Empire and the Armenian Kingdom of Cilicia [1]. It probably controlled ancient and medieval caravan routes [1]. The castle is on a hill overlooking the Karakız valley [1]. Most of the buildings as well as the walls are in ruins, but a large room known as the queen’s room survives [1]. Next to the main gate there is a rock relief showing two soldiers and one pregnant woman [1]. There is also a highly effaced inscription [1]. Although it was thought to be in Armenian, up to now only a few words could be deciphered [1].''"}, {"source": "remediation_change_log:102625", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:102626", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''100'' -> None"}, {"source": "remediation_change_log:250217", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:250218", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''-800''"}, {"source": "remediation_change_log:325286", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/82ab3246/hero.webp'' -> ''/data/images/wiki/82ab3246/Dağlı Castle, Mersin Province.webp''"}, {"source": "remediation_change_log:357229", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s005: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:357230", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s005: period_start ''-800'' -> ''-27''"}]'::jsonb),
