    ('83711b0a-71a6-4022-88f9-060aada84ea6'::uuid, 'antiquity', '8', '5', 'card-stats-2026-11-05-rollback:83711b0a-71a6-4022-88f9-060aada84ea6:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Ballinran Court Tomb', '86a8be13a62c6eeea82e039f8517724c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -4000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28318", "url": "remediation_change_log", "quote": "phase3:batch-0110:chunk-0001: site_type ''Necropolis/tombs complex'' -> ''Tomb''"}, {"source": "remediation_change_log:85698", "url": "remediation_change_log", "quote": "phase4:p4-2121:chunk-0001: description \"Neolithic court tomb near Killowen, County Down, Northern Ireland, on the shore of Carlingford Lough, also known as the Giant''s Grave. Excavated in April-May 1976 ahead of a road-widening project, the dig revealed a burial gallery over 12 m long divided into five or six segments, with the forecourt facing the Mourne Mountains. No intact burial deposits survived, though cremated human bone, three primary flint flakes, and a nest of winkle shells placed in a pit were recovered. First recorded in the 1858 Ordnance Survey Revision Name Book.\" -> \"Ballinran Court Tomb is situated close to Killowen, County Down, Northern Ireland, on the shore of Carlingford Lough [1]. The site was excavated in April and May 1976 in preparation for a road widening project [1]. The excavation revealed the remains of a large court tomb, despite the absence of visible surface features [1]. By the late 19th century, the monument had largely been destroyed, though its location remained accurately marked on subsequent maps [1]. The excavation uncovered a burial gallery consisting of five or six segments, aligned approximately north–south, with the forecourt facing the Mourne Mountains [1]. The gallery featured stone sockets for orthostats, some of which contained packing stones or fragments of the original stones [1]. No trace of burial deposits was found in situ, although some cremated, presumably human, bone and three primary flint flakes were found [1]. A ''nest'' of winkle shells were found placed in a pit as a secondary deposit in the grave [1].\""}, {"source": "remediation_change_log:102647", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:102648", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:250585", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:250586", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-800''"}, {"source": "remediation_change_log:350037", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''1500 - 500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:350038", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-800'' -> ''-4000''"}]'::jsonb),
