    ('83cbd9c5-1962-4f95-8f49-eeb525af234f'::uuid, 'empire_count', '1', '0', 'card-stats-2026-11-05-rollback:83cbd9c5-1962-4f95-8f49-eeb525af234f:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Camboglanna', '8613702cb3e86e513bb2a304071186ee', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 1 from tag_site(54.96508620115894, -2.76089271420787, period_start 101)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85702", "url": "remediation_change_log", "quote": "phase4:p4-2121:chunk-0001: description ''Camboglanna (modern Castlesteads) was a Roman fort on Hadrian\\''s Wall. It was the twelfth fort from the east, situated between Banna (Birdoswald) 11 km to the east and Uxelodunum (Stanwix) to the west[1]. The fort occupied a high bluff commanding the Cambeck Valley, guarding a key approach to the Wall and monitoring the east bank against raiders from the Bewcastle area[1]. The site was drastically levelled in 1791 when the gardens of Castlesteads House were constructed over it[1]. The name Camboglanna derives from Brythonic elements: cambo- meaning \"curved, bent\" and glanna meaning \"steep bank\" or \"river side,\" interpreted as \"Crook Bank\" or \"Bent Valley\" referencing its position overlooking a bend in the river Irthing[1].'' -> \"Camboglanna was a Roman fort [1]. It was the twelfth fort on Hadrian''s Wall counting from the east, between Banna almost 7 miles to the east and Uxelodunum, 9 miles to the west [1]. It was on a high bluff commanding the Cambeck Valley [1]. It guarded an important approach to the Wall and also watched the east bank of the Cambeck against raiders from the Bewcastle area [1]. The site was drastically levelled in 1791 when the gardens of Castlesteads House were laid over it [1]. The fort was approximately square, measuring about 400 by 400 feet and covering approximately 3.75 acres [1]. The 2nd-century garrison was the Cohors IV Gallorum equitata [1]. Several altars have been found at the site and have been preserved [1].\""}, {"source": "remediation_change_log:102657", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:102658", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''1'' -> None"}, {"source": "remediation_change_log:154592", "url": "remediation_change_log", "quote": "served-image-2026-09-30-018: thumbnail_url ''/data/images/wiki/83cbd9c5/hero.webp'' -> ''/data/images/wiki/83cbd9c5/Roman Antiquities at Castlesteads in Cumberland Figure 01.webp''"}, {"source": "remediation_change_log:250591", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:250592", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''43''"}, {"source": "remediation_change_log:350043", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350044", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''43'' -> None"}, {"source": "remediation_change_log:354785", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_name ''Undated'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:354786", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_start None -> ''101''"}]'::jsonb),
