    ('8414ca9b-404d-49df-9aa9-6fe545ccac80'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:8414ca9b-404d-49df-9aa9-6fe545ccac80:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Preston Candover Long Barrow', 'b199e95daedd15ae8d25f06d0685baa5', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85704", "url": "remediation_change_log", "quote": "phase4:p4-2121:chunk-0001: description ''Preston Candover Long Barrow is an unchambered Neolithic long barrow near the village of Preston Candover in Hampshire, England. It is one of only two known long barrows on the North Downs, alongside the Badshot Lea Long Barrow in Surrey. The site retains high archaeological potential, including probable early medieval burials associated with the mound. An iron spearhead and a seax dating from the 7th or 8th century were recovered from the barrow, initially misidentified as Iron Age before Christopher Hawkes established their early medieval date.'' -> ''Preston Candover Long Barrow is an unchambered long barrow located near to the village of Preston Candover in the south-eastern English county of Hampshire [1]. The archaeologist Ian Kinnes classed the Preston Candover example alongside the Badshot Lea Long Barrow in Surrey as the two known examples located on the North Downs [1]. In the late nineteenth century, an iron spearhead was recovered from inside the barrow [1]. A scramasax was also reported as having been found from the edge of the barrow [1]. In the late nineteenth century, the Reverend Sumner Wilson and T. W. Shore expressed the opinion that the Preston Candover barrow was stylistically a long barrow [1]. O. G. S. Crawford disagreed with this assessment and on the Ordnance Survey map it was instead classified as a round barrow [1].''"}, {"source": "remediation_change_log:102661", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:102662", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-5000'' -> None"}, {"source": "remediation_change_log:154593", "url": "remediation_change_log", "quote": "served-image-2026-09-30-018: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/Maps_indicate_a_barrow_-_geograph.org.uk_-_3617140.jpg/400px-Maps_indicate_a_barrow_-_geograph.org.uk_-_3617140.jpg'' -> None"}, {"source": "remediation_change_log:250593", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:250594", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-4000''"}, {"source": "remediation_change_log:350045", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:350046", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-4000'' -> None"}]'::jsonb),
