    ('8423294a-2f28-4eec-87b0-9d55552cf023'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:8423294a-2f28-4eec-87b0-9d55552cf023:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Hybla Gereatis', 'fef7fb1f83f691bbef6535cd816b530f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85728", "url": "remediation_change_log", "quote": "phase4:p4-2122:chunk-0001: description \"An ancient city of Magna Graecia on the southern slope of Mount Etna in Sicily, identified with modern Paterno through the discovery of an altar dedicated to Venus ''Victrici Hyblensi''. The volcanic hill contains remains spanning from the Bronze Age through Greek, Hellenistic-Roman, Byzantine, and early medieval periods. Described as the largest and most considerable of the several Sicilian cities named Hybla, it was a prosperous community in Cicero''s time with fertile corn-producing territory. Artifacts including ceramics, terracottas, and Greco-Roman silverware dated to the 5th-3rd centuries BC are housed in the Siracusa Museum.\" -> ''Hybla Gereatis has been described as the largest and most considerable of the Sicilian cities called Hybla, thence equated with Hybla Major or Magna [1]. During the Second Punic War, Livy mentions Hybla as one of the towns that were induced to revolt to the Carthaginians in 211 BCE, but were quickly recovered by the Roman praetor M. Cornelius [1]. In the time of Cicero the Hyblenses (evidently the people of the Aetnaean city) appear as a considerable municipal community [1]. Its name is also found both in Pliny, who reckons it among the populi stipendiarii of the island, and in Ptolemy [1]. We find no later notice of it, though an inscription of Christian times found at Catana appears to refer to Hybla as still existing under its ancient name [1].''"}, {"source": "remediation_change_log:102668", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:102669", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-500'' -> None"}, {"source": "remediation_change_log:250599", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:250600", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-500''"}, {"source": "remediation_change_log:350051", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350052", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-500'' -> None"}]'::jsonb),
