    ('8426a941-5472-44b1-b7aa-0872fa5ae26d'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:8426a941-5472-44b1-b7aa-0872fa5ae26d:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Stripple Stones', 'bf413f1803dac14e045760c103f46130', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2900"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85732", "url": "remediation_change_log", "quote": "phase4:p4-2122:chunk-0001: description \"The Stripple Stones is a late Neolithic henge and stone circle on the south slope of Hawk''s Tor, Bodmin Moor, Cornwall, England. Unique in Cornwall as the only stone circle built within a henge, it features a 44.8-metre diameter circle inside a 68.3-metre henge enclosure. Originally comprising about 28 stones, eleven remain, along with a fallen central menhir 3.7 metres long. The central pillar may have served as a backsight for observing the major northern moonrise, equinox sunrise, and May Day sunset.\" -> ''The Stripple stones is a henge and stone circle located on the south slope of Hawk\\''s Tor, Blisland, 10 kilometres north northeast of Bodmin on Bodmin Moor in Cornwall, England [1]. First recorded by this name during the reign of Queen Elizabeth I the circle has been described by William Lukis as \"the most interesting and remarkable monument in the county\" [1]. It is surrounded by a circular ditch and vallum that forms a level platform 175 feet in diameter [1]. The circle is 145.5 feet in diameter with four granite standing stones and several fallen [1]. The Stripple stones were excavated in 1905 by H. St. George Gray who found a burnt flint, three flint flakes, an ox bone and some charcoal and oak timbers in the surrounding ditch [1]. He also detected an entrance from this facing southwest, directly towards the Trippet stones [1]. Gray noted that the stones had only been set approximately 1.5 feet deep into the ground [1]. The vallum surrounding the circle has three semi-lunar projections facing towards the northwest, northeast and east [1].''"}, {"source": "remediation_change_log:102670", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:102671", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:154598", "url": "remediation_change_log", "quote": "served-image-2026-09-30-018: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/ac/Stripple_Stones_henge_and_stone_circle_%28geograph_6416860%29.jpg'' -> ''/data/images/wiki/8426a941/hero.webp''"}, {"source": "remediation_change_log:250601", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:250602", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-4000''"}, {"source": "remediation_change_log:350053", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:350054", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-4000'' -> ''-2900''"}]'::jsonb),
