layers were discovered in the cave [1].''"}, {"source": "remediation_change_log:120227", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:120228", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_start ''-500'' -> None"}, {"source": "remediation_change_log:120229", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: site_type ''Cave Structures'' -> ''Cave''"}, {"source": "remediation_change_log:250603", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:250604", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-500''"}, {"source": "remediation_change_log:313191", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-008: thumbnail_url ''/data/images/wiki/84c1ff70/hero.webp'' -> ''/data/images/wiki/84c1ff70/Dəvəgözündən_əmək_alətləri,_Qazma_mağarası.webp''"}, {"source": "remediation_change_log:350055", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350056", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s005: period_start ''-500'' -> None"}, {"source": "remediation_change_log:355907", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Cave'' -> ''Cave Structures''"}]'::jsonb),
