    ('85ed945a-9d3c-437c-97b5-adf0cf0b3a9c'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:85ed945a-9d3c-437c-97b5-adf0cf0b3a9c:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Salzofen Cave', '271837f9264cb289586b58df16806ee0', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85782", "url": "remediation_change_log", "quote": "phase4:p4-2123:chunk-0001: description ''Salzofen Cave is an archaeological site in Styria, Austria, located in the municipality of Grundlsee at approximately 2,000 metres (6,600 ft) altitude, about 60 metres below the summit[1]. The cave contains evidence of both Middle Paleolithic and Neolithic occupation, with finds including fireplaces, stone tools, and bone tools dating from 65,000 to 31,000 BCE[1]. In 1924, two hunters who had taken shelter in the cave from a storm discovered several fossilized bones in the entrance area[1].'' -> ''Salzofen Cave is an archaeological site in Styria, Austria [1]. In 1924 two hunters, who had taken shelter in the cave from a storm found several fossilized bones in the entrance area [1]. They handed them over to Otto Körber, a local school principal from Bad Aussee [1]. Körber visited the site on the next day and immediately began to dig, progressing almost 100 m until summer, unearthing large amounts of bone fossils [1].''"}, {"source": "remediation_change_log:102695", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''<