    ('8627799e-bfb9-4667-bbc6-d30ebdd99703'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:8627799e-bfb9-4667-bbc6-d30ebdd99703:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Dolmen de la Pastora', '62d6218c5813c2a9b911d172f1f370c8', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Dolmen'', ''3000 - 1500 BC'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85784", "url": "remediation_change_log", "quote": "phase4:p4-2123:chunk-0001: description ''The Dolmen de la Pastora is a Chalcolithic passage grave at Valencina de la Concepcion near Seville, Spain. Its 43-metre gallery -- the longest on the Iberian Peninsula -- is built with drystone walls and roofed with limestone and granite slabs. The passage terminates in a circular funeral chamber 2.5 m in diameter, topped by a single granite capstone. Uniquely among Iberian passage graves, it faces west toward the sunset. Discovered in 1860, excavations yielded 29 copper javelin-point arrowheads dated to between the 2nd and 3rd millennium BC.'' -> ''The Dolmen de la Pastora (also known as Cueva de la Pastora) is a prehistoric passage grave at Valencina de la Concepción near Seville, Spain [1]. It has been dated to the Chalcolithic Age [1]. The dolmen is under \"La Pastora\" mound at Valencina de la Concepción [1]. It is a 43-metre long gallery, made with drystone walls and roofed with slabs of limestone and granite [1]. The passage terminates in a circular funeral chamber with a diameter of 2.5 metres, roofed with a single granite capstone [1]. The passage is orientated towards the sunset, unlike other similar tombs in the region which tend to face towards sunrise [1]. Excavations in the slope of the tumulus in 1860 yielded 27 copper arrow heads of the \"javelin type\" [1].''"}, {"source": "remediation_change_log:102701", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:102702", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-4000'' -> ''-3000''"}, {"source": "remediation_change_log:154670", "url": "remediation_change_log", "quote": "served-image-2026-09-30-018: thumbnail_url ''/data/images/wiki/8627799e/hero.webp'' -> ''/data/images/wiki/8627799e/Dolmen de la Pastora.webp''"}, {"source": "remediation_change_log:313821", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/8627799e/Dolmen de la Pastora.webp'' -> ''/data/images/wiki/8627799e/Dolmen_de_la_Pastora_1.webp''"}]'::jsonb),
