    ('86b67ab6-879c-4b80-a6ab-7bae209b8dc4'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:86b67ab6-879c-4b80-a6ab-7bae209b8dc4:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Roca dels Moros', '0fe2b2c91431cf227dfcf45d82fe02b7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85788", "url": "remediation_change_log", "quote": "phase4:p4-2123:chunk-0001: description \"Rock shelter in El Cogul, Catalonia, featuring prehistoric Levantine rock art and Iberian schematic paintings. The site contains inscriptions in Northeastern Iberian script and Latin alphabet, indicating use as a sanctuary into Iberian and Roman times. Since 1998, the paintings have been protected as part of the UNESCO World Heritage Site ''Rock art of the Iberian Mediterranean Basin.''[1][2]\" -> \"The Roca dels Moros or Caves of El Cogul is a rock shelter containing paintings of prehistoric Levantine rock art and Iberian schematic art [1]. The site is in El Cogul, in the autonomous community of Catalonia, Spain [1]. Since 1998 the paintings have been protected as part of the Rock art of the Iberian Mediterranean Basin, a UNESCO World Heritage Site [1]. Inscriptions in Northeastern Iberian script and in Latin alphabet indicate that the place was used as a sanctuary into Iberian and Roman times [1]. The paintings were discovered in 1908 by the el Cogul village rector, Ramon Huguet, and a report was published in the same year [1]. At Roca dels Moros there are forty-five figures depicted, of which thirty-eight are painted bright red, black and dark red, seven are engraved in stone [1]. Conservation work has been carried out on the paintings under the auspices of the Museu d''Arqueologia de Catalunya [1]. Near the paintings is a cemetery with tombs carved into the rock called Saladar tombs [1].\""}, {"source": "remediation_change_log:154693", "url": "remediation_change_log", "quote": "served-image-2026-09-30-018: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/4/4d/064_Pintures_de_la_cova_dels_Moros%2C_exposici%C3%B3_al_Museu_de_Gav%C3%A0.JPG'' -> ''/data/images/wiki/86b67ab6/Coves del Cogul1.webp''"}, {"source": "remediation_change_log:313830", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/86b67ab6/Coves del Cogul1.webp'' -> ''/data/images/wiki/86b67ab6/064_Pintures_de_la_cova_dels_Moros,_exposició_al_Museu_de_Gavà.webp''"}]'::jsonb),
