    ('87abc0f0-0a56-420f-94ce-ada2998bbd0d'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:87abc0f0-0a56-420f-94ce-ada2998bbd0d:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Cave of Pego do Diabo', '6312af2d6702777fb09fe4170651be80', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44765", "url": "remediation_change_log", "quote": "phase4:p4-0099:chunk-0001: description ''The Cave of Pego do Diabo (Loca do Gato) is a small karst cave in Turonian limestone located 250m above sea level in Loures municipality, ~20km north of Lisbon, Portugal [1]. Archaeological excavations have revealed evidence of Neanderthal occupation with finds dating back to approximately 35,000 years ago [1]. The site has yielded stone tools, faunal remains, and evidence of carnivorous animals, providing insights into Paleolithic human presence on the Iberian Peninsula [1].'' -> ''The Cave of Pego do Diabo is a small karst cave in a Turonian limestone outcrop located about 250 metres above sea level in the municipality of Loures, about 20 km north of Lisbon in Portugal [1]. The cave consists of a narrow passage about 13 metres long and one metre wide, with a chamber at the end that is about two metres wide [1]. First officially explored in 1965–66 by the Portuguese Speleological Society, it was surveyed in 1976 by the Grupo para o Estudio do Paleolitico Portugues and at the end of the 1980s by Prof. João Zilhão [1]. The stratigraphic profile carried out by Zilhão identified six layers to a depth of about 1.4 metres [1]. Layer 1 contained a mixture of modern and Pleistocene items while Layer 2 contained artifacts of the Upper Paleolithic associated with animal remains [1]. Work by Maria João Valente analysed the fauna of Layers 1 and 2 associated with the Upper Paleolithic [1]. She noted that the cave contained bones of humans, together with those of wolves, bears, and hyenas, the Iberian lynx and other small carnivores and birds of prey, and their prey such as rabbits [1].''"}, {"source": "remediation_change_log:103347", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:103348", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-35000'' -> None"}, {"source": "remediation_change_log:154739", "url": "remediation_change_log", "quote": "served-image-2026-09-30-018: thumbnail_url ''/data/images/wiki/87abc0f0/hero.webp'' -> ''/data/images/wiki/87abc0f0/PegodoDiabo3.webp''"}, {"source": "remediation_change_log:302159", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:302160", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-50000''"}, {"source": "remediation_change_log:323289", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-002: thumbnail_url ''/data/images/wiki/87abc0f0/PegodoDiabo3.webp'' -> ''/data/images/wiki/87abc0f0/hero.webp''"}, {"source": "remediation_change_log:325290", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/87abc0f0/hero.webp'' -> ''/data/images/wiki/87abc0f0/PegodoDiabo1.webp''"}]'::jsonb),
