    ('87ea9721-2bb2-456a-b1e6-8a44dbde62d3'::uuid, 'mystery', '7', '4', 'card-stats-2026-11-05-rollback:87ea9721-2bb2-456a-b1e6-8a44dbde62d3:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Winterbourne Bassett Stone Circle', 'afa628cbff050ec1ad0fcd46708a73b5', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Stone circle'', ''4500 - 3000 BC'') is shared by 8 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36775", "url": "remediation_change_log", "quote": "phase4:p4-0042:chunk-0001: description ''Remains of a Neolithic double concentric stone circle near the village of Winterbourne Bassett in Wiltshire, 5.5 km north of Avebury. The outer ring measured approximately 234 feet in diameter with an inner ring of 148 feet, plus a single central stone. Today only six stones remain visible, none upright. Designated a scheduled monument in 1924, the circle was part of a Late Neolithic to Early Bronze Age tradition of stone circle construction (c.3300-900 BCE) alongside nearby Avebury and The Sanctuary.'' -> ''Knowledge of Winterbourne Bassett Stone Circle derives almost entirely from antiquarian sources [1]. Stukeley recorded two concentric sarsen rings, with an outlying stone to the west of these [1]. Smith\\''s plan, produced in the 1880s, proposed a diameter of c.71m for the outer circle and 45m for the inner circle [1]. The archaeologists Joshua Pollard and Andrew Reynolds stated that there was a \"real need\" for archaeologists to establish whether Winterbourne Bassett Stone Circle really was a human-built structure or whether it had been a scatter of natural stones mistaken for the former [1]. A geophysical survey in 1998 confirmed at least seven of the stones at the places indicated by Smith, although the results were described as being \"very ambiguous\" [1].''"}, {"source": "remediation_change_log:103355", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:103356", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:250633", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:250634", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-4000''"}]'::jsonb),
