    ('8838f1fa-2c3c-44b6-a554-75e34ae61ee9'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:8838f1fa-2c3c-44b6-a554-75e34ae61ee9:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Kahu-Jo-Darro', '4adf3b1223469f1f8005bf8d60ebc954', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Archaeological site'', ''1 - 500 AD'') is shared by 15 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28196", "url": "remediation_change_log", "quote": "phase3:batch-0091:chunk-0002: site_type ''Temple complex'' -> ''Monument''"}, {"source": "remediation_change_log:35870", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Monument'' -> ''Temple complex''"}, {"source": "remediation_change_log:36777", "url": "remediation_change_log", "quote": "phase4:p4-0042:chunk-0001: description ''(1st-5th c. AD) Kahu-Jo-Darro is an ancient Buddhist stupa at the Mirpurkhas site in Sindh, Pakistan. The temple complex covers 30 acres (120,000 m²) and was excavated before 1910, revealing a large brick-based stupa with numerous terracotta reliefs now housed in major world museums[1]. Archaeological finds include historic Indian and Arab coins, which scholars like Derryl MacLean cite as evidence that Buddhism was thriving in Sindh until the 10th century, declining after the Islamic conquest[2].'' -> ''Kahu-Jo-Darro, also known as Mirpur Khas stupa, is an ancient Buddhist stupa found at the Mirpurkhas archaeological site in Sindh, Pakistan [1]. The site is spread over 30 acres [1]. Excavations completed before 1910 revealed this large brick-based stupa and numerous terracotta reliefs now displayed in major world museums [1]. Clay tablets containing the Buddhist formula \"Ye Dharma Hetu\" in 7th-8th century script were also found [1]. The stupa was decorated using terracotta sculptures representing the Buddha [1]. According to Henry Cousens, the Kahu-Jo-Daro site was significantly damaged when railway contractors in colonial-era Sindh carted off large quantities of the ancient bricks to use them as track ballast [1].''"}, {"source": "remediation_change_log:103361", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: site_type ''Temple complex'' -> None"}, {"source": "remediation_change_log:154748", "url": "remediation_change_log", "quote": "served-image-2026-09-30-018: thumbnail_url ''/data/images/wiki/8838f1fa/hero.webp'' -> ''/data/images/wiki/8838f1fa/KAHO J DARO.webp''"}, {"source": "remediation_change_log:239687", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: site_type None -> ''Archaeological site''"}, {"source": "remediation_change_log:313866", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/8838f1fa/KAHO J DARO.webp'' -> ''/data/images/wiki/8838f1fa/Buddha,_da_mirpur_khas,_sindh_(pakistan),_410_dc_ca.webp''"}]'::jsonb),
