    ('8a66f7db-94df-45d9-919f-760b966192be'::uuid, 'mystery', '10', '9', 'card-stats-2026-11-05-rollback:8a66f7db-94df-45d9-919f-760b966192be:mystery', 'rollback of card-stats-2026-11-05: mystery ''9'' restored on Gunung Padang Megalithic Site', 'e875c5551a7bb18642514d71ce9cc8e3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 10 from (''Megalithic structures'', ''500 BC - 1 AD'') is shared by 1 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36805", "url": "remediation_change_log", "quote": "phase4:p4-0043:chunk-0001: description \"Indonesia''s largest megalithic site, located on an extinct volcano in West Java with five terraces, stone retaining walls, and roughly 370 steps built from andesite columnar joints. First recorded by Dutch colonizers in 1914, rediscovered by farmers in 1979, and declared a National Site in 2014. Archaeologist Lutfi Yondri''s 30-year excavation program dated charcoal samples to around 50-117 BCE, suggesting construction roughly 2,000 years ago. Claims of 20,000+ year dating by geologist Natawidjaja were retracted in 2024 after samples were found to be natural soil, not anthropogenic.\" -> ''Gunung Padang is an archaeological site located in Karyamukti, West Java, Indonesia, 50 kilometres southwest of Cianjur [1]. Located at 885 metres above sea level, the site covers a hill—an extinct volcano—in a series of five terraces bordered by retaining walls of stone that are accessed by 370 successive andesite steps rising about 95 metres [1]. It is covered with massive hexagonal stone columns of volcanic origin [1]. Gunung Padang consists of a series of five artificial terraces—one rectangular and four trapezoidal—that occur, in succession, at progressively higher elevations [1]. The terraces are aligned along a central longitudinal NW–SE axis [1]. They are artificial platforms created by lowering elevated areas and filling in depressions until a flat surface was achieved [1]. The perimeters of the terraces feature retaining walls constructed from volcanic polygonal columns [1]. Pottery fragments found at the site were dated by the bureau of archaeology in the range 45 BCE–22 CE [1].''"}, {"source": "remediation_change_log:120314", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_name ''1 - 500 AD'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:120315", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_start ''100'' -> ''-117''"}, {"source": "remediation_change_log:155304", "url": "remediation_change_log", "quote": "served-image-2026-09-30-019: thumbnail_url ''/data/images/wiki/8a66f7db/hero.webp'' -> ''/data/images/wiki/8a66f7db/Situs_Megalitikum_Gunung_Padang_Cianjur.webp''"}]'::jsonb),
    ('8a66f7db-94df-45d9-919f-760b966192be'::uuid, 'rarity_score', '52', '49', 'card-stats-2026-11-05-rollback:8a66f7db-94df-45d9-919f-760b966192be:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''49'' restored on Gunung Padang Megalithic Site', 'e875c5551a7bb18642514d71ce9cc8e3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 52 from mystery 10, cultural_influence 10"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36805", "url": "remediation_change_log", "quote": "phase4:p4-0043:chunk-0001: description \"Indonesia''s largest megalithic site, located on an extinct volcano in West Java with five terraces, stone retaining walls, and roughly 370 steps built from andesite columnar joints. First recorded by Dutch colonizers in 1914, rediscovered by farmers in 1979, and declared a National Site in 2014. Archaeologist Lutfi Yondri''s 30-year excavation program dated charcoal samples to around 50-117 BCE, suggesting construction roughly 2,000 years ago. Claims of 20,000+ year dating by geologist Natawidjaja were retracted in 2024 after samples were found to be natural soil, not anthropogenic.\" -> ''Gunung Padang is an archaeological site located in Karyamukti, West Java, Indonesia, 50 kilometres southwest of Cianjur [1]. Located at 885 metres above sea level, the site covers a hill—an extinct volcano—in a series of five terraces bordered by retaining walls of stone that are accessed by 370 successive andesite steps rising about 95 metres [1]. It is covered with massive hexagonal stone columns of volcanic origin [1]. Gunung Padang consists of a series of five artificial terraces—one rectangular and four trapezoidal—that occur, in succession, at progressively higher elevations [1]. The terraces are aligned along a central longitudinal NW–SE axis [1]. They are artificial platforms created by lowering elevated areas and filling in depressions until a flat surface was achieved [1]. The perimeters of the terraces feature retaining walls constructed from volcanic polygonal columns [1]. Pottery fragments found at the site were dated by the bureau of archaeology in the range 45 BCE–22 CE [1].''"}, {"source": "remediation_change_log:120314", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_name ''1 - 500 AD'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:120315", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_start ''100'' -> ''-117''"}, {"source": "remediation_change_log:155304", "url": "remediation_change_log", "quote": "served-image-2026-09-30-019: thumbnail_url ''/data/images/wiki/8a66f7db/hero.webp'' -> ''/data/images/wiki/8a66f7db/Situs_Megalitikum_Gunung_Padang_Cianjur.webp''"}]'::jsonb),
