    ('8baf0d5a-4f61-4d77-a3f9-2eba4321fadf'::uuid, 'empire_count', '1', '0', 'card-stats-2026-11-05-rollback:8baf0d5a-4f61-4d77-a3f9-2eba4321fadf:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Castle Crag', 'cdf87dfa5c5e96f874691a74feddedb0', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 1 from tag_site(54.53292095358903, -3.1619765891012284, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84248", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:84249", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:84250", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: site_type ''Fortress/citadel'' -> ''Fort''"}, {"source": "remediation_change_log:84251", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: source_url ''https://en.wikipedia.org/wiki/Castle_Crag'' -> ''https://www.megalithic.co.uk/article.php?sid=13326''"}, {"source": "remediation_change_log:85884", "url": "remediation_change_log", "quote": "phase4:p4-2126:chunk-0001: description ''Castle Crag is a conical hill in Borrowdale, Lake District, whose summit hosted a slight univallate Iron Age hillfort. The internal enclosure measures approximately 60 m by 25 m, protected on the north and northeast by a turf-covered stone rampart up to 4 m wide. Fragments of Roman Samian ware found on the hill indicate trade with nearby Roman settlers. Norse settlers named the valley \"Borgar dalr\" (valley of the fortress), referencing the ancient fort. An 18th-century slate quarry destroyed much of the southern fortification. The summit was given to the National Trust as a World War One memorial to Borrowdale\\''s fallen.'' -> ''Castle Crag is a hill in the North Western Fells of the English Lake District [1]. The wooded height of Castle Crag rises between Broadslack Gill and the Derwent [1]. The slopes of Castle Crag are extensively quarried with pits and levels on the northern and south eastern flanks [1]. The summit has also been extensively worked [1]. The summit area is believed to have been an ancient hill fort, although the western section has been sliced away by quarrying [1].''"}, {"source": "remediation_change_log:155336", "url": "remediation_change_log", "quote": "served-image-2026-09-30-019: thumbnail_url ''/data/images/wiki/8baf0d5a/hero.webp'' -> ''/data/images/wiki/8baf0d5a/Castle_crag.webp''"}, {"source": "remediation_change_log:250669", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:250670", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-800''"}, {"source": "remediation_change_log:313922", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/8baf0d5a/Castle_crag.webp'' -> ''/data/images/wiki/8baf0d5a/Castle_Crag_summit.webp''"}, {"source": "remediation_change_log:350842", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:350843", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-800'' -> None"}]'::jsonb),
