    ('8bcea3e7-dfdc-4af5-8b75-70fb9e34d7ee'::uuid, 'cultural_influence', '8', '6', 'card-stats-2026-11-05-rollback:8bcea3e7-dfdc-4af5-8b75-70fb9e34d7ee:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''6'' restored on Berbati Valley', '2572a50ef161e803d9b60c01ad8093f6', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 8 from description yes, thumbnail yes, 4 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28396", "url": "remediation_change_log", "quote": "phase3:batch-0124:chunk-0001: period_start ''-5000'' -> ''-100000''"}, {"source": "remediation_change_log:35877", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-100000'' -> ''-5000''"}, {"source": "remediation_change_log:43557", "url": "remediation_change_log", "quote": "phase4:p4-0076:chunk-0001: description \"The Berbati Valley is an archaeological site in the northeastern Peloponnese, northeast of Argos in Greece, with evidence of human activity extending back to the Paleolithic era. The Swedish Institute at Athens began excavations in 1935 under Axel W. Persson, and fieldwork continued through the 1990s under Berit Wells. The most significant discovery was a Late Mycenaean Potter''s Quarter on Mastos hill containing over 175,000 ceramic sherds, including a kiln and pottery dumps dated to around 1400 BC. Vessels produced here have been found as far afield as Cyprus and the Levant, demonstrating long-distance Mycenaean trade networks.\" -> \"The Berbati Valley is an archaeological site located in the northeast of the Peloponnese, northeast of Argos [1]. The Swedish Institute at Athens started with archaeological excavations on the site in 1935, under supervision of Axel W. Persson [1]. In 1936, Persson and Åke Åkerström explored the eastern slopes of the Mastos Hill and found what would later be called the Potter''s Quarters [1]. Säflund investigated the Western Necropolis northwest of the Mastos Hill [1]. In 1937 he also excavated part of an Early Helladic settlement that continued into the Middle Helladic period [1]. The earliest remains in the Berbati and Limnes valleys date from the Middle Palaeolithic (around 100.000–35.000 BCE) period, with a limited number of flaked stone tools suggesting frequent human visits over a long period of time [1]. During the Upper Palaeolithic (around 30.000–11.000 BCE) a decline in material is noticeable [1].\""}, {"source": "remediation_change_log:340904", "url": "remediation_change_log", "quote": "insert-2026-10-07-005-001: thumbnail_url None -> ''/data/images/wiki/8bcea3e7/Pottery from Cult place at the Berbati tholos, AM of Nafplio, 202294.webp''"}]'::jsonb),
