    ('8c66d030-330a-4f76-9e07-8e1ed0b0f706'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:8c66d030-330a-4f76-9e07-8e1ed0b0f706:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Roman Rig', '6fe2ec256a7914c9346245ab5e957a7c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85902", "url": "remediation_change_log", "quote": "phase4:p4-2127:chunk-0001: description ''The Roman Rig is a series of earthworks in north Rotherham, South Yorkshire, England. The earthworks are believed to have originally formed a single dyke extending from near Wincobank in Sheffield to Mexborough [1]. Its purpose and exact date of construction remain unknown [1]. Formerly interpreted as a Roman road, modern archaeologists propose two possible origins: either built in the 1st century AD by the Brigantian tribes as defence against the Roman invasion of Britain, or constructed after the 5th century to defend the Kingdom of Elmet from Anglo-Saxon expansion [1].'' -> \"The Roman Rig is the name given to a series of earthworks in the north of Rotherham, in South Yorkshire [1]. They are believed to originally have formed a single dyke running from near Wincobank, in Sheffield to Mexborough [1]. Its purpose and date of construction are unknown [1]. Formerly thought to have been a Roman road, modern archaeologists think that it was built either in the 1st century AD by the Brigantian tribes as a defence against the Roman invasion of Britain or after the 5th century to defend the kingdom of Elmet from the Angles [1]. The southernmost end of the dyke is thought to have been close to Lady''s Bridge at the River Don in Sheffield, but today, it becomes visible only close to the Iron Age fort at Wincobank [1]. The dyke continues in a north-easterly direction following the Don Valley to Kimberworth in Rotherham where it splits into two branches that continue roughly parallel to each other in a sweep starting to the north-east and turning east [1].\""}, {"source": "remediation_change_log:103411", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:103412", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''1'' -> None"}, {"source": "remediation_change_log:250675", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:250676", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-4000''"}, {"source": "remediation_change_log:350848", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:350849", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-4000'' -> None"}]'::jsonb),
