    ('8cead41d-19f8-45cf-9dc0-144583641e4f'::uuid, 'mystery', '8', '7', 'card-stats-2026-11-05-rollback:8cead41d-19f8-45cf-9dc0-144583641e4f:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Banwolseong', 'e934c1008b43b42f0b841c59f46f4773', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Palace'', ''1 - 500 AD'') is shared by 5 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27924", "url": "remediation_change_log", "quote": "phase3:batch-0031:chunk-0001: period_start ''1'' -> ''-57''"}, {"source": "remediation_change_log:30451", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1 - 500 AD'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:32417", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-journal-reversal-2: period_name ''500 BC - 1 AD'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:32418", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-journal-reversal-2: period_start ''-57'' -> ''1''"}, {"source": "remediation_change_log:85906", "url": "remediation_change_log", "quote": "phase4:p4-2127:chunk-0001: description ''The crescent-shaped royal palace-fortress of the Silla dynasty in Gyeongju, South Korea, occupied for nearly 900 years from the reign of King Seoktalhae (AD 57-80) through the 56th king Gyeongsoon (r. 927-935). Meaning \"Half Moon Fortress\" for the shape of its walls, Banwolseong served as the political center of the Silla and Unified Silla kingdoms (57 BC - 935 AD). The site preserves the Seokbinggo, a Joseon-era stone ice storage facility. It is part of the Gyeongju Historic Areas, a UNESCO World Heritage Site.'' -> ''Wolseong or Wolseong Palace was a royal palace of Silla [1]. It was located in what is now Gyeongju [1]. The palace was used during the Silla and Unified Silla periods [1]. The palace gets its names from the approximate outline of the palace walls, which were shaped like a crescent moon [1]. It is also called Banwolseong or Sinwolseong or Jaeseong, which means where the king resides [1]. The South Korean government has also designated the palace ruins as Historic Site No. 16 [1].''"}, {"source": "remediation_change_log:120354", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: site_type ''Castle/palace'' -> ''Palace''"}, {"source": "remediation_change_log:120355", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: source_url ''https://en.wikipedia.org/wiki/Banwolseong'' -> ''https://en.wikipedia.org/wiki/Wolseong''"}]'::jsonb),
