    ('8d4f7a98-2c79-4a0e-ae9b-c8f4a665902f'::uuid, 'mystery', '4', '8', 'card-stats-2026-11-05-rollback:8d4f7a98-2c79-4a0e-ae9b-c8f4a665902f:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Brittenburg', 'f6217f40210dc3a19e50db84b584b948', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Fortress/citadel'', ''1 - 500 AD'') is shared by 91 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28252", "url": "remediation_change_log", "quote": "phase3:batch-0100:chunk-0003: site_type ''City/town/settlement'' -> ''Fortress''"}, {"source": "remediation_change_log:85912", "url": "remediation_change_log", "quote": "phase4:p4-2127:chunk-0001: description ''Brittenburg was a Roman ruin site west of Leiden between Katwijk aan Zee and Noordwijk aan Zee, likely identical to the earlier Celtic Lugdunum fortress[1]. First mentioned in 1401, it was uncovered by storm erosion in 1520, 1552, and 1562, then entirely eroded away[1]. Archaeological evidence indicates it served as a Roman naval base and fortified military granary at the Rhine estuary[2].'' -> ''Brittenburg was a Roman ruin site west of Leiden between Katwijk aan Zee and Noordwijk aan Zee, presumably identical to the even older Celtic Lugdunum fortress [1]. The site is first mentioned in 1401, was uncovered more completely by storm erosion in 1520, 1552 and 1562, and has subsequently been entirely eroded away [1]. When built, it was located at the mouth of the Oude Rijn (old river Rhine), which has since moved [1]. The site was about one kilometre west of the European Space Research and Technology Centre, now offshore in the North Sea [1]. The site, known as \"Brittenburg\", was still visible in the dunes in the fourteenth century, but the gradual advance of the sea made the ruins lie on the beach in the sixteenth and seventeenth century [1]. Today, they would be somewhere in the North Sea, inaccessible to archaeological research [1]. All that remains is a small set of finds, collected in the sixteenth and seventeenth centuries, and a famous map by Ortelius [1].''"}, {"source": "remediation_change_log:103421", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:103422", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:155366", "url": "remediation_change_log", "quote": "served-image-2026-09-30-019: thumbnail_url ''/data/images/wiki/8d4f7a98/hero.webp'' -> ''/data/images/wiki/8d4f7a98/Brittenburg, Objectnr PV PV75948.webp''"}, {"source": "remediation_change_log:239727", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:239728", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_start None -> ''301''"}, {"source": "remediation_change_log:334583", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/8d4f7a98/Brittenburg, Objectnr PV PV75948.webp'' -> ''/data/images/wiki/8d4f7a98/ValkenburgZH-kaart-P.vanBilderbeeck.webp''"}, {"source": "remediation_change_log:355916", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Fortress'' -> ''Fortress/citadel''"}]'::jsonb),
