    ('8d5b27e6-c0ab-4c08-8742-7bb0c59bcfa5'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:8d5b27e6-c0ab-4c08-8742-7bb0c59bcfa5:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Villa of Torre de Palma', 'd7ab941c294bdab13718c93f6cce6cc3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -700"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85916", "url": "remediation_change_log", "quote": "phase4:p4-2127:chunk-0001: description ''The Villa Lusitano-Romana de Torre de Palma is a Roman villa near Monforte in Portugal, in the Roman province of Lusitania[1]. It is considered one of the largest villas in the Iberian Peninsula[1]. The estate prospered through latifundia agriculture, evidenced by shrines found in its courtyard[1]. The complex includes extensive living areas, a basilica, and a remarkable seven-roomed baptistery[1].'' -> ''The villa of Torre de Palma is located about 5 km northwest of Monforte on the main road to Vaiamonte  [1]. The remains of the villa were discovered in 1947 and until 1956, excavations were conducted under the direction of the Portuguese archaeologist Manuel Heleno [1]. The chronology of the various periods of the villa ranges from the 1st to the 5th century [1]. In addition to a large residential complex, a thermal complex was discovered to the east, and a building north of the main building may also have been used for residential purposes [1].''"}, {"source": "remediation_change_log:103426", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:103427", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''1'' -> None"}, {"source": "remediation_change_log:155368", "url": "remediation_change_log", "quote": "served-image-2026-09-30-019: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/2/24/Mosaic_floor%2C_Roman_Villa_Torre_de_Palma%2C_Lusitania%2C_Portugal_%2813029498433%29.jpg'' -> ''/data/images/wiki/8d5b27e6/Mosaic_floor,_Roman_Villa_Torre_de_Palma,_Lusitania,_Portugal_(13029498433).webp''"}, {"source": "remediation_change_log:239732", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:239733", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_start None -> ''1''"}, {"source": "remediation_change_log:350861", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1 - 500 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:350862", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''1'' -> ''-700''"}]'::jsonb),
