    ('8dace4e6-f6f7-4901-8132-897017b01700'::uuid, 'antiquity', '4', '6', 'card-stats-2026-11-05-rollback:8dace4e6-f6f7-4901-8132-897017b01700:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on Tulamba', '19ac73c16ce70da6b3745345ee4a55cf', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 4 from period_start -500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85936", "url": "remediation_change_log", "quote": "phase4:p4-2128:chunk-0001: description ''Tulamba is an ancient settlement in Punjab, Pakistan, located on the eastern bank of the Ravi River between Abdul Hakeem and Mian Channu [1]. Archaeological excavations have revealed four distinct cultural layers spanning Hindu, Buddhist, Muslim, and Sikh civilizations [2]. Numerous coins from various historical governments have been unearthed during digs [2]. The ancient ruins lie on the edge of the modern town, which now has a population of nearly 50,000 people [1]. The settlement was part of Multan District until 1985, when it became part of Mian Channu Tehsil in newly formed Khanewal District [1].'' -> \"Tulamba is more than 2,500 years old [1]. Archaeological digs have uncovered four distinct layers, belonging to the Hindu, Buddhist, Muslim, Sikh civilisations [1]. The coins of several prior governments have been excavated here [1]. Tulamba saw the influence of several Mahajanapada of ancient India, mainly Gandhara, Kamboja and Magadha [1]. Alexander the Great came to Tulamba when he invaded the Indian sub-continent [1]. At that time Tulamba was ruled by the Moi people, who fought Alexander''s forces [1]. The ruins of the ancient city are situated on the edge of the modern city [1].\""}, {"source": "remediation_change_log:103428", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:103429", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:155371", "url": "remediation_change_log", "quote": "served-image-2026-09-30-019: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/5/54/Ruins_of_Old_Tulamba_-_panoramio.jpg'' -> ''/data/images/wiki/8dace4e6/hero.webp''"}, {"source": "remediation_change_log:250689", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:250690", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-1500''"}, {"source": "remediation_change_log:325298", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/8dace4e6/hero.webp'' -> ''/data/images/wiki/8dace4e6/Ruins of Old Tulamba - panoramio.webp''"}, {"source": "remediation_change_log:357263", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s006: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:357264", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s006: period_start ''-1500'' -> ''-500''"}]'::jsonb),
