    ('8e131607-f575-485f-8115-275c68dda764'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:8e131607-f575-485f-8115-275c68dda764:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Beech Bottom Dyke', 'ba6ce90dbaf138f8763d7d395f6876f9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Earthwork'', ''1 - 500 AD'') is shared by 11 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85942", "url": "remediation_change_log", "quote": "phase4:p4-2128:chunk-0001: description ''Beech Bottom Dyke is a massive Late Iron Age earthwork at the northern edge of St Albans, Hertfordshire, up to 30 m wide and 10 m deep, traceable for nearly 1.2 km. Constructed probably between 5 and 40 AD, it is attributed to the Catuvellauni tribe, likely built under King Cunobelinus to define territorial boundaries around their centre at Verlamion, predecessor of Roman Verulamium. The dyke formed part of a boundary system linking the settlements near St Albans and Wheathampstead, isolating high ground between the Rivers Ver and Lea. It is a Scheduled Ancient Monument.'' -> ''Beech Bottom Dyke, is a large ditch running for almost a mile at the northern edge of St Albans, Hertfordshire, flanked by banks on both sides [1]. It is up to 30 m wide, and 10 m deep [1]. The dyke was constructed towards the end of the Iron Age, probably between 5 and 40 AD [1]. This, and other similar earthworks in the district, may have been built by the powerful Celtic tribe established in this area, the Catuvellauni, probably by King Cunobelinus to define areas of land around their tribal centre at Verlamion, the predecessor of the Roman city of Verulamium [1]. Beech Bottom Dyke is thought to have originally been part of a defensive system for a Belgic settlement [1].''"}, {"source": "remediation_change_log:103436", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:103437", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''1'' -> None"}, {"source": "remediation_change_log:103438", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: site_type ''Earthwork'' -> None"}, {"source": "remediation_change_log:239734", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:239735", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_start None -> ''5''"}, {"source": "remediation_change_log:239736", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: site_type None -> ''Earthwork''"}]'::jsonb),
