    ('8e4daf07-4633-4481-865a-9243993c227c'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:8e4daf07-4633-4481-865a-9243993c227c:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Castle Close', 'a7e799f4560b2dbd326d49751af9d606', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -800"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28054", "url": "remediation_change_log", "quote": "phase3:batch-0059:chunk-0001: site_type ''Earthwork'' -> ''Fortress/citadel''"}, {"source": "remediation_change_log:35879", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Fortress/citadel'' -> ''Earthwork''"}, {"source": "remediation_change_log:85946", "url": "remediation_change_log", "quote": "phase4:p4-2128:chunk-0001: description ''Castle Close is a circular univallate earthwork near Stoodleigh in Mid Devon, England, situated 208 m above sea level overlooking the River Exe. Most likely an Iron Age hillfort or enclosure, the site occupies a prominent hill with clear sightlines to other Devon hillforts including Cadbury Castle, Huntsham Castle, Cranmore Castle, and Hembury Fort, suggesting they were all contemporary and part of an interconnected defensive network. While the earthworks are less pronounced than those at neighbouring sites, they retain the classical layout typical of Iron Age enclosures in the region.'' -> ''Castle Close is a circular earthwork located near Stoodleigh in Mid Devon [1]. It is described on maps as a settlement [1]. Situated some 208 metres above sea level, overlooking the River Exe, it is most likely to be an Iron Age Hill fort or enclosure [1]. While the earthworks do not appear as pronounced as others nearby at Huntsham Castle, Cranmore Castle and Cadbury Castle they are still in a classical layout typical of an Iron Age hill fort or enclosure [1]. These other Devon Hill forts are all in plain view from the centre of the enclosure [1].''"}, {"source": "remediation_change_log:103441", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:103442", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:250697", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:250698", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-4000''"}, {"source": "remediation_change_log:350868", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''4500 - 3000 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:350869", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-4000'' -> ''-800''"}]'::jsonb),
