    ('8ef67a96-2590-4382-b575-4a15f7c468fe'::uuid, 'antiquity', '10', '3', 'card-stats-2026-11-05-rollback:8ef67a96-2590-4382-b575-4a15f7c468fe:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Cova Foradà', '7fbb793f85a61a909312bdcdb3fee8af', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -300000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85966", "url": "remediation_change_log", "quote": "phase4:p4-2129:chunk-0001: description ''Cova Foradà is an archaeological cave site with Neanderthal remains near Oliva, in Valencia, Spain [1]. The most complete Neanderthal skeleton ever found on the Iberian peninsula was discovered there in 2010 [1]. One individual used a toothpick to relieve dental pain from periodontal disease and wear [1].'' -> ''Cova Foradà (or Cova Foradada) is an archaeological site consisting of a cave with remains of Neanderthals near Oliva, in the Province of Valencia, Spain [1]. The most complete skeleton of a Neanderthal ever found on the Iberian peninsula was found there in 2010 [1]. The karst cave is located 5 kilometres southeast of the village of Oliva, at 3.5 kilometres from the coast of the Mediterranean, and archaeological excavations have taken place since 1977 [1]. The cave is found in a low hill, one of a group of hills called the Muntanyetes de Oliva, the last part of the Serra de Mustalla before the floodplain that ends at the coast [1]. It has been occupied since the Middle Paleolithic, including in the Mousterian and Mesolithic periods, and in the Bronze Age [1]. A maxilla (almost complete, with a number of teeth), a molar, a fibula, and four fragments of a cranium belonging to two humans were found between 2000 and 2003, in what appeared to be a layer from the Mousterian [1].''"}, {"source": "remediation_change_log:103460", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:103461", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-100000'' -> None"}, {"source": "remediation_change_log:251045", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:251046", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''1''"}, {"source": "remediation_change_log:341459", "url": "remediation_change_log", "quote": "insert-2026-10-07-006-001: thumbnail_url None -> \"/data/images/wiki/8ef67a96/Talla lítica, conjunt de la cova Foradà, Museu Arqueològic d''Oliva.webp\""}, {"source": "remediation_change_log:350874", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1 - 500 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:350875", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''1'' -> ''-300000''"}]'::jsonb),
