    ('8f0bd6a2-46b6-46cb-afbb-efd18b2471d8'::uuid, 'total_power', '22', '24', 'card-stats-2026-11-05-rollback:8f0bd6a2-46b6-46cb-afbb-efd18b2471d8:total_power', 'rollback of card-stats-2026-11-05: total_power ''24'' restored on Yereruyk Archaeological Site', '28f5987aee22aa6c35973873a4fb7af1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 22 from antiquity + fortification + cultural_influence + mystery + legacy = 3 + 3 + 9 + 6 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85968", "url": "remediation_change_log", "quote": "phase4:p4-2129:chunk-0001: description ''One of the earliest surviving Armenian Christian monuments, this basilica near the village of Anipemza in Shirak Province was built in the 5th century by the Kamsarakan princely family. Constructed from pink tuff stone on an elevated stepped foundation, the three-aisled basilica features a large columned hall and ornately carved southern portal. An inscription identifies it as a martyrial sanctuary dedicated to Saint John the Baptist and Saint Stephen. Added to the UNESCO World Heritage Tentative List in 1995, the basilica is considered a key to understanding the origins of Armenian ecclesiastical architecture. It was severely damaged in the 1988 earthquake.'' -> ''Yererouk, also Yereruyk or Ererouk, is an ancient Armenian church near the village of Anipemza in the Shirak Province of Armenia [1]. Yererouk was built on a plateau near the Akhurian River, which defines the frontier with Turkey, about 5 km southeast of the ancient city of Ani [1]. Yererouk means quivering in the Armenian language [1]. According to Toros Toramanian, Yererouk is a clear and perhaps the earliest example of the basilica style of the Armenian church buildings that are constructed on pillars [1]. The church was surrounded with thick walls [1]. From the surrounding buildings, underground rooms and the water reservoir, it becomes clear that the church was the centre of a developed residential community [1]. Yererouk Basilica is similar to Syrian basilicas in the architectural system and in the sculptural decoration [1].''"}, {"source": "remediation_change_log:120378", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: site_type ''Temple complex'' -> ''Church''"}, {"source": "remediation_change_log:155398", "url": "remediation_change_log", "quote": "served-image-2026-09-30-019: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/8/87/%D4%B5%D6%80%D5%A5%D6%80%D5%B8%D6%82%D5%B5%D6%84%D5%AB_%D5%8F%D5%A1%D5%B3%D5%A1%D6%80_05.jpg'' -> ''/data/images/wiki/8f0bd6a2/Երերույքի_Տաճար_03.webp''"}, {"source": "remediation_change_log:313960", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/8f0bd6a2/Երերույքի_Տաճար_03.webp'' -> ''/data/images/wiki/8f0bd6a2/Երերույքի_Տաճար_05.webp''"}, {"source": "remediation_change_log:355917", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Church'' -> ''Church/cathedral''"}]'::jsonb),
    ('8f256d92-11a1-4310-90e2-be5cebfc350e'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:8f256d92-11a1-4310-90e2-be5cebfc350e:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Great Serpent Mound', '4b53b82e065ee343215c4591acad5c38', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85970", "url": "remediation_change_log", "quote": "phase4:p4-2129:chunk-0001: description ''The Great Serpent Mound is a 1,348-foot-long (411m), four-feet-high prehistoric effigy mound located in Peebles, Ohio[1]. It was built on the Serpent Mound crater plateau, running along Ohio Brush Creek in Adams County, Ohio[1]. The mound is the largest serpent effigy known in the world[1].'' -> ''The Great Serpent Mound is a 1,348-feet-long (411m), four-feet-high precontact effigy mound located in Peebles, Ohio, United States [1]. It was built on what is known as the Serpent Mound crater plateau, running along the Ohio Brush Creek in Adams County, Ohio [1]. The mound is the largest serpent effigy known in the world [1]. The first published surveys of the mound, by E. G. Squier and Edwin Hamilton Davis, were featured in their 1848 study Ancient Monuments of the Mississippi Valley [1]. Serpent Mound conforms to the surrounding land, as it was built on a bluff above the Ohio Brush Creek [1]. The mound is located on the site of a meteorite impact site known as the Serpent Mound crater [1]. The crater is around 8.7 miles in diameter and was formed 252–330 million years ago [1].''"}, {"source": "remediation_change_log:120379", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:120380", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s006: period_start ''1'' -> None"}, {"source": "remediation_change_log:155401", "url": "remediation_change_log", "quote": "served-image-2026-09-30-019: thumbnail_url ''/data/images/wiki/8f256d92/hero.webp'' -> ''/data/images/wiki/8f256d92/Adena Burial Mound at Serpent Mound.webp''"}, {"source": "remediation_change_log:239749", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:239750", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s006: period_start None -> ''-300''"}, {"source": "remediation_change_log:313963", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/8f256d92/Adena Burial Mound at Serpent Mound.webp'' -> ''/data/images/wiki/8f256d92/Serpent_mound_8438.webp''"}, {"source": "remediation_change_log:350876", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350877", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-300'' -> None"}]'::jsonb),
