    ('8f34775c-ca69-41e8-9517-35005cdc21b8'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:8f34775c-ca69-41e8-9517-35005cdc21b8:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Aughlish', 'f9f0328085af79d7b4d0eaf86535e477', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:30801", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-uk-parts: country ''Ireland'' -> ''Northern Ireland''"}, {"source": "remediation_change_log:36837", "url": "remediation_change_log", "quote": "phase4:p4-0044:chunk-0001: description ''Bronze Age ritual complex in the Sperrin Mountains of County Londonderry, Northern Ireland, comprising at least six stone circles and two stone rows. The largest circle contains 41 small stones with a fallen 1.5 m stone at the south, while one alignment stretches for 18 metres. Aubrey Burl considers the site typical of Bronze Age ritual sites in the Sperrins, with the layout indicating connections to circle-building traditions in England, Scotland, and wider Ireland. A stone row aligns with the southernmost setting point of the Moon, suggesting a lunar observational purpose.'' -> ''Aughlish (also Auglish) is a townland and the site of at least six stone circles and two stone rows, in County Londonderry, Northern Ireland, 3.6 km from Feeny [1]. The site features a group of circles including one with 41 small stones and a fallen stone 150 cm high at the south, with another of the same height outside the circle to the north [1]. There are three other circles (or parts of circles) with alignments, one of which stretches for 18m [1]. Aubrey Burl considers the site to be typical of Irish Bronze Age ritual sites around the Sperrins, the local range of hills [1]. He argues that the layout of the stone circles and rows indicates connections with circle builders in England, Scotland and elsewhere in Northern Ireland [1].''"}, {"source": "remediation_change_log:103462", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:103463", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:251047", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251048", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-4000''"}, {"source": "remediation_change_log:350878", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:350879", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
