    ('90923e91-3e29-4568-aa2e-989de43d2a0f'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:90923e91-3e29-4568-aa2e-989de43d2a0f:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on La Ferrassie', '239d2dd957005f18743fbcbb76c2ad46', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81102", "url": "remediation_change_log", "quote": "phase4:p4-2020:chunk-0001: description \"A major Palaeolithic rock shelter in Savignac-de-Miremont, Dordogne, France, where Neanderthal fossils were discovered between 1909 and 1921. Eight individuals were found intentionally buried at the site, including a man, a woman, children, an infant, and newborns, dating to approximately 50,000 years ago. The adult male La Ferrassie 1 preserves the largest and most complete Neanderthal skull ever found. One child''s grave contained a skull covered by a limestone slab with markings on its underside, suggesting ritualistic behavior. The site provided key evidence for Neanderthal burial practices and is associated with Middle Palaeolithic Mousterian stone tools.\" -> ''La Ferrassie is an archaeological site in Savignac-de-Miremont France [1]. The site, located in the Vézère valley, consists of a large and deep cave flanked by two rock shelters within a limestone cliff, under which there is a scree slope formation [1]. Artifacts found at the site are the productions of Mousterian (300,000-30,000 BP), Aurignacian (45,000–35,000 BP), and Périgordian (35,000–20,000 BP) cultures [1]. Complex Mousterian burial structures found at La Ferrasie finally provided the evidence of Neanderthal burial practice [1]. At least seven Neanderthals have been found in La Ferrassie, including infants and one fetus [1]. All specimens were found in a thin 60 cm archaeological layer dated to 74-68 thousand years ago [1].''"}, {"source": "remediation_change_log:103483", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:103484", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-500'' -> None"}, {"source": "remediation_change_log:155916", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''/data/images/wiki/90923e91/hero.webp'' -> ''/data/images/wiki/90923e91/La Ferrassie Grabungsflächen 2017-09-17.webp''"}, {"source": "remediation_change_log:251059", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:251060", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-500''"}, {"source": "remediation_change_log:313999", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/90923e91/La Ferrassie Grabungsflächen 2017-09-17.webp'' -> ''/data/images/wiki/90923e91/La_Ferrassie.webp''"}, {"source": "remediation_change_log:350888", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350889", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-500'' -> None"}]'::jsonb),
