    ('90a0c184-5830-45a7-a5ab-f82191dc0c23'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:90a0c184-5830-45a7-a5ab-f82191dc0c23:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Dudsbury Camp', 'ddd396dff9d65365dac15074dd0edfa1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -800"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:85996", "url": "remediation_change_log", "quote": "phase4:p4-2130:chunk-0001: description ''Dudsbury Camp (also known as Dudsbury Rings) is an Iron Age hillfort situated on the north bank of the River Stour near West Parley in Dorset, England[1]. It forms part of a linear chain of earthworks in the Stour valley, beginning at Hambledon Hill and continuing through Hod Hill, Spetisbury Rings, Buzbury Rings, and Badbury Rings, with the Iron Age port at Hengistbury Head marking the final monument in this sequence[1]. The defences enclose a semicircular area and utilize natural topography for strategic advantage[1].'' -> ''Dudsbury Camp (or Dudsbury Rings) is one of a series of Iron Age earthworks in Dorset, starting from Hambledon Hill, and including Hod Hill, Spetisbury Rings, Buzbury Rings, Badbury Rings and Dudsbury Camp [1]. The fort is located near the village of West Parley [1]. Dudsbury is an Iron Age hillfort situated on the north bank of the River Stour [1]. The defences enclose a semicircular area of about 3 hectares and consist of double ramparts and ditch on the west, north and east sides, with a steep slope to the river on the south side [1]. Much of the outer rampart and ditch has been obliterated or severely damaged [1]. The best preserved portion lies near the southwest corner where the inner rampart stands 1.5 metres above the interior and 4 metres above the bottom of the outer ditch [1]. The outer rampart there rises over 5 metres above the bottom of the ditch [1].''"}, {"source": "remediation_change_log:103485", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:103486", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:251061", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251062", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-4000''"}, {"source": "remediation_change_log:350890", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''4500 - 3000 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:350891", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-4000'' -> ''-800''"}]'::jsonb),
