    ('90cfd278-3aac-40b9-9d3c-d50a40bd3051'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:90cfd278-3aac-40b9-9d3c-d50a40bd3051:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Withypool Stone Circle', 'e6b91fb6b09339760dd985e0b326381d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2350"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86002", "url": "remediation_change_log", "quote": "phase4:p4-2130:chunk-0001: description ''Withypool Stone Circle sits on the Exmoor moorland in Somerset, England, near the village of Withypool[1]. Constructed during the Late Neolithic to Early Bronze Age (circa 3300–900 BCE), it belongs to a tradition of stone circle construction that spread across Britain, Ireland, and Brittany[1][2]. The purpose of these monuments remains unknown, though archaeologists suggest the stones may have represented supernatural entities for their builders[1].'' -> ''Withypool Stone Circle, also known as Withypool Hill Stone Circle, is a stone circle located on the Exmoor moorland, near the village of Withypool in the southwestern English county of Somerset [1]. The ring is part of a tradition of stone circle construction that spread throughout much of Britain, Ireland, and Brittany during the Late Neolithic and Early Bronze Age [1]. The Withypool ring is located on the south-western slope of Withypool Hill, on an area of heathland [1]. It is about 36.4 metres in diameter [1]. Around thirty small gritstones remain, although there may originally have been around 100; there are conspicuous gaps on the northern and western sides of the monument [1]. The site was rediscovered in 1898 and surveyed by the archaeologist Harold St George Gray in 1905 [1]. The site is 381 metres above sea level [1].''"}, {"source": "remediation_change_log:103490", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:103491", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:155942", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/a1/Withypool_Stone_Circle_%28geograph_4591136%29.jpg'' -> ''/data/images/wiki/90cfd278/Withypool_Stone_Circle,_May_2014.webp''"}, {"source": "remediation_change_log:251067", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251068", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-4000''"}, {"source": "remediation_change_log:350896", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:350897", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-4000'' -> ''-2350''"}]'::jsonb),
