    ('90f8d91e-5465-41c2-a297-8f33269c241e'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:90f8d91e-5465-41c2-a297-8f33269c241e:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Theatre of Clunia Sulpicia', 'b60b29b5168adecb32d6f66ce21d57d7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Theatre'', ''1 - 500 AD'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86006", "url": "remediation_change_log", "quote": "phase4:p4-2130:chunk-0001: description ''The Theatre of Clunia Sulpicia is a Roman theatre in the ancient city of Colonia Clunia Sulpicia, located between Coruna del Conde and Penalba de Castro in the province of Burgos, northern Spain. Built in the 1st century AD under Emperor Tiberius, it was semi-excavated into the hillside of Alto de Castro at 1,000 metres elevation, with a capacity of approximately 10,000 spectators -- one of the largest in Roman Hispania. Remodeled in the 2nd century for animal spectacles, the theatre remains the best-preserved monument at Clunia and hosts a Youth Festival of Greco-Latin Theatre since 1999.'' -> ''The Theatre of Clunia Sulpicia is a Roman theatre in the ancient city of Colonia Clunia Sulpicia, in what is now province of Burgos, northern Spain [1]. The edifice was built under the reign of Emperor Tiberius to monumentalize the most important city, along with Asturica Augusta, of the Douro basin [1]. The theatre is the most significant structure to survive at Clunia [1]. Carved out of rock, it had a capacity of 10,000 spectators, which made it one of the biggest of its time in Hispania [1]. It was intended to house performances of theatrical works of the classical period [1]. However, in the 2nd century, it underwent a renovation to adapt it for use as an amphitheater [1]. This resulted in the removal of parts of the lower cavea, the orchestra, and the podium of the scene [1]. Next to the remains of the postscenium, thirty burials were found during the 2008-09 excavation campaign, which can be associated with the 5th century [1].''"}, {"source": "remediation_change_log:155966", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/5/5a/Teatro_de_Clunia_01.JPG'' -> ''/data/images/wiki/90f8d91e/Clunia Sulpicia (Peñalba de Castro) - 001 (35754335521).webp''"}, {"source": "remediation_change_log:314005", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/90f8d91e/Clunia Sulpicia (Peñalba de Castro) - 001 (35754335521).webp'' -> ''/data/images/wiki/90f8d91e/Teatro_de_Clunia_01.webp''"}]'::jsonb),
