    ('918025af-8cfa-47db-a273-b4b715590e0c'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:918025af-8cfa-47db-a273-b4b715590e0c:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Broch of Mousa', 'ea0e1bcdc9b28ef248b4ac988c694322', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Minaret/tower'', ''500 BC - 1 AD'') is shared by 13 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86028", "url": "remediation_change_log", "quote": "phase4:p4-2131:chunk-0001: description \"The tallest surviving broch and one of the best-preserved prehistoric buildings in Europe, standing 13.3 metres high on the island of Mousa in Shetland. Constructed around 300 BC, its double-walled drystone structure contains six internal galleries reached by a staircase between the walls. The broch features in two Norse sagas: Egil''s Saga describes shipwrecked eloping lovers sheltering inside, while the Orkneyinga Saga recounts a siege by Earl Harald Maddadsson in 1153. Managed by Historic Environment Scotland as a scheduled monument.\" -> ''Broch of Mousa or Mousa Broch is a preserved Iron Age broch or round tower [1]. It is on the island of Mousa in Shetland [1]. It is the tallest broch still standing and amongst the best-preserved prehistoric buildings in Europe [1]. It is thought to have been constructed c.\\u2009300 BC [1]. Mousa Broch continued to be used over the centuries and is mentioned in two Norse Sagas [1]. The Orkneyinga Saga gives an account of a siege of the broch by Earl Harald Maddadsson in 1153 following the abduction of his mother [1].''"}, {"source": "remediation_change_log:155971", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''/data/images/wiki/918025af/hero.webp'' -> ''/data/images/wiki/918025af/Broch of Mousa from the Sea.webp''"}]'::jsonb),
