    ('920b1e8b-7b15-48bf-8352-e48ea2cdc264'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:920b1e8b-7b15-48bf-8352-e48ea2cdc264:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Riesenstein, Wolfershausen', '3071cc9e4f26eae69782d57cb9214643', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Megalithic stones'', ''3000 - 1500 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86060", "url": "remediation_change_log", "quote": "phase4:p4-2132:chunk-0001: description \"The Riesenstein (German for ''giant''s stone'') is a megalithic menhir located near Wolfershausen in Hesse, Germany. It is the largest megalith in the district of Schwalm-Eder-Kreis [1].\" -> ''The Riesenstein is a megalith or menhir, which is situated close to the village of Wolfershausen [1]. It is the largest megalith in the district of Schwalm-Eder-Kreis, Hesse, Germany [1]. The Riesenstein is located 1.14 km directly north of the village of Wolfershausen [1]. Riesenstein is composed of Neogene Miocene quartzite [1]. The megalith has an oblate rectangular cuboid shape [1]. It has a maximum height of 4.7 m, a maximum width of 4.6 m, and it is approximately 1 m thick [1]. In 1615 the megalith was first referred to in documents as \"Großer Stein\" [1].''"}, {"source": "remediation_change_log:103521", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:103522", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s013: perio