    ('92313299-3bb1-45c2-aa95-eb147b0269ba'::uuid, 'mystery', '1', '6', 'card-stats-2026-11-05-rollback:92313299-3bb1-45c2-aa95-eb147b0269ba:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Little Woodbury', '9773f671efb2c034b7435568ea1abad1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''500 BC - 1 AD'') is shared by 316 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86062", "url": "remediation_change_log", "quote": "phase4:p4-2132:chunk-0001: description ''An Iron Age settlement near Salisbury, Wiltshire, excavated in 1938-1939 by German archaeologist Gerhard Bersu using revolutionary open-area techniques. Bersu identified the first Iron Age roundhouse in Britain, overturning the prevailing belief that prehistoric Britons lived in pit-dwellings. He also found storage pits, granaries, corn-drying frames, animal bones, and cereal grains. War interrupted work in 1939 when Bersu was interned on the Isle of Man, and post-excavation was never completed. The site is a scheduled monument near Salisbury District Hospital.'' -> ''Little Woodbury is the name of an Iron Age archaeological site in Britford parish, near Salisbury in the English county of Wiltshire [1]. The site lies about 1+1⁄4 miles south of the centre of Salisbury and 1 mile north of Odstock village [1]. It was partially excavated in 1938 and 1939 by Gerhard Bersu [1]. A settlement had been identified at the site through aerial archaeology by O.G.S. Crawford almost twenty years previously [1]. Bersu worked at the site from 12 June to 18 September 1938, and 12 June to 19 July 1939 [1]. He dug a network of 4-5m wide parallel trenches across the site [1]. By this method he was able to identify a large roundhouse and several other domestic features such as corn-drying frames, granaries, and storage pits [1]. The postholes of the roundhouse enabled Bersu to argue that these structures were the common domestic building type of the Iron Age; prior to his work it was thought that people lived in clusters of pit-dwellings in the ground [1].''"}, {"source": "remediation_change_log:121455", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:121456", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:121457", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: site_type ''City/town/settlement'' -> ''Settlement''"}, {"source": "remediation_change_log:240627", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:240628", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-400''"}, {"source": "remediation_change_log:325302", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/92313299/hero.webp'' -> ''/data/images/wiki/92313299/Butser Farm Little Woodbury.webp''"}, {"source": "remediation_change_log:355921", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
