    ('92cad00e-4027-4e01-bb7d-2da01760d197'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:92cad00e-4027-4e01-bb7d-2da01760d197:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on West Kennet Long Barrow', '912fb795d28beb9826f811a3571c24e5', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44817", "url": "remediation_change_log", "quote": "phase4:p4-0100:chunk-0001: description ''One of the largest Neolithic chambered tombs in Britain, built around 3650 BC near Avebury, Wiltshire. The mound stretches over 100m long and up to 3.2m high, with five burial chambers opening off a central passage that extends 13m into the barrow. Remains of at least 46 individuals were found alongside grave goods including pottery, beads, and a stone dagger dating to 3000-2600 BC. Around 2000 BC the chambers were deliberately sealed with earth and sarsen boulders. Part of the Stonehenge and Avebury UNESCO World Heritage Site.'' -> ''The West Kennet Long Barrow, also known as South Long Barrow, is a chambered long barrow near the village of Avebury in the south-western English county of Wiltshire [1]. Built out of earth, local sarsen megaliths, and oolitic limestone imported from the Cotswolds, the long barrow consisted of a sub-rectangular earthen tumulus enclosed by kerb-stones [1]. Human bones were placed within the chamber, probably between 3670 and 3635 BC, representing a mixture of men, women, children, and adults [1]. In the Late Neolithic, the entrance to the long barrow was blocked up with the addition of large sarsen boulders [1]. The ruin attracted the interest of antiquarians in the 17th century, while archaeological excavation took place in 1859 and again in 1955-1956, after which it underwent reconstruction [1]. West Kennet Long Barrow is 100 metres long and 20 metres wide [1].''"}, {"source": "remediation_change_log:156008", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/4/49/Westkennet.jpg'' -> ''/data/images/wiki/92cad00e/West kennet long barrow interior.webp''"}, {"source": "remediation_change_log:314029", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/92cad00e/West kennet long barrow interior.webp'' -> ''/data/images/wiki/92cad00e/Westkennet.webp''"}]'::jsonb),
