    ('92d7c758-2244-465f-ac17-a6f8ca51a3cf'::uuid, 'mystery', '7', '6', 'card-stats-2026-11-05-rollback:92d7c758-2244-465f-ac17-a6f8ca51a3cf:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Willy Howe', '110d79d0371d1aa4784808a758497487', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Mound/tumulus'', ''4500 - 3000 BC'') is shared by 9 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86076", "url": "remediation_change_log", "quote": "phase4:p4-2132:chunk-0001: description ''Large Neolithic round barrow in the Yorkshire Wolds, standing 7.5m high and 40m in diameter between Wold Newton and Burton Fleming. Excavated by Lord Londesborough (1857) and Canon Greenwell (1887), neither found burials, though a rock-cut shaft was discovered beneath the center, similar to nearby Duggleby Howe. The site is associated with 12th-century fairy folklore recorded by William of Newburgh, describing a villager who witnessed people feasting inside the mound. It is a Scheduled Monument and one of the largest surviving barrows in eastern England.'' -> ''Willy Howe (also Willey-Hou) is a tumulus in the Yorkshire Wolds, East Riding of Yorkshire [1]. Willy Howe is a large round barrow 7.5 m (25 ft) high, located between Wold Newton and Burton Fleming in the civil parish of Thwing [1]. The mound has been recorded as being excavated several times: by Lord Londesborough in 1857; and by Canon William Greenwell in 1887 [1]. Neither found burials or grave goods; Greenwell found a feature approximating a shallow grave [1].''"}, {"source": "remediation_change_log:104186", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:104187", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:156015", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/0/0b/Willy_Howe_Barrow.JPG'' -> ''/data/images/wiki/92d7c758/Willy_Howe_Barrow.webp''"}, {"source": "remediation_change_log:251087", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251088", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-4000''"}]'::jsonb),
