    ('931ddb0f-7236-4315-ac59-8cc677dd5aa7'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:931ddb0f-7236-4315-ac59-8cc677dd5aa7:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Kents Cavern', 'fdce0606554c1c7ffa1338c251a90e77', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44821", "url": "remediation_change_log", "quote": "phase4:p4-0100:chunk-0001: description \"Kents Cavern is a prehistoric cave system in Torquay, Devon, and one of Europe''s most important Palaeolithic sites. A human jawbone fragment found in 1927 has been dated to 44,200-41,500 years ago, potentially the earliest evidence of Homo sapiens in northwestern Europe. William Pengelly''s 1865-1880 excavations pioneered the first 3D grid mapping system, laying foundations for modern archaeological methods. The cave''s six stratigraphic layers contain Acheulian to Magdalenian tools and remains of woolly mammoth, cave bear, and other extinct fauna. It has been a Site of Special Scientific Interest since 1952.\" -> ''Kents Cavern is a cave system in Torquay, Devon, England [1]. It is notable both for its archaeological and geological features [1]. Handaxes found in the \"Breccia\" layer of the cavern indicate that the area in the vicinity of the cave system was occupied during the Acheulean period of the Lower Paleolithic, no later than Marine Isotope Stage 12 (~478-424,000 years ago) [1]. Mousterian stone tools found in the cavern during excavations in the 19th century indicate that the cave was later occupied by Neanderthals during the late Middle Paleolithic (likely sometime roughly around 60-40,000 years ago) [1]. A prehistoric upper jawbone fragment of a modern human was discovered in the cavern during a 1927 excavation by the Torquay Natural History Society and named Kents Cavern 4 [1]. The cave was where the holotype canine teeth of the sabertooth cat Homotherium latidens were collected by John MacEnery in 1826, and formally described by Richard Owen in 1846 [1].''"}, {"source": "remediation_change_log:104192", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:104193", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-500000'' -> None"}, {"source": "remediation_change_log:156017", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''/data/images/wiki/931ddb0f/hero.webp'' -> ''/data/images/wiki/931ddb0f/Kents Cavern (6990).webp''"}, {"source": "remediation_change_log:302163", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:302164", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-2580000''"}]'::jsonb),
