    ('93370dfd-9467-4c8b-9dc7-dca5faa812ac'::uuid, 'antiquity', '5', '7', 'card-stats-2026-11-05-rollback:93370dfd-9467-4c8b-9dc7-dca5faa812ac:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Jasov Cave', '6793fba39a388e0d1f12510adcbf2745', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36869", "url": "remediation_change_log", "quote": "phase4:p4-0045:chunk-0001: description ''Jasov Cave (Jasovska jaskyna) is a limestone cave and archaeological site in the Slovak Karst, about 25 km from Kosice. Listed as a UNESCO World Heritage Site within the Caves of Aggtelek Karst and Slovak Karst, it features exceptional dripstone formations including pagoda-shaped stalagmites and sinter waterfalls. The cave was settled during the Neolithic (Bukk-Mountain Culture), Bronze Age, and Hallstatt periods, with Paleolithic artifacts also found. Bones of cave bear and cave hyena were discovered, making it an important paleontological site, while 19 bat species hibernate there today.'' -> ''Jasov Cave is a speleothem limestone cave and archaeological site in the Slovak Karst in Slovakia [1]. It is located near the village of Jasov, around 25 km from Košice city [1]. Along with a number of caves of the Slovak Karst, Jasov Cave has been added to the UNESCO World Heritage list as a part of the Caves of Aggtelek Karst and Slovak Karst site [1]. The cave is known for its pagoda-like stalagmites, sinter waterfalls, and straw stalactites [1]. Many archaeological discoveries of the Paleolithic, Neolith and the Hallstatt periods have been made in the cave [1].''"}, {"source": "remediation_change_log:104194", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:104195", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:156020", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''/data/images/wiki/93370dfd/hero.webp'' -> ''/data/images/wiki/93370dfd/JasovskaJaskyna2.webp''"}, {"source": "remediation_change_log:251093", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:251094", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-3000''"}, {"source": "remediation_change_log:350908", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''3000 - 1500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:350909", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-3000'' -> None"}]'::jsonb),
