    ('936b5a30-e1dd-4524-95c2-e7214ecf3090'::uuid, 'mystery', '2', '6', 'card-stats-2026-11-05-rollback:936b5a30-e1dd-4524-95c2-e7214ecf3090:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Archaeological Site of Grand', 'cd0874cd382ad4d28bc1750614f040e1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 2 from (''City/town/settlement'', ''1 - 500 AD'') is shared by 180 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44823", "url": "remediation_change_log", "quote": "phase4:p4-0100:chunk-0001: description \"Gallo-Roman sanctuary of Apollo Grannus, the healing god, in the Vosges department of northeastern France, identified with Andesina on the Peutinger Table. Its 1st-century amphitheatre seated 17,000 spectators, making it one of the largest in the Roman Empire. A 232-square-metre floor mosaic from an ancient basilica depicts four wild animals around a central theatrical scene from Menander''s Phasma. The town was enclosed by a rampart and developed as a major pilgrimage centre for healing rituals dedicated to Apollo Grannus.\" -> ''The archaeological site of Grand contains a wide amphitheater and a mosaic of 232 m2 [1]. It is located in the French department of Vosges, in the region Grand Est, in France [1]. It was an ancient Gallo-Roman city named Andésina (15,000-20,000 inhabitants) [1]. The amphitheater was built at the end of the 1st century and can contain 17,000 people [1]. At its center, the mosaic shows a theater scene of the Phasma of Menander and four animals at the four corners [1].''"}, {"source": "remediation_change_log:104196", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:104197", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''1'' -> None"}, {"source": "remediation_change_log:104198", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: site_type ''Megalithic structures'' -> ''City''"}, {"source": "remediation_change_log:156045", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''/data/images/wiki/936b5a30/hero.webp'' -> \"/data/images/wiki/936b5a30/Vue_générale_de_l''amphithéâtre.webp\""}, {"source": "remediation_change_log:240638", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:240639", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''1''"}, {"source": "remediation_change_log:355922", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
