source": "remediation_change_log:104196", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:104197", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''1'' -> None"}, {"source": "remediation_change_log:104198", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: site_type ''Megalithic structures'' -> ''City''"}, {"source": "remediation_change_log:156045", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''/data/images/wiki/936b5a30/hero.webp'' -> \"/data/images/wiki/936b5a30/Vue_générale_de_l''amphithéâtre.webp\""}, {"source": "remediation_change_log:240638", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:240639", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''1''"}, {"source": "remediation_change_log:355922", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
    ('93a36090-1dd8-43e4-8da1-79782cb01b96'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:93a36090-1dd8-43e4-8da1-79782cb01b96:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Kealkill Stone Circle', '1567db084e3b9de3e1e49c41fc68d5bc', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86106", "url": "remediation_change_log", "quote": "phase4:p4-2133:chunk-0001: description ''Kealkill Stone Circle is a Bronze Age axial five-stone circle in County Cork, southwest Ireland [1]. Excavated in 1938, the circle originally was thought to align north, atypical for Irish stone circles which generally face southwest [1]. Later research suggests the less prominent southwestern stone is actually the axial stone [1]. Two associated standing stones stand nearby, one re-erected after falling [1].'' -> ''Kealkill stone circle is a Bronze Age axial five-stone circle located just outside the village of Kealkill, County Cork in southwest Ireland [1]. Kealkill is an example of the type of stone circle commonly found in counties Cork and Kerry [1]. The stones are positioned in a somewhat elliptical shape, about 2.8 by 2.4 metres, and there are two tall upright standing stones and a ring cairn nearby [1]. Five metres to the northeast the two tall standing stones, menhirs, are 1.6 metres apart [1]. Excavation of the cairn showed that there had originally been 18 radially-orientated kerb stones in a ring that was somewhat smaller than the 7.6-metre diameter of the cairn [1]. Nothing was found helpful for dating purposes and there were no signs of burial within the circle or the cairn [1].''"}, {"source": "remediation_change_log:104199", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:104200", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:251097", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251098", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-4000''"}, {"source": "remediation_change_log:350910", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:350911", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
    ('93a36090-1dd8-43e4-8da1-79782cb01b96'::uuid, 'total_power', '28', '29', 'card-stats-2026-11-05-rollback:93a36090-1dd8-43e4-8da1-79782cb01b96:total_power', 'rollback of card-stats-2026-11-05: total_power ''29'' restored on Kealkill Stone Circle', '1567db084e3b9de3e1e49c41fc68d5bc', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 28 from antiquity + fortification + cultural_influence + mystery + legacy = 7 + 8 + 8 + 4 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86106", "url": "remediation_change_log", "quote": "phase4:p4-2133:chunk-0001: description ''Kealkill Stone Circle is a Bronze Age axial five-stone circle in County Cork, southwest Ireland [1]. Excavated in 1938, the circle originally was thought to align north, atypical for Irish stone circles which generally face southwest [1]. Later research suggests the less prominent southwestern stone is actually the axial stone [1]. Two associated standing stones stand nearby, one re-erected after falling [1].'' -> ''Kealkill stone circle is a Bronze Age axial five-stone circle located just outside the village of Kealkill, County Cork in southwest Ireland [1]. Kealkill is an example of the type of stone circle commonly found in counties Cork and Kerry [1]. The stones are positioned in a somewhat elliptical shape, about 2.8 by 2.4 metres, and there are two tall upright standing stones and a ring cairn nearby [1]. Five metres to the northeast the two tall standing stones, menhirs, are 1.6 metres apart [1]. Excavation of the cairn showed that there had originally been 18 radially-orientated kerb stones in a ring that was somewhat smaller than the 7.6-metre diameter of the cairn [1]. Nothing was found helpful for dating purposes and there were no signs of burial within the circle or the cairn [1].''"}, {"source": "remediation_change_log:104199", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:104200", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:251097", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251098", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-4000''"}, {"source": "remediation_change_log:350910", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:350911", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
    ('93f7a2e9-2d34-4ac7-bb22-9327d1897648'::uuid, 'mystery', '1', '6', 'card-stats-2026-11-05-rollback:93f7a2e9-2d34-4ac7-bb22-9327d1897648:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Prinias', 'f4b2ae54814f7c57fae25a9883c3913e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''1500 - 500 BC'') is shared by 286 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81106", "url": "remediation_change_log", "quote": "phase4:p4-2020:chunk-0001: description ''Prinias is an archaeological site in Crete that has revealed a seventh-century BCE temple with striking similarities to ancient Egyptian architecture, including an Egyptianised seated goddess [1]. It is 35 kilometres (22 mi) southwest of Iraklion, about halfway between Gortyn and Knossos [1]. Above the site is a peak sanctuary, a sub-Minoan survival [1].'' -> ''Prinias (ancient Rizinia) is an archaeological site in Crete that has revealed a seventh-century BCE temple with striking similarities to ancient Egyptian architecture, including an Egyptianised seated goddess [1]. Prinias developed at a similar time frame with Lato and Polyrrhenia as an Archaic Period settlement, colonised by Greeks from the mainland [1]. Most of the finds from Prinias (including a singular frieze of horsemen) are conserved at the Archaeological Museum at Heraklion [1].''"}, {"source": "remediation_change_log:121473", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_name ''3000 - 1500 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_