    ('940444fb-1897-4c1f-bdc2-30e967df95c8'::uuid, 'rarity_score', '35', '32', 'card-stats-2026-11-05-rollback:940444fb-1897-4c1f-bdc2-30e967df95c8:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''32'' restored on Rocha dos Namorados', 'f3d32ca042905a0b658e913c8482789b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 35 from mystery 7, cultural_influence 7"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86112", "url": "remediation_change_log", "quote": "phase4:p4-2133:chunk-0001: description ''A large mushroom-shaped granite outcrop over 2 metres high in the parish of Corval, Reguengos de Monsaraz, Evora district, Portugal. Sometimes classified as a menhir, it appears to be a natural formation bearing dimpled megalithic engravings and a later Christian cross carved to Christianise the site. Associated with fertility traditions: during droughts, pilgrimages were made from a nearby chapel, and single women throw stones onto the rock on the first Monday of Easter to divine how many years until marriage. It is one of several Neolithic megalithic sites in the Reguengos de Monsaraz area, alongside the Cromeleque do Xerez and the Menhir of Outeiro.'' -> ''The Rocha dos Namorados (Lovers’ Rock) is a large upright granite stone located in the parish of Corval, municipality of Reguengos de Monsaraz, in the Évora District of the Alentejo region of Portugal [1]. It is sometimes considered to be a menhir or standing stone but there is no evidence of it having been placed at the site and it seems to be a natural outcrop, although it does have some dimpled, megalithic engravings, as well as a cross, which is believed to have been carved in order to Christianise what was an ancient ritual [1]. It is considered a rare example of the veneration of stones associated with a secular, pagan fertility rite that has continued to the present [1]. The stone is more than two meters high, and has a shape similar to that of a mushroom, with the top having a circumference of about 7 meters [1]. The fertility rite involves girls of marriageable age consulting the rock to find out how long before they get married [1].''"}, {"source": "remediation_change_log:121476", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:121477", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:156054", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/2/2c/RochadosNamorados.jpg'' -> ''/data/images/wiki/940444fb/Menir da Rocha dos Namorados - Corval - Portugal (472182318).webp''"}, {"source": "remediation_change_log:251101", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:251102", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-10000''"}, {"source": "remediation_change_log:323383", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-002: thumbnail_url ''/data/images/wiki/940444fb/Menir da Rocha dos Namorados - Corval - Portugal (472182318).webp'' -> ''/data/images/wiki/940444fb/hero.webp''"}, {"source": "remediation_change_log:325304", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/940444fb/hero.webp'' -> ''/data/images/wiki/940444fb/RochadosNamorados.webp''"}, {"source": "r