    ('941b3241-8cc0-408b-a1be-2ee5cd8ad6f7'::uuid, 'antiquity', '10', '6', 'card-stats-2026-11-05-rollback:941b3241-8cc0-408b-a1be-2ee5cd8ad6f7:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on Kamyana Mohyla', '4db51c1738036f996dbea56e98d0ce36', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -10000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43567", "url": "remediation_change_log", "quote": "phase4:p4-0076:chunk-0001: description \"Kamyana Mohyla is an archaeological site in the Molochna River valley, about 1.6 km from Terpinnia village in Zaporizhzhia Oblast, Ukraine[1]. The site features petroglyphs spanning from the Upper Paleolithic to the Medieval period, with Stone Age depictions being of greatest archaeological interest[1]. It comprises a group of isolated sandstone blocks forming a natural monument[1]. Kamyana Mohyla is listed on Ukraine''s Tentative List of World Heritage Sites[1].\" -> ''Kamyana Mohyla is an archaeological site in the Molochna River valley, about a mile from the village of Terpinnia, Zaporizhzhia Oblast, Ukraine [1]. The site encompasses a group of isolated blocks of sandstone, up to twelve meters in height, scattered around an area of some 3,000 sq m [1]. Petroglyphs are found only inside the caves and grottoes of Kamyana Mohyla, many of them still filled up with sand [1]. Faint traces of red paint remain on parts of the surface [1]. In 1889, the Russian archaeologist Nikolay Veselovsky was called upon to explore the enigmatic site and started excavations the following year [1]. As soon as he concluded that the site was a burial mound, excavations were terminated [1]. In the 1930s, the site was investigated by a team of scholars from Melitopol under Valentin Danylenko [1].''"}, {"source": "remediation_change_log:104203", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:104204", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:156059", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''/data/images/wiki/941b3241/hero.webp'' -> \"/data/images/wiki/941b3241/Кам''яна_Могила_поблизу_Мелітополя_смт_Мирне_у_Запорізькій_області.webp\""}, {"source": "remediation_change_log:240640", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:240641", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-2000''"}, {"source": "remediation_change_log:314044", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url \"/data/images/wiki/941b3241/Кам''яна_Могила_поблизу_Мелітополя_смт_Мирне_у_Запорізькій_області.webp\" -> ''/data/images/wiki/941b3241/Kamenna2.webp''"}, {"source": "remediation_change_log:350914", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''3000 - 1500 BC'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:350915", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-2000'' -> ''-10000''"}]'::jsonb),
