    ('944099e9-5dfb-435f-a1a2-0c87eb4660be'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:944099e9-5dfb-435f-a1a2-0c87eb4660be:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Troldkirken', '66d1e19d37f3ad497c99f49afa5ad5cf', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44827", "url": "remediation_change_log", "quote": "phase4:p4-0100:chunk-0001: description ''Troldkirken (\"Church of the Troll\") is a Neolithic long barrow near Nibe, Denmark, constructed by the Funnelbeaker culture around 3500 BC. The monument stretches nearly 50 metres long and 12 metres wide, encircled by 47 large megaliths with a polygonal dolmen chamber topped by a capstone weighing approximately 7,000 kilograms. It became a protected site in 1809, making it one of the first prehistoric monuments officially preserved by the Danish government. The site offers panoramic views over the Limfjorden.'' -> ''Troldkirken is a Stone Age long barrow in the village of Nibe, Denmark [1]. The barrow was constructed by the Funnelbeaker culture around 3500 BC and is marked out by 47 megaliths [1]. Placed on the top of the barrow is a polygonal chambered dolmen with a large capstone [1]. The whole monument is some 50 metres long [1]. The name \"Troldkirken\" means both Church of the Troll and Church of Sorcery in Danish [1].''"}, {"source": "remediation_change_log:121483", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: site_type ''Necropolis/tombs complex'' -> ''Barrow''"}, {"source": "remediation_change_log:156065", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/4/4b/Troldkirken_07_ies.jpg'' -> ''/data/images/wiki/944099e9/Dyssekammeret på Troldkirken.webp''"}, {"source": "remediation_change_log:314047", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/944099e9/Dyssekammeret på Troldkirken.webp'' -> ''/data/images/wiki/944099e9/Troldkirken_07_ies.webp''"}]'::jsonb),
