    ('94cf34a3-2cf8-41e9-adf3-80c288b4f972'::uuid, 'antiquity', '7', '5', 'card-stats-2026-11-05-rollback:94cf34a3-2cf8-41e9-adf3-80c288b4f972:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Aston Valley Barrow Cemetery', '18644420675e23b3e04004940b38ad10', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86138", "url": "remediation_change_log", "quote": "phase4:p4-2134:chunk-0001: description ''Bronze Age barrow group on the south-facing edge of Codford Down, Wiltshire, England, dating to roughly 3300-800 BC. Originally comprising ten bowl barrows and one bell barrow, only five bowl barrows and the bell barrow survive; the rest were ploughed out. First excavated by W.F. Cunnington in 1801 and recorded by Sir R. Colt Hoare, revealing cremation burials. The site is a scheduled monument, situated near the Iron Age hillforts of Codford Circle and Knook Castle.'' -> ''The Aston Valley Barrow Cemetery, or Ashton Valley Barrow Cemetery, is a group of Bronze Age bowl barrow and bell barrow tumuli on the south facing edge of Codford Down on the west side of the valley of the Chitterne Brook, within the civil parish of Codford, in Wiltshire [1]. There were originally ten bowl barrows and a single bell barrow, but some of these have now been ploughed out: only the bell barrow and five bowl barrows survive [1]. The site lies in close proximity to Codford Circle, an Iron Age hillfort or enclosure some 2 km to the southeast, and Knook Castle, an Iron Age hillfort a similar distance to the northwest [1]. Excavations at the barrows have revealed many Bronze Age and some possible Saxon urned cremations and other interments [1]. The barrows were originally excavated by W.F. Cunnington in 1801, and recorded by Sir R. Colt-Hoare, with later excavations by the Reverend E.H. Steele in 1957; and with further correlations by Leslie Grinsell [1]. Some burials and items were left in place by Cunnington, but others are now preserved at the Wiltshire Museum in Devizes [1].''"}, {"source": "remediation_change_log:104219", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:104220", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:251113", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:251114", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-800''"}, {"source": "remediation_change_log:350924", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1500 - 500 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:350925", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-800'' -> ''-2500''"}]'::jsonb),
