    ('96395824-9c31-477a-bf51-13ecb5035d56'::uuid, 'antiquity', '4', '5', 'card-stats-2026-11-05-rollback:96395824-9c31-477a-bf51-13ecb5035d56:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Pintia', 'c46c624c5b81bc349959bbdeb1a285fa', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 4 from period_start -500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86172", "url": "remediation_change_log", "quote": "phase4:p4-2135:chunk-0001: description ''Pintia is the remains of an ancient Vaccaei city near Padilla de Duero in the province of Valladolid, central Spain, founded approximately 2,400 years ago by Celtic peoples. The archaeological complex comprises three areas: the city of Las Quintanas, the necropolis of Las Ruedas with over 300 excavated tombs, and the artisan quarter of Carralaceña featuring the largest kiln in Europe. Occupation spans from the Bronze Age through Visigothic times, with peak activity during the Iron Age and Roman periods. The University of Valladolid has systematically excavated the site for over three decades, uncovering thousands of ceramics, weapons, and glass beads that reveal a sophisticated agrarian society.'' -> \"Pintia was besieged and destroyed by the Romans, which also buried forever the Vaccean culture, religion, and language [1]. The archaeological excavations conducted in Padilla de Duero uncovered an important settlement that has been interpreted as its possible location [1]. The Archaeological Zone consists of three different parts: the city of Las Quintanas, the necropolis of Las Ruedas, and the potter''s district of Carralaceña [1].\""}, {"source": "remediation_change_log:104232", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:104233", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-500'' -> None"}, {"source": "remediation_change_log:156125", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/7/71/Necr%C3%B3polis_de_Las_Ruedas.jpg'' -> ''/data/images/wiki/96395824/Pintia.webp''"}, {"source": "remediation_change_log:302165", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:302166", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-600''"}, {"source": "remediation_change_log:323409", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-002: thumbnail_url ''/data/images/wiki/96395824/Pintia.webp'' -> ''/data/images/wiki/96395824/hero.webp''"}, {"source": "remediation_change_log:325308", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/96395824/hero.webp'' -> ''/data/images/wiki/96395824/Necrópolis de Las Ruedas.webp''"}, {"source": "remediation_change_log:357267", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s006: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:357268", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s006: period_start ''-600'' -> ''-500''"}]'::jsonb),
