    ('96938167-cc5f-44fa-b3fd-2ab39fad89a7'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:96938167-cc5f-44fa-b3fd-2ab39fad89a7:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Grey Wethers', '6df3f1ee3af3af6e47784d4c67f3e0db', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36909", "url": "remediation_change_log", "quote": "phase4:p4-0046:chunk-0001: description ''Grey Wethers is the only double stone circle on Dartmoor and stands at the highest altitude of all Dartmoor circles, on a grassy plateau north of Postbridge. The northern circle measures 31.5m across with 20 stones, while the southern is 33m with 29 stones, separated by just 4.5m and aligned almost exactly north-south. Named because from a distance the stones resemble flocks of grey sheep (wethers), the circles date to the later Neolithic or Bronze Age. Excavation in the late 19th century revealed charcoal fragments, and in 1909 many fallen stones were re-erected, though some were placed in wrong positions.'' -> ''Grey Wethers consists of a pair of prehistoric stone circles, situated on grassy plateau to the north of Postbridge, Dartmoor [1]. The circles are each approximately 33 m in diameter, and less than five metres apart [1]. Their centre points are aligned almost exactly north to south [1]. The northern circle has 20 stones remaining, while the southern has 29 – all of a relatively consistent size, mostly between 1.2 and 1.4 m in height [1]. An excavation was carried out in 1898 and a number of charcoal fragments were discovered within the circles [1]. The circles were restored and many fallen stones re-erected in 1909 [1].''"}, {"source": "remediation_change_log:104238", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:104239", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:156131", "url": "remediation_change_log", "quote": "served-image-2026-09-30-020: thumbnail_url ''/data/images/wiki/96938167/hero.webp'' -> ''/data/images/wiki/96938167/Grey_Wethers_stone_circle_in_the_snow_on_Dartmoor.webp''"}, {"source": "remediation_change_log:251121", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251122", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-4000''"}, {"source": "remediation_change_log:314095", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-009: thumbnail_url ''/data/images/wiki/96938167/Grey_Wethers_stone_circle_in_the_snow_on_Dartmoor.webp'' -> ''/data/images/wiki/96938167/Grey Wethers 14(1).webp''"}, {"source": "remediation_change_log:350930", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:350931", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
