    ('9737ca03-ad30-46d2-8740-3dec20bed1ea'::uuid, 'antiquity', '8', '3', 'card-stats-2026-11-05-rollback:9737ca03-ad30-46d2-8740-3dec20bed1ea:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Grakliani Hill', 'ff6a1e14645f43e4e6417c4ca597c812', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -4500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27264", "url": "remediation_change_log", "quote": "2026-09-21_mechanical-country: country ''Georgia (country)'' -> ''Georgia''"}, {"source": "remediation_change_log:36911", "url": "remediation_change_log", "quote": "phase4:p4-0046:chunk-0001: description ''Grakliani Hill is a 7th-century BC temple complex in eastern Georgia near Kaspi, featuring a fertility goddess shrine with a disputed inscription that may predate other known regional scripts by over a millennium. Excavations revealed human presence potentially spanning 300,000 years [1].'' -> \"Grakliani Hill is an archaeological excavation site in eastern Georgia near Kaspi, showing evidence of human presence possibly going back 300,000 years [1]. The site was discovered in 2007, during work to widen the Tbilisi-Senaki-Leselidze highway [1]. The site contains a temple to a fertility goddess from the seventh century BCE, a pit-type burial cemetery from the early Bronze Age, and the remains of a building from around 450-350 BCE; the building consists of three rooms with three storage rooms [1]. The site had been occupied between the Chalcolithic and the Late Hellenistic periods [1]. The excavation of layers yielded artifacts including children''s toys, weapons, icons, and pharmacological devices [1]. Within the first two months of digging, archaeologists had excavated over 35,000 pieces from hundreds of graves and ruins of settlements that date back to the eighth century BCE [1].\""}, {"source": "remediation_change_log:104246", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:104247", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:156681", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''/data/images/wiki/9737ca03/hero.webp'' -> ''/data/images/wiki/9737ca03/Grakliani Gora archaeological site, Kaspi Municipality, Georgia 11.webp''"}, {"source": "remediation_change_log:251127", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:251128", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''43''"}, {"source": "remediation_change_log:334618", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/9737ca03/Grakliani Gora archaeological site, Kaspi Municipality, Georgia 11.webp'' -> ''/data/images/wiki/9737ca03/Grakliani_Script_(IX-X_century_B.D.).webp''"}, {"source": "remediation_change_log:357269", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s006: period_name ''1 - 500 AD'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:357270", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s006: period_start ''43'' -> ''-4500''"}]'::jsonb),
