    ('97eeca75-a0d6-4365-a610-c3b5044a3043'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:97eeca75-a0d6-4365-a610-c3b5044a3043:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Barreira Megalithic Complex', '08416fb6a2a0c1d72f02886e65351465', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Megalithic stones'', ''4500 - 3000 BC'') is shared by 17 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86224", "url": "remediation_change_log", "quote": "phase4:p4-2136:chunk-0001: description ''The Barreira Megalithic Complex is a prehistoric site in the Sintra municipality, Lisbon District, Portugal, situated on a wooded hill overlooking the village of Odrinhas. It consists of about twenty menhirs and other megaliths arranged around a central stone, with the tallest reaching approximately 4 metres. The site was not identified as megalithic until 1961. Finds include Lower Paleolithic flints, Neolithic ceramics, and Iron Age pottery fragments. Unfortunately, several monoliths were removed in 1975 for port construction at Ericeira, and three more were taken in 1985, including the central menhir. The complex was classified as a Site of Public Interest in 1993.'' -> ''The Barreira Megalithic Complex is located in the Sintra municipality in the Lisbon District of Portugal [1]. Situated on a small wooded hill overlooking the village of Odrinhas, site of Roman ruins and an archaeological museum, it consists of about twenty menhirs and other monoliths or megaliths [1]. The site, which is assumed to be a dolmen or cromlech, contains mainly cylindrical stones of varying heights, with the largest being approximately four metres tall [1]. No carved or painted symbols have been detected, except for a few pairs of small circular cavities, possibly representing eyes [1]. A small number of items have been found to the west of the complex, including flints from the Lower Paleolithic, ceramic fragments and other items from the Neolithic period, and ceramic fragments from the Iron Age, suggesting that the site has been reused over time [1]. The complex was not identified as a megalithic site until 1961 when it was studied by Gil Estevam Miguéis Andrade and Eduardo Prescott Vicente [1].''"}, {"source": "remediation_change_log:104255", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:104256", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:156700", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''/data/images/wiki/97eeca75/hero.webp'' -> ''/data/images/wiki/97eeca75/ConjuntoBarreira2.webp''"}, {"source": "remediation_change_log:251131", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251132", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s013: period_start None -> ''-4000''"}]'::jsonb),
