    ('99115b5a-460c-41e5-98f0-be47a7235402'::uuid, 'mystery', '6', '4', 'card-stats-2026-11-05-rollback:99115b5a-460c-41e5-98f0-be47a7235402:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Utroba Cave', '2717c028e6ba8958b618003058f4efdb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Cave Structures'', ''500 BC - 1 AD'') is shared by 19 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36919", "url": "remediation_change_log", "quote": "phase4:p4-0046:chunk-0001: description ''The Utroba Cave, also known as Womb Cave, is an ancient Thracian cave sanctuary located in the Eastern Rhodope Mountains of Bulgaria near the village of Ilinitsa, approximately 20 km from Kardzhali [1]. The cave\\''s natural entrance closely resembles a human vulva, giving it the name \"Womb Cave\" [1]. Dating to around 480 BC during the Thracian period, archaeologists believe the cave functioned as a fertility shrine, likely used in ancient religious rituals related to worship of fertility and reproduction [1]. The interior features carved stone pillars and niches, though much of the original ceremonial equipment has not survived [1].'' -> ''The Utroba Cave, also known as Womb Cave, is an ancient cave sanctuary in Kardzhali Province [1]. Located in the Eastern Rhodope Mountains near the Ilinitsa village, the cave resembles a human vulva and dates to the Thracian period [1]. Historians believe that it was once used as a fertility shrine [1]. The cave is located 20 kilometers from the city of Kardzhali near the village of Ilinitsa and it dates to 480 BC [1]. The inside of the cave resembles a uterus [1]. Researchers believe that the entrance to the cave was a slit, which was then widened by humans [1]. The entrance to the cave is 3 metres tall and 2.50 m wide and inside the cave there is a 1.3 m-tall altar which has been carved [1].''"}, {"source": "remediation_change_log:104270", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:104271", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-500'' -> None"}, {"source": "remediation_change_log:156725", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/9e/Womb_Cave_TanKaya_BG.jpg'' -> ''/data/images/wiki/99115b5a/Utrobat nenkovo entrance.webp''"}, {"source": "remediation_change_log:240676", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:240677", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-480''"}, {"source": "remediation_change_log:334627", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/99115b5a/Utrobat nenkovo entrance.webp'' -> ''/data/images/wiki/99115b5a/hero.webp''"}]'::jsonb),
