ource": "remediation_change_log:251470", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''1''"}, {"source": "remediation_change_log:350942", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350943", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''1'' -> None"}]'::jsonb),
    ('9aab078b-ef81-43a1-8169-235e5b22dd34'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:9aab078b-ef81-43a1-8169-235e5b22dd34:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Longyou Grottoes', '8bb6841e69794ba70685babba3e64f8b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86300", "url": "remediation_change_log", "quote": "phase4:p4-2138:chunk-0001: description ''A complex of 24 artificial sandstone caverns carved into Fenghuang Hill near Shiyan Beicun village in Zhejiang Province, China, covering approximately 30,000 square metres. Discovered in 1992 when local villagers drained ponds they believed bottomless, each grotto descends about 30 m underground. Every surface is adorned with uniform parallel chisel marks, and an estimated one million cubic metres of rock were removed during construction. Glazed clay pots found on the cavern floor date to the Western Han Dynasty (206 BC - 23 AD), but no historical records mention their construction, leaving their origin and purpose a profound archaeological mystery.'' -> ''The Longyou Caves, also called the Xiaonanhai Stone Chambers, are a group of 24 artificial sandstone caverns located at Fenghuang Hill, near the village of Shiyan Beicun on the Qu River in Longyou County, Quzhou City, Zhejiang Province [1]. In June 1992, four farmers in Longyou found the caves when they drained the water of five small ponds in their village [1]. The ponds turned out to be five large manmade caverns [1]. Further investigation revealed 19 more caverns nearby [1]. The caves are very large for human-made excavations: The average floor area of each cave is over 1,000 m2, with ceiling heights of up to 30 m, and the total area covered in excess of 30,000 m2 [1].''"}, {"source": "remediation_change_log:104301", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:104302", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-500'' -> None"}, {"source": "remediation_change_log:156774", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''/data/images/wiki/9aab078b/hero.webp'' -> ''/data/images/wiki/9aab078b/Longyou Xiaonanhai Shishi 2016.12.11 16-07-21.webp''"}, {"source": "remediation_change_log:251471", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:251472", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-500''"}, {"source": "remediation_change_log:332736", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-006-002: thumbnail_url ''/data/images/wiki/9aab078b/Longyou Xiaonanhai Shishi 2016.12.11 16-07-21.webp'' -> ''/data/images/wiki/9aab078b/Longyou Xiaonanhai Shishi 2016.12.11 16-10-51.webp''"}, {"source": "remediation_change_log:350944", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350945", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-500'' -> None"}]'::jsonb),
