    ('9ab9a6fa-2a4d-47db-8db4-237820a577d2'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:9ab9a6fa-2a4d-47db-8db4-237820a577d2:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Aigeira', '3e1aa5e35681ec94421eabb80527eac5', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''< 4500 BC'') is shared by 105 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29113", "url": "remediation_change_log", "quote": "phase3:batch-0240:chunk-0001: period_start ''-4500'' -> ''-5500''"}, {"source": "remediation_change_log:30459", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''4500 - 3000 BC'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:36925", "url": "remediation_change_log", "quote": "phase4:p4-0046:chunk-0001: description ''Aigeira is an archaeological site in northeastern Achaea, West Greece, located on the Gulf of Corinth[1]. The settlement dates to 4500-3000 BC during the Early Helladic period, making it one of the prehistoric centers in eastern Achaea[2]. The Austrian Archaeological Institute has conducted excavations at the site, uncovering significant remains from this Bronze Age settlement[3]. Later, during the Late Geometric period, the location became a sanctuary[2]. The modern municipal unit spans from the coastal town to the mountains in the south, covering 103.646 km²[1].'' -> ''The archaeological site of ancient Aigeira is located approximately 6 km from the modern town [1]. It is an important site for the Mycenaean and later periods, with particularly extensive remains from the Hellenistic period [1]. Settlement at Aigeira is known from the Middle Neolithic and Final Neolithic, beginning around 5500 BCE [1]. The first settlement was situated on the acropolis, and has furnished evidence of pottery, including vessels likely used in the production of cheese [1]. Some evidence of Neolithic settlement has been found on a lower plateau, approximately 150m to the east of the acropolis [1]. Like many Aegean sites, Aigeira was abandoned at the end of the Bronze Age, following the destruction of the site at the end of LH IIIC Middle [1]. Occupation began again in the second half of the 8th century BCE, likely associated with the sanctuary at the site [1]. Some partial fortifications are known from the Archaic period, covering an area of around 3.5 hectares [1].''"}, {"source": "remediation_change_log:104305", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:104306", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-5500'' -> None"}, {"source": "remediation_change_log:156777", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''/data/images/wiki/9ab9a6fa/hero.webp'' -> ''/data/images/wiki/9ab9a6fa/Aigeira2.webp''"}, {"source": "remediation_change_log:240690", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:240691", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-5500''"}]'::jsonb),
