    ('9b3bade9-0410-4e3d-8c00-89cdc1b776ed'::uuid, 'antiquity', '8', '5', 'card-stats-2026-11-05-rollback:9b3bade9-0410-4e3d-8c00-89cdc1b776ed:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Buzbury Rings', '0ab3d977c559e0913facd87f242099f8', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -4000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86308", "url": "remediation_change_log", "quote": "phase4:p4-2138:chunk-0001: description ''Buzbury Rings is an Iron Age hillfort about 3.2 km east of Blandford Forum in Dorset, England, designated as a Scheduled Ancient Monument. It comprises a kidney-shaped outer enclosure of roughly 4.9 hectares and a non-concentric inner enclosure of about 1 hectare bounded by a single bank. Geophysical and lidar surveys from 2006 suggest the earliest remains are a Neolithic causewayed enclosure, indicating continuous use across millennia. Objects from the Iron Age through the late Roman period have been found, mostly within the inner enclosure where circular depressions mark probable building sites. The rings form part of a chain of Dorset hillforts stretching from Hambledon Hill to Dudsbury Camp.'' -> ''Buzbury Rings is an Iron Age hillfort about 2 miles east of Blandford Forum and 1 mile northwest of the village of Tarrant Keyneston, in Dorset [1]. The site is on a hill on Keynston Down [1]. There is an inner enclosure, area about 3 acres, bounded by a single bank of width 30 feet and height 4 feet [1]. Surrounding this is an outer enclosure, not concentric with the inner enclosure, of area about 10 acres [1]. It is bounded in the north and west by a single bank, width 20 feet and height 3 feet; an outer ditch, now buried, has been revealed by partial excavation [1]. In the south there is a double bank; the banks are up to 24 feet wide, and the ditch between is about 10 feet wide [1]. There are traces of additional earthworks to the south [1].''"}, {"source": "remediation_change_log:104327", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:104328", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:251481", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:251482", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-800''"}, {"source": "remediation_change_log:314785", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url ''/data/images/wiki/9b3bade9/hero.webp'' -> ''/data/images/wiki/9b3bade9/Buzbury Rings (geograph 3293909).webp''"}, {"source": "remediation_change_log:350954", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1500 - 500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:350955", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-800'' -> ''-4000''"}]'::jsonb),
