    ('9b639757-cc79-496b-9748-69594f98c109'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:9b639757-cc79-496b-9748-69594f98c109:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Lascaux', 'c7a20c35693bb7973be5f496dae5c98c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28797", "url": "remediation_change_log", "quote": "phase3:batch-0195:chunk-0001: period_start ''-500'' -> ''-22000''"}, {"source": "remediation_change_log:30461", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:43597", "url": "remediation_change_log", "quote": "phase4:p4-0077:chunk-0001: description ''Lascaux is a network of caves near Montignac in the Dordogne, southwestern France, containing approximately 600 paintings and 1,400 engravings dating to c. 17,000-15,000 BCE. Discovered in 1940 by four teenagers, the cave features depictions of horses, deer, aurochs, bison, ibex, and felines painted using mineral pigments applied with moss, hair, or blown through tubes. The Hall of the Bulls contains monumental animal figures. Closed to the public in 1963 to prevent deterioration, it was inscribed as a UNESCO World Heritage Site in 1979 as part of the Vezere Valley prehistoric sites.'' -> ''Lascaux is a network of caves near the village of Montignac, in the department of Dordogne in southwestern France [1]. Over 600 parietal wall paintings cover the interior walls and ceilings of the cave [1]. The paintings represent primarily large animals, typical local contemporary fauna that correspond with the fossil record of the Upper Paleolithic in the area [1]. They are the combined effort of many generations [1]. With continued debate, the age of the paintings is now usually estimated at 17,000 to 22,000 years [1]. On 12 September 1940, the entrance to the Lascaux Cave was discovered on the La Rochefoucauld-Montbel lands by 18-year-old Marcel Ravidat when his dog investigated a hole left by an uprooted tree [1]. The cave contains nearly 6,000 figures, which can be grouped into three main categories: animals, human figures, and abstract signs [1].''"}, {"source": "remediation_change_log:104331", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:104332", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-22000'' -> None"}, {"source": "remediation_change_log:156846", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''/data/images/wiki/9b639757/hero.webp'' -> ''/data/images/wiki/9b639757/Lascaux_II.webp''"}, {"source": "remediation_change_log:240701", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:240702", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-17000''"}, {"source": "remediation_change_log:314800", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url ''/data/images/wiki/9b639757/Lascaux_II.webp'' -> ''/data/images/wiki/9b639757/Lascaux,_Megaloceros.webp''"}]'::jsonb),
