    ('9ba07ea3-0efb-41eb-a65d-e7c5d4c2fe2d'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:9ba07ea3-0efb-41eb-a65d-e7c5d4c2fe2d:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Twmbarlwm', '044c2d90e1cf11faf90c0711e8e98520', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -800"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36953", "url": "remediation_change_log", "quote": "phase4:p4-0047:chunk-0001: description ''Twmbarlwm is an Iron Age hillfort (c. 1500–500 BC) in South Wales, rising 419 metres (1,375 ft) above the M4 corridor near Risca. [1] The ancient earthworks command panoramic views over Newport, Cwmbran and the Bristol Channel. [1] Locally known as \"the Twmp\" (the hump), the Nipple or the Pimple after its prominent summit mound, it remains a well-known landmark in the region. [1]'' -> ''Twmbarlwm, also known as Twm Barlwm, Twyn Barlwm or locally known as \"the Twmp\", the Nipple or the Pimple because of the mound that lies at its summit, is a hill situated 2 km to the northeast of Risca in South Wales [1]. It is 419 m high and is a well-known landmark throughout the region [1]. At the top of the hill, near its summit, are the remains of what is presumed to be an Iron Age hillfort, believed to have been built by the Silures, the Celtic tribe that inhabited the area before and during Roman times [1]. These remains have led the local people of Risca and Cwmcarn to call it \"The Tump\" [1]. There was also thereafter possibly a Roman signal point and a substantial Norman motte-and-bailey castle which is incorporated into the eastern end of the fort, probably of early Norman construction [1].''"}, {"source": "remediation_change_log:104337", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:104338", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:156851", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Twmbarlwm_Hill_Fort_-_geograph.org.uk_-_88185.jpg/400px-Twmbarlwm_Hill_Fort_-_geograph.org.uk_-_88185.jpg'' -> ''/data/images/wiki/9ba07ea3/Twmbarlwm 423340.webp''"}, {"source": "remediation_change_log:240705", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:240706", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-500''"}, {"source": "remediation_change_log:350960", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''500 BC - 1 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:350961", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-500'' -> ''-800''"}]'::jsonb),
