    ('9bae60a8-363b-4c0a-a470-87836fcc9158'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:9bae60a8-363b-4c0a-a470-87836fcc9158:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Maroulas, Kythnos', 'ef7d19a784e9087afb71eebb6448ea3c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''< 4500 BC'') is shared by 105 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28436", "url": "remediation_change_log", "quote": "phase3:batch-0132:chunk-0001: period_start ''-9000'' -> ''-8800''"}, {"source": "remediation_change_log:35909", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-8800'' -> ''-9000''"}, {"source": "remediation_change_log:86328", "url": "remediation_change_log", "quote": "phase4:p4-2139:chunk-0001: description ''Maroulas is a Mesolithic settlement on Kythnos, Greece, dating to 8800–8600 BC, making it the oldest settlement in the Aegean island region[1]. The site was identified as pre-Neolithic in 1975, though this interpretation remained contested until excavation began in 1995[1]. Excavations from 2001–2005 by the University of the Aegean and the 21st Ephorate of the Cyclades uncovered architectural structures, tombs, stone tools, and food residues from fauna and flora[1]. The settlement appears to have been used for a few centuries at the beginning of the 9th millennium BC[1].'' -> ''Maroulas is an archaeological site in Kythnos, Greece [1]. It is a Mesolithic settlement located in Loutra and dates back to between 8800 and 8600 BC [1]. Architectural structures, tombs, stone tools and food residues of fauna and flora have been discovered at the site [1]. Maroulas is the only open area Mesolithic settlement whose architectural elements have been preserved [1]. The buildings of Maroulas were circular in shape with a diameter of 3 to 4 m [1]. The burials at Maroulas are part of a limited number of burials of the Mesolithic period in Greece, since burial practices have only been observed in caves at Franchthi in Argolida and at Theopetra in Trikala [1]. The stone tools of Maroulas were mainly made of local quartz and to a lesser extent of obsidian and flint from Milos [1].''"}, {"source": "remediation_change_log:156855", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''/data/images/wiki/9bae60a8/hero.webp'' -> ''/data/images/wiki/9bae60a8/Mesolithic site Maroulas, Kythnos, 190219.webp''"}, {"source": "remediation_change_log:314809", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url ''/data/images/wiki/9bae60a8/Mesolithic site Maroulas, Kythnos, 190219.webp'' -> ''/data/images/wiki/9bae60a8/Mesolithic_site_Maroulas,_Kythnos,_190216.webp''"}]'::jsonb),
    ('9bae60a8-363b-4c0a-a470-87836fcc9158'::uuid, 'rarity_score', '31', '34', 'card-stats-2026-11-05-rollback:9bae60a8-363b-4c0a-a470-87836fcc9158:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''34'' restored on Maroulas, Kythnos', 'ef7d19a784e9087afb71eebb6448ea3c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 31 from mystery 3, cultural_influence 10"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28436", "url": "remediation_change_log", "quote": "phase3:batch-0132:chunk-0001: period_start ''-9000'' -> ''-8800''"}, {"source": "remediation_change_log:35909", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-8800'' -> ''-9000''"}, {"source": "remediation_change_log:86328", "url": "remediation_change_log", "quote": "phase4:p4-2139:chunk-0001: description ''Maroulas is a Mesolithic settlement on Kythnos, Greece, dating to 8800–8600 BC, making it the oldest settlement in the Aegean island region[1]. The site was identified as pre-Neolithic in 1975, though this interpretation remained contested until excavation began in 1995[1]. Excavations from 2001–2005 by the University of the Aegean and the 21st Ephorate of the Cyclades uncovered architectural structures, tombs, stone tools, and food residues from fauna and flora[1]. The settlement appears to have been used for a few centuries at the beginning of the 9th millennium BC[1].'' -> ''Maroulas is an archaeological site in Kythnos, Greece [1]. It is a Mesolithic settlement located in Loutra and dates back to between 8800 and 8600 BC [1]. Architectural structures, tombs, stone tools and food residues of fauna and flora have been discovered at the site [1]. Maroulas is the only open area Mesolithic settlement whose architectural elements have been preserved [1]. The buildings of Maroulas were circular in shape with a diameter of 3 to 4 m [1]. The burials at Maroulas are part of a limited number of burials of the Mesolithic period in Greece, since burial practices have only been observed in caves at Franchthi in Argolida and at Theopetra in Trikala [1]. The stone tools of Maroulas were mainly made of local quartz and to a lesser extent of obsidian and flint from Milos [1].''"}, {"source": "remediation_change_log:156855", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''/data/images/wiki/9bae60a8/hero.webp'' -> ''/data/images/wiki/9bae60a8/Mesolithic site Maroulas, Kythnos, 190219.webp''"}, {"source": "remediation_change_log:314809", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url ''/data/images/wiki/9bae60a8/Mesolithic site Maroulas, Kythnos, 190219.webp'' -> ''/data/images/wiki/9bae60a8/Mesolithic_site_Maroulas,_Kythnos,_190216.webp''"}]'::jsonb),
