    ('9c3e1746-6da1-412c-aeb3-eb61cb3cafbb'::uuid, 'cultural_influence', '5', '3', 'card-stats-2026-11-05-rollback:9c3e1746-6da1-412c-aeb3-eb61cb3cafbb:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''3'' restored on Qalagah', 'b318524eb56cd15a729d44886524858c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 5 from description yes, thumbnail yes, 0 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36957", "url": "remediation_change_log", "quote": "phase4:p4-0047:chunk-0001: description \"Qalagah is a village in the Ismailli Rayon of Azerbaijan with an associated 1st-2nd century AD settlement covering approximately 30 hectares and an adjacent cemetery. In 1899, a silver plate 24 cm in diameter was accidentally found during excavations near the village, depicting a mounted Nereid surrounded by tritons and cupids. Scholar Kamilla Trever characterized the plate as one of the most interesting examples of Roman toreutics, highlighting Caucasian Albania''s connections with the Roman world.\" -> ''A 1st or 2nd century-related settlement with an area of ca. 30 ha and a cemetery are near Qalagah [1]. In 1899 a silver plate (24 cm in diameter) was also accidentally found during excavations near the village [1]. The plate depicts a mounted Nereid, surrounded by tritons and cupids [1]. Based on its technique and artistic characteristics, the plate is a 2nd or 3rd century example of Roman toreutics [1]. The artifact was sent to the Imperial Archaeological Commission, then to the Hermitage Museum [1].''"}, {"source": "remediation_change_log:121579", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:121580", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_start ''1'' -> None"}, {"source": "remediation_change_log:240710", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:240711", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''1''"}, {"source": "remediation_change_log:343874", "url": "remediation_change_log", "quote": "insert-2026-10-07-010-001: thumbnail_url None -> ''/data/images/wiki/9c3e1746/Qalagah kilsəsinin xarabalıqları.webp''"}]'::jsonb),
