_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:121580", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_start ''1'' -> None"}, {"source": "remediation_change_log:240710", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:240711", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''1''"}, {"source": "remediation_change_log:343874", "url": "remediation_change_log", "quote": "insert-2026-10-07-010-001: thumbnail_url None -> ''/data/images/wiki/9c3e1746/Qalagah kilsəsinin xarabalıqları.webp''"}]'::jsonb),
