    ('9cb2bfc1-76b9-4904-941d-0d3cc7f86d6a'::uuid, 'cultural_influence', '6', '4', 'card-stats-2026-11-05-rollback:9cb2bfc1-76b9-4904-941d-0d3cc7f86d6a:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''4'' restored on Rapidum', '3f00a2c501e974174d679db3fafc57d1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 6 from description yes, thumbnail yes, 0 content link(s), 2 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36961", "url": "remediation_change_log", "quote": "phase4:p4-0047:chunk-0001: description \"Rapidum was a Roman fort and settlement in Mauretania Caesariensis, established in the 1st century AD approximately 100 km south of modern Algiers [1]. Located between Castellum Tingitanum and Auzia along the Nova Praetentura road, the fortress extended Roman control into the region''s interior [2]. Under Emperor Hadrian, a civilian settlement grew adjacent to the military installation [2].\" -> ''Rapidum was a Roman settlement and fort located in Mauretania Caesariensis, nearly 100 km south of Icosium (Algiers) [1]. Soon under Hadrian near the fort grew up a civilian settlement called \"Rapidum\", on the Roman road called the Nova Praetentura [1]. The original castrum of Rapidum remained until 201 AD, while the town survived until emperor Aurelian when it was destroyed by Berber nomads [1]. The initial garrison of Rapidum fort was – according to historian M. Ruiu – the Cohors II Sardorum and protected the new limes of the Roman Empire moved south from the Mediterranean shores to a military road called Nova Praetentura [1]. This road went from Rapidum near Numidia to Altava and to Numerus Syrorum at the border of Mauretania Tingitana [1]. Rapidum was named \"municipium\" and had an extension of 15 hectares under Marcus Aurelius (with nearly 4,000 inhabitants, mostly romanised Berbers, like Auzia) [1].''"}, {"source": "remediation_change_log:121582", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: lat ''36.13340221459354'' -> ''36.136435''"}, {"source": "remediation_change_log:121583", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: lon ''3.4335242421272154'' -> ''3.421825''"}, {"source": "remediation_change_log:121584", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: site_type ''Fortress/citadel'' -> ''Fort''"}, {"source": "remediation_change_log:156901", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Karte_Römische_Städte_in_Nordafrika.svg/400px-Karte_Römische_Städte_in_Nordafrika.svg'' -> None"}, {"source": "remediation_change_log:341609", "url": "remediation_change_log", "quote": "insert-2026-10-07-006-001: thumbnail_url None -> ''/data/images/wiki/9cb2bfc1/Rapidum evolution.webp''"}]'::jsonb),
