    ('9d58f665-8cc3-4438-9dc5-99885deb90d0'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:9d58f665-8cc3-4438-9dc5-99885deb90d0:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Bruniquel Cave', '858992c846aced287dc1f47dcf9a2031', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -174550"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28545", "url": "remediation_change_log", "quote": "phase3:batch-0157:chunk-0001: period_start ''-500'' -> ''-176500''"}, {"source": "remediation_change_log:30466", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:36963", "url": "remediation_change_log", "quote": "phase4:p4-0047:chunk-0001: description ''Bruniquel Cave is an archaeological site near the town of Bruniquel in southwestern France, famous for mysterious stone circle structures built by Neanderthals around 176,500 years ago [1][2]. Located 336 metres from the cave entrance, the annular (ring) and accumulation (pile) structures were constructed from broken stalagmites, with traces of fire found nearby [1]. The discovery challenged previous assumptions about Neanderthal cognitive abilities, showing they were capable of building elaborate, purpose-built structures deep underground [2][3].'' -> ''Bruniquel Cave is an archeological site near Bruniquel, in an area which has many paleolithic sites, east of Montauban in southwestern France [1]. Annular (ring) and accumulation (pile) structures made of broken stalagmites have been found 336 metres from the cave entrance [1]. Traces of fire were also found [1]. In a letter to Nature reporting the discovery in 2016, Jacques Jaubert and his co-authors state the structures are of anthropogenic origin, and as early Neanderthals were the only humans in the area at that time, they must have been the builders [1]. Bruniquel Cave was closed naturally during the Pleistocene [1]. The artificial ring structures made of broken stalagmites now have been dated by uranium series dating as 176.5 thousand years old [1]. Approximately 400 stalagmite pieces were used in the construction of the structure, with a total length of 112.4 metres and weight of approximately 2.2 tons [1].''"}, {"source": "remediation_change_log:104366", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:104367", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-176500'' -> None"}, {"source": "remediation_change_log:251501", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:251502", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-500''"}, {"source": "remediation_change_log:325313", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/9d58f665/hero.webp'' -> ''/data/images/wiki/9d58f665/La structure de la grotte de Bruniquel.webp''"}, {"source": "remediation_change_log:350966", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:350967", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-500'' -> ''-174550''"}]'::jsonb),
