    ('9db1409d-3216-4448-b9c9-c42d5071ba4d'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:9db1409d-3216-4448-b9c9-c42d5071ba4d:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Bohonagh Stone Circle', '5e78aa33a700c667d393d8c86bc0a9b7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86346", "url": "remediation_change_log", "quote": "phase4:p4-2139:chunk-0001: description ''Bohonagh is a Bronze Age axial stone circle located east of Rosscarbery, County Cork, Ireland. Originally comprising 13 stones in a circle 9.1 metres in diameter, nine survive, with two imposing portal stones standing 2.4 metres high set radially on an east-west axis aligned to sunset at the equinoxes. A 1959 excavation revealed a central pit containing charcoal and cremated bone. Nearby stands a boulder burial with a massive capstone bearing seven or more cup-marks on its upper surface.'' -> ''Bohonagh is an axial stone circle located 2.4 km east of Rosscarbery, County Cork, Ireland [1]. The circle is thought to date from the Bronze Age [1]. The stone circle comprised 13 stones set in a circle with a diameter of 30 feet (9 m) [1]. Four out of the 13 stones are missing and three were re-erected after excavation [1]. Two portal stones are set radially on an east–west axis to the recumbent stones and are 240 centimetres (7 ft 10 in) high [1]. The axis from these stones to the large axial-stone on the west side, points to sunset at the equinoxes [1]. Many of the stones have quartz inclusions and many small pieces of quartz are associated with the circle [1]. In 1959 the site was excavated and a central pit containing charcoal and cremated bone was found [1].''"}, {"source": "remediation_change_log:104370", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:104371", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:251503", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251504", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-4000''"}, {"source": "remediation_change_log:341624", "url": "remediation_change_log", "quote": "insert-2026-10-07-006-001: thumbnail_url None -> ''/data/images/wiki/9db1409d/BohonaghSteinkreis.webp''"}, {"source": "remediation_change_log:350968", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:350969", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
