    ('9e2b99df-4b4c-41cb-80d3-879a5812e7ed'::uuid, 'mystery', '6', '8', 'card-stats-2026-11-05-rollback:9e2b99df-4b4c-41cb-80d3-879a5812e7ed:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on La basilique Sainte-Crispine', '80aea4b1b96e73e438f02c0d08d92177', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Church/cathedral'', ''1 - 500 AD'') is shared by 12 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44877", "url": "remediation_change_log", "quote": "phase4:p4-0101:chunk-0001: description \"The Basilica of Sainte-Crispine in Tebessa (ancient Theveste), Algeria, is one of the largest surviving early Christian basilicas in North Africa. Built c. 400 AD in a pagan necropolis outside the city walls, it honors St. Crispina, martyred in 305 CE under the Diocletian persecutions. The three-aisled complex includes a monumental 20-metre-wide staircase, geometric mosaics, a trefoil martyrium, baptistery, bathhouse, and stables. Rebuilt by Byzantine general Solomon in 535 after Berber destruction, it is on Algeria''s UNESCO Tentative List.\" -> \"The Tébessa Basilica is a Late Roman archeological site located in the eastern Algerian city of Theveste, which is known today as Tébessa [1]. It is one of the largest remains of Roman basilicas in Northern Africa [1]. It was dedicated to St. Crispina to honor her martyrdom in 305 CE [1]. The basilica''s large size is due to the additions and modifications made by the various Roman and Byzantine leaders in the 4th and 5th century [1]. The mosaic floors are accented by a pathway of balustrades marking the entrance into the great forecourt of the basilica [1]. A massive piscina is carved into the wall leading to a large open-air atrium [1]. In the center of the atrium is a four-lobed fountain [1].\""}, {"source": "remediation_change_log:121598", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: site_type ''Temple complex'' -> ''Church''"}, {"source": "remediation_change_log:355938", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Church'' -> ''Church/cathedral''"}]'::jsonb),
