    ('9e4fdcf5-98b1-4607-b412-e2348889b3b3'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:9e4fdcf5-98b1-4607-b412-e2348889b3b3:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Phthiotic Thebes', '53006fc8109ced913b04c0b0bb92df8a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86376", "url": "remediation_change_log", "quote": "phase4:p4-2140:chunk-0001: description ''Phthiotic Thebes (Thessalian Thebes) was an ancient city in Achaia Phthiotis, Thessaly, near modern Mikrothives on the Pagasetic Gulf. Inhabited since the Stone Age, it rose to prominence in the 4th century BC as the leading city of the Phthiotic Achaean League and the principal harbour on the Gulf until Demetrias was founded around 293 BC. Excavations revealed Cyclopean acropolis walls with about 40 towers and a 9 x 12 m temple foundation, possibly dedicated to Athena Polias. The site is also notable for nine Early Christian basilicas attesting to prosperity from the 4th through 6th centuries AD.'' -> ''Phthiotic Thebes or Thessalian Thebes was a city and polis in ancient Thessaly, Greece; its site was north of the modern village of Mikrothives and its harbour was at Pyrasus [1]. The city was located in the northeastern corner of the district of Phthiotis at the northern end of the ancient Crocus Field, to the north of the Pagasetic Gulf, at the distance of 300 stadia from Larissa [1]. Evidence of human habitation on the site dates back to the Stone Age, but the city is not mentioned by name until the 4th century BCE [1]. An inscription of the late fourth century BCE attests to the presence of a cult of Athena Polias [1].''"}, {"source": "remediation_change_log:104376", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:104377", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-500'' -> None"}, {"source": "remediation_change_log:157493", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Thessaly.jpg/400px-Thessaly.jpg'' -> ''/data/images/wiki/9e4fdcf5/Basilica_A_capital_2.webp''"}, {"source": "remediation_change_log:251509", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:251510", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-500''"}, {"source": "remediation_change_log:350974", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:350975", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-500'' -> None"}]'::jsonb),
