    ('9e723832-0a2b-43f9-90d1-3743b61b91ed'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:9e723832-0a2b-43f9-90d1-3743b61b91ed:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Lot''s Cave', '7f6a93abcf147da6a620179df7c56cf9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Cave Structures'', ''4500 - 3000 BC'') is shared by 11 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29380", "url": "remediation_change_log", "quote": "phase3:batch-0280:chunk-0001: site_type ''Cave Structures'' -> ''Monastery''"}, {"source": "remediation_change_log:35912", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Monastery'' -> ''Cave Structures''"}, {"source": "remediation_change_log:88788", "url": "remediation_change_log", "quote": "phase4:p4-2502:chunk-0001: description ''A cave and Byzantine monastic complex on a steep hillside near Ghor al-Safi, south of the Dead Sea in Jordan, traditionally identified as the refuge of the biblical Lot after the destruction of Sodom. Excavations led by Dr. Konstantinos Politis from 1986 revealed Early Bronze Age I burials (c. 3300-3000 BC) with pottery juglets, and Middle Bronze Age artifacts including a ceramic chalice and copper axe-head. A 5th-7th century triple-apsed basilica was built at the cave entrance, featuring mosaic pavements with Greek inscriptions dated to 606 AD and 691 AD that name clerics and a governor. The complex includes a pilgrim hostel, refectory, and a seven-metre-deep cistern.'' -> \"The Monastery of St Lot is a Byzantine-period monastic site near the Dead Sea in Jordan, at the entrance to a natural cave, which Catholics believed to have been the one where Lot and his daughters sought shelter after Sodom was destroyed [1]. The monastery, dating to the 5th-7th centuries, is centered around a basilical church and overlooks from a steep slope the southeastern Dead Sea and the modern town of Safi in Jordan [1]. The oldest material found inside the cave suggests a sizable Early and Middle Bronze Age presence, followed by Nabataean pottery, which is indicative of a settlement there during the first centuries BC and AD [1]. Two inscriptions on the church''s mosaic floor bear dates from the 7th century: construction in April 606, and a renovation in Xanthikos (roughly May) 691 [1]. Habitation only ceased after the Early Abbasid period [1]. The monastery had a large basilical church 18 x 17 meters long, a reservoir, a hostel complex, and access to a wide range of foods including fruits, meats, and fish from the Red Sea [1].\""}, {"source": "remediation_change_log:104381", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:104382", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:157514", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''/data/images/wiki/9e723832/hero.webp'' -> ''https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Lot%27s_cave_1.jpg/1280px-Lot%27s_cave_1.jpg''"}, {"source": "remediation_change_log:240725", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:240726", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-3300''"}]'::jsonb),
