    ('9f328a68-b73d-4fd9-bc44-a78d3cae960c'::uuid, 'mystery', '2', '8', 'card-stats-2026-11-05-rollback:9f328a68-b73d-4fd9-bc44-a78d3cae960c:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Isca Dumnoniorum', '0ee867af1792de9000258414711ec726', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 2 from (''City/town/settlement'', ''1 - 500 AD'') is shared by 180 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86380", "url": "remediation_change_log", "quote": "phase4:p4-2140:chunk-0001: description \"(c. AD 55) Roman legionary fortress at modern Exeter, built for the Legio II Augusta to secure southwest Britannia against the Dumnonii tribe. The 37-acre fort included a stone bathhouse with hypocaust heating, uncovered in 1970s excavations on Cathedral Green. After the legion relocated to Caerleon c. AD 75, the site became the civitas capital of the Dumnonii, gaining a forum, basilica, and public baths. Late 2nd-century stone walls, 3 m thick and 6 m high, enclosed 92 acres. About 70% of the circuit survives as the lower courses of Exeter''s medieval city walls.\" -> ''Isca Dumnoniorum was originally a Roman legionary fortress for the Second Augustan Legion (established c.\\u2009AD 55) in the Roman province of Britannia at the site of present-day Exeter in Devon [1]. The name Isca Dumnoniorum is a Latinization of a native Brittonic name describing flowing water, in reference to the River Exe [1]. The settlement of Isca Dumnoniorum seems to have developed around the Roman fortress [1].''"}, {"source": "remediation_change_log:121611", "url": 