    ('9f99919a-d5d6-4384-994b-704ece327ab6'::uuid, 'antiquity', '8', '5', 'card-stats-2026-11-05-rollback:9f99919a-d5d6-4384-994b-704ece327ab6:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Prosymna', 'ff40f84f26c4f41c08a0cbd15c1bb945', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -4000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36993", "url": "remediation_change_log", "quote": "phase4:p4-0048:chunk-0001: description \"Prosymna was a town in ancient Argolis, Greece, in whose territory the celebrated Heraeum (temple of Hera) stood, situated between Mycenae and Midea. The site was inhabited from the Neolithic period and hosts one of the largest Mycenaean cemeteries in mainland Greece (16th-13th century BC), yielding vases, weapons, and jewellery. Carl W. Blegen excavated the site (1925-28), uncovering numerous chamber tombs on slopes north and west of the temple. According to mythology, the name derives from a daughter of Asterion who, with her sisters Acraea and Euboea, nursed the goddess Hera. A 7th-century BC Doric temple was built on an 8th-century terrace, later replaced by a 5th-century BC temple housing Polykleitos'' chryselephantine statue of Hera.\" -> ''Prosymna was a town in ancient Argolis, in whose territory the celebrated Heraeum, or temple of Hera, stood [1]. The place was inhabited since the Neolithic period [1]. In 1878 Panagiotis Stamatakis found a beehive tomb that was built in the Mycenaean epoch and that was also reused in later periods [1]. Archaeological investigations continued under the auspices of the Swedish Institute at Athens in the 1930s and then during the 1980s and 1990s that found two settlement areas on two different sides of the Mastos hill slope, belonging to the Early and Late Helladic periods, respectively [1]. They have found chamber tombs and large amounts of pottery that testify that the place was an important center of production of this material for many centuries [1].''"}, {"source": "remediation_change_log:121612", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:121613", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:157543", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/c/cb/Prosymna_Tholos_4.JPG'' -> ''/data/images/wiki/9f99919a/Prosymna_Tholos_4.webp''"}, {"source": "remediation_change_log:251519", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:251520", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-800''"}, {"source": "remediation_change_log:350983", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1500 - 500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:350984", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-800'' -> ''-4000''"}]'::jsonb),
