    ('9fe64aa7-1b1a-4074-b6c2-f2d236938ab4'::uuid, 'empire_count', '2', '0', 'card-stats-2026-11-05-rollback:9fe64aa7-1b1a-4074-b6c2-f2d236938ab4:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Am Forsthofweg', 'c190c75e00328807b245fef1c5a7204d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 2 from tag_site(50.49418032204183, 7.393792337637719, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:36995", "url": "remediation_change_log", "quote": "phase4:p4-0048:chunk-0001: description ''(1st-2nd c. AD) Am Forsthofweg was a Roman castellum (small fort) situated along the Upper Germanic-Raetian Limes [1][2]. The site was inscribed as a UNESCO World Heritage Site in 2005 as part of the \"Upper Germanic-Raetian Limes\" designation [2].'' -> ''The castellum or small fort nowadays called Am Forsthofweg was a Roman military camp of the Upper Germanic-Rhaetian Limes [1]. It received UNESCO World Heritage status in 2005 [1]. The fortification was located in the area of the current Bad Hönningen association of municipalities within the district of Neuwied in Rhineland-Palatinate, Germany [1]. The fort was discovered in 1894 under the direction of Heinrich Jacobi, the local section commissioner of the Imperial Limes Commission, and examined in two excavation campaigns in 1894 and 1901 [1]. The Roman fortlet \"Am Forsthofweg\" is an almost square earthwork [1]. A rampart and a ditch 5 meters wide and 1.5 meters deep served as a first defense line [1]. With its only gate, the camp faced north, towards the Limes frontline [1]. A wooden construction of unknown function, covering around 45 square meters was found inside [1].''"}, {"source": "remediation_change_log:105053", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:105054", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''1'' -> None"}, {"source": "remediation_change_log:251521", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:251522", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-800''"}, {"source": "remediation_change_log:334648", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/9fe64aa7/hero.webp'' -> ''/data/images/wiki/9fe64aa7/Kleinkastell_am_Forsthofweg_3.webp''"}, {"source": "remediation_change_log:350985", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:350986", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-800'' -> None"}]'::jsonb),
