    ('a25bcd91-5122-452f-9a4c-87377012c26c'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:a25bcd91-5122-452f-9a4c-87377012c26c:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Castle Goff', 'db954d7356de1354107f627fbf47e667', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -800"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29581", "url": "remediation_change_log", "quote": "phase3:batch-0309:chunk-0001: site_type ''Fortress/citadel'' -> ''Earthwork''"}, {"source": "remediation_change_log:37007", "url": "remediation_change_log", "quote": "phase4:p4-0048:chunk-0001: description ''Castle Goff is a Cornish \"round\" -- a small circular embanked enclosure dating from the late Iron Age to the early post-Roman period -- located about 2.4 km south-west of Camelford. The enclosure measures approximately 60 metres in diameter, with a rampart standing 1.8 metres above the interior and 3.5 metres above the external ditch, which is 8 metres wide. An original western entrance, now blocked, leads via a causeway to a later annexe extending 106 metres north to south with its own rampart and outer ditch. Rounds are the most common type of Iron Age defended settlement in Cornwall, typically featuring a single entrance and serving as enclosed farmsteads.'' -> ''Castle Goff is an enclosure about 1.5 miles (2.4 km) south-west of Camelford, in Cornwall [1]. It is a scheduled monument [1]. Castle Goff is considered to be a \"round\": these are small circular embanked enclosures, with one entrance; they date from the late Iron Age to the early post-Roman period [1]. They are most common in Cornwall [1]. It is situated on the southern edge of a ridge between two tributaries of the River Allen [1]. Its diameter is about 60 metres (66 yd) [1]. The rampart is 1.8 metres (5.9 ft) above the interior, and 3.5 metres (11 ft) above the external ditch, which is about 8 metres (26 ft) wide and 0.8 metres (2.6 ft) deep [1]. From the original western entrance, which is now blocked, there is a causeway to an annexe to the west [1].''"}, {"source": "remediation_change_log:105096", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:105097", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''-500'' -> None"}, {"source": "remediation_change_log:157610", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''/data/images/wiki/a25bcd91/hero.webp'' -> ''/data/images/wiki/a25bcd91/Lanteglos DSC 8715.webp''"}, {"source": "remediation_change_log:251529", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251530", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-4000''"}, {"source": "remediation_change_log:314919", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url ''/data/images/wiki/a25bcd91/Lanteglos DSC 8715.webp'' -> ''/data/images/wiki/a25bcd91/Lanteglos_DSC_8710A.webp''"}, {"source": "remediation_change_log:357289", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s007: period_name ''4500 - 3000 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:357290", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s007: period_start ''-4000'' -> ''-800''"}]'::jsonb),
