    ('a36bb548-bebc-4606-af26-9cded2b3cded'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:a36bb548-bebc-4606-af26-9cded2b3cded:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Vatin Circles', '61ff6bfd7480f05adb5146c2eeb76c27', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86482", "url": "remediation_change_log", "quote": "phase4:p4-2143:chunk-0001: description ''The Vatin Circles are a prehistoric archaeological site near the village of Vatin, close to Vrsac in Vojvodina, Serbia. The site consists of four regular concentric circles forming a slight elevation, with a diameter of approximately 150 metres, while the nearby Vlajkovac Circles span about 300 metres. Artifacts found near the circles are attributed to the Vinca culture and estimated to be around 6,500 years old. On the eastern side, foundations of a smaller structure suggest the site may have served as an astronomical observatory for tracking celestial movements.'' -> ''Vatin circles are an archaeological site near the village of Vatin near Vršac [1]. It consists of four regular concentric circles that, going from larger to smaller, form a slight elevation [1]. Vatin circles have a diameter of around 150 meters while the Vlajkovac circles around 300 meters [1]. It is not known for sure how they were created or what their purpose was [1]. Objects that were found near the circles also speak in support of the assumption that these are Neolithic creations [1]. They were estimated in the Vršac City Museum to belong to the Vinča culture and are estimated to be 6500 years old [1].''"}, {"source": "remediation_change_log:121663", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:121664", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_start ''-5000'' -> None"}, {"source": "remediation_change_log:121665", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: site_type ''Geoglyphs'' -> ''Earthwork''"}, {"source": "remediation_change_log:251543", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251544", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-4000''"}, {"source": "remediation_change_log:345713", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:345714", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_start ''-4000'' -> None"}]'::jsonb),
