    ('a38ebb14-4f7b-459e-9ca4-0cbc15d16a32'::uuid, 'empire_count', '1', '0', 'card-stats-2026-11-05-rollback:a38ebb14-4f7b-459e-9ca4-0cbc15d16a32:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Dinas Emrys', '06bac480a28b73ecb3924ac5396d7521', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 1 from tag_site(53.02212904168553, -4.078989273851242, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81146", "url": "remediation_change_log", "quote": "phase4:p4-2022:chunk-0001: description \"Dinas Emrys is a rocky hillock near Beddgelert in Gwynedd, rising 76 m above the Glaslyn valley in Snowdonia. Excavations in 1910 and 1954-56 revealed occupation from the late Iron Age (1st-2nd century BC) through the Roman period to the early medieval era (5th-8th centuries AD). Imported Mediterranean pottery and iron smelting evidence date to the 5th century. Stone ramparts 2.5-3 m thick encircle the summit, with a 12th-century keep base attributed to the princes of Gwynedd. The site is famous in Welsh mythology as the place where the young prophet Ambrosius (later Merlin) revealed two fighting dragons beneath Vortigern''s failed citadel, a legend central to the Welsh red dragon emblem.\" -> \"Dinas Emrys (Welsh for ''Emrys''s city'') is a rocky and wooded hillock near Beddgelert in Gwynedd, north-west Wales [1]. Rising some 76 m above the floor of the Glaslyn river valley, it overlooks the southern end of Llyn Dinas in Snowdonia [1]. Little remains of the structures that once stood on the hill [1]. Such remains as are visible today, including three series of ramparts and other walls and some foundations, mostly date to the Middle Ages [1]. Excavations in 1910 and 1954–56 revealed several periods of habitation at the site [1]. According to legend, when Vortigern fled into Wales to escape the Anglo-Saxon invaders, he chose this lofty hillfort as the site for his royal retreat [1].\""}, {"source": "remediation_change_log:105116", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:105117", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:157682", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''/data/images/wiki/a38ebb14/hero.webp'' -> ''/data/images/wiki/a38ebb14/Castell Dinas Emrys, Parc Cenedlaethol Eryri, Gwynedd, Cymru (Wales) 09.webp''"}, {"source": "remediation_change_log:251549", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:251550", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-800''"}, {"source": "remediation_change_log:351001", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:351002", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-800'' -> None"}]'::jsonb),
