    ('a3a38d98-16fc-464f-bbeb-c027813ef202'::uuid, 'antiquity', '6', '4', 'card-stats-2026-11-05-rollback:a3a38d98-16fc-464f-bbeb-c027813ef202:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Acumincum', '0fd3f0b8260f015a8772bf344f4fe2ac', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 6 from period_start -1600"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86504", "url": "remediation_change_log", "quote": "phase4:p4-2144:chunk-0001: description ''Acumincum was an ancient Roman settlement and military fort located in present-day Stari Slankamen, Serbia, on the banks of the Danube in the Roman province of Pannonia [1]. The site was originally inhabited by Celtic Scordisci people in the 3rd century BC before Roman conquest in the 1st century BC [1]. It functioned as a key fort along the Pannonian Limes, the Roman frontier defense system [1]. The name derives from the Latin \"acumen\" meaning point or projection, referring to the site\\''s geographic position [1].'' -> ''Acumincum was an ancient Roman settlement, located in the present day town of Stari Slankamen, Serbia [1]. In the 3rd century BC, the area was inhabited by Celtic Scordisci [1]. The name also appears as Acimincum and in the Peutingerian Table, the name is written Acunum [1]. Jupiter Dolichenus sculptures have been found in the town [1].''"}, {"source": "remediation_change_log:121673", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:121674", "url": "remediation_change_log", "quot