    ('a3c3f3e8-b249-4f70-bb03-8cd733213e76'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:a3c3f3e8-b249-4f70-bb03-8cd733213e76:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Platt', 'b6611da86ac98048c0bc00f02e2138a7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86508", "url": "remediation_change_log", "quote": "phase4:p4-2144:chunk-0001: description \"The Sandberg ridge between Platt and Roseldorf in Lower Austria''s Weinviertel region hosts the largest known Celtic central settlement of this period in Austria, covering approximately 40 hectares. Dating to the Middle La Tene period (c. 260-150 BC), the site contained around 450 pit houses and featured seven square shrine enclosures (10-17 m each) where weapons, horse harness parts, and animal and human bones were deposited as offerings. Austria''s oldest and richest coin-minting site was discovered here, alongside potteries, smithies, and glass workshops. Evidence of cultivated dill and wine indicates Mediterranean trade contacts.\" -> ''The Platt area shows signs of human habitation that date back to late neolithic (Funnelbeaker culture) and early Bronze Age (Unetice culture) times [1]. Prehistoric culture reached its peak during the early and middle La Tène period, around 300 B.C., when the large (20-40 ha) Sandberg Celtic city existed here on the southern slopes of the nearby Sandberg ridge [1]. Systematic archeological excavations that have been ongoing since 2001 continue to reveal information on this recently recognized and highly significant settlement from the Iron Age, which at its climax comprised at least 450 buildings and included a halidom district with several cult sites [1].''"}, {"source": "remediation_change_log:105118", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:105119", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''-500'' -> None"}, {"source": "remediation_change_log:157684", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/3/3b/Platt_old%2Bnew_church.jpg'' -> None"}, {"source": "remediation_change_log:251553", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:251554", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-500''"}, {"source": "remediation_change_log:314952", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url None -> ''/data/images/wiki/a3c3f3e8/Platt_old+new_church.webp''"}, {"source": "remediation_change_log:351007", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:351008", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''-500'' -> None"}]'::jsonb),
