    ('a4856c44-4e78-4a45-b618-d558b763942d'::uuid, 'antiquity', '5', '1', 'card-stats-2026-11-05-rollback:a4856c44-4e78-4a45-b618-d558b763942d:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''1'' restored on Arroyo de Piedra', 'bdafd81bd010e9f8eb058233ef6b801d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37035", "url": "remediation_change_log", "quote": "phase4:p4-0049:chunk-0001: description \"Arroyo de Piedra is a pre-Columbian Maya archaeological site in the Petexbatún region of Guatemala, located 2-3 km northeast of Dos Pilas and 3 km west of Tamarindito [1]. The site flourished during the Classic Maya period (c. 250-900 AD), reaching its peak between 500-600 AD when it shared political power and a regional emblem glyph with neighboring Tamarindito [2]. Unlike the architecture of Dos Pilas and Aguateca, Arroyo de Piedra''s structures more closely resemble those of Tamarindito [1]. The site functioned as a secondary center within the Petexbatún polity, losing prominence when Dos Pilas rose to dominance [2]. Arroyo de Piedra was abandoned in the 8th century AD, likely following the collapse of Dos Pilas [2].\" -> ''Arroyo de Piedra is a pre-Columbian Maya archaeological site in Guatemala located approximately 2-3 km east/northeast of Dos Pilas and 3 km west of Tamarindito [1]. The site dates to the middle half of the Classic period [1]. While initially a center of some regional importance, with the rise of Dos Pilas, Arroyo de Piedra was subsumed as a secondary center within the Petexbatun region [1]. The architecture of Arroyo de Piedra is different from that of Dos Pilas and nearby Aguateca, but bears similarities to Tamarindito [1]. Hieroglyphic data shows that together Arroyo de Piedra and Tamarindito formed an independent polity prior to the establishment of Dos Pilas by Tikal [1]. It appears that Arroyo de Piedra was abandoned during the 8th century following the collapse of Dos Pilas and the disintegration of the polity centered there [1].''"}, {"source": "remediation_change_log:105124", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''1000 - 1500 AD'' -> None"}, {"source": "remediation_change_log:105125", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''1000'' -> None"}, {"source": "remediation_change_log:105126", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:157717", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''/data/images/wiki/a4856c44/hero.webp'' -> None"}, {"source": "remediation_change_log:240786", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: site_type None -> ''Archaeological site''"}, {"source": "remediation_change_log:251557", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:251558", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''1000''"}, {"source": "remediation_change_log:351009", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_name ''1000 - 1500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:351010", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s006: period_start ''1000'' -> None"}]'::jsonb),
