    ('a4955f7b-3996-4477-9540-891364da6c71'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:a4955f7b-3996-4477-9540-891364da6c71:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Car Dyke', '4da919547391affb9fb56629a0b7f3a1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Earthwork'', ''1 - 500 AD'') is shared by 11 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86514", "url": "remediation_change_log", "quote": "phase4:p4-2144:chunk-0001: description \"Car Dyke is a Roman-era earthwork extending approximately 92 km (57 mi) along the western edge of the Fens in eastern England [1][2]. This substantial ditch was long believed to mark the fenland''s western boundary [1].\" -> ''The Car Dyke is a long ditch which runs along the western edge of the Fens in eastern England for a distance of over 57 miles (92 km) [1]. It is generally accepted as being a Roman construction and was, for many centuries, considered to mark the western edge of the Fens [1]. Its name derives from carr, a fourteenth-century word for marsh or drained land [1]. The Car Dyke is a ditch that runs through the counties of Lincolnshire and Cambridgeshire [1]. The main section starts close to the River Witham at Washingborough, near Lincoln and runs in a generally southerly direction to Fengate on the River Nene [1]. The ditch is obviously artificial, since it runs from north to south, whereas all the natural drainage of the area runs from west to east, and it roughly follows the 10-foot contour [1]. The 57-mile northern part of the Car Dyke from Lincoln to Peterborough is reasonably easy to follow with earthworks extant upon the ground or from cropmarks visible from the air [1].''"}, {"source": "remediation_change_log:157720", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''/data/images/wiki/a4955f7b/hero.webp'' -> ''/data/images/wiki/a4955f7b/Car Dyke S of Dyke.webp''"}, {"source": "remediation_change_log:314961", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url ''/data/images/wiki/a4955f7b/Car Dyke S of Dyke.webp'' -> ''/data/images/wiki/a4955f7b/Car Dyke near Branston, Lincolnshire, - Geograph 524787.webp''"}]'::jsonb),
