    ('a4ac2a6f-0159-447e-a6d2-7300fbc986ef'::uuid, 'mystery', '3', '8', 'card-stats-2026-11-05-rollback:a4ac2a6f-0159-447e-a6d2-7300fbc986ef:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Sidrón Cave', 'fdee22f113781afe358c11305f360704', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28770", "url": "remediation_change_log", "quote": "phase3:batch-0191:chunk-0001: site_type ''Megalithic structures'' -> ''Cave Structures''"}, {"source": "remediation_change_log:32422", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-journal-reversal-2: site_type ''Cave Structures'' -> ''Megalithic structures''"}, {"source": "remediation_change_log:44907", "url": "remediation_change_log", "quote": "phase4:p4-0102:chunk-0001: description ''The Sidrón Cave is a non-carboniferous limestone karst cave system located in the Piloña municipality of Asturias, northwestern Spain, where Paleolithic rock art and the fossils of more than a dozen Neanderthals were found [1]. The cave was declared a \"Partial Natural Reserve\" in 1995 [1]. The site serves as a retreat for five species of bats and is the place of discovery of two species of Coleoptera (beetles) [1].'' -> ''The Sidrón Cave is a non-carboniferous limestone karst cave system located in the Piloña municipality of Asturias where Paleolithic rock art and the fossils of more than a dozen Neanderthals were found [1]. The total length of this huge complex is approximately 3,700 m, which contains a central hall of 200 m length and the Neanderthal fossil site, called the Ossuary Gallery, which is 28 m long and 12 m wide [1]. In 1994, human remains were found accidentally in the cave [1]. They were initially suspected to be from the Spanish Civil War because Republican fighters used to hide there; however, later analysis shows that the remains actually belong to Neanderthals [1]. Researchers recovered more than 2500 hominin fossil elements from the site [1]. The minimum number of individuals from Sidrón Cave is 13 [1]. The age of these remains of three men, three adolescent boys, four women, and three infants has been estimated to about 49,000 years [1]. The first sequencing of the Neanderthal Y chromosome was successfully completed from a specimen from Sidrón Cave [1].''"}, {"source": "remediation_change_log:121686", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: site_type ''Megalithic structures'' -> ''Cave''"}, {"source": "remediation_change_log:157722", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Cueva_El_Sidron_(02)_Arqueoloxicu.jpg/400px-Cueva_El_Sidron_(02)_Arqueoloxicu.jpg'' -> ''/data/images/wiki/a4ac2a6f/Cueva_El_Sidron_(02)_Arqueoloxicu.webp''"}, {"source": "remediation_change_log:355942", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Cave'' -> ''Cave Structures''"}]'::jsonb),
    ('a4ac2a6f-0159-447e-a6d2-7300fbc986ef'::uuid, 'rarity_score', '23', '38', 'card-stats-2026-11-05-rollback:a4ac2a6f-0159-447e-a6d2-7300fbc986ef:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''38'' restored on Sidrón Cave', 'fdee22f113781afe358c11305f360704', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 23 from mystery 3, cultural_influence 7"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28770", "url": "remediation_change_log", "quote": "phase3:batch-0191:chunk-0001: site_type ''Megalithic structures'' -> ''Cave Structures''"}, {"source": "remediation_change_log:32422", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-journal-reversal-2: site_type ''Cave Structures'' -> ''Megalithic structures''"}, {"source": "remediation_change_log:44907", "url": "remediation_change_log", "quote": "phase4:p4-0102:chunk-0001: description ''The Sidrón Cave is a non-carboniferous limestone karst cave system located in the Piloña municipality of Asturias, northwestern Spain, where Paleolithic rock art and the fossils of more than a dozen Neanderthals were found [1]. The cave was declared a \"Partial Natural Reserve\" in 1995 [1]. The site serves as a retreat for five species of bats and is the place of discovery of two species of Coleoptera (beetles) [1].'' -> ''The Sidrón Cave is a non-carboniferous limestone karst cave system located in the Piloña municipality of Asturias where Paleolithic rock art and the fossils of more than a dozen Neanderthals were found [1]. The total length of this huge complex is approximately 3,700 m, which contains a central hall of 200 m length and the Neanderthal fossil site, called the Ossuary Gallery, which is 28 m long and 12 m wide [1]. In 1994, human remains were found accidentally in the cave [1]. They were initially suspected to be from the Spanish Civil War because Republican fighters used to hide there; however, later analysis shows that the remains actually belong to Neanderthals [1]. Researchers recovered more than 2500 hominin fossil elements from the site [1]. The minimum number of individuals from Sidrón Cave is 13 [1]. The age of these remains of three men, three adolescent boys, four women, and three infants has been estimated to about 49,000 years [1]. The first sequencing of the Neanderthal Y chromosome was successfully completed from a specimen from Sidrón Cave [1].''"}, {"source": "remediation_change_log:121686", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: site_type ''Megalithic structures'' -> ''Cave''"}, {"source": "remediation_change_log:157722", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Cueva_El_Sidron_(02)_Arqueoloxicu.jpg/400px-Cueva_El_Sidron_(02)_Arqueoloxicu.jpg'' -> ''/data/images/wiki/a4ac2a6f/Cueva_El_Sidron_(02)_Arqueoloxicu.webp''"}, {"source": "remediation_change_log:355942", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''Cave'' -> ''Cave Structures''"}]'::jsonb),
