    ('a4f216bd-ef7d-4764-aa03-c88b3d5a588e'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:a4f216bd-ef7d-4764-aa03-c88b3d5a588e:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Warratyi', '234f846cdf873c409f9ab76b1c5af4da', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -47050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29264", "url": "remediation_change_log", "quote": "phase3:batch-0262:chunk-0001: period_start ''-500'' -> ''-49000''"}, {"source": "remediation_change_log:29265", "url": "remediation_change_log", "quote": "phase3:batch-0262:chunk-0001: site_type ''Cave Structures'' -> ''Archaeological site''"}, {"source": "remediation_change_log:30472", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:35928", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''Cave Structures''"}, {"source": "remediation_change_log:37039", "url": "remediation_change_log", "quote": "phase4:p4-0049:chunk-0001: description \"Warratyi is a rock shelter in the Flinders Ranges, South Australia, representing the oldest known site of human habitation in inland Australia [1]. Discovered accidentally in 2011 by a local resident, the shelter contains thousands of artefacts and bone fragments dating between 49,000 and 10,000 years ago [1]. The excavations revealed Australia''s earliest evidence of bone and stone-axe technology, ochre use, and interaction with megafauna such as Diprotodon [1].\" -> \"Warratyi is the site of a rock shelter in the Flinders Ranges in South Australia [1]. Located around 550 kilometres north of Adelaide and about 200 kilometres inland, it has been identified as the oldest known site of human habitation in inland Australia [1]. Researchers found thousands of artefacts and bone fragments, which enabled them to date the shelter''s occupation to a number of periods between 49,000 and 10,000 years ago [1]. The finds include the earliest evidence in Australia of the development of bone and stone-axe technology, the use of ochre, and interaction with megafauna such as Diprotodon [1]. The site is located in the ancestral lands of the Adnyamathanha, an Indigenous Australian people [1]. It lies in a gorge at the southern end of the Lake Eyre basin in the northern Flinders Ranges [1]. The artefacts included pieces of gypsum pigment, hafted and stone tools, and bone needles including the oldest bone tool so far found in Australia [1].\""}, {"source": "remediation_change_log:105132", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:105133", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''-49000'' -> None"}, {"source": "remediation_change_log:251563", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:251564", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s014: period_start None -> ''-500''"}, {"source": "remediation_change_log:351760", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:351761", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-500'' -> ''-47050''"}]'::jsonb),
