    ('a5009e55-a34f-4568-9d9b-1d86d1082a9b'::uuid, 'mystery', '1', '5', 'card-stats-2026-11-05-rollback:a5009e55-a34f-4568-9d9b-1d86d1082a9b:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Tayasal', '5970901736e6d7801c2d536dcd8fbf2e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''1500 - 500 BC'') is shared by 286 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81148", "url": "remediation_change_log", "quote": "phase4:p4-2022:chunk-0001: description ''Tayasal is a Maya archaeological site on a peninsula on Lake Peten Itza in northern Guatemala, occupied from the Middle Preclassic (c. 1000 BC) through the Late Postclassic period (c. 1539 AD). The site features a 30-metre-high acropolis that served as the elite residence, pyramid temples, triadic pyramids, E-Group complexes, plazas, and defensive walls. Tayasal was among the last Maya cities to fall to the Spanish, conquered in 1697. Excavations since 1921 have uncovered burials, caches, and evidence of Spanish contact including bullets from European firearms.'' -> ''Tayasal is a Maya archaeological site located in present-day Guatemala [1]. It was a large Maya city with a long history of occupation [1]. The site was occupied from the Middle Preclassic period (c. 1000–350 BC) through to the Late Postclassic (c. 1200–1539 AD) [1]. The Tayasal archaeological site is situated on a peninsula on Lake Petén Itzá a short distance to the north of the modern town of Flores, separated from it by a 270-metre wide stretch of water, and falls within the municipality of Flores, in the department of Petén in northern Guatemala [1]. The site covers an area of approximately 2.75 square kilometres [1]. The University of Pennsylvania mapped the site in 1971 [1]. The University of Pennsylvania project mapped 339 structures; the city possessed large open plazas, palaces, pyramid-temples, an acropolis, defensive walls, residential buildings, and a cenote [1]. As many as fifty burials and twelve caches have been recovered from Tayasal [1].''"}, {"source": "remediation_change_log:105134", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''500 BC - 1 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:105135", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''-500'' -> ''-600''"}, {"source": "remediation_change_log:105136", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:157726", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Tayazal_10.JPG/400px-Tayazal_10.JPG'' -> ''/data/images/wiki/a5009e55/Tayazal 07.webp''"}, {"source": "remediation_change_log:240787", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: site_type None -> ''City''"}, {"source": "remediation_change_log:355943", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s002: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
