    ('a55ddaef-8835-4749-ab18-978c295cf1b5'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:a55ddaef-8835-4749-ab18-978c295cf1b5:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Second Ancient Theatre, Larissa', 'dd66256331c6b1f35d05acea798b792f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Theatre'', ''500 BC - 1 AD'') is shared by 28 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37041", "url": "remediation_change_log", "quote": "phase4:p4-0049:chunk-0001: description \"Built in the late 1st century BC, the Second Ancient Theatre of Larissa is an ancient Greek theatre located on the southwestern slopes of Pefkakia hill in Larissa, Thessaly, Greece [1]. It was constructed likely as a replacement for the city''s original theatre, which was converted into an arena for gladiatorial contests and public spectacles following the Roman conquest of Greece [1]. The theatre reflects the architectural adaptation that occurred in Greek cities during the Roman period, serving as a venue for dramatic performances and public entertainments [1].\" -> \"The Second Ancient Theatre of Larissa is an ancient Greek theatre in the city of Larissa in Thessaly, Greece [1]. The theatre was built in the second half of the 1st century BC, on the southwestern slopes of the Pefkakia hill [1]. Its construction is probably connected to the conversion of the city''s original theatre, which was converted into an arena for gladiatorial contests and public spectacles after the Roman conquest of Greece [1]. An inscription dedicated to Demeter and the Kore indicates that the site also housed a temple dedicated to them [1]. Only the stage and the chorus area (orchestra) were completed; the semi-circular seating area (koilon) and the side entrances were left incomplete, apparently due to inability to fund their completion [1]. The koilon is divided by 14 stairs into thirteen tiers, each with two rows of low seats of grey-white marble; the rest were never completed, and probably wooden seats were used instead [1]. The orchestra has a diameter of 29.7 metres and is composed of two layers of stamped earth mixed with gravel [1].\""}, {"source": "remediation_change_log:157733", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/6/60/Second_Ancient_Theater_of_Larissa_2.jpg'' -> ''/data/images/wiki/a55ddaef/Théâtre B de Larissa.webp''"}, {"source": "remediation_change_log:314973", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url ''/data/images/wiki/a55ddaef/Théâtre B de Larissa.webp'' -> ''/data/images/wiki/a55ddaef/Second_Ancient_Theater_of_Larissa_2.webp''"}]'::jsonb),
