    ('a627df4e-f241-478e-b8ab-273e67f52441'::uuid, 'mystery', '8', '7', 'card-stats-2026-11-05-rollback:a627df4e-f241-478e-b8ab-273e67f52441:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Sweet Track', 'bcd247e200013c3dc81e025aa0c67e2b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Road/avenue/trackway'', ''4500 - 3000 BC'') is shared by 4 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86536", "url": "remediation_change_log", "quote": "phase4:p4-2145:chunk-0001: description ''Built in 3807 BC, the Sweet Track is a Neolithic timber causeway in the Somerset Levels, England, named after its discoverer Ray Sweet. It is the second-oldest timber trackway found in the British Isles, constructed largely along the route of the earlier Post Track[1].'' -> ''The Sweet Track is an ancient trackway, or causeway, in the Somerset Levels, England, named after its finder, Ray Sweet [1]. The Sweet Track was predominantly built along the course of an earlier structure, the Post Track [1]. The track extended across the now largely drained marsh between what was then an island at Westhay and a ridge of high ground at Shapwick, a distance close to 1,800 metres or around 1.1 mi [1]. Various artifacts and prehistoric finds, including a jadeitite ceremonial axe head, have been found in the peat bogs along its length [1]. The track was used for a period of only around ten years and was then abandoned, probably due to rising water levels [1]. The track was discovered in 1970 during peat excavations and is named after its finder, Ray Sweet [1]. Built in 3807 or 3806 BC, the track was a walkway consisting mainly of planks of oak laid end-to-end, supported by crossed pegs of ash, oak, and lime, driven into the underlying peat [1].''"}, {"source": "remediation_change_log:158255", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/6/66/Sweettrack.jpg'' -> ''/data/images/wiki/a627df4e/Sweet_track_cross_section2.webp''"}, {"source": "remediation_change_log:314985", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url ''/data/images/wiki/a627df4e/Sweet_track_cross_section2.webp'' -> ''/data/images/wiki/a627df4e/Sweettrack.webp''"}]'::jsonb),
