    ('a6f66111-c0d1-4c01-a49a-eb2d476a33d0'::uuid, 'mystery', '7', '6', 'card-stats-2026-11-05-rollback:a6f66111-c0d1-4c01-a49a-eb2d476a33d0:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Treasury of the Acanthians', '607793110f66486ba948a3e8c31272f9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (None, ''500 BC - 1 AD'') is shared by 9 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27931", "url": "remediation_change_log", "quote": "phase3:batch-0032:chunk-0001: period_start ''-1500'' -> ''-424''"}, {"source": "remediation_change_log:30476", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1500 - 500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:81152", "url": "remediation_change_log", "quote": "phase4:p4-2022:chunk-0001: description ''The Treasury of the Acanthians at Delphi was built by citizens of Acanthos on the Chalcidice peninsula to commemorate their joint victory with the Lacedaemonians against Athens. Built likely after 424 BC, when Spartan general Brasidas persuaded Acanthos to defect from the Athenian alliance during the Peloponnesian War. Plutarch records that the treasury housed a statue debated as depicting either Lysander or Brasidas, and a chryselephantine (gold and ivory) trireme donated by Cyrus the Younger. In the Roman period, a gate behind the treasury led to the House of the Peristyle.'' -> ''The Treasury of the Acanthians at Delphi was built by the citizens of Acanthos on the Chalcidice peninsula in commemoration of their joint victory with the Lacedaemonians against the Athenians [1]. In 424 B.C., in the course of the Peloponnesian War, the Spartan general Brasidas managed to persuade Acanthos, an ally of Athens on the Chalcidice peninsula, to defect from their alliance [1]. Then, the Acanthians sided with the Lacaedemonians and fought against Athens [1]. From the booty of the battles, including the battle of Lyncestis, they built a treasury in the sanctuary of Apollo at Delphi, commemorating the joint victory [1]. Plutarch in his \"Life of Lysander\" mentions the dedicatory inscription: Brasidas and the Acanthians from the Athenians [1].''"}, {"source": "remediation_change_log:122808", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:122809", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_start ''-424'' -> None"}, {"source": "remediation_change_log:122810", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: site_type ''Megalithic structures'' -> None"}, {"source": "remediation_change_log:240802", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:240803", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-422''"}]'::jsonb),
