    ('a86f1885-cf64-4dfc-bbec-b388a3ae2ebf'::uuid, 'cultural_influence', '8', '7', 'card-stats-2026-11-05-rollback:a86f1885-cf64-4dfc-bbec-b388a3ae2ebf:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''7'' restored on Totternhoe Roman Villa', 'b8d6f7565cdb476ab939073a0e16fa59', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 8 from description yes, thumbnail yes, 5 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86590", "url": "remediation_change_log", "quote": "phase4:p4-2146:chunk-0001: description ''Totternhoe Roman Villa is a Scheduled Monument on Church Farm in Totternhoe, Bedfordshire, England. Excavated by the Manshead Archaeological Society in the 1950s under C. L. Matthews, the villa measured approximately 68 by 73 metres around a central courtyard. It featured a bath block, tessellated pavements, and painted wall plaster described as without parallel in Roman Britain. Primarily occupied in the 4th century, with 2nd-century pottery indicating earlier activity and a 5th-century Saxon sherd marking its abandonment. The site has been filled in and grassed over with nothing visible above ground.'' -> ''Totternhoe Roman villa is on Church Farm, Church Road, in Totternhoe, Bedfordshire [1]. The villa was excavated by the Manshead Archaeological Society under the direction of C. L. Matthews in the 1950s [1]. It was a Roman courtyard house, 200x240 feet, with at least 14 rooms, with mosaics, hypocausts and painted wall plaster [1]. Pottery was mainly late 4th century, but there was also some from the 2nd century [1]. 5-6th century Saxon potsherds were also found, suggesting occupation after the villa was abandoned [1].''"}, {"source": "remediation_change_log:105196", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:105197", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''1'' -> None"}, {"source": "remediation_change_log:158356", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/2/28/Site_of_Totternhoe_Roman_Villa.JPG'' -> None"}, {"source": "remediation_change_log:241628", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:241629", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_start None -> ''301''"}, {"source": "remediation_change_log:323551", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-002: thumbnail_url None -> ''/data/images/wiki/a86f1885/hero.webp''"}, {"source": "remediation_change_log:325328", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/a86f1885/hero.webp'' -> ''/data/images/wiki/a86f1885/Site of Totternhoe Roman Villa.webp''"}]'::jsonb),
