    ('a8c2a8e8-d03c-4037-ab82-8c246b2d6e29'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:a8c2a8e8-d03c-4037-ab82-8c246b2d6e29:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Cuevas de la Araña', '8fe8220ae4abf765853baab496391e75', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Rock art'', ''< 4500 BC'') is shared by 29 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44925", "url": "remediation_change_log", "quote": "phase4:p4-0103:chunk-0001: description \"The Coves de l''Aranya (Cuevas de la Araña) are a group of caves in Bicorp, València, eastern Spain, located in the valley of the river Escalona. These prehistoric rock art sites contain painted images of a bow-and-arrow goat hunt and a unique scene depicting a human figure foraging honey, representing the earliest known depiction of bees and the oldest evidence of honey consumption by Homo sapiens, dating to approximately 8,000 years ago [1].\" -> \"The Coves de l''Aranya (in original Catalan language, known in English as the Spider Caves and in Spanish Cuevas de la Araña) are a group of caves in the municipality of Bicorp in València, eastern Spain [1]. The caves are in the valley of the river Escalona and were used by prehistoric people who left rock art [1]. They are known for painted images of a bow and arrow goat hunt and for a scene depicting a human figure foraging honey [1]. The dating of such art is controversial, but the famous honey-gathering painting is believed to be epipaleolithic and is estimated to be around 8000 years old [1]. The caves were discovered in the early twentieth century by a local teacher, Jaume Garí i Poch [1]. They are included in the World Heritage Site Rock art of the Iberian Mediterranean Basin [1].\""}, {"source": "remediation_change_log:158361", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''/data/images/wiki/a8c2a8e8/hero.webp'' -> ''/data/images/wiki/a8c2a8e8/Cuevas de la Araña 02.webp''"}, {"source": "remediation_change_log:315634", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-011: thumbnail_url ''/data/images/wiki/a8c2a8e8/Cuevas de la Araña 02.webp'' -> \"/data/images/wiki/a8c2a8e8/Cova_de_l''Aranya.webp\""}]'::jsonb),
