    ('a98dcb51-39c4-4ab9-b34e-1f10a9aa14d9'::uuid, 'mystery', '8', '7', 'card-stats-2026-11-05-rollback:a98dcb51-39c4-4ab9-b34e-1f10a9aa14d9:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Pilgrims'' Way', '59f6ffac73088118de8bea5ced719048', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Road/avenue/trackway'', ''1500 - 500 BC'') is shared by 5 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81174", "url": "remediation_change_log", "quote": "phase4:p4-2023:chunk-0001: description ''The Pilgrims\\'' Way is an ancient trackway in southern England, originally dating to 600-450 BC though likely used since the Stone Age [1]. The name refers to the medieval pilgrimage route from Winchester to Canterbury\\''s shrine of Thomas Becket, though this is a later application to the pre-existing prehistoric route [1]. The track follows the \"natural causeway\" along the southern slopes of the North Downs, connecting Hampshire to Kent [1].'' -> ''The Pilgrims\\'' Way is the historical route supposedly taken by pilgrims from Winchester in Hampshire, England, to the shrine of Thomas Becket at Canterbury in Kent [1]. This name, of comparatively recent coinage, is applied to a pre-existing ancient trackway dated by archaeological finds to 600–450 BC, but probably in existence since the Stone Age [1]. The prehistoric route followed the \"natural causeway\" east to west on the southern slopes of the North Downs [1]. The prehistoric trackway extended further than the present Way, providing a link from the narrowest part of the English Channel to the important religious complexes of Avebury and Stonehenge, in Wiltshire, where it is known as the Harroway [1]. The way then existed as \"broad and ill-defined corridors of movement up to half a mile wide\" and not as a single, well-defined track [1]. The route was still followed as an artery for through traffic in Roman times [1].''"}, {"source": "remediation_change_log:105216", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:105217", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:158393", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/a7/Pilgrims%27_Way_to_the_South_of_the_White_Horse_Stone_%28I%29.jpg'' -> \"/data/images/wiki/a98dcb51/Pilgrims'' Way to the South of the White Horse Stone (II).webp\""}, {"source": "remediation_change_log:241633", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:241634", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_start None -> ''-600''"}, {"source": "remediation_change_log:315646", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-011: thumbnail_url \"/data/images/wiki/a98dcb51/Pilgrims'' Way to the South of the White Horse Stone (II).webp\" -> \"/data/images/wiki/a98dcb51/Pilgrims''_Way_to_the_South_of_the_White_Horse_Stone_(I).webp\""}]'::jsonb),
