    ('aa60e5f1-a3f5-4f27-b152-44ad38e72f54'::uuid, 'cultural_influence', '5', '4', 'card-stats-2026-11-05-rollback:aa60e5f1-a3f5-4f27-b152-44ad38e72f54:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''4'' restored on Stoke Hill', 'eac045bdf3fdcf62d347e5648ec6395e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 5 from description yes, thumbnail yes, 0 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81176", "url": "remediation_change_log", "quote": "phase4:p4-2023:chunk-0001: description ''Stoke Hill is a prominent hill north of Exeter in Devon, England, notable for both an Iron Age hillfort and a Roman signal station. The univallate hillfort, built during the Iron Age, was occupied for at least 200 years before the Romans arrived, and a 1935 excavation indicated 1st-century AD activity. The Roman signal station, discovered via aerial photography by J.K. St. Joseph in 1953, comprises concentric enclosures -- the outer roughly 350 feet square -- and served as part of a 3rd-century coastal defence network. The site is a scheduled ancient monument.'' -> ''Stoke Hill is a large hill rising to the north of Exeter in Devon, England [1]. It is significant as the site of both an Iron Age hill fort and a later Roman signal station [1]. The hill fort is situated slightly below and northeast of the Roman signal station, putting it in a better position to have sight of a number of other hill forts simultaneously [1]. It is at an elevation of approximately 145 metres above sea level [1]. The signal station is at the highest point of the hill, 159 metres above sea level [1].''"}, {"source": "remediation_change_log:105237", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:105238", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:158411", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/e/e1/Exeter_District_-_Stoke_Hill_Farm_Track_%28geograph_3417475%29.jpg'' -> None"}, {"source": "remediation_change_log:251935", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:251936", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_start None -> ''-800''"}, {"source": "remediation_change_log:323575", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-002: thumbnail_url None -> ''/data/images/wiki/aa60e5f1/hero.webp''"}, {"source": "remediation_change_log:325331", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/aa60e5f1/hero.webp'' -> ''/data/images/wiki/aa60e5f1/Exeter District - Stoke Hill Farm Track (geograph 3417475).webp''"}]'::jsonb),
    ('aa60e5f1-a3f5-4f27-b152-44ad38e72f54'::uuid, 'rarity_score', '13', '11', 'card-stats-2026-11-05-rollback:aa60e5f1-a3f5-4f27-b152-44ad38e72f54:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''11'' restored on Stoke Hill', 'eac045bdf3fdcf62d347e5648ec6395e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 13 from mystery 1, cultural_influence 5"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81176", "url": "remediation_change_log", "quote": "phase4:p4-2023:chunk-0001: description ''Stoke Hill is a prominent hill north of Exeter in Devon, England, notable for both an Iron Age hillfort and a Roman signal station. The univallate hillfort, built during the Iron Age, was occupied for at least 200 years before the Romans arrived, and a 1935 excavation indicated 1st-century AD activity. The Roman signal station, discovered via aerial photography by J.K. St. Joseph in 1953, comprises concentric enclosures -- the outer roughly 350 feet square -- and served as part of a 3rd-century coastal defence network. The site is a scheduled ancient monument.'' -> ''Stoke Hill is a large hill rising to the north of Exeter in Devon, England [1]. It is significant as the site of both an Iron Age hill fort and a later Roman signal station [1]. The hill fort is situated slightly below and northeast of the Roman signal station, putting it in a better position to have sight of a number of other hill forts simultaneously [1]. It is at an elevation of approximately 145 metres above sea level [1]. The signal station is at the highest point of the hill, 159 metres above sea level [1].''"}, {"source": "remediation_change_log:105237", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:105238", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:158411", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/e/e1/Exeter_District_-_Stoke_Hill_Farm_Track_%28geograph_3417475%29.jpg'' -> None"}, {"source": "remediation_change_log:251935", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:251936", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_start None -> ''-800''"}, {"source": "remediation_change_log:323575", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-002: thumbnail_url None -> ''/data/images/wiki/aa60e5f1/hero.webp''"}, {"source": "remediation_change_log:325331", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/aa60e5f1/hero.webp'' -> ''/data/images/wiki/aa60e5f1/Exeter District - Stoke Hill Farm Track (geograph 3417475).webp''"}]'::jsonb),
