    ('aaf549ca-d5c7-47da-a42a-76d0806d21e9'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:aaf549ca-d5c7-47da-a42a-76d0806d21e9:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Drachenhöhle', 'a0222f326fa3fc08123f2be9cce6d2b5', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27966", "url": "remediation_change_log", "quote": "phase3:batch-0037:chunk-0003: period_start ''-500'' -> ''-65000''"}, {"source": "remediation_change_log:30478", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:81178", "url": "remediation_change_log", "quote": "phase4:p4-2023:chunk-0001: description ''A 542-metre-long cave near Mixnitz, Styria, Austria, with a 20-metre-wide entrance at 950 metres elevation, famous as one of Europe\\''s richest cave bear fossil deposits. It contains an estimated 30,000 skeletal remains of Ursus ingressus from the Pleistocene epoch. Medieval villagers mistook the bones for dragon remains, giving rise to the legend of the \"Dragon Slayer of Mixnitz\". During WWI-era phosphate mining (1918-1923), Paleolithic stone tools and hearth remains of the Aurignacian culture dated to 67,000-33,000 years ago were unearthed, ranking among the oldest evidence of human presence in Austria. Protected as a natural monument since 1949.'' -> ''Drachenhöhle or Drachenhöhle Mixnitz is a 542 m long cave with a 20 m wide and 12 m high entrance near Mixnitz, Styria, Austria, south-east of Bruck an der Mur located at an elevation of 950 m above sea level [1]. The cave is one of the largest caves in the Alps where bears occupied an area that stretched over a length of way over 500 m, by an average width of up to 40 m and a height of 10 to 15 m [1]. Due to a shortage of fertilizers during and after World War I the 8 to 10 m high sediments inside the cave were intensively mined between 1918 and 1923 of which around 2,500 tons of phosphoric acid were extracted [1]. During the fertilizer mining, several geologists and paleontologists were present, who only documented the most valuable discoveries [1]. Nonetheless, a rich cache of cave bear, Eurasian cave lion, Gray wolf, Alpine ibex and Alpine marmot fossils, remains of open hearths and Paleolithic stone tools of the Aurignacian culture dated to 65,000 to 31,000 BCE were unearthed [1].''"}, {"source": "remediation_change_log:105244", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:105245", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_start ''-65000'' -> None"}, {"source": "remediation_change_log:158427", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''/data/images/wiki/aaf549ca/hero.webp'' -> ''/data/images/wiki/aaf549ca/Drachenhöhle Blick einwärts.webp''"}, {"source": "remediation_change_log:241646", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:241647", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_start None -> ''-65000''"}, {"source": "remediation_change_log:315667", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-011: thumbnail_url ''/data/images/wiki/aaf549ca/Drachenhöhle Blick einwärts.webp'' -> ''/data/images/wiki/