    ('ab0a09e4-2350-42b5-b864-6a9330e4670f'::uuid, 'mystery', '4', '5', 'card-stats-2026-11-05-rollback:ab0a09e4-2350-42b5-b864-6a9330e4670f:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Birkrigg Stone Circle', '41c0e227556fe0b4ae17e7ae261efb8e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''Stone circle'', ''3000 - 1500 BC'') is shared by 57 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44929", "url": "remediation_change_log", "quote": "phase4:p4-0103:chunk-0001: description \"A Bronze Age double stone circle on Birkrigg Common, 3.2 km south of Ulverston in Cumbria, dating to 1700-1400 BC. Also known as the Druid''s Temple, it consists of an outer ring of 15 stones measuring 26 m across and an inner ring of 10 stones spanning 9 m, none taller than 0.6 m. Excavations in 1911 uncovered two layers of cobble pavement beneath which five cremation burials were found, three in pits, one on cobbles, and one covered by an inverted urn. A 1921 dig yielded small stone implements including a possible pestle and red ochre, suggesting ceremonial use.\" -> ''The Birkrigg stone circle is a Bronze Age stone circle on Birkrigg Common, two miles south of Ulverston in the English county of Cumbria [1]. The circle consists of two rings of stones, the inner being 8.5 m wide and consisting of 12 stones varying between 0.3 m and 0.9 m tall and the outer measuring 26 m and consisting of 20 smaller stones [1]. Limited excavation within the inner circle in 1911 found an upper and lower pavement of cobbles [1]. Below the lower layer of cobbles five cremations were uncovered, three in pits, one on a layer of cobbles and one covered by an inverted urn [1]. A second excavation in 1921 produced a few small stone implements which the excavator thought might be a pestle, a palate and a piece of red ochre, and which might therefore have had a ceremonial use [1].''"}, {"source": "remediation_change_log:158436", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''/data/images/wiki/ab0a09e4/hero.webp'' -> ''/data/images/wiki/ab0a09e4/Birkrigg stone circle - panoramio - jolmartyn (1).webp''"}, {"source": "remediation_change_log:323583", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-002: thumbnail_url ''/data/images/wiki/ab0a09e4/Birkrigg stone circle - panoramio - jolmartyn (1).webp'' -> ''/data/images/wiki/ab0a09e4/hero.webp''"}, {"source": "remediation_change_log:325332", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/ab0a09e4/hero.webp'' -> ''/data/images/wiki/ab0a09e4/Birkrigg stone circle.webp''"}]'::jsonb),
