    ('ab20e4ad-f101-4b3d-84fb-c0710060c941'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:ab20e4ad-f101-4b3d-84fb-c0710060c941:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Heel Stone', '8e707be283391c3d1c241906e3ea8e25', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -3000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86652", "url": "remediation_change_log", "quote": "phase4:p4-2148:chunk-0001: description \"The Heel Stone is a massive sarsen monolith standing within the Avenue outside Stonehenge''s entrance in Wiltshire, England. Rising 4.7 metres above ground with 1.2 metres buried below, it weighs approximately 35 tons and leans 27 degrees southwest, positioned 77.4 metres from the stone circle''s centre [1]. The sub-rectangular stone has a girth of 7.6 metres and is surrounded by the Heelstone Ditch [1].\" -> ''The Heel Stone is a single large block of sarsen stone standing within the Avenue outside the entrance of the Stonehenge earthwork in Wiltshire [1]. It has a minimum thickness of 2.4 metres, rising to a tapered top about 4.7 metres high [1]. Excavation has shown that a further 1.2 metres is buried in the ground [1]. It is 77.4 metres from the centre of Stonehenge circle [1]. It leans towards the southwest nearly 27 degrees from the vertical [1]. The stone has an overall girth of 7.6 metres and weighs about 35 tons [1]. It is surrounded by the Heelstone Ditch [1].''"}, {"source": "remediation_change_log:105248", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s015: period_