    ('ac28b46b-542e-48b7-adf9-32da0efd74c1'::uuid, 'mystery', '8', '10', 'card-stats-2026-11-05-rollback:ac28b46b-542e-48b7-adf9-32da0efd74c1:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Ancon Archaeological Site', '260e4884510d69f15cea06eff4f4bd41', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Necropolis/tombs complex'', ''< 4500 BC'') is shared by 3 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86676", "url": "remediation_change_log", "quote": "phase4:p4-2149:chunk-0001: description \"One of Peru''s most important archaeological sites, located on the central coast in the Bay of Ancon, with evidence of continuous human occupation spanning 10,000 years from the preceramic period through Inca times. Its vast pre-Hispanic necropolis, one of the largest in the Andes, yielded thousands of burials with tattooed bodies, copper ornaments, and richly colored textiles. First major excavations by Wilhelm Reiss and Alphons Stubel in 1875 are considered pioneering work in Peruvian scientific archaeology.\" -> ''Ancon is an archaeological site in the north of the Bay of Ancon, in the Ancón District, on the central coast of Peru [1]. It is one of the most important centers of the Peruvian archeology and features a vast necropolis of the pre-Hispanic era, with countless funerary sites [1]. Permanent occupation in Ancon is documented throughout all periods of Andean history [1]. The oldest evidence of human occupation dates back 10,000 years ago to the preceramic period [1]. In 1870, during the construction of the railroad from Ancon to Pasamayo, the first large ancient tombs were discovered here [1]. In 1875, German scholars Wilhelm Reiss and Alphons Stubel visited in the area, and made several excavations in and around the area of the necropolis [1]. In the Archaic period, sedentary fishermen and collectors of seafood and shellfish lived in the Bay of Ancon; this is evidenced by the presence of large middens, specifically in the area of Las Colinas [1].''"}, {"source": "remediation_change_log:105923", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:105924", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''-8000'' -> None"}, {"source": "remediation_change_log:105925", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: site_type ''City/town/settlement'' -> ''Necropolis''"}, {"source": "remediation_change_log:158479", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''/data/images/wiki/ac28b46b/hero.webp'' -> ''/data/images/wiki/ac28b46b/Necrópolis de Ancón Vista 3.webp''"}, {"source": "remediation_change_log:241665", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:241666", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_start None -> ''-8000''"}, {"source": "remediation_change_log:356152", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Necropolis'' -> ''Necropolis/tombs complex''"}]'::jsonb),
