    ('acec1746-35a0-4d0e-be03-1d240bad074c'::uuid, 'mystery', '5', '10', 'card-stats-2026-11-05-rollback:acec1746-35a0-4d0e-be03-1d240bad074c:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on El Temblor', '472c7b5f5aa8dd3c6ee9cc5af241752b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''City/town/settlement'', ''500 - 1000 AD'') is shared by 40 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86686", "url": "remediation_change_log", "quote": "phase4:p4-2149:chunk-0001: description \"A medium-sized Maya settlement about 18 km south of Tikal in Guatemala''s Peten department, first recorded by Ian Graham in 1974. The site consists of at least three architectural groups (A, B, C) arranged on a north-south axis, with Group A containing a pyramid exceeding 10 metres in height. The most notable find is Stela 1, an Early Classic monument measuring 119 cm high with three carved surfaces recording a possible coronation event and referencing the ruler Chak Tok Ich''aak. The stela was looted and sawn apart; fragments are now in museums in Durham, North Carolina and Las Vegas, Nevada.\" -> \"El Temblor is an archaeological site in Petén Department, Guatemala which was once the location of a settlement of the Maya civilization [1]. First recorded in 1974 by Ian Graham of Harvard University''s Peabody Museum, the site represents a medium-sized and compact settlement about 18 kilometres (11 mi) south-south-east of the ruined Mayan city of Tikal and about 13 kilometres (8.1 mi) north-east of the ruins of Ixlu [1]. It is situated in a wooded area called Paso del Carmen [1]. The ruins at El Temblor consist of at least three groups of collapsed structures or platforms on a north-south axis [1]. The northernmost group, designated as Group A, is clustered in a wooded hilltop and includes a pyramid standing over 10 metres (33 ft) high [1]. A damaged stela stands east of the pyramid [1]. Group B is located in a lower and flatter area to the south and includes at least five mounds or platforms [1]. Group C is located further south along the site''s main axis and comprises eight structures on a hill, possibly representing temples and palaces [1].\""}, {"source": "remediation_change_log:105949", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:105950", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''500'' -> None"}, {"source": "remediation_change_log:105951", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:241677", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:241678", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_start None -> ''600''"}, {"source": "remediation_change_log:241679", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: site_type None -> ''Settlement''"}, {"source": "remediation_change_log:356154", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
