    ('ad16f637-fa0c-4920-bfae-7a53dee2593a'::uuid, 'cultural_influence', '8', '6', 'card-stats-2026-11-05-rollback:ad16f637-fa0c-4920-bfae-7a53dee2593a:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''6'' restored on Tal-Barrani', '498b20055b6718da46067e79e23960c7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 8 from description yes, thumbnail yes, 3 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37233", "url": "remediation_change_log", "quote": "phase4:p4-0050:chunk-0001: description ''Tal-Barrani is an agricultural area in southeastern Malta extending from Zejtun to Santa Lucija, Hal Tarxien, and Hal Ghaxaq, containing significant archaeological remains. The site includes an ancient tomb cluster and field systems at Tal-Hotba, along with late Roman and Byzantine catacombs dating to around the 3rd century AD. A Christian catacomb and four rock-cut tombs were discovered in 1915, 1963, and 1993. The Tal-Barrani catacomb was the first in Malta to be examined scientifically, preserving intact burial strata. By 2009, fourteen rock-cut tombs had been found and partially studied.'' -> ''Tal-Barrani contains a significant number of archaeological remains [1]. These include an ancient tomb cluster and field systems at the Tal-Ħotba site at Tal-Barrani, and a number of late Roman and Byzantine catacombs [1]. Three ancient Punic rock-cut tombs were uncovered and investigated by the Museums Department in 1965 and 1966 in the Tal-Ħotba area of Tal-Barrani [1]. The tombs were uncovered during the construction of a milk depot on previously undeveloped agricultural land [1]. In May 1993, an important Late Roman to Byzantine burial site was uncovered during trenching works along Tal-Barrani road [1]. Two subterranean burial monuments were discovered within 10.0 metres from each other [1]. These were a multi-chambered burial catacomb, and a Late Roman rock-cut chamber tomb [1].''"}, {"source": "remediation_change_log:105959", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:105960", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''1'' -> None"}, {"source": "remediation_change_log:105961", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:158501", "url": "remediation_change_log", "quote": "served-image-2026-09-30-023: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/f/fe/Niche_of_the_Annunciation%2C_Tarxien.jpg'' -> None"}, {"source": "remediation_change_log:241686", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: site_type None -> ''Necropolis/tombs complex''"}, {"source": "remediation_change_log:251955", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:251956", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_start None -> ''-800''"}, {"source": "remediation_change_log:324477", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-003: thumbnail_url None -> ''/data/images/wiki/ad16f637/hero.webp''"}, {"source": "remediation_change_log:325986", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/ad16f637/hero.webp'' -> ''/data/images/wiki/ad16f637/Niche of the Annunciation, Tarxien.webp''"}, {"so