    ('ad4967fa-1303-4b2c-822e-de70130f841b'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:ad4967fa-1303-4b2c-822e-de70130f841b:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Nine Stones Close', '20df8dcdc4a09ba6004c79716bcd0491', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2900"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37251", "url": "remediation_change_log", "quote": "phase4:p4-0051:chunk-0001: description ''A late Neolithic to early Bronze Age stone circle on Harthill Moor in Derbyshire, also known as the Grey Ladies, so called because the stones supposedly represent ladies who dance at midnight. The circle originally measured about 13.7 metres (45 feet) in diameter; by the mid-19th century seven stones remained, but today only four stand. The stones are the tallest in Derbyshire, ranging from 1.2 to 2.1 metres in height. Excavation in 1847 by Thomas Bateman recovered pottery fragments and flints. Scheduled as a monument in 1949.'' -> ''Nine Stones Close, also known as the Grey Ladies, is a stone circle on Harthill Moor in Derbyshire in the English East Midlands [1]. The purpose of the monument is unknown [1]. Nine Stones Close originally measured 13.7 metres in diameter [1]. In the mid-19th century it had seven stones in its ring, although by the early 21st century that number had declined to four [1]. There are two carved cup marks, a form of rock art, evident on one of the remaining stones [1]. In 1877, William Greenwell and Llewellynn Jewitt excavated at the site, and in the late 1930s the Derbyshire Archaeological Society set two of the orthostats standing again [1].''"}, {"source": "remediation_change_log:105966", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:105967", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:159059", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/e/eb/Nine_Stones_Close_stone_circle_on_Harthill_Moor.jpg'' -> ''/data/images/wiki/ad4967fa/Nine_Stones_Close,_Derbyshire;_removed_upright_in_field_gate.webp''"}, {"source": "remediation_change_log:251957", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251958", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_start None -> ''-4000''"}, {"source": "remediation_change_log:334696", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/ad4967fa/Nine_Stones_Close,_Derbyshire;_removed_upright_in_field_gate.webp'' -> ''/data/images/wiki/ad4967fa/hero.webp''"}, {"source": "remediation_change_log:351823", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:351824", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-4000'' -> ''-2900''"}]'::jsonb),
