    ('ae28d423-c02b-44be-b78d-7d65c99f3c3b'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:ae28d423-c02b-44be-b78d-7d65c99f3c3b:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Oakley Down Barrow Cemetery', '540c5302257ed5bcb1a96aa71cde6319', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81184", "url": "remediation_change_log", "quote": "phase4:p4-2023:chunk-0001: description ''Oakley Down Barrow Cemetery is one of the finest groups of Bronze Age round barrows on Cranborne Chase, located near Sixpenny Handley in Dorset, England. The scheduled monument comprises approximately 30 barrows of varied types including bowl, bell, and rare disc barrows, with most dating to 1400-1200 BC. Excavations revealed primary and secondary inhumations and cremations in urns, with grave goods including amber, glass and faience beads, and bronze daggers suggesting social differentiation. The site survived agricultural destruction through its protection as a royal hunting ground.'' -> \"Oakley Down Barrow Cemetery is a group of Bronze Age round barrows on Cranborne Chase, about 1 mile east of the village of Sixpenny Handley in Dorset, England [1]. The presence of Wor Barrow, a Neolithic long barrow nearby to the west, may have been influential in the construction of the Oakley Down cemetery [1]. There are about 30 barrows [1]. Many of the barrows were excavated in the early 19th century by Sir Richard Colt Hoare and William Cunnington; the barrows investigated can be identified from Hoare''s numbered plan [1]. The barrows contained primary and secondary inhumations, and primary and secondary cremations in urns and cists [1]. Grave goods included beads of amber, glass and faience, and bronze daggers [1].\""}, {"source": "remediation_change_log:105987", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:105988", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:159089", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/96/Oakley_disc_barrow_panorama.jpg'' -> ''/data/images/wiki/ae28d423/hero.webp''"}, {"source": "remediation_change_log:251967", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251968", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_start None -> ''-4000''"}, {"source": "remediation_change_log:345717", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:345718", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
