    ('b0a89bee-ba85-4f69-a396-2d30707ff1e7'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:b0a89bee-ba85-4f69-a396-2d30707ff1e7:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Columns of Rajajil', '4208f406816dcf4ba711eebfc1a8b7bf', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Megalithic stones'', ''4500 - 3000 BC'') is shared by 17 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37271", "url": "remediation_change_log", "quote": "phase4:p4-0051:chunk-0001: description \"The Columns of Rajajil are an archaeological site in Saudi Arabia''s Al Jawf Region, comprising 50 groups of upright sandstone pillars near Qara south of Sakakah. Some pillars exceed 3 meters in height and are about 60 cm thick. The site is thought to be approximately 6,000 years old. Some columns bear Thamudic inscriptions.[1]\" -> ''The Columns of Rajajil is an archaeological site of sandstone pillars in the Al Jawf Region of Saudi Arabia, dated to the Chalcolithic period approximately 6,000 years ago [1]. Sometimes popularly described as \"the Stonehenge of Saudi Arabia,\" the site comprises 54 groups of trimmed stone pillars, each group containing between two and 19 pillars, distributed across a wide sandy plain in the Qara suburb southeast of Sakakah [1]. The site is named Rajajil from a local Arabic term meaning \"men,\" as the standing columns are said to resemble a gathering of human figures when viewed from a distance [1]. Excavations carried out by the Saudi General Administration of Antiquities and Museums between 1975 and 1976 recovered stone tools — including scrapers, awls, and blades — as well as a quantity of pottery fragments, confirming a date in the Copper Age of the fourth millennium BC [1]. Further documented finds at the site include obsidian stones, sandstone vessels, burnt ornaments, necklaces, and beads of metal, shell, and bone, alongside fan scrapers [1].''"}, {"source": "remediation_change_log:159155", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''/data/images/wiki/b0a89bee/hero.webp'' -> ''/data/images/wiki/b0a89bee/Rajajil standing columns, al-Jouf, 6th - 5th millenia BCE (1).webp''"}, {"source": "remediation_change_log:315767", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-011: thumbnail_url ''/data/images/wiki/b0a89bee/Rajajil standing columns, al-Jouf, 6th - 5th millenia BCE (1).webp'' -> ''/data/images/wiki/b0a89bee/أعمدة_الرجاجيل_2.webp''"}]'::jsonb),
