    ('b10227e6-8a83-4290-8503-ec037e4bc3c3'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:b10227e6-8a83-4290-8503-ec037e4bc3c3:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Devil''s Jumps, Treyford', '2b293884dbdd0babb160d6f419539050', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37295", "url": "remediation_change_log", "quote": "phase4:p4-0052:chunk-0001: description \"The Devil''s Jumps are a group of five large Bronze Age bell barrows on the South Downs, 1.2 km southeast of Treyford in West Sussex, considered the best-preserved barrow cemetery on the South Downs. The barrows range from 20-26 metres in central diameter with overall mound diameters of 37-45 metres and heights of 2.7-5.3 metres. Their linear alignment runs northeast to southwest, oriented with sunset on Midsummer Day. Excavations in 1853 recovered cremated human bone from ground surfaces between the mounds. Listed as a Scheduled Ancient Monument and Local Nature Reserve, the site provides valuable insight into Bronze Age burial traditions and social organization in southern England.\" -> \"The Devil''s Jumps are a group of five large bell barrows situated on the South Downs 1.2 kilometres south-east of Treyford in the county of West Sussex in southern England [1]. Most barrows along the South Downs have been damaged by agriculture and treasure hunters but the Devil''s Jumps are considered to be the best preserved Bronze Age barrow group in Sussex [1]. The barrows are laid out in a line running approximately south-east to north-west [1]. The five barrows vary in diameter from 26 to 34 metres and stand up to 4.8 metres high [1]. The Devil''s Jumps have been dated to the Bronze Age and they are believed to be between three and four thousand years old [1]. The Devil''s Jumps were explored in the 19th century, when bones were found in two of the mounds, although some of the barrows contained no cremated remains at all [1]. The main line of five barrows is aligned with sunset on Midsummer Day [1].\""}, {"source": "remediation_change_log:106042", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:106043", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:159190", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''/data/images/wiki/b10227e6/hero.webp'' -> ''/data/images/wiki/b10227e6/Devils Jumps Treyford 22.webp''"}, {"source": "remediation_change_log:251991", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251992", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_start None -> ''-4000''"}, {"source": "remediation_change_log:324495", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-003: thumbnail_url ''/data/images/wiki/b10227e6/Devils Jumps Treyford 22.webp'' -> ''/data/images/wiki/b10227e6/hero.webp''"}, {"source": "remediation_change_log:325988", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/b10227e6/hero.webp'' -> ''/data/images/wiki/b10227e6/Devils Jumps Treyford 1.webp''"}, {"source": "remediation_change_log:351842", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:351843", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
    ('b10227e6-8a83-4290-8503-ec037e4bc3c3'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:b10227e6-8a83-4290-8503-ec037e4bc3c3:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Devil''s Jumps, Treyford', '2b293884dbdd0babb160d6f419539050', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''3000 - 1500 BC'') is shared by 34 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37295", "url": "remediation_change_log", "quote": "phase4:p4-0052:chunk-0001: description \"The Devil''s Jumps are a group of five large Bronze Age bell barrows on the South Downs, 1.2 km southeast of Treyford in West Sussex, considered the best-preserved barrow cemetery on the South Downs. The barrows range from 20-26 metres in central diameter with overall mound diameters of 37-45 metres and heights of 2.7-5.3 metres. Their linear alignment runs northeast to southwest, oriented with sunset on Midsummer Day. Excavations in 1853 recovered cremated human bone from ground surfaces between the mounds. Listed as a Scheduled Ancient Monument and Local Nature Reserve, the site provides valuable insight into Bronze Age burial traditions and social organization in southern England.\" -> \"The Devil''s Jumps are a group of five large bell barrows situated on the South Downs 1.2 kilometres south-east of Treyford in the county of West Sussex in southern England [1]. Most barrows along the South Downs have been damaged by agriculture and treasure hunters but the Devil''s Jumps are considered to be the best preserved Bronze Age barrow group in Sussex [1]. The barrows are laid out in a line running approximately south-east to north-west [1]. The five barrows vary in diameter from 26 to 34 metres and stand up to 4.8 metres high [1]. The Devil''s Jumps have been dated to the Bronze Age and they are believed to be between three and four thousand years old [1]. The Devil''s Jumps were explored in the 19th century, when bones were found in two of the mounds, although some of the barrows contained no cremated remains at all [1]. The main line of five barrows is aligned with sunset on Midsummer Day [1].\""}, {"source": "remediation_change_log:106042", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:106043", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:159190", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''/data/images/wiki/b10227e6/hero.webp'' -> ''/data/images/wiki/b10227e6/Devils Jumps Treyford 22.webp''"}, {"source": "remediation_change_log:251991", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251992", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_start None -> ''-4000''"}, {"source": "remediation_change_log:324495", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-003: thumbnail_url ''/data/images/wiki/b10227e6/Devils Jumps Treyford 22.webp'' -> ''/data/images/wiki/b10227e6/hero.webp''"}, {"source": "remediation_change_log:325988", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/b10227e6/hero.webp'' -> ''/data/images/wiki/b10227e6/Devils Jumps Treyford 1.webp''"}, {"source": "remediation_change_log:351842", "url": "remediation_change_log", "quote": "2026-10-17a_fiel