    ('b1410fda-e006-411f-a8ce-64513976d158'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:b1410fda-e006-411f-a8ce-64513976d158:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Wet Withens', 'cf97f08d4bb6b18f35738f904956749d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:84256", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:84257", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:84258", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: site_type ''Henge'' -> ''Stone circle''"}, {"source": "remediation_change_log:86832", "url": "remediation_change_log", "quote": "phase4:p4-2153:chunk-0001: description \"Wet Withens is a Bronze Age embanked stone circle on Eyam Moor in the Derbyshire Peak District, and the largest of its type in the county. The continuous bank measures approximately 31m by 29.5m internally, with ten or eleven millstone grit uprights set at the inner edge. Seven stones remain standing, the tallest being the 0.7m ''Chair Stone'' in the northeast, which bears possible cupmarks. The circle has a notable midsummer sunrise alignment with Higgar Tor, and the Chair Stone mirrors the shape of the tor on the horizon. The site is a Scheduled Monument, also known as Eyam Moor I.\" -> \"Wet Withens is a Bronze Age henge on Eyam Moor in the Derbyshire Peak District [1]. On gritstone moorland over 300 metres above sea level, the site has clear views of the valley of the River Derwent and Higger Tor [1]. The earthen bank of Wet Withens is over 30m in diameter, making it the largest embanked stone circle in Derbyshire [1]. The ''Chair Stone'' is the tallest and most prominent stone with a ledge cut out of its face, appearing as a seat [1]. About 10m north of the henge is a large stone cairn (known as Eyam Moor Barrow) about 27m long and 1m high [1]. Near the middle of the cairn is an unusual cup-marked stone [1]. The cairn''s shape indicates that it was likely to have been a prehistoric burial barrow [1]. Wet Withens is also known as Eyam Moor 1 because there are 2 smaller stone circles about 650m to the east [1].\""}, {"source": "remediation_change_log:159199", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/5/5a/Wet_Withens_-_geograph.org.uk_-_59759.jpg'' -> ''/data/images/wiki/b1410fda/Wet Withens - geograph.org.uk - 59759.webp''"}, {"source": "remediation_change_log:251995", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:251996", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_start None -> ''-4000''"}, {"source": "remediation_change_log:351846", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:351847", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
