    ('b1a2bdd2-590d-4a2f-8168-d398739c1661'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:b1a2bdd2-590d-4a2f-8168-d398739c1661:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Marcahuamachuco', 'c12e2ed00663fae45576b28fb88de51f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Archaeological site'', ''1 - 500 AD'') is shared by 15 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29405", "url": "remediation_change_log", "quote": "phase3:batch-0283:chunk-0001: period_start ''500'' -> ''400''"}, {"source": "remediation_change_log:29406", "url": "remediation_change_log", "quote": "phase3:batch-0283:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:30483", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 - 1000 AD'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:35954", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:81212", "url": "remediation_change_log", "quote": "phase4:p4-2024:chunk-0001: description \"Marcahuamachuco is a pre-Incan archaeological complex in La Libertad Region, Peru, spanning approximately 5 square kilometres at an altitude of 3,650 metres. Named ''Town of Men with Falcon Hats'' in Quechua, construction began around 400 AD and continued to 800 AD, predating both Wari and Inca expansions. The site features massive curved fortifications of andesite stone, circular towers exceeding 10 metres in height, and over 300 monumental structures serving ceremonial and administrative functions. Often called the ''Machu Picchu of the North,'' it was northern Peru''s most important political and military centre before Inca conquest in the 14th century.\" -> \"Marcahuamachuco is an archeological site of Pre-Incan ruins in the La Libertad Region of Peru [1]. Construction of Marcahuamachuco began around AD 400, during the Andean Middle Horizon period and continued until approximately 800 AD [1]. Before being conquered by the Incas in the 14th century, Marcahuamachuco was known as northern Peru''s most important political, economic and military center [1]. The first formal archaeological research in Marcahuamachuco was conducted during three months in 1900 by Max Uhle and Julio C. Tello under the auspices of the University of California, Berkeley [1]. Marcahuamachuco is set atop the nexus of three mountain valleys at an altitude of more than 3,200 meters [1]. Encompassing more than three kilometres of land, the site is celebrated for its massive castillos and unique circular double-walled archaeological structures [1]. The domestic residences are multi-storied galleries which originally housed numerous individual families [1].\""}, {"source": "remediation_change_log:106056", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:159204", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''/data/images/wiki/b1a2bdd2/hero.webp'' -> ''/data/images/wiki/b1a2bdd2/Marcahuamachuco - La Portada Oeste.webp''"}, {"source": "remediation_change_log:241736", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: site_type None -> ''Archaeological site''"}, {"source": "remediation_change_log:315794", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-011: thumbnail_url ''/data/images/wiki/b1a2bdd2/Marcahuamachuco - La Portada Oeste.webp'' -> ''/data/images/wiki/b1a2bdd2/Marcahuamachuco-_Detalles_de_muros_del_Castillo.webp''"}]'::jsonb),
