    ('b1e7b190-e66c-49da-8df8-2b1345fa68fd'::uuid, 'mystery', '2', '6', 'card-stats-2026-11-05-rollback:b1e7b190-e66c-49da-8df8-2b1345fa68fd:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Tiwanaku', '67d974da9aff2759bce54a2bc49f2f3a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 2 from (''City/town/settlement'', ''1 - 500 AD'') is shared by 180 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27864", "url": "remediation_change_log", "quote": "phase3:batch-0020:chunk-0002: period_start ''1'' -> ''110''"}, {"source": "remediation_change_log:35955", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''110'' -> ''1''"}, {"source": "remediation_change_log:43645", "url": "remediation_change_log", "quote": "phase4:p4-0078:chunk-0001: description ''Tiwanaku is a Pre-Columbian archaeological site in western Bolivia, near Lake Titicaca, about 70 kilometers from La Paz[1]. Surface remains cover around 4 square kilometers (2.4 sq mi) and include decorated ceramics, monumental structures, and megalithic blocks[1]. It was one of the largest sites in South America and has been conservatively estimated to have supported 10,000 to 20,000 inhabitants around AD 800[1].'' -> ''Tiwanaku is a Pre-Columbian archaeological site in western Bolivia, near Lake Titicaca, about 70 kilometers from La Paz, and it is one of the largest sites in South America [1]. Tiwanaku began its steady growth in the early centuries of the first millennium AD [1]. At its height, the city of Tiwanaku spanned an area of roughly 4 square kilometers and had a population greater than 10,000 individuals [1]. The structures that have been excavated by researchers at Tiwanaku include the terraced platform mound Akapana, Akapana East, and Pumapunku stepped platforms, the Kalasasaya, the Kantatallita, the Kheri Kala, and Putuni enclosures, and the Semi-Subterranean Temple [1]. Tiwanaku became a center of pre-Columbian religious ceremonies for both the general public and elites [1]. Excavations of the Akapana at Tiwanaku revealed the remains of sacrificial dedications of humans and camelids [1]. Today Tiwanaku has been designated as a UNESCO World Heritage Site [1].''"}, {"source": "remediation_change_log:122915", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: site_type ''Temple complex'' -> ''City''"}, {"source": "remediation_change_log:159208", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/e/e3/Slune%C4%8Dn%C3%AD_br%C3%A1na_-_Puerta_del_Sol%2C_Tiwanaku_-_panoramio_%281%29.jpg'' -> ''/data/images/wiki/b1e7b190/Tiwanaku_-_Puerta_de_la_Luna_-_panoramio.webp''"}, {"source": "remediation_change_log:332846", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-006-002: thumbnail_url ''/data/images/wiki/b1e7b190/Tiwanaku_-_Puerta_de_la_Luna_-_panoramio.webp'' -> ''/data/images/wiki/b1e7b190/Sluneční brána - Puerta del Sol, Tiwanaku - panoramio (1).webp''"}, {"source": "remediation_change_log:356162", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
