    ('b27d56e3-58e8-4ee7-b32f-2f7d58d737ed'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:b27d56e3-58e8-4ee7-b32f-2f7d58d737ed:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Trou de l''Abîme', '97fc767c49a062557d601dcb8bdf4deb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -42550"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44961", "url": "remediation_change_log", "quote": "phase4:p4-0104:chunk-0001: description \"Trou de l''Abîme (Couvin Cave) is a karst cave in Wallonia, Belgium, on the right bank of the Eau Noire river in Couvin, Namur province[1]. Excavations uncovered Mousterian stone tools and a Neanderthal molar, indicating repeated Neanderthal occupation during the Middle Paleolithic[1].\" -> \"Trou de l’Abîme also known as La caverne de l''Abîme and Couvin Cave is a karst cave located in Wallonia on the right bank of the Eau Noire river in the center of Couvin, Belgium, in Namur province [1]. The site consists of a large two level cave with the entrance on the upper level of the western face of an Eifelian limestone cliff and a large terrace which forms a rock shelter of 50 m width and 5 m depth [1]. Excavations of the cave entrance were first conducted in 1887 and 1902 but the evidence recovered from these is lost [1]. In a series of excavations between 1984 and 1985 Palaeolithic stone artifacts and Pleistocene faunal remains were uncovered [1]. Most of the lithic material is flint which had to be transported to the site from a mine at least 30 km away [1]. Associated with the material was a partial human molar [1]. At the time it was found scientists were unable to determine whether it was Homo sapiens or Neanderthal [1].\""}, {"source": "remediation_change_log:106072", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:106073", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''-50000'' -> None"}, {"source": "remediation_change_log:159254", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/7/7f/Abime_Couvin.jpg'' -> ''/data/images/wiki/b27d56e3/hero.webp''"}, {"source": "remediation_change_log:252339", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:252340", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''-500''"}, {"source": "remediation_change_log:351850", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:351851", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-500'' -> ''-42550''"}]'::jsonb),
