    ('b2a97f1e-1f85-4f7f-97d0-38da53be836a'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:b2a97f1e-1f85-4f7f-97d0-38da53be836a:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Tibradden Mountain', '987e0c1a966aed7b4153cc08f6fcd46a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37301", "url": "remediation_change_log", "quote": "phase4:p4-0052:chunk-0001: description \"A prehistoric burial cairn crowning the 467-metre summit of Tibradden Mountain in County Dublin. Possibly Neolithic in origin but reused during the Bronze Age, the cairn features a centrally placed stone-lined cist and a partially lintelled passage within a circular chamber about 3 metres in diameter. Excavated in 1849 by members of the Royal Irish Academy, the cist yielded a Bronze Age food vessel and cremated human remains, now held by the National Museum of Ireland. Restored in the 1950s, the cairn became a national monument in 1940. Locally known as Niall Dhu''s grave, it is traditionally associated with the High King Niall Glundub (d. AD 919).\" -> ''Tibradden Mountain is a mountain in County Dublin, Ireland [1]. The mountain is also a site of archaeological interest with a prehistoric burial site close to the summit [1]. Local tradition associates it, incorrectly, with Niall Glúndub [1]. It was excavated in 1849 by members of the Royal Irish Academy who found a stone-lined cist containing a pottery vessel and cremated remains, now preserved by the National Museum of Ireland in Dublin [1].''"}, {"source": "remediation_change_log:122925", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:122926", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:122927", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: source_url ''https://en.wikipedia.org/wiki/Tibradden_Mountain'' -> ''https://de.wikipedia.org/wiki/Tibradden_Cairn''"}, {"source": "remediation_change_log:159258", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/f/f0/Tibradden_Chambered_Cairn.jpg'' -> ''/data/images/wiki/b2a97f1e/Tibradden Passage Grave.webp''"}, {"source": "remediation_change_log:252341", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:252342", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''-4000''"}, {"source": "remediation_change_log:315819", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-011: thumbnail_url ''/data/images/wiki/b2a97f1e/Tibradden Passage Grave.webp'' -> ''/data/images/wiki/b2a97f1e/Tibradden_Chambered_Cairn.webp''"}, {"source": "remediation_change_log:351852", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:351853", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
