    ('b3b17110-a61a-43c1-8962-7c8f71947f52'::uuid, 'mystery', '7', '6', 'card-stats-2026-11-05-rollback:b3b17110-a61a-43c1-8962-7c8f71947f52:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Cotzumalhuapa', '79339e0774eeef4d19b98118a32ed708', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Archaeological site'', ''1500 - 500 BC'') is shared by 9 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37309", "url": "remediation_change_log", "quote": "phase4:p4-0052:chunk-0001: description ''Cotzumalhuapa is a pre-Columbian Maya archaeological zone in the piedmont of Escuintla Department, Guatemala, near Santa Lucía Cotzumalguapa[1]. Occupied from the Middle Preclassic period (c. 1000 BC) through the Late Classic period (c. 900 AD), it is known for monumental architecture and elaborate stone carvings[1][2]. The site features large carved stone pillars (stelae) and altars, with notable examples depicting deities and elite figures[2]. Cotzumalhuapa represents a major Maya center in the Pacific coastal piedmont, demonstrating cultural connections between highland and lowland Maya regions[1][3].'' -> ''The Cotzumalhuapa archaeological zone is a pre-Columbian Maya archaeological zone dating mainly to the Late Classic period in Mesoamerican chronology, although it was occupied since the Middle Preclassic period and there is evidence of a major development during the Late Preclassic period [1]. Cotzumalhuapa is located on the Pacific piedmont of southern Guatemala, in the Escuintla Department, on the outskirts of modern Santa Lucia Cotzumalguapa [1]. During the Late Classic period, Cotzumalhuapa was a major city that extended more than 10 square kilometres [1].''"}, {"source": "remediation_change_log:106102", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:106103", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:106104", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:241760", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: site_type None -> ''Archaeological site''"}, {"source": "remediation_change_log:252365", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:252366", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''-1500''"}]'::jsonb),
