    ('b3f1d305-9a29-43e9-ba1f-023b13ecbe6f'::uuid, 'mystery', '1', '6', 'card-stats-2026-11-05-rollback:b3f1d305-9a29-43e9-ba1f-023b13ecbe6f:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Danish Camp', '733f185ec04b75e55adbf955703a8120', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''500 BC - 1 AD'') is shared by 316 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28404", "url": "remediation_change_log", "quote": "phase3:batch-0126:chunk-0002: period_start ''-2000'' -> ''-400''"}, {"source": "remediation_change_log:30488", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''3000 - 1500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:81220", "url": "remediation_change_log", "quote": "phase4:p4-2024:chunk-0001: description ''Danish Camp is an Iron Age fortified settlement in Shoeburyness, Essex, classified as a Scheduled Monument and one of only about 150 slight univallate hillforts recorded in Britain. The fort originally enclosed a sub-rectangular coastal area approximately 450 metres long. A 1998 excavation sampling 4% of the interior revealed four roundhouses, boundary ditches, post-built structures, and evidence of spinning, weaving, salt manufacture, and cereal processing, dating the main occupation to the Middle Iron Age (c. 400-200 BCE). Despite its name suggesting Viking origins, the earthwork predates the Vikings by over a millennium.'' -> \"Danish Camp is an Iron Age fortified settlement in Shoeburyness in Essex [1]. The site is in the Gunners Park and Shoebury Ranges nature reserve [1]. This site is classed by Natural England as a ''slight univallate hillfort'' [1]. There are two sections remaining of the defensive banks of the settlement [1]. The surviving part of the north-western bank is around 80 metres long, and it has an average height of 2 metres and width of 11 metres [1]. Pottery vessels have been found dating to the Middle Iron Age, around 400 to 200 years BC, together with four round houses and many post holes and pits [1]. The site is called the Danish Camp because it was thought to have been constructed by the Danish Viking leader Hastein, who is reported by the Anglo-Saxon Chronicle to have built a fort at Shoebury in 894; though he might have re-used the existing camp, no evidence has been found of Viking occupation [1].\""}, {"source": "remediation_change_log:106121", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:106122", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''-400'' -> None"}, {"source": "remediation_change_log:106123", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: site_type ''City/town/settlement'' -> ''Settlement''"}, {"source": "remediation_change_log:159909", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''/data/images/wiki/b3f1d305/hero.webp'' -> ''/data/images/wiki/b3f1d305/Danish Camp 3.webp''"}, {"source": "remediation_change_log:241771", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:241772", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_start None -> ''-400''"}, {"source": "remediation_change_log:315846", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-011: thumbnail_url ''/data/images/wiki/b3f1d305