    ('b43e7f32-5f59-4370-9cf0-43c3f159e4e3'::uuid, 'mystery', '2', '6', 'card-stats-2026-11-05-rollback:b43e7f32-5f59-4370-9cf0-43c3f159e4e3:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on La Muerta', 'cfe132ce241bb9bf0c36a3c98704b463', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 2 from (''City/town/settlement'', ''1 - 500 AD'') is shared by 180 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37313", "url": "remediation_change_log", "quote": "phase4:p4-0052:chunk-0001: description \"La Muerta is a Maya archaeological site in northern Peten, Guatemala, situated on a promontory 3.5 km south of El Mirador''s El Tigre complex [1]. The site is considered a satellite of El Mirador, lying between it and El Tintal [1]. Occupied during the Early through Late Classic periods, the site displays the architectural influence of its powerful neighbor [1]. La Muerta has suffered extensive looting that has damaged its structures [1].\" -> ''La Muerta is a Maya archaeological site in the northern Petén region of Guatemala, located between the sites of El Mirador and El Tintal [1]. It is located on a promontory 3.5 kilometres south of the El Tigre complex of El Mirador, and it is considered a satellite of that city [1]. La Muerta was inhabited during the Early to Late Classic Period [1]. La Muerta was investigated by archaeologist Richard D. Hansen in the 1980s [1]. The site is divided into North and South Groups, located approximately 400 metres apart [1]. Eleven residential areas have been identified within these two groups [1]. Structure A1 is a temple with a north-facing stairway [1]. Monument 1 is a sculptured stela that was found in the North Group [1].''"}, {"source": "remediation_change_log:122947", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:122948", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_start ''1'' -> None"}, {"source": "remediation_change_log:122949", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: site_type ''Temple complex'' -> ''Settlement''"}, {"source": "remediation_change_log:252373", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:252374", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''1''"}, {"source": "remediation_change_log:325990", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/b43e7f32/hero.webp'' -> ''/data/images/wiki/b43e7f32/La Muerta.webp''"}, {"source": "remediation_change_log:356168", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
    ('b43e7f32-5f59-4370-9cf0-43c3f159e4e3'::uuid, 'rarity_score', '28', '40', 'card-stats-2026-11-05-rollback:b43e7f32-5f59-4370-9cf0-43c3f159e4e3:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''40'' restored on La Muerta', 'cfe132ce241bb9bf0c36a3c98704b463', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 28 from mystery 2, cultural_influence 10"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37313", "url": "remediation_change_log", "quote": "phase4:p4-0052:chunk-0001: description \"La Muerta is a Maya archaeological site in northern Peten, Guatemala, situated on a promontory 3.5 km south of El Mirador''s El Tigre complex [1]. The site is considered a satellite of El Mirador, lying between it and El Tintal [1]. Occupied during the Early through Late Classic periods, the site displays the architectural influence of its powerful neighbor [1]. La Muerta has suffered extensive looting that has damaged its structures [1].\" -> ''La Muerta is a Maya archaeological site in the northern Petén region of Guatemala, located between the sites of El Mirador and El Tintal [1]. It is located on a promontory 3.5 kilometres south of the El Tigre complex of El Mirador, and it is considered a satellite of that city [1]. La Muerta was inhabited during the Early to Late Classic Period [1]. La Muerta was investigated by archaeologist Richard D. Hansen in the 1980s [1]. The site is divided into North and South Groups, located approximately 400 metres apart [1]. Eleven residential areas have been identified within these two groups [1]. Structure A1 is a temple with a no