    ('b4666064-903d-4db2-a282-38897ac4c1a1'::uuid, 'antiquity', '5', '2', 'card-stats-2026-11-05-rollback:b4666064-903d-4db2-a282-38897ac4c1a1:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''2'' restored on Dun Fiadhairt Broch', 'ff23979d02f89d862ab248ef0b05ca69', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -800"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44963", "url": "remediation_change_log", "quote": "phase4:p4-0104:chunk-0001: description ''Dun Fiadhairt is an Iron Age broch located on the north coast of the island of Skye, Scotland [1].'' -> ''Dun Fiadhairt is an Iron Age broch located on the north coast of the island of Skye [1]. The broch stands on a low, rocky knoll, in the midst of moorland, on a peninsula which juts into the east side of Loch Dunvegan [1]. The broch has an external diameter of 16.8 metres and an internal diameter of 9.6 metres [1]. Dun Fiadhairt was excavated around 1892 by the Countess Vincent Baillet de Latour [1]. Finds included a quantity of pottery, and a large amount of \"iron refuse\" [1]. Stone finds included a rotary quern, a whetstone, a hammerstone, spindle whorls and a fragment of an armlet [1]. Several glass beads were found of various colours, and in addition there were 59 amber beads in the form of short cylinders which presumably formed a necklace [1]. There was also found a baked clay object, thought to be a Roman votive model of a bale of wool [1].''"}, {"source": "remediation_change_log:106136", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:106137", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''1'' -> None"}, {"source": "remediation_change_log:159946", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''/data/images/wiki/b4666064/hero.webp'' -> ''/data/images/wiki/b4666064/Dun_Fiadhairt_Broch_Interior.webp''"}, {"source": "remediation_change_log:252377", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:252378", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''800''"}, {"source": "remediation_change_log:351872", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''500 - 1000 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:351873", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''800'' -> ''-800''"}]'::jsonb),
