    ('b50b9e02-1fb6-42e5-9850-f463acd49604'::uuid, 'antiquity', '10', '3', 'card-stats-2026-11-05-rollback:b50b9e02-1fb6-42e5-9850-f463acd49604:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Cueva Antón', 'cd4a1593ea8bbfec40b6648140564643', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -300000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86936", "url": "remediation_change_log", "quote": "phase4:p4-2156:chunk-0001: description ''Cueva Antón is a paleoanthropological site in the Region of Murcia, southeastern Spain, located about 60 km inland from Cartagena near Mula[1]. Eroded by the Río Mula, this Middle Paleolithic cave was inhabited by Neanderthals[1]. The site gained international attention in 2010 when archaeologists discovered a shell at least 43,000 years old with orange pigment adhering to it[1]. This pigment indicated the shell was used for aesthetic or symbolic purposes[1]. Together with similar finds from Cave of Los Aviones, these items were identified as the first Neanderthal jewelry discovered in Europe[1]. This represents the last known Neanderthal occupation site on the Iberian Peninsula[1].'' -> ''Cueva Antón is a paleoanthropological and archeological site in the Region of Murcia of southeast Spain [1]. The cave is located about 60 kilometers from the Mediterranean port city of Cartagena inland in the territory of the municipality of Mula [1]. It was eroded by the Río Mula and served as a cave in the Middle Palaeolithic inhabited by Neanderthals [1]. The cave became internationally known in 2010, after a shell at least 43,000 years old with adhering orange pigment was discovered there [1]. The find from the Cueva Antón was published together with similar finds from the Cave of Los Aviones; they were named as the first such Neanderthal jewelry found in Europe [1]. The rock of the cave is Eocene limestone [1]. It is at the base of a 25 meter high cliff on the bank of the Río Mula [1].''"}, {"source": "remediation_change_log:106799", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:106800", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-75000'' -> None"}, {"source": "remediation_change_log:252383", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:252384", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''1''"}, {"source": "remediation_change_log:351878", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''1 - 500 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:351879", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''1'' -> ''-300000''"}]'::jsonb),
    ('b50b9e02-1fb6-42e5-9850-f463acd49604'::uuid, 'empire_count', '0', '1', 'card-stats-2026-11-05-rollback:b50b9e02-1fb6-42e5-9850-f463acd49604:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''1'' restored on Cueva Antón', 'cd4a1593ea8bbfec40b6648140564643', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 0 from tag_site(38.064585805861526, -1.4964336746680689, period_start -300000)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86936", "url": "remediation_change_log", "quote": "phase4:p4-2156:chunk-0001: description ''Cueva Antón is a paleoanthropological site in the Region of Murcia, southeastern Spain, located about 60 km inland from Cartagena near Mula[1]. Eroded by the Río Mula, this Middle Paleolithic cave was inhabited by Neanderthals[1]. The site gained international attention in 2010 when archaeologists discovered a shell at least 43,000 years old with orange pigment adhering to it[1]. This pigment indicated the shell was used for aesthetic or symbolic purposes[1]. Together with similar finds from Cave of Los Aviones, these items were identified as the first Neanderthal jewelry discovered in Europe[1]. This represents the last known Neanderthal occupation site on the Iberian Peninsula[1].'' -> ''Cueva Antón is a paleoanthropological and archeological site in the Region of Murcia of southeast Spain [1]. The cave is located about 60 kilometers from the Mediterranean port city of Cartagena inland in the territory of the municipality of Mula [1]. It was eroded by the Río Mula and served as a cave in the Middle Palaeolithic inhabited by Neanderthals [1]. The cave became internationally known in 2010, after a shell at least 43,000 years old with adhering orange pigment was discovered there [1]. The find from the Cueva Antón was published together with similar finds from the Cave of Los Aviones; they were named as the first such Neanderthal jewelry found in Europe [1]. The rock of the cave is Eocene limestone [1]. It is at the base of a 25 meter high cliff on the bank of the Río Mula [1].''"}, {"source": "remediation_change_log:106799", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:106800", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-75000'' -> None"}, {"source": "remediation_change_log:252383", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:252384", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''1''"}, {"source": "remediation_change_log:351878", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''1 - 500 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:351879", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''1'' -> ''-300000''"}]'::jsonb),
