    ('b50b9e02-1fb6-42e5-9850-f463acd49604'::uuid, 'total_power', '21', '17', 'card-stats-2026-11-05-rollback:b50b9e02-1fb6-42e5-9850-f463acd49604:total_power', 'rollback of card-stats-2026-11-05: total_power ''17'' restored on Cueva Antón', 'cd4a1593ea8bbfec40b6648140564643', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 21 from antiquity + fortification + cultural_influence + mystery + legacy = 10 + 2 + 5 + 3 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86936", "url": "remediation_change_log", "quote": "phase4:p4-2156:chunk-0001: description ''Cueva Antón is a paleoanthropological site in the Region of Murcia, southeastern Spain, located about 60 km inland from Cartagena near Mula[1]. Eroded by the Río Mula, this Middle Paleolithic cave was inhabited by Neanderthals[1]. The site gained international attention in 2010 when archaeologists discovered a shell at least 43,000 years old with orange pigment adhering to it[1]. This pigment indicated the shell was used for aesthetic or symbolic purposes[1]. Together with similar finds from Cave of Los Aviones, these items were identified as the first Neanderthal jewelry discovered in Europe[1]. This represents the last known Neanderthal occupation site on the Iberian Peninsula[1].'' -> ''Cueva Antón is a paleoanthropological and archeological site in the Region of Murcia of southeast Spain [1]. The cave is located about 60 kilometers from the Mediterranean port city of Cartagena inland in the territory of the municipality of Mula [1]. It was eroded by the Río Mula and served as a cave in the Middle Palaeolithic inhabited by Neanderthals [1]. The cave became internationally known in 2010, after a shell at least 43,000 years old with adhering orange pigment was discovered there [1]. The find from the Cueva Antón was published together with similar finds from the Cave of Los Aviones; they were named as the first such Neanderthal jewelry found in Europe [1]. The rock of the cave is Eocene limestone [1]. It is at the base of a 25 meter high cliff on the bank of the Río Mula [1].''"}, {"source": "remediation_change_log:106799", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:106800", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-75000'' -> None"}, {"source": "remediation_change_log:252383", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:252384", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''1''"}, {"source": "remediation_change_log:351878", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''1 - 500 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:351879", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''1'' -> ''-300000''"}]'::jsonb),
    ('b539ba9e-5d7e-4ce8-a9ff-943ac3247297'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:b539ba9e-5d7e-4ce8-a9ff-943ac3247297:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Carnac Stones', 'bcf8e310c28dfd84b1579b692611bfc9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Megalithic stones'', ''4500 - 3000 BC'') is shared by 17 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86940", "url": "remediation_change_log", "quote": "phase4:p4-2156:chunk-0001: description \"The Carnac Stones are the largest collection of megalithic monuments in the world, comprising over 3,000 standing stones erected between the 5th and 3rd millennia BC by Neolithic farming communities in Brittany. The alignments stretch across 15 kilometres, with the most complete group at Le Menec featuring eleven parallel rows of stones decreasing in size eastward, terminating in stone circles. Their purpose remains debated, with theories ranging from processional ways and sacred spaces to astronomical calendars marking solstice sunrise patterns. Scientific study began in the 19th century with Scotsman J. Miln, whose student Zacharie Le Rouzic continued excavations and ensured the stones'' preservation.\" -> \"The Carnac stones are an exceptionally dense collection of megalithic sites near the south coast of Brittany in northwestern France, consisting of stone alignments, dolmens, tumuli, and single menhirs [1]. Most of the stones are within the Breton municipality of Carnac, but some to the east are within neighboring La Trinité-sur-Mer [1]. The standing stones are made of weathered granite from local outcroppings that once extensively covered the area [1]. Three exceptionally large burial mounds are known from the Carnac and Morbihan area, dating from the mid-5th millennium BC and known collectively as ''Carnacéen tumuli'': Saint-Michel, Tumiac and Mané-er-Hroëk [1]. Each of these tumuli contained a megalithic burial chamber, containing the burial of only one individual, along with numerous large polished stone axeheads, stone arm-rings, and jewellery made from callaïs [1]. Scientific analyses have shown that many of the axeheads are made of jade from the Italian Alps, whilst the callaïs was imported from south-western Iberia [1].\""}, {"source": "remediation_change_log:159969", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''/data/images/wiki/b539ba9e/hero.webp'' -> ''/data/images/wiki/b539ba9e/Mégalithes_vus_depuis_la_Maison_des_Mégalithes_à_Carnac_le_1er_septembre_2019_-_2.webp''"}, {"source": "remediation_change_log:315858", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-011: thumbnail_url ''/data/images/wiki/b539ba9e/Mégalithes_vus_depuis_la_Maison_des_Mégalithes_à_Carnac_le_1er_septembre_2019_-_2.webp'' -> ''/data/images/wiki/b539ba9e/Carnac_megalith_alignment_1.webp''"}]'::jsonb),
