est end [1].''"}, {"source": "remediation_change_log:106811", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:106812", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:159978", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/1/19/Grey_Mare_and_her_Colts_-_geograph.org.uk_-_180692.jpg'' -> ''/data/images/wiki/b5958bf8/Grey Mare & Her Colts.webp''"}, {"source": "remediation_change_log:302188", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:302189", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-3400''"}]'::jsonb),
