iation_change_log:106817", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:106818", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:241785", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:241786", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_start None -> ''-2000''"}, {"source": "remediation_change_log:351880", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''3000 - 1500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:351881", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-2000'' -> None"}]'::jsonb),
