    ('b5e251e7-b1d1-46d4-8bba-b02956ff13c9'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:b5e251e7-b1d1-46d4-8bba-b02956ff13c9:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Caves of Nerja', '3941ee4ff9d6321187311916551d7481', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Rock art'', ''< 4500 BC'') is shared by 29 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27926", "url": "remediation_change_log", "quote": "phase3:batch-0031:chunk-0002: period_start ''1'' -> ''-25000''"}, {"source": "remediation_change_log:30489", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1 - 500 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:81222", "url": "remediation_change_log", "quote": "phase4:p4-2024:chunk-0001: description ''The Caves of Nerja are a series of caverns near Nerja in Malaga province, stretching nearly 5 km. Rediscovered in 1959, research shows the caves have been visited for over 41,000 years. Paleolithic cave paintings depict horses, deer, goats, seals, and fish, with some organic remains dated to 42,000 years ago, potentially the oldest art in human history. The caves were seasonally occupied from about 25,000 BC through the Bronze Age, used as shelter, residence, and burial site. Declared a Bien de Interes Cultural in 1985.'' -> ''The Caves of Nerja are a series of caverns close to the town of Nerja in the Province of Málaga, Spain [1]. The caves were re-discovered in modern times on 12 January 1959 by five friends, who entered through a narrow sinkhole known as \"La Mina\" [1]. The cave is divided into two main parts known as Nerja I and Nerja II [1]. Skeletal remains found in the caverns indicate that they were inhabited from about 25,000 BC up until the Bronze Age [1]. Cave paintings from the Paleolithic and post-Paleolithic eras have been discovered on the walls of the cave [1]. For about 4,000 years from 25,000 BC the caves were used seasonally by a small group of humans, and were occupied by cave hyena during the periods that the humans were absent [1]. By 21,000 BC the human population had taken up year-round residence in the caves and had increased in number [1].''"}, {"source": "remediation_change_log:159982", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''/data/images/wiki/b5e251e7/hero.webp'' -> ''/data/images/wiki/b5e251e7/Cueva_de_Nerja_2020.webp''"}, {"source": "remediation_change_log:332862", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-006-002: thumbnail_url ''/data/images/wiki/b5e251e7/Cueva_de_Nerja_2020.webp'' -> ''/data/images/wiki/b5e251e7/Cuevas de Nerja.webp''"}]'::jsonb),
