    ('b66e9572-4469-4d1a-b13f-b927af5d79db'::uuid, 'antiquity', '5', '6', 'card-stats-2026-11-05-rollback:b66e9572-4469-4d1a-b13f-b927af5d79db:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''6'' restored on Somma Vesuviana', '229629bf8072ba42f28e99c7b87adf23', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81240", "url": "remediation_change_log", "quote": "phase4:p4-2025:chunk-0001: description ''Somma Vesuviana hosts the remains of a monumental Roman villa on the northern flank of Vesuvius, buried by a volcanic eruption in AD 472. Discovered in the 1930s, the site was systematically excavated from 2002 by the University of Tokyo, revealing decorated rooms with Dionysiac motifs, frescoes of Nereids and Tritons, and a functioning wine cellar with earthenware jars. Ancient sources suggest Emperor Augustus died at a villa in this area in 14 AD, and recent excavations have uncovered possible traces of an Augustan-era structure beneath the 2nd-century AD villa.'' -> \"Before the Roman colonisation, the area of today''s Somma Vesuviana was probably inhabited by Italic peoples like Samnites and Oscans [1]. A large Roman villa was discovered in the 1930s in the frazione of Starza della Regina and due to its size, later interpreted as that of emperor Augustus at Nola where he probably passed his last days of life [1].\""}, {"source": "remediation_change_log:106826", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''1500 - 500 BC'' -> None"}, {"source": "reme