    ('b6aab229-8793-40ad-a697-c8dbf6e331bf'::uuid, 'cultural_influence', '8', '7', 'card-stats-2026-11-05-rollback:b6aab229-8793-40ad-a697-c8dbf6e331bf:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''7'' restored on Grovely Castle', '08400f9eb97f0f0da4a6dae3c0fff343', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 8 from description yes, thumbnail yes, 5 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:86968", "url": "remediation_change_log", "quote": "phase4:p4-2157:chunk-0001: description ''Grovely Castle is an Iron Age univallate hill fort in Steeple Langford, Wiltshire[1]. The remaining ramparts stand 3.2\\u202fm high with 1.5\\u202fm deep ditches, though ploughing has damaged some earthworks[1]. Excavations revealed five human skeletons within the ramparts[1]. The hillfort has entrances in the southwest and northeast corners, with a circular enclosure of 35–40\\u202fm visible in aerial photographs[1]. A later bank and ditch extends through the site, likely part of a broader Celtic field system[1].'' -> ''Grovely Castle is the site of an Iron Age univallate hill fort in the parish of Steeple Langford, in Wiltshire [1]. The remaining ramparts stand approximately 3.2 m high, with 1.5 m deep ditches, although ploughing has damaged the earthworks in some parts of the site [1]. Excavations have uncovered the remains of five human skeletons within the ramparts [1]. Entrances are in the south-west and north-east corners of the hillfort [1]. A circular enclosure of 35 to 40 m is evident in aerial photographs of the hillfort interior [1]. There is also a later bank and ditch which runs through the hill-fort from south-west to north-east, and is probably part of an extensive surrounding Celtic field system [1].''"}, {"source": "remediation_change_log:106832", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:106833", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:159997", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''/data/images/wiki/b6aab229/hero.webp'' -> None"}, {"source": "remediation_change_log:252397", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:252398", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''-800''"}, {"source": "remediation_change_log:324525", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-004-003: thumbnail_url None -> ''/data/images/wiki/b6aab229/hero.webp''"}, {"source": "remediation_change_log:325993", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/b6aab229/hero.webp'' -> ''/data/images/wiki/b6aab229/Grovely Castle - panoramio.webp''"}]'::jsonb),
