tion_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:106835", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-4000'' -> ''-2500''"}, {"source": "remediation_change_log:160000", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/8/85/Merrymaidens5.jpg'' -> ''/data/images/wiki/b6af84c5/The_Merry_Maidens_Penwith.webp''"}, {"source": "remediation_change_log:315882", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-011: thumbnail_url ''/data/images/wiki/b6af84c5/The_Merry_Maidens_Penwith.webp'' -> ''/data/images/wiki/b6af84c5/Merrymaidens5.webp''"}]'::jsonb),
