    ('b740c74a-83ce-4e01-a07c-87ab90574750'::uuid, 'mystery', '1', '5', 'card-stats-2026-11-05-rollback:b740c74a-83ce-4e01-a07c-87ab90574750:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Tres Islas', '43427a327dbda32b7b60bd3e726d3e20', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''500 BC - 1 AD'') is shared by 316 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29099", "url": "remediation_change_log", "quote": "phase3:batch-0238:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:35967", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:86994", "url": "remediation_change_log", "quote": "phase4:p4-2158:chunk-0001: description \"Tres Islas is a small pre-Columbian Maya archaeological site situated 20 kilometres (12 mi) north of modern Cancuen in Guatemala''s Petén Department, within the dense tropical forests of the Petén lowlands.[1] Excavations have dated the settlement to the Late Preclassic and Late Classic periods of Mesoamerican chronology, spanning roughly 400 BC to 900 AD, indicating a long-lived community in the Maya region.[1] The site''s principal feature comprises three carved stone stelae and an accompanying altar, arranged in a distinctive linear formation that mimics the design of an E-Group astronomical complex typically used for solar observations and ceremonial purposes.[1]\" -> ''Tres Islas is a small pre-Columbian Maya archaeological site 20 kilometres north of Cancuen in Petén Department, northern Guatemala [1]. The main feature of the site is a group of three Maya stelae and an altar [1]. Tres Islas is one of only a few Maya cities that erected dated monuments in the Early Classic period (c. AD 250 - 600) [1]. The early presence of the Emblem glyph that was later associated with the Late Classic Cancuen-Machaquila kingdom indicates that Tres Islas was the Early Classic capital of the kingdom [1]. Preliminary investigations in the area of Tres Islas and Cancuen revealed evidence of inhabitation from the Late Preclassic period (c.400 BC - 250 AD) through to the Late Classic (c.600-900 AD) [1]. The arrangement of the stelae and altar precisely mimics the orientation and relationships of the E-Group astronomical complex at Uaxactun, suggesting that the monument group served a similar purpose [1]. The siting of the stela-altar complex on the edge of an east-facing scarp offers a perfect location for observing the sunrise [1].''"}, {"source": "remediation_change_log:106848", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:106849", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-500'' -> None"}, {"source": "remediation_change_log:106850", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:241794", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:241795", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_start None -> ''-400''"}, {"source": "remediation_change_log:241796", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: site_type None -> ''City''"}, {"source": "re