    ('b8bf4ddf-8b56-4544-adde-843e7577320f'::uuid, 'mystery', '4', '10', 'card-stats-2026-11-05-rollback:b8bf4ddf-8b56-4544-adde-843e7577320f:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Pseira', 'b806592c63c128b3a610e5f89f885143', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''City/town/settlement'', ''4500 - 3000 BC'') is shared by 87 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87026", "url": "remediation_change_log", "quote": "phase4:p4-2159:chunk-0001: description ''Pseira is a small island in the Gulf of Mirabello, northeastern Crete, bearing the remains of a Minoan town first excavated by Richard Seager in 1906-1907. The settlement grew from the Final Neolithic through the Late Minoan IB period, comprising over 60 buildings arranged on terraces around a central town square. Notable finds include painted plaster reliefs of seated female figures from Building AC (the \"Shrine\") and evidence of stone vase manufacture and weaving. The prosperous town was violently destroyed at the end of LM IB.'' -> ''Pseira is an islet in the Gulf of Mirabello in northeastern Crete with the archaeological remains of Minoan and Mycenean civilisation [1]. The island was explored in 1906–1907 by Richard Seager and partially documented by Halvor Bagge in ink and watercolors based on photographs, and more minutely examined in 1984–1992 by Philip P. Betancourt and Costis Davaras [1]. Archaeological materials in this seaport, sited above its harbor, to which it was connected by cliffside stairs, span the period from the end of the Neolithic in the 4th millennium to the Late Bronze Age, with the cultural high point being Early Minoan to Late Minoan IB [1]. At that time the prosperous town of some 60 buildings was ranged round its open square, with a single large building that occupied one side [1]. Like many contemporary Late Minoan IB sites, it was violently destroyed, c. 1550–1450 BC [1]. The Minoan community supported itself by fishing and subsistence agriculture: They deeply tilled and terraced agricultural sites where they manured the thin limy soil with human waste from the settlement [1].''"}, {"source": "remediation_change_log:122980", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:122981", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:122982", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: site_type ''City/town/settlement'' -> ''Town''"}, {"source": "remediation_change_log:160053", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Psira_island.jpg/400px-Psira_island.jpg'' -> ''/data/images/wiki/b8bf4ddf/Bull-shaped rhyton, net, Pseira, 1500-1450 BC, AMH, 145065.webp''"}, {"source": "remediation_change_log:242634", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:242635", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-4000''"}, {"source": "remediation_change_log:356174", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Town'' -> ''City/town/settlement''"}]'::jsonb),
