    ('b8e5e38c-b300-4fdb-8ef1-ab136542504b'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:b8e5e38c-b300-4fdb-8ef1-ab136542504b:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Rock Carvings at Eidefoss', '3e1cf5f702a6d87429eb1447ca219893', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87030", "url": "remediation_change_log", "quote": "phase4:p4-2159:chunk-0001: description \"Prehistoric rock carvings located by the river Fossen in Nord-Fron municipality, Innlandet county, Norway. The site comprises two images of moose carved on a rock that may have fallen from a west-facing, nearly vertical cliff about 20 m from the river. One figure measures 31 cm and the other 35 cm. The site is classified as a hunting-related petroglyph site and is part of Norway''s broader collection of Stone Age rock art.\" -> ''The rock carvings at Eidefoss are petroglyphs located near the river Fossen in Nord-Fron Municipality in Innlandet county [1]. The carvings comprise two images of moose, one measuring 31 centimetres and the other 35 centimetres [1]. The rock on which they are carved may have fallen from a west-facing, nearly vertical cliff about 20 metres from the river [1]. When the river is at its normal levels, the rock is well away from the river [1].''"}, {"source": "remediation_change_log:106874", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:106875", "url": "remediatio