    ('b8f4c5f4-c567-4605-9f3d-9475d2db6362'::uuid, 'antiquity', '6', '7', 'card-stats-2026-11-05-rollback:b8f4c5f4-c567-4605-9f3d-9475d2db6362:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Dulan Site', '39a4e301fd2ed8b4709a01f8bd2c66af', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 6 from period_start -1050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87032", "url": "remediation_change_log", "quote": "phase4:p4-2159:chunk-0001: description ''The Dulan Site is an archaeological complex in Donghe Township, Taitung County, Taiwan, situated on a mild marine terrace. Dating back approximately 3,000 years, its artifacts are associated with the Kirin Culture. During the Japanese colonial period, a rectangular stone coffin was excavated here, and subsequent investigation by Academia Sinica revealed giant stone pile structures. The site is divided into two main areas: a stony coffin zone with preserved megalithic burial containers and a stony wall area with monumental stone constructions. Designated a third-grade historical site and protected cultural heritage, researchers believe additional sites nearby await excavation.'' -> ''The Dulan Site (traditional Chinese: 都蘭遺址; simplified Chinese: 都兰遗址; pinyin: Dōulán Yízhǐ) is an archaeological site in Dulan Village, Donghe Township, Taitung County, Taiwan [1]. During Japanese rule of Taiwan, a rectangular stony coffin was excavated in the area [1]. Further investigation by Academia Sinica led to the discovery of a giant stone pile [1]. The site and objects date back to 3,000 years ago [1]. It is now considered a cultural heritage and third grade historical site [1]. The area is divided into two areas, which are the stony coffin area and the stony wall area [1].''"}, {"source": "remediation_change_log:106877", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:106878", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:106879", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: site_type ''Necropolis/tombs complex'' -> None"}, {"source": "remediation_change_log:160056", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''/data/images/wiki/b8f4c5f4/hero.webp'' -> ''/data/images/wiki/b8f4c5f4/Dulan Stone Wall - 1.webp''"}, {"source": "remediation_change_log:242642", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: site_type None -> ''Archaeological site''"}, {"source": "remediation_change_log:252421", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:252422", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''-3000''"}, {"source": "remediation_change_log:316509", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-012: thumbnail_url ''/data/images/wiki/b8f4c5f4/Dulan Stone Wall - 1.webp'' -> ''/data/images/wiki/b8f4c5f4/Dulan_Stone_Wall_-_2.webp''"}, {"source": "remediation_change_log:351904", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''3000 - 1500 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:351905", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-3000'' -> ''-1050''"}]'::jsonb),
