    ('b9024baf-e614-498c-aa14-5c14d2c525b4'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:b9024baf-e614-498c-aa14-5c14d2c525b4:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Thibilis', 'd462f73de1d64d2b1914bb5136f38862', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29089", "url": "remediation_change_log", "quote": "phase3:batch-0237:chunk-0001: site_type ''Megalithic stones'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:84261", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:84262", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: period_start ''1'' -> None"}, {"source": "remediation_change_log:87034", "url": "remediation_change_log", "quote": "phase4:p4-2159:chunk-0001: description ''Thibilis was a Roman and Byzantine era town in ancient Numidia, located in present-day northeastern Algeria in the commune of Sellaoua Announa near Guelma (ancient Calama) [1]. The settlement depended administratively on the Roman colony of Cirta situated 57 km to the northwest, before later achieving the status of autonomous municipality [1]. Archaeological excavations conducted by Charles Albert Joly at the beginning of the 20th century uncovered a small forum, a temple, and additional buildings [1]. The site features extensive Roman and Byzantine ruins, representing nearly 500 years of continuous occupation from the 1st to the 5th century AD [1][2].'' -> ''Thibilis was a Roman and Byzantine era town in what was Numidia but is today northeast Algeria [1]. The site has extensive Roman and Byzantine ruins [1]. The numerous Latin inscriptions discovered on the site of Thibilis provided indications on the status and magistrates of this city: during the Early Empire, Thibilis was first a pagus dependent on the Cirtaian confederacy which united Cirta, Rusicade, Chullu and Milève [1]. Enjoying a certain autonomy, the city was administered by two magistri of annual mandate, assisted by one or two aediles [1]. Thibilis gained the rank of municipality headed by two duumviri between 260 and 268 which corresponds to the period estimated for the dissolution of the confederacy [1].''"}, {"source": "remediation_change_log:160057", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/4/40/Announa_-_Arc_de_triomphe_-_Mieusement.jpg'' -> ''/data/images/wiki/b9024baf/Thibilispan01.webp''"}, {"source": "remediation_change_log:252423", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:252424", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''1''"}, {"source": "remediation_change_log:316512", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-012: thumbnail_url ''/data/images/wiki/b9024baf/Thibilispan01.webp'' -> ''/data/images/wiki/b9024baf/Announa_-_Arc_de_triomphe_-_Mieusement.webp''"}, {"source": "remediation_change_log:351906", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:351907", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''1'' -> None"}]'::jsonb),
