    ('b96aa592-779d-4d93-a16f-7b09496b1139'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:b96aa592-779d-4d93-a16f-7b09496b1139:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Cave of Chufín', 'e3f9a022fb541686a70ab43a1b3135d1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Rock art'', ''< 4500 BC'') is shared by 29 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44969", "url": "remediation_change_log", "quote": "phase4:p4-0104:chunk-0001: description \"The Cave of Chufín is located in the town of Riclones in Rionansa, Cantabria, Spain, situated at the confluence of the Lamasón and Nansa rivers [1]. Several caves adorned with Paleolithic rock art dot the steep slopes above the water [1]. Chufín is one of 17 caves included in UNESCO''s World Heritage listing Cave of Altamira and Paleolithic Cave Art of Northern Spain [1]. The cave contains significant Paleolithic paintings.\" -> ''The cave of Chufín is located in the town of Riclones in Rionansa, Spain [1]. In Chufín were found different levels of occupation, the oldest being around 20000 years old [1]. The small cave has some subtle engravings and paintings of red deer, goats, and cattle, all represented very schematically [1]. Also found in the cave were many symbols [1].''"}, {"source": "remediation_change_log:160063", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''/data/images/wiki/b96aa592/hero.webp'' -> ''/data/images/wiki/b96aa592/Chufin6.webp''"}]'::jsonb),
