    ('b97f1e4c-09df-4190-aed5-22bfeb4a45cc'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:b97f1e4c-09df-4190-aed5-22bfeb4a45cc:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Carrigagulla', '773d98fdd1194a010da5e5436c8efd63', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37353", "url": "remediation_change_log", "quote": "phase4:p4-0053:chunk-0001: description ''Carrigagulla is a megalithic complex 2.9 km northeast of Ballinagree in County Cork, Ireland, set within an amphitheatre of foothills leading to the monument-rich Boggeragh Mountains. The centrepiece is Carrigagulla A, a fine axial stone circle 8.2 metres in diameter consisting of 16 standing stones (originally likely 17) ranging from 90 cm to just over 30 cm in height, encircling a central boulder. The complex also includes two stone rows -- the northeast row of five stones (four now displaced as gateposts) and a southwest row of three stones (one fallen) -- plus an ogham stone discovered during peat cutting, now housed in Cork Public Museum since 1940. The axial stone circle typology is characteristic of the Cork-Kerry megalithic tradition of the Bronze Age.'' -> ''Carrigagulla (Irish: Carraig an Ghiolla) is a megalithic complex 2.9 km north-east of Ballinagree, County Cork, Ireland [1]. Carrigagulla A is an 8-metre-diameter (26 ft) stone circle consisting of 16 standing stones circling a central slab [1]. The Carrigagulla NE stone row consists of five stones, four of which have been moved and are now used as gates [1]. The stone row at Carrigagulla SW is built from three stones, one of which has fallen [1].''"}, {"source": "remediation_change_log:122992", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:122993", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:160066", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''/data/images/wiki/b97f1e4c/hero.webp'' -> ''/data/images/wiki/b97f1e4c/Carrigagulla 0509.webp''"}, {"source": "remediation_change_log:252429", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:252430", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''-4000''"}, {"source": "remediation_change_log:334720", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/b97f1e4c/Carrigagulla 0509.webp'' -> ''/data/images/wiki/b97f1e4c/hero.webp''"}, {"source": "remediation_change_log:351910", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:351911", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-4000'' -> None"}]'::jsonb),
