    ('ba020c96-afeb-452a-8dbc-faf14155c96c'::uuid, 'antiquity', '8', '7', 'card-stats-2026-11-05-rollback:ba020c96-afeb-452a-8dbc-faf14155c96c:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Pant-y-Saer Burial Chamber', 'a8b726b82f8f2df340957775e3009621', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -3500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44983", "url": "remediation_change_log", "quote": "phase4:p4-0105:chunk-0001: description ''Pant-y-Saer is a Neolithic dolmen on Anglesey, Wales, dating to before 4500 BC. This burial chamber is partially collapsed, with its massive capstone resting on the ground at one end. Excavations revealed the remains of fifty-six individuals buried here, indicating it served as a collective burial site. The chamber sits on a scrubby hilltop near the town of Benllech in the parish of Llanfair Mathafarn Eithaf.'' -> ''Pant-y-Saer is a Neolithic dolmen near the small town of Benllech in Anglesey, Wales [1]. This burial chamber is partially collapsed with the massive capstone resting on the ground at one end [1]. The remains of fifty-six people who were buried here have been found during excavations [1]. The capstone is large, measuring about 3 m in length and breadth, with a thickness of 0.5 m; it has partially collapsed and rests with one end on the ground and the other end supported by two upright stones, one on the north side and the other on the south [1]. The chamber was originally covered with a cairn or mound, of which traces remain [1]. Excavations show that the cairn was walled at the front and may have been extended for some way at the back [1].''"}, {"source": "remediation_change_log:122997", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:122998", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_start ''-5000'' -> None"}, {"source": "remediation_change_log:160080", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/5/58/PantySaer.jpg'' -> ''/data/images/wiki/ba020c96/hero.webp''"}, {"source": "remediation_change_log:252431", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:252432", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''-3000''"}, {"source": "remediation_change_log:351912", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''3000 - 1500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:351913", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-3000'' -> ''-3500''"}]'::jsonb),
