    ('ba0ce1ee-9848-4de1-9884-0e0bb37e2abd'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:ba0ce1ee-9848-4de1-9884-0e0bb37e2abd:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Niederstotzingen', '2c23f60a9e0a76d01260f941043de136', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44985", "url": "remediation_change_log", "quote": "phase4:p4-0105:chunk-0001: description ''Niederstotzingen is notable for the nearby Vogelherd Cave in the Lone Valley, one of the most important Paleolithic sites in Europe. Excavated by Gustav Riek in 1931, the cave yielded mammoth ivory figurines from the Aurignacian period, dated to nearly 40,000 years before present, making them among the oldest known figurative artworks in the world. The carved animals include mammoth, horse, bison, and cave lion. In 2017, Vogelherd became part of the UNESCO World Heritage Site \"Caves and Ice Age Art in the Swabian Jura\".'' -> ''The region around Niederstotzingen has been inhabited since pre-historic times [1]. A Celtic Viereckschanze or \"four-sided earthworks\" has been discovered near modern Niederstotzingen [1]. From the Roman era, a villa rustica has been discovered between Niederstotzingen and Sontheim [1]. During construction in the south part of town, in 1962, a small cemetery from the later half of the 7th century was discovered [1]. The Alamannian cemetery contained the remains of several nobles as well as their animals and valuables [1].''"}, {"source": "remediation_change_log:106889", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:106890", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-35000'' -> None"}, {"source": "remediation_change_log:160103", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Hürben_Kaltenburg3.jpg/400px-Hürben_Kaltenburg3.jpg'' -> ''/data/images/wiki/ba0ce1ee/Landappbw 263023 1818 Stadtmauer Niederstotzingen.webp''"}, {"source": "remediation_change_log:252433", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:252434", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s016: period_start None -> ''-500''"}, {"source": "remediation_change_log:351914", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:351915", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-500'' -> None"}]'::jsonb),
