    ('ba33abc5-f266-4b9c-85f1-cd691699b271'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:ba33abc5-f266-4b9c-85f1-cd691699b271:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Kit''s Coty House', '23bf0acbf07f5141a97aa6d38c090c6c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27982", "url": "remediation_change_log", "quote": "phase3:batch-0042:chunk-0004: period_start ''-4500'' -> ''-4000''"}, {"source": "remediation_change_log:35973", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-4000'' -> ''-4500''"}, {"source": "remediation_change_log:87058", "url": "remediation_change_log", "quote": "phase4:p4-2160:chunk-0001: description \"Kit''s Coty House is a Neolithic chambered long barrow near Aylesford in Kent, England, constructed between 4300 and 3000 BC. Part of the Medway Megaliths, the most southeasterly group of megalithic monuments in the British Isles, it consists of three sarsen uprights in an H-shaped arrangement topped by a massive capstone measuring 13 by 9 feet. The original mound extended approximately 85 metres in length. Built as a communal burial site by early Neolithic pastoralist communities, it is maintained by English Heritage alongside nearby Little Kit''s Coty House.\" -> \"Kit''s Coty House or Kit''s Coty is a chambered long barrow near the village of Aylesford in the southeastern English county of Kent [1]. Constructed circa 4000 BCE, during the Early Neolithic period of British prehistory, today it survives in a ruined state [1]. Archaeologists have established that the monument was built by pastoralist communities shortly after the introduction of agriculture to Britain from continental Europe [1]. Although representing part of an architectural tradition of long barrow building that was widespread across Neolithic Europe, Kit''s Coty House belongs to a localised regional variant of barrows produced in the vicinity of the River Medway, now known as the Medway Megaliths [1]. Of these, it lies near to both Little Kit''s Coty House and the Coffin Stone on the eastern side of the river [1]. The surviving part of the monument represents three stones covered by a capstone [1]. The mound and flanking ditches have largely been ploughed flat but remain visible from aerial photographs [1].\""}, {"source": "remediation_change_log:106897", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:106898", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:160117", "url": "remediation_change_log", "quote": "served-image-2026-09-30-025: thumbnail_url ''/data/images/wiki/ba33abc5/hero.webp'' -> \"/data/images/wiki/ba33abc5/Kit''s Coty House 02.webp\""}, {"source": "remediation_change_log:242651", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:242652", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-4000''"}, {"source": "remediation_change_log:316534", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-012: thumbnail_url \"/data/images/wiki/ba33abc5/Kit''s Coty House 02.webp\" -> \"/data/images/wiki/ba33abc5/Kit''s_Coty_House_01.webp\""}]'::jsonb),
