    ('bc55dd6f-a972-4caa-af6a-e4e96f65d0f5'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:bc55dd6f-a972-4caa-af6a-e4e96f65d0f5:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Rillaton Barrow', 'e318b7022e1207a7550e9484a6df65a9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37389", "url": "remediation_change_log", "quote": "phase4:p4-0054:chunk-0001: description ''Rillaton Barrow is a Bronze Age round barrow on the eastern flank of Bodmin Moor in Cornwall. Excavated in 1837 by workmen searching for building stone, it revealed a stone cist burial beneath the 25-metre-wide mound containing the Rillaton Gold Cup, a bronze dagger, beads, and pottery. The cup, dating to approximately 1700-1500 BC, was crafted from a single sheet of hammered gold with horizontal concentric corrugations and a riveted handle. It is one of only seven similar gold vessels found in Europe and the best preserved, showing stylistic links to Mycenaean Greece. Now displayed at the British Museum alongside the similar Ringlemere Cup, it still belongs to the Royal Collection.'' -> ''The Rillaton Barrow is a Bronze Age round barrow in Cornwall [1]. The site is on the eastern flank of Bodmin Moor in the parish of Linkinhorne about four miles north of Liskeard [1]. Rillaton Barrow was excavated in 1837 and found to contain a centrally-placed inhumation beneath the 34-metre wide barrow [1]. The burial had been placed in a stone cist measuring 2 meters by almost 1 meter [1]. Human remains were found along with grave goods including the Rillaton Gold Cup, a bronze dagger, beads, pottery, glass and other items [1]. Most notably, the burial contained the Rillaton Gold Cup, a biconical gold vessel, around 9 cm high, with a handle attached with rivets [1].''"}, {"source": "remediation_change_log:106944", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:106945", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:160676", "url": "remediation_change_log", "quote": "served-image-2026-09-30-026: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/ac/Blocked_up_entrance_to_Rillaton_Barrow.JPG'' -> ''/data/images/wiki/bc55dd6f/Blocked_up_entrance_to_Rillaton_Barrow.webp''"}, {"source": "remediation_change_log:252781", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:252782", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-4000''"}, {"source": "remediation_change_log:351922", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:351923", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
