    ('bcefdb51-0003-46f4-806a-9bfca2b630e1'::uuid, 'antiquity', '5', '7', 'card-stats-2026-11-05-rollback:bcefdb51-0003-46f4-806a-9bfca2b630e1:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Glassonby', '70e5c751cd37220e608a332ff3f86bf6', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37393", "url": "remediation_change_log", "quote": "phase4:p4-0054:chunk-0001: description ''Glassonby stone circle, actually a kerbed cairn, lies 2 km north of the famous Long Meg and Her Daughters site in Cumbria. An oval arrangement of approximately 30 kerb stones (measuring 15.7 m by 14 m) sits atop a grass-covered cobble mound 30-33 m in diameter. Excavated by W.G. Collingwood in 1900, the site yielded a robbed cist, a cremation in a collared urn, burnt bones of a man, and a blue glass bead. Two stones bear carved concentric rings, spirals, and semi-ovoids, suggesting links to the wider Long Meg ritual complex.'' -> ''The Glassonby stone circle (actually a kerbed cairn) is at OS reference NY57293934 on private land [1]. An oval cairn is surrounded by a ring of kerb stones (30 stones in all, although some have been taken away and others added from field clearance over the years) [1]. Two of the stones had markings in the form of concentric rings or spirals and semi-ovoids [1]. The stones were not set in sockets, but were supported by the cairn material [1]. Outside the circle, burnt bones and an inverted collared urn were found [1].''"}, {"source": "remediation_change_log:106956", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:106957", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:160688", "url": "remediation_change_log", "quote": "served-image-2026-09-30-026: thumbnail_url ''/data/images/wiki/bcefdb51/hero.webp'' -> None"}, {"source": "remediation_change_log:252787", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:252788", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-3000''"}, {"source": "remediation_change_log:351926", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''3000 - 1500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:351927", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-3000'' -> None"}]'::jsonb),
