    ('bd3f6a4e-0452-448a-8674-b8a87c0e63e8'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:bd3f6a4e-0452-448a-8674-b8a87c0e63e8:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Magura Cave', '606eb6be190742ede110584549f27524', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87138", "url": "remediation_change_log", "quote": "phase4:p4-2162:chunk-0001: description ''Magura Cave is located in north-western Bulgaria near the village of Rabisha, 25 km from Belogradchik in Vidin Province[1].'' -> ''The Magura Cave is located in north-western Bulgaria close to the village of Rabisha [1]. The prehistoric wall paintings of Magura have great resemblance with those of the Grotta dei Cervi in Italy [1]. The total length of the 15 million year old cave is 2.5 km [1]. The Magura cave was formed in the limestone Rabisha Hill [1]. The morphology of the cave consists of one main gallery with six various-sized halls and three lateral galleries around it [1]. Bones from prehistoric species like cave bear, cave hyena, fox, wolf, wild cat and otter have been discovered in the Magura Cave [1]. The drawings represent important events of the society that had occupied the Magura Cave: religious ceremonies, hunting scenes and depictions of deities which are unique on the Balkan Peninsula [1]. The Fertility Dance and the Hunting Ceremony rank among the most noteworthy paintings [1].''"}, {"source": "remediation_change_log:123018", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:123019", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_start ''-500'' -> ''-8000''"}]'::jsonb),
