    ('bdba33af-64d6-4a74-90f3-4ecf9e512c83'::uuid, 'mystery', '7', '6', 'card-stats-2026-11-05-rollback:bdba33af-64d6-4a74-90f3-4ecf9e512c83:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Dun Grugaig', 'cab3061948f4e27d16a5145239e8d85e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Fortification'', ''1500 - 500 BC'') is shared by 10 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28817", "url": "remediation_change_log", "quote": "phase3:batch-0197:chunk-0001: site_type ''Megalithic structures'' -> ''Fortification''"}, {"source": "remediation_change_log:87142", "url": "remediation_change_log", "quote": "phase4:p4-2162:chunk-0001: description ''Dun Grugaig is a D-shaped Iron Age dun, or \"semi-broch,\" in Gleann Beag near Glenelg, Highland Scotland. Measuring roughly 47 by 38 feet with walls 14 feet thick surviving to about 4 metres high, it features mural chambers, a scarcement ledge, and a blocked entrance passage with door checks and bar hole. Located on rugged rising ground above the Abhainn a\\''Ghlaine Bhig, it sits in the same valley as the well-preserved brochs of Dun Telve and Dun Troddan. The site has not been excavated, though it was first recorded by Alexander Gordon in 1720 as \\''Castle Chonil\\''. Its hollow-wall construction is considered characteristic of proto-broch design.'' -> ''Dun Grugaig is a D-shaped dun, or \"semi-broch\", located about 7 kilometres southeast of the village of Glenelg, Highland [1]. Dun Grugaig stands on the north bank of the Abhainn a’Ghlaine Bhig, in the upper reaches of Gleann Beag [1]. It is in the same valley as the two Glenelg brochs of Dun Telve and Dun Troddan [1]. Dun Grugaig is a D-shaped fortification of a type commonly regarded as a prototype broch or \"semi-broch\" [1]. The first modern survey was conducted by Henry Dryden in 1871 [1].''"}, {"source": "remediation_change_log:106965", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:106966", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:252793", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:252794", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-800''"}]'::jsonb),
