    ('bdbf1e68-32c8-4571-90c0-ef154d458704'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:bdbf1e68-32c8-4571-90c0-ef154d458704:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Kutikina Cave', '36b71ea31c2bedee8a77cba5a36b917c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -18050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37421", "url": "remediation_change_log", "quote": "phase4:p4-0055:chunk-0001: description \"Kutikina Cave is a Pleistocene rock shelter on the Franklin River in Tasmania''s South West Wilderness World Heritage Area. Excavated in 1981, it yielded over 250,000 bone fragments and 75,000 stone tools, making it one of Australia''s richest archaeological deposits. During the last Ice Age, it was the southernmost human habitation on Earth, where people hunted Bennett''s wallaby on open tundra. Its discovery in 1977 by Kevin Kiernan was pivotal in the campaign to stop the Franklin Dam, with the High Court citing its world heritage value.\" -> ''Kutikina Cave is a rock shelter located on the Franklin River in the South West Wilderness, a World Heritage Area in the Australian state of Tasmania [1]. Originally referred to as Fraser Cave, it was important in the establishment of the antiquity and range of Aboriginal occupation in Tasmania during the Pleistocene [1]. The cave was discovered in 1977 by geomorphology student Kevin Keirnan and investigated by a team led by archeologists Don Ranson and Rhys Jones in the 1980s [1]. The cave has important archaeological deposits relating to human occupation in the Pleistocene, with evidence of wallaby hunting at a time the landscape was an open tundra and it was the most southerly human occupation in the world during the last ice age [1].''"}, {"source": "remediation_change_log:106967", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:106968", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-500'' -> None"}, {"source": "remediation_change_log:252797", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:252798", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-500''"}, {"source": "remediation_change_log:351932", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:351933", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-500'' -> ''-18050''"}]'::jsonb),
