    ('bdd92d68-2715-4dfe-a956-e2f3a5b77465'::uuid, 'mystery', '1', '5', 'card-stats-2026-11-05-rollback:bdd92d68-2715-4dfe-a956-e2f3a5b77465:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on La Milpa', '4b9d639e5deb64ab802b57cf2de4bf63', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''500 BC - 1 AD'') is shared by 316 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87164", "url": "remediation_change_log", "quote": "phase4:p4-2163:chunk-0001: description \"(500 BC - 850 AD) La Milpa is an ancient Maya city in the Three River region of northwest Belize, near the Mexico-Guatemala border [1]. Located between Rio Azul and Lamanai, it is one of Belize''s significant Maya sites [1]. The site lies within a nature preserve managed by the Programme for Belize, which acquired the land from Coca-Cola Company [1].\" -> ''La Milpa is an archaeological site and an ancient Maya city within the Three River region of Northwest Belize bordering Mexico and Guatemala [1]. La Milpa is located between the sites of Rio Azul and Lamanai [1]. Following Caracol and Lamanai, La Milpa is the third largest site in Belize with the Main Plaza alone covering 18,000 square meters, making it one of the largest in the entire Maya region [1]. At La Milpa during the mid-8th century, there was a steep upward climb in the construction of monumental architecture and the dedication of stelae [1]. The site of La Milpa was occupied from the Pre-classic and Early Classic into the Late and Terminal Classic [1]. La Milpa had intensive agriculture as indicated by extensive terraces [1].''"}, {"source": "remediation_change_log:123029", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: site_type ''Pyramid complex'' -> ''City''"}, {"source": "remediation_change_log:160723", "url": "remediation_change_log", "quote": "served-image-2026-09-30-026: thumbnail_url ''/data/images/wiki/bdd92d68/hero.webp'' -> None"}, {"source": "remediation_change_log:356179", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
