    ('be35e129-235b-498b-969d-580eac095ae0'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:be35e129-235b-498b-969d-580eac095ae0:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Cranmore Castle', 'c83afbdc3b47f8cd7ae6d5d4ea15709d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -800"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:37427", "url": "remediation_change_log", "quote": "phase4:p4-0055:chunk-0001: description ''Cranmore Castle is an Iron Age earthwork above the Devon town of Tiverton, covering over 15 acres and ranking among the largest enclosures in Devon. Its substantial ramparts and ditches enclose sloping terrain between 395 and 560 feet elevation, though its defensive value is debated since it is overlooked from higher ground to the south. Scholars have proposed it may have served as a livestock enclosure, market site, or tribal oppidum. The site offers clear sightlines to Cadbury Castle, Hembury Fort, and other contemporary hillforts, and overlooks the confluence of the Exe and Lowman rivers.'' -> ''Cranmore Castle is an Iron Age earthwork situated on a hillside above the Devon town of Tiverton in south-west England [1]. The earthwork is also unusual in that the area it encloses slopes from 120 metres to 170 metres above sea level [1]. This arrangement does however offer clear lines of sight to Cadbury Castle, Castle Close below Stoodleigh up the Exe Valley, Huntsham Castle, Hembury fort and other significant hills and earthworks, suggesting that all were contemporary [1]. It also manages to overlook the confluence of the rivers Lowman and Exe and the forded crossings on those rivers, which a higher position would not allow [1]. The Ordnance Survey Map of Southern Britain in the Iron Age shows Cranmore as the largest enclosure in Devon (along with Hillsborough) at over 15 acres [1].''"}, {"source": "remediation_change_log:106978", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:106979", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:252803", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:252804", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-4000''"}, {"source": "remediation_change_log:351938", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_name ''4500 - 3000 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:351939", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s007: period_start ''-4000'' -> ''-800''"}]'::jsonb),
