    ('bebb7616-5341-4fd5-a69e-ee430e59c44f'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:bebb7616-5341-4fd5-a69e-ee430e59c44f:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Margery Hill', 'b52ddb73bdfbb32831a9db8799762609', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Cairn'', ''3000 - 1500 BC'') is shared by 35 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87168", "url": "remediation_change_log", "quote": "phase4:p4-2163:chunk-0001: description ''Margery Hill is a 546-metre summit on the Howden Moors in South Yorkshire, England, within the Peak District National Park. Peat near the summit cairn has been radiocarbon dated to approximately 3,500 years old, indicating it was deliberately constructed rather than natural, likely as a Bronze Age funerary mound (c. 2000-700 BC). The round cairn has been designated a Scheduled Ancient Monument by English Heritage, reflecting its archaeological significance as evidence of Bronze Age settlement and ceremonial activity in the surrounding uplands.'' -> ''Margery Hill is a 546-metre hill on the Howden Moors in South Yorkshire, England [1]. It lies towards the northern boundary of the Peak District National Park, between Langsett Reservoir to the northeast and Howden Reservoir to the southwest [1]. The area is managed by the National Trust as part of their High Peak Estate [1]. Peat near the summit cairn has been dated to a uniform age of about 3,500 years old, indicating that it was constructed rather than natural; it is believed to have been part of a Bronze Age burial mound [1]. The area has been designated a Scheduled Ancient Monument by English Heritage [1]. Margery Hill is the highest marked point within the boundaries of the City of Sheffield [1].''"}, {"source": "remediation_change_log:123039", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:123040", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:123041", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: site_type ''Mound/tumulus'' -> ''Cairn''"}, {"source": "remediation_change_log:123042", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: source_url ''https://en.wikipedia.org/wiki/Margery_Hill'' -> ''https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA170256''"}, {"source": "remediation_change_log:242692", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:242693", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-1940''"}]'::jsonb),
