    ('bebeb092-4bf8-41da-accd-cf2a8b640343'::uuid, 'antiquity', '3', '7', 'card-stats-2026-11-05-rollback:bebeb092-4bf8-41da-accd-cf2a8b640343:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Borough Hill Roman Villa', 'f735578db68ffa04f8cc346a46271dcf', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 3 from period_start 43"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:44997", "url": "remediation_change_log", "quote": "phase4:p4-0105:chunk-0001: description \"Borough Hill Roman Villa occupies the north tip of Borough Hill, a prominent hill near Daventry in Northamptonshire, sitting within the ramparts of an Iron Age fortress that covers the summit [1]. The villa remains were discovered in 1823 by historian George Baker, who identified the site with the Roman settlement Isannavaria and the Britons'' Benaventa [1]. Full excavation occurred in 1852 under local historian Beriah Botfield, who thoroughly excavated and recorded the site [1]. Botfield employed an artist to create drawings of the site; his notes, manuscripts, and antiquities found during the excavation are now held at the British Museum [1].\" -> ''Borough Hill Roman villa is located on the north tip of Borough Hill, a prominent hill near the town of Daventry in Northamptonshire [1]. The villa’s remains lie within the ramparts of an Iron Age fortress which covers the summit of the hill [1]. The remains of the Roman villa were discovered in 1823 by the historian and archaeologist George Baker [1]. The remains were not fully excavated until 1852 when local historian Beriah Botfield thoroughly excavated and recorded the site [1]. Botfield’s excavations revealed a large range of rooms which ran from north to south, part of which was a bath suite [1]. It was deduced that the buildings were built over a period of time and that the northern rooms are later additions [1]. The earliest parts of the villa were built in the early years of the Roman occupation [1]. The villa consisted of a single storey and was constructed from the local marlstone (sandstone), infilled with rubble [1].''"}, {"source": "remediation_change_log:106988", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:106989", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''1'' -> None"}, {"source": "remediation_change_log:160757", "url": "remediation_change_log", "quote": "served-image-2026-09-30-026: thumbnail_url ''/data/images/wiki/bebeb092/hero.webp'' -> ''/data/images/wiki/bebeb092/Borough_Hill_Floor.webp''"}, {"source": "remediation_change_log:252811", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:252812", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-2500''"}, {"source": "remediation_change_log:352715", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''3000 - 1500 BC'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:352716", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-2500'' -> ''43''"}]'::jsonb),
