    ('bf6f967e-3161-45c3-840d-d68ebff231b7'::uuid, 'antiquity', '10', '8', 'card-stats-2026-11-05-rollback:bf6f967e-3161-45c3-840d-d68ebff231b7:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Caves of Poço Velho', 'ce4b97639c73e38bb99005ef353f62d9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -3000000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87190", "url": "remediation_change_log", "quote": "phase4:p4-2164:chunk-0001: description ''The Caves of Poco Velho are two natural caves with interconnected galleries in central Cascais, Lisbon district. Formed 1.6 million years ago by water seeping into limestone, they were primarily used as a necropolis during the Final Neolithic and Chalcolithic periods (4th-3rd millennia BC), with approximately 115 burials identified. First excavated in 1879 by Carlos Ribeiro and again in the 1940s, artifacts include a notable Neolithic necklace of green minerals, slate, limestone, and shells dating to c. 4000 BC. Finds are displayed at the Cascais Town Museum and the National Geological Museum.'' -> ''The Caves of Poço Velho are located in the centre of Cascais in the Lisbon district of Portugal [1]. The caves were first explored in 1879 by the geologist, Carlos Ribeiro [1]. However, subsequent work has found that the main occupation of the caves took place in the Neolithic and Chalcolithic periods (4th and 3rd millennia BC) [1]. Evidence points to their use as a necropolis, with around 115 burials having been identified [1]. In 1942, Afonso do Paço carried out the second major exploration of the caves and between 1945 and 1947, the archaeologist, Abreu Nunes, carried out new excavations that discovered different funerary remains, including: polished and chipped stone artefacts; limestone votive offerings, such as cylindrical idols; decorated schist slabs, and ceramics [1].''"}, {"source": "remediation_change_log:107006", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:107007", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:242707", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:242708", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-4000''"}, {"source": "remediation_change_log:352721", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:352722", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> ''-3000000''"}]'::jsonb),
