    ('bf6f967e-3161-45c3-840d-d68ebff231b7'::uuid, 'total_power', '22', '24', 'card-stats-2026-11-05-rollback:bf6f967e-3161-45c3-840d-d68ebff231b7:total_power', 'rollback of card-stats-2026-11-05: total_power ''24'' restored on Caves of Poço Velho', 'ce4b97639c73e38bb99005ef353f62d9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 22 from antiquity + fortification + cultural_influence + mystery + legacy = 10 + 2 + 6 + 3 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87190", "url": "remediation_change_log", "quote": "phase4:p4-2164:chunk-0001: description ''The Caves of Poco Velho are two natural caves with interconnected galleries in central Cascais, Lisbon district. Formed 1.6 million years ago by water seeping into limestone, they were primarily used as a necropolis during the Final Neolithic and Chalcolithic periods (4th-3rd millennia BC), with approximately 115 burials identified. First excavated in 1879 by Carlos Ribeiro and again in the 1940s, artifacts include a notable Neolithic necklace of green minerals, slate, limestone, and shells dating to c. 4000 BC. Finds are displayed at the Cascais Town Museum and the National Geological Museum.'' -> ''The Caves of Poço Velho are located in the centre of Cascais in the Lisbon district of Portugal [1]. The caves were first explored in 1879 by the geologist, Carlos Ribeiro [1]. However, subsequent work has found that the main occupation of the caves took place in the Neolithic and Chalcolithic periods (4th and 3rd millennia BC) [1]. Evidence points to their use as a necropolis, with around 115 burials having been identified [1]. In 1942, Afonso do Paço carried out the second major exploration of the caves and between 1945 and 1947, the archaeologist, Abreu Nunes, carried out new excavations that discovered different funerary remains, including: polished and chipped stone artefacts; limestone votive offerings, such as cylindrical idols; decorated schist slabs, and ceramics [1].''"}, {"source": "remediation_change_log:107006", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:107007", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s017: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:242707", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:242708", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-4000''"}, {"source": "remediation_change_log:352721", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:352722", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> ''-3000000''"}]'::jsonb),
    ('bfa3495a-39f7-4ba8-a110-eff95d15f05c'::uuid, 'mystery', '6', '4', 'card-stats-2026-11-05-rollback:bfa3495a-39f7-4ba8-a110-eff95d15f05c:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Whitehawk Camp', 'd9c235efc2483879dd05a09c07cd4506', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Earthwork'', ''4500 - 3000 BC'') is shared by 13 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29100", "url": "remediation_change_log", "quote": "phase3:batch-0238:chunk-0001: site_type ''City/town/settlement'' -> ''Earthwork''"}, {"source": "remediation_change_log:87198", "url": "remediation_change_log", "quote": "phase4:p4-2164:chunk-0001: description ''Whitehawk Camp is a Neolithic causewayed enclosure on Whitehawk Hill near Brighton, East Sussex, dating to approximately 3700-3500 BC[1]. The site features four concentric circular ditches with interior earth banks, possibly once topped by a timber palisade[1]. Causewayed enclosures are characterized by ditches interrupted by gaps, and their purpose remains unknown—scholars suggest they may have been settlements, meeting places, or ritual sites[1]. Outside the main circuit, at least two additional ditches exist, including one from the Bronze Age roughly 2,000 years after the earliest activity[1].'' -> ''Whitehawk Camp is the remains of a causewayed enclosure on Whitehawk Hill near Brighton, East Sussex, England [1]. The Whitehawk site consists of four roughly concentric circular ditches, with banks of earth along the interior of the ditches evident in some places [1]. Whitehawk was first excavated by R. P. Ross Williamson and E. Cecil Curwen in 1929 in response to a plan to lay out football pitches on the site [1]. In 2011, the Gathering Time project published an analysis of radiocarbon dates from almost forty British causewayed enclosures, including several from Whitehawk Camp [1]. The conclusion was that the Neolithic part of the site was probably constructed between 3650 and 3500 BC, and probably went out of use some time between 3500 and 3400 BC [1]. Most of the prehistoric pottery found at Whitehawk Camp is of the plain bowl or decorated bowl types; these are the earliest forms of Neolithic pottery found in England [1].''"}, {"source": "remediation_change_log:160784", "url": "remediation_change_log", "quote": "served-image-2026-09-30-026: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/c/cb/Signboard_at_Whitehawk_Neolithic_Camp%2C_Whitehawk_Hill%2C_Brighton_%28November_2020%29_%2810%29.JPG'' -> ''/data/images/wiki/bfa3495a/Whitehawk_camp_aerial_view_1930_Williamson.webp''"}, {"source": "remediation_change_log:334738", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/bfa3495a/Whitehawk_camp_aerial_view_1930_Williamson.webp'' -> ''/data/images/wiki/bfa3495a/Signboard_at_Whitehawk_Neolithic_Camp,_Whitehawk_Hill,_Brighton_(November_2020)_(10).webp''"}]'::jsonb),
