    ('c0526e60-577b-4f28-9a07-e3c5739984bd'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:c0526e60-577b-4f28-9a07-e3c5739984bd:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Praetorium Agrippinae', '1b21613c7051a93f42f4dcf191c0b3b0', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Fort'', ''1 - 500 AD'') is shared by 26 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29203", "url": "remediation_change_log", "quote": "phase3:batch-0254:chunk-0001: site_type ''City/town/settlement'' -> ''Fortification''"}, {"source": "remediation_change_log:84268", "url": "remediation_change_log", "quote": "2026-09-26a_fields-wd1-s001: site_type ''Fortification'' -> ''Fort''"}, {"source": "remediation_change_log:87230", "url": "remediation_change_log", "quote": "phase4:p4-2165:chunk-0001: description ''Praetorium Agrippinae was a Roman settlement and military encampment in the province of Lower Germania, located in modern-day Valkenburg, Netherlands. Situated on the Old Rhine, it stood on the northern frontier of the Roman Empire—the limes. It is mentioned on the Tabula Peutingeriana between the castella of Matilo to the east and Lugdunum Batavorum to the west.'' -> ''Praetorium Agrippinae was a Roman settlement in the province of Lower Germania, in the area of the Cananefates, located in modern-day Valkenburg [1]. It was an army encampment on the Old Rhine, on the northern border of the Roman Empire, the limes [1]. Praetorium Agrippinae is mentioned on the Tabula Peutingeriana between the castella of Matilo in the east and Lugdunum Batavorum to the west [1]. The fort was built in the current centre of Valkenburg, and was at first fortified by a palisaded earthen wall and three moats [1]. To the southeast of the fortress, a large civil settlement developed, stretching for approx. 1 km along the via militaris [1]. It was inhabited between approx. 70 and 240 AD [1]. Archaeological investigations have uncovered living quarters, storehouses and granaries, and possibly a bath house [1]. Investigations started in 1875, but the main excavations were done between 1941 and 1953 under the direction of Albert Egges van Giffen [1].''"}, {"source": "remediation_change_log:160822", "url": "remediation_change_log", "quote": "served-image-2026-09-30-026: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Peutinger_Renus_Patabus.png/400px-Peutinger_Renus_Patabus.png'' -> ''/data/images/wiki/c0526e60/Afb 009 Maquette castellum ValkenburgZH fase1 foto in blauw collRMO.webp''"}]'::jsonb),
