    ('c1f010f5-9a19-4070-8a1d-a3ddb408eac8'::uuid, 'mystery', '7', '6', 'card-stats-2026-11-05-rollback:c1f010f5-9a19-4070-8a1d-a3ddb408eac8:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Mnajdra', '946d9cf595833b027f41ddf0dbc4d385', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Megalithic structures'', ''4500 - 3000 BC'') is shared by 10 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:45201", "url": "remediation_change_log", "quote": "phase4:p4-0106:chunk-0001: description \"Mnajdra is a megalithic temple complex on the southern coast of Malta, over 5,000 years old and designated a UNESCO World Heritage Site in 1992. The complex consists of three conjoined but unconnected temples built in globigerina and coralline limestone. The South Temple features remarkable astronomical alignment: its doorway aligns with sunrise during the equinoxes, while solstice sunlight illuminates decorated megaliths along the entrance edges. Tiny rooms built within wall thicknesses distinguish Mnajdra''s unique architectural design.\" -> ''Mnajdra is a megalithic temple complex found on the southern coast of the Mediterranean island of Malta [1]. Mnajdra is approximately 497 metres from the Ħaġar Qim megalithic complex [1]. Mnajdra was built around the fourth millennium BCE; the Megalithic Temples of Malta are among the most ancient religious sites on Earth, described by the World Heritage Sites committee as \"unique architectural masterpieces.\" In 1992, UNESCO recognized the Mnajdra complex and four other Maltese megalithic structures as UNESCO World Heritage Sites [1]. Mnajdra is made of coralline limestone, which is much harder than the soft globigerina limestone of Ħaġar Qim [1]. The prehistoric structure consists of three temples, conjoined, but not connected: the upper, middle, and lower [1]. The upper temple is the oldest structure in the Mnajdra complex and dates to the Ġgantija phase (3600-3200 BC) [1]. The lowest temple is astronomically aligned and thus was probably used as an astronomical observation and/or calendrical site [1]. The excavations of the Mnajdra temples were performed under the direction of J.G. Vance in 1840 [1].''"}, {"source": "remediation_change_log:161348", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/7/75/Mnajdra_03.jpg'' -> ''/data/images/wiki/c1f010f5/Malta_16_Mnajdra.webp''"}, {"source": "remediation_change_log:334747", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/c1f010f5/Malta_16_Mnajdra.webp'' -> ''/data/images/wiki/c1f010f5/Mnajdra_03.webp''"}]'::jsonb),
