    ('c292f83a-933b-40e3-a658-ad7aa6c19d33'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:c292f83a-933b-40e3-a658-ad7aa6c19d33:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Les Combarelles', '1e105d9bdafc76e607a73ab7d0391630', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29189", "url": "remediation_change_log", "quote": "phase3:batch-0251:chunk-0001: period_start ''-500'' -> ''-11680''"}, {"source": "remediation_change_log:30498", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:81262", "url": "remediation_change_log", "quote": "phase4:p4-2026:chunk-0001: description ''Les Combarelles is a cave in Les Eyzies de Tayac, Dordogne, France, inhabited by Cro-Magnon people between approximately 13,000 to 11,000 years ago [1]. The cave holds over 600 prehistoric engravings of animals and symbols across two galleries, which were crucial in re-evaluating the mental and technical capabilities of prehistoric humans around the turn of the 20th century [1]. In 1979, it was inscribed on the UNESCO World Heritage List as part of the Prehistoric Sites and Decorated Caves of the Vézère Valley [1].'' -> ''Les Combarelles is a cave in Les Eyzies de Tayac, Dordogne, France, which was inhabited by Cro-Magnon people between approximately 13,000 to 11,000 years ago [1]. Holding more than 600 prehistoric engravings of animals and symbols, the two galleries in the cave were crucial in the re-evaluation of the mental and technical capabilities of these prehistoric humans around the turn of the 20th century [1]. In 1979 the cave was inscribed on the UNESCO World Heritage List as part of the Prehistoric Sites and Decorated Caves of the Vézère Valley [1]. Formed by an underground river, the cave is approximately 300 m long with an average width of 1 m [1]. Long used as a stable by local peasants who regularly found Magdalenian artifacts in the cave, the cave and its content remained unstudied by scientists for a long period [1]. It was officially discovered in September 1901 by pre-historians Denis Peyrony, Abbé Breuil, and Louis Capitan [1]. Radiocarbon dating of bones found in the cave indicate the cave was inhabited by Cro-Magnon people 13,680–11,380 years ago [1].''"}, {"source": "remediation_change_log:107934", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:107935", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-11680'' -> None"}, {"source": "remediation_change_log:161382", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''/data/images/wiki/c292f83a/hero.webp'' -> ''/data/images/wiki/c292f83a/Guide leaflet (1901) (14764048431).webp''"}, {"source": "remediation_change_log:242741", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:242742", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-12000''"}, {"source": "remediation_change_log:316692", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-012: thumbnail_url ''/data/images/wiki/c292f83a/Guide leaflet (1901) (14764048431).webp'' -> ''/data/images/wiki/c292f83a/Entrance_to_Les_Combarelles.webp''"}]'::j