    ('c2cd2a6a-8f1d-4fce-9645-234908ef7d37'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:c2cd2a6a-8f1d-4fce-9645-234908ef7d37:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Hodson Stone Circle', '3701a618786fe50ea114a44354025fbe', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87272", "url": "remediation_change_log", "quote": "phase4:p4-2166:chunk-0001: description ''Hodson Stone Circle was a stone circle in the village of Hodson, Wiltshire, England, part of the Late Neolithic and Early Bronze Age tradition of stone circle construction dating between 3300 and 900 BC. It was discovered and recorded by antiquarian A. D. Passmore in the 1890s, who noted eight stones remaining and a possible avenue or stone row extending toward Coate. A road cut through the circle and several barns encroached upon it, making it very difficult to locate. Archaeologists David Field and David McOmish noted in 2017 that any surviving stones may now be found loose around the village or incorporated into local buildings.'' -> ''Hodson Stone Circle was a stone circle in the village of Hodson in the south-western English county of Wiltshire [1]. The ring was part of a tradition of stone circle construction that spread throughout much of Britain, Ireland, and Brittany during the Late Neolithic and Early Bronze Age [1]. The circle was discovered and recorded by the antiquarian A. D. Passmore in the 1890s [1]. He briefly mentioned it in an article published in The Wiltshire Archaeological and Natural History Magazine, while detailing it in greater depth in his unpublished notebooks [1]. He recorded the circle as consisting of eight stones at that time, with a possible avenue or stone row emerging from it and facing in the direction of the circle at Coate [1]. Later archaeologists have noted that some of the sarsens used as building material in Hodson were once part of the circle [1].''"}, {"source": "remediation_change_log:107940", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:107941", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:252863", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:252864", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-4000''"}, {"source": "remediation_change_log:352742", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:352743", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> None"}]'::jsonb),
