    ('c3517388-2457-42fd-9cf8-f6a043021b1e'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:c3517388-2457-42fd-9cf8-f6a043021b1e:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Petrovaradin', 'fe04860e57d46b2d2e1cfbe96ccafed7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81264", "url": "remediation_change_log", "quote": "phase4:p4-2026:chunk-0001: description \"Petrovaradin is a historic town on the right bank of the Danube in Vojvodina, Serbia, built around the Petrovaradin Fortress. Archaeological evidence reveals Paleolithic settlement dating from 19,000-15,000 BC, with Middle Paleolithic artifacts representing the most convincing evidence of Neanderthal settlement in the Serbian Danube Basin. Bronze Age ramparts (c. 3000 BC) confirm early fortification. The Celts established a fortress in the 4th century BC, and the Romans built the Cusum fort over it. In 1235, Cistercian monks constructed the Belakut monastery on the Roman remains, and the present 112-hectare fortress -- Europe''s second largest -- was completed in 1776.\" -> ''Human settlement in the territory of present-day Petrovaradin has been traced as far back as the Stone Age (about 4500 BC) [1]. This region was conquered by Celts (in the 4th century BC) and Romans (in the 1st century BC) [1]. The Celts founded the first fortress at this location [1]. It was part of the tribal state of the Scordisci, which had its capital in Singidunum (present-day Belgrade) [1]. During the Roman administration, a larger fortress was built with the name Cusum and was included into Roman Pannonia [1]. Subsequently, the fortress was included into the Pannonia Inferior and the Pannonia Secunda [1].''"}, {"source": "remediation_change_log:107955", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:107956", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-500'' -> None"}, {"source": "remediation_change_log:161418", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Petrovaradin_panorama.jpg/400px-Petrovaradin_panorama.jpg'' -> ''/data/images/wiki/c3517388/Petrovaradin_Fortress_(Péterváradi_vár,_Peterwardein).webp''"}, {"source": "remediation_change_log:242752", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:242753", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-4500''"}, {"source": "remediation_change_log:352753", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:352754", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4500'' -> None"}]'::jsonb),
