    ('c3bf5c7e-26d4-4441-95ea-990a5c82c4ae'::uuid, 'mystery', '8', '7', 'card-stats-2026-11-05-rollback:c3bf5c7e-26d4-4441-95ea-990a5c82c4ae:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Route of Megalithic Culture', '9fd8a3f13c9ada28e3b9438ae6b9398d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Road/avenue/trackway'', ''4500 - 3000 BC'') is shared by 4 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28879", "url": "remediation_change_log", "quote": "phase3:batch-0209:chunk-0001: site_type ''Megalithic stones'' -> ''Road/avenue/trackway''"}, {"source": "remediation_change_log:45207", "url": "remediation_change_log", "quote": "phase4:p4-0106:chunk-0001: description \"The Route of Megalithic Culture (Straße der Megalithkultur) is a 310 km tourist route in North-West Germany connecting Osnabrück to Oldenburg. Signposted with brown road signs, it links places of archaeological interest from the Megalithic era. The route was officially opened on 14 May 2009 after signs were installed in 2008-2009, promoting awareness of the region''s prehistoric heritage.\" -> ''The Route of Megalithic Culture was first created as a tourist route that meanders from Osnabrück to Oldenburg in North-West Germany [1]. Signposted with brown road signs it links many places of archaeological interest from the Megalithic era [1]. The whole 310-kilometre-long route was officially opened on 14 May 2009 [1]. The route links many sites of archaeological investigation and 33 stations where the public can visit archaeological sites, for example, with standing stones [1]. On the 27th of August 2013, the route became part of the Cultural Route of the Council of Europe initiative, with sections in a growing number of countries, including Denmark, England, Netherlands, Portugal, and Sweden [1]. The Route of Megalithic Culture is intended to give a better understanding of the lives of people who lived over 5,000 years ago in all its member countries [1].''"}, {"source": "remediation_change_log:107957", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:107958", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:141501", "url": "remediation_change_log", "quote": "2026-10-01a_fields-wd3-s001: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:141502", "url": "remediation_change_log", "quote": "2026-10-01a_fields-wd3-s001: period_start None -> ''-3500''"}, {"source": "remediation_change_log:161425", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/a6/Gretescher_steine_10.jpg'' -> ''/data/images/wiki/c3bf5c7e/Vehrte_-_Süntelstein_-BT-_01.webp''"}, {"source": "remediation_change_log:316718", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-012: thumbnail_url ''/data/images/wiki/c3bf5c7e/Vehrte_-_Süntelstein_-BT-_01.webp'' -> ''/data/images/wiki/c3bf5c7e/Gretescher_steine_10.webp''"}]'::jsonb),
