    ('c434e091-07f2-4748-a298-2766e0717bb6'::uuid, 'mystery', '1', '6', 'card-stats-2026-11-05-rollback:c434e091-07f2-4748-a298-2766e0717bb6:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Igeum-dong', 'b16dec8aec7c7f367e0c6addf9298743', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''1500 - 500 BC'') is shared by 286 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28947", "url": "remediation_change_log", "quote": "phase3:batch-0217:chunk-0001: period_start ''-1500'' -> ''-700''"}, {"source": "remediation_change_log:35994", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-700'' -> ''-1500''"}, {"source": "remediation_change_log:87296", "url": "remediation_change_log", "quote": "phase4:p4-2167:chunk-0001: description \"Igeum-dong is a complex prehistoric archaeological site in Samcheonpo, South Gyeongsang Province, South Korea. The settlement dates to the Late Middle Mumun Pottery Period (approximately 700–550 BC) based on pottery typology, pit-house structures, and AMS radiocarbon dating [1]. Excavated in 1997–1999, the site provides key evidence that simple chiefdoms emerged in the Middle Mumun period, roughly 950 years before Korea''s first state-level societies appeared [1].\" -> ''Igeum-dong is a complex archaeological site located in Igeum-dong, Samcheonpo in Sacheon-si, South Gyeongsang Province, South Korea [1]. This prehistoric archaeological site is important in Korean prehistory because it represents solid evidence that simple chiefdoms formed in as early as the Middle Mumun, some 950 years before the first state-level societies formed in Korea [1]. The settlement is dated by pottery, pit-house types, and an AMS radiocarbon date to the Late Middle Mumun Pottery Period (c. 700–550 BC) [1]. Test excavations were conducted in 1997 [1]. The site contains a megalithic cemetery with 63 burials, some of them with artifacts of high-status, 25 raised-floor buildings, including the two largest raised-floor buildings in Korean prehistory, 5 ditches, 1 palisade, and 27 pit-houses [1]. The megalithic cemetery is notable for a number of high-status burials and an interconnected series of low ‘pavement’ features made of rounded river cobbles that link the burials together [1]. Some of the artifacts excavated from the cemetery include two rare Liaoning-style bronze daggers [1].''"}, {"source": "remediation_change_log:107966", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:107967", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:107968", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: site_type ''Cemetery'' -> None"}, {"source": "remediation_change_log:161434", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''/data/images/wiki/c434e091/hero.webp'' -> None"}, {"source": "remediation_change_log:242757", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:242758", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-700''"}, {"source": "remediation_change_log:242759", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: site_type None -> ''Settlement''"}, {"source": "remediation_change_log:356187", "url": "re