    ('c4dcfccd-1092-41dd-a29a-d3a0355bc325'::uuid, 'cultural_influence', '6', '5', 'card-stats-2026-11-05-rollback:c4dcfccd-1092-41dd-a29a-d3a0355bc325:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''5'' restored on Chiripa Archaeological site', '2ee66a4aad293a16b599e6aa570e5de1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 6 from description yes, thumbnail yes, 0 content link(s), 2 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87314", "url": "remediation_change_log", "quote": "phase4:p4-2168:chunk-0001: description \"Chiripa is a Formative Period site on the Taraco Peninsula overlooking Lake Titicaca in Bolivia, occupied from c. 1400 to 100 BC. Its artificial mound (60 x 55 m, 6 m high) supports a temple-storage complex of rectangular double-walled adobe buildings arranged around a central sunken court. Storage bins within contained quinoa and freeze-dried potatoes, while ceremonial trumpets and Yaya-Mama style stone sculptures attest to the site''s ritual significance. Chiripa served as a prototype for later Pucara temple complexes and was central to the Yaya-Mama Religious Tradition that unified Lake Titicaca Basin populations for over a millennium.\" -> \"The site of Chiripa consists of a large mound platform that dominates the settlement [1]. On the platform is a rectangular sunken plaza with a carved stone in the center of the plaza [1]. Rituals occurred in specially prepared public places like the plaza, suggesting the importance of rituals in the creation and maintenance of legitimacy and power [1]. There are fourteen upper houses with thatched roofs and double walls of cobble and adobe, arranged in a trapezoid surrounding the sunken plaza [1]. These were first identified by Bennet (1936) [1]. Around 800 BCE, we find samples composed almost entirely of quinoa at Chiripa''s social and political center, the Montículo [1]. During the Middle Chiripa phase the population grew, and the village of Chiripa increased to 4.25 ha [1].\""}, {"source": "remediation_change_log:107989", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:107990", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:161462", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''/data/images/wiki/c4dcfccd/hero.webp'' -> None"}, {"source": "remediation_change_log:242767", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:242768", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-1500''"}, {"source": "remediation_change_log:316738", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-012: thumbnail_url None -> ''/data/images/wiki/c4dcfccd/Quinua.webp''"}]'::jsonb),
