    ('c4ee2569-7555-47a2-8d4c-71fcae8468fb'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:c4ee2569-7555-47a2-8d4c-71fcae8468fb:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Thickthorn Down Long Barrows', '40f727e16cebc5b0a08f504e900fe35e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87318", "url": "remediation_change_log", "quote": "phase4:p4-2168:chunk-0001: description ''The Thickthorn Down Long Barrows are two Neolithic long barrows near Gussage St Michael in Dorset, situated at the southwestern terminal of the Dorset Cursus. The southern barrow, excavated by Stuart Piggott in 1933, measures 145 feet long, 60 feet wide, and 8 feet high, surrounded by a U-shaped ditch. Excavation yielded Early Neolithic pottery, two carved chalk phalli, animal bone, and later Peterborough Ware, with four secondary Beaker-period crouched burials inserted into the mound. Both barrows are a scheduled monument dating to approximately 4000-2351 BC.'' -> ''The Thickthorn Down Long Barrows are two Neolithic long barrows, near the village of Gussage St Michael in Dorset, England [1]. They are near the south-western end of the Dorset Cursus, a Neolithic feature [1]. The long barrows are situated on a ridge on Thickthorn Down [1]. The barrow to the north-west, which is unexcavated, is rectangular, 44 by 18 metres, and 2.4 metres high; there is an incomplete ditch around the barrow [1]. It is aligned north-west to south-east, and is immediately south-east of the south-western terminus of the Dorset Cursus [1]. The second barrow, a short distance along the ridge to the south-east, is also aligned north-west to south-east [1]. It is rectangular, 30 by 18 metres, and 2.4 metres high [1]. The south-eastern barrow was excavated in 1933 by C. D. Drew and Stuart Piggott, and carefully restored [1].''"}, {"source": "remediation_change_log:107991", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:107992", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:161469", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url None -> ''/data/images/wiki/c4ee2569/hero.webp''"}, {"source": "remediation_change_log:252883", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:252884", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-4000''"}]'::jsonb),
    ('c4ee2569-7555-47a2-8d4c-71fcae8468fb'::uuid, 'rarity_score', '25', '22', 'card-stats-2026-11-05-rollback:c4ee2569-7555-47a2-8d4c-71fcae8468fb:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''22'' restored on Thickthorn Down Long Barrows', '40f727e16cebc5b0a08f504e900fe35e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 25 from mystery 5, cultural_influence 5"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87318", "url": "remediation_change_log", "quote": "phase4:p4-2168:chunk-0001: description ''The Thickthorn Down Long Barrows are two Neolithic long barrows near Gussage St Michael in Dorset, situated at the southwestern terminal of the Dorset Cursus. The southern barrow, excavated by Stuart Piggott in 1933, measures 145 feet long, 60 feet wide, and 8 feet high, surrounded by a U-shaped ditch. Excavation yielded Early Neolithic pottery, two carved chalk phalli, animal bone, and later Peterborough Ware, with four secondary Beaker-period crouched burials inserted into the mound. Both barrows are a scheduled monument dating to approximately 4000-2351 BC.'' -> ''The Thickthorn Down Long Barrows are two Neolithic long barrows, near the village of Gussage St Michael in Dorset, England [1]. They are near the south-western end of the Dorset Cursus, a Neolithic feature [1]. The long barrows are situated on a ridge on Thickthorn Down [1]. The barrow to the north-west, which is unexcavated, is rectangular, 44 by 18 metres, and 2.4 metres high; there is an incomplete ditch around the barrow [1]. It is aligned north-west to south-east, and is immediately south-east of the south-western terminus of the Dorset Cursus [1]. The second barrow, a short distance along the ridge to the south-east, is also aligned north-west to south-east [1]. It is rectangular, 30 by 18 metres, and 2.4 metres high [1]. The south-eastern barrow was excavated in 1933 by C. D. Drew and Stuart Piggott, and carefully restored [1].''"}, {"source": "remediation_change_log:107991", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:107992", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:161469", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url None -> ''/data/images/wiki/c4ee2569/hero.webp''"}, {"source": "remediation_change_log:252883", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:252884", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-4000''"}]'::jsonb),
