    ('c5851dba-f3f4-4aaf-a4a1-37bf6a56600b'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:c5851dba-f3f4-4aaf-a4a1-37bf6a56600b:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Micheldever Wood', '599bc006872d2384d32ad3abb1029778', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87322", "url": "remediation_change_log", "quote": "phase4:p4-2168:chunk-0001: description ''Micheldever Wood is a Bronze Age to Romano-British archaeological site in Hampshire, England, located about 8 km (5 mi) north-east of Winchester near the village of Micheldever [1]. The woodland preserves prehistoric earthworks and settlement remains dating from the Bronze Age (c. 3000–1500 BC) through to the Romano-British period [1][2]. Notable features include Bronze Age burial mounds and field systems, as well as the ruins of a Roman villa [1]. The site is managed by Forestry England and is a scheduled monument, protected for its archaeological importance [1].'' -> ''Micheldever Wood is a wood near the village of Micheldever, in Hampshire, England, about 5 miles north-east of Winchester [1]. Archaeological features survive from the Bronze Age to the Romano-British period, preserved for many centuries by the woodland [1]. Information boards are provided for some of the features [1]. There is a Bronze Age cross dyke in the south-east of the wood, extending into Itchen Wood to the south; it is thought to mark a territorial boundary [1]. It is a bank 3 metres wide, with a ditch either side; the part of the dyke in Micheldever Wood is about 90 metres long [1]. There is a linear earthwork running west–east across the wood [1].''"}, {"source": "remediation_change_log:124169", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:124170", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:253187", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:253188", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_start None -> ''-4000''"}, {"source": "remediation_change_log:326012", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/c5851dba/hero.webp'' -> ''/data/images/wiki/c5851dba/Micheldever Woods Bowl Barrow.webp''"}, {"source": "remediation_change_log:352761", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:352762", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
