    ('c5b89e54-5127-4500-b6b4-e63f35efdc8d'::uuid, 'mystery', '8', '5', 'card-stats-2026-11-05-rollback:c5b89e54-5127-4500-b6b4-e63f35efdc8d:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Machu Pirqa', '4f77cb92d75d4dc51512430aaaab68a7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (None, ''1000 - 1500 AD'') is shared by 5 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81284", "url": "remediation_change_log", "quote": "phase4:p4-2027:chunk-0001: description ''Machu Pirqa (Quechua for \"old wall\") is a Chachapoyas funerary site in Peru\\''s Amazonas Region, situated at 1,900 m on the left bank of the Kuntichaka River near the entrance of Shihual Cave. Dating to approximately 1100-1300 AD, its stone buildings were constructed with mud cement to house the remains of Chachapoya dignitaries. The structures feature characteristic high-relief friezes with rhomboidal and zigzag patterns. The site lies along the Qhapaq Nan trail network between Chachapoyas and Kuelap.'' -> ''Machu Pirqa is an archaeological site of the Chachapoyas culture in Peru [1]. It is located in the Amazonas Region, Chachapoyas Province, Magdalena District [1]. Machu Pirqa is situated at a height of about 1,900 metres on the left bank of the river Kuntichaka, an affluent of the Utcubamba River [1].''"}, {"source": "remediation_change_log:108007", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:108008", "url": "remediation_change_log", "quote": "2026-09-26d_