    ('c621bee7-f67e-4969-8bb0-d9b801d14e0f'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:c621bee7-f67e-4969-8bb0-d9b801d14e0f:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Pikimachay', '1a57553414288aeac4754a8885d112c0', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81286", "url": "remediation_change_log", "quote": "phase4:p4-2027:chunk-0001: description \"Pikimachay (Piki Mach''ay) is a cave archaeological site in the Ayacucho Valley of Peru. Radiocarbon dating indicates a human presence ranging from 22,200 to 14,700 years ago, though this evidence has been disputed with a more conservative date of 12,000 years BCE proposed [1].\" -> ''Piki Mach\\''ay (Quechua piki flea, mach\\''ay cave, \"flea cave\", also spelled Pikimachay, Piquimachay, where machay means \"drunkenness\", \"to get drunk\" or \"a spindle packed with thread\") is an archaeological site in the Ayacucho Valley of Peru [1]. Richard S. MacNeish was the first archaeologist to explore Piki Mach\\''ay [1]. The cave is part of the Ayacucho complex, a culture defined by several cave sites including Jaya Mach\\''ay [1]. Piki Mach\\''ay yielded some of the oldest plant remains in Peru, including an 11,000-year-old bottle gourd [1]. Strata from later periods at the site revealed fishtail point arrows, manos, and metates [1].''"}, {"source": "remediation_change_log:108020", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: perio