    ('c663e466-6644-4d97-9fb5-24d85eddb646'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:c663e466-6644-4d97-9fb5-24d85eddb646:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Rock Shelter of Solhapa', 'e29f8764f5c24a0795698e8ab42627e2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27846", "url": "remediation_change_log", "quote": "phase3:batch-0017:chunk-0001: site_type ''Rock relief/carving'' -> ''Rock art''"}, {"source": "remediation_change_log:35998", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Rock art'' -> ''Rock relief/carving''"}, {"source": "remediation_change_log:87350", "url": "remediation_change_log", "quote": "phase4:p4-2169:chunk-0001: description ''A prehistoric rock shelter in Duas Igrejas, Miranda do Douro, Portugal, within the International Douro Natural Park. A huge granite slab has protected Bronze Age engravings of geometric and human shapes for thousands of years. The cover of the grotto bears an engraving interpreted as representing a sorcerer, similar to examples found in Spain and France. The human figure has a trapezoidal head ending in points resembling branches, with lines at the waist suggesting a tail and erect phallus.'' -> ''The Rock shelter of Solhapa is a Paleolithic archaeological site in Duas Igrejas, Miranda do Douro [1]. On the cover of the grotto is an engraving, similar to others found in Spain and France, and which have been interpreted as representing a sorcerer [1]. It is a representation of a human figure, whose head, in a trapezoidal configuration, ends in points resembling a pair of branches [1]. The remaining sculptures can be found either on the interior walls of the cave or on the floor [1]. The iconographic diversity is great with dimples, perpendicular features, semicircles and straight and interconnected bars, almost labyrinthine [1]. There is also an element in the form of a snake and human figures, chronologically bounded between the end of the Neolithic period and the beginning of the Chalcolithic / Bronze Age [1].''"}, {"source": "remediation_change_log:124176", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:124177", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:124178", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: site_type ''Rock relief/carving'' -> ''Rock art''"}, {"source": "remediation_change_log:161505", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Abrigo_rupestre_da_Solhapa_-_Freguesia_de_Duas_Igrejas,_concelho_de_Miranda_do_Douro,_distrito_de_Bragança,_Portugal_-_13.jpg/400px-Abrigo_rupestre_da_Solhapa_-_Freguesia_de_Duas_Igrejas,_concelho_de_Miranda_do_Douro,_distrito_de_Bragança,_Portugal_-_13.jpg'' -> ''/data/images/wiki/c663e466/Abrigo rupestre da Solhapa - Freguesia de Duas Igrejas, concelho de Miranda do Douro, distrito de Bragança, Portugal - 15.webp''"}, {"source": "remediation_change_log:253197", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:253198", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_start None -> ''-10000''"}, {"source": "remedia