    ('c70fe2a7-a7d0-4b6e-b59d-b4d1510573bf'::uuid, 'antiquity', '2', '5', 'card-stats-2026-11-05-rollback:c70fe2a7-a7d0-4b6e-b59d-b4d1510573bf:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Pusuquy Pata', '60daf06a6485be21ee3d576cd861e1bb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 2 from period_start 600"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81290", "url": "remediation_change_log", "quote": "phase4:p4-2027:chunk-0001: description \"Pusuquy Pata (also known as Posoqoypata) is a Wari culture cemetery in the Huanta District of Peru''s Ayacucho Region, dating to the Middle Horizon period (c. AD 600-1000). Accidentally exposed by a bulldozer in 2000, rescue excavations revealed twelve cylindrical stone-and-clay burial cists and a rectangular mortuary chamber (2.2m x 1.2m) with an east-facing entrance containing remains of multiple individuals. These tomb forms were previously unknown for the Wari culture, and the chamber''s accessible design suggests ancestor veneration practices.\" -> \"Pusuquy Pata (Ayacucho Quechua pusuquy a cactus, pata step, bank of a river, hispanicized spelling Posoqoypata) or Ch''illiku Pampa is an archaeological site in the Ayacucho Region in Peru [1]. It is located in the Huanta Province, Huanta District [1]. The site consists of tombs of the Wari culture [1].\""}, {"source": "remediation_change_log:108037", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:108038", "url": "remediation_change_log", "quote": "