    ('c80bf1e4-215a-440d-9e2e-848c40348037'::uuid, 'mystery', '3', '8', 'card-stats-2026-11-05-rollback:c80bf1e4-215a-440d-9e2e-848c40348037:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Krapina Neanderthal Site', 'f6aa49aece298939a7d6c1f0eb585fb2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28516", "url": "remediation_change_log", "quote": "phase3:batch-0153:chunk-0001: site_type ''Museum'' -> ''Archaeological site''"}, {"source": "remediation_change_log:37511", "url": "remediation_change_log", "quote": "phase4:p4-0057:chunk-0001: description \"The Krapina Neanderthal site at Husnjakovo Hill near Krapina, Croatia, is one of the world''s most important paleoanthropological sites. Discovered in 1899 by Dragutin Gorjanovic-Kramberger, it yielded approximately 900 fossil bones from around 80 Neanderthal individuals aged 2 to 27, alongside 1,200 Mousterian stone tools and 2,400 animal bones. The remains date to approximately 125,000 years ago. The site holds the European Heritage Label and is Croatia''s first protected paleontological monument.\" -> ''Krapina Neanderthal site, also known as Hušnjakovo Hill is a Paleolithic archaeological site located near Krapina, Croatia [1]. Krapina represents the largest known recovery of human skeletal remains from any Upper Pleistocene site [1]. The site was first discovered by Dragutin Gorjanović-Kramberger, who excavated the site between 1899 and 1905 and subsequently published two monographs [1]. The prehistoric site itself is located in a collapsed cave, nestled in a sandstone bluff overlooking the Krapinica River in Hrvatsko Zagorje [1]. More recently, it was determined that the site was about 120–130 kyr [1]. Researchers determined its date by using ESR and U-series dating [1]. 1191 lithic artifacts were discovered during the century of research at the site [1]. Eight white-tailed eagle talons and one foot phalanx were found at the site, and were dated by uranium–thorium dating to 130 000 BP [1].''"}, {"source": "remediation_change_log:124206", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: site_type ''Archaeological site'' -> ''Cave''"}, {"source": "remediation_change_log:161571", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''/data/images/wiki/c80bf1e4/hero.webp'' -> ''/data/images/wiki/c80bf1e4/Krapina-Neanderthal-1.webp''"}, {"source": "remediation_change_log:356190", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Cave'' -> ''Cave Structures''"}]'::jsonb),
