    ('c82e8c63-783d-4d7b-aead-69052b6a04a2'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:c82e8c63-783d-4d7b-aead-69052b6a04a2:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Drizzlecombe', 'f29f6aaf757c30202f6ce6e2e04f80f3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87384", "url": "remediation_change_log", "quote": "phase4:p4-2170:chunk-0001: description \"A Bronze Age ceremonial and settlement complex on Dartmoor''s southwest slope of Hartor Hill, Devon, featuring three principal stone rows each aligned roughly southwest-northeast uphill, with an associated burial cairn and terminal menhir. The tallest menhir, known as the Bone Stone, stands 4.3 metres high -- the largest on Dartmoor -- and was re-erected in 1893 by Sabine Baring-Gould and R. Hansford Worth. On the winter solstice its shadow aligns perfectly with its stone row. The site also includes the Giant''s Basin, a substantial cairn 22 metres across and 3 metres high, plus remains of at least five enclosed settlement sites with huts, additional cairns, and a stone-walled cist.\" -> \"Drizzlecombe or Thrushelcombe is an area of Dartmoor in the county of Devon, England, containing a number of Bronze Age stone rows, cairns and menhirs [1]. There are three principal stone rows each with an associated barrow and terminal menhir [1]. Most of the artifacts are on the southwest slope of Hartor Hill [1]. The tallest menhir, which at 14 ft high is the largest on Dartmoor, was re-erected by Sabine Baring-Gould, R. Hansford Worth and others in 1893 [1]. Drizzlecombe is located on the western side of Dartmoor, about 4 miles east of the village of Yelverton, to the west of the upper reaches of the River Plym [1]. Nearby is the large but damaged cairn known as Giant''s Basin; many of its stones were removed by warreners to build their rabbit-warrens at Ditsworthy, lower down the river [1]. Higher up the slope and overlooking these monuments is a village of stone hut circles [1].\""}, {"source": "remediation_change_log:108045", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:108046", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:161575", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''/data/images/wiki/c82e8c63/hero.webp'' -> ''/data/images/wiki/c82e8c63/Drizzlecombe kist 1.webp''"}, {"source": "remediation_change_log:253211", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:253212", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_start None -> ''-4000''"}, {"source": "remediation_change_log:317409", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-013: thumbnail_url ''/data/images/wiki/c82e8c63/Drizzlecombe kist 1.webp'' -> ''/data/images/wiki/c82e8c63/Drizzlecombe_large_stone.webp''"}, {"source": "remediation_change_log:352782", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:352783", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
