    ('c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359'::uuid, 'mystery', '3', '6', 'card-stats-2026-11-05-rollback:c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Fournou Korifi', '467f683ff473e894199ce1f980d46d7a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''3000 - 1500 BC'') is shared by 130 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81292", "url": "remediation_change_log", "quote": "phase4:p4-2027:chunk-0001: description \"Fournou Korifi is an Early Minoan settlement on a steep hilltop overlooking the Libyan Sea near Myrtos in southern Crete. First excavated in 1967 by Peter Warren, the roughly 100-room settlement was occupied during the Early Minoan II period (c. 2600-2170 BC) before being destroyed by fire. Notable finds include the ''Goddess of Myrtos,'' a distinctive ceramic vessel now in the Archaeological Museum of Agios Nikolaos, along with pottery workshops, weaving looms, and evidence of olive and cereal cultivation. The dense, walled hillside layout provides key insight into pre-palatial Minoan social organization.\" -> ''Fournou Korifi is the archaeological site of a Minoan settlement on southern Crete [1]. Fournou Korifi was built at the top of a steep hill, with excellent views of the coast [1]. Fournou Korifi was first excavated in 1967 by Peter Warren [1]. The settlement was in use only during the Early Minoan II period [1]. Among the artefacts excavated were two weaving looms [1].''"}, {"source": "remediation_change_log:124224", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:124225", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: period_start ''-4500'' -> ''-2600''"}, {"source": "remediation_change_log:124226", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: site_type ''City/town/settlement'' -> ''Settlement''"}, {"source": "remediation_change_log:162090", "url": "remediation_change_log", "quote": "served-image-2026-09-30-028: thumbnail_url ''/data/images/wiki/c8dc3d03/hero.webp'' -> ''/data/images/wiki/c8dc3d03/Fournou Koryfi 04.webp''"}, {"source": "remediation_change_log:326060", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/c8dc3d03/Fournou Koryfi 04.webp'' -> ''/data/images/wiki/c8dc3d03/Fournou Koryfi 37.webp''"}, {"source": "remediation_change_log:352789", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: lat ''35.007058153179614'' -> ''35.0067''"}, {"source": "remediation_change_log:352790", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: lon ''25.5900678098488'' -> ''25.6093''"}, {"source": "remediation_change_log:356192", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
