    ('c96274da-bdec-445d-a79f-2a43c0688421'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:c96274da-bdec-445d-a79f-2a43c0688421:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Escoural Cave', '49a3628d31accaf3e17a1dd88d7134cf', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Rock art'', ''< 4500 BC'') is shared by 29 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27969", "url": "remediation_change_log", "quote": "phase3:batch-0038:chunk-0001: period_start ''-500'' -> ''-50000''"}, {"source": "remediation_change_log:30502", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:81296", "url": "remediation_change_log", "quote": "phase4:p4-2027:chunk-0001: description ''Escoural Cave in Montemor-o-Novo, Portugal, discovered in 1963, is the first site in Portugal where prehistoric art was identified and the westernmost location in Europe with Paleolithic wall paintings and engravings. The earliest human occupation dates to 50,000 years ago during the Middle Paleolithic, when Neanderthal hunter-gatherers used it as a temporary shelter. Upper Paleolithic rock art (40,000-10,000 BC) includes depictions of horses, bovines, and abstract figures. During the Late Neolithic (3500-3000 BC), the cave served as a collective necropolis. Classified as a Portuguese National Monument in 1963.'' -> ''The Prehistoric Rock-Art Site of Escoural Cave is a structure known for its Paleolithic-era rock-art and funerary burial site, located in the Portuguese municipality of Montemor-o-Novo, in the civil parish of Santiago do Escoural [1]. The earliest vestiges of human occupation date back to 50,000 years B.C., associated with the interior of the cave [1]. The first occupants of the cave came from groups of Neanderthal hunter-gatherers, who used the cave as a temporary shelter in order to hunt [1]. Based on bone evidence within the cave, these groups hunted nearby aurochs, deer and horse [1]. Elements of rock art also pertain to the Upper Paleolithic (40,000 to 10,000 years B.C.) or final parts of the Neolithic period, when the interior was used as a funerary site, while a small settlement inhabited the area in the exterior [1]. During the Chalcolithic period, a human settlement existed within the cave, developing into a fortified site by the end of Copper Age [1].''"}, {"source": "remediation_change_log:108079", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:108080", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-50000'' -> None"}, {"source": "remediation_change_log:253231", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:253232", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_start None -> ''-10000''"}]'::jsonb),
