    ('c9a49774-6211-499c-b80c-9dbeec95b47c'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:c9a49774-6211-499c-b80c-9dbeec95b47c:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Quinkan Rock Art', '5895872d92692cebc07495ec39cefb58', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Rock art'', ''< 4500 BC'') is shared by 29 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:45247", "url": "remediation_change_log", "quote": "phase4:p4-0107:chunk-0001: description ''Quinkan Rock Art is a significant body of Aboriginal rock art found among sandstone escarpments near Laura, Queensland. The art features unique representations of \"Quinkans\" rendered through painting and engraving techniques. Quinkan Country was inscribed on the Australian National Heritage List on 10 November 2018 [1].'' -> ''Quinkan rock art refers to a large body of locally, nationally and internationally significant Aboriginal rock art in Australia of a style characterised by their unique representations of \"Quinkans\" (an Aboriginal mythological being, often spelt \"Quinkin\"), found among the sandstone escarpments around the small town of Laura, Queensland [1]. Quinkan Country was inscribed on the Australian National Heritage List on 10 November 2018 [1]. The Australian Heritage Commission\\''s 1980 entry on the register of the national estate describes the Quinkan rock art as being located across 230,000 hectares of rugged sandstone plateaux and escarpments 4 km south east of Laura and 50 km west of Cooktown [1]. The paintings are generally large and well preserved, and engravings of great antiquity occur [1]. Engravings of both figurative and abstract styles are found throughout Quinkan country [1].''"}, {"source": "remediation_change_log:108731", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:108732", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-25000'' -> None"}, {"source": "remediation_change_log:162111", "url": "remediation_change_log", "quote": "served-image-2026-09-30-028: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/e/ef/Quinkan5.jpg'' -> ''/data/images/wiki/c9a49774/hero.webp''"}, {"source": "remediation_change_log:253233", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:253234", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_start None -> ''-10000''"}, {"source": "remediation_change_log:317448", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-013: thumbnail_url ''/data/images/wiki/c9a49774/hero.webp'' -> ''/data/images/wiki/c9a49774/Quinkan5.webp''"}]'::jsonb),
