    ('c9ea41a4-53e0-481a-9e3c-d314cfa36c9e'::uuid, 'mystery', '1', '6', 'card-stats-2026-11-05-rollback:c9ea41a4-53e0-481a-9e3c-d314cfa36c9e:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Castro of Santa Trega', 'cda387e83db9200db078ef790a270951', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''500 BC - 1 AD'') is shared by 316 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29595", "url": "remediation_change_log", "quote": "phase3:batch-0310:chunk-0001: period_start ''-500'' -> ''-100''"}, {"source": "remediation_change_log:36012", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-100'' -> ''-500''"}, {"source": "remediation_change_log:42052", "url": "remediation_change_log", "quote": "phase4:p4-0058:chunk-0001: description ''The Castro of Santa Trega is a Castro-Roman settlement on Mount Santa Trega in A Guarda, Galicia, Spain, at 341 m above sea level overlooking the Mino River mouth. Covering about 20 hectares, it housed 3,000-5,000 inhabitants at its peak between 100 BC and 100 AD, making it one of the largest castros in northwestern Iberia. Documented origins trace to the 4th century BC. Excavations began in 1914 under the Pro-Monte Society; Cayetano de Mergelina led major campaigns from 1928-1933. Stone carvings feature geometric spirals, triskelions, and Celtic rose motifs. Declared a National Historical and Artistic Monument in 1931, the MASAT museum displays ceramics, Roman coins, and the iconic \"Cabezon\" stone head.'' -> \"The Castro of Santa Trega is an archaeological site on the hillsides of Mount Santa Trega, in the southwestern Galician municipality of A Guarda [1]. The site is strategically located overlooking the mouth of the river Miño, at 341 meters above sea level [1]. Santa Trega is a ''Castro-Roman'' settlement [1]. It was inhabited between 100 BC and 100 AD, in a period when the process of Romanisation of the northwest of the Iberian Peninsula had already begun [1]. Despite this, the construction system reflects techniques that respect the Castro tradition and has seen very little Roman influence [1]. This style is dominated by the use of circular structures [1]. Proof of human presence approximately 2,000 years before the settlement was built is confirmed by petroglyphs or rock engravings in various locations [1]. In 1862, the first recorded archaeological discovery was a bronze sculpture of Hercules found by stonemasons [1].\""}, {"source": "remediation_change_log:124234", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: lat ''41.90306258189035'' -> ''41.8927''"}, {"source": "remediation_change_log:124235", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: lon ''-8.875190269054976'' -> ''-8.8698''"}, {"source": "remediation_change_log:124236", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: site_type ''City/town/settlement'' -> ''Settlement''"}, {"source": "remediation_change_log:162115", "url": "remediation_change_log", "quote": "served-image-2026-09-30-028: thumbnail_url ''/data/images/wiki/c9ea41a4/hero.webp'' -> ''/data/images/wiki/c9ea41a4/2014 Castro de Santa Trega. A Guarda. Galiza-17.webp''"}, {"source": "remediation_change_log:317457", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-013: thumbnail_url ''/data/images/wiki/c9ea41a4/2014 Castro de Santa Trega. A Guarda. Galiza-17.webp'' -> ''/data/images/wiki/c9ea41a4/2014_Castro_de_Santa_Trega._Galiza.webp''"}, {"source": "remediation_change_log:356194", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
