    ('cab346d8-176c-429d-830c-2f1ac68e2eb9'::uuid, 'antiquity', '3', '4', 'card-stats-2026-11-05-rollback:cab346d8-176c-429d-830c-2f1ac68e2eb9:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Roman Thermae of Maximinus', 'cc72b9b79913319e933d51f3fb9666cc', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 3 from period_start 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87458", "url": "remediation_change_log", "quote": "phase4:p4-2172:chunk-0001: description ''The Roman Thermae of Maximinus are the archaeological ruins of monumental public baths in Braga, Portugal, integrated into the urban renewal of Bracara Augusta, the Roman provincial capital of Gallaecia. The large civic construction consisted of a building housing both baths and a theatre. Excavations continue to reveal the extent of this complex, representing Roman urban planning in northern Hispania.[1]'' -> ''The Roman Thermae of Maximinus, are the archaeological ruins of a monumental building and public baths, whose construction was integrated into the urban renewal of the civitas of Bracara Augusta [1]. Around the 2nd century, a theatre was constructed [1]. At the end of the 3rd century, the complex was profoundly remodelled, resulting in the substantial reduction in the total area occupied by the thermae; the remodelling of the urban structure was part of the ongoing redesign of Bracara Augusta, into the provincial capital of Gallaecia by Diocletian [1]. This meant that by the 4th century even the theatre was deactivated, and the stones used to construct the city walls [1].''"}, {"source": "remediation_change_log:108752", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:108753", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-500'' -> None"}, {"source": "remediation_change_log:162148", "url": "remediation_change_log", "quote": "served-image-2026-09-30-028: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/9c/Termas_romanas_Alto_da_Cividade.jpg'' -> ''/data/images/wiki/cab346d8/TERMAS ROMANAS DE MAXIMINOS 1.webp''"}, {"source": "remediation_change_log:242825", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:242826", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-100''"}, {"source": "remediation_change_log:317475", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-013: thumbnail_url ''/data/images/wiki/cab346d8/TERMAS ROMANAS DE MAXIMINOS 1.webp'' -> ''/data/images/wiki/cab346d8/Termas_romanas_Alto_da_Cividade.webp''"}, {"source": "remediation_change_log:352798", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''500 BC - 1 AD'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:352799", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-100'' -> ''1''"}]'::jsonb),
