onstruct the city walls [1].''"}, {"source": "remediation_change_log:108752", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:108753", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-500'' -> None"}, {"source": "remediation_change_log:162148", "url": "remediation_change_log", "quote": "served-image-2026-09-30-028: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/9c/Termas_romanas_Alto_da_Cividade.jpg'' -> ''/data/images/wiki/cab346d8/TERMAS ROMANAS DE MAXIMINOS 1.webp''"}, {"source": "remediation_change_log:242825", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:242826", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-100''"}, {"source": "remediation_change_log:317475", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-013: thumbnail_url ''/data/images/wiki/cab346d8/TERMAS ROMANAS DE MAXIMINOS 1.webp'' -> ''/data/images/wiki/cab346d8/Termas_romanas_Alto_da_Cividade.webp''"}, {"source": "remediation_change_log:352798", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''500 BC - 1 AD'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:352799", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-100'' -> ''1''"}]'::jsonb),
