    ('cb4e0159-7d70-4981-900a-908015803e7b'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:cb4e0159-7d70-4981-900a-908015803e7b:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Jacket''s Field Long Barrow', '6b4274d5ad6bae5a8ea0306feee97389', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87470", "url": "remediation_change_log", "quote": "phase4:p4-2172:chunk-0001: description \"Jacket''s Field Long Barrow is an unchambered long barrow located near the village of Boughton Aluph in Kent, England. Constructed during the fourth millennium BCE in Britain''s Early Neolithic period, it consists of an earth-built, sub-trapezoidal tumulus, oriented east-southeast to west-southwest and flanked by side ditches [1].\" -> \"Jacket''s Field Long Barrow is an unchambered long barrow located near to the village of Boughton Aluph in the south-eastern English county of Kent [1]. It was probably constructed in the fourth millennium BCE, during Britain''s Early Neolithic period [1]. Built out of earth, the long barrow consists of a sub-trapezoidal tumulus flanked by side ditches [1]. Although representing part of an architectural tradition of long-barrow building that was widespread across Neolithic Europe, Jacket''s Field Long Barrow belongs to a localised regional variant of barrows produced in the vicinity of the River Stour [1]. Of these, it lies on the western side of the river, while Julliberrie''s Grave and Shrub''s Wood Long Barrow are found on the eastern side [1].\""}, {"source": "remediation_change_log:108763", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:108764", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:162182", "url": "remediation_change_log", "quote": "served-image-2026-09-30-028: thumbnail_url ''/data/images/wiki/cb4e0159/hero.webp'' -> \"/data/images/wiki/cb4e0159/Jacket''s Field Long Barrow (North Face - 01).webp\""}, {"source": "remediation_change_log:242828", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:242829", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''-4000''"}, {"source": "remediation_change_log:317496", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-013: thumbnail_url \"/data/images/wiki/cb4e0159/Jacket''s Field Long Barrow (North Face - 01).webp\" -> \"/data/images/wiki/cb4e0159/Jacket''s_Field_Long_Barrow_I.webp\""}]'::jsonb),
