    ('ccf25f6a-36aa-458a-9d43-5b33ef8c119c'::uuid, 'empire_count', '1', '0', 'card-stats-2026-11-05-rollback:ccf25f6a-36aa-458a-9d43-5b33ef8c119c:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Borough Hill', '91cdbc7a4629f712dfc176bbdefa04ce', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 1 from tag_site(52.254938486814574, -1.140072918077397, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87534", "url": "remediation_change_log", "quote": "phase4:p4-2174:chunk-0001: description ''Borough Hill is a prominent hilltop east of Daventry, Northamptonshire, rising over 200 m above sea level. It contains two Bronze Age bowl barrows, two Iron Age hillforts -- one being the fourth largest in Britain -- and a Roman building complex with a barrow cemetery. The large multivallate hillfort extends over 1.5 km north to south across the oblong hilltop. Partial excavation in 1823 revealed two human burials within one barrow mound. The entire complex is designated a Scheduled Monument, reflecting continuous occupation from the Bronze Age through the Roman period.'' -> ''Borough Hill is a hill to the east of the town of Daventry in the English county of Northamptonshire [1]. It is over 200 metres above sea level and dominates the surrounding area [1]. Borough Hill has a history of human habitation dating into prehistory [1]. Remains have been found on the hill of two Bronze Age barrows, two Iron Age hillforts, one of which is the fourth largest found in Britain, and a later Roman villa and farming settlement [1]. The hill is designated as a scheduled monument [1]. The site then underwent a full excavation in 1852 by local historian Beriah Botfield who recorded his findings [1].''"}, {"source": "remediation_change_log:124288", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:124289", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:124290", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: site_type ''Barrow'' -> ''Fort''"}, {"source": "remediation_change_log:124291", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: source_url ''https://en.wikipedia.org/wiki/Borough_Hill'' -> ''https://her.northamptonshire.gov.uk/Monument/MNN3603''"}, {"source": "remediation_change_log:162267", "url": "remediation_change_log", "quote": "served-image-2026-09-30-028: thumbnail_url ''/data/images/wiki/ccf25f6a/hero.webp'' -> ''/data/images/wiki/ccf25f6a/Borough Hill 18 - panoramio.webp''"}, {"source": "remediation_change_log:253255", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:253256", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_start None -> ''-800''"}, {"source": "remediation_change_log:352813", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:352814", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-800'' -> None"}]'::jsonb),
