    ('cdd96b01-efff-4896-acca-a97484a9f87c'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:cdd96b01-efff-4896-acca-a97484a9f87c:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Earl Shilton', 'e205d22b386fc252d0c854c3c0257bdc', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87568", "url": "remediation_change_log", "quote": "phase4:p4-2175:chunk-0001: description ''Earl Shilton is a market town in Leicestershire, England, with roots in Iron Age and Roman-period settlement. The area was inhabited by the Corieltauvi, a confederation of Belgic warriors who arrived from continental Europe after c. 100 BC and built the Salt Road, an ancient trackway connecting east and west Leicestershire along the southern edge of the Great Leicester Forest. By AD 47, the Corieltauvi welcomed Roman legions as protection against their neighbours the Brigantes. A Roman pottery was established on Shilton Heath, producing grey ware pots from the early 2nd century AD using local clay deposits.'' -> ''The village of Earl Shilton would evolve on Shilton Hill in what would be south Leicestershire [1]. Below the hill ran an ancient trackway known as the Salt Road, connecting east and west Leicestershire [1]. Earl Shilton lay in the kingdom of the Middle Angles [1]. Earl Shilton, like many English villages, first appears in recorded history in the Domesday Book of 1086 [1]. One of the parcels of land granted to Hugh de Grandmesnil by William the Conqueror was the village of Scheltone, now known as Earl Shilton [1].''"}, {"source": "remediation_change_log:108807", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:108808", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-500'' -> None"}, {"source": "remediation_change_log:162827", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url ''/data/images/wiki/cdd96b01/hero.webp'' -> ''/data/images/wiki/cdd96b01/View towards Earl Shilton - geograph.org.uk - 678046.webp''"}, {"source": "remediation_change_log:253263", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:253264", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s018: period_start None -> ''-500''"}, {"source": "remediation_change_log:352819", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:352820", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-500'' -> None"}]'::jsonb),
