    ('ce8a19e4-c1b3-42e6-9bf9-4eb5600c0650'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:ce8a19e4-c1b3-42e6-9bf9-4eb5600c0650:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Chauvet Cave', 'ea1139e99ffb9a15ad96d887b1ea4827', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28400", "url": "remediation_change_log", "quote": "phase3:batch-0125:chunk-0001: period_start ''-500'' -> ''-32000''"}, {"source": "remediation_change_log:30506", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:81324", "url": "remediation_change_log", "quote": "phase4:p4-2028:chunk-0001: description \"The Chauvet-Pont-d''Arc Cave in the Ardèche department of southeastern France contains some of the best-preserved figurative cave paintings in the world, with evidence of Upper Paleolithic life[1]. Located near Vallon-Pont-d''Arc on a limestone cliff above the former bed of the Ardèche river in the Gorges de l''Ardèche, the cave represents a remarkable achievement in early human artistic expression[1].\" -> ''Rather than depicting only the familiar herbivores that predominate in Paleolithic cave art, i.e. horses, aurochs, mammoths, etc., the walls of the Chauvet Cave feature many predatory animals, e.g., cave lions, leopards, bears, and cave hyenas [1]. There are also paintings of rhinoceroses [1]. Typical of most cave art, there are no paintings of complete human figures, although there are two partial \"Venus\" figures: one within a niche or vestibule of the End Chamber, and the other on a roughly conical or dental-shaped pendant several metres away; both are composed of what appears to be a vulva attached to an incomplete pair of legs [1]. Above the pendant Venus, and in contact with it, is a bison head, which has led some to describe the composite drawing as a Minotaur [1]. There are a few panels of red ochre hand prints and hand stencils made by blowing pigment over hands pressed against the cave surface [1].''"}, {"source": "remediation_change_log:162873", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url ''/data/images/wiki/ce8a19e4/hero.webp'' -> ''/data/images/wiki/ce8a19e4/Etologic horse study, Chauvet cave.webp''"}, {"source": "remediation_change_log:317558", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-013: thumbnail_url ''/data/images/wiki/ce8a19e4/Etologic horse study, Chauvet cave.webp'' -> ''/data/images/wiki/ce8a19e4/Rhinos_Chauvet_Cave.webp''"}]'::jsonb),
