    ('cf8b5d56-cbc8-4550-bd77-4dc259020bad'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:cf8b5d56-cbc8-4550-bd77-4dc259020bad:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Wurdi Youang Stone Arrangement', 'b73bd93dcd3948c85a9a2c9189a17327', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87604", "url": "remediation_change_log", "quote": "phase4:p4-2176:chunk-0001: description ''Wurdi Youang is an Aboriginal stone arrangement at Mount Rothwell, Victoria, Australia [1]. The site was acquired by the Indigenous Land Corporation on 14 January 2000 and transferred to the Wathaurong Aboriginal Co-operative on 17 August 2006 [1].'' -> ''Wurdi Youang is the name attributed to an Aboriginal stone arrangement located off the Little River – Ripley Road at Mount Rothwell, near Little River [1]. The stone arrangement takes the form of an irregular egg-shape or ovoid about 50 m (164 ft) in diameter with its major axis aligning east-west [1]. It is composed of about 100 basalt stones, ranging from small rocks about 200 mm (8 in) in diameter to standing stones about 1 m (3 ft) high with an estimated total mass of about 23 t (23 long tons) [1]. There are three prominent waist-high stones, at its western end, which is the highest point of the ring [1]. The purpose, use, and age of the arrangement are not known [1].''"}, {"source": "remediation_change_log:124336", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: period_name ''< 4500 BC'' -> None"},