].''"}, {"source": "remediation_change_log:124350", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: lat ''42.55015804695938'' -> ''42.569722''"}, {"source": "remediation_change_log:124351", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s009: lon ''-8.550021460953094'' -> ''-8.583055''"}, {"source": "remediation_change_log:162951", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url ''/data/images/wiki/cfe7373f/hero.webp'' -> ''/data/images/wiki/cfe7373f/Menhir (5529089509).webp''"}, {"source": "remediation_change_log:335229", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-003: thumbnail_url ''/data/images/wiki/cfe7373f/Menhir (5529089509).webp'' -> ''/data/images/wiki/cfe7373f/hero.webp''"}]'::jsonb),
