    ('cff3c769-e793-40f3-897c-4b085cdf9b56'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:cff3c769-e793-40f3-897c-4b085cdf9b56:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Ali Murad Mound', '8b1ae8416e345b09ea4fc16cc5cca586', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2600"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87610", "url": "remediation_change_log", "quote": "phase4:p4-2176:chunk-0001: description ''Ali Murad Mound is a Harappan-era archaeological site in the Dadu District of Sindh, Pakistan, explored and named by archaeologist N.G. Majumdar. Atop the mound, an ancient hamlet was discovered enclosed by defensive walls of stone blocks. Excavations by Mortimer Wheeler yielded Harappan pottery, terracotta figurines of bulls and pigs, chert flakes, a small bronze axe, and beads of steatite, agate, and carnelian. Located 32 km southwest of Dadu and 13 km from Ghazi Shah Mound, it represents an important Indus Valley settlement.'' -> ''The Ali Murad Mound is an archaeological site situated at Johi Tehsil, in Dadu District of Sindh, Pakistan [1]. The site was explored as well as named by archaeologist N. G. Majumdar [1]. It is located 20 miles from Dadu towards the southwest [1]. It is eight miles from Ghazi Shah Mound and 14 miles to the south of Johi town [1]. At the top of the mound, an ancient hamlet was discovered surrounded by defensive walls built with stone blocks [1].''"}, {"source": "remediation_change_log:108848", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s01