:108848", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:108849", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:162952", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url ''/data/images/wiki/cff3c769/hero.webp'' -> ''/data/images/wiki/cff3c769/Mounds of Ali Murad Shahni near Bahlil Shah.webp''"}, {"source": "remediation_change_log:253613", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:253614", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-4000''"}, {"source": "remediation_change_log:326124", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/cff3c769/Mounds of Ali Murad Shahni near Bahlil Shah.webp'' -> ''/data/images/wiki/cff3c769/Mound of village Ali Murad.webp''"}, {"source": "remediation_change_log:352837", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:352838", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> ''-2600''"}]'::jsonb),
    ('cfffa587-4250-43cb-89c2-84cad4e21c8a'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:cfffa587-4250-43cb-89c2-84cad4e21c8a:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Whetstones Stone Circle', 'fd2730ad7c60dc38026815ef9eaf93a9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87612", "url": "remediation_change_log", "quote": "phase4:p4-2176:chunk-0001: description \"The Whetstones were a stone circle beneath Corndon Hill in Church Stoke, Montgomeryshire, Wales. The circle originally comprised eight or nine stones with a major axis estimated at 30 metres. Three stones still stood in 1841, the tallest measuring 1.2m, but by the 1860s nearly all were blown up, and the last stone was uprooted around 1870 during land enclosure, with charcoal and bones found beneath it. The stones were incorporated into a boundary wall. The Whetstones were one of five probable circles recorded within two miles, alongside the surviving Hoarstones and Mitchell''s Fold.\" -> ''The Whetstones are, or were, a stone circle beneath Corndon Hill in the parish of Church Stoke, Montgomeryshire, Wales, near the border with Shropshire [1]. They lie immediately to the west of the village of White Grit and close to Priestweston [1]. The site is also a short distance from the better-known Hoarstones and Mitchell\\''s Fold circles [1]. No information on the shape of the circle survives [1]. The Reverend C. H. Hartshorne visited the site in 1841, commenting that three stones then remained, all leaning [1]. He referred to these as being \"mutilated fragments\" of the ring\\''s original appearance [1].''"}, {"source": "remediation_change_log:108850", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:108851", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:253615", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:253616", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-4000''"}, {"source": "remediation_change_log:352839", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:352840", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> None"}]'::jsonb),
