    ('d0b9e72f-73a8-4671-a01f-5cafa6e53bf8'::uuid, 'mystery', '4', '10', 'card-stats-2026-11-05-rollback:d0b9e72f-73a8-4671-a01f-5cafa6e53bf8:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Uruk', '85909965a6f3ce8de6007c9ba1cc31c1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 4 from (''City/town/settlement'', ''4500 - 3000 BC'') is shared by 87 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28038", "url": "remediation_change_log", "quote": "phase3:batch-0054:chunk-0006: site_type ''Megalithic stones'' -> ''City''"}, {"source": "remediation_change_log:42122", "url": "remediation_change_log", "quote": "phase4:p4-0060:chunk-0001: description \"One of the world''s earliest major cities, located in modern Muthanna Governorate, Iraq. Settled from the Ubaid period (before 5000 BC), Uruk rose to dominance c. 3800 BC and by 3100 BC may have housed 40,000 residents across 5.5 sq km. Two great temple complexes -- the Anu Ziggurat with its White Temple and the Eanna sanctuary dedicated to Ishtar -- dominated the city. Proto-cuneiform clay tablets discovered here, dating to c. 3300 BC, represent some of the earliest known writing. Legend credits Gilgamesh with building its 10 km city walls.\" -> ''Uruk, the archeological site known today as Warka, was an ancient city in the Near East or West Asia, located east of the current bed of the Euphrates River, on an ancient, now-dried channel of the river in Muthanna Governorate [1]. Uruk is the type site for the Uruk period and played a leading role in the early urbanization of Sumer in the mid-4th millennium BC [1]. William Kennett Loftus visited the site of Uruk in 1849, identifying it as \"Erech\", known as \"the second city of Nimrod\", and led the first excavations from 1850 to 1854 [1]. The city was formed when two smaller Ubaid settlements developed into the cities of Unug and Kullaba and later merged to become Uruk [1]. The temple complexes at their cores became the Eanna District dedicated to Inanna and the \"Anu\" District of Kullaba [1]. The Mask of Warka, also known as the \\''Lady of Uruk\\'' and the \\''Sumerian Mona Lisa\\'', dating from 3100 BC, is one of the earliest representations of the human face [1]. The Eanna district is historically significant as both writing and monumental public architecture emerged here during Uruk periods VI–IV [1].''"}, {"source": "remediation_change_log:162967", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/4/41/White_Temple_ziggurat_in_Uruk.jpg'' -> ''/data/images/wiki/d0b9e72f/معبد_كاريوس_...اوروك_...._مدينة_الوركاء_..._المثنى.webp''"}, {"source": "remediation_change_log:333004", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-006-002: thumbnail_url ''/data/images/wiki/d0b9e72f/معبد_كاريوس_...اوروك_...._مدينة_الوركاء_..._المثنى.webp'' -> ''/data/images/wiki/d0b9e72f/White Temple ziggurat in Uruk.webp''"}, {"source": "remediation_change_log:356206", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
