    ('d138312f-d127-427e-beac-f0210cf41ba8'::uuid, 'cultural_influence', '8', '7', 'card-stats-2026-11-05-rollback:d138312f-d127-427e-beac-f0210cf41ba8:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''7'' restored on Wraxall Camp', '6d1288c42ff77c3c8fba0c5fc46fcd92', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 8 from description yes, thumbnail yes, 5 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87638", "url": "remediation_change_log", "quote": "phase4:p4-2177:chunk-0001: description ''Wraxall Camp (also called Failand Camp) is a small Iron Age enclosed settlement in North Somerset, situated on carboniferous limestone upland between Wraxall and Failand villages. The sub-oval enclosure measures about 40 metres across, surrounded by an earth-and-stone bank up to 8m wide and a ditch, with a possible 3m-wide entrance on the southwest. Partial excavations in 1928 recovered black burnished pottery sherds and a Kimmeridge shale bracelet, typical of rural Iron Age farmsteads, though these finds were later destroyed by World War II bombing. The site appears to have been a farmstead rather than a defensive fortification.'' -> ''Wraxall Camp, or Failand Camp, is a small round earthwork in Somerset [1]. The remains are indistinct and thickly covered by woods, but it appears to have been an Iron Age farmstead, and not a defensive structure [1]. Wraxall Camp is a scheduled monument in the parish of Wraxall and Failand in North Somerset, in an upland region of carboniferous limestone [1]. The site is 1.5 miles east of Wraxall village and 100 metres north of Failand village [1]. It is an Iron Age settlement with a raised oval interior about 40 metres wide on the long axis [1]. Partial excavations in 1928 found sherds of black burnished pottery and a Kimmeridge shale bracelet, typical of rural settlements in the Iron Age [1]. Minor earthworks mark the homes in the interior, which were surrounded by a bank and ditch [1]. The bank, up to 8 metres wide, was made of earth and small stones over natural rock outcrops [1].''"}, {"source": "remediation_change_log:108862", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:108863", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:108864", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: site_type ''Earthwork'' -> None"}, {"source": "remediation_change_log:162981", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/3/3a/Field_edge_boundary_%28geograph_3522458%29.jpg'' -> None"}, {"source": "remediation_change_log:243694", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: site_type None -> ''Settlement''"}, {"source": "remediation_change_log:253629", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:253630", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-1500''"}, {"source": "remediation_change_log:326138", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url None -> ''/data/images/wiki/d138312f/Field edge boundary (geograph 3522458).webp''"}, {"source": "remediation_change_log:356207", "url": "remediation_change_log", "quote": "20