    ('d1877f2c-7bdb-46ee-8368-950eacc0edd5'::uuid, 'antiquity', '5', '1', 'card-stats-2026-11-05-rollback:d1877f2c-7bdb-46ee-8368-950eacc0edd5:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''1'' restored on Palazzo a Mare', '614e407c8da370b224fabb34aab243eb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87642", "url": "remediation_change_log", "quote": "phase4:p4-2177:chunk-0001: description ''Palazzo a Mare (\"Sea Palace\") is a Roman imperial villa on the north coast of Capri, built by Augustus and later modified by Tiberius as one of his twelve island residences described by Tacitus. The villa extended 850 metres along the shoreline across multiple terraces, featuring a residential quarter, exedra, loggia, baths, a semicircular nymphaeum, and fish tanks fed by both fresh and sea water. Excavated by Amedeo Maiuri from 1932, the site was heavily damaged by marble looting in the 18th-19th centuries and military levelling, leaving only partial ruins including the Bagni di Tiberio.'' -> ''Palazzo a Mare is a well-preserved ancient Roman archaeological site on the north side of the island of Capri, consisting of an imperial palace built by Augustus and modified by Tiberius [1]. It was one of the supposed twelve villas of Tiberius on the island as described by Tacitus, along with the Villa Jovis, Villa di Gradola and Villa Damecuta [1]. It covers a very large area on several terraces overlooking the sea [1]. The palace was equipped with a semicircular nymphaeum [1]. The excavations were carried out by Amedeo Maiuri starting from 1932 [1].''"}, {"source": "remediation_change_log:108872", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:108873", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''1'' -> None"}, {"source": "remediation_change_log:162987", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url None -> ''/data/images/wiki/d1877f2c/hero.webp''"}, {"source": "remediation_change_log:253631", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:253632", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''1000''"}, {"source": "remediation_change_log:352847", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''1000 - 1500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:352848", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''1000'' -> None"}]'::jsonb),
