    ('d2db72cb-3a9d-429f-98ad-e56925fcdc43'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:d2db72cb-3a9d-429f-98ad-e56925fcdc43:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Ballowall Barrow', '201e173db8df879be92975cc57b734dd', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87686", "url": "remediation_change_log", "quote": "phase4:p4-2178:chunk-0001: description \"Complex prehistoric funerary cairn on the cliff top at Ballowall Common near St Just in Cornwall, also known as Carn Gluze. One of the largest funerary monuments along the West Penwith coastline, it spans multiple phases from the Neolithic to Bronze Age (c. 3500-2500 BC). Discovered in 1878 by William Copeland Borlase beneath tin-mining debris, excavation revealed a central domed mound with two concentric drystone walls, five cists containing Bronze Age pottery and cremated bone, and an entrance grave. Borlase''s post-excavation reconstruction complicates modern interpretation of the site.\" -> ''Ballowall Barrow is a prehistoric funerary cairn which Ashbee and Hencken state contains several phases of use from the Neolithic to the Bronze Age [1]. It is situated on the cliff top at Ballowall Common, near St Just in Cornwall, England [1]. It is also known as Carn Gluze Barrow [1]. It was first excavated in 1878 by William Copeland Borlase, when it was discovered under mining debris [1]. The barrow is 72 feet (22 m) in diameter [1]. The Cornwall and Scilly Historic Environment Record describes it as a central domed structure, containing cists and with a pit beneath, surrounded by an outer cairn also containing cists [1]. An entrance grave is located in the external side of the outer cairn [1].''"}, {"source": "remediation_change_log:108897", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:108898", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:163041", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url ''/data/images/wiki/d2db72cb/hero.webp'' -> ''/data/images/wiki/d2db72cb/Carn Gloose aka Ballowall Barrow, St Just, Cornwall.webp''"}, {"source": "remediation_change_log:243715", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:243716", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''-3500''"}, {"source": "remediation_change_log:317627", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-013: thumbnail_url ''/data/images/wiki/d2db72cb/Carn Gloose aka Ballowall Barrow, St Just, Cornwall.webp'' -> ''/data/images/wiki/d2db72cb/Ballowall Barrow, near St Just - geograph.org.uk - 660261.webp''"}]'::jsonb),
