    ('d35fe3f8-3e3e-4cb5-8008-fb4232a5db9c'::uuid, 'antiquity', '3', '4', 'card-stats-2026-11-05-rollback:d35fe3f8-3e3e-4cb5-8008-fb4232a5db9c:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Alcantarilla Dam', '2774d874f75798eb375b3fcadae29d49', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 3 from period_start 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87694", "url": "remediation_change_log", "quote": "phase4:p4-2178:chunk-0001: description ''The Alcantarilla Dam is a ruined Roman gravity dam near Mazarambroz in Toledo province, Spain, believed to date to the 2nd century BC, making it possibly the oldest known Roman dam. Standing 20 m high and at least 550 m long, it was built using opus caementitium and opus incertum masonry to supply water to the city of Toletum (Toledo) via an aqueduct passing through Layos. The dam and reservoir were constructed on a tributary of the River Tagus, but the structure may have been breached in antiquity due to insufficient strength.'' -> ''The Alcantarilla Dam is an ancient Roman gravity dam built to supply water to the Roman city of Toletum, in the Roman province of Hispania Tarraconensis [1]. It was constructed in the 2nd century BC on a tributary of the Tagus River [1]. Currently in ruins, it is located between the towns of Sonseca and Mazarambroz [1]. It is believed to be the oldest dam in Spain and possibly the oldest known Roman dam [1]. The toponym \"Alcantarilla\" means conduit and is of Arabic origin: its Latin name is unknown [1]. It was 20 metres high and at least 550 metres long [1]. The water was conveyed to the city by an aqueduct which passed through Layos [1].''"}, {"source": "remediation_change_log:108908", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:108909", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''-500'' -> None"}, {"source": "remediation_change_log:243720", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:243721", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''-200''"}, {"source": "remediation_change_log:352869", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''500 BC - 1 AD'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:352870", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-200'' -> ''1''"}]'::jsonb),
