    ('d3da22e7-2499-4573-80f1-32037b641d57'::uuid, 'antiquity', '3', '8', 'card-stats-2026-11-05-rollback:d3da22e7-2499-4573-80f1-32037b641d57:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Raw Dykes', 'f60bb764e5c8a4830589e43f317cb77e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 3 from period_start 43"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87716", "url": "remediation_change_log", "quote": "phase4:p4-2179:chunk-0001: description ''Raw Dykes is a Roman earthwork and scheduled monument in Leicester consisting of two parallel banks up to 20 metres apart with a channel between them. A 110-metre stretch survives of what was originally over 550 metres long. Its purpose remains debated: it may have been an aqueduct supplying water to the Roman town of Ratae Corieltauvorum, or a navigable transport canal. Excavations in 1938 recovered 1st-century AD pottery, and during the English Civil War, Royalist forces used part of the earthwork as an artillery position.'' -> \"Raw Dykes is a Roman earthwork and scheduled monument in Leicester [1]. The monument consists of two parallel banks up to 20 metres apart, with an excavated channel running between them [1]. A stretch 110 metres long survives, but originally the earthwork was at least 550 metres in length [1]. The first written reference to the earthwork occurs in the borough of Leicester''s accounts from 1322 [1]. During the English Civil War, Royalist soldiers used part of the earthwork as an artillery emplacement; it also appears on several 18th- and 19th-century maps [1]. Since the early modern period its length has been greatly shortened by the expansion of Leicester [1].\""}, {"source": "remediation_change_log:108922", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:108923", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''1'' -> None"}, {"source": "remediation_change_log:163066", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/d/da/Raw_Dykes_north_end.jpg'' -> ''/data/images/wiki/d3da22e7/Raw Dykes viewing enclosure.webp''"}, {"source": "remediation_change_log:253659", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:253660", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-4000''"}, {"source": "remediation_change_log:326160", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/d3da22e7/Raw Dykes viewing enclosure.webp'' -> ''/data/images/wiki/d3da22e7/Raw Dykes north end.webp''"}, {"source": "remediation_change_log:352877", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:352878", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> ''43''"}]'::jsonb),
