    ('d6665022-2763-44cd-8963-d6fb7d4cfc52'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:d6665022-2763-44cd-8963-d6fb7d4cfc52:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Flowerdown Barrows', 'd29320406453405409335b5ad06019ee', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81354", "url": "remediation_change_log", "quote": "phase4:p4-2029:chunk-0001: description \"Flowerdown Barrows is a Bronze Age burial site near Littleton, Winchester, comprising three well-preserved round barrows constructed approximately 4,000 years ago as part of a larger cemetery. The site features Hampshire''s finest disc barrow, a rare type with a flat platform 28 metres in diameter containing two low mounds, surrounded by a ditch and external bank. Two bowl barrows of 20 and 8 metres diameter complete the group. The barrows preserve the original Bronze Age land surface containing seeds and molluscs, providing valuable environmental evidence of ancient vegetation and farming practices. With roughly 75% of Hampshire''s barrows destroyed by development, this intact site is exceptionally significant.\" -> ''Flowerdown Barrows is a Bronze Age Barrow site near Littleton, Winchester, Hampshire [1]. The site has three Bronze Age burial mounds in a much larger cemetery, two bowl barrows and a well-preserved disc barrow which has been described as \"the finest in Hampshire\" [1]. The disc barrow is 28 metres in diameter and contains two circular mounds of 7 metres and 6 metres diameter respectively [1]. The larger mound is centrally positioned and has a central hollow [1]. The larger of the two bowl barrows is 20 metres in diameter and 1 metre high [1]. The other, situated close to the edge of the disc barrow, is 8 metres in diameter and only 0.3 metres high [1].''"}, {"source": "remediation_change_log:109641", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:109642", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:253673", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:253674", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-4000''"}, {"source": "remediation_change_log:352889", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:352890", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> ''-2050''"}]'::jsonb),
    ('d6665022-2763-44cd-8963-d6fb7d4cfc52'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:d6665022-2763-44cd-8963-d6fb7d4cfc52:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Flowerdown Barrows', 'd29320406453405409335b5ad06019ee', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''3000 - 1500 BC'') is shared by 34 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81354", "url": "remediation_change_log", "quote": "phase4:p4-2029:chunk-0001: description \"Flowerdown Barrows is a Bronze Age burial site near Littleton, Winchester, comprising three well-preserved round barrows constructed approximately 4,000 years ago as part of a larger cemetery. The site features Hampshire''s finest disc barrow, a rare type with a flat platform 28 metres in diameter containing two low mounds, surrounded by a ditch and external bank. Two bowl barrows of 20 and 8 metres diameter complete the group. The barrows preserve the original Bronze Age land surface containing seeds and molluscs, providing valuable environmental evidence of ancient vegetation and farming practices. With roughly 75% of Hampshire''s barrows destroyed by development, this intact site is exceptionally significant.\" -> ''Flowerdown Barrows is a Bronze Age Barrow site near Littleton, Winchester, Hampshire [1]. The site has three Bronze Age burial mounds in a much larger cemetery, two bowl barrows and a well-preserved disc barrow which has been described as \"the finest in Hampshire\" [1]. The disc barrow is 28 metres in diameter and contains two circular mounds of 7 metres and 6 metres diameter respectively [1]. The larger mound is centrally positioned and has a central hollow [1]. The larger of the two bowl barrows is 20 metres in diameter and 1 metre high [1]. The other, situated close to the edge of the disc barrow, is 8 metres in diameter and only 0.3 metres high [1].''"}, {"source": "remediation_change_log:109641", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:109642", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:253673", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:253674", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-4000''"}, {"source": "remediation_change_log:352889", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:352890", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-4000'' -> ''-2050''"}]'::jsonb),
