    ('d67b3b53-ac6c-4ed9-9e37-ab42585c1247'::uuid, 'empire_count', '3', '0', 'card-stats-2026-11-05-rollback:d67b3b53-ac6c-4ed9-9e37-ab42585c1247:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Alyscamps', '4f31ce1cd8d948505dbdffb344655b59', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 3 from tag_site(43.67325076178326, 4.634037789005321, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:42146", "url": "remediation_change_log", "quote": "phase4:p4-0061:chunk-0001: description ''Alyscamps is a large Roman necropolis located just outside the ancient walls of Arles, France. One of the most famous necropolises of the ancient world, the name derives from the Provençal Occitan \"Aliscamps,\" originating from the Latin \"Elisii Campi\" [1]. The necropolis gained medieval fame, referenced by Dante in Inferno and Ariosto in Orlando Furioso [1].'' -> \"The Alyscamps is a large Roman necropolis, which is a short distance outside the walls of the old town of Arles [1]. It was one of the most famous necropolises of the ancient world [1]. The Alyscamps was Arles'' main burial ground for nearly 1,500 years [1]. It was the final segment of the Aurelian Way leading up to the city gates and was used as a burial ground for well-off citizens, whose memorials ranged from simple sarcophagi to elaborate monuments [1]. The Alyscamps continued to be used after the city was Christianised in the 4th century [1]. Saint Genesius, a Roman civil servant beheaded in 303 for refusing to follow orders to persecute Christians, was buried there and rapidly became the focus of a cult [1]. The area became a highly desirable place to be buried and tombs soon multiplied [1]. As early as the 4th century there were already several thousand tombs, necessitating the stacking of sarcophagi three layers deep [1].\""}, {"source": "remediation_change_log:109643", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:109644", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''1'' -> None"}, {"source": "remediation_change_log:163648", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''/data/images/wiki/d67b3b53/hero.webp'' -> ''/data/images/wiki/d67b3b53/0_Arles_-_Les_Alyscamps_(1).webp''"}, {"source": "remediation_change_log:253675", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:253676", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-800''"}, {"source": "remediation_change_log:318300", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/d67b3b53/0_Arles_-_Les_Alyscamps_(1).webp'' -> ''/data/images/wiki/d67b3b53/Alyscamps_road.webp''"}, {"source": "remediation_change_log:352891", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:352892", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-800'' -> None"}]'::jsonb),
