    ('d765c593-eb36-4978-b73f-534333b85bda'::uuid, 'antiquity', '5', '2', 'card-stats-2026-11-05-rollback:d765c593-eb36-4978-b73f-534333b85bda:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''2'' restored on Huaca Casa Rosada', '9ba8f2908081fa3d28ea8fdf93245995', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29398", "url": "remediation_change_log", "quote": "phase3:batch-0282:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:87754", "url": "remediation_change_log", "quote": "phase4:p4-2181:chunk-0001: description ''Huaca Casa Rosada is an archaeological site in the San Miguel district of Lima, Peru, spanning approximately 5,300 square meters. The site features a square-shaped adobe and rammed-earth platform measuring 36 meters per side and 3-4 meters high. Its occupation extends from the Middle Horizon through the Late Horizon, colonial, and republican periods, and was part of the Maranga complex under Ichma Lordship rule. Excavations in 1973-1974 uncovered colonial ceramics including French earthenware with floral motifs. Declared Cultural Heritage of the Nation in 2003.'' -> ''Huaca Casa Rosada is an archaeological site located in San Miguel District, in Lima, Peru [1]. The site presents evidence of human occupation from the Intermediate period to the Inca period and remains from the Spanish colonial and Republican periods [1]. The archaeological site consists of a square-shaped structure of approximately 36 meters on each side and around 3 to 4 meters high, formed by rammed earth and adobe to build a platform [1]. The huaca has structures with big adobes that were filled with earth and wall fragments to serve as the base for the house of Republican period, known as \"Casa Rosada\", made with Quincha and wood walls [1]. During the archaeological excavations carried out between 1973 and 1974, by the “Seminario de Arqueología” of the Pontifical Catholic University of Peru, fragments of turned and glazed pottery, earthenware and imported fine ceramics from the 16th-18th centuries were found [1]. During excavations in the early 2000s, compartments made of rammed earth walls were found at the top of the building, below the Republican house [1].''"}, {"source": "remediation_change_log:109665", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:109666", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''500'' -> None"}, {"source": "remediation_change_log:253685", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:253686", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''500''"}, {"source": "remediation_change_log:326190", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/d765c593/hero.webp'' -> ''/data/images/wiki/d765c593/HuacaCasaRosada.webp''"}, {"source": "remediation_change_log:352900", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''500 - 1000 AD'' -> ''Undated''"}, {"source": "remediation_change_log:352901", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''500'' -> None"}]'::jsonb),
    ('d765c593-eb36-4978-b73f-534333b85bda'::uuid, 'empire_count', '1', '0', 'card-stats-2026-11-05-rollback:d765c593-eb36-4978-b73f-534333b85bda:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''0'' restored on Huaca Casa Rosada', '9ba8f2908081fa3d28ea8fdf93245995', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 1 from tag_site(-12.081498828986419, -77.08748927550582, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29398", "url": "remediation_change_log", "quote": "phase3:batch-0282:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:87754", "url": "remediation_change_log", "quote": "phase4:p4-2181:chunk-0001: description ''Huaca Casa Rosada is an archaeological site in the San Miguel district of Lima, Peru, spanning approximately 5,300 square meters. The site features a square-shaped adobe and rammed-earth platform measuring 36 meters per side and 3-4 meters high. Its occupation extends from the Middle Horizon through the Late Horizon, colonial, and republican periods, and was part of the Maranga complex under Ichma Lordship rule. Excavations in 1973-1974 uncovered colonial ceramics including French earthenware with floral motifs. Declared Cultural Heritage of the Nation in 2003.'' -> ''Huaca Casa Rosada is an archaeological site located in San Miguel District, in Lima, Peru [1]. The site presents evidence of human occupation from the Intermediate period to the Inca period and remains from the Spanish colonial and Republican periods [1]. The archaeological site consists of a square-shaped structure of approximately 36 meters on each side and around 3 to 4 meters high, formed by rammed earth and adobe to build a platform [1]. The huaca has structures with big adobes that were filled with earth and wall fragments to serve as the base for the house of Republican period, known as \"Casa Rosada\", made with Quincha and wood walls [1]. During the archaeological excavations carried out between 1973 and 1974, by the “Seminario de Arqueología” of the Pontifical Catholic University of Peru, fragments of turned and glazed pottery, earthenware and imported fine ceramics from the 16th-18th centuries were found [1]. During excavations in the early 2000s, compartments made of rammed earth walls were found at the top of the building, below the Republican house [1].''"}, {"source": "remediation_change_log:109665", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:109666", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''500'' -> None"}, {"source": "remediation_change_log:253685", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:253686", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''500''"}, {"source": "remediation_change_log:326190", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/d765c593/hero.webp'' -> ''/data/images/wiki/d765c593/HuacaCasaRosada.webp''"}, {"source": "remediation_change_log:352900", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''500 - 1000 AD'' -> ''Undated''"}, {"source": "remediation_change_log:352901", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''500'' -> None"}]'::jsonb),
