1].''"}, {"source": "remediation_change_log:109669", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:109670", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''450'' -> None"}, {"source": "remediation_change_log:253689", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:253690", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-800''"}, {"source": "remediation_change_log:352904", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''1500 - 500 BC'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:352905", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_start ''-800'' -> ''450''"}]'::jsonb),
