    ('d7c375d0-6ddc-42ed-a3d4-f128c3c1d89f'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:d7c375d0-6ddc-42ed-a3d4-f128c3c1d89f:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Harhoog', 'c775767cfc73bc38d184034f81f8a104', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Dolmen'', ''3000 - 1500 BC'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27782", "url": "remediation_change_log", "quote": "phase3:batch-0008:chunk-0002: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:30516", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:87770", "url": "remediation_change_log", "quote": "phase4:p4-2182:chunk-0001: description ''A Neolithic megalithic tomb from the Funnelbeaker culture, dating to approximately 3000 BC, located near Keitum on the island of Sylt in Schleswig-Holstein, Germany. Classified as an extended dolmen, it consists of a burial chamber with a rectangular long bed constructed from large rough stone slabs. First unearthed in 1925 during construction of the Hindenburgdamm, it was scientifically examined in 1936 and relocated to its present site near the Tipkenhoog in 1954 when Sylt Airport was developed. The Funnelbeaker culture once created approximately 600 such megalithic tombs on Sylt, though only about half survive today.'' -> \"The Harhoog is a dolmen, a rectangular megalithic tomb from the Funnelbeaker culture, located near Keitum on the island of Sylt in Schleswig-Holstein [1]. The megalithic Harhoog burial chambers were originally located near the mud-flats between Keitum and Tinnum [1]. The stones were moved to the area near the Tipkenhoog on the coast near Keitum in 1954, when Sylt Airport was under development [1]. The chambers contain parallel and transverse sections [1]. The graves at Harhoog are dated to the Neolithic and belonged to ancient settlements of the island''s Funnelbeaker culture, probably around 3000 BC [1]. Harhoog dolmen is an extended dolmen, under Ernst Sprockhoff''s six-category classification; the other five types are simple dolmen, great dolmen, passage grave, long barrows (without a burial chamber) and cist [1].\""}, {"source": "remediation_change_log:109677", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:109678", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:163700", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''/data/images/wiki/d7c375d0/hero.webp'' -> ''/data/images/wiki/d7c375d0/Harhoog vom Tipkenhoog.webp''"}, {"source": "remediation_change_log:243755", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:243756", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''-3000''"}, {"source": "remediation_change_log:318331", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/d7c375d0/Harhoog vom Tipkenhoog.webp'' -> ''/data/images/wiki/d7c375d0/Megalithic_grave_Harhoog_in_Keitum,_Sylt,_Germany.webp''"}]'::jsonb),
