    ('d82e4a95-00dd-4c1d-8e94-dd201f72e331'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:d82e4a95-00dd-4c1d-8e94-dd201f72e331:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on La Chaire a Calvin', '1adc8df8497fc7227faab53447325065', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -13050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28971", "url": "remediation_change_log", "quote": "phase3:batch-0219:chunk-0001: period_start ''-500'' -> ''-13000''"}, {"source": "remediation_change_log:30518", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:81356", "url": "remediation_change_log", "quote": "phase4:p4-2029:chunk-0001: description ''La Chaire a Calvin is a Magdalenian rock shelter in the Gersac valley near Mouthiers-sur-Boëme, Charente, France. The shelter occupies a southeast-facing cliff and features a sculpted frieze dating to approximately 15,000 years BP [1]. This assemblage provides evidence of the hunting practices and environment occupied by Upper Paleolithic hunter-gatherer groups in this region of southwestern France.'' -> ''La Chaire a Calvin is a rock shelter near the village of Mouthiers-sur-Boëme in the Département of Charente, situated in the valley of the Gersac stream [1]. The shelter is on a cliff which faces south east [1]. The rock face of this rock-shelter has a sculpted frieze dated to the Magdalenian period; approximately 15000 years BP [1]. This site was studied by Pierre David from 1924 onwards, who discovered the frieze in 1926 [1]. The only human remains discovered are a single molar, discovered in 1933 and attributed to the Magdelenian [1]. The frieze is the only example of parietal art still visible in Charente [1]. The frieze includes depictions of an aurochs without its head, a pregnant tarpan, and a mating scene of tarpans [1].''"}, {"source": "remediation_change_log:109681", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:109682", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''-13000'' -> None"}, {"source": "remediation_change_log:163712", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''/data/images/wiki/d82e4a95/hero.webp'' -> ''/data/images/wiki/d82e4a95/MouthiersB1.3.webp''"}, {"source": "remediation_change_log:253697", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:253698", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-500''"}, {"source": "remediation_change_log:335250", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-003: thumbnail_url ''/data/images/wiki/d82e4a95/MouthiersB1.3.webp'' -> ''/data/images/wiki/d82e4a95/hero.webp''"}, {"source": "remediation_change_log:353683", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:353684", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-500'' -> ''-13050''"}]'::jsonb),
