    ('d85b55ee-afa3-423c-99d5-84149e5f8ee9'::uuid, 'mystery', '7', '6', 'card-stats-2026-11-05-rollback:d85b55ee-afa3-423c-99d5-84149e5f8ee9:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Makra Stoa', 'e174760ec3174b1bb23a44deefb63b4d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Archaeological site'', ''1500 - 500 BC'') is shared by 9 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29642", "url": "remediation_change_log", "quote": "phase3:batch-0318:chunk-0001: site_type ''Megalithic structures'' -> ''Archaeological site''"}, {"source": "remediation_change_log:32434", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-journal-reversal-2: site_type ''Archaeological site'' -> ''Megalithic structures''"}, {"source": "remediation_change_log:87784", "url": "remediation_change_log", "quote": "phase4:p4-2182:chunk-0001: description ''The Makra Stoa (Long Stoa) is an archaeological site in the ancient port city of Piraeus, Athens, built during the age of Pericles in the 5th century BC. Also known as the Alphitopolis Stoa, the long colonnaded building stored imported cereals -- mainly barley and wheat -- for distribution to Athens and supply of the Athenian trireme fleet. One side featured an open colonnade while the other contained rectangular shop rooms connected by a 5 m wide service road to the city wall. In 411 BC the Stoa was incorporated into the city fortifications. The fenced ruins remain visible at the corner of Akti Poseidonos and Dimitriou Gounari streets.'' -> ''The Makra Stoa was built during the time of Pericles [1]. It was also known as the Alphitopolis Stoa, from the Greek word alphita (barley flour) [1]. The Stoa was a long building which was used for the storage of imported cereals, mainly barley and wheat [1]. The cereals were then transported to the main city of Athens for consumption [1]. The Stoa also supplied the Athenian fleet of triremes and, during times of shortage, supplied the people directly [1]. The Stoa had an open facade and colonnade on one side and on the other side had shops made up of rectangular rooms [1]. The rooms alternated between small and large sizes and each shop had a space for supplying cereals and a grain storage area [1].''"}, {"source": "remediation_change_log:125550", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:125551", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:125552", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: site_type ''Megalithic structures'' -> ''Archaeological site''"}, {"source": "remediation_change_log:163716", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''/data/images/wiki/d85b55ee/hero.webp'' -> None"}, {"source": "remediation_change_log:253701", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:253702", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s019: period_start None -> ''-1500''"}]'::jsonb),
