    ('d9543648-1f50-4614-b33e-398edff7d7d6'::uuid, 'mystery', '7', '8', 'card-stats-2026-11-05-rollback:d9543648-1f50-4614-b33e-398edff7d7d6:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Tenampua', '8299558393b6eebed33a731edbac0a3c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Fortress/citadel'', ''500 - 1000 AD'') is shared by 9 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:42166", "url": "remediation_change_log", "quote": "phase4:p4-0062:chunk-0001: description \"Tenampúa is a Lenca culture archaeological site and fortress located in the Comayagua valley of central Honduras, dating to 250–500 AD [1]. The 21-hectare complex features multiple pyramidal mounds ranging from 6 to 15 metres tall and a fortified citadel situated in a strategically defensible mountainous location [1]. This early Mesoamerican site represents one of the largest and most fortified Lenca settlements in Honduras, with its elevated position providing natural defensive advantages [1]. The architectural complexity, including the massive stone structures and defensive fortifications, indicates the site''s importance as a regional center during the classical period [1].\" -> ''Tenampúa is an archaeological site belonging to the Lenca culture dating from the Mesoamerican classical period, located in central Honduras in the Comayagua valley [1]. It is known for having the interesting characteristic of several mounds of between 6 and 15 meters and a fortress inside [1]. In the area there are also some bleachers, mounds that were once a characteristic ball court of Mesoamerican cultures [1]. 250 structures have been registered on the site [1].''"}, {"source": "remediation_change_log:109709", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:109710", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''250'' -> None"}, {"source": "remediation_change_log:109711", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: site_type ''Fortress/citadel'' -> None"}, {"source": "remediation_change_log:163760", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/af/Tenampua_Lenca_Ruins.jpg'' -> ''/data/images/wiki/d9543648/Great_Wall_of_Tenampua.webp''"}, {"source": "remediation_change_log:243773", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:243774", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''750''"}, {"source": "remediation_change_log:243775", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: site_type None -> ''Fortress''"}, {"source": "remediation_change_log:356216", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Fortress'' -> ''Fortress/citadel''"}]'::jsonb),
