    ('d972a5b7-866c-48d6-af54-d9ac91f00b0b'::uuid, 'mystery', '9', '10', 'card-stats-2026-11-05-rollback:d972a5b7-866c-48d6-af54-d9ac91f00b0b:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Tahai Ceremonial Complex', '5036219c48f883a96d489b7bf152c2e4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 9 from (''Religious'', ''Undated'') is shared by 2 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27274", "url": "remediation_change_log", "quote": "2026-09-21_mechanical-country: country ''Chile, Easter Island'' -> ''Chile''"}, {"source": "remediation_change_log:87818", "url": "remediation_change_log", "quote": "phase4:p4-2183:chunk-0001: description \"The Tahai Ceremonial Complex is an archaeological site on Rapa Nui (Easter Island), in Chilean Polynesia [1]. Restored in 1974 by American archaeologist William Mulloy, the complex comprises three principal ahu (stone platforms) running north to south: Ko Te Riku, Tahai, and Vai Ure [1]. From this ceremonial center, visitors can see two additional restored ahu at Hanga Kio''e, which Mulloy restored in 1972 [1]. The site is now part of the Rapa Nui National Park, a UNESCO World Heritage site [2].\" -> ''The Tahai Ceremonial Complex is an archaeological site on Rapa Nui (Easter Island) in Chilean Polynesia [1]. Restored in 1974 by American archaeologist William Mulloy, Tahai comprises three principal ahu from north to south: Ko Te Riku (with restored eyes), Tahai, and Vai Ure [1]. Like other Mulloy restoration projects at Ahu Akivi, the ceremonial village of Orongo and Vinapu, the ceremonial center at Tahai now constitutes an integral part of the Rapa Nui National Park [1]. William Mulloy and his wife Emily Ross Mulloy are buried at Tahai [1].''"}, {"source": "remediation_change_log:109712", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:109713", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''690'' -> None"}, {"source": "remediation_change_log:109714", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: site_type ''Megalithic structures'' -> None"}, {"source": "remediation_change_log:163763", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/d/db/Tahai-Moais-2014.jpg'' -> ''/data/images/wiki/d972a5b7/Tahai-Ceremonial-Complex-2013.webp''"}, {"source": "remediation_change_log:243776", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: site_type None -> ''Religious''"}, {"source": "remediation_change_log:304144", "url": "remediation_change_log", "quote": "2026-10-04e_period-label-undated: period_name None -> ''Undated''"}, {"source": "remediation_change_log:335256", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-003: thumbnail_url ''/data/images/wiki/d972a5b7/Tahai-Ceremonial-Complex-2013.webp'' -> ''/data/images/wiki/d972a5b7/Tahai-Moais-2014.webp''"}]'::jsonb),
