    ('d9d26446-9348-4f16-b5e4-c4c11e8ccffb'::uuid, 'antiquity', '3', '4', 'card-stats-2026-11-05-rollback:d9d26446-9348-4f16-b5e4-c4c11e8ccffb:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Roman Ruins of Creiro', 'f3af3de45d94cd73bae7c07f8c10c96c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 3 from period_start 51"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87848", "url": "remediation_change_log", "quote": "phase4:p4-2184:chunk-0001: description ''The Roman Ruins of Creiro are the remains of a fish-salting factory and baths situated in the Arrabida Natural Park above Creiro Beach in the Setubal District of Portugal. First excavated in 1987, the site reveals three phases of occupation beginning in the third quarter of the 1st century AD, when nine fish-salting tanks lined with opus signinum waterproofing were constructed. The factory was linked to the broader salted-fish industries centered on ancient Cetobriga (modern Setubal) and Troia along the Sado River estuary. After abandonment at the end of the 1st century, the site was reoccupied in the mid-4th century before final abandonment around 400 AD.'' -> ''The Roman ruins of Creiro are situated in the Arrábida Natural Park above Creiro Beach in the Setúbal District of Portugal [1]. They are ruins of a fish-salting factory and Roman baths, dating back to the days when the province of Lusitania formed part of the Roman Empire [1]. The factory at Creiro was one of the smaller but older production units for salted and pickled fish and fish sauces that were exported throughout the Empire in specially designed amphorae [1]. The ruins were first identified by the archaeologist António Inácio Marques da Costa in 1907 [1]. However, he provided no detailed information about the site and it was not until 1964 when his unpublished manuscripts were discovered that the nature of the site was officially known [1]. It was only in 1987 that the first archaeological excavation was carried out, by the Museum of Archaeology and Ethnology of Setúbal District, led by Carlos Tavares da Silva [1].''"}, {"source": "remediation_change_log:109721", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:109722", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''1'' -> None"}, {"source": "remediation_change_log:163771", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/ab/Creiro1.jpg'' -> ''/data/images/wiki/d9d26446/Creiro2.webp''"}, {"source": "remediation_change_log:243779", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:243780", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''-100''"}, {"source": "remediation_change_log:326196", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/d9d26446/Creiro2.webp'' -> ''/data/images/wiki/d9d26446/Creiro1.webp''"}, {"source": "remediation_change_log:353691", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''500 BC - 1 AD'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:353692", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-100'' -> ''51''"}]'::jsonb),
