    ('da2f5fea-80b2-4c88-a5d1-738c054512b5'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:da2f5fea-80b2-4c88-a5d1-738c054512b5:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Balanica', 'f8a627c7f196967250127533898b5ff3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:45319", "url": "remediation_change_log", "quote": "phase4:p4-0109:chunk-0001: description ''A cave complex in the Sicevo Gorge near Nis, Serbia, consisting of Velika Balanica and Mala Balanica. In 2006, a fragmentary human mandible (BH-1) was discovered in Mala Balanica, dated to 392,000-525,000 years old, making it the oldest hominin fossil from the Central Balkans. The specimen lacks derived Neanderthal features and was initially classified as Homo heidelbergensis, later tentatively reassigned to Homo bodoensis. The mandible is the easternmost Middle Pleistocene hominin specimen found in Europe.'' -> \"Balanica is a cave complex, archaeological and palentological site in the City of Niš'' municipality of Niška Banja in southeast Serbia [1]. It consists of Velika Balanica and Mala Balanica [1]. The Balanica caves are located within the Sićevo Gorge, some 100 m away from the last houses in the Sićevo village [1]. Balanica caves were discovered in 2002 [1]. In 2006, a hominin hemi-mandible BH-1 was discovered at Mala Balanica [1]. The mandible was excavated in the lower stratigraphic level of the cave, 1.5 m below the artifact bearing level [1]. It was the first hominin specimen in the Central Balkans recovered through controlled excavations with firm stratigraphic context [1]. Remains in Velika Balanica make it one of the oldest localities in Europe where transition from the Lower to Middle Paleolithic is recorded [1].\""}, {"source": "remediation_change_log:109728", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:109729", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''-525000'' -> None"}, {"source": "remediation_change_log:163786", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''/data/images/wiki/da2f5fea/hero.webp'' -> ''/data/images/wiki/da2f5fea/Balanica_BH1.webp''"}, {"source": "remediation_change_log:302203", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:302204", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-300000''"}]'::jsonb),
