    ('da488c94-540b-4fdc-8d3a-0d5aba57b372'::uuid, 'mystery', '1', '6', 'card-stats-2026-11-05-rollback:da488c94-540b-4fdc-8d3a-0d5aba57b372:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Pozzuoli', 'b2dd8fc55080b2a0d0ad89d7d6d348c0', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''1500 - 500 BC'') is shared by 286 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87854", "url": "remediation_change_log", "quote": "phase4:p4-2184:chunk-0001: description \"Pozzuoli, ancient Puteoli, was founded around 529 BCE as the Greek colony of Dicaearchia (''City of Justice'') by Samian refugees fleeing the tyrant Polycrates. It became Rome''s principal Mediterranean harbor after 194 BCE, ranking second only to Delos as a maritime center. The city retains a Flavian amphitheatre seating 40,000 (third largest in Italy) and the Macellum marketplace, erroneously called the Temple of Serapis. The region''s volcanic pozzolana clay was crucial to Roman concrete innovation.\" -> \"Pozzuoli, known in antiquity as Puteoli, was established in 531 BC as the Greek colony of Dicaearchia by refugees fleeing the tyranny of Polycrates on Samos [1]. During the Second Punic War, the city''s fortified harbor withstood the advances of the Carthaginian general Hannibal [1]. At its peak during the late Republic and early Empire, Puteoli was the primary commercial port of Rome, despite being located 150 mi from the capital [1]. The city played a role in the import of wheat from Egypt to Rome and became home to a mixed population that included Greeks, Jews, Nabataeans, Phoenician merchants, and early Christians [1]. The city began to decline in the mid-1st century AD as the emperors Claudius and Trajan expanded the port of Ostia in Latium to provide a direct gateway to the Tiber [1]. The Samnites occupied Dicaearchia in 421 BC after conquering Cumae and may have changed its name to Fistelia [1]. It enjoyed considerable political and commercial autonomy favoured by the excellent position of its port with the Campanian hinterland [1].\""}, {"source": "remediation_change_log:163800", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/1/1a/Amfiteatr_Flawiuszy_w_Pozzuoli.jpg'' -> ''/data/images/wiki/da488c94/Johann_Joachim_Faber_Die_Bucht_von_Pozzuoli_bei_Neapel_1829.webp''"}, {"source": "remediation_change_log:318372", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/da488c94/Johann_Joachim_Faber_Die_Bucht_von_Pozzuoli_bei_Neapel_1829.webp'' -> ''/data/images/wiki/da488c94/Amfiteatr_Flawiuszy_w_Pozzuoli.webp''"}, {"source": "remediation_change_log:353698", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: lat ''40.84455799856999'' -> ''40.822643''"}, {"source": "remediation_change_log:353699", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: lon ''14.093408398482643'' -> ''14.121911''"}, {"source": "remediation_change_log:356218", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
