    ('dae23b93-8b4c-4e7c-961b-ca9bd54c4871'::uuid, 'antiquity', '10', '5', 'card-stats-2026-11-05-rollback:dae23b93-8b4c-4e7c-961b-ca9bd54c4871:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Trevelgue Head', 'b56b2b60cfe1e032bab9a3c39c870a44', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -10000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87860", "url": "remediation_change_log", "quote": "phase4:p4-2184:chunk-0001: description ''Trevelgue Head, also known as Porth Island, is a headland on the north-eastern edge of Newquay Bay in Cornwall, England[1]. The site encompasses an Iron Age promontory fort featuring substantial defensive ramparts, demonstrating sophisticated fortification techniques from this period[1]. Additionally, two round barrows on the headland date from the early Bronze Age, indicating earlier ritual use of this coastal location[1]. The headland projects into the Atlantic, offering commanding views over the surrounding coastline and sea approaches[1].'' -> ''Trevelgue Head, also known as Porth Island, is a headland north-east of Newquay, Cornwall, England [1]. It is the site of an Iron Age promontory fort with defensive ramparts and two round barrows dating from the early Bronze Age [1]. The peninsula is connected to the mainland at the eastern end; on the south is a natural harbour [1]. On the east side there are defensive earthworks [1]. There is a single bank and ditch on the wider part of the peninsula near the mainland [1]. The wide enclosure between this and the ramparts further west is protected by sea-cliffs on the northern side; on the south side there is a smaller drop to the sea [1]. There is a gap in the peninsula, crossed by a modern bridge where there may have been originally a land-bridge; immediately before this there are three massive banks and ditches [1]. About 600 items of worked stone, over 4,000 shards of pottery, and objects of tin, copper and iron and glass were found [1].''"}, {"source": "remediation_change_log:125580", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:125581", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:125582", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: site_type ''Fortress/citadel'' -> ''Fort''"}, {"source": "remediation_change_log:254097", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:254098", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''-800''"}, {"source": "remediation_change_log:353704", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''1500 - 500 BC'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:353705", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-800'' -> ''-10000''"}]'::jsonb),
