    ('dc277dc8-5631-484f-b07a-d1462403dd92'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:dc277dc8-5631-484f-b07a-d1462403dd92:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on The Poind and his Man', 'caa932c1f9656318dba5316d1bb52032', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2900"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:42180", "url": "remediation_change_log", "quote": "phase4:p4-0062:chunk-0001: description ''The Poind and his Man is a Late Neolithic to Early Bronze Age site near Bolam in Northumberland, consisting of a round cairn and a standing stone, designated a scheduled monument. The burial mound is 28 metres in circumference and 1.5 metres high, situated on a small knoll. The standing stone rises 2 metres above ground. In 1718, excise officer John Warburton excavated the mound and found a stone coffin about 3 feet long. A second stone was historically present but was moved to Wallington Hall in the early 18th century. In 1552, watches were set at the site to guard against Scottish raids.'' -> ''The Poind and his Man is a prehistoric site in Northumberland, England, near the village of Bolam and about 7 miles (11 km) west of Morpeth [1]. The site, consisting of a burial mound and a standing stone, is a scheduled monument [1]. The burial mound, described as a round cairn, is situated on a small knoll [1]. It dates from the Late Neolithic to Early Bronze Age [1]. Its diameter is 14 metres, and it is 1.9 metres high [1]. A standing stone, height 2 metres, is next to the mound; it was formerly one of two such stones (\"the poind and his man\") [1]. The standing stone in the grounds of Wallington Hall is thought to have been moved from here in the early 18th century [1]. The mound was partly excavated in the 18th century by John Warburton [1].''"}, {"source": "remediation_change_log:125603", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:125604", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:164313", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/0/0a/The_Poind_And_His_Man_-_geograph.org.uk_-_1941567.jpg'' -> ''/data/images/wiki/dc277dc8/hero.webp''"}, {"source": "remediation_change_log:254119", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:254120", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''-4000''"}, {"source": "remediation_change_log:353726", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:353727", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-4000'' -> ''-2900''"}]'::jsonb),
