    ('dc7253ce-0ab9-43eb-a8ca-a254f77e2d96'::uuid, 'category_group', 'Settlements', 'Monuments', 'card-stats-2026-11-05-rollback:dc7253ce-0ab9-43eb-a8ca-a254f77e2d96:category_group', 'rollback of card-stats-2026-11-05: category_group ''Monuments'' restored on Warawtampu', 'a7174c97af11b51d19b7316799288d7e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "category_group = Settlements from site_type ''City/town/settlement'' is in group ''Settlements''"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29470", "url": "remediation_change_log", "quote": "phase3:batch-0291:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:36048", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:87886", "url": "remediation_change_log", "quote": "phase4:p4-2185:chunk-0001: description \"Warawtampu (Huarautambo) is an Inca rest station and sanctuary in the Pasco Region, built between 1460-1470 during the reign of Pachakutiq at 3,600 m elevation. Positioned along the Qhapaq Nan (Inca road system) between Cusco and Cajamarca, it was considered one of the road''s most elegant stops. Key structures include Inkawasi palace, Warmiwasi, and Phaqcha, a ceremonial waterfall altar for water worship. The site features a polished stone pool and an Inca bridge. Its cultural importance was recognized when Peru''s Central Reserve Bank featured it on a commemorative coin in 2012.\" -> ''Warawtampu (Quechua waraw high and deep, tampu inn, Hispanicized spelling Huarautambo) is an archaeological site in the Pasco Region in Peru [1]. It is located in Daniel Alcides Carrión Province, Yanahuanca District, in the community of the same name [1]. The archaeological site of Astupampa is close to it [1]. The complex was built during the government of Pachakutiq Inka Yupanki [1]. Some of the most interesting buildings at Warawtampu are Inkawasi (\"Inca house\"), Warmiwasi (\"woman house\") and Phaqcha (\"waterfall\"), an altar for water ceremonies [1].''"}, {"source": "remediation_change_log:109782", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:164316", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/a0/Edificio_Inkawasi.jpg'' -> ''/data/images/wiki/dc7253ce/Sitio arqueológico Huarautambo (Inkawasi).webp''"}, {"source": "remediation_change_log:243796", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: site_type None -> ''Archaeological site''"}, {"source": "remediation_change_log:318412", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/dc7253ce/Sitio arqueológico Huarautambo (Inkawasi).webp'' -> ''/data/images/wiki/dc7253ce/Edificio_Inkawasi.webp''"}, {"source": "remediation_change_log:353728", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: site_type ''Archaeological site'' -> ''Settlement''"}, {"source": "remediation_change_log:356222", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
