    ('dce4d9db-1bf4-4430-b5e6-2e13e63e4813'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:dce4d9db-1bf4-4430-b5e6-2e13e63e4813:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Verziau of Gargantua', '24d8d8d9de762da838b47a04aeb4255c', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Megalithic stones'', ''4500 - 3000 BC'') is shared by 17 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87892", "url": "remediation_change_log", "quote": "phase4:p4-2185:chunk-0001: description ''The Verziau of Gargantua, also known as Haute-Borne, is a prehistoric menhir at Bois-les-Pargny in the Aisne department, northern France. The monolith stands 4.35 meters high and 1.50 meters wide at its base, tapering to just over 1 meter at the top, carved from locally sourced hard sandstone. First documented by Amedee Piette in 1851, it was classified as a Historic Monument in 1889. A twin menhir once stood nearby but was destroyed in the early 19th century for its stone. According to local Picard legend, a giant used the stone -- called a verziau -- to sharpen his scythe and left it on the hillside in a gesture of anger.'' -> ''The verziau of Gargantua (or vierzeux of Gargantua), also known as Haute-Borne, is a menhir at Bois-lès-Pargny in Aisne, France [1]. The menhir is north of the town of Bois-lès-Pargny, a few meters from a small copse, near Sons-et-Ronchères [1]. At the beginning of the 19th century, the menhir had a twin sister, which was destroyed to extract a large amount of sandstone [1]. Legend has it that a man of immense size was using it to sharpen his scythe, and left the rock on the site in a gesture of anger [1]. The monument was listed as a monument historique in 1889 [1].''"}, {"source": "remediation_change_log:109797", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:109798", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:164323", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/a1/Verziau_de_Gargantua%2C_Bois-l%C3%A8s-Pargny.jpg'' -> ''/data/images/wiki/dce4d9db/Verziau de Gargantua 2.webp''"}, {"source": "remediation_change_log:254127", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:254128", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''-4000''"}, {"source": "remediation_change_log:318424", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/dce4d9db/Verziau de Gargantua 2.webp'' -> ''/data/images/wiki/dce4d9db/Verziau_de_Gargantua,_Bois-lès-Pargny.webp''"}, {"source": "remediation_change_log:353733", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:353734", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:354795", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_name ''Undated'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:354796", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_start None -> ''-4000''"}]'::jsonb),
