    ('dd8e1148-5057-4496-a859-5f28c798a3f6'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:dd8e1148-5057-4496-a859-5f28c798a3f6:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Punta de Chimino', 'c7a9521b1dc60fe91fd151527687a12b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -700"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87916", "url": "remediation_change_log", "quote": "phase4:p4-2186:chunk-0001: description ''Located in the Petexbatún region of Guatemala, Punta de Chimino was a Maya settlement spanning the Preclassic to Terminal Classic periods. After a Late Preclassic population surge and Early Classic decline, the site experienced renewed growth in the Terminal Classic, becoming one of the few urban centers to survive the political disintegration of the Petexbatún kingdom after the fall of Dos Pilas. Seibal subsequently intervened and politically dominated the site.[1]'' -> ''Punta de Chimino is a Maya archaeological site in the Petexbatún region of the department of Petén in Guatemala [1]. Occupation at the site dates to the Preclassic and Classic periods of Mesoamerican chronology [1]. The site is located on a peninsula on the western side of Lake Petexbatún [1]. In the Late Classic a series of defensive ditches were excavated across the base of this peninsula in order to fortify the site [1]. The site is one of very few locations in the Pasión drainage to have erected major architecture during the Terminal Classic, including a corbel-vaulted temple, large palace platforms and a very large ballcourt [1]. The neck of the peninsula was fortified with three moats, one of which was 12 metres deep, each moat was topped by a palisaded wall [1]. The area between these moats was used for intensive agriculture and included box gardens divided by crude stone walls [1].''"}, {"source": "remediation_change_log:109804", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:109805", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''1'' -> None"}, {"source": "remediation_change_log:109806", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:243803", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: site_type None -> ''City''"}, {"source": "remediation_change_log:254131", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:254132", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''1''"}, {"source": "remediation_change_log:345738", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_name ''1 - 500 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:345739", "url": "remediation_change_log", "quote": "2026-10-09a_fields-wd5-s001: period_start ''1'' -> ''-700''"}, {"source": "remediation_change_log:356223", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
