    ('dde240ca-5969-4123-a842-e7e235f7566b'::uuid, 'mystery', '3', '6', 'card-stats-2026-11-05-rollback:dde240ca-5969-4123-a842-e7e235f7566b:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Langweiler - Archaeological Site', '80c749382f28735fa210f55327c36431', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''< 4500 BC'') is shared by 105 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27804", "url": "remediation_change_log", "quote": "phase3:batch-0011:chunk-0005: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:36055", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Archaeological site'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:87922", "url": "remediation_change_log", "quote": "phase4:p4-2186:chunk-0001: description \"Langweiler is a Bandkeramik archaeological site in the Merzbach Valley on the Aldenhovener Plateau of western Germany, dating to 5300-4900 BC. Systematic excavations from 1973 to 1981 revealed 160 houses across eight settlement sites, plus three enclosures and a cemetery. The founding settlement, Langweiler 8, shows continuous occupation across 13 phases of roughly 25 years each. Houses were predominantly longhouses (83%) built with post-and-wattle-and-daub construction, providing key data on Europe''s earliest farming communities.\" -> ''Langweiler is an archaeological site situated in the Merzbach Valley on the Aldenhovener Plateau of western Germany [1]. Systematic excavations have revealed evidence of 160 houses from eight distinct settlement sites, plus three enclosures and a cemetery, belonging to the period 5300-4900 BC [1]. The site is a key region for understanding the nature of the earliest farming societies in west-central Europe (Bandkeramik era) [1]. Extensive surveys done from 1973 to 1981 contributed to recovery of the largest settlements in the valley before destruction of the area for mining [1]. The settlement at Langweiler 8 lasted over 300 years, with permanent occupation of about 15 houses [1]. The agricultural basis for these Bandkeramik settlements is reconstructed as small-scale cereal cultivation in fixed plots adjacent to the settlements [1]. During the latest stage of the Merzbach Bandkeramik period, special enclosures were constructed which may have been the setting for social or ritual activities by whole communities [1].''"}, {"source": "remediation_change_log:109812", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:109813", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''-5300'' -> None"}, {"source": "remediation_change_log:109814", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:243805", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:243806", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''-5300''"}, {"source": "remediation_change_log:243807", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: site_type None -> ''Settlement''"}, {"source": "remediation_change_log:356225", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Settlement'' -> ''City/t