    ('df056ae9-c7c1-4a2d-93f9-76e9d6bd0f93'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:df056ae9-c7c1-4a2d-93f9-76e9d6bd0f93:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Bodrum Antique Theatre', '75418213b61cdd045687978c5e43feb7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Theatre'', ''500 BC - 1 AD'') is shared by 28 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28114", "url": "remediation_change_log", "quote": "phase3:batch-0075:chunk-0001: site_type ''Megalithic structures'' -> ''Theatre''"}, {"source": "remediation_change_log:87966", "url": "remediation_change_log", "quote": "phase4:p4-2187:chunk-0001: description ''The Theatre at Halicarnassus is a Greco-Roman theatre in Bodrum, Turkey, possibly built under Carian satrap Mausolos in the 4th century BC, though some scholars date it to the Hellenistic period. With a cavea width of 86 metres and a capacity of 10,000-13,000 spectators, it was significantly enlarged by the Romans in the 2nd century AD. By the 3rd century it was adapted for gladiatorial contests and animal hunts. The theatre still hosts cultural events including the Bodrum International Ballet Festival.'' -> ''The Theatre at Halicarnassus, also known as Bodrum Antique Theatre, is a 4th-century BC Greco-Roman theatre located in Bodrum, Turkey [1]. The theatre is considered to be built in a similar style to Ancient Theatre of Epidaurus [1]. Construction of the Theatre at Halicarnassus is attributed to the reign of the Carian Satrap Mausolos during the 4th century BC [1]. With a cavea width of 86 meters and an 18 meters orchestra diameter, the theatre originally had a seating capacity of 10,000 to 13,000 people [1].''"}]'::jsonb),
