    ('df0881e1-4fd6-4d2d-b9de-ffdca718970c'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:df0881e1-4fd6-4d2d-b9de-ffdca718970c:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Odeon of Philippopolis', 'ad1e78e476ce29565710c66bcf059fee', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Theatre'', ''1 - 500 AD'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:87968", "url": "remediation_change_log", "quote": "phase4:p4-2187:chunk-0001: description ''The Odeon of Philippopolis served as the bouleuterion (city council hall) and covered theatre of ancient Plovdiv, located in the northeast corner of the Roman forum. Built during the reign of Hadrian in the 2nd century AD, it underwent four construction periods before its abandonment in the 4th century. The rectangular structure seated 300-350 people and contained a skene, orchestra, and cavea with vaulted seating supports similar to the Colosseum in Rome. Discovered in 1988 by archaeologists Z. Dimitrov and Maya Martinova, it was designated a national cultural monument in 1995.'' -> ''The Odeon of Philippopolis was the house of the city council of citizens of ancient Plovdiv [1]. It was also used as a theatre due to its appropriate structure [1]. The Odeon buildings had four construction periods: from the 2nd century AD when it was initially built to the 4th century AD when it was abandoned [1]. Evidence of the 250/1 destruction by the Goths has been discovered around the Odeon [1]. The Odeon of Philippopolis was discovered near General Gurko Street in the northeastern corner of the Roman forum in Plovdiv [1]. The Odeon was a rectangular building which comprised typical elements for roofed theatres like skene, orchestra and cavea [1]. The skene was two stories high and built in the Corinthian order which was typical for the period [1]. The Odeon of Philippopolis was discovered in 1988 by the archeologist Z. Dimitrov and Maya Martinova [1].''"}, {"source": "remediation_change_log:164373", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/ad/Odeon_plovdiv.jpg'' -> ''/data/images/wiki/df0881e1/AncientRomanOdeon-Plovdiv001.webp''"}, {"source": "remediation_change_log:318451", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/df0881e1/AncientRomanOdeon-Plovdiv001.webp'' -> ''/data/images/wiki/df0881e1/Odeon_plovdiv.webp''"}]'::jsonb),
