    ('df70e98f-a1d1-4998-966a-d9a4ee2a945f'::uuid, 'mystery', '6', '8', 'card-stats-2026-11-05-rollback:df70e98f-a1d1-4998-966a-d9a4ee2a945f:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Piruro', '72b9ac38713a46da4ff23c4d5a7afc36', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Fortress/citadel'', ''3000 - 1500 BC'') is shared by 19 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28265", "url": "remediation_change_log", "quote": "phase3:batch-0102:chunk-0001: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:30523", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:87974", "url": "remediation_change_log", "quote": "phase4:p4-2187:chunk-0001: description ''Piruro is a multi-period archaeological complex in the Huanuco Region, Huamalies Province, Tantamayo District, situated at over 3,800 metres above sea level. Known as the \"skyscrapers of America,\" the site features some of the tallest pre-Columbian buildings grouped at high altitude. Occupation spans from the Final Preceramic (3000-2500 BC) through the Inca Empire, comprising two sections named Piruro I and Piruro II. Declared National Cultural Heritage in 2002, the site was researched by Bertrand Flornoy and the French Institute of Andean Studies from 1957 to 1975.'' -> ''Piruro (possibly from Quechua for whorl) is an archaeological site in Peru [1]. It is situated in the Huánuco Region, Huamalíes Province, Tantamayo District [1]. The complex consists of two parts named Piruro I and Piruro II [1]. This archaeological zone has had a long occupation: Its first vestiges date from 3000 to 2500 years B.C. (Final Preceramic), and they extend until the Inca Empire (Late Horizon) [1]. The Fortress of Piruro II can be found on the right side of the river Tantamayo over 3.8 km above sea level [1]. The fortress is composed of walls built with stones hewn in squared shape and uniform size [1]. The building is a five-story structure with rectangular doors and windows on its front area [1]. Currently the building is enclosed by stone walls measuring approximately 1 1/2 meters in height [1].''"}, {"source": "remediation_change_log:109830", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:109831", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:109832", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s020: site_type ''Temple complex'' -> None"}, {"source": "remediation_change_log:164381", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/d/de/Complejo_arqueol%C3%B3gico_piruro_hu%C3%A1nuco.PNG'' -> ''/data/images/wiki/df70e98f/Piruro 02123.webp''"}, {"source": "remediation_change_log:243813", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:243814", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''-3000''"}, {"source": "remediation_change_log:243815", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: site_type None -> ''Fortress''"}, {"source": "remediation_change_log:318454", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-0