    ('df9d4d4a-20d8-4384-ab5b-1e28e625cee4'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:df9d4d4a-20d8-4384-ab5b-1e28e625cee4:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Azykh Cave', '7c21eb0eef0a4ace54661e58c61a70dd', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''Cave Structures'', ''< 4500 BC'') is shared by 113 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:42216", "url": "remediation_change_log", "quote": "phase4:p4-0063:chunk-0001: description ''A six-cave complex near Azykh village in Azerbaijan, discovered in 1960 by Mammadali Huseynov. The site contains 10 cultural layers spanning over a million years, with the oldest dated to ~1.19 million years ago. In 1968, a Neanderthal-like jawbone estimated at 350,000-400,000 years old was found. The cave preserves evidence of Acheulean culture and early Homo erectus occupation, referred to locally as \"Guruchai culture\". It is on Azerbaijan\\''s UNESCO tentative list.'' -> ''Azykh Cave, also referred to as Azokh Cave, is a six-cave complex in Azerbaijan, known as a habitation site of prehistoric humans [1]. It is situated near the village of Azykh in the Khojavend District [1]. The cave is an important prehistoric site which has been occupied by different human groups over time [1]. The cave was discovered in 1960 by the Azerbaijan National Academy of Sciences under the leadership of Mammadali Huseynov and is considered to be the site of one of the most ancient locations of proto-human presence in Eurasia [1]. The poor quality of the 1960s excavation, in which no taphonomic data was collected, led to uncertainties over the chronological sequence of the layers [1]. Excavations resumed in the mid-1990s [1].''"}, {"source": "remediation_change_log:110488", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:110489", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-500'' -> None"}, {"source": "remediation_change_log:164382", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''/data/images/wiki/df9d4d4a/hero.webp'' -> ''/data/images/wiki/df9d4d4a/Azokh.webp''"}, {"source": "remediation_change_log:243816", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:243817", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''-700000''"}, {"source": "remediation_change_log:318457", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/df9d4d4a/Azokh.webp'' -> ''/data/images/wiki/df9d4d4a/Azokh_Cave4.webp''"}]'::jsonb),
