    ('e0ffa4e7-7b44-473d-af17-99abdfbef90e'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:e0ffa4e7-7b44-473d-af17-99abdfbef90e:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Lugbury Long Barrow', '63a9e0170848e9483de7e91ce8d9d412', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:42224", "url": "remediation_change_log", "quote": "phase4:p4-0063:chunk-0001: description \"Lugbury Long Barrow is a Neolithic chambered tomb of the Cotswold-Severn tradition near Nettleton in Wiltshire, England, constructed between approximately 3800 and 3625 BC. Originally measuring 219 by 78 feet, it contained four stone cists on its southern side with seven, zero, nine, and ten skeletons respectively, discovered during George Poulett Scrope''s 1854 excavation. The eastern end features a large capstone resting against two upright limestone slabs forming a false entrance portal. Designated Scheduled Monument SM 12290, the barrow is now classified as at risk due to ploughing encroachment.\" -> ''Lugbury Long Barrow is a prehistoric long barrow in Wiltshire, England, about 0.6 miles east of Nettleton and about 1 mile north-west of Castle Combe [1]. The monument is one of many long barrows in Dorset, Hampshire and Wiltshire [1]. Dating from the early to middle Neolithic periods, they are the burial places of early farming communities [1]. The mound, on level ground, is orientated west–east [1]. The size of the mound before excavation is thought to have been about 209 by 78 feet [1]. Towards the eastern end are the remains of a chamber: a capstone, about 12 by 6 feet, leaning against two upright stones (all of limestone), which formed the false entrance portal to the mound [1]. George Scrope excavated the site from 1854 to 1855, and a report was written by John Thurnam [1]. Four burial chambers were found, three of which contained a total of twenty-six skeletons of adults and children of both sexes [1].''"}, {"source": "remediation_change_log:110504", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:110505", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:164464", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''/data/images/wiki/e0ffa4e7/hero.webp'' -> ''/data/images/wiki/e0ffa4e7/Chamber at Lugbury Long Barrow as seen from the West.webp''"}, {"source": "remediation_change_log:243828", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:243829", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''-3700''"}, {"source": "remediation_change_log:326263", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/e0ffa4e7/Chamber at Lugbury Long Barrow as seen from the West.webp'' -> ''/data/images/wiki/e0ffa4e7/The chamber of Lugbury Long Barrow from the south.webp''"}]'::jsonb),
