    ('e1e4e79c-a9c4-4169-8fde-371c0df79061'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:e1e4e79c-a9c4-4169-8fde-371c0df79061:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Theatre Area of Pompeii', '1632bc9ad7105ab0b8a42c891f71ccc9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Theatre'', ''500 BC - 1 AD'') is shared by 28 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29493", "url": "remediation_change_log", "quote": "phase3:batch-0296:chunk-0001: site_type ''Megalithic structures'' -> ''Theatre''"}, {"source": "remediation_change_log:45359", "url": "remediation_change_log", "quote": "phase4:p4-0110:chunk-0001: description \"The Theatre Area of Pompeii comprises the Large Theatre, the Odeon, and the Quadriporticum, forming the city''s entertainment district in its southwest quarter. The Large Theatre, built into a natural hillside in the 2nd century BC during the Samnite era, seated approximately 5,000 spectators and was one of the earliest permanent stone theatres in the Roman world. The roofed Odeon, constructed around 80-75 BC, accommodated up to 1,000 for intimate musical and poetic performances. All structures were preserved under volcanic ash from Vesuvius''s eruption in 79 AD.\" -> ''The theatre area of Pompeii is located in the southwest region of the city [1]. There are three main buildings that make up this area: the Large Theatre, the Odeon (small theatre), and the Quadriporticum [1]. These served as an entertainment and meeting centre of the city [1]. The Large Theatre was built into a natural hill in the second century BC and was one of the first permanent stone theatres in the Roman empire [1]. It sat roughly 5,000 spectators [1]. Around 2 BC, the theatre was renovated and presented to the city of Pompeii as a gift by two relatives, M. Holconius Rufus and M. Holconius Celer, according to an inscription in the theatre [1]. The Odeon was a smaller roofed theatre, theatrum tectum, that sat 1500 spectators and was built in 80 BC [1].''"}, {"source": "remediation_change_log:164484", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/e/e0/Pompei_17_35_25_282000.jpeg'' -> ''/data/images/wiki/e1e4e79c/Pompei_17_35_25_282000.webp''"}]'::jsonb),
