    ('e282f2a0-5fbd-445b-81dc-63432936feff'::uuid, 'antiquity', '8', '10', 'card-stats-2026-11-05-rollback:e282f2a0-5fbd-445b-81dc-63432936feff:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Amazmaz', 'f8caec059bc76b4bc5f77037c598ed29', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -4000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:42260", "url": "remediation_change_log", "quote": "phase4:p4-0064:chunk-0001: description ''An isolated steep-sided elevation on the western Adrar plateau in Mauritania, approximately 400 km northeast of Nouakchott. At its base lie the gueltas of Amazmaz, a chain of rock-sheltered ponds surrounded by rushes that have sustained life for millennia. The slopes above the water feature Neolithic rock paintings, part of a broader Saharan pastoral art tradition (c. 5500-2000 BC) depicting cattle, hunting scenes, and human figures. The Adrar region contains roughly thirty known rock art sites documenting the transition from a wetter Saharan climate to the present desert.'' -> ''Amazmaz is an isolated elevation with steep slopes in the western part of the Adrar plateau in Mauritania, 400 km northeast of the capital Nouakchott [1]. At the foot of the hill there are the gueltas of Amazmaz, a chain of ponds, hidden among rocks and surrounded by rushes, but used for thousands of years, as evidenced by the rock paintings on the slopes bordering the waters [1].''"}, {"source": "remediation_change_log:125673", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_name ''500 BC -