    ('e2a08d7d-4038-4738-9702-4eb316357521'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:e2a08d7d-4038-4738-9702-4eb316357521:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on La Grotte des Fées', 'c218e1fb7ec5e0beaf0a7cd0a7b735e5', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81384", "url": "remediation_change_log", "quote": "phase4:p4-2031:chunk-0001: description ''A Palaeolithic cave site in Chatelperron, Allier department, central France, serving as the type site for the Chatelperronian culture (c. 38,000-32,000 BP), a transitional industry created by the last Neanderthals. First discovered around 1840 during railway construction, the caves were excavated by Dr. Guillaume Bailleau between 1867 and 1872, and later by Henri Delporte in the 1950s, who identified Mousterian and Chatelperronian occupation levels. Abbe Breuil selected Chatelperron in 1906 to name this prehistoric culture, characterized by distinctive backed blades known as Chatelperron knives. The site provides key evidence for understanding the Middle to Upper Palaeolithic transition in western Europe.'' -> ''La Grotte des Fées is a cave located in Châtelperron, in the central French department of Allier [1]. The name refers to three caves, of which one is collapsed [1]. The caves are located in the commune of Châtelperron, about 1 km north of the town [1]. Two interlinked caves were first discovered around 1840, perhaps in 1848, during the construction of the railway which used to link the mines from Bert to Dompierre-sur-Besbre [1]. A third cave (today collapsed), was discovered in 1867 by Bailleau [1]. Several thousand flint blades and mammoth tusks of over 2 metres (6 ft 7 in) long were found [1]. The last research, from 1951 to 1954 and in 1962, was led by Henri Delporte and revealed back blades of flint, burins, drills and scrapers [1].''"}, {"source": "remediation_change_log:110549", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:110550", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-500'' -> None"}, {"source": "remediation_change_log:164508", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''/data/images/wiki/e2a08d7d/hero.webp'' -> ''/data/images/wiki/e2a08d7d/Upper Paleolithic scrapers Wellcome M0015595.webp''"}, {"source": "remediation_change_log:254175", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:254176", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''-500''"}, {"source": "remediation_change_log:326312", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/e2a08d7d/Upper Paleolithic scrapers Wellcome M0015595.webp'' -> ''/data/images/wiki/e2a08d7d/Châtelperron - grotte des fées - 2.webp''"}, {"source": "remediation_change_log:353756", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:353757", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-500'' -> None"}]'::jsonb),
