    ('e2fab8b2-fe0a-4691-9556-3fc8d71ed312'::uuid, 'antiquity', '5', '2', 'card-stats-2026-11-05-rollback:e2fab8b2-fe0a-4691-9556-3fc8d71ed312:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''2'' restored on Tirefour Castle', 'fcd47d89a9c2e5ad5a2cf97c7a4aca37', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -800"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29254", "url": "remediation_change_log", "quote": "phase3:batch-0261:chunk-0001: site_type ''Minaret/tower'' -> ''Fortification''"}, {"source": "remediation_change_log:36063", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Fortification'' -> ''Minaret/tower''"}, {"source": "remediation_change_log:88054", "url": "remediation_change_log", "quote": "phase4:p4-2189:chunk-0001: description \"(800 BC - 1st c. AD) Tirefour Castle is an Iron Age broch located 4 km north of Achnacroish on the island of Lismore, Scotland [1]. The tower sits on a rocky height along the island''s east coast, commanding views of Ben Nevis to the north, Ben Cruachan to the east, and the Paps of Jura to the south [1]. The structure features a steep northwest slope and a southeast slope descending into a rolling plateau [1]. As a surviving example of prehistoric defensive architecture, it represents the Iron Age settlement patterns of the Scottish islands [1].\" -> ''Tirefour Castle, (or Tirefour Broch, also spelled Tirfuir and Tirrefour) is an Iron Age broch located 4 kilometres north of Achnacroish on the island of Lismore, Scotland [1]. Tirefour Castle is situated on a rocky height on the east coast of the island of Lismore [1]. The broch was probably built in the late Iron Age [1]. It was inhabited during the Roman era as shown by the discovery of an enamel brooch in the foundation layer [1]. Among the finds in the broch was a decorative pin from the 8th century and a Norse pin and rivets, dating from the 11th or 12th century [1]. Tirefour Castle has an almost circular floor plan [1]. The lower floor has a solid, dry stone wall [1]. The wall is on average 3 metres high and survives to a maximum height of 4.9 metres in the southeast corner [1].''"}, {"source": "remediation_change_log:110553", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:110554", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:164515", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/91/Tirefour_Broch_20100929.jpg'' -> ''/data/images/wiki/e2fab8b2/DSCN3763 Tirefour Broch.webp''"}, {"source": "remediation_change_log:254179", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:254180", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''800''"}, {"source": "remediation_change_log:318531", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/e2fab8b2/DSCN3763 Tirefour Broch.webp'' -> ''/data/images/wiki/e2fab8b2/Tirefour_Broch_20100929.webp''"}, {"source": "remediation_change_log:353763", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''500 - 1000 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:353764", "url": "remediation_change_log", "quot