    ('e355bfda-5a11-4b50-813f-8212abdd0009'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:e355bfda-5a11-4b50-813f-8212abdd0009:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Tischofer Cave', '6525e13615deb3a62948820c30c23edb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81388", "url": "remediation_change_log", "quote": "phase4:p4-2031:chunk-0001: description ''The Tischofer Cave is a cave in the Kaisertal valley in the Kaisergebirge mountains of Austria. The roughly 40 metre long cave, about 8.5 metres high at the entrance, was occupied by cave bears during the Paleolithic as evidenced by numerous excavated skeletal remains [1]. Bone tools made of cave bear bones and skulls, dated to about 27,000–28,000 years ago, were discovered here [1]. This makes the Tischofer Cave the oldest known uncontested site of human occupation in Tyrol [1]. The cave also served as a locally important gathering place and weapons cache during the Tyrolean Rebellion in the Napoleonic Wars [1].'' -> ''The Tischofer Cave is a cave in the Kaisertal valley in the Kaisergebirge mountains in Austria [1]. The roughly 40 m long cave, which is about 8.5 m high at the entrance, was occupied by cave bears and other predators as shelter during the Paleolithic as evidenced by numerous excavated skeletal remains [1]. Bone tools of paleo-human inhabitants made of cave bear bones and skulls discovered here and dated to about 27,000 - 28,000 years ago may be viewed in the local history museum in the fortress at Kufstein [1]. That dating makes the Tischofer Cave the oldest known uncontested site of human occupation in Tyrol [1]. Discoveries of more recent human skeletons and associated tools also indicate that the cave served as a copper smithy and foundry during the Bronze Age [1].''"}, {"source": "remediation_change_log:110557", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:110558", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-500'' -> None"}, {"source": "remediation_change_log:164526", "url": "remediation_change_log", "quote": "served-image-2026-09-30-031: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/b/b2/WAF-Exkursion_Vorderkaiserfelden_16.jpg'' -> ''/data/images/wiki/e355bfda/Tischoferhöhle I.webp''"}, {"source": "remediation_change_log:254181", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:254182", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''-500''"}, {"source": "remediation_change_log:318543", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/e355bfda/Tischoferhöhle I.webp'' -> ''/data/images/wiki/e355bfda/WAF-Exkursion_Vorderkaiserfelden_16.webp''"}, {"source": "remediation_change_log:353765", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:353766", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-500'' -> None"}]'::jsonb),
