11: period_start None -> ''-18000''"}, {"source": "remediation_change_log:326328", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/e3cf8ea1/hero.webp'' -> ''/data/images/wiki/e3cf8ea1/Sanghao Cave Stone cutters.webp''"}]'::jsonb),
    ('e3df9803-11c3-47ca-8cd2-39265d32470b'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:e3df9803-11c3-47ca-8cd2-39265d32470b:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Madjedbebe', 'c69e6416bbb3b25a9f8b4730ea2dc4d8', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -63050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28200", "url": "remediation_change_log", "quote": "phase3:batch-0091:chunk-0005: period_start ''-500'' -> ''-63000''"}, {"source": "remediation_change_log:30525", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:81390", "url": "remediation_change_log", "quote": "phase4:p4-2031:chunk-0001: description ''Madjedbebe is a sandstone rock shelter in Arnhem Land, Northern Territory, Australia, representing possibly the oldest site of human habitation in Australia. Located approximately 50 km from the coast, the site is situated within the traditional lands of the Mirarr people, an Aboriginal clan of the Gaagudju people. The site is surrounded by Kakadu National Park but lies within the former Jabiluka Mineral Leasehold. [1]'' -> ''Madjedbebe (formerly known as Malakunanja II) is a sandstone rock shelter in Arnhem Land, in the Northern Territory of Australia, possibly the oldest site of human habitation in Australia [1]. It is located about 50 kilometres from the coast [1]. It is part of the lands traditionally inhabited by the Mirarr, an Aboriginal Australian clan of the Gaagudju people, of the Gunwinyguan language group [1]. More than 100,000 artefacts have been excavated, including flaked stone artefacts, ground stone axe heads, grinding stones, animal bones, shellfish remains, ground ochre, charcoal, seeds and human burials [1]. Some of these were buried more than 2.5 metres below the surface [1]. Archaeobotanical investigations have demonstrated the exploitation of plant foods, including seeds, tubers and pandanus nuts [1]. In 1973 archaeologist Johan Kamminga carried out a small-scale test pit excavation to a depth of nearly 2.5 m below surface [1].''"}, {"source": "remediation_change_log:110569", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:110570", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-63000'' -> None"}, {"source": "remediation_change_log:254189", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:254190", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''-500''"}, {"source": "remediation_change_log:353769", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:353770", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-500'' -> ''-63050''"}]'::jsonb),
