    ('e3e42f8a-9a6e-438b-bd2f-69b883334600'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:e3e42f8a-9a6e-438b-bd2f-69b883334600:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Spy Cave', '812f54c310789a578b82b5eb9831be99', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88088", "url": "remediation_change_log", "quote": "phase4:p4-2190:chunk-0001: description ''Spy Cave is located in Wallonia near Spy in the municipality of Jemeppe-sur-Sambre, Namur Province, Belgium above the left bank of the Orneau River [1]. Classified as a premier Heritage site of the Walloon Region, the site ranks among the most significant Paleolithic sites in Europe [1]. The cave consists of numerous small chambers and corridors [1].'' -> ''Spy Cave (French: Grotte de Spy) is located in Wallonia near Spy in the municipality of Jemeppe-sur-Sambre, Namur Province [1]. The cave consists of numerous small chambers and corridors [1]. In 1886 Neanderthal fossils of excellent quality were discovered [1]. The excavation was conducted by Liège-based archaeologist Marcel de Puydt and geologist Max Lohest [1]. In 2018, researchers succeeded in extracting DNA from Spy94a, an upper right molar that has been directly dated to around 39,150-37,880 BP [1]. Almost 12,000 faunal remains of the Pleistocene were discovered, including mammoth, horse, cave hyena, woolly rhinoceros, reindeer, and cave bear bones [1]. Evidence of occupation by Upper Paleolithic anatomically modern humans has also been found at Spy [1].''"}, {"source": "remediation_change_log:110571", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:110572", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-35000'' -> None"}, {"source": "remediation_change_log:165018", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/7/7d/Spygrot.jpg'' -> ''/data/images/wiki/e3e42f8a/Spy Cave - 11.webp''"}, {"source": "remediation_change_log:254191", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:254192", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''-500''"}, {"source": "remediation_change_log:318550", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/e3e42f8a/Spy Cave - 11.webp'' -> ''/data/images/wiki/e3e42f8a/Spygrot.webp''"}, {"source": "remediation_change_log:353771", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:353772", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-500'' -> None"}]'::jsonb),
