    ('e427d7bf-01bd-4238-b972-b0ff62511a9e'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:e427d7bf-01bd-4238-b972-b0ff62511a9e:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Leubingen Tumulus', 'debb889d4880e34392a33f208dcdd2c8', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Mound/tumulus'', ''3000 - 1500 BC'') is shared by 14 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88092", "url": "remediation_change_log", "quote": "phase4:p4-2190:chunk-0001: description ''The Leubingen Tumulus (German: Furstengrab von Leubingen) is an Early Bronze Age \"princely\" grave dating to approximately 1940 BC [1]. Located near the Kyffhauser hills in Leubingen, Thuringia, Germany, it is a significant elite burial from the Early Bronze Age [1].'' -> ''The Leubingen tumulus is an Early Bronze Age \"princely\" grave of the Leubingen culture dating to about 1940 BC [1]. It is located near the hills of Kyffhäuser in Leubingen [1]. The site was first unearthed in 1877 by Jena art professor and archaeologist Friedrich Klopfleisch [1]. The earthen mound is 7 metres high and contains a burial chamber of 3.90 by 2.10 metres with a maximum height of 1.70 metres [1]. The original height of the mound was around 8.5 metres and its diameter was 34 metres [1]. In a central position lay the body of a man about 50 years old [1].''"}, {"source": "remediation_change_log:165021", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''/data/images/wiki/e427d7bf/hero.webp'' -> ''/data/images/wiki/e427d7bf/Fürstengrab von Leubingen.webp''"}, {"source": "remediation_change_log:318562", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/e427d7bf/Fürstengrab von Leubingen.webp'' -> ''/data/images/wiki/e427d7bf/MUFT_-_Leubingen_Fürstengrab_1_Rekonstruktion.webp''"}]'::jsonb),
