    ('e45af002-3182-479c-984e-0692325c40c7'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:e45af002-3182-479c-984e-0692325c40c7:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Roman Theatre, Benevento', '2c4252be368ce3b9887203209acd4cb6', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Theatre'', ''1 - 500 AD'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28948", "url": "remediation_change_log", "quote": "phase3:batch-0217:chunk-0001: site_type ''Megalithic structures'' -> ''Theatre''"}, {"source": "remediation_change_log:88094", "url": "remediation_change_log", "quote": "phase4:p4-2190:chunk-0001: description \"The Roman Theatre in Benevento, southern Italy, was constructed in the 2nd century AD during the reign of Emperor Hadrian [1]. It was built near the city''s cardo maximus and abandoned during the Lombard period [1]. The structure is now enveloped by the medieval Rione Triggio district [1]. The venue continues to host concerts, performances, and other cultural events [1].\" -> \"The Roman Theatre (Italian: Teatro romano di Benevento) is an ancient Roman edifice in Benevento [1]. It was built in the 2nd century by emperor Hadrian near the city''s cardo maximus (126 AD) [1]. Abandoned in Lombard times, it is now surrounded by the medieval Rione (district) Triggio [1]. The theatre has a semicircular plan with a diameter of 90 meters: it could originally house some 10,000/15,000 spectators [1]. The cavea has mostly survived [1]. The large scene features remains of three monumental gates which led to the orchestra; at the latter''s side are the remains of the parodoi, of which the right one has kept the pavement mosaic and the polychrome marble walls, which likely characterized most of the theatre originally [1].\""}, {"source": "remediation_change_log:165026", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/0/02/Roman_Theater_terraces_and_stage.jpg'' -> ''/data/images/wiki/e45af002/Benevento - Entrata al Teatro Romano.webp''"}, {"source": "remediation_change_log:318565", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/e45af002/Benevento - Entrata al Teatro Romano.webp'' -> ''/data/images/wiki/e45af002/Roman_Theater_terraces_and_stage.webp''"}]'::jsonb),
