    ('e62c980a-351d-40c1-8297-05f52f72a59c'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:e62c980a-351d-40c1-8297-05f52f72a59c:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Nysa Bridge', '9dd72a97564b0f1760f3dd69f0527015', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81412", "url": "remediation_change_log", "quote": "phase4:p4-2032:chunk-0001: description ''The Nysa Bridge is a late Imperial Roman bridge spanning the Cakircak stream in the ancient city of Nysa (modern Sultanhisar) in Aydin Province, Turkey. The 100-metre-long structure was the second largest tunnel-bridge substructure in antiquity after Pergamon, featuring a two-level design: a bottom vault spanning the brook with arched superstructure connecting two hills of the urban area. The vault is made of rubble stone in mortar on ashlar block foundations. Nysa itself dates to the 3rd century BC and preserves a theater, stadium, library, and three bridges as examples of Roman engineering.'' -> ''The Nysa Bridge is a late imperial Roman bridge over the Cakircak stream in Nysa in the ancient region of Caria [1]. The 100 m long substructure was the second largest of its kind in antiquity, after the Pergamon Bridge [1]. The Nysa Bridge served as a substructure for the area in front of the city theatre [1]. It was built as a two-level structure: the bottom vault spanned the brook [1]. On top of it a row of arches connected the two hills that formed the urban area [1]. The ground arch spanned the stream on a length of some 100 m, giving the bridge the appearance of a tube or a tunnel, although it was constructed entirely above ground [1]. It consists of a single, 5.7 m wide vault whose uphill mouth widens to 7 m [1].''"}, {"source": "remediation_change_log:110603", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:110604", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''1'' -> None"}, {"source": "remediation_change_log:165075", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/c/c7/The_late_imperial_Roman_bridge%2C_the_100_m_%28328_ft%29_long_substructure_was_the_second_largest_of_its_kind_in_antiquity_after_the_Pergamon_Bridge%2C_Nysa_on_the_Meander%2C_Turkey_%2820254375673%29.jpg'' -> ''/data/images/wiki/e62c980a/hero.webp''"}, {"source": "remediation_change_log:254207", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:254208", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''43''"}, {"source": "remediation_change_log:318598", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/e62c980a/hero.webp'' -> ''/data/images/wiki/e62c980a/The_late_imperial_Roman_bridge,_the_100_m_(328_ft)_long_substructure_was_the_second_largest_of_its_kind_in_antiquity_after_the_Pergamon_Bridge,_Nysa_on_the_Meander,_Turkey_(20254375673).webp''"}, {"source": "remediation_change_log:353777", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:353778", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''43'' -> None"}]'::jsonb),
