    ('e6b90e74-f7c5-40fa-846f-6ffab5ac8beb'::uuid, 'antiquity', '4', '3', 'card-stats-2026-11-05-rollback:e6b90e74-f7c5-40fa-846f-6ffab5ac8beb:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Ta'' Kaċċatura', '68bf09021b0c2799c62f498b17665f44', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 4 from period_start -200"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:42298", "url": "remediation_change_log", "quote": "phase4:p4-0065:chunk-0001: description \"Ta'' Kaccatura is an archaeological complex on the outskirts of Birzebbuga, southern Malta, featuring a rustic Roman villa and underground cisterns. The villa, built around a peristyle courtyard with twelve Coralline Limestone columns, confirms a thriving olive oil industry during the Punic and Roman periods. Some structures use opus africanum technique linked to Phoenician and Punic building traditions from Carthage. A major rock-cut cistern preserves the only surviving Roman concrete roof on the island, with visible reed impressions from its construction. The site was cleared by Thomas Ashby in 1915, who published findings in the Journal of Roman Studies.\" -> \"Ta'' Kaċċatura is an archaeological complex on the outskirts of Birżebbuġa, in southern Malta [1]. The complex includes a rustic Roman villa and a number of underground cisterns [1]. The villa confirms the presence of a thriving olive oil industry in this part of the Maltese islands [1]. The remains rest on a long, flat ridge flanked by two valleys, Wied Dalam to the north-east and Wied Żembaq to the south-west [1]. The site was mostly untouched in the late 19th century, with investigations only resuming under the direction of Thomas Ashby and Temi Żammit in 1915 [1]. Ashby''s descriptions remain the principal sources of information on the rustic villa [1].\""}, {"source": "remediation_change_log:110614", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:110615", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-500'' -> None"}, {"source": "remediation_change_log:165083", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/3/39/Kaccatura_masonry_wall.jpg'' -> ''/data/images/wiki/e6b90e74/Kaccatura_masonry_wall.webp''"}, {"source": "remediation_change_log:254213", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:254214", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s020: period_start None -> ''43''"}, {"source": "remediation_change_log:357369", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s009: period_name ''1 - 500 AD'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:357370", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s009: period_start ''43'' -> ''-200''"}]'::jsonb),
