    ('e7623642-d009-4d1f-8f0e-fa03a89be90e'::uuid, 'antiquity', '8', '9', 'card-stats-2026-11-05-rollback:e7623642-d009-4d1f-8f0e-fa03a89be90e:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''9'' restored on Grotte de Lombrives', '143a73b39f43b6845eb3bc7894c5646b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -4000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88172", "url": "remediation_change_log", "quote": "phase4:p4-2192:chunk-0001: description \"Grotte de Lombrives is one of Europe''s largest cave systems, spanning 39 km of passages across multiple levels in the Ariege Pyrenees. Excavations by Felix Regnault in the late 19th century confirmed Neolithic habitation, while Bronze Age burials and Hallstatt-period human bones were recovered in the 1980s. The Cathedral Chamber, reaching 80 m in height, could contain Notre-Dame de Paris. After the fall of Montsegur in 1244, Cathar bishop Amiel Aicard reportedly took refuge here, and the cave later sheltered Huguenots during the Wars of Religion.\" -> ''Grotte de Lombrives or Lombrives Cave is a large natural cavern located in Ornolac-Ussat-les-Bains, at the eastern edge of the Pyrénées Ariégeoises Natural Regional Park, in the Ariège department of Occitanie, in southwestern France [1]. The cave has a length of 8 km [1]. It is located inside a limestone mountain named Cap de la Lesse between the Vicdessos and Ariège valley [1]. There are three caves in this mountain, Niaux and Sabart in the Vicdessos valley, Lombrives in the Ariège valley [1]. All three caves together are 14 km long, but while it is obvious that they belong to the same system, only the caves of Niaux and Lombrives are connected; neither is connected with Sabart [1]. The caves are found on two main levels, the upper level around 650 m above sea level and the lower level around 550 m, which are the main stages of cave development [1].''"}, {"source": "remediation_change_log:110626", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:110627", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-5000'' -> None"}, {"source": "remediation_change_log:165120", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''/data/images/wiki/e7623642/hero.webp'' -> ''/data/images/wiki/e7623642/Grotte de Lombrives (LM23307).webp''"}, {"source": "remediation_change_log:254569", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:254570", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''-4501''"}, {"source": "remediation_change_log:319220", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-015: thumbnail_url ''/data/images/wiki/e7623642/Grotte de Lombrives (LM23307).webp'' -> ''/data/images/wiki/e7623642/LombrivesEntree.webp''"}, {"source": "remediation_change_log:357371", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s009: period_name ''< 4500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:357372", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s009: period_start ''-4501'' -> ''-4000''"}]'::jsonb),
