    ('e7bb01c3-14d8-4dd1-9e63-5d804927a032'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:e7bb01c3-14d8-4dd1-9e63-5d804927a032:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Temple of Proserpina', 'a3ac039d66910f46b2ea1cff40b9a693', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88204", "url": "remediation_change_log", "quote": "phase4:p4-2193:chunk-0001: description \"A Roman temple in Mtarfa, Malta, dedicated to Proserpina (the Roman Persephone), goddess of the underworld and renewal, located in a suburb outside the walls of ancient Melite. A Latin inscription discovered in 1613 records that Chrestion, a freedman of Augustus and procurator of Malta and Gozo, restored the temple''s columns, roof, and walls which had deteriorated with age. The temple featured marble construction with Corinthian columns. Its ruins were destroyed in the 17th-18th centuries when marble blocks were removed for reuse, including the trophy of Grandmaster Carafa above the Auberge d''Italie entrance and the facade of the Castellania in Valletta. In 2002, a wall from the temple''s crepidoma was discovered during construction work on Villegaignon Street.\" -> \"The Temple of Proserpina or Temple of Proserpine was a Roman temple in Mtarfa, Malta, an area which was originally a suburb outside the walls of Melite [1]. It was dedicated to Proserpina, goddess of the underworld and renewal [1]. The date of construction is unknown, but it was renovated in the 1st century BC or AD [1]. The ruins of the temple were discovered in 1613, and most of its marble blocks were later used in the decoration of buildings, including Auberge d''Italie and the Castellania in Valletta [1]. The only epigraphic evidence of the temple is the Chrestion inscription, which was discovered among its ruins in 1613 [1]. It records that the temple was already old and was threatening to collapse during the reign of Augustus in the 1st century BC or AD, and it was restored by Chrestion, the procurator of the Maltese Islands [1]. This inscription is the earliest known Latin text that was found in Malta [1]. The temple was built out of marble and its columns were in the Corinthian order [1].\""}, {"source": "remediation_change_log:110639", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:110640", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-500'' -> None"}, {"source": "remediation_change_log:165127", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/8/8a/Statue_of_St._Nicholas_in_Mtarfa_stands_on_the_site_of_the_former_Temple_of_Proserpina.jpeg'' -> ''/data/images/wiki/e7bb01c3/hero.webp''"}, {"source": "remediation_change_log:254577", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:254578", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''43''"}, {"source": "remediation_change_log:326371", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/e7bb01c3/hero.webp'' -> ''/data/images/wiki/e7bb01c3/Statue of St. Nicholas in Mtarfa stands on the site of the former Temple of Proserpina.webp''"}, {"source": "remediation_change_log:353789", "url": "remediation_change_lo