    ('e7c32c5c-3f26-483a-9d49-75ad5003c44b'::uuid, 'total_power', '19', '23', 'card-stats-2026-11-05-rollback:e7c32c5c-3f26-483a-9d49-75ad5003c44b:total_power', 'rollback of card-stats-2026-11-05: total_power ''23'' restored on Heronbridge Roman Site', '583014413b3f31d729fdb23c5ec1305f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 19 from antiquity + fortification + cultural_influence + mystery + legacy = 3 + 5 + 8 + 2 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88206", "url": "remediation_change_log", "quote": "phase4:p4-2193:chunk-0001: description ''A major Roman settlement on Watling Street, 2 km south of Chester, England, continuously occupied from the late 1st century to at least 350 AD. The site features a large industrial complex with furnaces dating to c.100-160 AD, numerous stone buildings with hypocausts, and a quayside cut into bedrock along the River Dee. A red sandstone altar dedicated to the Mother Goddesses Ollototae was found among 2nd-century debris. About 19 human skeletons from the 1930-31 excavations show evidence of violent deaths, and a post-Roman mass grave may hold casualties from the Battle of Chester (c.611 AD). Geophysical surveys revealed the settlement extended nearly a kilometre in length.'' -> ''Heronbridge Roman Site is the remains of a Roman settlement on both sides of Watling Street, about 2 kilometres south of Chester in Cheshire, England, with evidence of industrial activity in the late 1st and 2nd centuries [1]. The site was found by chance by a member of Chester Archaeological Society in 1929 [1]. Excavations took place in 1930–31 and found human remains with evidence of violent deaths [1]. Carbon-dating of two further skeletons, uncovered in 2004, is consistent with a date of death in the early 7th century [1]. The settlement was founded on the west bank of the River Dee in the late 1st century AD [1]. It became a significant settlement, with many established stone buildings and a quayside cut into the bedrock [1]. There are also indications of a river bridge in the area, and evidence of trade in coal (dated to about AD 200) has been found at the inland port [1]. After Roman occupation ended, around AD 350, the town decayed into ruin [1].''"}, {"source": "remediation_change_log:110641", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: site_type ''City/town/settlement'' -> ''Settlement''"}, {"source": "remediation_change_log:356235", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
    ('e7e75467-cc43-437e-9221-5ed85c050e63'::uuid, 'mystery', '2', '6', 'card-stats-2026-11-05-rollback:e7e75467-cc43-437e-9221-5ed85c050e63:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Zaldapa', 'c419a05a0d2743355b5fd581157bb7ed', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 2 from (''City/town/settlement'', ''1 - 500 AD'') is shared by 180 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28248", "url": "remediation_change_log", "quote": "phase3:batch-0100:chunk-0001: period_start ''1'' -> ''-800''"}, {"source": "remediation_change_log:30531", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1 - 500 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:81414", "url": "remediation_change_log", "quote": "phase4:p4-2032:chunk-0001: description \"Zaldapa was a major Late Roman fortified city in Scythia Minor, covering approximately 35 hectares near modern Abrit in northeast Bulgaria. Originally a Thracian settlement from the 8th century BC (its name meaning ''yellow water''), the fortress walls were probably built in a single campaign during the late 4th century AD. The defences included 32 towers, three main gates, and two secondary gates, with a 3-metre-wide secret tunnel connecting a water reservoir to the fortress interior. Excavations since 2014 have uncovered a Roman civic basilica (101 by 18 m), an early Christian basilica, and a bishop''s basilica, confirming Zaldapa as a major regional centre of Christianity in the 6th century.\" -> \"Zaldapa was a large Late Roman fortified city in Scythia Minor/Moesia, located near today''s Abrit [1]. Zaldapa is included in the list of fortifications renovated during the reign of Emperor Justinian I the Great (527–565) [1]. In 2015, a Greek stone inscription was discovered by the archaeologists excavating the ruins of a Christian bishop''s basilica at Zaldapa [1].\""}, {"source": "remediation_change_log:125730", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_name ''1500 - 500 BC'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:125731", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_start ''-800'' -> ''301''"}, {"source": "remediation_change_log:125732", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: site_type ''Fortress/citadel'' -> ''City''"}, {"source": "remediation_change_log:356236", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''City'' -> ''City/town/settlement''"}]'::jsonb),
