    ('e8d4bfaa-7f9f-440a-9fc9-7e5bb12f5e6e'::uuid, 'antiquity', '3', '4', 'card-stats-2026-11-05-rollback:e8d4bfaa-7f9f-440a-9fc9-7e5bb12f5e6e:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Double Arches Pit', '65f227cf576bc0f9cf58a4fead125a75', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 3 from period_start 43"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88240", "url": "remediation_change_log", "quote": "phase4:p4-2194:chunk-0001: description ''A former sand quarry near Heath and Reach, Bedfordshire, opened in 1916, now designated a Site of Special Scientific Interest. Archaeological excavations revealed a substantial Romano-British settlement, with finds including a Roman well twelve feet deep lined with rubble, multiple pottery fragments, and quern stones for grinding grain. Additional finds in the surrounding area include a possible kiln site identified in 1967 from pottery debris and a Roman coin, indicating a sizeable settlement during the 1st-5th centuries AD.'' -> ''Double Arches Pit (formerly known as New Trees Pit) was a sand quarry near the village and civil parish of Heath and Reach, Bedfordshire [1]. It is now a Site of Special Scientific Interest and a Geological Conservation Review site [1]. Archaeological excavations have concluded that a good-sized Roman settlement existed there, with multiple pieces of pottery and a Roman well being discovered [1]. The pit was opened by J. Arnold & Sons Limited in 1916 [1]. An application was made to designate the pit a Site of Special Scientific Interest in 1988 [1]. The application was made on the basis that it was the best accessible exposure to Lower Greensand and Gault in the Leighton Buzzard area [1].''"}, {"source": "remediation_change_log:125758", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:125759", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s010: period_start ''-500'' -> None"}, {"source": "remediation_change_log:254593", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:254594", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''-500''"}, {"source": "remediation_change_log:326393", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-003: thumbnail_url ''/data/images/wiki/e8d4bfaa/hero.webp'' -> ''/data/images/wiki/e8d4bfaa/Double Arches Pit.webp''"}, {"source": "remediation_change_log:353802", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''500 BC - 1 AD'' -> ''1 - 500 AD''"}, {"source": "remediation_change_log:353803", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-500'' -> ''43''"}]'::jsonb),
