    ('e8ef0cd6-6f7b-4b96-905d-e3eb22423006'::uuid, 'antiquity', '5', '7', 'card-stats-2026-11-05-rollback:e8ef0cd6-6f7b-4b96-905d-e3eb22423006:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''7'' restored on Pollena Trocchia', '241848eaa0925df1d6f303e650810183', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81416", "url": "remediation_change_log", "quote": "phase4:p4-2032:chunk-0001: description ''Pollena Trocchia, a municipality near Naples of Samnite-Etruscan origin, hosts a significant Roman bath complex at Masseria De Carolis, dating to the late 1st to early 2nd century AD. The complex comprises ten rooms on two floors, including praefurnia (furnaces), heated bath chambers with suspensurae (raised floors on pilae for hot air circulation), a cistern, and a charcoal depot. The site was partially buried by the 472 AD eruption of Vesuvius. Inhabitants returned and reoccupied the upper level before a final burial by the 505 or 512 eruption. Systematic excavations began in 2007 under the Apolline Project.'' -> ''The baths of an ancient Roman villa were discovered at Masseria De Carolis in Pollena Trocchia in 1988 and subsequently exposed [1]. The baths were built after the 79 AD eruption and before the mid-2nd century [1]. The eruptions of Vesuvius of 472 buried the lower floors but clearance work was done and occupation then continued in the upper levels until it was completely buried in the 505 and 512 eruptions [1]. The site was first discovered during construction of apartment blocks but the builders tried to destroy it as a hindrance to their work [1]. The Apolline Project identified the site and from 2005 it was cleared and annual excavations started [1]. 10 rooms of baths with massive structures have been discovered on two floors [1].''"}, {"source": "remediation_change_log:110668", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:110669", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:165219", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/0/06/Scavi_-_Pollena_Trocchia_-_2014_-_03.jpg'' -> ''/data/images/wiki/e8ef0cd6/Scavi - Pollena Trocchia - 2014 - 01.webp''"}, {"source": "remediation_change_log:254595", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:254596", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''-3000''"}, {"source": "remediation_change_log:319247", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-015: thumbnail_url ''/data/images/wiki/e8ef0cd6/Scavi - Pollena Trocchia - 2014 - 01.webp'' -> ''/data/images/wiki/e8ef0cd6/Scavi_-_Pollena_Trocchia_-_2014_-_03.webp''"}, {"source": "remediation_change_log:353804", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''3000 - 1500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:353805", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-3000'' -> None"}]'::jsonb),
