    ('e99aac35-d2da-448f-8cd2-d07c02ae007c'::uuid, 'total_power', '23', '24', 'card-stats-2026-11-05-rollback:e99aac35-d2da-448f-8cd2-d07c02ae007c:total_power', 'rollback of card-stats-2026-11-05: total_power ''24'' restored on Bosiliack Barrow', '363e46329cf37c22182131c8a825a322', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 23 from antiquity + fortification + cultural_influence + mystery + legacy = 7 + 2 + 8 + 5 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88250", "url": "remediation_change_log", "quote": "phase4:p4-2194:chunk-0001: description ''Bosiliack Barrow is a Neolithic chambered tomb on the Penwith Moors between Madron and Morvah near Bosiliack hamlet in Cornwall, England. It is a Scillonian entrance grave, a type found in Cornwall and on the Isles of Scilly. The barrow was excavated in 1984 [1][2].'' -> ''Bosiliack Barrow is a barrow on the Penwith Moors between Madron and Morvah near the hamlet of Bosiliack in Cornwall [1]. The barrow is Neolithic and was excavated in 1984, causing little disturbance to the ancient site [1].''"}]'::jsonb),
    ('e9e6da5f-9c61-444a-aa39-6a2a690813b7'::uuid, 'antiquity', '2', '3', 'card-stats-2026-11-05-rollback:e9e6da5f-9c61-444a-aa39-6a2a690813b7:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Kʼatepan', 'a896014901265136bd1d036557c29097', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 2 from period_start 950"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:42306", "url": "remediation_change_log", "quote": "phase4:p4-0065:chunk-0001: description ''K\\''atepan (meaning \"old temple\" in Chuj) is a Postclassic Maya archaeological site located 1 km east of San Mateo Ixtatan in Guatemala\\''s Huehuetenango Department. Dating to c. 950-1539 AD, the site features 19 structures in six architectural groups, centered on a small temple plaza fronting two large terraces set against a mountainside. Local tradition links the site to the Tojolabal Maya, who were reportedly expelled by the Chuj after a war over salt springs; the Tojolabal still make yearly pilgrimages from Chiapas to pray for rain.'' -> ''Kʼatepan, also known as Yolchonabʼ, is an archaeological site of the ancient Maya civilization located 1 kilometre to the east of the modern town of San Mateo Ixtatán, in the Huehuetenango Department of Guatemala [1]. The name Kʼatepan translates as \"old church\", while the alternate name of Yolchonabʼ means \"in the village\" [1]. The site consists of a small temple plaza in front of two large terraces set against a mountainside, accessed by broad stairways [1]. The site was first described by Guatemalan historian Adrián Recinos in 1913 [1]. Recinos considered Kʼatepan to be the most important ceremonial site in the northern Sierra de los Cuchumatanes mountains [1]. Kʼatepan possesses 19 structures clustered in six architectural groups [1]. The main temple measures 8 by 13.5 by 2.5 metres and stands in the centre of a small plaza [1]. A substantial portion of the southeastern corner of the temple has collapsed, revealing a substructure with finely cut stonework, perhaps belonging to its stairway [1].''"}, {"source": "remediation_change_log:110684", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''500 - 1000 AD'' -> None"}, {"source": "remediation_change_log:110685", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''500'' -> None"}, {"source": "remediation_change_log:110686", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:244702", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: site_type None -> ''Temple complex''"}, {"source": "remediation_change_log:254603", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:254604", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''43''"}, {"source": "remediation_change_log:353808", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''1 - 500 AD'' -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:353809", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''43'' -> ''950''"}]'::jsonb),
