    ('eab8cd53-0fe7-4b42-a9cc-8b9ec68ae133'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:eab8cd53-0fe7-4b42-a9cc-8b9ec68ae133:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Wade''s Causeway', 'a53df5ed6a0026e4ce4fef8903b98ab1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:42310", "url": "remediation_change_log", "quote": "phase4:p4-0065:chunk-0001: description \"Wade''s Causeway is a sinuous, linear earthwork in the North York Moors, North Yorkshire, England, potentially spanning up to 40 km (25 mi) across the moors[1]. The visible course on Wheeldale Moor extends just over 1.6 km (1 mi) and consists of a stone-surfaced trackway with flanking ditches[1]. Its origins, age, purpose and full extent remain subjects of ongoing research and debate, with suggestions ranging from Roman road to Neolithic trackway[1][2].\" -> \"Wade''s Causeway is a Roman road, or possibly a Neolithic structure, located in the North York Moors national park in North Yorkshire, England [1]. The structure has been the subject of local folklore for several hundred years and possibly for more than a millennium [1]. Its construction was commonly attributed to a giant known as Wade, a figure from Germanic mythology [1]. The stretch of the causeway on Wheeldale Moor was cleared of vegetation and excavated in the early twentieth century by a local gamekeeper interested in archaeology [1]. The first modern written record that unquestionably relates to the Wheeldale structure was in 1720 by the antiquarian John Warburton [1].\""}, {"source": "remediation_change_log:110699", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:110700", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s021: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:165253", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/0/04/Wade%27s_Causeway.jpg'' -> \"/data/images/wiki/eab8cd53/North York Moors Guide 1966 Plate 12 Wade''s Causeway.webp\""}, {"source": "remediation_change_log:254609", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:254610", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''-4500''"}, {"source": "remediation_change_log:335295", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-003: thumbnail_url \"/data/images/wiki/eab8cd53/North York Moors Guide 1966 Plate 12 Wade''s Causeway.webp\" -> ''/data/images/wiki/eab8cd53/hero.webp''"}, {"source": "remediation_change_log:353815", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:353816", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-4500'' -> None"}]'::jsonb),
