    ('eae0879c-2e4a-422d-8626-2fbf21adb227'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:eae0879c-2e4a-422d-8626-2fbf21adb227:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Barpa Langass', '8b651921bc2cd6f257f87a4499da01fb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Cairn'', ''3000 - 1500 BC'') is shared by 35 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43111", "url": "remediation_change_log", "quote": "phase4:p4-0066:chunk-0001: description ''Barpa Langass is a Neolithic chambered cairn on the northwestern slope of Ben Langass, Isle of North Uist, Outer Hebrides, Scotland, approximately 5,000 years old. Measuring about 22 metres in diameter and 5.5 metres in height, it is the only chambered cairn in the Western Isles known to retain its chamber intact. The passage grave served as a communal tribal burial site over thousands of years. Excavation by antiquarian Erskine Beveridge in the 1890s uncovered cremated human remains, charcoal, pottery fragments, and stone tool-manufacturing evidence including quartz flakes and an anvil stone still in position after six millennia.'' -> ''Barpa Langass or Langass Barp is a Neolithic chambered cairn on the Isle of North Uist in the Outer Hebrides of Scotland [1]. It measures around 22 meters in diameter by 5.5 meters in height, and is around 5,000 years old [1]. The roof is constructed of two massive slabs with a third slab superimposed [1]. The entrance is at the east side [1]. The antiquary Erskine Beveridge believed that a second and perhaps a third chamber exist [1]. In or prior to 1911, Dr Beveridge excavated within and near the cairn, and he found evidence of burnt burials as well as pieces of pottery (some with patterned lines), wood ashes, burnt bones, a flint arrowhead, a scraper, and a piece of pierced talc [1].''"}, {"source": "remediation_change_log:111352", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:111353", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:165254", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''/data/images/wiki/eae0879c/hero.webp'' -> ''/data/images/wiki/eae0879c/Barpa Langass - 47092123164.webp''"}, {"source": "remediation_change_log:319273", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-015: thumbnail_url ''/data/images/wiki/eae0879c/Barpa Langass - 47092123164.webp'' -> ''/data/images/wiki/eae0879c/Barpa_Langais_20090608.webp''"}]'::jsonb),
    ('eae0879c-2e4a-422d-8626-2fbf21adb227'::uuid, 'rarity_score', '37', '40', 'card-stats-2026-11-05-rollback:eae0879c-2e4a-422d-8626-2fbf21adb227:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''40'' restored on Barpa Langass', '8b651921bc2cd6f257f87a4499da01fb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 37 from mystery 5, cultural_influence 10"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43111", "url": "remediation_change_log", "quote": "phase4:p4-0066:chunk-0001: description ''Barpa Langass is a Neolithic chambered cairn on the northwestern slope of Ben Langass, Isle of North Uist, Outer Hebrides, Scotland, approximately 5,000 years old. Measuring about 22 metres in diameter and 5.5 metres in height, it is the only chambered cairn in the Western Isles known to retain its chamber intact. The passage grave served as a communal tribal burial site over thousands of years. Excavation by antiquarian Erskine Beveridge in the 1890s uncovered cremated human remains, charcoal, pottery fragments, and stone tool-manufacturing evidence including quartz flakes and an anvil stone still in position after six millennia.'' -> ''Barpa Langass or Langass Barp is a Neolithic chambered cairn on the Isle of North Uist in the Outer Hebrides of Scotland [1]. It measures around 22 meters in diameter by 5.5 meters in height, and is around 5,000 years old [1]. The roof is constructed of two massive slabs with a third slab superimposed [1]. The entrance is at the east side [1]. The antiquary Erskine Beveridge believed that a second and perhaps a third chamber exist [1]. In or prior to 1911, Dr Beveridge excavated within and near the cairn, and he found evidence of burnt burials as well as pieces of pottery (some with patterned lines), wood ashes, burnt bones, a flint arrowhead, a scraper, and a piece of pierced talc [1].''"}, {"source": "remediation_change_log:111352", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:111353", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''-4500'' -> ''-3000''"}, {"source": "remediation_change_log:165254", "url": "remediation_change_log", "quote": "served-image-2026-09-30-032: thumbnail_url ''/data/images/wiki/eae0879c/hero.webp'' -> ''/data/images/wiki/eae0879c/Barpa Langass - 47092123164.webp''"}, {"source": "remediation_change_log:319273", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-015: thumbnail_url ''/data/images/wiki/eae0879c/Barpa Langass - 47092123164.webp'' -> ''/data/images/wiki/eae0879c/Barpa_Langais_20090608.webp''"}]'::jsonb),
