    ('eaf2f471-84d2-4661-8781-6a81241b11fb'::uuid, 'total_power', '28', '29', 'card-stats-2026-11-05-rollback:eaf2f471-84d2-4661-8781-6a81241b11fb:total_power', 'rollback of card-stats-2026-11-05: total_power ''29'' restored on Fernacre', 'd7351346aa5319953a2bed79e843f6a0', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 28 from antiquity + fortification + cultural_influence + mystery + legacy = 7 + 8 + 8 + 4 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43113", "url": "remediation_change_log", "quote": "phase4:p4-0066:chunk-0001: description \"One of Cornwall''s largest stone circles, located on Bodmin Moor northeast of St Breward. The oval monument measures 46 x 44 metres and contains approximately 70 irregularly shaped granite stones, with 39 still standing. Aubrey Burl identified Fernacre and nearby Stannon Circle as among the oldest on the moor, dating to the Late Neolithic or Early Bronze Age. Roger Mercer''s 1968 excavation recovered cord-ornamented pottery, querns, flints, and two greenstone axes indicating substantial tree clearance. The circle aligns with Brown Willy at the equinox sunrise.\" -> ''Fernacre, also known as Fernacre stone circle or Fernacre circle, is a stone circle located on the slopes of the De Lank River, 1.25 miles northeast of St Breward on Bodmin Moor in Cornwall in the United Kingdom [1]. Fernacre is one of the biggest stone circles in Cornwall [1]. Fernacre is a marker for the start of a medieval drove road from Rough Tor to Garrow [1]. Fernacre carries a pivotal location between Rough Tor located due north and Brown Willy located due east [1].''"}, {"source": "remediation_change_log:111356", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:111357", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:254611", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:254612", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''-4000''"}, {"source": "remediation_change_log:353817", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:353818", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:354797", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_name ''Undated'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:354798", "url": "remediation_change_log", "quote": "2026-10-19r_fields-wd5-s001: period_start None -> ''-2500''"}]'::jsonb),
    ('eb13e438-eba3-44d7-8189-9365e245f0b8'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:eb13e438-eba3-44d7-8189-9365e245f0b8:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Witzna', 'f3253a76d4f07ed9198ad453e5872300', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43115", "url": "remediation_change_log", "quote": "phase4:p4-0066:chunk-0001: description \"Witzna (c. 1st–8th century AD) is a mid-sized Maya archaeological site in Guatemala''s Petén Basin [1]. Inscriptions found at the site confirm its ancient name was Bahlam Jol [2]. The settlement flourished during the Classic period of Mesoamerican chronology [3]. It is situated near the confluence of the Holmul and Ixcán Rivers, adjacent to the site of Chanchich II [4].\" -> ''Witzna is a mid-sized archaeological site of the pre-Columbian Maya civilization, situated in the Petén Basin region of what is now northern Guatemala [1]. Inscriptions discovered on site indicate that the city was known to the ancient Mayans as Bahlam Jol [1]. Significant occupancy is dated to the Classic period of Mesoamerican chronology [1]. It is located near the confluence of the Holmul and Ixcán Rivers, near the site of Chanchich II [1]. The site\\''s main center contains several palaces, stepped-pyramid \"temples\" and a ballcourt [1]. Archaeological evidence shows that a large fire destroyed much of the city at the end of the 7th century, which corresponds to a hieroglyphic account in nearby Naranjo describing the burning of a rebellious vassal city named Bahlam Jol dated to 21 May 697 CE [1]. This event caused a significant decline in the population of the city, with many of its inhabitants likely enslaved or taken prisoner by Naranjo [1]. The city was rebuilt during the early 700s CE, though less prominent and more sparsely populated than before [1].''"}, {"source": "remediation_change_log:111358", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:111359", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''1'' -> None"}, {"source": "remediation_change_log:254613", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:254614", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''1''"}, {"source": "remediation_change_log:353819", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:353820", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''1'' -> None"}]'::jsonb),
