    ('eb347510-7433-420e-aee8-adb0cdec43aa'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:eb347510-7433-420e-aee8-adb0cdec43aa:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Bindon Hill', '4eedb00c237d03f899fea26acca787df', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -800"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88280", "url": "remediation_change_log", "quote": "phase4:p4-2195:chunk-0001: description ''Bindon Hill is an extensive Iron Age univallate earthwork on the Jurassic Coast near Lulworth Cove in Dorset, England, about 19 km west of Swanage and 6 km southwest of Wareham[1]. The rampart and external ditch extend for over a mile along a ridge[2]. The site occupies a commanding coastal position within an Area of Outstanding Natural Beauty[1]. The earthwork represents a significant defensive enclosure constructed by Iron Age communities[1][2].'' -> ''Bindon Hill is an extensive Iron Age earthwork, enclosing a coastal hill area on the Jurassic Coast near Lulworth Cove in Dorset [1]. It is about 19 kilometres west of Swanage, about 6 kilometres south west of Wareham, and about 17 kilometres southeast of Dorchester [1]. The main rampart and external ditch run for over 2 km along an east-west ridge parallel to the coast, which lies about 750 m to the south [1]. The ridge rises to 168 m and the cliffs are 30–120 m high [1]. At the western end, an incomplete series of ramparts curves back to the cliffs of Lulworth Cove [1]. At the eastern end, the main rampart reaches the cliffs on the north side of Mupe Bay [1]. The total enclosed area is about 110 ha [1]. The enormous enclosed area, lack of evidence of settlement in the interior, and the impossibility of effectively defending such a large perimeter, all suggest it was primarily an enclosed pasture for domesticated animals, not a strategic tribal hill fort [1].''"}, {"source": "remediation_change_log:111360", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:111361", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:254615", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:254616", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''-4000''"}, {"source": "remediation_change_log:353821", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''4500 - 3000 BC'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:353822", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-4000'' -> ''-800''"}]'::jsonb),
