    ('eb9e5db8-a757-4451-8af7-b5eb273a5c9d'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:eb9e5db8-a757-4451-8af7-b5eb273a5c9d:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Nakhchivan Necropolises', 'fef60089fe05ce56638ad07785ebe9b2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Necropolis/tombs complex'', ''1500 - 500 BC'') is shared by 24 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88286", "url": "remediation_change_log", "quote": "phase4:p4-2195:chunk-0001: description ''The Nakhchivan necropolises are Bronze Age burial grounds on the northern outskirts of Nakhchivan city, Azerbaijan, accidentally discovered in 1968 during farm work. Dating to the 17th-15th centuries BC, the rectangular stone-slab tombs contain painted clay vessels, bronze ornaments (bracelets, rings, earrings), and mineral beads. Excavations have revealed evidence of warrior women with skeletal deformations from sustained archery and horse-riding, along with high-status grave goods including bronze daggers, mace heads, and carnelian necklaces.'' -> ''The Nakhchivan necropolis is an archeological site of the Bronze Age on the northern outskirts of Nakhchivan city [1]. The monument was accidentally discovered in 1968 when earth graves were destroyed during farm work [1]. The surface of the rectangular tombs is covered with stone slabs 1 m long, 0.5 m wide and 0.2–0.3 m thick [1]. The remains of the skeletons are very poorly preserved [1]. Nakhchivan necropolis I is an archeological monument of antiquity near the Nakhchivan necropolis [1]. It was discovered by accident during construction in 1970 [1]. The monument with an area of 1.9 hectares consists of six destroyed tombs [1].''"}, {"source": "remediation_change_log:111371", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:111372", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:111373", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: site_type ''Necropolis/tombs complex'' -> None"}, {"source": "remediation_change_log:244712", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:244713", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: period_start None -> ''-1500''"}, {"source": "remediation_change_log:244714", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: site_type None -> ''Necropolis''"}, {"source": "remediation_change_log:356241", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Necropolis'' -> ''Necropolis/tombs complex''"}]'::jsonb),
