    ('ebf816e0-2353-4ed3-81bd-685d6480973f'::uuid, 'antiquity', '5', '3', 'card-stats-2026-11-05-rollback:ebf816e0-2353-4ed3-81bd-685d6480973f:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''3'' restored on Żejtun Roman Villa', '9cf9cb7505cc8de4d1a0286ca0a40259', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81426", "url": "remediation_change_log", "quote": "phase4:p4-2032:chunk-0001: description ''The Zejtun Roman Villa is a multi-period archaeological complex in southeastern Malta, first uncovered in 1961 during school construction. The site spans the Bronze Age through Late Antiquity, with visible remains dating primarily to the Punic and Roman periods. The residential area features rooms paved with lozenge-shaped terracotta tiles in herringbone patterns and walls decorated with painted plaster imitating marble. An industrial area housed an olive-pressing operation with stone counterweights and settling vats. Notable finds include a hoard of 43 bronze Roman coins from the 3rd century AD and a pottery fragment bearing a Punic inscription possibly dedicated to the goddess Astarte.'' -> ''The Żejtun Roman villa is an archaeological complex in the city of Żejtun, in south-eastern Malta [1]. The open-air remains contain areas of original Roman tiling and coloured stucco [1]. The complex was an active settlement since the Bronze Age, although the presently visible remains can be mainly dated from the Punic period right up to Late Antiquity [1]. The excavation site at the villa confirms the presence of a thriving olive oil industry on the southern end of the islands [1]. The remains rest on the highest point of a long, flat ridge stretching in an east-west direction [1].''"}, {"source": "remediation_change_log:111381", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:111382", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''-500'' -> None"}, {"source": "remediation_change_log:165751", "url": "remediation_change_log", "quote": "served-image-2026-09-30-033: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Zejtun_Roman_Villa_(12682983103).jpg/400px-Zejtun_Roman_Villa_(12682983103).jpg'' -> ''/data/images/wiki/ebf816e0/hero.webp''"}, {"source": "remediation_change_log:254625", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''1 - 500 AD''"}, {"source": "remediation_change_log:254626", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''43''"}, {"source": "remediation_change_log:353825", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''1 - 500 AD'' -> ''Undated''"}, {"source": "remediation_change_log:353826", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''43'' -> None"}]'::jsonb),
