    ('ece8c6c5-0934-4817-b30d-cc3c0e27899e'::uuid, 'antiquity', '4', '5', 'card-stats-2026-11-05-rollback:ece8c6c5-0934-4817-b30d-cc3c0e27899e:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''5'' restored on Gurnard''s Head', '3a0e183668122a2ce77dc659a5f1603b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 4 from period_start -200"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43123", "url": "remediation_change_log", "quote": "phase4:p4-0066:chunk-0001: description ''An Iron Age promontory fort (cliff castle) called Trereen Dinas on a narrow headland in Zennor parish, Cornwall, defended by two stone ramparts each about 60 metres long with three ditches. A 1939 excavation revealed 16 roundhouses averaging 6 metres in diameter, and rampart construction in three steps to provide platforms for slingers. Pottery finds include sherds from Brittany and high-status wares dating to 800-200 BCE, suggesting the site served as a seasonal maritime trading post. Owned by the National Trust, it is one of only three excavated promontory forts in Cornwall.'' -> \"Gurnard''s Head is a prominent headland on the north coast of the Penwith peninsula in Cornwall, England [1]. Gurnard''s Head is the site of basaltic pillow lavas, formed by underwater volcanic eruptions up to 400 million years ago [1]. It is north of the hamlet of Treen in the parish of Zennor [1]. The headland is the site of an Iron Age promontory fort known as Trereen Dinas (not to be confused with Treryn Dinas) [1].\""}, {"source": "remediation_change_log:111397", "url": "remediation_change_log", "quote": "20