    ('ee091b60-f72c-4e85-be61-baa970aa0630'::uuid, 'mystery', '3', '6', 'card-stats-2026-11-05-rollback:ee091b60-f72c-4e85-be61-baa970aa0630:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Roca Archaeological Site', '31656a836ae2de21b2b0047fc21ab942', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''3000 - 1500 BC'') is shared by 130 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88328", "url": "remediation_change_log", "quote": "phase4:p4-2197:chunk-0001: description \"3000-1500 BC Bronze Age settlement on Italy''s Adriatic coast, near modern Melendugno and Lecce. Excavated since the late 1980s by the University of Salento, it features the best-preserved monumental architecture of the Bronze Age in southern Italy [1]. The site also yielded the largest collection of Mycenaean pottery found west of mainland Greece [1].\" -> ''Roca (also known as Rocavecchia or Roca Vecchia) is an archaeological site located on the Adriatic coast of Apulia in Southern Italy, a few kilometres from the modern town of Melendugno and close to the city of Lecce [1]. The site, which has been explored since the end of the 1980s by a team of the University of Salento, has produced some of the best-preserved monumental architecture of the Bronze Age (2nd millennium BC) in Southern Italy, along with the largest set of Mycenaean pottery ever recovered west of mainland Greece [1]. The occupation of the site continued also in the Iron Age and Classical times, when a large natural cavity known as Poesia Cave was used for cult practices involving the writing of thousands of dedications to a local deity in three languages: Greek, Messapic and Latin [1]. Grotta della Poesia is one of the most well known natural rock formations inside the archaeological site [1].''"}, {"source": "remediation_change_log:165809", "url": "remediation_change_log", "quote": "served-image-2026-09-30-033: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/d/d8/Roca_vecchia_2.JPG'' -> ''/data/images/wiki/ee091b60/Grotta_della_Poesia_in_Roca_Vecchia_(Melendugno,_Apulia,_Italy).webp''"}, {"source": "remediation_change_log:319333", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-015: thumbnail_url ''/data/images/wiki/ee091b60/Grotta_della_Poesia_in_Roca_Vecchia_(Melendugno,_Apulia,_Italy).webp'' -> ''/data/images/wiki/ee091b60/Roca_vecchia_2.webp''"}, {"source": "remediation_change_log:356245", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s003: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
