    ('f04199e9-626c-4eda-bccf-0395ef21d332'::uuid, 'mystery', '6', '9', 'card-stats-2026-11-05-rollback:f04199e9-626c-4eda-bccf-0395ef21d332:mystery', 'rollback of card-stats-2026-11-05: mystery ''9'' restored on Goloring', '9fbb0863ec25d63b74e712fc36b4b7f3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Earthwork'', ''1500 - 500 BC'') is shared by 22 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88364", "url": "remediation_change_log", "quote": "phase4:p4-2198:chunk-0001: description ''The Goloring is a Bronze Age henge monument near Koblenz, Germany, dating to the Urnfield culture (1200-800 BC). It features a circular ditch 175 m in diameter with an outer embankment extending to 190 m. Excavations by Dr. Josef Roder (1940-48) uncovered remnants of a central wooden post estimated at 8-12 m tall, possibly used for solar calendar observations aligned with a nearby volcano. The design is unique in Germany but comparable to British henges like Stonehenge. The site was acquired by the town of Kobern-Gondorf in 2004.'' -> ''The Goloring is an ancient earthworks monument located near Koblenz [1]. The Goloring consists of a circular ditch of 175 metres in diameter with an outside embankment extending to 190 metres [1]. The outside embankment is approx. 7 metres wide and 80 cm high [1]. The ditch has an upper width of 5–6 metres and is approx. 80 cm deep [1].''"}, {"source": "remediation_change_log:111457", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_