    ('f0b4765f-f0ab-46bf-bfb0-900cd3914323'::uuid, 'cultural_influence', '8', '7', 'card-stats-2026-11-05-rollback:f0b4765f-f0ab-46bf-bfb0-900cd3914323:cultural_influence', 'rollback of card-stats-2026-11-05: cultural_influence ''7'' restored on Woodbury Hill, Worcestershire', 'ca74d2b10108aaee636732f1f80e12e1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 8 from description yes, thumbnail yes, 5 content link(s), 1 image(s), source_url yes"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88366", "url": "remediation_change_log", "quote": "phase4:p4-2198:chunk-0001: description ''Woodbury Hill is an Iron Age hillfort near Great Witley, Worcestershire, England, situated about 8km southwest of Stourport-on-Severn [1].'' -> ''Woodbury Hill is a hill near the village of Great Witley, about 5 miles south-west of Stourport-on-Severn in Worcestershire [1]. It is the site of an Iron Age hillfort [1]. The hill overlooks the River Teme to the south-west [1]. The fort has a single rampart with an external ditch [1]. It has dimensions of about 600 metres west to east and 350 metres north to south, enclosing an area of about 11 hectares [1]. There is an entrance with inturned ramparts at the south-west [1]. The fort is called \"Owen Glendower\\''s Camp\" [1]. In 1405 it was the site of a standoff between the Welsh/French army of Owain Glyndŵr and the army of King Henry IV of England [1].''"}, {"source": "remediation_change_log:111466", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_ch