    ('f10115c4-5ca9-4d69-990c-8054f9962ea3'::uuid, 'empire_count', '4', '1', 'card-stats-2026-11-05-rollback:f10115c4-5ca9-4d69-990c-8054f9962ea3:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''1'' restored on Salina Catacombs', 'bdac973c1ff9ff972257dc4a02744c94', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 4 from tag_site(35.944343691339284, 14.424795098249195, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88368", "url": "remediation_change_log", "quote": "phase4:p4-2198:chunk-0001: description ''The Salina Catacombs are a cluster of more than 15 small hypogea cut into quarry rock near Salina Bay in Naxxar, Malta, dating to around the 2nd-3rd century AD. The site overlooks a now-lost Roman harbour, indicating a sizeable ancient community. Practically all tombs, even unfinished ones, are heavily decorated with elements pointing to Christian origins. The fifth hypogeum is regarded as the finest cut burial chamber, with mastery that few local hypogea can parallel. Only three of the five largest chambers remain accessible today.'' -> ''The Salina Catacombs are a cluster of small catacombs located near the Church of the Annunciation in Salina, Naxxar [1]. Although small when compared to the catacombs of St. Paul and St. Agatha in Rabat, they are an important record of the sizeable community that must have lived in the area in around the last half of the first millennium AD [1]. The catacombs open on to a low ridge facing a now lost Roman harbour [1]. The site comprises five hypogea cut into the vertical surface of a small quarry [1]. The most impressive hypogeum is adorned with two decorated pillars, an agape table and two baldacchino tombs [1]. The window tombs that surround the agape table suggest that it was an important feature of the catacomb [1]. At least two of the window tombs are lavishly decorated with reliefs depicting palm fronds and other spiraled patterns [1]. The palm fronds, together with a number of incised crosses, are proof of the Christian origins of the burial site [1].''"}, {"source": "remediation_change_log:111476", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:111477", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''1'' -> None"}, {"source": "remediation_change_log:165899", "url": "remediation_change_log", "quote": "served-image-2026-09-30-033: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/7/74/Salina_tomb.JPG'' -> ''/data/images/wiki/f10115c4/Malta - Naxxar - Triq il-Katakombi - Salina Catacombs 01 ies.webp''"}, {"source": "remediation_change_log:254665", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:254666", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''-800''"}, {"source": "remediation_change_log:319389", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-015: thumbnail_url ''/data/images/wiki/f10115c4/Malta - Naxxar - Triq il-Katakombi - Salina Catacombs 01 ies.webp'' -> ''/data/images/wiki/f10115c4/Salina_tomb.webp''"}, {"source": "remediation_change_log:353855", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:353856", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-800'' -> None"}]'::jsonb),
