g:357399", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s010: period_name ''< 4500 BC'' -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:357400", "url": "remediation_change_log", "quote": "2026-10-25p_fields-wd5-s010: period_start ''-10000'' -> ''750''"}]'::jsonb),
    ('f12e6473-3c60-4196-a99d-0611be3bb2a3'::uuid, 'mystery', '6', '5', 'card-stats-2026-11-05-rollback:f12e6473-3c60-4196-a99d-0611be3bb2a3:mystery', 'rollback of card-stats-2026-11-05: mystery ''5'' restored on Nydam Mose', '3084c46c53d1592e5e44ef6d0019d326', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Archaeological site'', ''1 - 500 AD'') is shared by 15 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:27993", "url": "remediation_change_log", "quote": "phase3:batch-0047:chunk-0001: site_type ''Geological interest'' -> ''Archaeological site''"}, {"source": "remediation_change_log:88370", "url": "remediation_change_log", "quote": "phase4:p4-2198:chunk-0001: description \"Nydam Mose (Nydam Bog) is an Iron Age sacrificial bog near Sonderborg, Denmark, where weapons and ships of defeated armies were ritually offered to gods between 200-400 AD. Excavated by Conrad Engelhardt from 1859-1863, the bog yielded three boats, including the celebrated 23-metre oak Nydam Boat dated to 310-320 AD, one of the oldest rowing vessels in Northern Europe. Weapons including swords, spears, bows, and shields were deliberately destroyed before deposition as ritual acts. The Nydam Boat now resides at Gottorf Castle in Schleswig, Germany, transferred after Denmark''s defeat in the 1864 war.\" -> ''The Nydam Mose, also known as Nydam Bog, is an archaeological site in Denmark located at Øster Sottrup, a town in Sundeved, eight kilometres from Sønderborg [1]. In the Iron Age, the site of the bog was a sacred place, where the weapons and ships of vanquished armies were offered to the indigenous gods in thanks for victory over the fallen enemy [1]. Many items were deliberately destroyed in ritual sacrificial acts [1]. From 1859 to 1863, archaeologist Conrad Engelhardt excavated the bog [1]. Engelhardt found weapons, tools, pieces of clothing and two intact clinker built boats, one made of oak and one made of pine [1]. Under these finds were the remains of a third boat, which apparently had been demolished already during the sacrifice [1]. The oak boat was the first and largest of the three boats that were found in the Nydam bog, and the only one still preserved [1]. It has been dendro dated to 310–320 CE [1].''"}, {"source": "remediation_change_log:165903", "url": "remediation_change_log", "quote": "served-image-2026-09-30-033: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/0/02/Nydam-Boot.JPG'' -> ''/data/images/wiki/f12e6473/hero.webp''"}, {"source": "remediation_change_log:335316", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-003: thumbnail_url ''/data/images/wiki/f12e6473/hero.webp'' -> ''/data/images/wiki/f12e6473/Nydam-Boot.webp''"}]'::jsonb),
