    ('f1a0b11e-e382-42dd-bfdd-4116409af9ca'::uuid, 'empire_count', '4', '1', 'card-stats-2026-11-05-rollback:f1a0b11e-e382-42dd-bfdd-4116409af9ca:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''1'' restored on Ħal Resqun Catacombs', '3294d51e1b93153837df211abc3058fc', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 4 from tag_site(35.852806388379754, 14.49459248290163, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88388", "url": "remediation_change_log", "quote": "phase4:p4-2199:chunk-0001: description \"Ħal Resqun catacombs (1st–5th century AD) at Gudja, Malta, are rare underground necropolises interpreted as Early Christian or Paleochristian hypogea. They stand out for elaborate carved decorations and architectural features uncommon in Maltese catacombs, of exceptional archaeological value [1]. Some historians identify Christian religious markers, while others consider the evidence inconclusive [1]. Notably, certain graffiti depicting biblical scenes are considered unique worldwide, marking these catacombs as one of Malta''s most significant Late Antiquity finds [1].\" -> ''The Ħal Resqun catacombs are especially notable for their carved decorations, and other features which are uncommon in Maltese catacombs [1]. The catacombs are dug into the local Globigerina Limestone [1]. The catacombs were first excavated by Temi Żammit in 1912, and again in 1934 by Żammit and his son, C. G. Żammit; although Temi Żammit reported how the site had already been disturbed in 1887 during the laying of a water main [1]. The doorway is flanked by two engraved columns, while the apsed arched entrance has carvings of a peacock and a peahen feeding a chick [1].''"}, {"source": "remediation_change_log:111499", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:111500", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''1'' -> None"}, {"source": "remediation_change_log:111501", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: site_type ''Necropolis/tombs complex'' -> ''Burial''"}, {"source": "remediation_change_log:254673", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:254674", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s021: period_start None -> ''-800''"}, {"source": "remediation_change_log:353864", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:353865", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s009: period_start ''-800'' -> None"}]'::jsonb),
