    ('f2041141-c82a-4e04-a6e6-d7d2e29f4ea5'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:f2041141-c82a-4e04-a6e6-d7d2e29f4ea5:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Schalkholz Passage Grave', '7c4c460c0370f9a13261feda707b2bce', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Tomb'', ''4500 - 3000 BC'') is shared by 12 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29084", "url": "remediation_change_log", "quote": "phase3:batch-0236:chunk-0004: site_type ''Necropolis/tombs complex'' -> ''Tomb''"}, {"source": "remediation_change_log:45431", "url": "remediation_change_log", "quote": "phase4:p4-0112:chunk-0001: description \"The Schalkholz Passage Grave is a Neolithic megalithic burial site of the Funnelbeaker culture in Schleswig-Holstein, Germany. Built between 3500-2800 BC, it features a passage grave structure used for collective burials. The site was reused during the late Bronze Age or early Iron Age for secondary interments. Archaeological excavations in 1969-1970 were conducted. The monument was moved to the town of Heide for preservation and returned to Schalkholz in 2021. It carries the Sprockhoff number 139, cataloging it among Northern Europe''s megalithic monuments.\" -> ''The Schalkholz Passage Grave, also known as Schalkholz-Vierth is a megalithic burial site of the Neolithic period and of the Funnelbeaker culture in Vierth, a district of Schalkholz in the province of Schleswig-Holstein in Germany [1]. During the late Bronze Age or early Iron Age, it was used for a secondary burial site and was expanded upon [1]. It has the Sprockhoff number 139 and the site number LA 33 or Heide LA 5 [1]. The grave was archaeologically investigated in 1969 and 1970 and was afterwards moved to the nearby town of Heide [1]. In 2021 it was moved back to Schalkholz [1].''"}, {"source": "remediation_change_log:111504", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:111505", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s022: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:141517", "url": "remediation_change_log", "quote": "2026-10-01a_fields-wd3-s001: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:141518", "url": "remediation_change_log", "quote": "2026-10-01a_fields-wd3-s001: period_start None -> ''-3500''"}, {"source": "remediation_change_log:165955", "url": "remediation_change_log", "quote": "served-image-2026-09-30-033: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Heide_Huenengrab_Wasserturm.jpg/400px-Heide_Huenengrab_Wasserturm.jpg'' -> ''/data/images/wiki/f2041141/Ganggrab Schalkholz Kreuzberg-Sprockhoff 139-1.webp''"}]'::jsonb),
