    ('f284934a-a5b3-4c85-ba90-953aa9e72bc5'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:f284934a-a5b3-4c85-ba90-953aa9e72bc5:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Ancient Theatre of Makyneia', 'd7ca0f29fa34950492ae48443e948f38', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Theatre'', ''500 BC - 1 AD'') is shared by 28 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:91732", "url": "remediation_change_log", "quote": "phase4wc:p4wc-4003:chunk-0001: description ''A small 4th-3rd century BC theatre at the site of ancient Aitolian Makyneia, located at the Paliokastro site in western Greece. The theatre has a single cuneus with 14 tiers of seats and an arc-shaped orchestra, and may have doubled as a bouleuterion (council house). Its compact design features seats of honor (proedriae) in the north part of the orchestra, with stone seat-backs for distinguished officials. Analysis shows it was designed using the Doric foot measurement system.'' -> ''A small 4th-3rd century BC theatre at the site of ancient Aitolian Makyneia, located at the Paliokastro site in western Greece [1] [2]. The theatre has a single cuneus with 14 tiers of seats and an arc-shaped orchestra, and may have doubled as a bouleuterion (council house) [2] [3]. Its compact design features seats of honor (proedriae) in the north part of the orchestra, with stone seat-backs for distinguished officials [2] [3]. Analysis shows it was designed using the Doric foot measurement system [1].''"}, {"source": "remediation_change_log:111512", "url":