    ('f6825042-70ed-4d70-8e17-42575be53b67'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:f6825042-70ed-4d70-8e17-42575be53b67:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on Dighton Rock', 'e690aefce4c4f23f338a47b9904cdc1a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88482", "url": "remediation_change_log", "quote": "phase4:p4-2202:chunk-0001: description ''The Dighton Rock is a 40-ton glacial boulder composed of sandstone that originally sat in the riverbed of the Taunton River in Berkley, Massachusetts[1]. The carvings have generated controversy regarding their creators, with theories ranging from Native American peoples to medieval Norse visitors[1]. In 1963, during construction of a coffer dam, state officials relocated the rock to Dighton Rock State Park for preservation[1]. It was listed on the National Register of Historic Places in 1971[1].'' -> ''The Dighton Rock is a 40-ton boulder composed of sandstone, originally located in the riverbed of the Taunton River at Berkley, Massachusetts, formerly part of the town of Dighton [1]. The rock is noted for its petroglyphs, \"primarily lines, geometric shapes, and schematic drawings of people, along with writing, both verified and not\" [1]. The carved designs are of ancient and uncertain origin, and there is controversy as to who created them [1]. State officials removed the rock from the river for preservation in 1963, during construction of a coffer dam [1]. It was installed in a museum in the nearby Dighton Rock State Park [1]. In 1971, it was listed on the National Register of Historic Places [1]. The boulder has the form of a slanted, six-sided block, approximately 5 feet high, 9.5 feet wide, and 11 feet long [1]. The surface with the inscriptions has a trapezoidal face and is inclined 70 degrees to the northwest [1].''"}, {"source": "remediation_change_log:126637", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_name ''1000 - 1500 AD'' -> None"}, {"source": "remediation_change_log:126638", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_start ''1000'' -> None"}, {"source": "remediation_change_log:255037", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:255038", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-10000''"}, {"source": "remediation_change_log:319485", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-015: thumbnail_url ''/data/images/wiki/f6825042/A Pedra de Dighton no Rio Taunton, ate ser removida para o Museu en 1963, pesa 40 toneladas!.webp'' -> ''/data/images/wiki/f6825042/Dighton Rock-Davis photograph.webp''"}, {"source": "remediation_change_log:354420", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''< 4500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:354421", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-10000'' -> None"}]'::jsonb),
    ('f6825042-70ed-4d70-8e17-42575be53b67'::uuid, 'total_power', '21', '26', 'card-stats-2026-11-05-rollback:f6825042-70ed-4d70-8e17-42575be53b67:total_power', 'rollback of card-stats-2026-11-05: total_power ''26'' restored on Dighton Rock', 'e690aefce4c4f23f338a47b9904cdc1a', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 21 from antiquity + fortification + cultural_influence + mystery + legacy = 5 + 2 + 7 + 6 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88482", "url": "remediation_change_log", "quote": "phase4:p4-2202:chunk-0001: description ''The Dighton Rock is a 40-ton glacial boulder composed of sandstone that originally sat in the riverbed of the Taunton River in Berkley, Massachusetts[1]. The carvings have generated controversy regarding their creators, with theories ranging from Native American peoples to medieval Norse visitors[1]. In 1963, during construction of a coffer dam, state officials relocated the rock to Dighton Rock State Park for preservation[1]. It was listed on the National Register of Historic Places in 1971[1].'' -> ''The Dighton Rock is a 40-ton boulder composed of sandstone, originally located in the riverbed of the Taunton River at Berkley, Massachusetts, formerly part of the town of Dighton [1]. The rock is noted for its petroglyphs, \"primarily lines, geometric shapes, and schematic drawings of people, along with writing, both verified and not\" [1]. The carved designs are of ancient and uncertain origin, and there is controversy as to who created them [1]. State officials removed the rock from the river for preservation in 1963, during construction of a coffer dam [1]. It was installed in a museum in the nearby Dighton Rock State Park [1]. In 1971, it was listed on the National Register of Historic Places [1]. The boulder has the form of a slanted, six-sided block, approximately 5 feet high, 9.5 feet wide, and 11 feet long [1]. The surface with the inscriptions has a trapezoidal face and is inclined 70 degrees to the northwest [1].''"}, {"source": "remediation_change_log:126637", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_name ''1000 - 1500 AD'' -> None"}, {"source": "remediation_change_log:126638", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_start ''1000'' -> None"}, {"source": "remediation_change_log:255037", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:255038", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-10000''"}, {"source": "remediation_change_log:319485", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-015: thumbnail_url ''/data/images/wiki/f6825042/A Pedra de Dighton no Rio Taunton, ate ser removida para o Museu en 1963, pesa 40 toneladas!.webp'' -> ''/data/images/wiki/f6825042/Dighton Rock-Davis photograph.webp''"}, {"source": "remediation_change_log:354420", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''< 4500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:354421", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-10000'' -> None"}]'::jsonb),
    ('f6916087-0021-44fe-af7e-5111e67f660a'::uuid, 'antiquity', '5', '4', 'card-stats-2026-11-05-rollback:f6916087-0021-44fe-af7e-5111e67f660a:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Risovača Cave', 'ba734dd98a60f8651330c7d0f2f5b106', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88484", "url": "remediation_change_log", "quote": "phase4:p4-2202:chunk-0001: description \"Risovača Cave is a Paleolithic archaeological site in central Serbia, located 17 metres above the Kubršnica river valley at the entrance of Aranđelovac [1]. It is one of Serbia''s most important Paleolithic sites alongside Gradac Cave near Kragujevac [2]. The cave''s discovery confirmed the existence of Paleolithic culture south of the Sava-Danube line and provided new insights into prehistoric human life in Europe [3].\" -> ''Risovača Cave, (Serbian Cyrillic: Пећина Рисовача, romanized: Pećina Risovača) is situated at the very entrance of the town of Aranđelovac in central Serbia around 17 m above the Kubršnica river valley [1]. It is one of the most important archaeological sites of the Paleolithic in Serbia besides the Gradac Cave near Kragujevac [1]. Its discovery confirmed the assumed existence of the Paleolithic culture south of the Sava-Danube line and provided new information on the life of prehistoric humans in Europe [1]. The site has been discovered around 1938 when the quarry on the location became operational, but the size and importance were not recognized until 1950 when the old quarry was reopened [1]. Archaeological and speleological excavations started in 1953, headed by the archaeologist Branko Gavela and young speleologist Radenko Lazarević [1]. Worked flint tools and bone artifacts of prehistoric human origin were discovered in sediments in a depth of 1 to 1.75 m [1]. These artifact assemblages are attributed to Neanderthal occupants during the end of the Middle Paleolithic period [1].''"}, {"source": "remediation_change_log:112221", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:112222", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-50000'' -> None"}, {"source": "remediation_change_log:166608", "url": "remediation_change_log", "quote": "served-image-2026-09-30-034: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Ulaz_u_pecinu_risovaca.jpg/400px-Ulaz_u_pecinu_risovaca.jpg'' -> ''/data/images/wiki/f6916087/Pećina Risovača, Risovaca Cave - panoramio.webp''"}, {"source": "remediation_change_log:255039", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:255040", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-500''"}, {"source": "remediation_change_log:354423", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: lat ''44.30014586334488'' -> ''44.303308''"}, {"source": "remediation_change_log:354424", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: lon ''20.56643181215441'' -> ''20.581952''"}, {"source": "remediation_change_log:354425", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:354426", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-500'' -> 