    ('f7847cdc-5030-4ccf-bcdc-df1a6e47fce3'::uuid, 'mystery', '7', '8', 'card-stats-2026-11-05-rollback:f7847cdc-5030-4ccf-bcdc-df1a6e47fce3:mystery', 'rollback of card-stats-2026-11-05: mystery ''8'' restored on Martin Down Enclosure', 'd529c6fec8ee39d4e86c3c2d0aafbad4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 7 from (''Earthwork'', ''3000 - 1500 BC'') is shared by 7 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29643", "url": "remediation_change_log", "quote": "phase3:batch-0318:chunk-0001: site_type ''City/town/settlement'' -> ''Settlement''"}, {"source": "remediation_change_log:36093", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: site_type ''Settlement'' -> ''City/town/settlement''"}, {"source": "remediation_change_log:43209", "url": "remediation_change_log", "quote": "phase4:p4-0068:chunk-0001: description ''Martin Down Enclosure is a scheduled monument near the village of Martin in Hampshire, England, and the type site for \"Martin Down style enclosures\" -- small Bronze Age domestic settlements typically under 0.3 hectares found on southern English downland. The rectangular enclosure measures roughly 100 by 70 yards with a single bank and external ditch. Augustus Pitt Rivers excavated the entire bank, ditch, and half the interior from November 1895 to March 1896, finding worked flint, animal bone, and pottery from middle Bronze Age and Romano-British periods. The present earthwork is his reconstruction.'' -> ''The Martin Down Enclosure is an archaeological site on Martin Down, near the village of Martin, in Hampshire [1]. It is near the boundaries with Dorset and Wiltshire [1]. The site is a scheduled monument, and it is one of several archaeological features on Martin Down, such as Bokerley Dyke [1]. The enclosure is the original example of a type of prehistoric feature, the \"Martin Down style enclosure\": they are small enclosures of the Bronze Age, area often less than 0.3 hectares, considered to be domestic settlements [1]. The rectangular enclosure has internal dimensions of about 90 metres south-west to north-east by 63 metres [1]. It has a single bank of width up to 10 metres and up to 0.7 metres above the interior, and there is an external ditch [1].''"}, {"source": "remediation_change_log:112238", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:112239", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:112240", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: site_type ''City/town/settlement'' -> ''Earthwork''"}, {"source": "remediation_change_log:302214", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:302215", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-2000''"}]'::jsonb),
