    ('f784a924-a2de-42ae-b530-4b292753fa8f'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:f784a924-a2de-42ae-b530-4b292753fa8f:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Overton Hill', '397b95e775b3f098a61e695b29e0d4b6', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''3000 - 1500 BC'') is shared by 34 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88492", "url": "remediation_change_log", "quote": "phase4:p4-2202:chunk-0001: description ''Overton Hill is a 174-metre hill at the southern edge of the Marlborough Downs in Wiltshire, England. It is notable as the start point of the Ridgeway National Trail, which follows an ancient trackway. The hill contains several scheduled archaeological sites including Bronze Age round barrows and the site of The Sanctuary, a Neolithic wooden and stone circle connected to Avebury by the West Kennet Avenue. The area forms part of the Stonehenge and Avebury UNESCO World Heritage Site.'' -> ''Overton Hill is a 571 ft hill at the southern edge of the Marlborough Downs in Wiltshire [1]. It lies just west of the village of West Overton and about 4 miles west from the town of Marlborough [1]. The hill is notable for being the start point of the Ridgeway National Trail, which follows an ancient trackway [1]. The hill is part of the Avebury section of the Stonehenge and Avebury World Heritage Site [1].''"}, {"source": "remediation_change_log:126648", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_name ''1500 - 500 BC'' -> ''3000 - 1500