    ('f7f6d178-0de5-4cc8-a1f7-d473bb13e06c'::uuid, 'empire_count', '3', '1', 'card-stats-2026-11-05-rollback:f7f6d178-0de5-4cc8-a1f7-d473bb13e06c:empire_count', 'rollback of card-stats-2026-11-05: empire_count ''1'' restored on Cave Sanctuaries of the Acropolis of Athens', '7bf2955b0b6e524284d31d5120bf0c8f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "empire_count = 3 from tag_site(37.97155802644958, 23.727959036968826, period_start None)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81486", "url": "remediation_change_log", "quote": "phase4:p4-2034:chunk-0001: description \"Natural fissures and cavities in the rock of the Acropolis hill in Athens that served as cult sites from the Archaic through Classical periods. On the northwest slope, three caves hosted worship of Zeus Olympios, Apollo Hypoakraios (''beneath the rock''s edge''), and Pan, whose cult was established after the Battle of Marathon in 490 BCE when he reportedly caused panic among the Persians. The southern slope held sanctuaries of the Nymphs, Aphrodite, and Isis, while the east side featured a cave honoring Aglauros, daughter of mythical king Kekrops. These slope sanctuaries represent personal piety distinct from the state religion practiced on the summit.\" -> ''The Cave Sanctuaries of the Acropolis of Athens are the natural fissures in the rock of the Acropolis hill that were used as sites of worship for deities of the Panhellenic pantheon in antiquity [1]. The northwestern slope of the rock of the Acropolis is dominated by three cave openings dedicated to the worship of Pan, Zeus and Apollo respectively [1]. On the east slope is the Aglaureion, the largest of the Acropolis caves at 14m across the mouth [1]. Herodotus records that the Persians in 480 BCE used this part of the hill to scale the Acropolis [1]. Pausanias described the Aglaureion as being above the sanctuary of the Dioskouroi near the Prytaneion [1]. These sources were the only inconclusive clues to the location of the shrine which was not identified as its current site until the 1980 stele find [1].''"}, {"source": "remediation_change_log:112244", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:112245", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:166640", "url": "remediation_change_log", "quote": "served-image-2026-09-30-034: thumbnail_url ''/data/images/wiki/f7f6d178/hero.webp'' -> ''/data/images/wiki/f7f6d178/The sanctuaries of Pan, Zeus, and Apollo on the Acropolis of Athens on March 22, 2021.webp''"}, {"source": "remediation_change_log:255049", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:255050", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-800''"}, {"source": "remediation_change_log:319979", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-016: thumbnail_url ''/data/images/wiki/f7f6d178/The sanctuaries of Pan, Zeus, and Apollo on the Acropolis of Athens on March 22, 2021.webp'' -> ''/data/images/wiki/f7f6d178/Zeus_and_Apollon_Ipakrion_caves_7233923.webp''"}, {"source": "remediation_change_log:354431", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:354432", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: pe