    ('f7fec312-2d2f-4dc7-87dd-a425ddbfa454'::uuid, 'mystery', '3', '4', 'card-stats-2026-11-05-rollback:f7fec312-2d2f-4dc7-87dd-a425ddbfa454:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Shillourokambos', '657c2e88a36eae2972697c4a8a66f371', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 3 from (''City/town/settlement'', ''< 4500 BC'') is shared by 105 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88524", "url": "remediation_change_log", "quote": "phase4:p4-2203:chunk-0001: description ''Shillourokambos is a Pre-Pottery Neolithic B (PPNB) settlement near Parekklisia, 6 km east of Limassol in southern Cyprus[1]. Located on a low plateau, excavations began in 1992 and revealed four occupational phases spanning from the end of the 9th millennium to the second half of the 8th millennium BC[1]. The site is particularly significant for providing the earliest evidence of domesticated cattle in Cyprus during the aceramic Neolithic period, with cattle populations dying out during the 8th millennium[1].'' -> ''Shillourokambos is a Pre-Pottery Neolithic B (PPNB) site near Parekklisia, 6 km east of Limassol in southern Cyprus [1]. It is located on a low plateau [1]. Excavations began in 1992 [1]. The settlement has four phases and was occupied from the end of the 9th millennium to the second half of the 8th millennium [1]. The architecture of phases A and B (8200–7500 BC, calibrated) is characterised by circular wattle and daub structures, with post holes cut into the bedrock [1]. Around 300 blades of Anatolian obsidian point to trade connections with the mainland [1]. The site is important because it attests to the presence of cattle in the aceramic Neolithic period [1].''"}, {"source": "remediation_change_log:244828", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: lat ''34.743725531193085'' -> ''34.76701''"}, {"source": "remediation_change_log:244829", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: lon ''33.15878130457239'' -> ''33.1563''"}]'::jsonb),
