    ('f8263779-fd9f-4983-9561-3f7755417987'::uuid, 'mystery', '5', '4', 'card-stats-2026-11-05-rollback:f8263779-fd9f-4983-9561-3f7755417987:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Adam''s Grave', '3f3ecaddfb2f6b4c4d5ff14de5be64d2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Barrow'', ''4500 - 3000 BC'') is shared by 33 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88526", "url": "remediation_change_log", "quote": "phase4:p4-2203:chunk-0001: description \"A Neolithic chambered long barrow dating to the first half of the 4th millennium BC, located on the summit of Walker''s Hill near Alton Barnes, Wiltshire. The mound is 70 m long and 7 m high, classified as a Severn-Cotswold type tomb. Excavation by Thurnham in 1860 revealed a sarsen stone chamber containing human skeletal remains and a leaf-shaped arrowhead. Known in Anglo-Saxon times as Woden''s Barrow, the site is linked to battles recorded in the Anglo-Saxon Chronicle in 592 and 715 AD. Scheduled as an ancient monument.\" -> ''Adam\\''s Grave was a Neolithic long barrow near Alton Barnes in Wiltshire, southwest England [1]. The barrow is considered to be of the Severn-Cotswold tomb type [1]. These generally consist of long, precisely built trapezoidal earth mounds covering burial chambers, thus they are a type of chambered long barrow [1]. The chamber, made of sarsen stones, contained partial human skeletons [1]. An arrowhead was also recovered [1]. There is a breast-shaped hill on the spot, with the remains of the barrow being 70 metres long and around 7 metres high with ditches on either side [1]. It was partially excavated by John Thurnam in 1860 [1]. In the Anglo-Saxon period, the site was known as \"Woden\\''s Barrow\" and the Anglo-Saxon Chronicle records two battles, in 592 and 715, thought to have taken place at the site [1].''"}, {"source": "remediation_change_log:112247", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:112248", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:166655", "url": "remediation_change_log", "quote": "served-image-2026-09-30-034: thumbnail_url ''/data/images/wiki/f8263779/hero.webp'' -> ''https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Figures_silhouetted_on_Adams_Grave_%28geograph_2705661%29.jpg/1280px-Figures_silhouetted_on_Adams_Grave_%28geograph_2705661%29.jpg''"}, {"source": "remediation_change_log:244832", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:244833", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: period_start None -> ''-4000''"}, {"source": "remediation_change_log:335337", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-003: thumbnail_url ''https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Figures_silhouetted_on_Adams_Grave_%28geograph_2705661%29.jpg/1280px-Figures_silhouetted_on_Adams_Grave_%28geograph_2705661%29.jpg'' -> ''/data/images/wiki/f8263779/hero.webp''"}]'::jsonb),
    ('f8263779-fd9f-4983-9561-3f7755417987'::uuid, 'rarity_score', '33', '30', 'card-stats-2026-11-05-rollback:f8263779-fd9f-4983-9561-3f7755417987:rarity_score', 'rollback of card-stats-2026-11-05: rarity_score ''30'' restored on Adam''s Grave', '3f3ecaddfb2f6b4c4d5ff14de5be64d2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 33 from mystery 5, cultural_influence 8"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88526", "url": "remediation_change_log", "quote": "phase4:p4-2203:chunk-0001: description \"A Neolithic chambered long barrow dating to the first half of the 4th millennium BC, located on the summit of Walker''s Hill near Alton Barnes, Wiltshire. The mound is 70 m long and 7 m high, classified as a Severn-Cotswold type tomb. Excavation by Thurnham in 1860 revealed a sarsen stone chamber containing human skeletal remains and a leaf-shaped arrowhead. Known in Anglo-Saxon times as Woden''s Barrow, the site is linked to battles recorded in the Anglo-Saxon Chronicle in 592 and 715 AD. Scheduled as an ancient monument.\" -> ''Adam\\''s Grave was a Neolithic long barrow near Alton Barnes in Wiltshire, southwest England [1]. The barrow is considered to be of the Severn-Cotswold tomb type [1]. These generally consist of long, precisely built trapezoidal earth mounds covering burial chambers, thus they are a type of chambered long barrow [1]. The chamber, made of sarsen stones, contained partial human skeletons [1]. An arrowhead was also recovered [1]. There is a breast-shaped hill on the spot, with the remains of the barrow being 70 metres long and around 7 metres high with ditches on either side [1]. It was partially excavated by John Thurnam in 1860 [1]. In the Anglo-Saxon period, the site was known as \"Woden\\''s Barrow\" and the Anglo-Saxon Chronicle records two battles, in 592 and 715, thought to have taken place at the site [1].''"}, {"source": "remediation_change_log:112247", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:112248", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:166655", "url": "remediation_change_log", "quote": "served-image-2026-09-30-034: thumbnail_url ''/data/images/wiki/f8263779/hero.webp'' -> ''https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Figures_silhouetted_on_Adams_Grave_%28geograph_2705661%29.jpg/1280px-Figures_silhouetted_on_Adams_Grave_%28geograph_2705661%29.jpg''"}, {"source": "remediation_change_log:244832", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:244833", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: period_start None -> ''-4000''"}, {"source": "remediation_change_log:335337", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-003: thumbnail_url ''https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Figures_silhouetted_on_Adams_Grave_%28geograph_2705661%29.jpg/1280px-Figures_silhouetted_on_Adams_Grave_%28geograph_2705661%29.jpg'' -> ''/data/images/wiki/f8263779/hero.webp''"}]'::jsonb),
