    ('f82d4a70-4581-4e06-858a-d52019ecbd0f'::uuid, 'mystery', '1', '6', 'card-stats-2026-11-05-rollback:f82d4a70-4581-4e06-858a-d52019ecbd0f:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Zacpeten', '53f2903212c225ee66d228f246be3242', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 1 from (''City/town/settlement'', ''1500 - 500 BC'') is shared by 286 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28677", "url": "remediation_change_log", "quote": "phase3:batch-0178:chunk-0001: period_start ''-1500'' -> ''-1000''"}, {"source": "remediation_change_log:36096", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-1000'' -> ''-1500''"}, {"source": "remediation_change_log:43241", "url": "remediation_change_log", "quote": "phase4:p4-0069:chunk-0001: description ''Zacpeten is a pre-Columbian Maya archaeological site in northern Petén Department, Guatemala, occupied from approximately 1000 BC to AD 950. It is notable as one of the few Maya communities that maintained independence through the early phases of Spanish control over Mesoamerica.'' -> ''Zacpeten is a pre-Columbian Maya archaeological site in the northern Petén Department of Guatemala [1]. The site of Zacpeten occupies a peninsula on Lake Salpeten in the Petén Department of northern Guatemala [1]. The site was sporadically inhabited by the Maya since its initial settlement during the Middle Preclassic (1000 – 300 BC) [1]. After abandonment during Late Preclassic and Early Classic, the site was resettled from the Late to Terminal Classic (AD 600 – 950) [1]. Abandoned again, it was reoccupied in the Late Postclassic by the Maya peoples who survived the Classic Maya collapse and migrated from Mayapan in Yucatán after the collapse of the city in the fifteenth century [1]. These people, the Kowoj Maya, brought their distinctive pottery and constructed typical Mayapan temple assemblages with a raised shrine lying at a right angle to a western facing temple rather than facing it, a very different pattern to ceremonial architecture outside central Peten [1]. This civilisation flourished and remained independent of Spanish domination until late into the 17th century, usually recorded as 1697 [1].''"}, {"source": "remediation_change_log:112249", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:112250", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-1500'' -> None"}, {"source": "remediation_change_log:112251", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: site_type ''City/town/settlement'' -> None"}, {"source": "remediation_change_log:244834", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:244835", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: period_start None -> ''-1000''"}, {"source": "remediation_change_log:244836", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s011: site_type None -> ''Settlement''"}, {"source": "remediation_change_log:356360", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s004: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
