    ('f9cfcc0f-960a-4184-b72d-ab054ed01221'::uuid, 'mystery', '9', '10', 'card-stats-2026-11-05-rollback:f9cfcc0f-960a-4184-b72d-ab054ed01221:mystery', 'rollback of card-stats-2026-11-05: mystery ''10'' restored on Krasnyi Yar, Kazakhstan', 'fcb0f8af1d2a485da06df4f004a7c667', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 9 from (''Village'', ''4500 - 3000 BC'') is shared by 2 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:81488", "url": "remediation_change_log", "quote": "phase4:p4-2034:chunk-0001: description \"Krasnyi Yar is an Eneolithic settlement of the Botai culture (3700-3100 BC) in north-central Kazakhstan, with 54 pit houses. The site provides key evidence for early horse management: corrals identified through geochemical markers for manure and urine, enormous quantities of horse bones with butchering marks, and pottery containing traces of fermented mare''s milk. However, recent genetic studies revealed that Botai horses are ancestral to Przewalski''s horses rather than modern domesticates, complicating the domestication narrative.\" -> ''Krasnyi Yar is an eneolithic site of the Botai culture in Kazakhstan [1]. This large site is significant for the early use of horses there [1]. Horse meat was eaten, but horses were also kept as livestock [1]. The only livestock bones found at the site were from horses, so the inference by the researchers is that horses were held in corrals at the site [1]. Horse-bone tools indicate leather production, suggesting horse tack [1].''"}, {"source": "remediation_change_log:126678", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_name ''< 4500 BC'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:126679", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_start ''-5000'' -> ''-3700''"}, {"source": "remediation_change_log:126680", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: site_type ''City/town/settlement'' -> ''Village''"}]'::jsonb),
