    ('f9e7abcd-b8a2-4844-8145-4a29f19568e2'::uuid, 'antiquity', '5', '8', 'card-stats-2026-11-05-rollback:f9e7abcd-b8a2-4844-8145-4a29f19568e2:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Louisenlund, Bornholm', '78dbbd89eb9c912de402b9e091e11c93', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88558", "url": "remediation_change_log", "quote": "phase4:p4-2204:chunk-0001: description \"Louisenlund is one of Denmark''s largest megalithic sites, featuring approximately 50 standing stones among the trees, many exceeding 2.5 metres in height[1]. Located 3.5 km east of Østermarie on Bornholm, Denmark, these monuments stand on low mounds marking burial places where cremated human remains have been discovered[1]. The uninscribed stones represent a significant ritual landscape on the island, while the similar Gryet site near Bodilsker once had over 60 megaliths, though many have been removed[1].\" -> \"Louisenlund, some 3.5 kilometres east of Østermarie on the Danish island of Bornholm, is a site with one of Denmark''s largest collection of megaliths [1]. The stones stand alone or in small groups [1]. As the site has not been archeologically investigated, it is not known why the stones were raised there [1]. Louisenlund was bought by King Frederik VII when he visited Bornholm in 1851 [1]. He named it after his mistress, Countess Louise Danner [1].\""}, {"source": "remediation_change_log:126681", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_na