    ('fa7e3956-6d81-4cc4-95ce-80e2c06b9f7a'::uuid, 'antiquity', '7', '4', 'card-stats-2026-11-05-rollback:fa7e3956-6d81-4cc4-95ce-80e2c06b9f7a:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Chimei Lithic Workshops', '037e25266e2582eed95549bec6648aba', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2550"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29584", "url": "remediation_change_log", "quote": "phase3:batch-0309:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:88582", "url": "remediation_change_log", "quote": "phase4:p4-2205:chunk-0001: description \"The Chimei Lithic Workshops are Neolithic stone tool production sites scattered across Chimei Island in Penghu County, Taiwan, dating to 3,800-4,500 years ago. Located at Nankang, Tunghu, and Hsihu villages, these workshops processed local basalt into adzes and other tools. Chemical analysis has established a direct link between Penghu basalt adzes and artifacts found on Taiwan''s southwest coast, demonstrating systematic maritime trade of stone tools beginning at least 4,000 years ago. The workshops contain only lithic debris, reflecting their function as specialized stone mining and preparation sites.\" -> ''The Chimei lithic workshops were workshops for making stone tools in the mid-Neolithic period scattered around Chimei Island in Penghu County [1]. These workshops are located at Nankang Village, Tunghu Village, and Hsihu Village in Chimei Township, Penghu County, and they can be dated back to 3,800 to 4,500 years ago [1]. Aside from the large amounts of lithics in the workshops, no other cultural remains or complete lithics have been found, reflecting their functions as sites for stone mining and preparation works for lithic manufacturing [1].''"}, {"source": "remediation_change_log:112292", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:112293", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:255073", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:255074", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-500''"}, {"source": "remediation_change_log:354454", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''500 BC - 1 AD'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:354455", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-500'' -> ''-2550''"}]'::jsonb),
    ('fa7e3956-6d81-4cc4-95ce-80e2c06b9f7a'::uuid, 'total_power', '24', '21', 'card-stats-2026-11-05-rollback:fa7e3956-6d81-4cc4-95ce-80e2c06b9f7a:total_power', 'rollback of card-stats-2026-11-05: total_power ''21'' restored on Chimei Lithic Workshops', '037e25266e2582eed95549bec6648aba', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "total_power = 24 from antiquity + fortification + cultural_influence + mystery + legacy = 7 + 7 + 3 + 6 + 1"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:29584", "url": "remediation_change_log", "quote": "phase3:batch-0309:chunk-0001: site_type ''City/town/settlement'' -> ''Archaeological site''"}, {"source": "remediation_change_log:88582", "url": "remediation_change_log", "quote": "phase4:p4-2205:chunk-0001: description \"The Chimei Lithic Workshops are Neolithic stone tool production sites scattered across Chimei Island in Penghu County, Taiwan, dating to 3,800-4,500 years ago. Located at Nankang, Tunghu, and Hsihu villages, these workshops processed local basalt into adzes and other tools. Chemical analysis has established a direct link between Penghu basalt adzes and artifacts found on Taiwan''s southwest coast, demonstrating systematic maritime trade of stone tools beginning at least 4,000 years ago. The workshops contain only lithic debris, reflecting their function as specialized stone mining and preparation sites.\" -> ''The Chimei lithic workshops were workshops for making stone tools in the mid-Neolithic period scattered around Chimei Island in Penghu County [1]. These workshops are located at Nankang Village, Tunghu Village, and Hsihu Village in Chimei Township, Penghu County, and they can be dated back to 3,800 to 4,500 years ago [1]. Aside from the large amounts of lithics in the workshops, no other cultural remains or complete lithics have been found, reflecting their functions as sites for stone mining and preparation works for lithic manufacturing [1].''"}, {"source": "remediation_change_log:112292", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:112293", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:255073", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:255074", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-500''"}, {"source": "remediation_change_log:354454", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''500 BC - 1 AD'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:354455", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-500'' -> ''-2550''"}]'::jsonb),
