tifacts has been found to the north of Battlegore [1].''"}, {"source": "remediation_change_log:112306", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:112307", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:112308", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: site_type ''Barrow'' -> None"}, {"source": "remediation_change_log:245168", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s012: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:245169", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s012: period_start None -> ''-2000''"}, {"source": "remediation_change_log:245170", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s012: site_type None -> ''Barrow''"}]'::jsonb),
