    ('fc337c87-1194-4407-b440-2b91f93dbdc7'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:fc337c87-1194-4407-b440-2b91f93dbdc7:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Zafarraya', 'a9c0307a0bbf532cf067e7f6b46a5bb2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -48050"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43265", "url": "remediation_change_log", "quote": "phase4:p4-0070:chunk-0001: description \"The Cueva del Boquete de Zafarraya is a cave at 1,100 metres altitude in the Sierra Tejeda mountains of Malaga province, Spain, where a Neanderthal mandible was discovered in 1983 by Cecilio Barroso and Paqui Medina. Securely dated to approximately 33,000 years ago with possible occupation as late as 27,000 years ago, it represents one of the last known Neanderthal populations in Europe. The lithic assemblage is distinctly Mousterian with Levallois technique, and about 90% of faunal remains are Iberian ibex. The site''s late Mousterian persistence supports the Ebro Frontier model, which proposes the Ebro River acted as a barrier allowing isolated Neanderthal survival on the Iberian Peninsula.\" -> ''Zafarraya is known for a Neanderthal mandible found in a cave in 1983 by Cecilio Barroso and Paqui Medina [1]. The mandible has been dated to 30,000 years Before Present (BP), and at the time represented the youngest-known Neanderthal remains [1]. Near the mandible, Mousterian tools dated to 27,000 years BP were found [1]. The find was one of the first pieces of definite evidence showing that the presence of Neanderthals and modern humans overlapped in Europe for a significant period [1].''"}, {"source": "remediation_change_log:126693", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: lat ''36.966820971360114'' -> ''36.950732''"}, {"source": "remediation_change_log:126694", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: lon ''-4.1333333035552275'' -> ''-4.127058''"}, {"source": "remediation_change_log:126695", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:126696", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_start ''-28000'' -> None"}, {"source": "remediation_change_log:167320", "url": "remediation_change_log", "quote": "served-image-2026-09-30-035: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Iglesia_de_la_Inmaculada_Concepción,_en_Zafarraya_(Granada).jpg/400px-Iglesia_de_la_Inmaculada_Concepción,_en_Zafarraya_(Granada).jpg'' -> None"}, {"source": "remediation_change_log:255089", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:255090", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-500''"}, {"source": "remediation_change_log:354469", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:354470", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-500'' -> ''-48050''"}]'::jsonb),
