    ('fce614a8-8697-45d3-9574-4b092231b0bd'::uuid, 'antiquity', '5', '10', 'card-stats-2026-11-05-rollback:fce614a8-8697-45d3-9574-4b092231b0bd:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''10'' restored on El Mirón Cave', '897c6cc08e22ac8e2a3cd7813c5b6c55', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start None"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43267", "url": "remediation_change_log", "quote": "phase4:p4-0070:chunk-0001: description ''El Mirón Cave is a large karst cave in the upper Asón River valley in eastern Cantabria, northern Spain, near the Basque border [1]. The site, located near Ramales de la Victoria, contains one of the most significant Upper Paleolithic burials in Iberia [1]. It is famous for the \"Red Lady of El Mirón,\" a female skeleton dated to approximately 18,700 years ago during the Magdalenian period [1][2]. The skeleton belongs to a woman aged 35-40 years at death, whose bones were coated with red ochre pigment, giving her the nickname [1][2].'' -> ''The El Mirón Cave is a large cave in the upper Asón River valley towards the eastern end of Cantabria in northern Spain [1]. It is an archeological site in Ramales de la Victoria [1]. It is known for a skeleton belonging to a woman nicknamed The Red Lady of El Mirón [1]. She is estimated to have died around 18,700 years ago, during the Upper Paleolithic (Magdalenian) [1]. The cave was discovered in 1903 by amateur archaeologists Hermilio Alcalde del Río and Lorenzo Sierra [1]. It contains a rich collection of Upper Paleolithic art [1]. The first systematic excavation started only in 1996 [1]. The Red Lady was discovered in 2010 [1].''"}, {"source": "remediation_change_log:112343", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''< 4500 BC'' -> None"}, {"source": "remediation_change_log:112344", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-17000'' -> None"}, {"source": "remediation_change_log:167405", "url": "remediation_change_log", "quote": "served-image-2026-09-30-035: thumbnail_url ''/data/images/wiki/fce614a8/hero.webp'' -> ''/data/images/wiki/fce614a8/Cueva de El Mirón 1.webp''"}, {"source": "remediation_change_log:302218", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:302219", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_start None -> ''-300000''"}, {"source": "remediation_change_log:354476", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''< 4500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:354477", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-300000'' -> None"}]'::jsonb),
