    ('fd2f475b-845a-42ec-8183-264673911980'::uuid, 'antiquity', '10', '4', 'card-stats-2026-11-05-rollback:fd2f475b-845a-42ec-8183-264673911980:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''4'' restored on Federsee', '46261c58af704ffb8ab2ec1df43b69f7', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -11000"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28834", "url": "remediation_change_log", "quote": "phase3:batch-0200:chunk-0001: site_type ''Museum'' -> ''Natural feature''"}, {"source": "remediation_change_log:88632", "url": "remediation_change_log", "quote": "phase4:p4-2206:chunk-0001: description ''A lake near Bad Buchau in Upper Swabia, southern Germany, surrounded by one of the largest connected moorlands in the region at 33 sq km. The Federsee basin is renowned for exceptionally well-preserved Neolithic and Bronze Age pile-dwelling settlements, with peat conditions enabling remarkable conservation of organic materials. First excavated in the 1920s, the site was designated a UNESCO World Heritage Site in 2011. Radiocarbon-dated pollen diagrams reveal multiple phases of prehistoric settlement and intensive human land use. The Federsee Museum showcases key finds from the area.'' -> ''Federsee is a lake located just north of Bad Buchau in the region of Upper Swabia in Southern Germany [1]. It is surrounded by moorland, partially overgrown with reeds [1]. With a size of 33 km2, the area is one of the largest, groundwater fed, connected moorlands in Southern Germany [1]. At its deepest point, Lake Federsee has a depth of 2 metres [1]. The basin of Lake Federsee is famous for its excavations of Stone Age and Bronze Age artifacts [1].''"}, {"source": "remediation_change_log:112347", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:112348", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:167432", "url": "remediation_change_log", "quote": "served-image-2026-09-30-035: thumbnail_url ''/data/images/wiki/fd2f475b/hero.webp'' -> ''/data/images/wiki/fd2f475b/Abendstimmung am Federsee.webp''"}, {"source": "remediation_change_log:255095", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:255096", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-500''"}, {"source": "remediation_change_log:354478", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:354479", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-500'' -> ''-11000''"}]'::jsonb),
