    ('fd42ae8f-5d57-4764-9d0e-5020eaf3eb13'::uuid, 'mystery', '6', '7', 'card-stats-2026-11-05-rollback:fd42ae8f-5d57-4764-9d0e-5020eaf3eb13:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on Barry Troglodyte Village', '6e5f655b3d78bc8278eb449b97598630', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Cave Structures'', ''4500 - 3000 BC'') is shared by 11 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88652", "url": "remediation_change_log", "quote": "phase4:p4-2207:chunk-0001: description ''The Barry Troglodyte Village is an archaeological site near Bollene in northwestern Vaucluse, France, perched on a forested hill overlooking the Rhone valley. It comprises a group of caves and stone buildings inhabited continuously from the Neolithic period until the early 20th century. Excavations have yielded Paleolithic arrowheads, Neolithic polished-stone axes, and other prehistoric tools. Most surviving structures date from the 17th to 19th centuries, including a 1706 chapel partly built into a cave. The village was abandoned after cliff collapses made it unsafe, and since 2009 access has been restricted to an outdoor marked trail.'' -> ''The Barry Troglodyte Village is an archaeological site near Bollène, northwestern Vaucluse [1]. It is located on a forested hill that overlooks the Rhône valley [1]. A group of caves and stone buildings comprise an ancient village that is historically interesting because it was inhabited continuously from the neolithic until the early 20th century [1]. Most remaining buildings date from the 17th until the 19th century, including a chapel from 1706 that was partly built in a cave [1].''"}, {"source": "remediation_change_log:112351", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:112352", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:255097", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:255098", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-4500''"}]'::jsonb),
