    ('fd9e31aa-e71d-4cf1-81ff-4104b7df8465'::uuid, 'mystery', '6', '4', 'card-stats-2026-11-05-rollback:fd9e31aa-e71d-4cf1-81ff-4104b7df8465:mystery', 'rollback of card-stats-2026-11-05: mystery ''4'' restored on Knap Hill', 'b66cd82f029d8b7460d1ecaeea512696', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 6 from (''Earthwork'', ''4500 - 3000 BC'') is shared by 13 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:28937", "url": "remediation_change_log", "quote": "phase3:batch-0216:chunk-0001: period_start ''-4500'' -> ''-3530''"}, {"source": "remediation_change_log:28938", "url": "remediation_change_log", "quote": "phase3:batch-0216:chunk-0001: site_type ''City/town/settlement'' -> ''Earthwork''"}, {"source": "remediation_change_log:36108", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-3530'' -> ''-4500''"}, {"source": "remediation_change_log:88660", "url": "remediation_change_log", "quote": "phase4:p4-2207:chunk-0001: description ''Knap Hill is a Neolithic causewayed enclosure on the northern rim of the Vale of Pewsey in northern Wiltshire, England, about 1.6 km (1 mi) north of Alton Priors village [1]. Built around 3700 BC, it features ditches interrupted by gaps, a characteristic form of Neolithic earthwork [1]. The purpose of causewayed enclosures remains unknown; they may have functioned as settlements, meeting places, or ritual sites [1]. The site has been scheduled as an ancient monument [1].'' -> ''Knap Hill lies on the northern rim of the Vale of Pewsey, in northern Wiltshire, England, about a mile north of the village of Alton Priors [1]. At the top of the hill is a causewayed enclosure, a form of Neolithic earthwork that was constructed in England from about 3700 BC onwards, characterized by the full or partial enclosure of an area with ditches that are interrupted by gaps [1]. Knap Hill is notable as the first causewayed enclosure to be excavated and identified [1]. Two barrows lay within the Neolithic enclosure, and at least one more outside it [1]. The hilltop also contains the remains of a Romano-British settlement on an adjoining smaller area called the plateau enclosure, along with some evidence of occupation in the 17th century [1].''"}, {"source": "remediation_change_log:112361", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:112362", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:167452", "url": "remediation_change_log", "quote": "served-image-2026-09-30-035: thumbnail_url ''/data/images/wiki/fd9e31aa/hero.webp'' -> ''/data/images/wiki/fd9e31aa/Knap Hill - panoramio.webp''"}, {"source": "remediation_change_log:245191", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s012: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:245192", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s012: period_start None -> ''-3530''"}]'::jsonb),
