    ('fe268a4c-2d51-42f9-a00e-addd8fe217da'::uuid, 'mystery', '8', '7', 'card-stats-2026-11-05-rollback:fe268a4c-2d51-42f9-a00e-addd8fe217da:mystery', 'rollback of card-stats-2026-11-05: mystery ''7'' restored on The Longstone, Mottistone', '48ff910d13412c5a4dee3951c649e3e3', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Standing stone'', ''4500 - 3000 BC'') is shared by 5 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43271", "url": "remediation_change_log", "quote": "phase4:p4-0070:chunk-0001: description ''The Longstone is a megalithic monument near Mottistone on the Isle of Wight, dating to 4500–3000 BC. It is the only megalithic monument on the island. The monument consists of two Greensand Sandstone boulders, the larger standing 3.9 metres (13 ft) tall with the smaller lying at its foot. Located in a fenced enclosure on the edge of a wood off Strawberry Lane, it was designated a scheduled monument in 1981.[1]'' -> ''The Longstone is a megalithic monument near the village of Mottistone, in the civil parish of Brighstone, close to the south west coast of the Isle of Wight [1]. It is the only megalithic monument on the Island [1]. The Longstone consists of two pieces of local greensand sandstone probably from a vein 100 metres away [1]. The larger stands at 3.9 metres and the smaller lies at its foot [1]. The stones are associated with a narrow mound 21 metres long, which runs from them to the west [1]. In September 1956, excavations by C.N. Hawkes appeared to confirm that this was the remains of a long barrow, so that the stones may be the remains of an entrance [1]. Although dating is difficult, pottery excavated in 1956 indicates that the mound (and therefore probably the stones also) are Neolithic [1].''"}, {"source": "remediation_change_log:126712", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:126713", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:126714", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: site_type ''Megalithic stones'' -> ''Standing stone''"}, {"source": "remediation_change_log:167466", "url": "remediation_change_log", "quote": "served-image-2026-09-30-035: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/e/ec/The_Longstone%2C_Mottistone%2C_IW%2C_UK.jpg'' -> ''/data/images/wiki/fe268a4c/The longstone, Mottistone, Isle of Wight, England (2).webp''"}, {"source": "remediation_change_log:255101", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:255102", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s022: period_start None -> ''-4000''"}, {"source": "remediation_change_log:327195", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-004: thumbnail_url ''/data/images/wiki/fe268a4c/The longstone, Mottistone, Isle of Wight, England (2).webp'' -> ''/data/images/wiki/fe268a4c/The Longstone, Mottistone, IW, UK.webp''"}]'::jsonb),
