    ('fee01523-1686-437c-97ef-9e3566fba1c3'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:fee01523-1686-437c-97ef-9e3566fba1c3:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Foel Chwern', '10010adf3fafacacfb245b58a6d1eabb', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2300"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43275", "url": "remediation_change_log", "quote": "phase4:p4-0070:chunk-0001: description ''Foel Chwern is a Bronze Age round cairn on the high plateau east of the Neath valley, near the summit of Craig y Llyn in Wales [1]. This burial monument sits on a steep scarp slope with commanding views to the north [1]. The headwaters of the River Rhondda lie to the southwest [1]. The site is surrounded by conifer plantations of Rheola Forest, and the Coed Morgannwg Way long-distance footpath passes nearby [1].'' -> ''Foel Chwern is a Round cairn on the edge of the high plateau east of the Neath valley, and near the summit of Craig y Llyn [1]. The headwaters of the River Rhondda are to the south-west [1]. It is a burial monument dating to the Bronze Age, and is sited on the edge of a steep scarp slope, with a wide field of view to the north [1]. The cairn is a mound roughly 8 metres across and 0.4 metres high, made up of small stones [1]. The visible ones appear to be slabs of the locally occurring sandstone, although much of the mound is grass covered, so most stones are obscured and the edge is very indistinct [1]. In 1977 the mound was reported to have received some damage during 20th century forestry activity, and received a partial excavation around this time, which confirmed its size, but revealed neither any burials nor any other finds [1]. The cairn is a Scheduled Monument [1].''"}, {"source": "remediation_change_log:112386", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:112387", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:255261", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s023: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:255262", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s023: period_start None -> ''-4000''"}, {"source": "remediation_change_log:344084", "url": "remediation_change_log", "quote": "insert-2026-10-07-010-001: thumbnail_url None -> ''/data/images/wiki/fee01523/Y Foel Chwern - geograph.org.uk - 6494728.webp''"}, {"source": "remediation_change_log:354499", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:354500", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-4000'' -> ''-2300''"}]'::jsonb),
