ix Romuliana and Naissus [1].\""}, {"source": "remediation_change_log:83142", "url": "remediation_change_log", "quote": "2026-09-26c_fields-wd1-s001: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:83143", "url": "remediation_change_log", "quote": "2026-09-26c_fields-wd1-s001: period_start ''-500'' -> None"}, {"source": "remediation_change_log:83144", "url": "remediation_change_log", "quote": "2026-09-26c_fields-wd1-s001: site_type ''Road/avenue/trackway'' -> None"}, {"source": "remediation_change_log:167482", "url": "remediation_change_log", "quote": "served-image-2026-09-30-035: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/9/92/Singidunum_ostaci1.jpg'' -> ''/data/images/wiki/fee2da6d/Singidunum_ostaci1.webp''"}, {"source": "remediation_change_log:255263", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s023: period_name None -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:255264", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s023: period_start None -> ''-500''"}, {"source": "remediation_change_log:354501", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''500 BC - 1 AD'' -> ''Undated''"}, {"source": "remediation_change_log:354502", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-500'' -> None"}]'::jsonb),
