    ('ffb9aa8c-0ecc-4510-b18d-8555e319c427'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:ffb9aa8c-0ecc-4510-b18d-8555e319c427:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Leskernick Hill', 'ea973cab218d209f9a0aca012dca3afe', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:88720", "url": "remediation_change_log", "quote": "phase4:p4-2209:chunk-0001: description ''Leskernick Hill is a Neolithic to Bronze Age archaeological site on Bodmin Moor in Cornwall, England, rising to 329 metres (1,079 ft) above sea level [1]. The hill falls within the Cornwall Area of Outstanding Natural Beauty and contains two Bronze Age settlements on its south and western slopes, featuring field enclosures, small cairns, a cist and a propped stone [2]. The settlements occupy extremely stony southwest-facing slopes and represent a significant prehistoric occupation site in southwest England [2]. The site has grid reference SX183803 and lies within sight of Rough Tor and its parent hill Brown Willy [1].'' -> ''Leskernick Hill is on Bodmin Moor in Cornwall [1]. It is 329m high and has grid reference SX183803 [1]. On the south and western slopes of Leskernick Hill are 2 Bronze Age settlements, with associated field enclosures, small cairns, a cist and a propped stone [1]. Between 1995 and 1999, Barbara Bender, Sue Hamilton and Christopher Tilley directed a changing group of UCL students in the landscape investigation of the late Neolithic and Bronze Age archaeological sites on, and near, Leskernick Hill, with associated archaeological excavations [1].''"}, {"source": "remediation_change_log:126741", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:126742", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:126743", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: site_type ''Stone circle'' -> ''Settlement''"}, {"source": "remediation_change_log:126744", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: source_url ''https://en.wikipedia.org/wiki/Leskernick_Hill'' -> ''https://www.megalithic.co.uk/article.php?sid=22135''"}, {"source": "remediation_change_log:255273", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s023: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:255274", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s023: period_start None -> ''-4500''"}, {"source": "remediation_change_log:354509", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:354510", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-4500'' -> ''-2500''"}, {"source": "remediation_change_log:356366", "url": "remediation_change_log", "quote": "2026-10-24_mechanical-site-type-merge-s004: site_type ''Settlement'' -> ''City/town/settlement''"}]'::jsonb),
