    ('ffdc79c0-d3da-413f-9d4d-114a0719585c'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-05-rollback:ffdc79c0-d3da-413f-9d4d-114a0719585c:mystery', 'rollback of card-stats-2026-11-05: mystery ''6'' restored on Ancient Theatre of Epidaurus', 'de031377e3a0cdf95aea5262b19924e1', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Theatre'', ''500 BC - 1 AD'') is shared by 28 curated site(s)"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:45529", "url": "remediation_change_log", "quote": "phase4:p4-0115:chunk-0001: description ''Designed by Polykleitos the Younger around 340-300 BC, this theatre at the Sanctuary of Asclepius seats 13,000-14,000 spectators and is considered the most acoustically perfect ancient Greek theatre. Its limestone seats naturally filter crowd noise while amplifying stage sounds. Inscribed as a UNESCO World Heritage Site in 1988, it remains in use for performances today.'' -> ''The Ancient Theatre of Epidaurus is a theatre in the Greek city of Epidaurus, located on the southeast end of the sanctuary dedicated to the ancient Greek God of medicine, Asclepius [1]. It is built on the west side of Cynortion Mountain, near modern Lygourio [1]. According to Pausanias, the ancient theatre was constructed at the end of the 4th century BC, circa 340-300 BCE, by the architect Polykleitos the Younger [1]. At a maximum capacity of 13,000 to 14,000 spectators, the theatre hosted music, singing and dramatic games that were included in the worship of Asclepius [1]. The monument retains the characteristic tripartite structure of a Hellenistic theatre that has a theatron, orchestra, and skene [1].''"}, {"source": "remediation_change_log:167539", "url": "remediation_change_log", "quote": "served-image-2026-09-30-035: thumbnail_url ''/data/images/wiki/ffdc79c0/hero.webp'' -> ''/data/images/wiki/ffdc79c0/+ 14 000 Personen haben im Theater von Epidauros Platz. 10.webp''"}, {"source": "remediation_change_log:320117", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-016: thumbnail_url ''/data/images/wiki/ffdc79c0/+ 14 000 Personen haben im Theater von Epidauros Platz. 10.webp'' -> ''/data/images/wiki/ffdc79c0/The_great_theater_of_Epidaurus,_designed_by_Polykleitos_the_Younger_in_the_4th_century_BC,_Sanctuary_of_Asklepeios_at_Epidaurus,_Greece_(14015010416).webp''"}]'::jsonb),
