    ('fffb6208-b675-47ff-8a0b-4d11f455b0ff'::uuid, 'antiquity', '7', '8', 'card-stats-2026-11-05-rollback:fffb6208-b675-47ff-8a0b-4d11f455b0ff:antiquity', 'rollback of card-stats-2026-11-05: antiquity ''8'' restored on Five Marys', '9feeec30baccc39afa948e8d70e989a9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 7 from period_start -2500"}, {"source": "production export 21200f1e3f26a29a (2026-11-05 22:52:16.465314+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 5519 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04f''s own export (2026-10-04 19:19:41.515456+00))"}, {"source": "remediation_change_log:43313", "url": "remediation_change_log", "quote": "phase4:p4-0071:chunk-0001: description \"The Five Marys is a Bronze Age round barrow cemetery on a ridge near Chaldon Herring, Dorset, comprising two bell barrows, a pond barrow, and seven bowl barrows. The name derives from ''Five Meers,'' meaning parish boundary markers, as shown on Taylor''s 1765 Map of Dorset. Excavations before 1866 revealed male burials in seated positions with stag antlers placed on their shoulders; one barrow also contained a female similarly adorned. The site is a scheduled monument overlooking the village to the south and Galton Heath marshes to the north.\" -> ''The Five Marys is a group of Bronze Age round barrows near the village of Chaldon Herring, in Dorset, England [1]. The barrows, on a west–east ridge overlooking Chaldon Herring to the south, are in an almost straight line [1]. In Taylor\\''s Map of Dorset, of 1765, they are shown as \"Five Meers\" (boundary points) [1]. The largest barrow has height 3.3 metres (11 ft) [1]. All but one have been damaged by antiquarian excavation [1]. Two of the barrows were excavated before 1866 by the Duchess of Berry; she was staying in Lulworth Castle [1]. A deep chalk-cut grave was found in each barrow, each containing a male skeleton in a sitting position, with stag antlers overlying each shoulder [1]. One barrow also contained a female skeleton, with similarly placed stag antlers, and the other had a secondary cremation in an urn [1].''"}, {"source": "remediation_change_log:112409", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:112410", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s023: period_start ''-3000'' -> None"}, {"source": "remediation_change_log:255277", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s023: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:255278", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s023: period_start None -> ''-4000''"}, {"source": "remediation_change_log:354511", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_name ''4500 - 3000 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:354512", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s010: period_start ''-4000'' -> ''-2500''"}]'::jsonb),
